syntheticSpectrumFromArrayParameters(
    std::vector<talas::project::ProjectParameterExpression> overrides);

talas::project::ProjectDocument makeVocoderChannelBankDocument()
{
    const auto spectrum = [] {
        return syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "2"},
            textParameter("amplitudes", "1 0.5"),
            textParameter("frequencies", "1000 4000"),
            textParameter("bandwidths", "300 600"),
        });
    };
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "cascade", "talas.oscillator",
        {{"frequency", "37 hz"}, {"amplitude", "0.25"}}));
    document.graph.nodes.push_back(node(
        "carrier", "talas.oscillator",
        {{"frequency", "1000 hz"}, {"amplitude", "1"}}));
    document.graph.nodes.push_back(node(
        "analysis", "talas.oscillator",
        {{"frequency", "1000 hz"}, {"amplitude", "0.75"}}));
    document.graph.nodes.push_back(node("carrierSpectrum", "talas.syntheticSpectrumFromArray", spectrum()));
    document.graph.nodes.push_back(node("analysisSpectrum", "talas.syntheticSpectrumFromArray", spectrum()));
    document.graph.nodes.push_back(node(
        "vocoder", "talas.vocoderChannelBank",
        {{"timeConstant", "5 ms"}, {"first", "1"}, {"count", "2"}}));
    document.graph.connections = {
        connection("cascade", "audioOut", "vocoder", "cascadeInput"),
        connection("carrier", "audioOut", "vocoder", "audioIn"),
        connection("analysis", "audioOut", "vocoder", "sideChain"),
        connection("carrierSpectrum", "spectrumOut", "vocoder", "inputParameters"),
        connection("analysisSpectrum", "spectrumOut", "vocoder", "sideChainParameters"),
        connection("vocoder", "audioOut", "out", "audioIn"),
    };
    return document;
}

void setVocoderEnvelopeTimes(
    talas::project::ProjectDocument& document,
    std::string attackTime,
    std::string releaseTime)
{
    const auto found = std::ranges::find_if(
        document.graph.nodes,
        [](const auto& candidate) {
            return candidate.instanceId == "vocoder";
        });
    require(found != document.graph.nodes.end(),
        "vocoder envelope fixture should contain its target node");
    found->parameters.push_back({"attackTime", std::move(attackTime)});
    found->parameters.push_back({"releaseTime", std::move(releaseTime)});
}

talas::project::ProjectDocument makeFilterBankRealtimeDocument(
    bool element,
    bool connectedBandwidth = false,
    std::size_t count = 2)
{
    std::string amplitudes;
    std::string frequencies;
    std::string bandwidths;
    for (std::size_t band = 0; band < count; ++band)
    {
        if (band != 0)
        {
            amplitudes += ' ';
            frequencies += ' ';
            bandwidths += ' ';
        }
        amplitudes += band == 0 ? "1" : "0";
        frequencies += std::to_string(1000 + band * 100);
        bandwidths += "200";
    }
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "input", "talas.oscillator",
        {{"frequency", "1000 hz"}, {"amplitude", "1"}}));
    document.graph.nodes.push_back(node(
        "spectrum", "talas.syntheticSpectrumFromArray",
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", std::to_string(count)}, {"envelope", "1"},
            textParameter("amplitudes", std::move(amplitudes)),
            textParameter("frequencies", std::move(frequencies)),
            textParameter("bandwidths", std::move(bandwidths)),
        })));
    if (element)
    {
        document.graph.nodes.push_back(node(
            "cascade", "talas.oscillator",
            {{"frequency", "37 hz"}, {"amplitude", "0.25"}}));
        document.graph.nodes.push_back(node(
            "bank", "talas.filterBankElement",
            {{"first", "1"}, {"count", std::to_string(count)},
             {"bandwidth", "0"},
             choiceParameter("bandwidthUnits", "legacyHertz")}));
        document.graph.connections.push_back(connection(
            "cascade", "audioOut", "bank", "cascadeInput"));
    }
    else
    {
        document.graph.nodes.push_back(node(
            "bank", "talas.filterBank",
            {{"nbrFilters", std::to_string(count)}, {"bankSize", "2"},
             {"bandwidth", "0"},
             choiceParameter("bandwidthUnits", "legacyHertz")}));
    }
    if (connectedBandwidth)
    {
        document.graph.nodes.push_back(node(
            "bandwidth", "talas.constant", {{"value", "250"}}));
        document.graph.connections.push_back(connection(
            "bandwidth", "value", "bank", "bandwidth"));
    }
    document.graph.connections.push_back(connection(
        "input", "audioOut", "bank", "audioIn"));
    document.graph.connections.push_back(connection(
        "spectrum", "spectrumOut", "bank", "spectrum"));
    document.graph.connections.push_back(connection(
        "bank", "audioOut", "out", "audioIn"));
    return document;
}

