talas::project::ProjectDocument makeNestedDynamicControlUtilitiesDocument()
{
    talas::project::ProjectSoundDefinition definition;
    definition.definitionId = "c44DynamicControlCell";
    definition.displayName = "C44 Dynamic Control Cell";
    definition.graph.nodes = {
        node("vca", "talas.vca"),
        node("oscillator", "talas.oscillator", {
            {"frequency", "1 hz"}, {"amplitude", "0.5"},
        }),
        node("index", "talas.constant", {{"value", "1"}}),
        node("quantizer", "talas.quantizer", {
            {"stepSize", "!C44Step"}, {"offset", "!C44Offset"},
        }),
        node("gate", "talas.gate", {
            {"lowThreshold", "!C44Low"},
            {"highThreshold", "!C44High"},
        }),
        node("logic", "talas.logic", {
            choiceParameter("operation", "xor"),
            {"left", "0"}, {"right", "!C44Right"},
        }),
    };
    definition.graph.connections = {
        connection("index", "value", "quantizer", "value"),
        connection("quantizer", "value", "gate", "value"),
        connection("gate", "gate", "logic", "left"),
        connection("logic", "gate", "vca", "gain"),
        connection("oscillator", "audioOut", "vca", "audioIn"),
    };
    definition.outputs = {{
        "audioOut", talas::core::PortType::Audio, "vca", "audioOut",
    }};

    talas::project::ProjectNode first;
    first.instanceId = "firstCell";
    first.soundDefinitionId = definition.definitionId;
    talas::project::ProjectNode second;
    second.instanceId = "secondCell";
    second.soundDefinitionId = definition.definitionId;

    talas::project::ProjectDocument document;
    document.soundDefinitions.push_back(std::move(definition));
    document.graph.nodes = {
        std::move(first),
        std::move(second),
        node("mix", "talas.mixer"),
        node("out", "talas.audioOutput"),
    };
    document.graph.connections = {
        connection("firstCell", "audioOut", "mix", "in1"),
        connection("secondCell", "audioOut", "mix", "in2"),
        connection("mix", "audioOut", "out", "audioIn"),
    };
    return document;
}

