talas::project::ProjectNode mixingControlTable(
    std::string nodeId,
    std::string resourceId = "Tables/MixControl")
{
    return node(
        std::move(nodeId),
        "talas.triggeredTableRead",
        {
            {"trigger", "1"},
            resourceParameter("wavetable", std::move(resourceId)),
            {"gate", "1"},
            booleanParameter("ignoreLoops", true),
            booleanParameter("fromMemoryWriter", false),
        });
}

