talas::project::ProjectDocument makeNestedRealtimeDynamicRangeControllerDocument()
{
    talas::project::ProjectSoundDefinition definition;
    definition.definitionId = "c21DrcCell";
    definition.displayName = "C21 DRC Cell";
    definition.graph =
        makeRealtimeDynamicRangeControllerDocument().graph;
    definition.graph.nodes.erase(
        std::remove_if(
            definition.graph.nodes.begin(),
            definition.graph.nodes.end(),
            [](const talas::project::ProjectNode& candidate) {
                return candidate.instanceId == "out";
            }),
        definition.graph.nodes.end());
    definition.graph.connections.erase(
        std::remove_if(
            definition.graph.connections.begin(),
            definition.graph.connections.end(),
            [](const talas::core::Connection& candidate) {
                return candidate.toNode == "out";
            }),
        definition.graph.connections.end());
    definition.outputs = {{
        "audioOut",
        talas::core::PortType::Audio,
        "drc",
        "audioOut",
    }};

    talas::project::ProjectNode first;
    first.instanceId = "firstCell";
    first.soundDefinitionId = definition.definitionId;
    talas::project::ProjectNode second;
    second.instanceId = "secondCell";
    second.soundDefinitionId = definition.definitionId;

    talas::project::ProjectDocument document;
    document.soundDefinitions.push_back(std::move(definition));
    document.graph.nodes = {
        std::move(first),
        std::move(second),
        node("mix", "talas.mixer"),
        node("out", "talas.audioOutput"),
    };
    document.graph.connections = {
        connection("firstCell", "audioOut", "mix", "in1"),
        connection("secondCell", "audioOut", "mix", "in2"),
        connection("mix", "audioOut", "out", "audioIn"),
    };
    return document;
}

