talas::project::ProjectDocument makeRealtimeCrossfadeDocument(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    bool connectFade = false)
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "crossfade", "talas.crossfade", std::move(parameters)));
    document.graph.nodes.push_back(node("input1", "talas.audioInput", {
        booleanParameter("channel1", true),
        booleanParameter("channel2", false),
    }));
    document.graph.nodes.push_back(node("input2", "talas.audioInput", {
        booleanParameter("channel1", false),
        booleanParameter("channel2", true),
    }));
    document.graph.connections.push_back(connection(
        "input1", "audioOut", "crossfade", "snd1"));
    document.graph.connections.push_back(connection(
        "input2", "audioOut", "crossfade", "snd2"));
    document.graph.connections.push_back(connection(
        "crossfade", "leftOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "crossfade", "rightOut", "out", "rightIn"));
    if (connectFade)
    {
        document.graph.nodes.push_back(mixingControlTable("control"));
        document.graph.connections.push_back(connection(
            "control", "value", "crossfade", "fade"));
    }
    return document;
}

