talas::project::ProjectDocument makeRealtimeStereoMix4Document(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    bool connectPan3 = false)
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "mix", "talas.stereoMix4", std::move(parameters)));
    for (std::size_t channel = 0; channel < 4; ++channel)
    {
        std::vector<talas::project::ProjectParameterExpression> selectors;
        for (std::size_t selected = 0; selected < 8; ++selected)
        {
            selectors.push_back(booleanParameter(
                "channel" + std::to_string(selected + 1),
                selected == channel));
        }
        const auto inputId = "input" + std::to_string(channel + 1);
        document.graph.nodes.push_back(node(
            inputId, "talas.audioInput", std::move(selectors)));
        document.graph.connections.push_back(connection(
            inputId,
            "audioOut",
            "mix",
            "in" + std::to_string(channel + 1)));
    }
    document.graph.connections.push_back(connection(
        "mix", "leftOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "mix", "rightOut", "out", "rightIn"));
    if (connectPan3)
    {
        document.graph.nodes.push_back(mixingControlTable("control"));
        document.graph.connections.push_back(connection(
            "control", "value", "mix", "pan3"));
    }
    return document;
}

