talas::project::ProjectDocument makePreparedMidiVoiceDocument(
    std::size_t polyphony = 2,
    std::uint8_t channel = 1,
    std::uint8_t lowPitch = 0,
    std::uint8_t highPitch = 127,
    std::string amplitudeExpression = "!KeyDown * !KeyVelocity")
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("midi", "talas.midiVoice", {
        {"left", "1"},
        {"right", "1"},
        {"channel", std::to_string(channel)},
        textParameter("source", ""),
        resourceParameter("midiFile", ""),
        {"polyphony", std::to_string(polyphony)},
        {"lowPitch", std::to_string(lowPitch) + " nn"},
        {"highPitch", std::to_string(highPitch) + " nn"},
        textParameter("script", ""),
        booleanParameter("shared", false),
    }));
    document.graph.nodes.push_back(node("osc", "talas.oscillator", {
        {"frequency", "!Pitch"},
        {"amplitude", std::move(amplitudeExpression)},
    }));
    document.graph.connections.push_back(connection("osc", "audioOut", "midi", "audioIn"));
    document.graph.connections.push_back(connection("midi", "leftOut", "out", "audioIn"));
    document.graph.connections.push_back(connection("midi", "rightOut", "out", "rightIn"));
    return document;
}

talas::project::ProjectDocument makePreparedMidiMapperDocument(
    std::string mode,
    std::size_t polyphony = 4,
    std::uint8_t channel = 0,
    std::uint8_t lowPitch = 0,
    std::uint8_t highPitch = 127)
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("midi", "talas.midiMapper", {
        textParameter("map", std::move(mode)),
        choiceParameter("voiceModel", "legacyPassthrough"),
        {"left", "1"},
        {"right", "1"},
        {"channel", std::to_string(channel)},
        textParameter("source", ""),
        resourceParameter("midiFile", ""),
        {"polyphony", std::to_string(polyphony)},
        {"lowPitch", std::to_string(lowPitch) + " nn"},
        {"highPitch", std::to_string(highPitch) + " nn"},
        textParameter("script", ""),
        booleanParameter("shared", false),
    }));
    document.graph.nodes.push_back(node("osc", "talas.oscillator", {
        {"frequency", "100 hz"},
        {"amplitude", "1"},
    }));
    document.graph.connections.push_back(connection(
        "osc", "audioOut", "midi", "audioIn"));
    document.graph.connections.push_back(connection(
        "midi", "leftOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "midi", "rightOut", "out", "rightIn"));
    return document;
}

talas::project::ProjectDocument makeMultiplePreparedMidiVoiceDocument()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("mix", "talas.mixer"));
    for (int region = 0; region < 2; ++region)
    {
        const auto suffix = std::to_string(region + 1);
        document.graph.nodes.push_back(node(
            "midi" + suffix,
            "talas.midiVoice",
            {
                {"left", "1"},
                {"right", "1"},
                {"channel", suffix},
                textParameter("source", ""),
                resourceParameter("midiFile", ""),
                {"polyphony", "1"},
                {"lowPitch", "0 nn"},
                {"highPitch", "127 nn"},
                textParameter("script", ""),
                booleanParameter("shared", false),
            }));
        document.graph.nodes.push_back(node(
            "osc" + suffix,
            "talas.oscillator",
            {
                {"frequency", region == 0 ? "100 hz" : "200 hz"},
                {"amplitude", "!KeyDown"},
            }));
        document.graph.connections.push_back(connection(
            "osc" + suffix,
            "audioOut",
            "midi" + suffix,
            "audioIn"));
        document.graph.connections.push_back(connection(
            "midi" + suffix,
            "leftOut",
            "mix",
            region == 0 ? "in1" : "in2"));
    }
    document.graph.connections.push_back(connection(
        "mix",
        "audioOut",
        "out",
        "audioIn"));
    return document;
}

talas::runtime::RenderSettings preparedMidiVoiceSettings(std::size_t queueCapacity = 16)
{
    talas::runtime::RenderSettings settings{1000.0, 16};
    settings.maxRealtimeEventTransactions = queueCapacity;
    settings.eventValues = {
        {"Pitch", 60.0, talas::expr::ValueDomain::NoteNumber},
        {"KeyVelocity", 0.0, talas::expr::ValueDomain::Scalar},
        {"KeyDown", 0.0, talas::expr::ValueDomain::Scalar},
    };
    return settings;
}

