talas::project::ProjectDocument makePreparedMidiVoiceWithLiveFilterQDocument(
    std::string qExpression = "1 - !KeyVelocity")
{
    auto document = makePreparedMidiVoiceDocument(1);
    // A live Q that leaves its range saturates (owner, 2026-10-12), so the
    // fixture's Q goes not finite, (q / q) * q, where q reaches zero.
    document.graph.nodes.push_back(node("filter", "talas.filter", {
        {"frequency", "100 hz"},
        {"q", "((" + qExpression + ") / (" + qExpression + ")) * (" + qExpression + ")"},
    }));
    document.graph.connections.clear();
    document.graph.connections.push_back(connection("osc", "audioOut", "filter", "audioIn"));
    document.graph.connections.push_back(connection("filter", "audioOut", "midi", "audioIn"));
    document.graph.connections.push_back(connection("midi", "leftOut", "out", "audioIn"));
    document.graph.connections.push_back(connection("midi", "rightOut", "out", "rightIn"));
    return document;
}

talas::project::ProjectDocument makeMixedRejectedVoiceAndMapperDocument()
{
    auto document = makePreparedMidiVoiceWithLiveFilterQDocument(
        "1 + !KeyDown");
    document.graph.nodes.push_back(node("mapper", "talas.midiMapper", {
        textParameter("map", "gate"),
        choiceParameter("voiceModel", "legacyPassthrough"),
        {"left", "1"},
        {"right", "1"},
        {"channel", "0"},
        textParameter("source", ""),
        resourceParameter("midiFile", ""),
        {"polyphony", "4"},
        {"lowPitch", "0 nn"},
        {"highPitch", "127 nn"},
        textParameter("script", ""),
        booleanParameter("shared", false),
    }));
    document.graph.nodes.push_back(node("mapperOsc", "talas.oscillator", {
        {"frequency", "100 hz"},
        {"amplitude", "1"},
    }));
    document.graph.nodes.push_back(node("mix", "talas.mixer"));
    document.graph.connections.erase(
        std::remove_if(
            document.graph.connections.begin(),
            document.graph.connections.end(),
            [](const auto& candidate) {
                return candidate.toNode == "out";
            }),
        document.graph.connections.end());
    document.graph.connections.push_back(connection(
        "mapperOsc", "audioOut", "mapper", "audioIn"));
    document.graph.connections.push_back(connection(
        "midi", "leftOut", "mix", "in1"));
    document.graph.connections.push_back(connection(
        "mapper", "leftOut", "mix", "in2"));
    document.graph.connections.push_back(connection(
        "mix", "audioOut", "out", "audioIn"));
    return document;
}

