talas::project::ProjectDocument makeConcurrentEventValueSnapshotDocument(std::size_t oscillatorCount)
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    std::string mixedNode;
    for (std::size_t index = 0; index < oscillatorCount; ++index)
    {
        const auto oscillatorId = "osc" + std::to_string(index);
        document.graph.nodes.push_back(node(oscillatorId, "talas.oscillator", {
            {"frequency", "1 hz"}, {"amplitude", "!Gain"},
        }));
        if (mixedNode.empty())
        {
            mixedNode = oscillatorId;
            continue;
        }

        const auto mixerId = "mixer" + std::to_string(index);
        document.graph.nodes.push_back(node(mixerId, "talas.mixer", {{"gain1", "1"}, {"gain2", "1"}}));
        document.graph.connections.push_back(connection(mixedNode, "audioOut", mixerId, "in1"));
        document.graph.connections.push_back(connection(oscillatorId, "audioOut", mixerId, "in2"));
        mixedNode = mixerId;
    }
    document.graph.connections.push_back(connection(mixedNode, "audioOut", "out", "audioIn"));
    return document;
}

