std::vector<std::string> stereoInOutputPairPorts(std::string_view typeId)
{
    if (typeId == "talas.stereoInOutput4")
        return {"out12", "out34"};
    if (typeId == "talas.stereoInOutput8")
        return {"out12", "out34", "out56", "out78"};
    return {};
}

talas::project::ProjectDocument makeStereoInOutputRealtimeDocument(
    std::string typeId)
{
    const auto pairPorts = stereoInOutputPairPorts(typeId);
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", std::move(typeId)));
    for (std::size_t pairIndex = 0; pairIndex < pairPorts.size(); ++pairIndex)
    {
        const auto sourceId = "source" + std::to_string(pairIndex + 1);
        const auto amplitude = pairIndex % 2 == 0
            ? 0.5 * static_cast<double>(pairIndex + 1)
            : -0.5 * static_cast<double>(pairIndex + 1);
        document.graph.nodes.push_back(node(
            sourceId,
            "talas.oscillator",
            {
                {"frequency", std::to_string(pairIndex + 1) + " hz"},
                {"amplitude", std::to_string(amplitude)},
            }));
        document.graph.connections.push_back(connection(
            sourceId, "audioOut", "out", pairPorts[pairIndex]));
    }
    return document;
}

talas::project::ProjectDocument makeStereoInOutputRollbackDocument()
{
    auto document = makeStereoInOutputRealtimeDocument(
        "talas.stereoInOutput8");
    const auto source3 = std::ranges::find(
        document.graph.nodes,
        std::string_view{"source3"},
        &talas::project::ProjectNode::instanceId);
    require(
        source3 != document.graph.nodes.end(),
        "C28 rollback fixture should expose its later scheduled source");
    const auto source3Amplitude = std::ranges::find(
        source3->parameters,
        std::string_view{"amplitude"},
        &talas::project::ProjectParameterExpression::parameterId);
    require(
        source3Amplitude != source3->parameters.end(),
        "C28 rollback fixture should expose its later scheduled amplitude");
    source3Amplitude->expression = "!C28LaterGain";
    document.graph.nodes.push_back(node(
        "transportClock",
        "talas.clock",
        {
            {"frequency", "8 hz"},
            {"dutyCycle", "0.5"},
            booleanParameter("enabled", true),
        }));
    document.graph.nodes.push_back(node(
        "probabilitySource",
        "talas.probabilityChaosGenerator",
        {
            {"frequency", "8 hz"},
            {"probability", "1"},
            {"chaos", "0.75"},
            {"slew", "0 s"},
            {"scale", "0.5"},
            {"seed", "17"},
        }));
    document.graph.nodes.push_back(node(
        "lateLevel",
        "talas.level",
        {
            {"left", "1"},
            {"right", "0"},
            booleanParameter("noGain", false),
        }));
    document.graph.nodes.push_back(node(
        "lateLevelControl",
        "talas.constant",
        {{"value", "!C28LateLevel"}}));
    document.graph.connections.erase(
        std::remove_if(
            document.graph.connections.begin(),
            document.graph.connections.end(),
            [](const talas::core::Connection& edge) {
                return edge.toNode == "out"
                    && ((edge.fromNode == "source1"
                            && edge.toPort == "out12")
                        || (edge.fromNode == "source2"
                            && edge.toPort == "out34")
                        || (edge.fromNode == "source4"
                            && edge.toPort == "out78"));
            }),
        document.graph.connections.end());
    document.graph.connections.push_back(connection(
        "transportClock", "gate", "source1", "amplitude"));
    document.graph.connections.push_back(connection(
        "source1", "audioOut", "out", "out12"));
    document.graph.connections.push_back(connection(
        "probabilitySource", "valueOut", "out", "out34"));
    document.graph.connections.push_back(connection(
        "source4", "audioOut", "lateLevel", "audioIn"));
    document.graph.connections.push_back(connection(
        "lateLevelControl", "value", "lateLevel", "left"));
    document.graph.connections.push_back(connection(
        "lateLevel", "leftOut", "out", "out78"));
    return document;
}

talas::project::ProjectDocument makeNestedStereoInOutputRealtimeDocument()
{
    talas::project::ProjectSoundDefinition definition;
    definition.definitionId = "c28NestedPairSource";
    definition.displayName = "C28 Nested Pair Source";
    definition.graph.nodes = {
        node(
            "osc",
            "talas.oscillator",
            {{"frequency", "1 hz"}, {"amplitude", "0.75"}}),
    };
    definition.outputs = {{
        "audioOut",
        talas::core::PortType::Audio,
        "osc",
        "audioOut",
    }};

    talas::project::ProjectNode first;
    first.instanceId = "firstSource";
    first.soundDefinitionId = definition.definitionId;
    talas::project::ProjectNode second;
    second.instanceId = "secondSource";
    second.soundDefinitionId = definition.definitionId;

    talas::project::ProjectDocument document;
    document.soundDefinitions.push_back(std::move(definition));
    document.graph.nodes = {
        std::move(first),
        std::move(second),
        node("out", "talas.stereoInOutput4"),
    };
    document.graph.connections = {
        connection("firstSource", "audioOut", "out", "out12"),
        connection("secondSource", "audioOut", "out", "out34"),
    };
    return document;
}

