talas::project::ProjectDocument makeSosOscillatorsAuthorityProbeDocument(
    bool useSpectrumOnDisk)
{
    auto document = makeSosOscillatorsDocument();
    document.graph.nodes.push_back(node("selector", "talas.spectrumTrackSelector", hertzSelector({
        {"track", "1"}, booleanParameter("amp", true),
        booleanParameter("freq", true),
    })));
    document.graph.nodes.push_back(node("mix", "talas.mixer"));
    if (useSpectrumOnDisk)
    {
        document.graph.nodes.push_back(node("alternate", "talas.spectrumOnDisk", {
            {"frequency", "1 hz"}, {"level", "1"}, {"rateScale", "1"},
            {"trigger", "0"},
            resourceParameter("fileName", "Analysis/C102Dynamic"),
            {"analysisFrames", "2"}, {"nbrPartials", "1"},
            {"firstPartial", "1"},
        }));
    }
    else
    {
        document.graph.nodes.push_back(node(
            "alternate",
            "talas.syntheticSpectrumFromArray",
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "1"},
                {"envelope", "1"},
                textParameter("amplitudes", "1"),
                textParameter("frequencies", "1"),
                textParameter("bandwidths", "0"),
            })));
        document.graph.nodes.push_back(
            node("alternateEnvelope", "talas.constant", {{"value", "1"}}));
        document.graph.connections.push_back(connection(
            "alternateEnvelope", "value", "alternate", "envelope"));
    }
    document.graph.connections.erase(
        std::remove_if(
            document.graph.connections.begin(),
            document.graph.connections.end(),
            [](const talas::core::Connection& edge) {
                return edge.toNode == "out";
            }),
        document.graph.connections.end());
    document.graph.connections.push_back(connection(
        "alternate", "spectrumOut", "selector", "spectrumIn"));
    document.graph.connections.push_back(connection(
        "sos", "audioOut", "mix", "in1"));
    document.graph.connections.push_back(connection(
        "selector", "leftOut", "mix", "in2"));
    document.graph.connections.push_back(connection(
        "mix", "audioOut", "out", "audioIn"));
    return document;
}

