talas::project::ProjectDocument makeSpectrumLinearToLogTrackSelectorDocument(
    std::size_t track, bool roundTrip,
    std::string frequencies = "440 880")
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("spectrum", "talas.syntheticSpectrumFromArray",
            syntheticSpectrumFromArrayParameters({
                textParameter("frequencies", std::move(frequencies)),
                textParameter("bandwidths", "0 220"),
            })),
        node("log", "talas.spectrumLinearToLog"),
        node("selector", "talas.spectrumTrackSelector", hertzSelector({
            {"track", std::to_string(track)},
            booleanParameter("amp", true),
            booleanParameter("freq", true),
        })),
    };
    document.graph.connections = {
        connection("spectrum", "spectrumOut", "log", "spectrumIn"),
        connection("selector", "leftOut", "out", "audioIn"),
        connection("selector", "rightOut", "out", "rightIn"),
    };
    if (roundTrip)
    {
        document.graph.nodes.push_back(node(
            "linear", "talas.spectrumLogToLinear"));
        document.graph.connections.push_back(connection(
            "log", "spectrumOut", "linear", "spectrumIn"));
        document.graph.connections.push_back(connection(
            "linear", "spectrumOut", "selector", "spectrumIn"));
    }
    else
        document.graph.connections.push_back(connection(
            "log", "spectrumOut", "selector", "spectrumIn"));
    return document;
}

