std::vector<std::uint8_t> boundedMidiFileEchoFixture()
{
    return {
        'M', 'T', 'h', 'd',
        0x00, 0x00, 0x00, 0x06,
        0x00, 0x00,
        0x00, 0x01,
        0x00, 0x60,
        'M', 'T', 'r', 'k',
        0x00, 0x00, 0x00, 0x0c,
        0x00, 0x90, 0x3c, 0x40,
        0x60, 0x80, 0x3c, 0x00,
        0x00, 0xff, 0x2f, 0x00,
    };
}

std::vector<std::uint8_t> midiFileEchoRunningStatusAfterSystemFixture(
    bool metaEvent)
{
    auto bytes = std::vector<std::uint8_t>{
        'M', 'T', 'h', 'd',
        0x00, 0x00, 0x00, 0x06,
        0x00, 0x00,
        0x00, 0x01,
        0x00, 0x60,
        'M', 'T', 'r', 'k',
        0x00, 0x00, 0x00, 0x00,
        0x00, 0x90, 0x3c, 0x40,
    };
    if (metaEvent)
        bytes.insert(bytes.end(), {0x00, 0xff, 0x01, 0x00});
    else
        bytes.insert(bytes.end(), {0x00, 0xf0, 0x00});
    bytes.insert(bytes.end(), {
        0x00, 0x3d, 0x41,
        0x00, 0xff, 0x2f, 0x00,
    });
    const auto trackLength = static_cast<std::uint32_t>(bytes.size() - 22);
    bytes[18] = static_cast<std::uint8_t>(trackLength >> 24U);
    bytes[19] = static_cast<std::uint8_t>(trackLength >> 16U);
    bytes[20] = static_cast<std::uint8_t>(trackLength >> 8U);
    bytes[21] = static_cast<std::uint8_t>(trackLength);
    return bytes;
}

std::vector<std::uint8_t> maximumBoundedMidiFileEchoFixture(
    std::size_t eventCount)
{
    require(
        eventCount > 0
            && eventCount
                <= std::numeric_limits<std::uint32_t>::max(),
        "C42 maximum fixture event count should fit its SMF track");
    std::vector<std::uint8_t> bytes{
        'M', 'T', 'h', 'd',
        0x00, 0x00, 0x00, 0x06,
        0x00, 0x00,
        0x00, 0x01,
        0x00, 0x60,
        'M', 'T', 'r', 'k',
        0x00, 0x00, 0x00, 0x00,
    };
    bytes.reserve(22 + 4 + ((eventCount - 1) * 3) + 4);
    bytes.insert(bytes.end(), {0x00, 0x90, 0x00, 0x01});
    for (std::size_t index = 1; index < eventCount; ++index)
    {
        bytes.push_back(0x00);
        bytes.push_back(static_cast<std::uint8_t>(index % 128));
        bytes.push_back(static_cast<std::uint8_t>((index % 127) + 1));
    }
    bytes.insert(bytes.end(), {0x00, 0xff, 0x2f, 0x00});
    const auto trackLength = static_cast<std::uint32_t>(bytes.size() - 22);
    bytes[18] = static_cast<std::uint8_t>(trackLength >> 24U);
    bytes[19] = static_cast<std::uint8_t>(trackLength >> 16U);
    bytes[20] = static_cast<std::uint8_t>(trackLength >> 8U);
    bytes[21] = static_cast<std::uint8_t>(trackLength);
    return bytes;
}

