talas::project::ProjectDocument makePeakDetectorVcaDocument()
{
    auto document = makeAmplitudeFollowerVcaDocument();
    for (auto& graphNode : document.graph.nodes)
    {
        if (graphNode.instanceId == "follower")
        {
            graphNode.instanceId = "detector";
            graphNode.typeId = "talas.peakDetector";
            graphNode.parameters = {{"attackTime", "0.25 s"}, {"releaseTime", "0.5 s"}, {"scale", "1"}};
        }
    }
    for (auto& graphConnection : document.graph.connections)
    {
        if (graphConnection.fromNode == "follower")
            graphConnection.fromNode = "detector";
        if (graphConnection.toNode == "follower")
            graphConnection.toNode = "detector";
    }
    return document;
}

