talas::project::ProjectDocument makeUnaryControlMathVcaDocument(std::string typeId, std::string value)
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("vca", "talas.vca"));
    document.graph.nodes.push_back(node("carrier", "talas.oscillator", {{"frequency", "0.5 hz"}, {"amplitude", "1"}}));
    document.graph.nodes.push_back(node("source", "talas.constant", {{"value", std::move(value)}}));
    // These ArcTans take the arctangent of one input in radians, as projects
    // before format 48 did.
    const auto isArcTan = typeId == "talas.arcTan";
    document.graph.nodes.push_back(node("math", std::move(typeId),
        isArcTan ? std::vector{choiceParameter("angle", "legacyRadians")}
                 : std::vector<talas::project::ProjectParameterExpression>{}));
    document.graph.connections.push_back(connection("source", "value", "math", "value"));
    document.graph.connections.push_back(connection("carrier", "audioOut", "vca", "audioIn"));
    document.graph.connections.push_back(connection("math", "value", "vca", "gain"));
    document.graph.connections.push_back(connection("vca", "audioOut", "out", "audioIn"));
    return document;
}

talas::project::ProjectDocument makeLinearLogAudioDocument(
    std::string typeId, bool roundTrip = false,
    bool simultaneousControl = false)
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("input", "talas.audioInput"));
    document.graph.nodes.push_back(node("math", std::move(typeId)));
    document.graph.connections.push_back(connection(
        "input", "audioOut", "math", "audioIn"));
    if (roundTrip)
    {
        document.graph.nodes.push_back(node(
            "inverse", "talas.logToLinear"));
        document.graph.connections.push_back(connection(
            "math", "audioOut", "inverse", "audioIn"));
        document.graph.connections.push_back(connection(
            "inverse", "audioOut", "out", "audioIn"));
    }
    else if (simultaneousControl)
    {
        document.graph.nodes.push_back(node(
            "control", "talas.constant",
            {{"value", "2.71828182845904523536"}}));
        document.graph.nodes.push_back(node("vca", "talas.vca"));
        document.graph.connections.push_back(connection(
            "control", "value", "math", "value"));
        document.graph.connections.push_back(connection(
            "math", "audioOut", "vca", "audioIn"));
        document.graph.connections.push_back(connection(
            "math", "value", "vca", "gain"));
        document.graph.connections.push_back(connection(
            "vca", "audioOut", "out", "audioIn"));
    }
    else
        document.graph.connections.push_back(connection(
            "math", "audioOut", "out", "audioIn"));
    return document;
}

