talas::project::ProjectDocument makeEqualityVcaDocument(std::string left, std::string right)
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("vca", "talas.vca"));
    document.graph.nodes.push_back(node("carrier", "talas.oscillator", {{"frequency", "0.5 hz"}, {"amplitude", "1"}}));
    document.graph.nodes.push_back(node("left", "talas.constant", {{"value", std::move(left)}}));
    document.graph.nodes.push_back(node("right", "talas.constant", {{"value", std::move(right)}}));
    document.graph.nodes.push_back(node("equal", "talas.equality"));
    document.graph.connections.push_back(connection("left", "value", "equal", "left"));
    document.graph.connections.push_back(connection("right", "value", "equal", "right"));
    document.graph.connections.push_back(connection("carrier", "audioOut", "vca", "audioIn"));
    document.graph.connections.push_back(connection("equal", "value", "vca", "gain"));
    document.graph.connections.push_back(connection("vca", "audioOut", "out", "audioIn"));
    return document;
}

talas::project::ProjectDocument makeProductVcaDocument(
    std::string left,
    std::string right)
{
    auto document = makeEqualityVcaDocument(
        std::move(left), std::move(right));
    for (auto& graphNode : document.graph.nodes)
    {
        if (graphNode.instanceId == "equal")
        {
            graphNode.instanceId = "product";
            graphNode.typeId = "talas.product";
        }
    }
    for (auto& edge : document.graph.connections)
    {
        if (edge.fromNode == "equal")
            edge.fromNode = "product";
        if (edge.toNode == "equal")
            edge.toNode = "product";
    }
    return document;
}

