talas::project::ProjectDocument makeCloudBankRealtimeDocument(
    std::vector<talas::project::ProjectParameterExpression> parameters
        = cloudBankRealtimeParameters(),
    double trigger = 1.0,
    double pan = 0.5,
    double frequencyMod = 0.0,
    double durationMod = 0.0)
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "trigger", "talas.constant", {{"value", std::to_string(trigger)}}));
    document.graph.nodes.push_back(node(
        "pan", "talas.constant", {{"value", std::to_string(pan)}}));
    document.graph.nodes.push_back(node(
        "freqMod", "talas.constant",
        {{"value", std::to_string(frequencyMod)}}));
    document.graph.nodes.push_back(node(
        "durMod", "talas.constant", {{"value", std::to_string(durationMod)}}));
    document.graph.nodes.push_back(node(
        "spectrum", "talas.syntheticSpectrumFromArray",
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "2"},
            {"envelope", "1.0"},
            textParameter("amplitudes", "1.0 0.5"),
            textParameter("frequencies", "1.0 2.0"),
            textParameter("bandwidths", "0.0 0.0"),
        })));
    document.graph.nodes.push_back(node(
        "cloud", "talas.cloudBank", std::move(parameters)));
    document.graph.connections.push_back(connection(
        "trigger", "value", "cloud", "trigger"));
    document.graph.connections.push_back(connection(
        "pan", "value", "cloud", "pan"));
    document.graph.connections.push_back(connection(
        "freqMod", "value", "cloud", "freqMod"));
    document.graph.connections.push_back(connection(
        "durMod", "value", "cloud", "grainDurMod"));
    document.graph.connections.push_back(connection(
        "spectrum", "spectrumOut", "cloud", "spectrumSource"));
    document.graph.connections.push_back(connection(
        "cloud", "leftOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "cloud", "rightOut", "out", "rightIn"));
    return document;
}

