talas::project::ProjectDocument makeCloudBankElementRealtimeDocument(
    std::vector<talas::project::ProjectParameterExpression> parameters
        = cloudBankElementRealtimeParameters(),
    double trigger = 1.0,
    double pan = 0.5,
    double frequencyMod = 0.0,
    double durationMod = 0.0)
{
    auto document = makeCloudBankRealtimeDocument(
        cloudBankRealtimeParameters(),
        trigger,
        pan,
        frequencyMod,
        durationMod);
    document.graph.nodes.push_back(node(
        "cascade", "talas.oscillator",
        {{"frequency", "1 hz"}, {"amplitude", "0.25"}}));
    const auto cloud = std::ranges::find_if(
        document.graph.nodes, [](const auto& candidate) {
            return candidate.instanceId == "cloud";
        });
    if (cloud != document.graph.nodes.end())
    {
        cloud->typeId = "talas.cloudBankElement";
        cloud->parameters = std::move(parameters);
    }
    document.graph.connections.push_back(connection(
        "cascade", "audioOut", "cloud", "cascadeInput"));
    return document;
}

