// The FreqTracker is in hz here, as in projects before format 47; a later
// project's is a fraction of half the sample rate. These fixtures shift by
// a phase vocoder, as projects before format 83 did.
talas::project::ProjectDocument makeFrequencyScaleDocument(
    std::vector<talas::project::ProjectParameterExpression> parameters)
{
    if (std::ranges::none_of(parameters, [](const auto& parameter) {
            return parameter.parameterId == "scaling";
        }))
        parameters.push_back(choiceParameter("scaling", "legacyVocoder"));
    if (std::ranges::none_of(parameters, [](const auto& parameter) {
            return parameter.parameterId == "trackerUnits";
        }))
        parameters.push_back(choiceParameter("trackerUnits", "legacyHertz"));
    // The formants move with the pitch here, as before format 52.
    if (std::ranges::none_of(parameters, [](const auto& parameter) {
            return parameter.parameterId == "formants";
        }))
        parameters.push_back(choiceParameter("formants", "legacyMove"));
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("scale", "talas.frequencyScale", std::move(parameters)));
    document.graph.nodes.push_back(node("osc", "talas.oscillator", {{"frequency", "1 hz"}, {"amplitude", "1"}}));
    document.graph.nodes.push_back(node("tracker", "talas.constant", {{"value", "440"}}));
    document.graph.connections.push_back(connection("osc", "audioOut", "scale", "audioIn"));
    document.graph.connections.push_back(connection("tracker", "value", "scale", "freqTracker"));
    document.graph.connections.push_back(connection("scale", "audioOut", "out", "audioIn"));
    return document;
}

