// These TimeOffsets start their Input late only with a fixed SilentTime and
// otherwise delay its samples, following a SilentTime fed by a Sound or
// that moves, as projects before format 87 play them (ADR-0023).
talas::project::ProjectDocument makeTimeOffsetDocument()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("offset", "talas.timeOffset",
        {{"offset", "250 ms"}, choiceParameter("offsetMeans", "legacyFixedStartsLate")}));
    document.graph.nodes.push_back(node("osc", "talas.oscillator", {{"frequency", "1 hz"}, {"amplitude", "1"}}));
    document.graph.connections.push_back(connection("osc", "audioOut", "offset", "audioIn"));
    document.graph.connections.push_back(connection("offset", "audioOut", "out", "audioIn"));
    return document;
}

talas::project::ProjectDocument makeConnectedTimeOffsetDocument()
{
    auto document = makeTimeOffsetDocument();
    document.graph.nodes.push_back(node("offsetValue", "talas.constant", {{"value", "!Offset"}}));
    document.graph.connections.push_back(connection("offsetValue", "value", "offset", "offset"));
    return document;
}

talas::project::ProjectDocument makeStaticModeTimeOffsetDocument(
    std::string offsetExpression,
    bool reverse,
    bool retrograde)
{
    auto document = makeTimeOffsetDocument();
    const auto offset = std::ranges::find(
        document.graph.nodes,
        std::string_view{"offset"},
        &talas::project::ProjectNode::instanceId);
    require(offset != document.graph.nodes.end(),
        "C142 static mode fixture should expose Time Offset");
    // Reverse plays the Input backwards in windows of the offset here, as
    // in projects before format 51.
    offset->parameters = {
        {"offset", std::move(offsetExpression)},
        booleanParameter("reverse", reverse),
        booleanParameter("retrograde", retrograde),
        choiceParameter("reverseMeans", "legacyReverseWindows"),
        choiceParameter("offsetMeans", "legacyFixedStartsLate"),
    };
    return document;
}

