talas::project::ProjectDocument makeC118NoiseDocument(
    std::string type)
{
    auto document = makeNoiseDocument();
    const auto noise = std::ranges::find(
        document.graph.nodes, std::string_view{"noise"},
        &talas::project::ProjectNode::instanceId);
    require(noise != document.graph.nodes.end(),
        "C118 fixture should expose Noise");
    noise->parameters.push_back(
        choiceParameter("type", std::move(type)));
    return document;
}

talas::project::ProjectDocument makeDirectEventValueNoiseDocument(bool connectControls = false)
{
    auto document = makeNoiseDocument();
    for (auto& graphNode : document.graph.nodes)
    {
        if (graphNode.instanceId != "noise")
            continue;
        for (auto& parameter : graphNode.parameters)
        {
            if (parameter.parameterId == "frequency")
                parameter.expression = "!NoiseFrequency * 1 hz";
            else if (parameter.parameterId == "centerValue")
                parameter.expression = "!NoiseCenter";
            else if (parameter.parameterId == "scale")
                parameter.expression = "!NoiseScale";
        }
        graphNode.parameters.push_back(choiceParameter("type", "hotPink"));
    }
    if (!connectControls)
        return document;

    document.graph.nodes.push_back(node("frequency", "talas.constant", {{"value", "!NoiseFrequency"}}));
    document.graph.nodes.push_back(node("center", "talas.constant", {{"value", "!NoiseCenter"}}));
    document.graph.nodes.push_back(node("scale", "talas.constant", {{"value", "!NoiseScale"}}));
    document.graph.connections.push_back(connection("frequency", "value", "noise", "frequency"));
    document.graph.connections.push_back(connection("center", "value", "noise", "centerValue"));
    document.graph.connections.push_back(connection("scale", "value", "noise", "scale"));
    return document;
}

talas::project::ProjectDocument makeTransactionalEventValueNoiseDocument()
{
    auto document = makeNoiseDocument();
    for (auto& graphNode : document.graph.nodes)
    {
        if (graphNode.instanceId != "noise")
            continue;
        for (auto& parameter : graphNode.parameters)
        {
            if (parameter.parameterId == "frequency")
                parameter.expression = "!NoiseControl * 1 hz";
            else if (parameter.parameterId == "scale")
                parameter.expression = "!NoiseControl";
        }
        graphNode.parameters.push_back(choiceParameter("type", "hotPink"));
    }
    return document;
}

