void testRealtimeAnalogSequencerRejectsInvalidControlsEvenWithClosedGate()
{
    auto document = makeAnalogSequencerRealtimeDocument();
    document.graph.nodes.push_back(node(
        "invalidLeft", "talas.constant", {{"value", "2"}}));
    document.graph.nodes.push_back(node(
        "closedGate", "talas.constant", {{"value", "0"}}));
    document.graph.connections.push_back(connection(
        "invalidLeft", "value", "sequence", "left"));
    document.graph.connections.push_back(connection(
        "closedGate", "value", "sequence", "gate"));
    auto graph = compile(document, talas::runtime::RenderSettings{4.0, 4});
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string{session.error()});
    std::array<double, 4> left{1.0, 1.0, 1.0, 1.0};
    std::array<double, 4> right{1.0, 1.0, 1.0, 1.0};
    std::size_t allocations = 0;
    require(
        !renderStereoAndCount(session, left, right, allocations),
        "closed Analog Sequencer gate must not hide an invalid connected level");
    require(
        allocations == 0
            && std::ranges::all_of(left, [](double value) {
                   return value == 0.0;
               })
            && std::ranges::all_of(right, [](double value) {
                   return value == 0.0;
               }),
        "failed Analog Sequencer callback should allocate nothing and clear external output");

    auto invalidStepDocument = makeAnalogSequencerRealtimeDocument();
    invalidStepDocument.graph.nodes.push_back(node(
        "invalidStep", "talas.constant", {{"value", "1e300"}}));
    invalidStepDocument.graph.nodes.push_back(node(
        "closedStepGate", "talas.constant", {{"value", "0"}}));
    invalidStepDocument.graph.connections.push_back(connection(
        "invalidStep", "value", "sequence", "step"));
    invalidStepDocument.graph.connections.push_back(connection(
        "closedStepGate", "value", "sequence", "gate"));
    auto invalidStepGraph = compile(
        invalidStepDocument, talas::runtime::RenderSettings{4.0, 4});
    talas::runtime::RealtimeRenderSession invalidStepSession(invalidStepGraph);
    require(
        invalidStepSession.ready(),
        std::string{invalidStepSession.error()});
    left.fill(1.0);
    right.fill(1.0);
    allocations = 0;
    require(
        !renderStereoAndCount(
            invalidStepSession, left, right, allocations)
            && allocations == 0,
        "closed Analog Sequencer gate must reject an unrepresentable connected step without allocation");
}

void testRealtimeAnalogSequencerEnforcesClosedPreparedBoundary()
{
    const auto requireRejected = [](
                                     std::vector<talas::project::ProjectParameterExpression> overrides,
                                     std::string_view label) {
        auto graph = compile(
            makeAnalogSequencerRealtimeDocument(
                analogSequencerParameters(std::move(overrides))),
            talas::runtime::RenderSettings{4.0, 4});
        talas::runtime::RealtimeRenderSession session(graph);
        require(
            !session.ready()
                && session.error().find("Analog Sequencer")
                    != std::string_view::npos,
            std::string{label}
                + " should reject at prepared Analog Sequencer admission");
    };
    requireRejected(
        {textParameter("extraValues", "{1}")},
        "extra-value sequencing");
    requireRejected({{"polyphony", "1 + 1"}}, "computed polyphony above one");
    requireRejected(
        {textParameter("dutyCycles", "")},
        "empty duty-cycle sequence");
    requireRejected(
        {textParameter("durations", "{0 s} {1 s}")},
        "non-positive duration");
    requireRejected(
        {textParameter("dutyCycles", "{1.1} {1}")},
        "out-of-range duty cycle");
    requireRejected(
        {textParameter("velocities", "{0.25} {-1}")},
        "negative velocity");
    requireRejected({{"startIndex", "1e300"}}, "unrepresentable start index");
    requireRejected({{"endIndex", "1e300"}}, "unrepresentable end index");
    requireRejected({{"step", "1e300"}}, "unrepresentable manual step");
    requireRejected(
        {
            textParameter("durations", "{1e308 s} {1e308 s}"),
            textParameter("dutyCycles", "{1} {1}"),
            textParameter("velocities", "{1} {1}"),
        },
        "non-finite selected duration");

    const auto maximumDurations = repeatedAnalogSequencerExpressions(
        256, "0.25 s");
    const auto maximumDutyCycles = repeatedAnalogSequencerExpressions(
        256, "1");
    const auto maximumVelocities = repeatedAnalogSequencerExpressions(
        256, "1");
    auto maximumGraph = compile(
        makeAnalogSequencerRealtimeDocument(analogSequencerParameters({
            {"endIndex", "255"},
            booleanParameter("loop", false),
            textParameter("durations", maximumDurations),
            textParameter("dutyCycles", maximumDutyCycles),
            textParameter("velocities", maximumVelocities),
        })),
        talas::runtime::RenderSettings{4.0, 256});
    talas::runtime::RealtimeRenderSession maximum(maximumGraph);
    require(
        maximum.ready(),
        "maximum 256-step Analog Sequencer should prepare: "
            + std::string{maximum.error()});
    std::array<double, 256> maximumLeft{};
    std::array<double, 256> maximumRight{};
    std::size_t allocations = 0;
    require(
        renderStereoAndCount(
            maximum, maximumLeft, maximumRight, allocations)
            && allocations == 0,
        "maximum 256-step Analog Sequencer callback should remain bounded and allocation-free");

    requireRejected(
        {
            {"endIndex", "256"},
            textParameter(
                "durations",
                repeatedAnalogSequencerExpressions(257, "0.25 s")),
            textParameter(
                "dutyCycles",
                repeatedAnalogSequencerExpressions(257, "1")),
            textParameter(
                "velocities",
                repeatedAnalogSequencerExpressions(257, "1")),
        },
        "257-step over-capacity sequence");
    requireRejected(
        {
            {"endIndex", "4095"},
            textParameter(
                "durations",
                repeatedAnalogSequencerExpressions(4096, "0.25 s")),
            textParameter(
                "dutyCycles",
                repeatedAnalogSequencerExpressions(4096, "1")),
            textParameter(
                "velocities",
                repeatedAnalogSequencerExpressions(4096, "1")),
        },
        "giant over-capacity sequence bounded at the first excess step");
}

void testRealtimeAnalogSequencerRejectsForgedPreparedAuthority()
{
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 8;
    settings.eventValues = {
        {"NestedLeft", 0.5, talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = compile(
        makeAnalogSequencerRealtimeDocument(), settings);
    const auto requireRejected = [&](talas::runtime::RuntimePlan plan,
                                     std::string_view context) {
        for (auto& step : plan.steps)
        {
            if (step.typeId != "talas.oscillator")
                continue;
            step.offlineSupport = talas::core::ExecutionSupport::Subset;
            step.preparedRealtimeSupport =
                talas::core::ExecutionSupport::Subset;
        }
        const talas::runtime::PreparedRuntimeGraph malformed{
            std::move(plan), settings};
        talas::runtime::RealtimeRenderSession session(malformed);
        require(
            !session.ready()
                && std::string(session.error()).find("Analog Sequencer")
                    != std::string::npos,
            std::string(context)
                + " should fail Analog Sequencer realtime preparation: "
                + std::string(session.error()));
    };
    const auto findSequencer = [](talas::runtime::RuntimePlan& plan) {
        return std::ranges::find(
            plan.steps,
            std::string_view{"talas.analogSequencer"},
            &talas::runtime::CompileStep::typeId);
    };

    {
        auto plan = compiled.plan();
        auto sequencer = findSequencer(plan);
        require(sequencer != plan.steps.end() && sequencer->supportsReset,
            "forged reset fixture should expose reset authority");
        sequencer->supportsReset = false;
        requireRejected(std::move(plan), "missing reset authority");
    }

    {
        auto plan = compiled.plan();
        auto sequencer = findSequencer(plan);
        require(sequencer != plan.steps.end(),
            "forged support fixture should expose sequencer step");
        sequencer->preparedRealtimeSupport =
            talas::core::ExecutionSupport::Subset;
        requireRejected(std::move(plan), "sealed support downgrade");
    }

    {
        auto plan = compiled.plan();
        auto sequencer = findSequencer(plan);
        require(sequencer != plan.steps.end()
                    && sequencer->resolvedLatencyFrames == 0,
            "forged latency fixture should expose zero intrinsic latency");
        sequencer->resolvedLatencyFrames = 1;
        requireRejected(std::move(plan), "forged intrinsic latency");
    }

    {
        auto plan = compiled.plan();
        auto sequencer = findSequencer(plan);
        require(sequencer != plan.steps.end()
                    && sequencer->inputs.size()
                        == sequencer->inputLatencyFrames.size(),
            "duplicate input fixture should expose coherent latency authority");
        const auto audioInput = std::ranges::find(
            sequencer->inputs,
            std::string_view{"audioIn"},
            &talas::runtime::InputBinding::inputPortId);
        require(audioInput != sequencer->inputs.end(),
            "duplicate input fixture should expose audioIn");
        const auto inputIndex = static_cast<std::size_t>(
            std::distance(sequencer->inputs.begin(), audioInput));
        sequencer->inputs.push_back(*audioInput);
        sequencer->inputLatencyFrames.push_back(
            sequencer->inputLatencyFrames[inputIndex]);
        requireRejected(std::move(plan), "duplicate audioIn binding");
    }

    {
        auto plan = compiled.plan();
        auto sequencer = findSequencer(plan);
        require(sequencer != plan.steps.end(),
            "forged source fixture should expose sequencer step");
        auto audioInput = std::ranges::find(
            sequencer->inputs,
            std::string_view{"audioIn"},
            &talas::runtime::InputBinding::inputPortId);
        require(audioInput != sequencer->inputs.end()
                    && audioInput->bufferIndex < plan.buffers.size(),
            "forged source fixture should expose a valid audioIn buffer");
        auto forgedBuffer = plan.buffers[audioInput->bufferIndex];
        forgedBuffer.portId = "forgedAudioOut";
        audioInput->sourcePortId = forgedBuffer.portId;
        audioInput->bufferIndex = plan.buffers.size();
        plan.buffers.push_back(std::move(forgedBuffer));
        requireRejected(
            std::move(plan),
            "self-consistent unproduced audioIn source buffer");
    }

    {
        auto plan = compiled.plan();
        auto sequencer = findSequencer(plan);
        require(sequencer != plan.steps.end(),
            "forged parameter-domain fixture should expose sequencer step");
        auto startIndex = std::ranges::find(
            sequencer->parameters,
            std::string_view{"startIndex"},
            &talas::runtime::ParameterValue::id);
        require(startIndex != sequencer->parameters.end()
                    && startIndex->domain
                        == talas::expr::ValueDomain::Scalar,
            "forged parameter-domain fixture should expose scalar startIndex");
        startIndex->domain = talas::expr::ValueDomain::Seconds;
        requireRejected(std::move(plan), "forged startIndex domain");
    }

    {
        auto plan = compiled.plan();
        auto sequencer = findSequencer(plan);
        require(sequencer != plan.steps.end(),
            "forged parameter-shape fixture should expose sequencer step");
        auto loop = std::ranges::find(
            sequencer->parameters,
            std::string_view{"loop"},
            &talas::runtime::ParameterValue::id);
        require(loop != sequencer->parameters.end()
                    && loop->boolean.has_value(),
            "forged parameter-shape fixture should expose boolean loop");
        loop->text = "true";
        requireRejected(std::move(plan), "forged loop parameter shape");
    }

    {
        auto nestedDocument =
            makeNestedAnalogSequencerRealtimeDocument(
                analogSequencerParameters({{"left", "!NestedLeft"}}));
        std::erase_if(
            nestedDocument.graph.nodes,
            [](const talas::project::ProjectNode& candidate) {
                return candidate.instanceId == "closedCell"
                    || candidate.instanceId == "leftMix"
                    || candidate.instanceId == "rightMix";
            });
        nestedDocument.graph.connections = {
            connection(
                "openCell", "leftOut", "out", "audioIn"),
            connection(
                "openCell", "rightOut", "out", "rightIn"),
        };
        const auto nestedCompiled = compile(
            nestedDocument, settings);
        auto plan = nestedCompiled.plan();
        const auto sequencer = std::ranges::find_if(
            plan.steps,
            [](const talas::runtime::CompileStep& step) {
                return step.typeId == "talas.analogSequencer"
                    && step.scopeId != talas::runtime::globalRuntimeScope;
            });
        require(
            sequencer != plan.steps.end()
                && sequencer->eventValueScopeId == sequencer->scopeId,
            "forged nested Event Value fixture should expose exact scope authority");
        sequencer->eventValueScopeId = talas::runtime::globalRuntimeScope;
        requireRejected(
            std::move(plan),
            "forged nested Event Value scope redirect");
    }
}

void testAnalogSequencerRequiresExactCompilerOwnedAuthority()
{
    const auto settings = talas::runtime::RenderSettings{4.0, 8};
    const auto compiled = compile(
        makeAnalogSequencerRealtimeDocument(), settings);
    talas::runtime::RealtimeRenderSession exactRealtime{compiled};
    const auto exactOffline = talas::runtime::renderOffline(compiled, 8);
    require(exactRealtime.ready() && exactOffline.ok(),
        "C162 exact built-in Analog Sequencer authority should render offline and prepare realtime");

    const auto publicGraph =
        makePublicCompatibilityGraphWithSubsetOscillators(compiled);
    talas::runtime::RealtimeRenderSession publicRealtime{publicGraph};
    const auto publicOffline = talas::runtime::renderOffline(publicGraph, 8);
    require(!publicRealtime.ready() && !publicOffline.ok(),
        "C162 Supported Analog Sequencer should require privately compiler-sealed authority");

    const auto requireMutationRejected = [&] (
        auto mutate, std::string_view context) {
        auto mutated = compiled;
        auto& plan = mutablePlanForTest(mutated);
        const auto step = std::ranges::find(
            plan.steps,
            std::string_view{"talas.analogSequencer"},
            &talas::runtime::CompileStep::typeId);
        require(step != plan.steps.end(),
            "C162 authority fixture should expose Analog Sequencer");
        mutate(plan, *step);
        talas::runtime::RealtimeRenderSession realtime{mutated};
        const auto offline = talas::runtime::renderOffline(mutated, 8);
        require(!realtime.ready() && !offline.ok(),
            "C162 Analog Sequencer should reject sealed "
                + std::string{context});
    };
    requireMutationRejected([] (auto&, auto& step) {
        step.parameters.front().value = std::nextafter(
            step.parameters.front().value,
            std::numeric_limits<double>::infinity());
    }, "parameter mutation");
    requireMutationRejected([] (auto&, auto& step) {
        std::ranges::find(step.parameters, "stepZeroMode",
            &talas::runtime::ParameterValue::id)->choice = "legacyAutomatic";
    }, "Step zero compatibility mutation");
    requireMutationRejected([] (auto&, auto& step) {
        step.inputs.front().sourcePortId += "Forged";
    }, "input-binding mutation");
    requireMutationRejected([] (auto& plan, auto& step) {
        const auto output = std::ranges::find_if(
            plan.buffers,
            [&] (const auto& buffer) {
                return buffer.nodeId == step.nodeId
                    && buffer.scopeId == step.scopeId
                    && buffer.portId == "leftOut";
            });
        require(output != plan.buffers.end(),
            "C162 authority fixture should expose left output buffer");
        ++output->frames;
    }, "buffer mutation");
    requireMutationRejected([] (auto&, auto& step) {
        ++step.scopeId;
    }, "scope mutation");
    requireMutationRejected([] (auto&, auto& step) {
        step.resolvedLatencyFrames = 1;
    }, "latency mutation");
    requireMutationRejected([] (auto&, auto& step) {
        step.preparedRealtimeSupport =
            talas::core::ExecutionSupport::Subset;
    }, "support downgrade");

    auto changedSettings = compiled;
    ++mutableSettingsForTest(changedSettings).maxBlockFrames;
    talas::runtime::RealtimeRenderSession settingsRealtime{changedSettings};
    const auto settingsOffline = talas::runtime::renderOffline(
        changedSettings, 8);
    require(!settingsRealtime.ready() && !settingsOffline.ok(),
        "C162 Analog Sequencer should reject sealed settings mutation");

    auto subsetRegistry = talas::core::makeBuiltinNodeRegistry();
    subsetRegistry.setNodeTypeOfflineSupport(
        "talas.analogSequencer", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    subsetRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.analogSequencer", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto subset = talas::runtime::compileProject(
        makeAnalogSequencerRealtimeDocument(), subsetRegistry, settings);
    require(subset.ok(),
        "C162 explicit custom Subset Analog Sequencer should compile");
    talas::runtime::RealtimeRenderSession subsetRealtime{*subset.graph};
    const auto subsetOffline = talas::runtime::renderOffline(
        *subset.graph, 8);
    const auto publicSubset =
        makePublicCompatibilityGraphWithSubsetOscillators(*subset.graph);
    talas::runtime::RealtimeRenderSession publicSubsetRealtime{publicSubset};
    const auto publicSubsetOffline = talas::runtime::renderOffline(
        publicSubset, 8);
    require(subsetRealtime.ready() && subsetOffline.ok()
            && publicSubsetRealtime.ready() && publicSubsetOffline.ok(),
        "C162 coherent both-Subset custom Analog Sequencer should retain bounded compatibility");

    auto mixedRegistry = talas::core::makeBuiltinNodeRegistry();
    mixedRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.analogSequencer", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto mixed = talas::runtime::compileProject(
        makeAnalogSequencerRealtimeDocument(), mixedRegistry, settings);
    require(mixed.ok(),
        "C162 mixed-support Analog Sequencer fixture should compile before admission rejection");
    talas::runtime::RealtimeRenderSession mixedRealtime{*mixed.graph};
    const auto mixedOffline = talas::runtime::renderOffline(*mixed.graph, 8);
    require(!mixedRealtime.ready() && !mixedOffline.ok(),
        "C162 mixed Analog Sequencer support should not mint promoted authority");

    auto divergentRegistry = talas::core::makeBuiltinNodeRegistry();
    divergentRegistry.setNodeTypeFanInLatencyPolicy(
        "talas.analogSequencer",
        talas::core::FanInLatencyPolicy::PreserveRelative);
    const auto divergent = talas::runtime::compileProject(
        makeAnalogSequencerRealtimeDocument(),
        divergentRegistry,
        settings);
    require(divergent.ok(),
        "C162 divergent Analog Sequencer descriptor should compile before admission rejection");
    talas::runtime::RealtimeRenderSession divergentRealtime{
        *divergent.graph};
    const auto divergentOffline = talas::runtime::renderOffline(
        *divergent.graph, 8);
    require(!divergentRealtime.ready() && !divergentOffline.ok(),
        "C162 divergent Supported Analog Sequencer descriptor should not mint built-in authority");
}

void testRealtimeAnalogSequencerPublishesValidatedEventValueControls()
{
    auto document = makeAnalogSequencerRealtimeDocument(
        analogSequencerParameters({
            {"left", "!AnalogLeft"},
            {"right", "!AnalogRight"},
            {"gate", "!AnalogGate"},
            {"step", "!AnalogStep"},
            {"rate", "!AnalogRate"},
        }));
    talas::runtime::RenderSettings settings{4.0, 4};
    settings.eventValues = {
        {"AnalogLeft", 0.5, talas::expr::ValueDomain::Scalar},
        {"AnalogRight", 0.25, talas::expr::ValueDomain::Scalar},
        {"AnalogGate", 1.0, talas::expr::ValueDomain::Scalar},
        {"AnalogStep", 0.0, talas::expr::ValueDomain::Scalar},
        {"AnalogRate", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto graph = compile(document, std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        "Event Value Analog Sequencer should prepare: "
            + std::string{session.error()});
    std::array<double, 4> left{};
    std::array<double, 4> right{};
    std::size_t allocations = 0;
    require(
        renderStereoAndCount(session, left, right, allocations)
            && allocations == 0,
        "initial Event Value Analog Sequencer block should render without allocation");

    require(
        session.updateEventValue(
            "AnalogLeft", 1.0, talas::expr::ValueDomain::Scalar)
            && session.updateEventValue(
                "AnalogRight", -0.5, talas::expr::ValueDomain::Scalar)
            && session.updateEventValue(
                "AnalogStep", 2.0, talas::expr::ValueDomain::Scalar)
            && session.updateEventValue(
                "AnalogRate", 2.0, talas::expr::ValueDomain::Scalar),
        "valid Analog Sequencer Event Values should publish atomically per assignment");
    require(
        renderStereoAndCount(session, left, right, allocations)
            && allocations == 0,
        "updated Event Value Analog Sequencer block should render without allocation");
    const std::array expectedLeft{0.0, 1.0, 0.0, -1.0};
    const std::array expectedRight{0.0, -0.5, 0.0, 0.5};
    for (std::size_t frame = 0; frame < left.size(); ++frame)
    {
        requireNear(
            left[frame], expectedLeft[frame], 1.0e-12,
            "updated Analog Sequencer left frame "
                + std::to_string(frame));
        requireNear(
            right[frame], expectedRight[frame], 1.0e-12,
            "updated Analog Sequencer right frame "
                + std::to_string(frame));
    }

    // A live level past 1 saturates at 1 (owner, 2026-10-12), as offline.
    require(
        session.updateEventValue(
            "AnalogLeft", 2.0, talas::expr::ValueDomain::Scalar),
        "an out-of-range Analog Sequencer Event Value should saturate");
    require(
        renderStereoAndCount(session, left, right, allocations)
            && allocations == 0,
        "a saturated Analog Sequencer Event Value should render");
    for (std::size_t frame = 0; frame < left.size(); ++frame)
    {
        requireNear(
            left[frame], expectedLeft[frame], 1.0e-12,
            "saturated Event Value Analog Sequencer left frame "
                + std::to_string(frame));
        requireNear(
            right[frame], expectedRight[frame], 1.0e-12,
            "saturated Event Value Analog Sequencer right frame "
                + std::to_string(frame));
    }

    require(
        session.updateEventValue(
            "AnalogGate", 0.0, talas::expr::ValueDomain::Scalar),
        "Analog Sequencer gate should close through an Event Value");
    require(
        renderStereoAndCount(session, left, right, allocations)
            && allocations == 0
            && std::ranges::all_of(left, [](double value) {
                   return value == 0.0;
               })
            && std::ranges::all_of(right, [](double value) {
                   return value == 0.0;
               }),
        "closed Event Value gate should silence and reset Analog Sequencer time");
}

void testAnalogSequencerScheduledControlsMatchOfflinePreparedAndPartitions()
{
    const auto initialSettings = [] {
        auto settings = talas::runtime::RenderSettings{8.0, 8};
        settings.maxRealtimeEventTransactions = 12;
        settings.eventValues = {
            {"C162Left", 0.5, talas::expr::ValueDomain::Scalar},
            {"C162Right", 0.25, talas::expr::ValueDomain::Scalar},
            {"C162Gate", 1.0, talas::expr::ValueDomain::Scalar},
            {"C162Step", 0.0, talas::expr::ValueDomain::Scalar},
            {"C162Rate", 1.0, talas::expr::ValueDomain::Scalar},
        };
        return settings;
    };
    auto offlineSettings = initialSettings();
    offlineSettings.eventValueChanges = {
        {1, "C162Left", 1.0, talas::expr::ValueDomain::Scalar},
        {1, "C162Right", -0.5, talas::expr::ValueDomain::Scalar},
        {2, "C162Gate", 0.0, talas::expr::ValueDomain::Scalar},
        {2, "C162Step", 2.0, talas::expr::ValueDomain::Scalar},
        {2, "C162Rate", 2.0, talas::expr::ValueDomain::Scalar},
        {3, "C162Gate", 1.0, talas::expr::ValueDomain::Scalar},
        {4, "C162Step", 0.0, talas::expr::ValueDomain::Scalar},
        {4, "C162Rate", 4.0, talas::expr::ValueDomain::Scalar},
        {5, "C162Left", -0.75, talas::expr::ValueDomain::Scalar},
        {5, "C162Right", 0.75, talas::expr::ValueDomain::Scalar},
    };
    const auto offlineGraph = compile(
        makeC162ScheduledAnalogSequencerDocument(), offlineSettings);
    const auto offline = talas::runtime::renderOffline(offlineGraph, 8);
    require(offline.ok() && offline.mono.size() == 8
            && offline.right.size() == 8,
        "C162 five-control Analog Sequencer offline schedule should render stereo");

    talas::runtime::OfflineRenderSession partitionedOffline{offlineGraph};
    std::vector<double> partitionedLeft;
    std::vector<double> partitionedRight;
    for (const auto frames : {std::size_t{1}, std::size_t{3},
             std::size_t{1}, std::size_t{3}})
    {
        const auto block = partitionedOffline.render(frames);
        require(block.ok(),
            "C162 irregular offline Analog Sequencer partition should render");
        partitionedLeft.insert(
            partitionedLeft.end(), block.mono.begin(), block.mono.end());
        partitionedRight.insert(
            partitionedRight.end(), block.right.begin(), block.right.end());
    }
    require(partitionedLeft == offline.mono
            && partitionedRight == offline.right,
        "C162 offline Analog Sequencer schedule should be stereo partition invariant");

    const auto schedule = [] (talas::runtime::RealtimeRenderSession& session) {
        const std::array levels{
            talas::runtime::RealtimeEventValueUpdate{
                "C162Left", 1.0, talas::expr::ValueDomain::Scalar},
            talas::runtime::RealtimeEventValueUpdate{
                "C162Right", -0.5, talas::expr::ValueDomain::Scalar},
        };
        const std::array closedStepRate{
            talas::runtime::RealtimeEventValueUpdate{
                "C162Gate", 0.0, talas::expr::ValueDomain::Scalar},
            talas::runtime::RealtimeEventValueUpdate{
                "C162Step", 2.0, talas::expr::ValueDomain::Scalar},
            talas::runtime::RealtimeEventValueUpdate{
                "C162Rate", 2.0, talas::expr::ValueDomain::Scalar},
        };
        const std::array timedRate{
            talas::runtime::RealtimeEventValueUpdate{
                "C162Step", 0.0, talas::expr::ValueDomain::Scalar},
            talas::runtime::RealtimeEventValueUpdate{
                "C162Rate", 4.0, talas::expr::ValueDomain::Scalar},
        };
        const std::array reversedLevels{
            talas::runtime::RealtimeEventValueUpdate{
                "C162Left", -0.75, talas::expr::ValueDomain::Scalar},
            talas::runtime::RealtimeEventValueUpdate{
                "C162Right", 0.75, talas::expr::ValueDomain::Scalar},
        };
        require(session.scheduleEventValues(levels, 1)
                && session.scheduleEventValues(closedStepRate, 2)
                && session.scheduleEventValue(
                    "C162Gate", 1.0,
                    talas::expr::ValueDomain::Scalar, 3)
                && session.scheduleEventValues(timedRate, 4)
                && session.scheduleEventValues(reversedLevels, 5),
            "C162 same-frame Analog Sequencer control batches should stage");
    };

    const auto preparedGraph = compile(
        makeC162ScheduledAnalogSequencerDocument(), initialSettings());
    talas::runtime::RealtimeRenderSession prepared{preparedGraph};
    require(prepared.ready(),
        "C162 scheduled Analog Sequencer should prepare: "
            + std::string{prepared.error()});
    // A level past 1 and a Rate of zero saturate (2026-10-13); values that
    // are not finite, and a Step that is not whole, are still refused.
    require(!prepared.scheduleEventValue(
                "C162Left", std::numeric_limits<double>::infinity(),
                talas::expr::ValueDomain::Scalar, 0)
            && !prepared.scheduleEventValue(
                "C162Right",
                std::numeric_limits<double>::infinity(),
                talas::expr::ValueDomain::Scalar, 0)
            && !prepared.scheduleEventValue(
                "C162Gate",
                std::numeric_limits<double>::infinity(),
                talas::expr::ValueDomain::Scalar, 0)
            && !prepared.scheduleEventValue(
                "C162Step", 1.5,
                talas::expr::ValueDomain::Scalar, 0)
            && !prepared.scheduleEventValue(
                "C162Rate", std::numeric_limits<double>::infinity(),
                talas::expr::ValueDomain::Scalar, 0),
        "C162 invalid Analog Sequencer schedules should reject transactionally");
    schedule(prepared);
    std::array<double, 8> preparedLeft{};
    std::array<double, 8> preparedRight{};
    std::size_t allocations = 0;
    require(renderStereoAndCount(
                prepared, preparedLeft, preparedRight, allocations)
            && allocations == 0
            && std::ranges::equal(preparedLeft, offline.mono)
            && std::ranges::equal(preparedRight, offline.right),
        "C162 five-control prepared schedule should match offline exactly without allocation");

    talas::runtime::RealtimeRenderSession singleFrame{preparedGraph};
    require(singleFrame.ready(),
        "C162 single-frame Analog Sequencer should prepare");
    schedule(singleFrame);
    std::array<double, 8> singleLeft{};
    std::array<double, 8> singleRight{};
    for (std::size_t frame = 0; frame < singleLeft.size(); ++frame)
    {
        require(renderStereoAndCount(
                    singleFrame,
                    std::span<double>{singleLeft}.subspan(frame, 1),
                    std::span<double>{singleRight}.subspan(frame, 1),
                    allocations)
                && allocations == 0,
            "C162 single-frame Analog Sequencer partition should render allocation free");
    }
    require(singleLeft == preparedLeft && singleRight == preparedRight,
        "C162 Analog Sequencer schedules should retain exact offsets across single-frame callbacks");
}

void testAnalogSequencerDownstreamFailureRestoresScheduledControls()
{
    auto document = makeC162ScheduledAnalogSequencerDocument();
    const auto oscillator = std::ranges::find(
        document.graph.nodes,
        std::string_view{"oscillator"},
        &talas::project::ProjectNode::instanceId);
    require(oscillator != document.graph.nodes.end(),
        "C162 rollback fixture should expose its carrier");
    const auto amplitude = std::ranges::find(
        oscillator->parameters,
        std::string_view{"amplitude"},
        &talas::project::ProjectParameterExpression::parameterId);
    require(amplitude != oscillator->parameters.end(),
        "C162 rollback fixture should expose carrier amplitude");
    amplitude->expression = "8";
    std::erase_if(document.graph.connections,
        [] (const auto& candidate) {
            return candidate.fromNode == "sequence"
                && candidate.toNode == "out";
        });
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C162Downstream"},
            {"right", "0"},
            booleanParameter("noGain", false),
        }));
    document.graph.connections.push_back(connection(
        "sequence", "leftOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "sequence", "rightOut", "out", "rightIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 2};
    settings.maxRealtimeEventTransactions = 4;
    settings.eventValues = {
        {"C162Left", 0.5, talas::expr::ValueDomain::Scalar},
        {"C162Right", 0.25, talas::expr::ValueDomain::Scalar},
        {"C162Gate", 1.0, talas::expr::ValueDomain::Scalar},
        {"C162Step", 0.0, talas::expr::ValueDomain::Scalar},
        {"C162Rate", 1.0, talas::expr::ValueDomain::Scalar},
        {"C162Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate{graph};
    talas::runtime::RealtimeRenderSession pristine{graph};
    require(candidate.ready() && pristine.ready(),
        "C162 scheduled downstream rollback fixtures should prepare");
    require(candidate.scheduleEventValue(
                "C162Left", 1.0,
                talas::expr::ValueDomain::Scalar, 1)
            && pristine.scheduleEventValue(
                "C162Left", 1.0,
                talas::expr::ValueDomain::Scalar, 1)
            && candidate.scheduleEventValue(
                "C162Downstream",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar, 1),
        "C162 rollback fixture should stage Analog Sequencer control and downstream failure together");
    const auto checkpoint =
        talas::runtime::RealtimeRenderSessionTestAccess::
            callbackTimelineState(candidate);
    std::array<double, 2> rejectedLeft{};
    std::array<double, 2> rejectedRight{};
    std::size_t allocations = 0;
    for (auto attempt = 0; attempt < 2; ++attempt)
    {
        rejectedLeft.fill(162.0);
        rejectedRight.fill(162.0);
        require(!renderStereoAndCount(
                    candidate,
                    rejectedLeft,
                    rejectedRight,
                    allocations)
                && allocations == 0
                && rejectedLeft == std::array<double, 2>{}
                && rejectedRight == std::array<double, 2>{}
                && talas::runtime::RealtimeRenderSessionTestAccess::
                        callbackTimelineState(candidate)
                    == checkpoint,
            "C162 repeated downstream failure should restore schedules, callback position, state, and both outputs");
    }
    require(candidate.updateEventValue(
                "C162Downstream", 1.0,
                talas::expr::ValueDomain::Scalar),
        "C162 repaired rollback fixture should publish a finite downstream value");
    std::array<double, 2> repairedLeft{};
    std::array<double, 2> repairedRight{};
    std::array<double, 2> expectedLeft{};
    std::array<double, 2> expectedRight{};
    require(renderStereoAndCount(
                candidate, repairedLeft, repairedRight, allocations)
            && renderStereoAndCount(
                pristine, expectedLeft, expectedRight, allocations)
            && allocations == 0
            && repairedLeft == expectedLeft
            && repairedRight == expectedRight,
        "C162 repaired retry should match pristine scheduled Analog Sequencer state exactly");
}

void testRealtimeAnalogSequencerKeepsNestedInstanceStateIsolated()
{
    const auto document = makeNestedAnalogSequencerRealtimeDocument();
    auto graph = compile(
        document, talas::runtime::RenderSettings{4.0, 10});
    std::vector<talas::runtime::RuntimeScopeId> scopes;
    for (const auto& step : graph.plan().steps)
    {
        if (step.typeId == "talas.analogSequencer")
            scopes.push_back(step.scopeId);
    }
    require(
        scopes.size() == 2 && scopes[0] != scopes[1],
        "nested Analog Sequencer instances should compile into distinct structural scopes");
    const std::array partitions{
        std::size_t{2}, std::size_t{5}, std::size_t{3}};
    requireAnalogSequencerRealtimeParity(
        document,
        talas::runtime::RenderSettings{4.0, 10},
        partitions,
        "nested isolated instances");
}

void testRealtimePartialTrackPlayerUsesImmutableTypedAssetWithoutAllocations()
{
    const talas::project::PartialTrackAsset asset{
        48'000.0,
        256,
        {
            {1, 0, {{9, 0.5, 440.0, 4.0}}},
            {1, 128, {{9, 0.25, 660.0, 4.0}}},
        }};
    const auto encoded = talas::project::encodePartialTrackAsset(asset);
    require(encoded.ok(), "partial player fixture should encode");
    const std::string hash(64, 'a');
    talas::project::ProjectDocument document;
    document.assets.push_back({
        "Analysis/Partials",
        talas::project::ProjectAssetKind::PartialSpectrum,
        "analysis/partials.talaspartial",
        talas::project::ProjectAssetDisposition::Referenced,
        hash,
        0,
        asset.sampleRate,
        asset.sourceFrameCount,
        std::string{talas::project::partialTrackAssetEncoding},
        7,
        {}});
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "partials",
        "talas.partialTrackPlayerV1",
        {resourceParameter("partialTrack", "Analysis/Partials"),
         {"gain", "1.0"}}));
    document.graph.connections.push_back(connection(
        "partials", "audioOut", "out", "audioIn"));

    auto snapshot = std::make_shared<talas::core::ResourceSnapshot>();
    snapshot->id = "Analysis/Partials";
    snapshot->kind = talas::core::ResourceSnapshotKind::PartialSpectrum;
    snapshot->generation = 7;
    snapshot->contentHash = hash;
    snapshot->sampleRate = asset.sampleRate;
    snapshot->frameCount = asset.sourceFrameCount;
    snapshot->encoding = std::string{talas::project::partialTrackAssetEncoding};
    snapshot->partialTrackBytes = encoded.bytes;
    talas::runtime::RenderSettings settings{asset.sampleRate, 256};
    settings.resourceSnapshots.push_back(std::move(snapshot));
    auto graph = compile(document, std::move(settings));
    const auto offline = talas::runtime::renderOffline(graph, 256);
    require(offline.ok() && offline.mono.size() == 256,
            "typed partial player should render through the offline runtime");

    talas::runtime::RealtimeRenderSession contiguous(graph);
    talas::runtime::RealtimeRenderSession partitioned(graph);
    require(contiguous.ready() && partitioned.ready(),
            "typed partial player should prepare against exact immutable media authority: "
                + std::string(contiguous.error()) + " / "
                + std::string(partitioned.error()));
    std::array<double, 256> expected{};
    std::array<double, 256> actual{};
    std::size_t allocations = 0;
    require(renderAndCount(contiguous, expected, allocations)
                && allocations == 0,
            "contiguous typed partial callback should render without allocation");
    require(renderAndCount(
                partitioned,
                std::span<double>{actual}.first(73),
                allocations)
                && allocations == 0
                && renderAndCount(
                    partitioned,
                    std::span<double>{actual}.subspan(73),
                    allocations)
                && allocations == 0
                && expected == actual,
            "typed partial player should remain exact across irregular callback partitions");
    require(std::equal(
                expected.begin(), expected.end(), offline.mono.begin()),
            "prepared realtime and offline partial-track runtimes should share exact output");

    const talas::project::PartialTrackAsset replacementAsset{
        48'000.0,
        256,
        {
            {1, 0, {{9, 0.5, 880.0, 4.0}}},
            {1, 128, {{9, 0.25, 990.0, 4.0}}},
        }};
    const auto replacementBytes =
        talas::project::encodePartialTrackAsset(replacementAsset);
    require(replacementBytes.ok(),
            "replacement partial player fixture should encode");
    document.assets.front().generation = 8;
    document.assets.front().contentHash = std::string(64, 'b');
    auto replacementSnapshot =
        std::make_shared<talas::core::ResourceSnapshot>();
    replacementSnapshot->id = "Analysis/Partials";
    replacementSnapshot->kind =
        talas::core::ResourceSnapshotKind::PartialSpectrum;
    replacementSnapshot->generation = 8;
    replacementSnapshot->contentHash = document.assets.front().contentHash;
    replacementSnapshot->sampleRate = replacementAsset.sampleRate;
    replacementSnapshot->frameCount = replacementAsset.sourceFrameCount;
    replacementSnapshot->encoding =
        std::string{talas::project::partialTrackAssetEncoding};
    replacementSnapshot->partialTrackBytes = replacementBytes.bytes;
    talas::runtime::RenderSettings replacementSettings{
        replacementAsset.sampleRate, 256};
    replacementSettings.resourceSnapshots.push_back(
        std::move(replacementSnapshot));
    auto replacementGraph = compile(
        document, std::move(replacementSettings));
    talas::runtime::RealtimeRenderSession replacement{
        replacementGraph};
    std::array<double, 256> replacementOutput{};
    require(replacement.ready()
                && renderAndCount(
                    replacement, replacementOutput, allocations)
                && allocations == 0
                && replacementOutput != expected,
            "a new immutable partial-track generation should own independent prepared DSP state");
}

void testRealtimeSessionPublishesBoundedPreparedNodeTimingWithoutAllocations()
{
    auto graph = compile(makeOscillatorVcaDocument(), {48'000.0, 2});
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    const auto initial = session.preparedNodeTiming();
    require(!initial.capacityExceeded,
        "small prepared graph should fit the node timing budget");
    require(initial.records.size() == 4,
        "node timing should retain one exact record per prepared step");
    require(std::ranges::all_of(initial.records, [](const auto& record) {
        return !record.publicationValid && record.sampleCount == 0;
    }), "node timing must remain unavailable before its first callback sample");

    std::array<double, 2> output{};
    for (std::size_t callback = 0; callback < initial.records.size(); ++callback)
    {
        std::size_t allocations = 0;
        require(renderAndCount(session, output, allocations),
            "timed prepared callback should render");
        require(allocations == 0,
            "prepared node timing publication must not allocate");
    }

    const auto sampled = session.preparedNodeTiming();
    require(sampled.records.size() == initial.records.size(),
        "timing publication must preserve exact prepared node cardinality");
    require(std::ranges::all_of(sampled.records, [](const auto& record) {
        return record.publicationValid
            && record.sampleCount == 1
            && record.sampleSequence == 1
            && record.callbackFrames == 2
            && record.maximumDurationNanoseconds
                >= record.latestDurationNanoseconds
            && record.sampledDurationNanoseconds
                >= record.latestDurationNanoseconds
            && !record.nodeId.empty()
            && !record.typeId.empty();
    }), "round-robin timing should publish one coherent sample per node");
}

void testRealtimeSessionRejectsOversizedPreparedNodeTimingEvidenceOnly()
{
    auto document = makeOscillatorVcaDocument();
    document.graph.connections.erase(
        std::remove_if(
            document.graph.connections.begin(),
            document.graph.connections.end(),
            [](const auto& candidate) {
                return candidate.fromNode == "gain"
                    && candidate.toNode == "vca";
            }),
        document.graph.connections.end());
    std::string previous = "gain";
    for (std::size_t index = document.graph.nodes.size();
         index <= talas::runtime::maximumPreparedNodeTimingRecords;
         ++index)
    {
        auto current = "timing-capacity-" + std::to_string(index);
        document.graph.nodes.push_back(node(current, "talas.add"));
        document.graph.connections.push_back(connection(
            previous, "value", current, "left"));
        document.graph.connections.push_back(connection(
            "gain", "value", current, "right"));
        previous = std::move(current);
    }
    document.graph.connections.push_back(connection(
        previous, "value", "vca", "gain"));
    auto graph = compile(document, {48'000.0, 2});
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(),
        "timing evidence capacity must not reject an otherwise valid graph");

    const auto timing = session.preparedNodeTiming();
    require(timing.capacityExceeded && timing.records.empty(),
        "an oversized graph must reject all partial per-node timing evidence");
    std::array<double, 2> output{};
    std::size_t allocations = 0;
    require(renderAndCount(session, output, allocations),
        "an oversized timing graph should remain playable");
    require(allocations == 0,
        "disabled oversized timing evidence must not allocate on callback");
}

void requireRealtimeBlockRejection(const talas::project::ProjectDocument& document, const std::string& message)
{
    auto graph = compile(document);
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 2> output{};
    std::size_t allocations = 0;
    require(!renderAndCount(session, output, allocations), message);
    require(allocations == 0, message + " should not allocate");
}

void testRealtimeSessionRendersPreparedMidiVoiceAtExactAttackFrameWithoutAllocations()
{
    auto graph = compile(makePreparedMidiVoiceDocument(), preparedMidiVoiceSettings());
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::size_t allocations = 0;
    std::array<double, 4> silentLeft{};
    std::array<double, 4> silentRight{};
    require(renderStereoAndCount(session, silentLeft, silentRight, allocations),
            "prepared MIDI voice pre-note block should render");
    require(allocations == 0, "prepared MIDI voice pre-note block should not allocate");
    for (std::size_t frame = 0; frame < silentLeft.size(); ++frame)
    {
        requireNear(silentLeft[frame], 0.0, 1.0e-12, "prepared MIDI voice should be silent before note-on");
        requireNear(silentRight[frame], 0.0, 1.0e-12, "prepared MIDI voice right should be silent before note-on");
    }

    talas::runtime::RealtimeMidiDispatchResult dispatch{};
    {
        AllocationCounter counter;
        dispatch = session.scheduleMidiNote(
            {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 60, 127},
            0);
        allocations = counter.count();
    }
    require(dispatch == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "matching MIDI note-on should route to prepared voices");
    require(allocations == 0, "prepared MIDI note scheduling should not allocate");

    std::array<double, 8> attackLeft{};
    std::array<double, 8> attackRight{};
    require(renderStereoAndCount(session, attackLeft, attackRight, allocations),
            "prepared MIDI voice attack block should render");
    require(allocations == 0, "prepared MIDI voice attack block should not allocate");
    for (std::size_t frame = 0; frame < 5; ++frame)
    {
        requireNear(attackLeft[frame], 0.0, 1.0e-12, "prepared MIDI voice should remain reset before delayed attack");
        requireNear(attackRight[frame], 0.0, 1.0e-12, "prepared MIDI voice right should remain reset before delayed attack");
    }
    auto heardAttack = false;
    for (std::size_t frame = 5; frame < attackLeft.size(); ++frame)
        heardAttack = heardAttack || std::abs(attackLeft[frame]) > 1.0e-6;
    require(heardAttack, "prepared MIDI voice should sound beginning at the five millisecond attack boundary");
    require(attackLeft == attackRight, "equal MIDI voice gains should produce matching stereo output");
}

void testRealtimeSessionRoutesMultiplePreparedMidiRegionsWithoutAllocations()
{
    auto graph = compile(
        makeMultiplePreparedMidiVoiceDocument(),
        preparedMidiVoiceSettings());
    require(
        graph.plan().midiVoices.size() == 2,
        "multiple-region realtime fixture should retain two prepared plans");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::size_t allocations = 0;
    talas::runtime::RealtimeMidiDispatchResult dispatch{};
    {
        AllocationCounter counter;
        dispatch = session.scheduleMidiNote(
            {talas::runtime::RealtimeMidiNoteKind::NoteOn, 3, 60, 127},
            0);
        allocations = counter.count();
    }
    require(
        dispatch == talas::runtime::RealtimeMidiDispatchResult::NotHandled
            && allocations == 0,
        "MIDI outside every prepared region should fall through without allocating");

    {
        AllocationCounter counter;
        dispatch = session.scheduleMidiNote(
            {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 60, 127},
            0);
        allocations = counter.count();
    }
    require(
        dispatch == talas::runtime::RealtimeMidiDispatchResult::Handled
            && allocations == 0,
        "first region scheduling should be allocation-free");
    std::array<double, 8> first{};
    require(
        renderAndCount(session, first, allocations)
            && allocations == 0
            && std::ranges::any_of(first, [](double sample) {
                   return std::abs(sample) > 1.0e-6;
               }),
        "first prepared region should attack and render without allocating");

    {
        AllocationCounter counter;
        dispatch = session.scheduleMidiNote(
            {talas::runtime::RealtimeMidiNoteKind::NoteOn, 2, 64, 127},
            0);
        allocations = counter.count();
    }
    require(
        dispatch == talas::runtime::RealtimeMidiDispatchResult::Handled
            && allocations == 0,
        "second region scheduling should be allocation-free");
    std::array<double, 8> both{};
    require(
        renderAndCount(session, both, allocations)
            && allocations == 0
            && std::ranges::any_of(both, [](double sample) {
                   return std::abs(sample) > 1.0e-6;
               }),
        "both prepared regions should retain independent state without callback allocation");
}

void testRealtimeSessionMixesIndependentPreparedVoicesAndFiltersMidi()
{
    auto graph = compile(makePreparedMidiVoiceDocument(2, 2, 48, 72), preparedMidiVoiceSettings());
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 60, 127},
                0)
            == talas::runtime::RealtimeMidiDispatchResult::NotHandled,
            "different MIDI channel should fall through");
    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 2, 73, 127},
                0)
            == talas::runtime::RealtimeMidiDispatchResult::NotHandled,
            "out-of-range MIDI note should fall through");
    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 2, 60, 127},
                0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "first matching MIDI note should be handled");

    std::array<double, 8> firstLeft{};
    std::array<double, 8> firstRight{};
    require(session.render(firstLeft, firstRight), "first prepared MIDI voice should render");

    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 2, 60, 127},
                0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "repeated MIDI note should allocate an independent voice");
    std::array<double, 8> doubledLeft{};
    std::array<double, 8> doubledRight{};
    std::size_t allocations = 0;
    require(renderStereoAndCount(session, doubledLeft, doubledRight, allocations),
            "two prepared MIDI voices should render");
    require(allocations == 0, "prepared MIDI voice mixing should not allocate");
    for (std::size_t frame = 5; frame < doubledLeft.size(); ++frame)
    {
        if (std::abs(firstLeft[frame]) > 1.0e-6)
            require(std::abs(doubledLeft[frame]) > std::abs(firstLeft[frame]),
                    "second activated voice should increase deterministic mix magnitude");
    }
}

void testSessionStateAdvancesOnlyForAffectedMidiVoice()
{
    auto polyGraph = compile(
        makePreparedMidiVoiceDocument(
            2,
            1,
            0,
            127,
            "previous(!KeyDown, 0)"),
        preparedMidiVoiceSettings());
    auto referenceGraph = compile(
        makePreparedMidiVoiceDocument(
            1,
            1,
            0,
            127,
            "previous(!KeyDown, 0)"),
        preparedMidiVoiceSettings());
    talas::runtime::RealtimeRenderSession poly(polyGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(poly.ready(), std::string(poly.error()));
    require(reference.ready(), std::string(reference.error()));
    for (auto* session : {&poly, &reference})
    {
        require(session->scheduleMidiNote(
                    {talas::runtime::RealtimeMidiNoteKind::NoteOn,
                     1,
                     60,
                     127},
                    0)
                == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "voice-isolation seed note should schedule");
    }
    std::array<double, 16> seededPoly{};
    std::array<double, 16> seededReference{};
    require(poly.render(seededPoly) && reference.render(seededReference),
        "voice-isolation seed callbacks should render");
    require(poly.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn,
                 1,
                 72,
                 127},
                0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
        "second prepared voice should schedule");
    std::array<double, 16> changed{};
    std::array<double, 16> unchanged{};
    std::size_t allocations = 0;
    require(renderAndCount(poly, changed, allocations)
            && reference.render(unchanged),
        "voice-isolation comparison callbacks should render");
    require(allocations == 0,
        "voice-isolated Session evaluation should allocate nothing");
    for (std::size_t frame = 0; frame < 5; ++frame)
    {
        requireNear(changed[frame], unchanged[frame], 1.0e-12,
            "a second voice retrigger must not advance the first voice Session state");
    }
}

void testVoiceStateShadowsMatchingGlobalEventUpdates()
{
    auto changedGraph = compile(
        makePreparedMidiVoiceDocument(
            1,
            1,
            0,
            127,
            "accumulate(!KeyDown, 0, 0)"),
        preparedMidiVoiceSettings());
    auto referenceGraph = compile(
        makePreparedMidiVoiceDocument(
            1,
            1,
            0,
            127,
            "accumulate(!KeyDown, 0, 0)"),
        preparedMidiVoiceSettings());
    talas::runtime::RealtimeRenderSession changed(changedGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(changed.ready(), std::string(changed.error()));
    require(reference.ready(), std::string(reference.error()));
    for (auto* session : {&changed, &reference})
    {
        require(session->scheduleMidiNote(
                    {talas::runtime::RealtimeMidiNoteKind::NoteOn,
                     1,
                     60,
                     127},
                    0)
                == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "MIDI-shadow fixture should schedule its voice");
    }
    std::array<double, 16> changedOutput{};
    std::array<double, 16> referenceOutput{};
    require(changed.render(changedOutput)
            && reference.render(referenceOutput),
        "MIDI-shadow seed callbacks should render");
    require(changed.updateEventValue(
                "KeyDown", 1.0, talas::expr::ValueDomain::Scalar),
        "matching global Event Value should remain a valid update");
    std::size_t allocations = 0;
    require(renderAndCount(changed, changedOutput, allocations)
            && reference.render(referenceOutput),
        "MIDI-shadow comparison callbacks should render");
    require(allocations == 0,
        "MIDI-shadow affected filtering should allocate nothing");
    for (std::size_t frame = 0; frame < changedOutput.size(); ++frame)
    {
        requireNear(
            changedOutput[frame],
            referenceOutput[frame],
            1.0e-12,
            "a global KeyDown binding must not advance voice state shadowed by MIDI");
    }
}

void testRealtimeSessionRejectsFullMidiQueueTransactionally()
{
    auto graph = compile(makePreparedMidiVoiceDocument(1), preparedMidiVoiceSettings(1));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 60, 127},
                0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "first MIDI command should fill prepared queue");
    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 61, 127},
                1)
            == talas::runtime::RealtimeMidiDispatchResult::Rejected,
            "full MIDI queue should reject without mutating allocator state");

    std::array<double, 8> left{};
    std::array<double, 8> right{};
    require(session.render(left, right), "accepted MIDI command should still render after rejected enqueue");
    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOff, 1, 60, 0},
                0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "queue should recover after rendering the accepted command");
}

void testRealtimeSessionSchedulesTypedMidiAndClassifiesFallback()
{
    const auto midiEvent = [](
        std::uint8_t channel,
        std::uint8_t note,
        std::size_t frameOffset,
        std::uint64_t sequence) {
        talas::runtime::TypedEventPayload payload{};
        payload.midiNote = {channel, note, 127};
        return talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::MidiNoteOn,
            {
                talas::runtime::TypedEventTargetKind::MidiVoice,
                1,
                1,
                1,
            },
            frameOffset,
            sequence,
            payload,
        };
    };

    auto graph = compile(
        makePreparedMidiVoiceDocument(1, 1, 0, 127),
        preparedMidiVoiceSettings(4));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    const std::array events = {
        midiEvent(1, 60, 0, 1),
        midiEvent(2, 64, 0, 2),
    };
    std::array<talas::runtime::RealtimeTypedEventDispatchResult, 2> results{};
    bool accepted = false;
    std::size_t allocations = 0;
    {
        AllocationCounter counter;
        accepted = session.scheduleTypedEvents(events, results);
        allocations = counter.count();
    }
    require(accepted, "typed MIDI batch should schedule handled events while classifying fallback");
    require(allocations == 0, "typed MIDI batch scheduling should not allocate");
    require(
        results[0] == talas::runtime::RealtimeTypedEventDispatchResult::Handled
            && results[1]
                == talas::runtime::RealtimeTypedEventDispatchResult::NotHandled,
        "typed MIDI scheduling should distinguish prepared-voice handling from fallback");
    std::array<double, 8> left{};
    std::array<double, 8> right{};
    require(
        renderStereoAndCount(session, left, right, allocations),
        "handled typed MIDI event should render");
    require(allocations == 0, "handled typed MIDI render should not allocate");
    require(
        std::ranges::any_of(left, [](double sample) {
            return std::abs(sample) > 1.0e-6;
        }),
        "handled typed MIDI event should reach the prepared voice");

    auto constrainedGraph = compile(
        makePreparedMidiVoiceDocument(1, 1, 0, 127),
        preparedMidiVoiceSettings(1));
    talas::runtime::RealtimeRenderSession constrained(constrainedGraph);
    require(constrained.ready(), std::string(constrained.error()));
    const std::array overflow = {
        midiEvent(1, 60, 0, 3),
        midiEvent(1, 61, 1, 4),
    };
    std::array<talas::runtime::RealtimeTypedEventDispatchResult, 2>
        overflowResults{};
    require(
        !constrained.scheduleTypedEvents(overflow, overflowResults),
        "typed MIDI batch beyond prepared capacity should reject transactionally");
    require(
        std::ranges::all_of(overflowResults, [](const auto result) {
            return result
                == talas::runtime::RealtimeTypedEventDispatchResult::Rejected;
        }),
        "typed MIDI capacity rejection should reject the whole batch");
    require(
        constrained.scheduleMidiNote(
            {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 60, 127},
            0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
        "typed MIDI rejection must leave legacy adapter queue state unchanged");
}

void testRealtimeSessionAppliesSameFrameVoiceAssignmentToNewGeneration()
{
    auto document = makePreparedMidiVoiceDocument(1);
    document.expressionLanguage =
        talas::expr::ExpressionLanguageVersion::VariablesV1;
    talas::project::ProjectVariableDeclaration variable;
    variable.variableId = "voiceGain";
    variable.displayName = "Voice gain";
    variable.initialValue = 0.25;
    variable.snapshotEligible = false;
    variable.owner.kind =
        talas::project::ProjectVariableOwnerKind::MidiVoice;
    variable.owner.nodeId = "midi";
    document.variableLibrary.variables.push_back(variable);
    auto graph = compile(document, preparedMidiVoiceSettings(4));
    require(graph.preparedVariables().cells.size() == 1,
        "same-frame voice-variable fixture should prepare one exact cell");
    {
        auto forged = graph;
        mutableSettingsForTest(forged).preparedVariables.cells.front().identity.voiceAncestors
            .push_back({"parent", {}, {}, 0});
        talas::runtime::RealtimeRenderSession rejected(forged);
        require(!rejected.ready(),
            "voice ancestry mutation must not retain the compiler's sealed variable authority");
    }
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    const auto& cell = graph.preparedVariables().cells.front();
    require(!session.variableTargetIndex(cell.identity, cell.domain).has_value(),
        "generic target resolution should exclude voice-owned cells");
    talas::runtime::TypedEventPayload notePayload{};
    notePayload.midiNote = {1, 60, 127};
    talas::runtime::TypedEventPayload variablePayload{};
    variablePayload.variable = {0.75, cell.domain};
    const std::array events{
        talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::MidiNoteOn,
            {talas::runtime::TypedEventTargetKind::MidiVoice, 1, 1, 1},
            0,
            1,
            notePayload,
        },
        talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::VariableAssignment,
            {
                talas::runtime::TypedEventTargetKind::Variable,
                1,
                1,
                1,
                1,
            },
            0,
            2,
            variablePayload,
        },
    };
    std::array<talas::runtime::RealtimeTypedEventDispatchResult, 2> results{};
    std::size_t allocations = 0;
    {
        AllocationCounter counter;
        require(session.scheduleTypedEvents(events, results),
            "same-frame NoteOn and exact generation assignment should queue atomically");
        allocations = counter.count();
    }
    require(std::ranges::all_of(results, [](const auto result) {
                return result
                    == talas::runtime::RealtimeTypedEventDispatchResult::Handled;
            }),
        "same-frame voice transaction should classify every event as handled");
    std::array<double, 8> output{};
    require(renderAndCount(session, output, allocations)
                && allocations == 0,
        "same-frame voice transaction should commit without callback allocation");
    const auto publication = session.preparedVariableValues();
    require(publication.publicationValid
                && publication.values.size() == 1
                && publication.values.front().voiceGeneration == 1
                && publication.values.front().value
                    == talas::expr::ExpressionValue{0.75, cell.domain}
                && session.voiceVariableTargetIndex(
                       cell.identity, cell.domain, 1)
                    == std::optional<std::uint32_t>{1}
                && !session.voiceVariableTargetIndex(
                       cell.identity, cell.domain, 2)
                        .has_value(),
        "committed voice cell should publish and resolve only its exact live generation");

    talas::runtime::TypedEventPayload staleVariablePayload{};
    staleVariablePayload.variable = {1.0, cell.domain};
    talas::runtime::TypedEventPayload stealPayload{};
    stealPayload.midiNote = {1, 61, 127};
    const std::array staleAcrossSteal{
        talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::VariableAssignment,
            {
                talas::runtime::TypedEventTargetKind::Variable,
                1,
                1,
                1,
                1,
            },
            0,
            3,
            staleVariablePayload,
        },
        talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::MidiNoteOn,
            {talas::runtime::TypedEventTargetKind::MidiVoice, 1, 1, 1},
            0,
            4,
            stealPayload,
        },
    };
    require(session.scheduleTypedEvents(staleAcrossSteal, results),
        "stale-across-steal fixture should reach callback validation");
    require(!session.render(output),
        "old-generation assignment sharing a steal batch must fail the whole transaction");
    const auto retained = session.preparedVariableValues();
    require(retained.publicationValid
                && retained.values.front().voiceGeneration == 1
                && retained.values.front().value.value == 0.75,
        "rejected steal batch should roll back allocator, generation, and voice cells together");
    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 61, 127},
                0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled
            && session.render(output),
        "allocator should remain usable after exact transaction rollback");
    const auto stolen = session.preparedVariableValues();
    require(stolen.values.front().voiceGeneration == 2
                && stolen.values.front().value.value == 0.25,
        "successful reuse after rollback should advance once and reset its cell range");
}

void testRealtimeSessionAppliesSoundSelectionsAtomicallyWithVoiceReuse()
{
    auto document = makePreparedMidiVoiceDocument(1);
    document.soundDefinitions = {
        {.definitionId = "toneA", .displayName = "Tone A"},
        {.definitionId = "toneB", .displayName = "Tone B"},
    };
    talas::project::ProjectSoundVariableDeclaration projectSound;
    projectSound.variableId = "projectSound";
    projectSound.displayName = "Project Sound";
    projectSound.candidateDefinitionIds = {"toneA", "toneB"};
    talas::project::ProjectSoundVariableDeclaration voiceSound = projectSound;
    voiceSound.variableId = "voiceSound";
    voiceSound.displayName = "Voice Sound";
    voiceSound.snapshotEligible = false;
    voiceSound.owner.kind = talas::project::ProjectVariableOwnerKind::MidiVoice;
    voiceSound.owner.nodeId = "midi";
    document.soundVariableLibrary.variables = {
        std::move(projectSound),
        std::move(voiceSound),
    };
    auto graph = compile(document, preparedMidiVoiceSettings(8));
    require(
        graph.preparedSoundVariables().cells.size() == 2,
        "Sound-selection fixture should prepare project and voice cells"
    );
    for (std::size_t index = 0; index < graph.preparedSoundVariables().cells.size(); ++index)
    {
        auto forged = graph;
        mutableSettingsForTest(forged).preparedSoundVariables.cells[index].identity.voiceAncestors
            .push_back({"parent", {}, {}, 0});
        talas::runtime::RealtimeRenderSession rejected(forged);
        require(!rejected.ready(),
            "Sound ancestry mutation must reject both project and voice cells in a sealed flat plan");
    }
    {
        talas::runtime::OfflineRenderSession offline(graph);
        const std::array offlineAssignments{
            talas::runtime::OfflineSoundVariableAssignment{
                2,
                1,
                1,
                graph.preparedSoundVariables().cells.front().identity,
                "toneB",
            },
        };
        require(
            offline.scheduleSoundVariableAssignments(offlineAssignments) && offline.render(4).ok(),
            "offline Sound assignment should commit at its exact absolute frame"
        );
        const auto offlineValues = offline.soundVariableValues();
        require(
            offlineValues.size() == 2 && offlineValues.front().selectedDefinitionId == "toneB",
            "offline publication should preserve exact definition identity"
        );
    }
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    const auto& projectCell = graph.preparedSoundVariables().cells.front();
    const auto& voiceCell = graph.preparedSoundVariables().cells.back();
    require(
        session.soundVariableTargetIndex(projectCell.identity, "toneB") ==
                std::optional<talas::runtime::PreparedSoundVariableTargetIndex>{{1, 1}} &&
            !session.soundVariableTargetIndex(voiceCell.identity, "toneB").has_value(),
        "generic Sound target resolution should validate exact candidate "
        "identity and exclude voice cells"
    );

    talas::runtime::TypedEventPayload projectPayload{};
    projectPayload.soundVariable = {1};
    const std::array projectEvents{
        talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::SoundVariableAssignment,
            {
                talas::runtime::TypedEventTargetKind::SoundVariable,
                1,
                1,
                1,
            },
            0,
            1,
            projectPayload,
        },
    };
    std::array<talas::runtime::RealtimeTypedEventDispatchResult, 1> projectResults{};
    require(
        session.scheduleTypedEvents(projectEvents, projectResults),
        "project Sound assignment should queue"
    );
    std::array<double, 8> output{};
    require(session.render(output), "project Sound assignment should commit");
    auto publication = session.preparedSoundVariableValues();
    require(
        publication.publicationValid && publication.values.front().selectedDefinitionId == "toneB",
        "committed project Sound assignment should publish exact definition ID"
    );

    talas::runtime::TypedEventPayload notePayload{};
    notePayload.midiNote = {1, 60, 127};
    talas::runtime::TypedEventPayload voicePayload{};
    voicePayload.soundVariable = {1};
    const std::array voiceEvents{
        talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::MidiNoteOn,
            {talas::runtime::TypedEventTargetKind::MidiVoice, 1, 1, 1},
            0,
            2,
            notePayload,
        },
        talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::SoundVariableAssignment,
            {
                talas::runtime::TypedEventTargetKind::SoundVariable,
                2,
                1,
                1,
                1,
            },
            0,
            3,
            voicePayload,
        },
    };
    std::array<talas::runtime::RealtimeTypedEventDispatchResult, 2> voiceResults{};
    require(
        session.scheduleTypedEvents(voiceEvents, voiceResults) && session.render(output),
        "NoteOn and exact-generation Sound assignment should commit atomically"
    );
    publication = session.preparedSoundVariableValues();
    require(
        publication.values.back().voiceGeneration == 1 &&
            publication.values.back().selectedDefinitionId == "toneB" &&
            session.voiceSoundVariableTargetIndex(voiceCell.identity, "toneA", 1) ==
                std::optional<talas::runtime::PreparedSoundVariableTargetIndex>{{2, 0}} &&
            !session.voiceSoundVariableTargetIndex(voiceCell.identity, "toneA", 2).has_value(),
        "voice Sound publication and resolution should bind to the exact live "
        "slot generation"
    );

    talas::runtime::TypedEventPayload oldVoicePayload{};
    oldVoicePayload.soundVariable = {0};
    talas::runtime::TypedEventPayload stealPayload{};
    stealPayload.midiNote = {1, 61, 127};
    const std::array staleAcrossSteal{
        talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::SoundVariableAssignment,
            {
                talas::runtime::TypedEventTargetKind::SoundVariable,
                2,
                1,
                1,
                1,
            },
            0,
            4,
            oldVoicePayload,
        },
        talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::MidiNoteOn,
            {talas::runtime::TypedEventTargetKind::MidiVoice, 1, 1, 1},
            0,
            5,
            stealPayload,
        },
    };
    require(
        session.scheduleTypedEvents(staleAcrossSteal, voiceResults),
        "stale Sound assignment should reach callback generation validation"
    );
    require(
        !session.render(output),
        "old-generation Sound assignment sharing a "
        "voice steal must reject the whole batch"
    );
    publication = session.preparedSoundVariableValues();
    require(
        publication.values.back().voiceGeneration == 1 &&
            publication.values.back().selectedDefinitionId == "toneB",
        "rejected Sound/voice batch should retain both prior voice "
        "generation and selection"
    );
}

talas::project::ProjectSoundDefinition makeSelectorTone(
    std::string definitionId,
    std::string amplitude)
{
    talas::project::ProjectSoundDefinition definition;
    definition.definitionId = std::move(definitionId);
    definition.displayName = definition.definitionId;
    definition.graph.nodes = {
        node(
            "osc",
            "talas.oscillator",
            {{"frequency", "1 hz"}, {"amplitude", std::move(amplitude)}}),
    };
    definition.outputs = {
        {"audioOut", talas::core::PortType::Audio, "osc", "audioOut"},
    };
    return definition;
}

talas::project::ProjectDocument makeSoundVariableSelectorDocument(
    std::string typeId,
    talas::project::ProjectSoundVariableKind kind,
    std::vector<std::string> candidates)
{
    talas::project::ProjectDocument document;
    if (!candidates.empty())
    {
        document.soundDefinitions = {
            makeSelectorTone("toneA", "0"),
            makeSelectorTone("toneB", "1"),
        };
    }
    talas::project::ProjectSoundVariableDeclaration declaration;
    declaration.variableId = "selected";
    declaration.displayName = "Selected Sound";
    declaration.kind = kind;
    declaration.candidateDefinitionIds = std::move(candidates);
    document.soundVariableLibrary.variables = {std::move(declaration)};
    document.graph.nodes = {
        node("selector", std::move(typeId), {textParameter("variableId", "selected")}),
        node("out", "talas.audioOutput"),
    };
    // The one-of-N selector, which a SoundCollectionVariable heard alone is
    // in projects before format 90.
    if (document.graph.nodes.front().typeId == "talas.soundCollectionVariable")
        document.graph.nodes.front().parameters.push_back(choiceParameter("members", "legacySelected"));
    document.graph.connections = {
        connection("selector", "audioOut", "out", "audioIn"),
    };
    return document;
}

talas::project::ProjectDocument makeNestedSoundVariableSelectorDocument()
{
    auto document = makeSoundVariableSelectorDocument(
        "talas.variable",
        talas::project::ProjectSoundVariableKind::Sound,
        {"toneA", "toneB"});
    document.soundVariableLibrary.variables.front().owner.kind =
        talas::project::ProjectVariableOwnerKind::SoundDefinition;
    document.soundVariableLibrary.variables.front().owner.definitionId =
        "wrapper";
    document.soundVariableLibrary.variables.front().initialSelectedOrdinal = 1;

    talas::project::ProjectSoundDefinition wrapper;
    wrapper.definitionId = "wrapper";
    wrapper.displayName = "Wrapper";
    wrapper.graph.nodes = {
        node(
            "selector",
            "talas.variable",
            {textParameter("variableId", "selected")}),
    };
    wrapper.outputs = {
        {"audioOut", talas::core::PortType::Audio, "selector", "audioOut"},
    };
    document.soundDefinitions.push_back(std::move(wrapper));
    talas::project::ProjectNode instance;
    instance.instanceId = "wrapper1";
    instance.soundDefinitionId = "wrapper";
    document.graph.nodes = {
        std::move(instance),
        node("out", "talas.audioOutput"),
    };
    document.graph.connections = {
        connection("wrapper1", "audioOut", "out", "audioIn"),
    };
    return document;
}

void testSoundVariableSelectorsRenderPreparedBranchesWithoutAllocations()
{
    constexpr std::size_t frameCount = 160;
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 128.0;
    settings.maxBlockFrames = frameCount;
    auto graph = compile(
        makeSoundVariableSelectorDocument(
            "talas.variable",
            talas::project::ProjectSoundVariableKind::Sound,
            {"toneA", "toneB"}),
        settings);
    require(
        graph.preparedSoundVariables().cells.size() == 1
            && graph.plan().steps.size() >= 4,
        "Sound-variable selector should prepare one exact cell and both candidate branches");
    const auto& cell = graph.preparedSoundVariables().cells.front();

    talas::runtime::OfflineRenderSession offline(graph);
    const std::array assignments{
        talas::runtime::OfflineSoundVariableAssignment{
            8, 1, 1, cell.identity, "toneB"},
    };
    require(
        offline.scheduleSoundVariableAssignments(assignments),
        "offline selector assignment should bind exact candidate identity");
    const auto expected = offline.render(frameCount);
    require(expected.ok() && expected.mono.size() == frameCount,
        "offline Sound-variable selector should render its prepared branches");

    talas::runtime::RealtimeRenderSession realtime(graph);
    require(realtime.ready(), std::string(realtime.error()));
    const auto target = realtime.soundVariableTargetIndex(
        cell.identity, "toneB");
    require(target.has_value(),
        "realtime selector should resolve the exact candidate target");
    talas::runtime::TypedEventPayload payload{};
    payload.soundVariable = {target->selectedOrdinal};
    const std::array events{
        talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::SoundVariableAssignment,
            {
                talas::runtime::TypedEventTargetKind::SoundVariable,
                target->index,
                1,
                1,
            },
            8,
            1,
            payload,
        },
    };
    std::array<talas::runtime::RealtimeTypedEventDispatchResult, 1> results{};
    require(realtime.scheduleTypedEvents(events, results)
            && results.front()
                == talas::runtime::RealtimeTypedEventDispatchResult::Handled,
        "realtime selector assignment should queue at the exact frame");
    std::array<double, frameCount> actual{};
    std::size_t allocations = 0;
    require(renderAndCount(realtime, actual, allocations),
        "realtime Sound-variable selector should render");
    require(allocations == 0,
        "Sound-variable selection and crossfade must not allocate on the callback");
    bool heardSelectedBranch = false;
    for (std::size_t frame = 0; frame < frameCount; ++frame)
    {
        requireNear(
            actual[frame], expected.mono[frame], 1.0e-12,
            "offline and realtime Sound-variable selectors should match");
        if (frame < 8)
        {
            requireNear(actual[frame], 0.0, 1.0e-12,
                "initial zero-amplitude Sound branch should remain silent");
        }
        else if (std::abs(actual[frame]) > 1.0e-4)
        {
            heardSelectedBranch = true;
        }
    }
    require(heardSelectedBranch,
        "exact selection should audibly switch to the second prepared branch");

    auto emptyGraph = compile(
        makeSoundVariableSelectorDocument(
            "talas.soundCollectionVariable",
            talas::project::ProjectSoundVariableKind::SoundCollection,
            {}),
        settings);
    talas::runtime::OfflineRenderSession emptyOffline(emptyGraph);
    const auto emptyExpected = emptyOffline.render(16);
    require(emptyExpected.ok()
            && emptyOffline.soundVariableValues().size() == 1
            && emptyOffline.soundVariableValues().front()
                   .selectedDefinitionId.empty()
            && std::ranges::all_of(
                emptyExpected.mono,
                [](double sample) { return sample == 0.0; }),
        "empty Sound collection should render deterministic offline silence");
    talas::runtime::RealtimeRenderSession emptyRealtime(emptyGraph);
    require(emptyRealtime.ready(), std::string(emptyRealtime.error()));
    std::array<double, 16> emptyOutput{};
    allocations = 0;
    require(renderAndCount(emptyRealtime, emptyOutput, allocations)
            && allocations == 0
            && emptyRealtime.preparedSoundVariableValues().publicationValid
            && emptyRealtime.preparedSoundVariableValues().values.size() == 1
            && emptyRealtime.preparedSoundVariableValues().values.front()
                   .selectedDefinitionId.empty()
            && std::ranges::all_of(
                emptyOutput,
                [](double sample) { return sample == 0.0; }),
        "empty Sound collection should render realtime silence without allocation");

    auto nestedGraph = compile(
        makeNestedSoundVariableSelectorDocument(), settings);
    require(nestedGraph.preparedSoundVariables().cells.size() == 1
            && nestedGraph.preparedSoundVariables().cells.front()
                   .identity.definitionId == "wrapper"
            && nestedGraph.preparedSoundVariables().cells.front()
                   .identity.instancePath
                == std::vector<std::string>{"wrapper1"},
        "nested selector should retain exact definition and instance-path authority");
    talas::runtime::OfflineRenderSession nestedOffline(nestedGraph);
    const auto nestedExpected = nestedOffline.render(16);
    talas::runtime::RealtimeRenderSession nestedRealtime(nestedGraph);
    std::array<double, 16> nestedOutput{};
    allocations = 0;
    require(nestedExpected.ok(),
        "nested selector should render offline");
    require(nestedRealtime.ready(), std::string(nestedRealtime.error()));
    require(renderAndCount(nestedRealtime, nestedOutput, allocations),
        "nested selector should render in prepared realtime");
    require(allocations == 0,
        "nested selector callback should not allocate: "
            + std::to_string(allocations));
    bool nestedAudible = false;
    for (std::size_t frame = 0; frame < nestedOutput.size(); ++frame)
    {
        requireNear(
            nestedOutput[frame], nestedExpected.mono[frame], 1.0e-12,
            "nested offline and realtime selector output should match");
        nestedAudible = nestedAudible
            || std::abs(nestedOutput[frame]) > 1.0e-4;
    }
    require(nestedAudible,
        "nested selector should render its exact initially selected branch");
}

void testC74SoundVariableSelectorRollsBackPreparedFailureWithoutAllocations(int candidateProfile = 0)
{
    auto document = makeSoundVariableSelectorDocument(
        "talas.variable",
        talas::project::ProjectSoundVariableKind::Sound,
        {"toneA", "toneB"});
    if (candidateProfile != 0)
    {
        auto& definition = document.soundDefinitions.back();
        if (candidateProfile == 1)
            definition.graph.nodes.push_back(node("delay", "talas.delayWithFeedback",
                {{"delay", "250 ms"}, {"feedback", "0.5"}, {"mix", "1"}}));
        else
        {
            definition.graph.nodes.push_back(node("delay", "talas.frequencyScale",
                {{"frequencyScale", candidateProfile == 2 ? "1" : "1.5"},
                    {"maxScale", candidateProfile == 2 ? "1" : "2"},
                    resourceParameter("window", "Private"), {"delay", "0.25"}}));
            // 4 hz, as a fraction of half the sample rate.
            definition.graph.nodes.push_back(node("tracker", "talas.constant", {{"value", "4 / 64"}}));
            definition.graph.connections.push_back(connection("tracker", "value", "delay", "freqTracker"));
        }
        definition.graph.connections.push_back(connection("osc", "audioOut", "delay", "audioIn"));
        definition.outputs = {{"audioOut", talas::core::PortType::Audio, "delay", "audioOut"}};
    }
    document.graph.nodes.push_back(node(
        "formants",
        "talas.twoFormantElement",
        {{"formant1", "8 hz"},
         {"bandwidth1", "4 hz"},
         {"scale1", "1"},
         {"formant2", "16 hz"},
         {"bandwidth2", "4 hz"},
         {"scale2", "0.5"}}));
    document.graph.nodes.push_back(node(
        "formantControl", "talas.constant", {{"value", "!C74Formant"}}));
    std::erase_if(
        document.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "selector" && edge.toNode == "out";
        });
    document.graph.connections.push_back(connection(
        "selector", "audioOut", "formants", "audioIn"));
    document.graph.connections.push_back(connection(
        "formantControl", "value", "formants", "formant1"));
    document.graph.connections.push_back(connection(
        "formants", "audioOut", "out", "audioIn"));

    talas::runtime::RenderSettings settings{128.0, 16};
    settings.eventValues.push_back({
        "C74Formant", 8.0, talas::expr::ValueDomain::Scalar});
    auto graph = compile(document, settings);
    require(
        graph.preparedSoundVariables().cells.size() == 1,
        "C74 prepared rollback fixture should compile one exact selector cell");
    const auto& cell = graph.preparedSoundVariables().cells.front();
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(
        candidate.ready() && reference.ready(),
        "C74 selector and candidate closure should prepare as transactional checked-DSP predecessors");

    std::array<double, 16> candidateBlock{};
    std::array<double, 16> referenceBlock{};
    std::size_t allocations = 0;
    require(
        renderAndCount(candidate, candidateBlock, allocations)
            && allocations == 0,
        "C74 candidate should establish selector and branch state without allocation");
    allocations = 0;
    require(
        renderAndCount(reference, referenceBlock, allocations)
            && allocations == 0 && candidateBlock == referenceBlock,
        "C74 reference should establish identical selector and branch state");

    if (candidateProfile == 3)
    {
        for (int block = 0; block < 80; ++block)
        {
            require(renderAndCount(candidate, candidateBlock, allocations) && allocations == 0,
                "active Frequency Scale Sound candidate must fill its spectral and delay history");
            require(renderAndCount(reference, referenceBlock, allocations) && allocations == 0
                    && candidateBlock == referenceBlock,
                "active Sound candidate must match uninterrupted history before selection");
        }
    }
    const auto scheduleToneB = [&](talas::runtime::RealtimeRenderSession& session) {
        const auto target = session.soundVariableTargetIndex(
            cell.identity, "toneB");
        require(target.has_value(),
            "C74 rollback fixture should resolve the exact second candidate");
        talas::runtime::TypedEventPayload payload{};
        payload.soundVariable = {target->selectedOrdinal};
        const std::array events{
            talas::runtime::PreparedTypedEvent{
                talas::runtime::TypedEventKind::SoundVariableAssignment,
                {
                    talas::runtime::TypedEventTargetKind::SoundVariable,
                    target->index,
                    1,
                    1,
                },
                0,
                1,
                payload,
            },
        };
        std::array<talas::runtime::RealtimeTypedEventDispatchResult, 1>
            results{};
        require(
            session.scheduleTypedEvents(events, results)
                && results.front()
                    == talas::runtime::RealtimeTypedEventDispatchResult::Handled,
            "C74 rollback fixture should schedule the same exact selection");
    };
    scheduleToneB(candidate);
    scheduleToneB(reference);
    require(
        candidate.scheduleEventValue(
            "C74Formant",
            64.0,
            talas::expr::ValueDomain::Scalar,
            8),
        "C74 rollback fixture should schedule a later invalid formant");

    candidateBlock.fill(1.0);
    allocations = 0;
    require(
        !renderAndCount(candidate, candidateBlock, allocations)
            && allocations == 0
            && candidateBlock == std::array<double, 16>{},
        "C74 late prepared failure should publish no audio or allocate");
    require(
        candidate.updateEventValue(
            "C74Formant", 8.0, talas::expr::ValueDomain::Scalar),
        "C74 prepared formant authority should recover after rejection");

    allocations = 0;
    require(
        renderAndCount(candidate, candidateBlock, allocations)
            && allocations == 0,
        "C74 rejected selector callback should retry without allocation");
    allocations = 0;
    require(
        renderAndCount(reference, referenceBlock, allocations)
            && allocations == 0
            && candidateBlock == referenceBlock,
        "C74 rejected callback must restore both candidate phases and all four selector fields");
    if (candidateProfile != 0)
    {
        bool audible = false;
        for (int block = 0; block < 3; ++block)
        {
            allocations = 0;
            require(renderAndCount(candidate, candidateBlock, allocations) && allocations == 0,
                "checkpointed selector delay must continue after recovered selection without allocation");
            allocations = 0;
            require(renderAndCount(reference, referenceBlock, allocations) && allocations == 0
                    && candidateBlock == referenceBlock,
                "selector delay ring/cursor and oscillator state must match uninterrupted continuation");
            audible |= std::ranges::any_of(candidateBlock, [](double sample) { return std::abs(sample) > 1e-8; });
        }
        require(audible, "selector rollback must exercise the delayed audible branch after its history fills");
        candidate.resetTransport();
        reference.resetTransport();
        for (int block = 0; block < 2; ++block)
        {
            allocations = 0;
            require(renderAndCount(candidate, candidateBlock, allocations) && allocations == 0,
                "selected delay branch must reset without allocation");
            allocations = 0;
            require(renderAndCount(reference, referenceBlock, allocations) && allocations == 0
                    && candidateBlock == referenceBlock && candidateBlock == std::array<double, 16>{},
                "selector reset must discard delay and filter history while retaining the chosen branch");
        }
    }

}

void testC74SoundVariableSelectorResetPreservesSelectionWithoutCrossfadeTail()
{
    const auto run = [](
                         std::string typeId,
                         talas::project::ProjectSoundVariableKind kind,
                         std::string_view context) {
        auto document = makeSoundVariableSelectorDocument(
            typeId, kind, {"toneA", "toneB"});
        auto selectedDocument = document;
        selectedDocument.soundVariableLibrary.variables.front()
            .initialSelectedOrdinal = 1;
        const auto settings = talas::runtime::RenderSettings{128.0, 16};
        auto graph = compile(document, settings);
        auto selectedGraph = compile(selectedDocument, settings);
        const auto selector = std::ranges::find(
            graph.plan().steps,
            std::string_view{typeId},
            &talas::runtime::CompileStep::typeId);
        require(
            selector != graph.plan().steps.end()
                && selector->supportsReset,
            std::string{context}
                + " descriptor and compile step should expose exact reset authority");
        const auto& cell = graph.preparedSoundVariables().cells.front();

        talas::runtime::RealtimeRenderSession session(graph);
        talas::runtime::RealtimeRenderSession reference(selectedGraph);
        require(
            session.ready() && reference.ready(),
            std::string{context}
                + " reset fixtures should prepare exact selector sessions");
        std::array<double, 16> scratch{};
        std::size_t allocations = 0;
        require(
            renderAndCount(session, scratch, allocations)
                && allocations == 0,
            std::string{context}
                + " reset fixture should initialize its first branch");

        const auto target = session.soundVariableTargetIndex(
            cell.identity, "toneB");
        require(target.has_value(),
            std::string{context}
                + " reset fixture should resolve its second branch");
        talas::runtime::TypedEventPayload payload{};
        payload.soundVariable = {target->selectedOrdinal};
        const std::array events{
            talas::runtime::PreparedTypedEvent{
                talas::runtime::TypedEventKind::SoundVariableAssignment,
                {
                    talas::runtime::TypedEventTargetKind::SoundVariable,
                    target->index,
                    1,
                    1,
                },
                0,
                1,
                payload,
            },
        };
        std::array<talas::runtime::RealtimeTypedEventDispatchResult, 1>
            results{};
        require(
            session.scheduleTypedEvents(events, results)
                && renderAndCount(session, scratch, allocations)
                && allocations == 0,
            std::string{context}
                + " reset fixture should enter its active crossfade");
        const auto beforeReset = session.preparedSoundVariableValues();
        require(
            beforeReset.publicationValid
                && beforeReset.values.size() == 1
                && beforeReset.values.front().selectedDefinitionId
                    == "toneB",
            std::string{context}
                + " reset fixture should publish its live selected Sound");

        session.resetTransport();
        const auto afterReset = session.preparedSoundVariableValues();
        std::array<double, 16> actual{};
        std::array<double, 16> expected{};
        allocations = 0;
        require(
            renderAndCount(session, actual, allocations)
                && allocations == 0,
            std::string{context}
                + " reset continuation should render without allocation");
        allocations = 0;
        require(
            renderAndCount(reference, expected, allocations)
                && allocations == 0,
            std::string{context}
                + " selected-at-construction reference should render without allocation");
        require(
            afterReset.publicationValid
                && afterReset.values.size() == 1
                && afterReset.values.front().selectedDefinitionId
                    == "toneB",
            std::string{context}
                + " transport reset must preserve the live selected Sound cell");
        require(
            actual == expected,
            std::string{context}
                + " transport reset must discard the stale previous branch and start directly on the selected Sound");
    };

    run(
        "talas.variable",
        talas::project::ProjectSoundVariableKind::Sound,
        "C74 Variable");
    run(
        "talas.soundCollectionVariable",
        talas::project::ProjectSoundVariableKind::SoundCollection,
        "C74 Sound Collection Variable");
}

void testC74SoundVariableSelectorsRejectForgedPreparedAuthority()
{
    const auto settings = talas::runtime::RenderSettings{128.0, 16};
    const auto compiled = compile(
        makeSoundVariableSelectorDocument(
            "talas.variable",
            talas::project::ProjectSoundVariableKind::Sound,
            {"toneA", "toneB"}),
        settings);
    const auto findSelector = [](talas::runtime::RuntimePlan& plan) {
        return std::ranges::find(
            plan.steps,
            std::string_view{"talas.variable"},
            &talas::runtime::CompileStep::typeId);
    };
    const auto requireRejected = [&](
                                     talas::runtime::RuntimePlan plan,
                                     std::string_view context) {
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), compiled.renderSettings()});
        require(
            !session.ready(),
            std::string{context}
                + " should reject forged C74 selector authority");
    };

    {
        auto plan = compiled.plan();
        auto selector = findSelector(plan);
        require(selector != plan.steps.end(),
            "C74 reset mutation should expose Variable");
        selector->supportsReset = false;
        requireRejected(std::move(plan), "C74 missing reset authority");
    }
    {
        auto plan = compiled.plan();
        auto selector = findSelector(plan);
        require(selector != plan.steps.end(),
            "C74 support mutation should expose Variable");
        selector->preparedRealtimeSupport =
            talas::core::ExecutionSupport::Supported;
        requireRejected(std::move(plan), "C74 forged full support");
    }
    {
        auto plan = compiled.plan();
        auto selector = findSelector(plan);
        require(selector != plan.steps.end(),
            "C74 type-kind mutation should expose Variable");
        selector->typeId = "talas.soundCollectionVariable";
        requireRejected(std::move(plan), "C74 forged selector type-kind pair");
    }
    {
        auto plan = compiled.plan();
        auto selector = findSelector(plan);
        require(
            selector != plan.steps.end()
                && selector->parameters.size() == 1,
            "C74 parameter mutation should expose one Variable parameter");
        selector->parameters.front().text.reset();
        requireRejected(std::move(plan), "C74 missing variableId text payload");
    }
    {
        auto plan = compiled.plan();
        auto selector = findSelector(plan);
        require(
            selector != plan.steps.end()
                && selector->inputs.size() == 2
                && selector->inputLatencyFrames.size() == 2,
            "C74 input-order mutation should expose two candidates");
        std::swap(selector->inputs[0], selector->inputs[1]);
        std::swap(
            selector->inputLatencyFrames[0],
            selector->inputLatencyFrames[1]);
        requireRejected(std::move(plan), "C74 reordered candidate inputs");
    }
    {
        auto plan = compiled.plan();
        auto selector = findSelector(plan);
        require(
            selector != plan.steps.end()
                && selector->inputs.size() == 2,
            "C74 source-identity mutation should expose two candidates");
        std::swap(
            selector->inputs[0].sourceNodeId,
            selector->inputs[1].sourceNodeId);
        std::swap(
            selector->inputs[0].sourcePortId,
            selector->inputs[1].sourcePortId);
        std::swap(
            selector->inputs[0].sourceScopeId,
            selector->inputs[1].sourceScopeId);
        std::swap(
            selector->inputs[0].bufferIndex,
            selector->inputs[1].bufferIndex);
        requireRejected(
            std::move(plan),
            "C74 swapped candidate source-definition authority");
    }
    {
        auto plan = compiled.plan();
        auto selector = findSelector(plan);
        require(
            selector != plan.steps.end()
                && selector->inputs.size() == 2,
            "C74 coordinated source/path mutation should expose two candidates");
        const auto firstSource = std::ranges::find_if(
            plan.steps,
            [&](const auto& step) {
                return step.nodeId == selector->inputs[0].sourceNodeId
                    && step.scopeId == selector->inputs[0].sourceScopeId;
            });
        const auto secondSource = std::ranges::find_if(
            plan.steps,
            [&](const auto& step) {
                return step.nodeId == selector->inputs[1].sourceNodeId
                    && step.scopeId == selector->inputs[1].sourceScopeId;
            });
        require(
            firstSource != plan.steps.end()
                && secondSource != plan.steps.end(),
            "C74 coordinated source/path mutation should expose both producer steps");
        std::swap(
            selector->inputs[0].sourceNodeId,
            selector->inputs[1].sourceNodeId);
        std::swap(
            selector->inputs[0].sourcePortId,
            selector->inputs[1].sourcePortId);
        std::swap(
            selector->inputs[0].sourceScopeId,
            selector->inputs[1].sourceScopeId);
        std::swap(
            selector->inputs[0].bufferIndex,
            selector->inputs[1].bufferIndex);
        std::swap(
            firstSource->structuralSourcePath,
            secondSource->structuralSourcePath);
        requireRejected(
            std::move(plan),
            "C74 coherently swapped candidate source/path authority");
    }
    {
        auto plan = compiled.plan();
        auto selector = findSelector(plan);
        require(
            selector != plan.steps.end()
                && selector->inputLatencyFrames.size() == 2,
            "C74 latency mutation should expose candidate latency");
        selector->inputLatencyFrames[0] = 1;
        requireRejected(std::move(plan), "C74 forged candidate input latency");
    }
    {
        auto plan = compiled.plan();
        auto selector = findSelector(plan);
        require(selector != plan.steps.end(),
            "C74 scope mutation should expose Variable");
        selector->eventValueScopeId += 1;
        requireRejected(std::move(plan), "C74 forged Event Value scope");
    }
    {
        auto plan = compiled.plan();
        auto selector = findSelector(plan);
        require(selector != plan.steps.end(),
            "C74 structural-path mutation should expose Variable");
        selector->structuralSourcePath += ".forged";
        requireRejected(std::move(plan), "C74 forged structural path");
    }
    {
        auto plan = compiled.plan();
        auto selector = findSelector(plan);
        require(selector != plan.steps.end(),
            "C74 ancillary mutation should expose Variable");
        selector->preparedSpectralFrameSize = 16;
        requireRejected(std::move(plan), "C74 forged spectral metadata");
    }
    {
        auto plan = compiled.plan();
        auto selector = findSelector(plan);
        require(selector != plan.steps.end(),
            "C74 output-capacity mutation should expose Variable");
        const auto output = std::ranges::find_if(
            plan.buffers,
            [&](const talas::runtime::BufferSpec& buffer) {
                return buffer.nodeId == selector->nodeId
                    && buffer.scopeId == selector->scopeId
                    && buffer.portId == "audioOut";
            });
        require(output != plan.buffers.end(),
            "C74 output-capacity mutation should expose audioOut");
        output->frames = 1;
        requireRejected(std::move(plan), "C74 undersized output buffer");
    }
    {
        auto plan = compiled.plan();
        auto zeroAmplitude = plan.steps.end();
        for (auto step = plan.steps.begin(); step != plan.steps.end(); ++step)
        {
            const auto amplitude = std::ranges::find(
                step->parameters,
                std::string_view{"amplitude"},
                &talas::runtime::ParameterValue::id);
            if (step->typeId == "talas.oscillator"
                && amplitude != step->parameters.end()
                && amplitude->value == 0.0)
            {
                zeroAmplitude = step;
                break;
            }
        }
        require(
            zeroAmplitude != plan.steps.end(),
            "C74 signed-zero mutation should expose a silent candidate oscillator");
        const auto amplitude = std::ranges::find(
            zeroAmplitude->parameters,
            std::string_view{"amplitude"},
            &talas::runtime::ParameterValue::id);
        amplitude->value = -0.0;
        requireRejected(
            std::move(plan),
            "C74 forged candidate parameter signed zero");
    }
    {
        auto feedbackDocument = makeSoundVariableSelectorDocument(
            "talas.variable",
            talas::project::ProjectSoundVariableKind::Sound,
            {"toneA", "toneB"});
        auto& feedbackDefinition = feedbackDocument.soundDefinitions.back();
        feedbackDefinition.graph.nodes = {
            node(
                "osc",
                "talas.oscillator",
                {{"frequency", "1 hz"}, {"amplitude", "1"}}),
            node(
                "sink",
                "talas.feedbackLoopInput",
                {textParameter("connection", "candidateLoop")}),
            node(
                "mix",
                "talas.mixer",
                {{"gain1", "1"}, {"gain2", "0.5"}}),
            node(
                "feedback",
                "talas.feedbackLoopOutput",
                {textParameter("connection", "candidateLoop"),
                 {"delay", "0 s"}}),
        };
        feedbackDefinition.graph.connections = {
            connection("osc", "audioOut", "mix", "in1"),
            connection("feedback", "audioOut", "mix", "in2"),
            connection("mix", "audioOut", "sink", "audioIn"),
        };
        feedbackDefinition.outputs = {
            {"audioOut", talas::core::PortType::Audio, "mix", "audioOut"},
        };
        const auto feedbackGraph = compile(feedbackDocument, settings);
        require(
            feedbackGraph.plan().feedbackPairs.size() == 1,
            "C74 feedback candidate should expose one compiler-derived pair");
        talas::runtime::RealtimeRenderSession authentic(feedbackGraph);
        require(
            authentic.ready(),
            "C74 feedback candidate should admit its authentic execution plan");
        auto plan = feedbackGraph.plan();
        ++plan.feedbackPairs.front().delayFrames;
        talas::runtime::RealtimeRenderSession forged(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), feedbackGraph.renderSettings()});
        require(
            !forged.ready(),
            "C74 candidate should reject a forged plan-side feedback delay");
    }
}

void testC74SoundVariableSelectorAcceptsFrequencyScaleCandidateClosure()
{
    auto document = makeSoundVariableSelectorDocument(
        "talas.variable",
        talas::project::ProjectSoundVariableKind::Sound,
        {"toneA", "toneB"});
    auto& frequencyCandidate = document.soundDefinitions.back();
    frequencyCandidate.graph.nodes = {
        node(
            "carrier", "talas.oscillator",
            {{"frequency", "1 hz"}, {"amplitude", "1"}}),
        node(
            "delay", "talas.frequencyScale",
            {{"frequencyScale", "1"}, {"maxScale", "1"},
             resourceParameter("window", "Private"), {"delay", "0.25"}}),
        node("tracker", "talas.constant", {{"value", "440"}}),
    };
    frequencyCandidate.graph.connections = {
        connection("carrier", "audioOut", "delay", "audioIn"),
        connection("tracker", "value", "delay", "freqTracker"),
    };
    frequencyCandidate.outputs = {
        {"audioOut", talas::core::PortType::Audio, "delay", "audioOut"},
    };
    const auto standalone = compile(makeFrequencyScaleDocument({
        {"frequencyScale", "1"}, {"maxScale", "1"}, resourceParameter("window", "Private"), {"delay", "0.25"},
    }), talas::runtime::RenderSettings{128.0, 16});
    require(talas::runtime::RealtimeRenderSession(standalone).ready(),
        "Frequency Scale candidate fixture must retain valid standalone admission");
    const auto graph = compile(
        document, talas::runtime::RenderSettings{128.0, 16});
    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        "C74 selector must admit a Frequency Scale closure with its general callback checkpoint");
}

void testMidiVoiceSoundVariableSelectorOwnsExactSlotState()
{
    auto document = makePreparedMidiVoiceDocument(1);
    std::erase_if(
        document.graph.nodes,
        [](const auto& candidate) { return candidate.instanceId == "osc"; });
    std::erase_if(
        document.graph.connections,
        [](const auto& candidate) {
            return candidate.fromNode == "osc"
                && candidate.toNode == "midi";
        });
    document.graph.nodes.push_back(node(
        "voiceSelector",
        "talas.variable",
        {textParameter("variableId", "voiceSound")}));
    document.graph.connections.push_back(connection(
        "voiceSelector", "audioOut", "midi", "audioIn"));
    document.soundDefinitions = {
        makeSelectorTone("toneA", "0"),
        makeSelectorTone("toneB", "1"),
    };
    talas::project::ProjectSoundVariableDeclaration declaration;
    declaration.variableId = "voiceSound";
    declaration.displayName = "Voice Sound";
    declaration.candidateDefinitionIds = {"toneA", "toneB"};
    declaration.snapshotEligible = false;
    declaration.owner.kind =
        talas::project::ProjectVariableOwnerKind::MidiVoice;
    declaration.owner.nodeId = "midi";
    document.soundVariableLibrary.variables = {std::move(declaration)};

    auto graph = compile(document, preparedMidiVoiceSettings());
    require(graph.preparedSoundVariables().cells.size() == 1
            && graph.plan().midiVoices.size() == 1
            && graph.plan().midiVoices.front().voices.size() == 1,
        "voice selector should prepare one exact cell and branch set per slot");
    const auto& cell = graph.preparedSoundVariables().cells.front();
    require(cell.identity.ownerKind
                == talas::project::ProjectVariableOwnerKind::MidiVoice
            && cell.identity.voiceOrdinal
                == std::optional<std::uint16_t>{0},
        "voice selector cell should retain exact slot identity");

    {
        auto plan = graph.plan();
        auto selector = std::ranges::find(
            plan.steps,
            std::string_view{"talas.variable"},
            &talas::runtime::CompileStep::typeId);
        require(
            selector != plan.steps.end()
                && selector->inputs.size() == 2,
            "voice candidate ancestry mutation should expose two selector inputs");
        auto firstSource = std::ranges::find_if(
            plan.steps,
            [&](const auto& step) {
                return step.nodeId == selector->inputs[0].sourceNodeId
                    && step.scopeId == selector->inputs[0].sourceScopeId;
            });
        auto secondSource = std::ranges::find_if(
            plan.steps,
            [&](const auto& step) {
                return step.nodeId == selector->inputs[1].sourceNodeId
                    && step.scopeId == selector->inputs[1].sourceScopeId;
            });
        require(
            firstSource != plan.steps.end()
                && secondSource != plan.steps.end(),
            "voice candidate ancestry mutation should expose both producer steps");
        const auto renameSource = [&](
                                      auto& input,
                                      auto& source,
                                      std::string nodeId) {
            require(
                input.bufferIndex < plan.buffers.size(),
                "voice candidate ancestry mutation should retain its source buffer");
            plan.buffers[input.bufferIndex].nodeId = nodeId;
            input.sourceNodeId = nodeId;
            source.nodeId = std::move(nodeId);
        };
        const auto settingsForAuthorityPlan = [&](
                                                  const auto& authorityPlan) {
            auto settings = graph.renderSettings();
            settings.preparedSoundVariableAuthorityPlan =
                std::make_shared<const talas::runtime::RuntimePlan>(
                    authorityPlan);
            return settings;
        };
        const auto firstCanonicalNodeId = firstSource->nodeId;
        const auto secondCanonicalNodeId = secondSource->nodeId;
        renameSource(
            selector->inputs[0],
            *firstSource,
            firstCanonicalNodeId + "_1");
        renameSource(
            selector->inputs[1],
            *secondSource,
            secondCanonicalNodeId + "_2");
        talas::runtime::RealtimeRenderSession collisionSuffixSession(
            talas::runtime::PreparedRuntimeGraph{
                plan, settingsForAuthorityPlan(plan)});
        require(
            collisionSuffixSession.ready(),
            "voice selector should accept canonical generated-id collision suffixes");
        renameSource(
            selector->inputs[0],
            *firstSource,
            firstCanonicalNodeId + "_184467440737095516160");
        talas::runtime::RealtimeRenderSession overflowSuffixSession(
            talas::runtime::PreparedRuntimeGraph{
                plan, settingsForAuthorityPlan(plan)});
        require(
            !overflowSuffixSession.ready(),
            "voice selector should reject a generated-id collision suffix overflow");
        renameSource(
            selector->inputs[0],
            *firstSource,
            firstCanonicalNodeId + "_" + std::string(4096, '1'));
        talas::runtime::RealtimeRenderSession oversizedNodeIdSession(
            talas::runtime::PreparedRuntimeGraph{
                plan, settingsForAuthorityPlan(plan)});
        require(
            !oversizedNodeIdSession.ready(),
            "voice selector should reject a generated node ID beyond compiler capacity");
        renameSource(
            selector->inputs[0],
            *firstSource,
            "__kc_nested_27_$sound-variable-candidate:1_27_$sound-variable-candidate:0_3_osc");
        renameSource(
            selector->inputs[1],
            *secondSource,
            "__kc_nested_27_$sound-variable-candidate:0_27_$sound-variable-candidate:1_3_osc");
        std::swap(
            selector->inputs[0].sourceNodeId,
            selector->inputs[1].sourceNodeId);
        std::swap(
            selector->inputs[0].sourcePortId,
            selector->inputs[1].sourcePortId);
        std::swap(
            selector->inputs[0].sourceScopeId,
            selector->inputs[1].sourceScopeId);
        std::swap(
            selector->inputs[0].bufferIndex,
            selector->inputs[1].bufferIndex);
        std::swap(
            firstSource->structuralSourcePath,
            secondSource->structuralSourcePath);
        talas::runtime::RealtimeRenderSession forged(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), graph.renderSettings()});
        require(
            !forged.ready(),
            "voice selector should reject an ancestor-marker source/path forgery");
    }

    {
        auto plan = graph.plan();
        auto selector = std::ranges::find(
            plan.steps,
            std::string_view{"talas.variable"},
            &talas::runtime::CompileStep::typeId);
        require(
            selector != plan.steps.end()
                && selector->inputs.size() == 2,
            "voice coherent identity swap should expose two selector inputs");
        auto firstSource = std::ranges::find_if(
            plan.steps,
            [&](const auto& step) {
                return step.nodeId == selector->inputs[0].sourceNodeId
                    && step.scopeId == selector->inputs[0].sourceScopeId;
            });
        auto secondSource = std::ranges::find_if(
            plan.steps,
            [&](const auto& step) {
                return step.nodeId == selector->inputs[1].sourceNodeId
                    && step.scopeId == selector->inputs[1].sourceScopeId;
            });
        require(
            firstSource != plan.steps.end()
                && secondSource != plan.steps.end()
                && selector->inputs[0].bufferIndex < plan.buffers.size()
                && selector->inputs[1].bufferIndex < plan.buffers.size(),
            "voice coherent identity swap should expose both source branches");
        std::swap(firstSource->nodeId, secondSource->nodeId);
        std::swap(
            plan.buffers[selector->inputs[0].bufferIndex].nodeId,
            plan.buffers[selector->inputs[1].bufferIndex].nodeId);
        std::swap(
            selector->inputs[0].bufferIndex,
            selector->inputs[1].bufferIndex);
        std::swap(
            firstSource->structuralSourcePath,
            secondSource->structuralSourcePath);
        std::swap(
            firstSource->structuralScopeId,
            secondSource->structuralScopeId);
        talas::runtime::RealtimeRenderSession forged(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), graph.renderSettings()});
        require(
            !forged.ready(),
            "voice selector should reject a coherent canonical candidate identity swap");
    }

    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 60, 127},
                0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
        "voice selector fixture should admit its first note");
    std::array<double, 16> output{};
    std::size_t allocations = 0;
    require(renderAndCount(session, output, allocations),
        "initial voice-owned branch should render");
    require(allocations == 0,
        "initial voice-owned branch should not allocate: "
            + std::to_string(allocations));
    require(std::ranges::all_of(
                output,
                [](double sample) { return sample == 0.0; }),
        "initial voice-owned zero branch should render silently");

    const auto target = session.voiceSoundVariableTargetIndex(
        cell.identity, "toneB", 1);
    require(target.has_value(),
        "live voice generation should resolve its exact second branch");
    talas::runtime::TypedEventPayload payload{};
    payload.soundVariable = {target->selectedOrdinal};
    const std::array events{
        talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::SoundVariableAssignment,
            {
                talas::runtime::TypedEventTargetKind::SoundVariable,
                target->index,
                1,
                1,
                1,
            },
            0,
            1,
            payload,
        },
    };
    std::array<talas::runtime::RealtimeTypedEventDispatchResult, 1> results{};
    require(session.scheduleTypedEvents(events, results),
        "voice selector assignment should queue for the exact live generation");
    bool heardSelectedBranch = false;
    for (std::size_t block = 0; block < 10; ++block)
    {
        require(renderAndCount(session, output, allocations)
                && allocations == 0,
            "voice selector crossfade should remain callback-allocation-free");
        heardSelectedBranch = heardSelectedBranch
            || std::ranges::any_of(
                output,
                [](double sample) { return std::abs(sample) > 1.0e-4; });
    }
    require(heardSelectedBranch,
        "voice-owned selector should audibly render its chosen branch");

    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 61, 127},
                0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled
            && renderAndCount(session, output, allocations)
            && allocations == 0
            && std::ranges::all_of(
                output,
                [](double sample) { return sample == 0.0; }),
        "voice slot reuse should reset the exact Sound selection and discard the old crossfade tail");

    talas::runtime::RealtimeRenderSession control(graph);
    talas::runtime::RealtimeRenderSession rejected(graph);
    require(control.ready() && rejected.ready(),
        "crossfade rollback fixtures should prepare");
    const auto beginCrossfade = [&](talas::runtime::RealtimeRenderSession& candidate) {
        std::array<double, 16> scratch{};
        std::size_t callbackAllocations = 0;
        require(candidate.scheduleMidiNote(
                    {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 60, 127},
                    0)
                == talas::runtime::RealtimeMidiDispatchResult::Handled
                && renderAndCount(candidate, scratch, callbackAllocations)
                && callbackAllocations == 0,
            "crossfade rollback fixture should activate generation one");
        const auto selected = candidate.voiceSoundVariableTargetIndex(
            cell.identity, "toneB", 1);
        require(selected.has_value(),
            "crossfade rollback fixture should resolve its second branch");
        talas::runtime::TypedEventPayload selectedPayload{};
        selectedPayload.soundVariable = {selected->selectedOrdinal};
        const std::array selectEvents{
            talas::runtime::PreparedTypedEvent{
                talas::runtime::TypedEventKind::SoundVariableAssignment,
                {
                    talas::runtime::TypedEventTargetKind::SoundVariable,
                    selected->index,
                    1,
                    1,
                    1,
                },
                0,
                1,
                selectedPayload,
            },
        };
        std::array<talas::runtime::RealtimeTypedEventDispatchResult, 1>
            selectResults{};
        require(candidate.scheduleTypedEvents(selectEvents, selectResults)
                && renderAndCount(candidate, scratch, callbackAllocations)
                && callbackAllocations == 0,
            "crossfade rollback fixture should enter the prepared 128-frame transition");
    };
    beginCrossfade(control);
    beginCrossfade(rejected);

    const auto rejectedTarget = rejected.voiceSoundVariableTargetIndex(
        cell.identity, "toneA", 1);
    require(rejectedTarget.has_value(),
        "rejected crossfade fixture should resolve the old exact generation");
    talas::runtime::TypedEventPayload rejectedSelection{};
    rejectedSelection.soundVariable = {rejectedTarget->selectedOrdinal};
    talas::runtime::TypedEventPayload rejectedSteal{};
    rejectedSteal.midiNote = {1, 61, 127};
    const std::array rejectedBatch{
        talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::SoundVariableAssignment,
            {
                talas::runtime::TypedEventTargetKind::SoundVariable,
                rejectedTarget->index,
                1,
                1,
                1,
            },
            0,
            2,
            rejectedSelection,
        },
        talas::runtime::PreparedTypedEvent{
            talas::runtime::TypedEventKind::MidiNoteOn,
            {talas::runtime::TypedEventTargetKind::MidiVoice, 1, 1, 1},
            0,
            3,
            rejectedSteal,
        },
    };
    std::array<talas::runtime::RealtimeTypedEventDispatchResult, 2>
        rejectedResults{};
    require(rejected.scheduleTypedEvents(rejectedBatch, rejectedResults)
            && !rejected.render(output),
        "stale assignment sharing a steal should reject during an active crossfade");

    std::array<double, 16> expectedContinuation{};
    std::array<double, 16> actualContinuation{};
    allocations = 0;
    require(renderAndCount(control, expectedContinuation, allocations)
            && allocations == 0,
        "control crossfade should continue without callback allocation");
    allocations = 0;
    require(renderAndCount(rejected, actualContinuation, allocations)
            && allocations == 0,
        "rolled-back crossfade should continue without callback allocation");
    for (std::size_t frame = 0; frame < expectedContinuation.size(); ++frame)
    {
        requireNear(
            actualContinuation[frame], expectedContinuation[frame], 1.0e-12,
            "rejected MIDI batch should restore the exact in-flight Sound crossfade state");
    }
}

void testOfflineMidiVoiceTransactionsMatchAcrossRenderPartitions()
{
    auto document = makePreparedMidiVoiceDocument(
        1,
        1,
        0,
        127,
        "!KeyDown * !KeyVelocity * @voiceGain");
    document.expressionLanguage =
        talas::expr::ExpressionLanguageVersion::VariablesV1;
    talas::project::ProjectVariableDeclaration variable;
    variable.variableId = "voiceGain";
    variable.displayName = "Voice gain";
    variable.initialValue = 0.25;
    variable.snapshotEligible = false;
    variable.owner.kind =
        talas::project::ProjectVariableOwnerKind::MidiVoice;
    variable.owner.nodeId = "midi";
    document.variableLibrary.variables.push_back(variable);
    auto graph = compile(document, preparedMidiVoiceSettings(8));
    require(graph.preparedVariables().cells.size() == 1,
        "offline voice fixture should prepare one exact cell");
    const auto& cell = graph.preparedVariables().cells.front();

    const auto note = [](
        std::uint64_t frame,
        std::uint64_t batch,
        std::uint64_t sequence,
        talas::runtime::OfflineMidiVoiceEventKind kind,
        std::uint8_t pitch,
        std::uint8_t velocity) {
        talas::runtime::OfflineMidiVoiceEvent event;
        event.frame = frame;
        event.batchId = batch;
        event.sequence = sequence;
        event.kind = kind;
        event.channel = 1;
        event.note = pitch;
        event.velocity = velocity;
        return event;
    };
    const auto assignment = [&cell](
        std::uint64_t frame,
        std::uint64_t batch,
        std::uint64_t sequence,
        std::uint64_t generation,
        double value) {
        talas::runtime::OfflineMidiVoiceEvent event;
        event.frame = frame;
        event.batchId = batch;
        event.sequence = sequence;
        event.kind =
            talas::runtime::OfflineMidiVoiceEventKind::VariableAssignment;
        event.target = cell.identity;
        event.voiceGeneration = generation;
        event.value = value;
        event.domain = cell.domain;
        return event;
    };
    const std::array events{
        note(0, 1, 1,
            talas::runtime::OfflineMidiVoiceEventKind::NoteOn,
            60, 127),
        assignment(0, 1, 2, 1, 0.75),
        note(16, 2, 3,
            talas::runtime::OfflineMidiVoiceEventKind::NoteOn,
            72, 127),
        assignment(16, 2, 4, 2, 0.5),
        note(28, 3, 5,
            talas::runtime::OfflineMidiVoiceEventKind::NoteOff,
            72, 0),
    };

    talas::runtime::OfflineRenderSession whole(graph);
    require(whole.scheduleMidiVoiceEvents(events),
        "offline voice stream should prepare exact generations");
    const auto wholeResult = whole.render(32);
    require(wholeResult.ok() && wholeResult.mono.size() == 32,
        "offline voice stream should render in one request");
    require(std::ranges::any_of(
                std::span<const double>(wholeResult.mono).subspan(5, 11),
                [](double sample) { return std::abs(sample) > 1.0e-6; }),
        "same-frame generation-one assignment should produce audible voice output");
    require(std::ranges::any_of(
                std::span<const double>(wholeResult.mono).subspan(21, 7),
                [](double sample) { return std::abs(sample) > 1.0e-6; }),
        "stolen generation-two voice should reset then accept its exact assignment");
    requireNear(wholeResult.mono[28], 0.0, 1.0e-12,
        "offline note-off should release at its exact frame");

    talas::runtime::OfflineRenderSession partitioned(graph);
    require(partitioned.scheduleMidiVoiceEvents(events),
        "partitioned offline voice stream should prepare");
    std::vector<double> partitionedOutput;
    for (const auto frames : {std::size_t{3}, std::size_t{9},
                             std::size_t{5}, std::size_t{15}})
    {
        const auto block = partitioned.render(frames);
        require(block.ok() && block.mono.size() == frames,
            "partitioned offline voice block should render");
        partitionedOutput.insert(
            partitionedOutput.end(), block.mono.begin(), block.mono.end());
    }
    require(partitionedOutput.size() == wholeResult.mono.size(),
        "partitioned offline render should preserve exact extent");
    for (std::size_t frame = 0; frame < wholeResult.mono.size(); ++frame)
    {
        requireNear(
            partitionedOutput[frame],
            wholeResult.mono[frame],
            1.0e-12,
            "offline allocator and voice transactions should be block-partition invariant");
    }

    partitioned.reset();
    require(partitioned.scheduleMidiVoiceEvents(events),
        "offline reset should restore the initial allocator contract");
    const auto resetResult = partitioned.render(32);
    require(resetResult.ok() && resetResult.mono == wholeResult.mono,
        "offline reset should reproduce generations and audio exactly");
}

void testThresholdAdmitsOscillatorOwnedMidiVoiceComposition()
{
    auto document = makePreparedMidiVoiceDocument(1);
    document.graph.nodes.push_back(node(
        "thresholdSource", "talas.constant", {{"value", "0.7"}}));
    document.graph.nodes.push_back(node(
        "threshold", "talas.threshold",
        {{"threshold", "0.5"}, {"hysteresis", "0.2"}}));
    document.graph.nodes.push_back(node(
        "thresholdCarrier", "talas.oscillator",
        {{"frequency", "40 hz"}, {"amplitude", "1"}}));
    document.graph.nodes.push_back(node("globalVca", "talas.vca"));
    document.graph.connections.clear();
    document.graph.connections.push_back(connection(
        "thresholdSource", "value", "threshold", "value"));
    document.graph.connections.push_back(connection(
        "osc", "audioOut", "midi", "audioIn"));
    document.graph.connections.push_back(connection(
        "midi", "leftOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "thresholdCarrier", "audioOut", "globalVca", "audioIn"));
    document.graph.connections.push_back(connection(
        "threshold", "value", "globalVca", "gain"));
    document.graph.connections.push_back(connection(
        "globalVca", "audioOut", "out", "rightIn"));

    const auto graph = compile(document, preparedMidiVoiceSettings(4));
    talas::runtime::RealtimeRenderSession prepared(graph);
    require(prepared.ready(),
        "C95 should admit the Oscillator-owned MIDI Voice as immutable DSP-pass input alongside checkpointed Threshold state: "
            + std::string{prepared.error()});

    talas::runtime::OfflineRenderSession offline(graph);
    talas::runtime::OfflineMidiVoiceEvent note;
    note.frame = 0;
    note.batchId = 1;
    note.sequence = 1;
    note.kind = talas::runtime::OfflineMidiVoiceEventKind::NoteOn;
    note.channel = 1;
    note.note = 60;
    note.velocity = 127;
    const std::array events{note};
    require(offline.scheduleMidiVoiceEvents(events)
            && offline.render(4).ok(),
        "C95 offline MIDI Voice should remain compatible with the admitted Threshold composition");
}

void testOfflineMappedMidiUsesExactPreparedReducer()
{
    talas::runtime::RenderSettings settings{1000.0, 8};
    settings.maxRealtimeEventTransactions = 8;
    auto graph = compile(
        makePreparedMidiMapperDocument("velocity", 2), settings);
    const auto note = [](
        std::uint64_t frame,
        std::uint64_t batch,
        std::uint64_t sequence,
        talas::runtime::OfflineMidiVoiceEventKind kind,
        std::uint8_t pitch,
        std::uint8_t velocity) {
        talas::runtime::OfflineMidiVoiceEvent event;
        event.frame = frame;
        event.batchId = batch;
        event.sequence = sequence;
        event.kind = kind;
        event.channel = 1;
        event.note = pitch;
        event.velocity = velocity;
        return event;
    };
    const std::array offlineEvents{
        note(0, 1, 1,
            talas::runtime::OfflineMidiVoiceEventKind::NoteOn, 60, 32),
        note(2, 2, 2,
            talas::runtime::OfflineMidiVoiceEventKind::NoteOn, 61, 96),
        note(4, 3, 3,
            talas::runtime::OfflineMidiVoiceEventKind::NoteOff, 61, 0),
        note(6, 4, 4,
            talas::runtime::OfflineMidiVoiceEventKind::NoteOff, 60, 0),
    };

    talas::runtime::OfflineRenderSession offline(graph);
    require(offline.scheduleMidiVoiceEvents(offlineEvents),
        "offline mapper should accept the prepared MIDI stream");
    const auto offlineResult = offline.render(8);
    require(offlineResult.ok() && offlineResult.mono.size() == 8,
        "offline mapper should render the complete stream");

    talas::runtime::RealtimeRenderSession realtime(graph);
    require(realtime.ready(), std::string(realtime.error()));
    for (const auto& event : offlineEvents)
    {
        require(realtime.scheduleMidiNote(
                    {event.kind
                            == talas::runtime::OfflineMidiVoiceEventKind::NoteOff
                        ? talas::runtime::RealtimeMidiNoteKind::NoteOff
                        : talas::runtime::RealtimeMidiNoteKind::NoteOn,
                     event.channel,
                     event.note,
                     event.velocity},
                    static_cast<std::size_t>(event.frame))
                == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "realtime parity mapper should accept the same MIDI stream");
    }
    std::array<double, 8> realtimeOutput{};
    require(realtime.render(realtimeOutput),
        "realtime parity mapper should render");
    for (std::size_t frame = 0; frame < realtimeOutput.size(); ++frame)
    {
        requireNear(offlineResult.mono[frame], realtimeOutput[frame],
            1.0e-12,
            "offline and prepared mapper reducers should be sample-identical");
    }
}

void testRealtimeSessionPublishesExactMidiRetriggerAndAttackBoundaries()
{
    auto midiGraph = compile(
        makePreparedMidiVoiceDocument(1, 1, 0, 127, "!KeyDown"),
        preparedMidiVoiceSettings());
    auto referenceGraph = compile(
        makeMidiVoiceReferenceOscillatorDocument(),
        preparedMidiVoiceSettings());
    talas::runtime::RealtimeRenderSession midiSession(midiGraph);
    talas::runtime::RealtimeRenderSession referenceSession(referenceGraph);
    require(midiSession.ready(), std::string(midiSession.error()));
    require(referenceSession.ready(), std::string(referenceSession.error()));
    require(midiSession.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 60, 127},
                0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "gate-boundary MIDI note should be handled");

    std::array<double, 16> midiLeft{};
    std::array<double, 16> midiRight{};
    std::array<double, 16> referenceLeft{};
    std::array<double, 16> referenceRight{};
    std::size_t allocations = 0;
    require(renderStereoAndCount(midiSession, midiLeft, midiRight, allocations),
            "gate-boundary MIDI voice should render");
    require(allocations == 0, "gate-boundary MIDI voice render should not allocate");
    require(referenceSession.render(referenceLeft, referenceRight),
            "gate-boundary reference should render");
    for (std::size_t frame = 0; frame < midiLeft.size(); ++frame)
    {
        const auto expected = frame < 5 ? -referenceLeft[frame] : referenceLeft[frame];
        requireNear(midiLeft[frame], expected, 1.0e-12,
                    "MIDI retrigger should publish -1 until the exact delayed +1 attack frame");
        requireNear(midiRight[frame], expected, 1.0e-12,
                    "MIDI gate boundaries should remain stereo coherent");
    }
}

void testRealtimeSessionAppliesMappedMidiGateAtExactFramesWithoutAllocations()
{
    talas::runtime::RenderSettings settings{1000.0, 16};
    settings.maxRealtimeEventTransactions = 8;
    auto mapperGraph = compile(
        makePreparedMidiMapperDocument("gate"), settings);
    auto referenceGraph = compile(
        makePreparedMidiMapperDocument(""), settings);
    talas::runtime::RealtimeRenderSession mapper(mapperGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(mapper.ready(), std::string(mapper.error()));
    require(reference.ready(), std::string(reference.error()));
    require(mapper.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 3, 60, 100},
                2)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
        "mapped gate note-on should be handled");
    require(mapper.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOff, 3, 60, 0},
                6)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
        "mapped gate note-off should be handled");

    std::array<double, 8> mappedLeft{};
    std::array<double, 8> mappedRight{};
    std::array<double, 8> referenceLeft{};
    std::array<double, 8> referenceRight{};
    std::size_t allocations = 0;
    require(renderStereoAndCount(
                mapper, mappedLeft, mappedRight, allocations),
        "mapped gate should render");
    require(allocations == 0,
        "mapped gate callback should not allocate");
    require(reference.render(referenceLeft, referenceRight),
        "mapped gate reference should render");
    for (std::size_t frame = 0; frame < mappedLeft.size(); ++frame)
    {
        const auto gain = frame >= 2 && frame < 6 ? 1.0 : 0.0;
        requireNear(mappedLeft[frame], referenceLeft[frame] * gain,
            1.0e-12, "mapped gate left exact frame");
        requireNear(mappedRight[frame], referenceRight[frame] * gain,
            1.0e-12, "mapped gate right exact frame");
    }
}

void testRealtimeSessionReducesMappedVelocityAndResetsHeldState()
{
    talas::runtime::RenderSettings settings{1000.0, 16};
    settings.maxRealtimeEventTransactions = 8;
    auto mapperGraph = compile(
        makePreparedMidiMapperDocument("velocity", 2), settings);
    auto referenceGraph = compile(
        makePreparedMidiMapperDocument(""), settings);
    talas::runtime::RealtimeRenderSession mapper(mapperGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(mapper.ready() && reference.ready(),
        "velocity mapper and blank reference should prepare");
    const std::array events{
        std::pair{talas::runtime::RealtimeMidiNoteEvent{
            talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 60, 32},
            std::size_t{0}},
        std::pair{talas::runtime::RealtimeMidiNoteEvent{
            talas::runtime::RealtimeMidiNoteKind::NoteOn, 2, 61, 96},
            std::size_t{2}},
        std::pair{talas::runtime::RealtimeMidiNoteEvent{
            talas::runtime::RealtimeMidiNoteKind::NoteOff, 2, 61, 0},
            std::size_t{4}},
        std::pair{talas::runtime::RealtimeMidiNoteEvent{
            talas::runtime::RealtimeMidiNoteKind::NoteOff, 1, 60, 0},
            std::size_t{6}},
    };
    for (const auto& [event, frame] : events)
    {
        require(mapper.scheduleMidiNote(event, frame)
                == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "velocity mapper event should be handled");
    }
    std::array<double, 8> mapped{};
    std::array<double, 8> referenceOutput{};
    require(mapper.render(mapped) && reference.render(referenceOutput),
        "velocity mapper comparison should render");
    for (std::size_t frame = 0; frame < mapped.size(); ++frame)
    {
        const auto gain = frame < 2 ? 32.0 / 127.0
            : frame < 4 ? 96.0 / 127.0
            : frame < 6 ? 32.0 / 127.0
            : 0.0;
        requireNear(mapped[frame], referenceOutput[frame] * gain,
            1.0e-12, "velocity mapper should publish exact max-held gain");
    }

    require(mapper.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 64, 127}, 0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
        "reset fixture should accept held note");
    mapper.resetTransport();
    std::array<double, 4> resetOutput{};
    require(mapper.render(resetOutput), "reset mapper should render");
    for (const auto sample : resetOutput)
        requireNear(sample, 0.0, 1.0e-12,
            "transport reset should clear mapped held-note state");
}

void testRealtimeSessionRejectsForgedMidiMapperPlanAuthority()
{
    talas::runtime::RenderSettings settings{1000.0, 8};
    settings.maxRealtimeEventTransactions = 4;
    auto staleOwner = compile(
        makePreparedMidiMapperDocument("gate"), settings);
    auto& stalePlan = const_cast<talas::runtime::RuntimePlan&>(
        staleOwner.plan());
    require(stalePlan.midiMappers.size() == 1,
        "forged mapper fixture should begin with one plan");
    stalePlan.midiMappers.front().ownerStepIndex =
        stalePlan.steps.size();
    talas::runtime::RealtimeRenderSession staleSession(staleOwner);
    require(!staleSession.ready(),
        "out-of-range mapper owner should fail prepared construction");

    auto duplicateOwner = compile(
        makePreparedMidiMapperDocument("gate"), settings);
    auto& duplicatePlan = const_cast<talas::runtime::RuntimePlan&>(
        duplicateOwner.plan());
    duplicatePlan.midiMappers.push_back(
        duplicatePlan.midiMappers.front());
    talas::runtime::RealtimeRenderSession duplicateSession(duplicateOwner);
    require(!duplicateSession.ready(),
        "duplicate exact mapper owner should fail prepared construction");

    const auto requireConfigurationMismatchRejected = [&](auto mutate,
                                                        std::string_view field) {
        auto graph = compile(
            makePreparedMidiMapperDocument("gate", 4, 3, 24, 96),
            settings);
        auto& plan = const_cast<talas::runtime::RuntimePlan&>(graph.plan());
        require(plan.midiMappers.size() == 1,
            "configuration mismatch fixture should have one mapper plan");
        mutate(plan.midiMappers.front().configuration);
        talas::runtime::RealtimeRenderSession session(graph);
        require(!session.ready(),
            "forged MIDI Mapper " + std::string(field)
                + " must fail exact prepared construction");
    };
    requireConfigurationMismatchRejected(
        [](auto& configuration) {
            configuration.mode =
                talas::runtime::PreparedMidiMapperMode::Velocity;
        },
        "mode");
    requireConfigurationMismatchRejected(
        [](auto& configuration) { configuration.channel = 0; },
        "channel");
    requireConfigurationMismatchRejected(
        [](auto& configuration) { configuration.lowPitch = 25; },
        "low pitch");
    requireConfigurationMismatchRejected(
        [](auto& configuration) { configuration.highPitch = 95; },
        "high pitch");
    requireConfigurationMismatchRejected(
        [](auto& configuration) { configuration.polyphony = 5; },
        "polyphony");
}

void testRealtimeSessionCarriesDelayedMidiAttackAcrossCallbacksAndReleasesExactly()
{
    auto graph = compile(makePreparedMidiVoiceDocument(1), preparedMidiVoiceSettings());
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 60, 127},
                0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "cross-callback MIDI note should be handled");

    std::array<double, 4> first{};
    std::array<double, 4> second{};
    require(session.render(first), "pre-attack callback should render");
    require(session.render(second), "crossing attack callback should render");
    for (const auto sample : first)
        requireNear(sample, 0.0, 1.0e-12, "delayed attack should remain silent in the first callback");
    requireNear(second[0], 0.0, 1.0e-12, "delayed attack should remain silent before its absolute frame");
    require(std::ranges::any_of(std::span<const double>(second).subspan(1), [](double sample) {
                return std::abs(sample) > 1.0e-6;
            }),
            "delayed attack should begin at its absolute frame in the next callback");

    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOff, 1, 60, 0},
                0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "active MIDI note-off should be handled");
    std::array<double, 4> released{};
    require(session.render(released), "released MIDI voice should render");
    for (const auto sample : released)
        requireNear(sample, 0.0, 1.0e-12, "note-off should publish release at the exact command frame");
}

void testRealtimeSessionInvalidatesStaleDelayedAttackAfterVoiceSteal()
{
    auto stolenGraph = compile(makePreparedMidiVoiceDocument(1), preparedMidiVoiceSettings());
    auto referenceGraph = compile(makePreparedMidiVoiceDocument(1), preparedMidiVoiceSettings());
    talas::runtime::RealtimeRenderSession stolen(stolenGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(stolen.ready(), std::string(stolen.error()));
    require(reference.ready(), std::string(reference.error()));
    require(stolen.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 60, 127}, 0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "initial note should occupy the only voice");
    require(stolen.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 72, 127}, 1)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "second note should steal the longest-held voice");
    require(reference.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 72, 127}, 1)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "reference stolen note should be handled");

    std::array<double, 16> stolenOutput{};
    std::array<double, 16> referenceOutput{};
    require(stolen.render(stolenOutput), "stolen MIDI voice should render");
    require(reference.render(referenceOutput), "stolen MIDI reference should render");
    for (std::size_t frame = 0; frame < stolenOutput.size(); ++frame)
        requireNear(stolenOutput[frame], referenceOutput[frame], 1.0e-12,
                    "stale delayed attack must not revive the stolen pitch");
}

