void testRealtimeSessionRollsBackMapperWithRejectedMidiVoiceTransaction()
{
    auto graph = compile(
        makeMixedRejectedVoiceAndMapperDocument(),
        preparedMidiVoiceSettings(8));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 60, 127}, 0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
        "mixed mapper/voice rejection should schedule atomically");
    std::array<double, 8> rejected{};
    std::size_t allocations = 0;
    require(!renderAndCount(session, rejected, allocations),
        "invalid MIDI Voice expression should reject the mixed callback");
    require(allocations == 0,
        "mixed mapper/voice rollback should not allocate");

    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 2, 64, 100}, 0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
        "mapper-only recovery note should schedule");
    std::array<double, 8> opened{};
    require(renderAndCount(session, opened, allocations),
        "mapper should recover after mixed rollback");
    require(std::ranges::any_of(opened, [](double sample) {
            return std::abs(sample) > 1.0e-8;
        }),
        "mapper-only recovery note should open the gate");

    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOff, 2, 64, 0}, 0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
        "mapper-only recovery note-off should schedule");
    std::array<double, 8> closed{};
    require(renderAndCount(session, closed, allocations),
        "mapper should render after recovery note-off");
    require(std::ranges::all_of(closed, [](double sample) {
            return std::abs(sample) <= 1.0e-12;
        }),
        "failed channel-one action must not survive the mixed rollback");
}

void testRealtimeSessionCancelsRejectedDelayedAttackAndAllowsNewNote()
{
    auto graph = compile(
        makePreparedMidiVoiceWithLiveFilterQDocument(),
        preparedMidiVoiceSettings());
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 60, 127}, 0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "invalid delayed attack note should schedule");

    std::array<double, 16> rejected{};
    std::size_t allocations = 0;
    require(!renderAndCount(session, rejected, allocations),
            "velocity-127 delayed attack should reject a zero live filter Q");
    require(allocations == 0, "rejected delayed MIDI attack should not allocate");
    require(session.scheduleMidiNote(
                {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, 72, 64}, 0)
            == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "a new note should schedule after the rejected delayed attack");
    std::array<double, 16> recovered{};
    require(renderAndCount(session, recovered, allocations),
            "a valid new note should recover after the rejected delayed attack");
    require(allocations == 0, "recovered delayed MIDI attack should not allocate");
    require(std::ranges::all_of(std::span<const double>(recovered).first(5), [](double sample) {
                return std::abs(sample) <= 1.0e-12;
            }),
            "recovered note should remain silent until its exact delayed attack frame");
    require(std::ranges::any_of(std::span<const double>(recovered).subspan(5), [](double sample) {
                return std::abs(sample) > 1.0e-8;
            }),
            "valid delayed attack should sound after the rejected attack is cancelled");
}

void testRealtimeSessionDeterministicallySumsSimultaneousPitchedVoices()
{
    auto polyGraph = compile(makePreparedMidiVoiceDocument(2), preparedMidiVoiceSettings());
    auto firstGraph = compile(makePreparedMidiVoiceDocument(1), preparedMidiVoiceSettings());
    auto secondGraph = compile(makePreparedMidiVoiceDocument(1), preparedMidiVoiceSettings());
    talas::runtime::RealtimeRenderSession poly(polyGraph);
    talas::runtime::RealtimeRenderSession first(firstGraph);
    talas::runtime::RealtimeRenderSession second(secondGraph);
    require(poly.ready(), std::string(poly.error()));
    require(first.ready(), std::string(first.error()));
    require(second.ready(), std::string(second.error()));
    const auto schedule = [](talas::runtime::RealtimeRenderSession& session, std::uint8_t note) {
        return session.scheduleMidiNote(
            {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, note, 127}, 0);
    };
    require(schedule(poly, 60) == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "first simultaneous polyphonic note should be handled");
    require(schedule(poly, 72) == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "second simultaneous polyphonic note should be handled");
    require(schedule(first, 60) == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "first reference note should be handled");
    require(schedule(second, 72) == talas::runtime::RealtimeMidiDispatchResult::Handled,
            "second reference note should be handled");

    std::array<double, 16> mixed{};
    std::array<double, 16> firstOnly{};
    std::array<double, 16> secondOnly{};
    require(poly.render(mixed), "simultaneous polyphonic voices should render");
    require(first.render(firstOnly), "first reference voice should render");
    require(second.render(secondOnly), "second reference voice should render");
    for (std::size_t frame = 0; frame < mixed.size(); ++frame)
        requireNear(mixed[frame], firstOnly[frame] + secondOnly[frame], 1.0e-12,
                    "prepared voices should mix in deterministic ascending voice order");
}

void testRealtimeSessionPropagatesScheduledGlobalEventValueToEveryVoice()
{
    auto settings = preparedMidiVoiceSettings();
    settings.eventValues.push_back({"GlobalGain", 1.0, talas::expr::ValueDomain::Scalar});
    auto changedGraph = compile(
        makePreparedMidiVoiceDocument(2, 1, 0, 127, "!KeyDown * !KeyVelocity * !GlobalGain"),
        settings);
    auto referenceGraph = compile(
        makePreparedMidiVoiceDocument(2, 1, 0, 127, "!KeyDown * !KeyVelocity * !GlobalGain"),
        settings);
    talas::runtime::RealtimeRenderSession changed(changedGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(changed.ready(), std::string(changed.error()));
    require(reference.ready(), std::string(reference.error()));
    for (const auto note : {std::uint8_t{60}, std::uint8_t{72}})
    {
        require(changed.scheduleMidiNote(
                    {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, note, 127}, 0)
                == talas::runtime::RealtimeMidiDispatchResult::Handled,
                "changed polyphonic note should be handled");
        require(reference.scheduleMidiNote(
                    {talas::runtime::RealtimeMidiNoteKind::NoteOn, 1, note, 127}, 0)
                == talas::runtime::RealtimeMidiDispatchResult::Handled,
                "reference polyphonic note should be handled");
    }
    require(changed.scheduleEventValue(
                "GlobalGain", 0.5, talas::expr::ValueDomain::Scalar, 7),
            "global voice gain should schedule");

    std::array<double, 16> changedOutput{};
    std::array<double, 16> referenceOutput{};
    std::size_t allocations = 0;
    require(renderAndCount(changed, changedOutput, allocations),
            "globally updated prepared voices should render");
    require(allocations == 0, "global prepared-voice update should render without allocations");
    require(reference.render(referenceOutput), "global prepared-voice reference should render");
    for (std::size_t frame = 0; frame < changedOutput.size(); ++frame)
    {
        const auto scale = frame < 7 ? 1.0 : 0.5;
        requireNear(changedOutput[frame], referenceOutput[frame] * scale, 1.0e-12,
                    "scheduled global Event Value should reach every active voice at the exact frame");
    }
}

