void testRealtimeProcessorPlacementMatchesOfflineAndRejectsForgery()
{
    auto graph = compile(
        makeNestedProcessorPlacementDocument(),
        {4.0, 3});
    const auto expected = talas::runtime::renderOffline(graph, 7);
    require(
        expected.ok() && expected.mono.size() == 7,
        "offline processor placement reference should render");

    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        "prepared processor placement should stage: "
            + std::string(session.error()));
    std::array<double, 7> actual{};
    std::size_t offset = 0;
    for (const auto blockFrames : {std::size_t{3}, std::size_t{2}, std::size_t{2}})
    {
        std::size_t allocations = 0;
        require(
            renderAndCount(
                session,
                std::span<double>{actual}.subspan(offset, blockFrames),
                allocations),
            "prepared processor placement block should render");
        require(
            allocations == 0,
            "prepared processor placement callback should not allocate");
        offset += blockFrames;
    }
    for (std::size_t frame = 0; frame < actual.size(); ++frame)
    {
        requireNear(
            actual[frame],
            expected.mono[frame],
            1.0e-12,
            "prepared processor placement should match offline");
    }

    auto forgedPlan = graph.plan();
    require(
        !forgedPlan.processorPlacement.transfers.empty(),
        "forgery fixture should contain a transfer");
    forgedPlan.processorPlacement.transfers.front().targetProcessorId = 99;
    talas::runtime::PreparedRuntimeGraph forged{
        std::move(forgedPlan),
        graph.renderSettings(),
    };
    talas::runtime::RealtimeRenderSession rejected(forged);
    require(
        !rejected.ready()
            && rejected.error().find("placement")
                != std::string_view::npos,
        "prepared realtime should reject forged placement authority");
    const auto rejectedOffline = talas::runtime::renderOffline(forged, 7);
    require(
        !rejectedOffline.ok() && rejectedOffline.mono.empty(),
        "offline render should reject forged placement without partial audio");
}

