void testRealtimeStereoInOutputKeepsNestedSourceScopesIsolated()
{
    const auto graph = compile(
        makeNestedStereoInOutputRealtimeDocument(), {4.0, 5});
    const auto terminal = std::ranges::find(
        graph.plan().steps,
        std::string_view{"talas.stereoInOutput4"},
        &talas::runtime::CompileStep::typeId);
    require(
        terminal != graph.plan().steps.end()
            && terminal->scopeId == talas::runtime::globalRuntimeScope
            && terminal->inputs.size() == 2
            && terminal->inputs[0].sourceScopeId
                != talas::runtime::globalRuntimeScope
            && terminal->inputs[1].sourceScopeId
                != talas::runtime::globalRuntimeScope
            && terminal->inputs[0].sourceScopeId
                != terminal->inputs[1].sourceScopeId,
        "C28 terminal should remain root-only while nested pair sources own independent scopes");

    const auto expected = talas::runtime::renderOffline(graph, 5);
    talas::runtime::RealtimeRenderSession realtime(graph);
    std::array<std::array<double, 5>, 4> actual{};
    std::array<double*, 4> destinations{};
    for (std::size_t channel = 0; channel < actual.size(); ++channel)
        destinations[channel] = actual[channel].data();
    std::size_t allocations = 0;
    require(
        expected.ok()
            && expected.channels.size() == actual.size()
            && realtime.ready()
            && renderMultichannelAndCount(
                realtime,
                destinations.data(),
                destinations.size(),
                5,
                allocations)
            && allocations == 0,
        "C28 nested pair sources should prepare and render allocation-free");
    for (std::size_t channel = 0; channel < actual.size(); ++channel)
    {
        require(
            std::equal(
                actual[channel].begin(),
                actual[channel].end(),
                expected.channels[channel].begin()),
            "C28 nested pair source output should match offline exactly");
    }
}

void testRealtimeStereoInOutputRollsBackLateSourceFailure()
{
    auto settings = talas::runtime::RenderSettings{32.0, 7};
    settings.eventValues.push_back({
        "C28LateLevel", 1.0, talas::expr::ValueDomain::Scalar});
    settings.eventValues.push_back({
        "C28LaterGain", 0.25, talas::expr::ValueDomain::Scalar});
    const auto graph = compile(
        makeStereoInOutputRollbackDocument(), settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession pristine(graph);
    require(
        candidate.ready()
            && pristine.ready()
            && candidate.scheduleEventValue(
                "C28LaterGain",
                0.5,
                talas::expr::ValueDomain::Scalar,
                1)
            && candidate.scheduleEventValue(
                "C28LateLevel",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar,
                2)
            && candidate.scheduleEventValue(
                "C28LaterGain",
                0.625,
                talas::expr::ValueDomain::Scalar,
                2)
            && candidate.scheduleEventValue(
                "C28LaterGain",
                0.75,
                talas::expr::ValueDomain::Scalar,
                5)
            && pristine.scheduleEventValue(
                "C28LaterGain",
                0.5,
                talas::expr::ValueDomain::Scalar,
                1)
            && pristine.scheduleEventValue(
                "C28LaterGain",
                0.625,
                talas::expr::ValueDomain::Scalar,
                2)
            && pristine.scheduleEventValue(
                "C28LaterGain",
                0.75,
                talas::expr::ValueDomain::Scalar,
                5),
        "C28 late-source rollback fixture should prepare and segment: candidate="
            + std::string{candidate.error()}
            + " pristine=" + std::string{pristine.error()});

    std::vector<std::vector<double>> rejected(
        8, std::vector<double>(7, 1.0));
    std::vector<double*> rejectedDestinations;
    rejectedDestinations.reserve(rejected.size());
    for (auto& channel : rejected)
        rejectedDestinations.push_back(channel.data());
    std::size_t allocations = 0;
    require(
        !renderMultichannelAndCount(
            candidate,
            rejectedDestinations.data(),
            rejectedDestinations.size(),
            7,
            allocations)
            && allocations == 0
            && std::ranges::all_of(
                rejected,
                [](const auto& channel) {
                    return std::ranges::all_of(
                        channel, [](double sample) {
                            return sample == 0.0;
                        });
                }),
        "C28 late source failure should publish no channel prefix");
    require(
        candidate.updateEventValue(
            "C28LateLevel", 1.0,
            talas::expr::ValueDomain::Scalar),
        "C28 rollback control should recover after failure");

    std::vector<std::vector<double>> recovered(
        8, std::vector<double>(7));
    std::vector<std::vector<double>> expected(
        8, std::vector<double>(7));
    std::vector<double*> recoveredDestinations;
    std::vector<double*> expectedDestinations;
    recoveredDestinations.reserve(8);
    expectedDestinations.reserve(8);
    for (std::size_t channel = 0; channel < 8; ++channel)
    {
        recoveredDestinations.push_back(recovered[channel].data());
        expectedDestinations.push_back(expected[channel].data());
    }
    require(
        renderMultichannelAndCount(
            candidate,
            recoveredDestinations.data(),
            recoveredDestinations.size(),
            7,
            allocations)
            && allocations == 0
            && renderMultichannelAndCount(
                pristine,
                expectedDestinations.data(),
                expectedDestinations.size(),
                7,
                allocations)
            && allocations == 0
            && recovered == expected,
        "C28 rejected callback should restore every mutable source and absolute frame exactly");
}

void testRealtimeStereoInOutputRecoveryOverridesPreparedTimelineFailure()
{
    const auto requireRecovery = [](
                                     talas::core::AutomationInterpolation interpolation,
                                     std::string_view context) {
        auto candidateSettings = talas::runtime::RenderSettings{32.0, 7};
        candidateSettings.eventValues = {
            {"C28LateLevel", 1.0, talas::expr::ValueDomain::Scalar},
            {"C28LaterGain", 0.25, talas::expr::ValueDomain::Scalar},
        };
        candidateSettings.eventValueChanges = {
            {0,
             "C28LateLevel",
             1.0,
             talas::expr::ValueDomain::Scalar,
             interpolation},
            {2,
             "C28LateLevel",
             std::numeric_limits<double>::max(),
             talas::expr::ValueDomain::Scalar},
            {2,
             "C28LaterGain",
             0.625,
             talas::expr::ValueDomain::Scalar},
            {5,
             "C28LaterGain",
             0.75,
             talas::expr::ValueDomain::Scalar},
        };
        auto pristineSettings = talas::runtime::RenderSettings{32.0, 7};
        pristineSettings.eventValues = candidateSettings.eventValues;
        pristineSettings.eventValueChanges = {
            {2,
             "C28LaterGain",
             0.625,
             talas::expr::ValueDomain::Scalar},
            {5,
             "C28LaterGain",
             0.75,
             talas::expr::ValueDomain::Scalar},
        };

        talas::runtime::RealtimeRenderSession candidate(compile(
            makeStereoInOutputRollbackDocument(),
            std::move(candidateSettings)));
        talas::runtime::RealtimeRenderSession pristine(compile(
            makeStereoInOutputRollbackDocument(),
            std::move(pristineSettings)));
        require(
            candidate.ready() && pristine.ready(),
            std::string{context}
                + " prepared-timeline rollback fixtures should prepare: candidate="
                + std::string{candidate.error()}
                + " pristine=" + std::string{pristine.error()});

        std::array<std::array<double, 7>, 8> rejected{};
        std::array<double*, 8> rejectedDestinations{};
        for (std::size_t channel = 0; channel < rejected.size(); ++channel)
            rejectedDestinations[channel] = rejected[channel].data();
        std::size_t allocations = 0;
        require(
            !renderMultichannelAndCount(
                candidate,
                rejectedDestinations.data(),
                rejectedDestinations.size(),
                rejected.front().size(),
                allocations)
                && allocations == 0,
            std::string{context}
                + " bad prepared timeline should reject without allocation");
        require(
            candidate.updateEventValue(
                "C28LateLevel",
                1.0,
                talas::expr::ValueDomain::Scalar),
            std::string{context}
                + " recovery update should supersede the bad prepared timeline");

        std::array<std::array<double, 7>, 8> recovered{};
        std::array<std::array<double, 7>, 8> expected{};
        std::array<double*, 8> recoveredDestinations{};
        std::array<double*, 8> expectedDestinations{};
        for (std::size_t channel = 0; channel < recovered.size(); ++channel)
        {
            recoveredDestinations[channel] = recovered[channel].data();
            expectedDestinations[channel] = expected[channel].data();
        }
        require(
            renderMultichannelAndCount(
                candidate,
                recoveredDestinations.data(),
                recoveredDestinations.size(),
                recovered.front().size(),
                allocations)
                && allocations == 0
                && renderMultichannelAndCount(
                    pristine,
                    expectedDestinations.data(),
                    expectedDestinations.size(),
                    expected.front().size(),
                    allocations)
                && allocations == 0
                && recovered == expected,
            std::string{context}
                + " recovery should suppress only the repaired prepared timeline binding");
    };

    requireRecovery(
        talas::core::AutomationInterpolation::Step,
        "C28 prepared step");
    requireRecovery(
        talas::core::AutomationInterpolation::Linear,
        "C28 prepared linear ramp");
}

void testRealtimeSessionRejectsForgedStereoInOutputAuthority()
{
    const auto compiled = compile(
        makeStereoInOutputRealtimeDocument("talas.stereoInOutput8"),
        {32.0, 7});
    const auto requireRejected = [](
                                     talas::runtime::RuntimePlan plan,
                                     talas::runtime::RenderSettings settings,
                                     std::string_view context) {
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), std::move(settings)});
        require(
            !session.ready(),
            std::string{context}
                + " should reject forged C28 paired terminal authority");
    };
    const auto mutateTerminal = [&] (
                                    auto mutate,
                                    std::string_view context) {
        auto plan = compiled.plan();
        const auto terminal = std::ranges::find(
            plan.steps,
            std::string_view{"talas.stereoInOutput8"},
            &talas::runtime::CompileStep::typeId);
        require(
            terminal != plan.steps.end(),
            "C28 forged-authority fixture should expose its terminal");
        mutate(plan, *terminal);
        requireRejected(
            std::move(plan), compiled.renderSettings(), context);
    };

    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.preparedRealtimeSupport =
                talas::core::ExecutionSupport::Supported;
        },
        "C28 forged full support");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.preparedRealtimeBinding =
                talas::core::ExecutionBinding::None;
        },
        "C28 forged binding");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.offlineSupport =
                talas::core::ExecutionSupport::Unsupported;
        },
        "C28 forged offline support");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.offlineBinding =
                talas::core::ExecutionBinding::None;
        },
        "C28 forged offline binding");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.supportsReset = true;
        },
        "C28 forged reset contract");
    mutateTerminal(
        [](auto&, auto& terminal) {
            ++terminal.eventValueScopeId;
        },
        "C28 forged Event Value scope");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.parameters.push_back({});
        },
        "C28 unexpected parameter authority");
    mutateTerminal(
        [](auto&, auto& terminal) {
            std::swap(terminal.inputs[0], terminal.inputs[1]);
        },
        "C28 reordered paired inputs");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.inputs.pop_back();
            terminal.inputLatencyFrames.pop_back();
        },
        "C28 missing paired input");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.inputs.push_back(terminal.inputs.back());
            terminal.inputLatencyFrames.push_back(
                terminal.inputLatencyFrames.back());
        },
        "C28 extra paired input");
    mutateTerminal(
        [](auto& plan, auto&) {
            plan.outputBufferIndices.pop_back();
        },
        "C28 truncated output map");
    mutateTerminal(
        [](auto& plan, auto&) {
            plan.outputBufferIndices.push_back(
                plan.outputBufferIndices.back());
        },
        "C28 expanded output map");
    mutateTerminal(
        [](auto& plan, auto&) {
            plan.outputBufferIndices[1] = plan.outputBufferIndices[2];
            plan.rightOutputBufferIndex = plan.outputBufferIndices[1];
        },
        "C28 false pair alias");
    mutateTerminal(
        [](auto& plan, auto&) {
            plan.outputBufferIndex = plan.outputBufferIndices[2];
        },
        "C28 forged legacy first output");
    mutateTerminal(
        [](auto& plan, auto&) {
            plan.rightOutputBufferIndex = plan.outputBufferIndices[2];
        },
        "C28 forged legacy right output");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.inputs[0].inputPortId = "out21";
        },
        "C28 wrong paired port");
    mutateTerminal(
        [](auto& plan, auto& terminal) {
            plan.buffers[terminal.inputs[0].bufferIndex].type =
                talas::core::PortType::Control;
        },
        "C28 wrong paired buffer type");
    mutateTerminal(
        [](auto& plan, auto& terminal) {
            ++plan.buffers[terminal.inputs[0].bufferIndex].frames;
        },
        "C28 forged paired buffer capacity");
    mutateTerminal(
        [](auto& plan, auto& terminal) {
            auto& binding = terminal.inputs[0];
            auto forged = plan.buffers[binding.bufferIndex];
            forged.nodeId += "Forged";
            binding.sourceNodeId = forged.nodeId;
            binding.bufferIndex = plan.buffers.size();
            plan.outputBufferIndices[0] = binding.bufferIndex;
            plan.outputBufferIndices[1] = binding.bufferIndex;
            plan.outputBufferIndex = binding.bufferIndex;
            plan.rightOutputBufferIndex = binding.bufferIndex;
            plan.buffers.push_back(std::move(forged));
        },
        "C28 unproduced coherent pair map");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.resolvedLatencyFrames = 1;
        },
        "C28 forged intrinsic latency");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.inputLatencyFrames[0] = 1;
            terminal.cumulativeInputLatencyFrames = 1;
            terminal.cumulativeOutputLatencyFrames = 1;
        },
        "C28 coherently forged input latency");
    mutateTerminal(
        [](auto& plan, auto& terminal) {
            auto& source = *std::ranges::find(
                plan.steps,
                terminal.inputs[0].sourceNodeId,
                &talas::runtime::CompileStep::nodeId);
            source.cumulativeInputLatencyFrames = 1;
            source.cumulativeOutputLatencyFrames = 1;
            terminal.inputLatencyFrames[0] = 1;
            terminal.cumulativeInputLatencyFrames = 1;
            terminal.cumulativeOutputLatencyFrames = 1;
            plan.totalOutputLatencyFrames = 1;
            plan.criticalPathLatencyFrames = 1;
        },
        "C28 coherently forged positive source and terminal latency");
    mutateTerminal(
        [](auto& plan, auto&) {
            plan.totalOutputLatencyFrames = 1;
        },
        "C28 forged terminal output latency");
    mutateTerminal(
        [](auto& plan, auto&) {
            plan.criticalPathLatencyFrames = 1;
        },
        "C28 forged critical-path latency");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.soundVariableCellIndex = 0;
        },
        "C28 forged ancillary state");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.soundVariableKind =
                talas::project::ProjectSoundVariableKind::SoundCollection;
        },
        "C28 forged ancillary Sound Variable kind");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.structuralSourcePath += "Forged";
        },
        "C28 forged structural source path");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.preparedSpectralFrameSize = 1024;
        },
        "C28 forged ancillary spectral frame size");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.preparedSpectralHopSize = 256;
        },
        "C28 forged ancillary spectral hop size");
    mutateTerminal(
        [](auto& plan, auto& terminal) {
            auto duplicate = terminal;
            duplicate.nodeId = "outDuplicate";
            duplicate.structuralSourcePath = "outDuplicate";
            plan.steps.push_back(std::move(duplicate));
            const auto placement =
                talas::runtime::buildProcessorPlacementPlan(plan);
            require(
                placement.ok(),
                "C28 unique duplicate terminal fixture should rebuild exact processor placement: "
                    + placement.error);
            plan.processorPlacement = *placement.plan;
        },
        "C28 uniquely named duplicate root terminal");
}

void requirePreparedMixingParity(
    const talas::project::ProjectDocument& document,
    talas::runtime::RenderSettings settings,
    const std::vector<std::vector<float>>& hostInputs,
    std::string_view context)
{
    constexpr std::size_t frameCount = 7;
    auto graph = compile(document, settings);
    const auto expected = talas::runtime::renderOffline(graph, frameCount);
    require(
        expected.ok()
            && expected.mono.size() == frameCount
            && expected.right.size() == frameCount,
        std::string(context) + " offline reference should render in stereo");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::vector<double> left(frameCount, 0.0);
    std::vector<double> right(frameCount, 0.0);
    constexpr std::array<std::size_t, 3> partitions{3, 1, 3};
    std::size_t offset = 0;
    for (const auto partition : partitions)
    {
        std::vector<const float*> channels;
        channels.reserve(hostInputs.size());
        for (const auto& input : hostInputs)
            channels.push_back(input.data() + offset);
        std::size_t allocations = 0;
        require(
            renderStereoInputAndCount(
                session,
                {channels.data(), channels.size()},
                std::span<double>(left).subspan(offset, partition),
                std::span<double>(right).subspan(offset, partition),
                allocations),
            std::string(context)
                + " should render across irregular callback partitions");
        require(
            allocations == 0,
            std::string(context)
                + " irregular callback should not allocate");
        offset += partition;
    }
    for (std::size_t frame = 0; frame < frameCount; ++frame)
    {
        requireNear(
            left[frame], expected.mono[frame], 1.0e-12,
            std::string(context) + " left parity frame");
        requireNear(
            right[frame], expected.right[frame], 1.0e-12,
            std::string(context) + " right parity frame");
    }
}

void testRealtimeMixingNodesMatchOfflineAcrossSampleControlsAndPartitions()
{
    const std::vector<float> input1{
        1.0F, -0.5F, 0.25F, 2.0F, -1.0F, 0.75F, 0.0F};
    const std::vector<float> input2{
        -0.25F, 1.0F, 0.5F, -1.0F, 0.0F, 1.5F, -0.75F};
    const std::vector<double> control{
        0.0, 0.25, 0.5, 0.75, 1.0, 0.5, 0.0};

    {
        talas::runtime::RenderSettings settings{8.0, 7};
        settings.audioInputChannels = {{1, {
            1.0, -0.5, 0.25, 2.0, -1.0, 0.75, 0.0}}};
        settings.tableResources.push_back({"Tables/MixControl", control});
        requirePreparedMixingParity(
            makeRealtimePanDocument(
                {{"pan", "0"}, {"scale", "0.75"},
                 choiceParameter("type", "power")},
                true),
            std::move(settings),
            {input1},
            "prepared Pan");
    }
    {
        talas::runtime::RenderSettings settings{8.0, 7};
        settings.audioInputChannels = {
            {1, {1.0, -0.5, 0.25, 2.0, -1.0, 0.75, 0.0}},
            {2, {-0.25, 1.0, 0.5, -1.0, 0.0, 1.5, -0.75}},
        };
        settings.tableResources.push_back({"Tables/MixControl", control});
        requirePreparedMixingParity(
            makeRealtimeCrossfadeDocument(
                {{"pan", "0.25"}, {"scale", "0.8"}, {"fade", "0"},
                 choiceParameter("type", "power")},
                true),
            std::move(settings),
            {input1, input2},
            "prepared Crossfade");
    }
    {
        talas::runtime::RenderSettings settings{8.0, 7};
        settings.audioInputChannels = {
            {1, {1.0, -0.5, 0.25, 2.0, -1.0, 0.75, 0.0}},
            {2, {-0.25, 1.0, 0.5, -1.0, 0.0, 1.5, -0.75}},
        };
        settings.tableResources.push_back({"Tables/MixControl", control});
        requirePreparedMixingParity(
            makeRealtimeStereoMix2Document(
                {{"left", "-0.5"}, {"right", "0.25"},
                 {"pan1", "0"}, {"scale1", "0.75"},
                 {"pan2", "1"}, {"scale2", "0.5"}},
                true),
            std::move(settings),
            {input1, input2},
            "prepared Stereo Mix 2");
    }
    {
        const std::vector<float> input3{
            0.5F, 0.25F, -0.5F, 1.0F, 0.75F, -1.0F, 2.0F};
        const std::vector<float> input4{
            -1.0F, 0.0F, 0.75F, 0.5F, -0.25F, 2.0F, 1.0F};
        talas::runtime::RenderSettings settings{8.0, 7};
        settings.audioInputChannels = {
            {1, {1.0, -0.5, 0.25, 2.0, -1.0, 0.75, 0.0}},
            {2, {-0.25, 1.0, 0.5, -1.0, 0.0, 1.5, -0.75}},
            {3, {0.5, 0.25, -0.5, 1.0, 0.75, -1.0, 2.0}},
            {4, {-1.0, 0.0, 0.75, 0.5, -0.25, 2.0, 1.0}},
        };
        settings.tableResources.push_back({"Tables/MixControl", control});
        requirePreparedMixingParity(
            makeRealtimeStereoMix4Document(
                {{"left", "0.75"}, {"right", "-0.5"},
                 {"pan1", "0"}, {"scale1", "1"},
                 {"pan2", "1"}, {"scale2", "0.5"},
                 {"pan3", "0"}, {"scale3", "0.25"},
                 {"pan4", "1"}, {"scale4", "0.75"}},
                true),
            std::move(settings),
            {input1, input2, input3, input4},
            "prepared Stereo Mix 4");
    }
}

void testRealtimeStereoRoutingUtilitiesMatchOfflineAcrossPartitions()
{
    const std::vector<float> input1{
        1.0F, -0.5F, 0.25F, 2.0F, -1.0F, 0.75F, 0.0F};
    const std::vector<float> input2{
        -0.25F, 1.0F, 0.5F, -1.0F, 0.0F, 1.5F, -0.75F};
    const std::vector<double> control{
        0.0, 0.25, 0.5, 0.75, 1.0, 0.5, 0.0};

    const auto settings = [&] {
        talas::runtime::RenderSettings result{8.0, 7};
        result.audioInputChannels = {
            {1, {1.0, -0.5, 0.25, 2.0, -1.0, 0.75, 0.0}},
            {2, {-0.25, 1.0, 0.5, -1.0, 0.0, 1.5, -0.75}},
        };
        result.tableResources.push_back({"Tables/MixControl", control});
        return result;
    };

    requirePreparedMixingParity(
        makeRealtimeLevelDocument({
            {"left", "0.25"}, {"right", "-0.5"},
            booleanParameter("noGain", true),
        }, true, false),
        settings(),
        {input1, input2},
        "prepared Level");
    requirePreparedMixingParity(
        makeRealtimeChannelCrosserDocument({
            {"leftInLeft", "0.5"}, {"rightInLeft", "-0.25"},
            {"leftInRight", "0"}, {"rightInRight", "0.75"},
        }, true, true),
        settings(),
        {input1, input2},
        "prepared Channel Crosser");
    requirePreparedMixingParity(
        makeRealtimeChannelCrosserDocument({
            {"leftInLeft", "0.5"}, {"rightInLeft", "1"},
            {"leftInRight", "-0.5"}, {"rightInRight", "1"},
        }, false, false),
        settings(),
        {input1, input2},
        "prepared Channel Crosser missing right input");
    requirePreparedMixingParity(
        makeRealtimeChannelJoinDocument(),
        settings(),
        {input1, input2},
        "prepared Channel Join");
    requirePreparedMixingParity(
        makeRealtimeChannellerDocument(true, false),
        settings(),
        {input1, input2},
        "prepared Channeller left");
    requirePreparedMixingParity(
        makeRealtimeChannellerDocument(false, true),
        settings(),
        {input1, input2},
        "prepared Channeller right");
    requirePreparedMixingParity(
        makeRealtimeChannellerDocument(true, false, true),
        settings(),
        {input1, input2},
        "prepared stereo Channeller left");
    requirePreparedMixingParity(
        makeRealtimeChannellerDocument(false, true, true),
        settings(),
        {input1, input2},
        "prepared stereo Channeller right");
    requirePreparedMixingParity(
        makeRealtimeChannellerDocument(true, true, true),
        settings(),
        {input1, input2},
        "prepared stereo Channeller both");
}

void testRealtimeChannellerLiveSelectorsMatchOfflineAcrossSegments()
{
    auto document = makeRealtimeChannellerDocument(false, true, true);
    document.graph.nodes.push_back(node(
        "leftSelector", "talas.constant", {{"value", "!C49Left"}}));
    document.graph.nodes.push_back(node(
        "rightSelector", "talas.constant", {{"value", "!C49Right"}}));
    document.graph.connections.push_back(connection(
        "leftSelector", "value", "channeller", "leftChannel"));
    document.graph.connections.push_back(connection(
        "rightSelector", "value", "channeller", "rightChannel"));

    constexpr std::array<double, 7> source{
        1.0, -0.5, 0.25, 2.0, -1.0, 0.75, -0.25};
    constexpr std::array<double, 7> rightSource{
        0.5, 1.5, -2.0, -0.75, 3.0, -1.25, 0.125};
    talas::runtime::RenderSettings settings{8.0, 3};
    settings.audioInputChannels = {
        {1, std::vector<double>{source.begin(), source.end()}},
        {2, std::vector<double>{rightSource.begin(), rightSource.end()}},
    };
    settings.eventValues = {
        {"C49Left", -1.0, talas::expr::ValueDomain::Scalar},
        {"C49Right", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "C49Left", 1.0, talas::expr::ValueDomain::Scalar},
        {4, "C49Right", 0.0, talas::expr::ValueDomain::Scalar},
        {5, "C49Left", -0.5, talas::expr::ValueDomain::Scalar},
        {5, "C49Right", 0.25, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(document, settings);
    const auto offline = talas::runtime::renderOffline(graph, source.size());
    // Only the right channel is checked, then both, then only the left,
    // then only the right again.
    require(
        offline.ok()
            && offline.mono
                == std::vector<double>{0.5, 1.5, 0.25, 2.0, -1.0, -1.25, 0.125}
            && offline.right
                == std::vector<double>{0.5, 1.5, -2.0, -0.75, -1.0, -1.25, 0.125},
        "C49 offline live-selector reference should be exact");

    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), "C49 Channeller should prepare: "
        + std::string{session.error()});
    std::array<float, source.size()> realtimeSource{};
    std::ranges::transform(source, realtimeSource.begin(), [](double value) {
        return static_cast<float>(value);
    });
    std::array<float, rightSource.size()> realtimeRightSource{};
    std::ranges::transform(
        rightSource, realtimeRightSource.begin(), [](double value) {
            return static_cast<float>(value);
        });
    std::array<double, source.size()> left{};
    std::array<double, source.size()> right{};
    constexpr std::array<std::size_t, 4> partitions{2, 1, 3, 1};
    std::size_t offset = 0;
    for (const auto partition : partitions)
    {
        const std::array<const float*, 2> inputs{
            realtimeSource.data() + static_cast<std::ptrdiff_t>(offset),
            realtimeRightSource.data() + static_cast<std::ptrdiff_t>(offset)};
        std::size_t allocations = 0;
        require(
            renderStereoInputAndCount(
                session,
                {inputs.data(), inputs.size()},
                std::span<double>{left}.subspan(offset, partition),
                std::span<double>{right}.subspan(offset, partition),
                allocations)
                && allocations == 0,
            "C49 Channeller should render irregular partitions without allocation");
        offset += partition;
    }
    require(
        std::ranges::equal(left, offline.mono)
            && std::ranges::equal(right, offline.right),
        "C49 prepared Channeller should match offline live routing exactly");
}

void testRealtimeChannellerRejectsInvalidLiveSelectorTransaction()
{
    auto document = makeRealtimeChannellerDocument(false, true);
    document.graph.nodes.push_back(node(
        "selectorValue", "talas.constant", {{"value", "!C49Selector"}}));
    document.graph.nodes.push_back(node(
        "selectorScale", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node("selector", "talas.add"));
    document.graph.connections.push_back(connection(
        "selectorValue", "value", "selector", "left"));
    document.graph.connections.push_back(connection(
        "selectorScale", "value", "selector", "right"));
    document.graph.connections.push_back(connection(
        "selector", "value", "channeller", "leftChannel"));

    talas::runtime::RenderSettings settings{8.0, 1};
    settings.eventValues = {{
        "C49Selector", -1.0e308, talas::expr::ValueDomain::Scalar}};
    auto offlineSettings = settings;
    offlineSettings.maxBlockFrames = 2;
    offlineSettings.audioInputChannels = {{1, {1.0, 1.0}}};
    offlineSettings.eventValueChanges = {{
        1, "C49Selector", 1.0e308, talas::expr::ValueDomain::Scalar}};
    const auto offlineGraph = compile(document, offlineSettings);
    const auto offline = talas::runtime::renderOffline(offlineGraph, 2);
    require(
        !offline.ok() && offline.mono.empty() && offline.right.empty(),
        "C49 late non-finite offline selector should publish no stereo prefix");

    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        "C49 invalid-selector fixture should prepare: "
            + std::string{session.error()});
    std::array<float, 1> source{1.0F};
    const std::array<const float*, 1> inputs{source.data()};
    std::array<double, 1> left{7.0};
    std::array<double, 1> right{7.0};
    std::size_t allocations = 0;
    require(
        renderStereoInputAndCount(
            session, {inputs.data(), inputs.size()}, left, right,
            allocations)
            && allocations == 0 && left[0] == 1.0 && right[0] == 1.0,
        "C49 initial finite selector block should use static/live precedence");

    require(
        session.updateEventValue(
            "C49Selector", 1.0e308, talas::expr::ValueDomain::Scalar),
        "C49 finite update that overflows its producer should enqueue");
    const auto checkpoint =
        talas::runtime::RealtimeRenderSessionTestAccess::
            callbackTimelineState(session);
    for (std::size_t attempt = 0; attempt < 2; ++attempt)
    {
        left[0] = 7.0;
        right[0] = 7.0;
        require(
            !renderStereoInputAndCount(
                session, {inputs.data(), inputs.size()}, left, right,
                allocations)
                && allocations == 0
                && left[0] == 0.0
                && right[0] == 0.0
                && talas::runtime::RealtimeRenderSessionTestAccess::
                        callbackTimelineState(session)
                    == checkpoint,
            "C49/C133 non-finite selector producer should repeatedly fail atomically and restore callback state");
    }

    require(
        session.updateEventValue(
            "C49Selector", -1.0e308, talas::expr::ValueDomain::Scalar),
        "C49 corrected selector update should enqueue");
    require(
        renderStereoInputAndCount(
            session, {inputs.data(), inputs.size()}, left, right,
            allocations)
            && allocations == 0 && left[0] == 1.0 && right[0] == 1.0,
        "C49 corrected current-position retry should match the finite route");
}

void testRealtimeChannellerRejectsForgedLiveSelectorAuthority()
{
    auto document = makeRealtimeChannellerDocument(false, true);
    document.graph.nodes.push_back(node(
        "leftSelector", "talas.constant", {{"value", "1"}}));
    document.graph.connections.push_back(connection(
        "leftSelector", "value", "channeller", "leftChannel"));
    const auto compiled = compile(document, {8.0, 1});

    const auto requireRejected = [&](talas::runtime::RuntimePlan plan,
                                     std::string_view context) {
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), compiled.renderSettings()});
        require(
            !session.ready()
                && (session.error().find("Channeller")
                        != std::string_view::npos
                    || session.error().find("stereo-routing")
                        != std::string_view::npos),
            std::string{context}
                + " should reject forged C49 authority: "
                + std::string{session.error()});
    };
    const auto findChanneller = [](talas::runtime::RuntimePlan& plan) {
        return std::ranges::find(
            plan.steps,
            std::string_view{"talas.channeller"},
            &talas::runtime::CompileStep::typeId);
    };

    {
        auto plan = compiled.plan();
        const auto channeller = findChanneller(plan);
        require(channeller != plan.steps.end(),
                "C49 duplicate-binding fixture should expose Channeller");
        const auto selector = std::ranges::find(
            channeller->inputs,
            std::string_view{"leftChannel"},
            &talas::runtime::InputBinding::inputPortId);
        require(
            selector != channeller->inputs.end(),
            "C49 duplicate-binding fixture should expose leftChannel");
        const auto index = static_cast<std::size_t>(
            std::distance(channeller->inputs.begin(), selector));
        channeller->inputs.push_back(*selector);
        channeller->inputLatencyFrames.push_back(
            channeller->inputLatencyFrames[index]);
        requireRejected(std::move(plan), "duplicate left selector binding");
    }
    {
        auto plan = compiled.plan();
        const auto channeller = findChanneller(plan);
        require(channeller != plan.steps.end(),
                "C49 selector-latency fixture should expose Channeller");
        const auto selector = std::ranges::find(
            channeller->inputs,
            std::string_view{"leftChannel"},
            &talas::runtime::InputBinding::inputPortId);
        require(
            selector != channeller->inputs.end(),
            "C49 selector-latency fixture should expose leftChannel");
        const auto index = static_cast<std::size_t>(
            std::distance(channeller->inputs.begin(), selector));
        require(
            index < channeller->inputLatencyFrames.size()
                && !channeller->inputLatencyFrames[index].has_value(),
            "C49 selector-latency fixture should expose resolved latency");
        channeller->inputLatencyFrames[index] = 1;
        requireRejected(std::move(plan), "forged selector input latency");
    }
    {
        auto plan = compiled.plan();
        const auto channeller = findChanneller(plan);
        require(channeller != plan.steps.end(),
                "C49 parameter fixture should expose Channeller");
        const auto left = std::ranges::find(
            channeller->parameters,
            std::string_view{"leftChannel"},
            &talas::runtime::ParameterValue::id);
        require(left != channeller->parameters.end()
                    && left->boolean.has_value(),
                "C49 parameter fixture should expose Boolean fallback");
        left->text = "false";
        requireRejected(std::move(plan), "forged left Boolean fallback");
    }
    {
        auto plan = compiled.plan();
        const auto channeller = findChanneller(plan);
        require(channeller != plan.steps.end(),
                "C49 scope fixture should expose Channeller");
        ++channeller->eventValueScopeId;
        requireRejected(std::move(plan), "forged selector scope");
    }
    {
        auto plan = compiled.plan();
        const auto channeller = findChanneller(plan);
        require(channeller != plan.steps.end(),
                "C49 state fixture should expose Channeller");
        channeller->supportsReset = true;
        requireRejected(std::move(plan), "forged selector state");
    }
}

void testRealtimeChannellerRendersMaximumBlockWithoutAllocations()
{
    auto document = makeRealtimeChannellerDocument(false, true);
    document.graph.nodes.push_back(node(
        "leftSelector", "talas.constant", {{"value", "1"}}));
    document.graph.nodes.push_back(node(
        "rightSelector", "talas.constant", {{"value", "0"}}));
    document.graph.connections.push_back(connection(
        "leftSelector", "value", "channeller", "leftChannel"));
    document.graph.connections.push_back(connection(
        "rightSelector", "value", "channeller", "rightChannel"));

    constexpr std::size_t frameCount = 4096;
    const auto graph = compile(document, {48000.0, frameCount});
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), "C49 maximum Channeller should prepare");
    std::array<float, frameCount> source{};
    for (std::size_t frame = 0; frame < frameCount; ++frame)
        source[frame] = frame % 2 == 0 ? 0.25F : -0.5F;
    const std::array<const float*, 1> inputs{source.data()};
    std::array<double, frameCount> left{};
    std::array<double, frameCount> right{};
    std::size_t allocations = 0;
    require(
        renderStereoInputAndCount(
            session, {inputs.data(), inputs.size()}, left, right,
            allocations)
            && allocations == 0,
        "C49 maximum Channeller callback should render without allocation");
    for (std::size_t frame = 0; frame < frameCount; ++frame)
    {
        require(
            left[frame] == static_cast<double>(source[frame])
                && right[frame] == static_cast<double>(source[frame]),
            "C49 maximum Channeller block should retain exact live routing");
    }
}

void testRealtimeShelvingPresenceFiltersMatchOfflineAcrossPartitions()
{
    const auto requireParity = [](
                                   const talas::project::ProjectDocument& document,
                                   talas::runtime::RenderSettings settings,
                                   std::string_view context) {
        constexpr std::size_t frameCount = 7;
        settings.maxBlockFrames = frameCount;
        auto graph = compile(document, std::move(settings));
        const auto expected = talas::runtime::renderOffline(graph, frameCount);
        require(
            expected.ok() && expected.mono.size() == frameCount,
            std::string{context} + " offline reference should render");

        talas::runtime::RealtimeRenderSession session(graph);
        require(
            session.ready(),
            std::string{context} + " should prepare: "
                + std::string{session.error()});

        std::array<double, frameCount> actual{};
        constexpr std::array<std::size_t, 3> partitions{3, 1, 3};
        std::size_t offset = 0;
        for (const auto partition : partitions)
        {
            std::size_t allocations = 0;
            require(
                renderAndCount(
                    session,
                    std::span<double>{actual}.subspan(offset, partition),
                    allocations),
                std::string{context}
                    + " should render across irregular callback partitions");
            require(
                allocations == 0,
                std::string{context}
                    + " irregular callback should not allocate");
            offset += partition;
        }
        for (std::size_t frame = 0; frame < frameCount; ++frame)
        {
            requireNear(
                actual[frame], expected.mono[frame], 1.0e-12,
                std::string{context} + " parity frame");
        }
    };

    requireParity(
        makeRealtimeShelvingPresenceFilterDocument(
            "talas.highShelvingFilter",
            {{"cutoffFreq", "1 hz"}, {"boostOrCut", "6"}, {"scale", "0.75"}}),
        talas::runtime::RenderSettings{8.0, 7},
        "prepared High Shelving Filter");
    requireParity(
        makeRealtimeShelvingPresenceFilterDocument(
            "talas.lowShelvingFilter",
            {{"cutoffFreq", "1 hz"}, {"boostOrCut", "-6"}, {"scale", "0.5"}}),
        talas::runtime::RenderSettings{8.0, 7},
        "prepared Low Shelving Filter");
    requireParity(
        makeRealtimeShelvingPresenceFilterDocument(
            "talas.presenceFilter",
            {{"centerFreq", "1 hz"}, {"bandwidth", "0.5 hz"},
             {"boostOrCut", "6"}, {"scale", "0.75"}}),
        talas::runtime::RenderSettings{8.0, 7},
        "prepared Presence Filter");
}

