void testRealtimeRemainingCheckedBiquadFamilyMatchesOfflineAcrossPartitions()
{
    const auto requireParity = [](
                                   const talas::project::ProjectDocument& document,
                                   talas::runtime::RenderSettings settings,
                                   std::string_view context) {
        constexpr std::size_t frameCount = 7;
        settings.maxBlockFrames = frameCount;
        auto graph = compile(document, std::move(settings));
        const auto expected = talas::runtime::renderOffline(graph, frameCount);
        require(
            expected.ok() && expected.mono.size() == frameCount,
            std::string{context} + " offline reference should render: "
                + (expected.diagnostics.empty()
                    ? std::string{"missing mono output"}
                    : expected.diagnostics.front().message));

        talas::runtime::RealtimeRenderSession session(graph);
        require(
            session.ready(),
            std::string{context} + " should prepare: "
                + std::string{session.error()});

        std::array<double, frameCount> actualLeft{};
        std::array<double, frameCount> actualRight{};
        constexpr std::array<std::size_t, 3> partitions{3, 1, 3};
        std::size_t offset = 0;
        for (const auto partition : partitions)
        {
            std::size_t allocations = 0;
            const auto rendered = expected.right.empty()
                ? renderAndCount(
                    session,
                    std::span<double>{actualLeft}.subspan(offset, partition),
                    allocations)
                : renderStereoAndCount(
                    session,
                    std::span<double>{actualLeft}.subspan(offset, partition),
                    std::span<double>{actualRight}.subspan(offset, partition),
                    allocations);
            require(
                rendered,
                std::string{context}
                    + " should render across irregular callback partitions");
            require(
                allocations == 0,
                std::string{context} + " callback should not allocate");
            offset += partition;
        }
        for (std::size_t frame = 0; frame < frameCount; ++frame)
        {
            requireNear(
                actualLeft[frame], expected.mono[frame], 1.0e-12,
                std::string{context} + " left parity frame");
            if (!expected.right.empty())
            {
                requireNear(
                    actualRight[frame], expected.right[frame], 1.0e-12,
                    std::string{context} + " right parity frame");
            }
        }
    };

    requireParity(
        makeRealtimeTwoFormantVoiceElementDocument(),
        talas::runtime::RenderSettings{8.0, 7},
        "C17 Two Formant Voice Element");
    requireParity(
        makeRealtimeDualParallelTwoPoleDocument(),
        talas::runtime::RenderSettings{8.0, 7},
        "C17 Dual Parallel Two Pole Filter");
    requireParity(
        makeRealtimeGraphicEqDocument(),
        talas::runtime::RenderSettings{48000.0, 7},
        "C17 Graphic EQ");
    requireParity(
        makeRealtimeAnalysisFilterDocument(),
        talas::runtime::RenderSettings{8.0, 7},
        "C17 Analysis Filter");
}

