void testRealtimePanRendersExactDiscreteLayoutsWithoutAllocations()
{
    const auto run = [](
                         std::size_t channelCount,
                         double position,
                         float inputSample) {
        const auto layout = channelCount == 4
            ? std::string{"discrete4"}
            : std::string{"discrete8"};
        const auto terminalType = channelCount == 4
            ? std::string{"talas.output4"}
            : std::string{"talas.output8"};
        talas::project::ProjectDocument document;
        document.graph.nodes = {
            node("out", terminalType),
            node("pan", "talas.pan", {
                {"pan", std::to_string(position)},
                {"scale", "1"},
                choiceParameter("type", "power"),
                choiceParameter("layout", layout),
            }),
            node("input", "talas.audioInput", {
                booleanParameter("channel1", true),
                booleanParameter("channel2", false),
            }),
        };
        document.graph.connections.push_back(connection(
            "input", "audioOut", "pan", "audioIn"));
        for (std::size_t channel = 0;
             channel < channelCount; ++channel)
        {
            const auto port = "out" + std::to_string(channel + 1);
            document.graph.connections.push_back(connection(
                "pan", port, "out", port));
        }
        const auto graph = compile(document, {8.0, 1});
        talas::runtime::RealtimeRenderSession session(graph);
        const std::array<float, 1> input{inputSample};
        const std::array<const float*, 1> inputs{input.data()};
        std::array<std::array<double, 1>, 8> outputStorage{};
        std::array<double*, 8> outputPointers{};
        for (std::size_t channel = 0;
             channel < channelCount; ++channel)
        {
            outputPointers[channel] = outputStorage[channel].data();
        }
        AllocationCounter counter;
        const auto rendered = session.render(
            {inputs.data(), inputs.size()},
            outputPointers.data(),
            channelCount,
            1);
        const auto allocations = counter.count();
        const auto expected = talas::runtime::equalPowerRingPan(
            position, channelCount);
        require(
            session.ready() && rendered && allocations == 0
                && expected.has_value(),
            "C134 discrete Pan should prepare and render without allocation: "
                + std::string{session.error()});
        for (std::size_t channel = 0;
             channel < channelCount; ++channel)
        {
            const auto expectedSample =
                channel == expected->firstChannel
                ? static_cast<double>(inputSample) * expected->firstGain
                : channel == expected->secondChannel
                    ? static_cast<double>(inputSample) * expected->secondGain
                    : 0.0;
            require(
                outputStorage[channel][0] == expectedSample
                    && (outputStorage[channel][0] != 0.0
                        || std::bit_cast<std::uint64_t>(
                               outputStorage[channel][0])
                            == std::uint64_t{0}),
                "C134 discrete Pan should preserve exact adjacent gains and canonical silent lanes");
        }
    };

    for (const auto position : std::array{0.0, 0.125, 0.875, 1.0})
    {
        run(4, position, 2.0F);
        run(8, position, 2.0F);
        run(4, position, -2.0F);
        run(8, position, -2.0F);
    }
}

void testRealtimeOverlappingMixerPreservesSelectionOrderAndEmptySelection()
{
    constexpr std::array<float, 1> input1{1.0e16F};
    constexpr std::array<float, 1> input2{-1.0e16F};
    constexpr std::array<float, 1> input3{1.0F};
    constexpr std::array<float, 1> input4{0.0F};
    const std::array<const float*, 4> inputs{
        input1.data(), input2.data(), input3.data(), input4.data()};

    const auto render = [&](std::string selection) {
        const auto graph = compile(
            makeRealtimeOverlappingMixerDocument(
                std::move(selection)),
            {4.0, 1});
        talas::runtime::RealtimeRenderSession session(graph);
        std::array<double, 1> left{};
        std::array<double, 1> right{};
        std::size_t allocations = 0;
        require(
            session.ready()
                && renderStereoInputAndCount(
                    session,
                    {inputs.data(), inputs.size()},
                    left,
                    right,
                    allocations)
                && allocations == 0,
            "C23 order-sensitive selection should render without allocation: "
                + std::string{session.error()});
        return std::pair{left[0], right[0]};
    };

    const auto numericOrder = render("in1 in2 in3");
    const auto reordered = render("in1 in3 in2");
    const auto emptySelection = render("");
    require(
        numericOrder == std::pair{0.5, -0.25},
        "C23 numeric selection should preserve the final unit after cancellation");
    require(
        reordered == std::pair{0.0, -0.0}
            && std::signbit(reordered.second),
        "C23 explicit reordered selection should preserve floating-point addition order");
    require(
        emptySelection == numericOrder,
        "C23 empty selection should resolve all connected ports in numeric order");

    talas::project::ProjectDocument silentDocument;
    silentDocument.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("mix", "talas.overlappingMixer", {
            textParameter("legacyInputs", ""),
            {"overlapTime", "0 s"},
            {"left", "1"},
            {"right", "-1"},
            choiceParameter("sequence", "legacyAllAtOnce"),
        }),
    };
    silentDocument.graph.connections = {
        connection("mix", "leftOut", "out", "audioIn"),
        connection("mix", "rightOut", "out", "rightIn"),
    };
    const auto silentGraph = compile(silentDocument, {8.0, 4});
    talas::runtime::RealtimeRenderSession silent(silentGraph);
    std::array<double, 4> silentLeft{1.0, 1.0, 1.0, 1.0};
    std::array<double, 4> silentRight{1.0, 1.0, 1.0, 1.0};
    std::size_t silentAllocations = 0;
    require(
        silent.ready()
            && renderStereoAndCount(
                silent,
                silentLeft,
                silentRight,
                silentAllocations)
            && silentAllocations == 0
            && silentLeft == std::array<double, 4>{}
            && silentRight == std::array<double, 4>{},
        "C23 mixer without connected inputs should prepare allocation-free stereo silence: "
            + std::string{silent.error()});
}

void testRealtimeOverlappingMixerMatchesDirectAndConnectedLiveGains()
{
    constexpr std::array<float, 6> input1{
        1.0F, 2.0F, -3.0F, 4.0F, 5.0F, -6.0F};
    constexpr std::array<float, 6> input2{
        0.5F, -1.0F, 1.5F, -2.0F, 2.5F, -3.0F};
    constexpr std::array<float, 6> input3{
        -4.0F, 3.0F, -2.0F, 1.0F, 0.0F, 5.0F};
    constexpr std::array<float, 6> input4{
        8.0F, -7.0F, 6.0F, -5.0F, 4.0F, -3.0F};
    constexpr std::array borrowedInputs{
        input1, input2, input3, input4};

    const auto requireParity = [&](talas::project::ProjectDocument document,
                                   talas::runtime::RenderSettings settings,
                                   std::string_view context) {
        for (std::size_t channel = 0;
             channel < borrowedInputs.size();
             ++channel)
        {
            settings.audioInputChannels.push_back({
                static_cast<std::uint8_t>(channel + 1),
                std::vector<double>(
                    borrowedInputs[channel].begin(),
                    borrowedInputs[channel].end()),
            });
        }
        const auto graph = compile(document, settings);
        const auto expected = talas::runtime::renderOffline(graph, 6);
        talas::runtime::RealtimeRenderSession session(graph);
        require(
            expected.ok() && session.ready(),
            "C23 live-gain fixture should prepare: "
                + std::string{context} + " "
                + std::string{session.error()});

        std::array<double, 6> left{};
        std::array<double, 6> right{};
        constexpr std::array partitions{
            std::size_t{2}, std::size_t{1}, std::size_t{3}};
        std::size_t offset = 0;
        for (const auto frameCount : partitions)
        {
            std::array<const float*, 4> inputs{};
            for (std::size_t channel = 0;
                 channel < inputs.size();
                 ++channel)
            {
                inputs[channel] =
                    borrowedInputs[channel].data() + offset;
            }
            std::size_t allocations = 0;
            require(
                renderStereoInputAndCount(
                    session,
                    {inputs.data(), inputs.size()},
                    std::span<double>{left}.subspan(
                        offset, frameCount),
                    std::span<double>{right}.subspan(
                        offset, frameCount),
                    allocations)
                    && allocations == 0,
                "C23 partitioned live-gain callback should render without allocation: "
                    + std::string{context});
            offset += frameCount;
        }
        require(
            expected.mono.size() == left.size()
                && expected.right.size() == right.size(),
            "C23 live-gain offline fixture should expose stereo samples");
        for (std::size_t frame = 0; frame < left.size(); ++frame)
        {
            requireNear(
                left[frame], expected.mono[frame], 0.0,
                "C23 live left parity " + std::string{context});
            requireNear(
                right[frame], expected.right[frame], 0.0,
                "C23 live right parity " + std::string{context});
        }
    };

    auto direct = makeRealtimeOverlappingMixerDocument("in4 in2 in1");
    const auto directMixer = std::ranges::find(
        direct.graph.nodes,
        std::string_view{"mix"},
        &talas::project::ProjectNode::instanceId);
    require(
        directMixer != direct.graph.nodes.end(),
        "C23 direct fixture should expose mixer node");
    for (auto& parameter : directMixer->parameters)
    {
        if (parameter.parameterId == "left")
            parameter.expression = "!C23DirectLeft";
        else if (parameter.parameterId == "right")
            parameter.expression = "!C23DirectRight";
    }
    auto directSettings = talas::runtime::RenderSettings{8.0, 6};
    directSettings.eventValues.push_back({
        "C23DirectLeft", 0.5,
        talas::expr::ValueDomain::Scalar});
    directSettings.eventValues.push_back({
        "C23DirectRight", -0.25,
        talas::expr::ValueDomain::Scalar});
    directSettings.eventValueChanges.push_back({
        3,
        "C23DirectLeft",
        -1.0,
        talas::expr::ValueDomain::Scalar,
    });
    directSettings.eventValueChanges.push_back({
        3,
        "C23DirectRight",
        0.75,
        talas::expr::ValueDomain::Scalar,
    });
    requireParity(
        std::move(direct),
        std::move(directSettings),
        "direct Event Values");

    auto connected = makeRealtimeOverlappingMixerDocument("in4 in2 in1");
    connected.graph.nodes.push_back(node(
        "leftGain", "talas.constant", {
            {"value", "!C23ConnectedLeft"},
        }));
    connected.graph.nodes.push_back(node(
        "rightGain", "talas.constant", {
            {"value", "!C23ConnectedRight"},
        }));
    connected.graph.connections.push_back(connection(
        "leftGain", "value", "mix", "left"));
    connected.graph.connections.push_back(connection(
        "rightGain", "value", "mix", "right"));
    auto connectedSettings = talas::runtime::RenderSettings{8.0, 6};
    connectedSettings.eventValues.push_back({
        "C23ConnectedLeft", 0.5,
        talas::expr::ValueDomain::Scalar});
    connectedSettings.eventValues.push_back({
        "C23ConnectedRight", -0.25,
        talas::expr::ValueDomain::Scalar});
    connectedSettings.eventValueChanges.push_back({
        3,
        "C23ConnectedLeft",
        -1.0,
        talas::expr::ValueDomain::Scalar,
    });
    connectedSettings.eventValueChanges.push_back({
        3,
        "C23ConnectedRight",
        0.75,
        talas::expr::ValueDomain::Scalar,
    });
    requireParity(
        std::move(connected),
        std::move(connectedSettings),
        "connected Event Values");
}

void testRealtimeOverlappingMixerKeepsNestedScopeAuthority()
{
    auto settings = talas::runtime::RenderSettings{8.0, 7};
    settings.eventValues.push_back({
        "C23NestedLeft", 0.75,
        talas::expr::ValueDomain::Scalar});
    const auto graph = compile(
        makeNestedRealtimeOverlappingMixerDocument(),
        settings);
    std::vector<talas::runtime::RuntimeScopeId> scopes;
    for (const auto& step : graph.plan().steps)
    {
        if (step.typeId != "talas.overlappingMixer")
            continue;
        require(
            step.scopeId != talas::runtime::globalRuntimeScope
                && step.eventValueScopeId == step.scopeId,
            "C23 nested mixer should retain exact local Event Value scope authority");
        scopes.push_back(step.scopeId);
    }

    const auto expected = talas::runtime::renderOffline(graph, 7);
    talas::runtime::RealtimeRenderSession session(graph);
    std::array<double, 7> left{};
    std::array<double, 7> right{};
    std::size_t allocations = 0;
    require(
        scopes.size() == 2
            && scopes[0] != scopes[1]
            && expected.ok()
            && session.ready()
            && renderStereoAndCount(
                session, left, right, allocations)
            && allocations == 0,
        "C23 nested sibling mixers should prepare and render independently: "
            + std::string{session.error()});
    for (std::size_t frame = 0; frame < left.size(); ++frame)
    {
        requireNear(
            left[frame], expected.mono[frame], 0.0,
            "C23 nested left scope parity");
        requireNear(
            right[frame], expected.right[frame], 0.0,
            "C23 nested right scope parity");
    }
}

void testRealtimeOverlappingMixerRollsBackInvalidLaterGainAndInput()
{
    talas::project::ProjectDocument oscillatorDocument;
    oscillatorDocument.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("mix", "talas.overlappingMixer", {
            textParameter("legacyInputs", "in1 in2"),
            {"overlapTime", "0 s"},
            {"left", "0.5"},
            {"right", "-0.25"},
            choiceParameter("sequence", "legacyAllAtOnce"),
        }),
        node("in1", "talas.oscillator", {
            {"frequency", "1 hz"}, {"amplitude", "0.5"},
        }),
        node("in2", "talas.oscillator", {
            {"frequency", "0.5 hz"}, {"amplitude", "0.25"},
        }),
        node("leftGain", "talas.constant", {
            {"value", "!C23RollbackGain"},
        }),
    };
    oscillatorDocument.graph.connections = {
        connection("in1", "audioOut", "mix", "in1"),
        connection("in2", "audioOut", "mix", "in2"),
        connection("leftGain", "value", "mix", "left"),
        connection("mix", "leftOut", "out", "audioIn"),
        connection("mix", "rightOut", "out", "rightIn"),
    };
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.eventValues.push_back({
        "C23RollbackGain", 0.5,
        talas::expr::ValueDomain::Scalar});
    const auto graph = compile(oscillatorDocument, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(
        candidate.ready() && reference.ready()
            && candidate.scheduleEventValue(
                "C23RollbackGain",
                1.25,
                talas::expr::ValueDomain::Scalar,
                2),
        "C23 rollback fixture should schedule a later bounded-gain failure");

    std::array<double, 4> failedLeft{1.0, 1.0, 1.0, 1.0};
    std::array<double, 4> failedRight{1.0, 1.0, 1.0, 1.0};
    std::size_t allocations = 0;
    require(
        !renderStereoAndCount(
            candidate, failedLeft, failedRight, allocations)
            && allocations == 0
            && failedLeft == std::array<double, 4>{}
            && failedRight == std::array<double, 4>{},
        "C23 later gain failure should publish neither stereo channel");
    require(
        candidate.updateEventValue(
            "C23RollbackGain",
            0.5,
            talas::expr::ValueDomain::Scalar),
        "C23 failed callback should recover to a valid connected gain");

    std::array<double, 4> candidateLeft{};
    std::array<double, 4> candidateRight{};
    std::array<double, 4> referenceLeft{};
    std::array<double, 4> referenceRight{};
    require(
        renderStereoAndCount(
            candidate,
            candidateLeft,
            candidateRight,
            allocations)
            && allocations == 0
            && renderStereoAndCount(
                reference,
                referenceLeft,
                referenceRight,
                allocations)
            && allocations == 0
            && candidateLeft == referenceLeft
            && candidateRight == referenceRight,
        "C23 failed callback should restore both oscillator phases exactly");

    const auto borrowedGraph = compile(
        makeRealtimeOverlappingMixerDocument("in1 in2"),
        {8.0, 4});
    talas::runtime::RealtimeRenderSession borrowed(borrowedGraph);
    std::array<float, 4> validInput{
        1.0F, 2.0F, 3.0F, 4.0F};
    std::array<float, 4> invalidInput{
        0.5F,
        1.0F,
        std::numeric_limits<float>::infinity(),
        2.0F};
    std::array<float, 4> unusedInput{};
    std::array<const float*, 4> borrowedInputs{
        validInput.data(), invalidInput.data(),
        unusedInput.data(), unusedInput.data()};
    failedLeft.fill(1.0);
    failedRight.fill(1.0);
    require(
        borrowed.ready()
            && !renderStereoInputAndCount(
                borrowed,
                {borrowedInputs.data(), borrowedInputs.size()},
                failedLeft,
                failedRight,
                allocations)
            && allocations == 0
            && failedLeft == std::array<double, 4>{}
            && failedRight == std::array<double, 4>{},
        "C23 later non-finite selected input should fail the complete callback atomically");

    talas::runtime::RealtimeRenderSession unselected(borrowedGraph);
    std::array<float, 4> nonFiniteUnselected{
        std::numeric_limits<float>::infinity(),
        std::numeric_limits<float>::quiet_NaN(),
        -std::numeric_limits<float>::infinity(),
        std::numeric_limits<float>::quiet_NaN()};
    std::array<const float*, 4> unselectedInputs{
        validInput.data(), validInput.data(),
        nonFiniteUnselected.data(), nonFiniteUnselected.data()};
    failedLeft.fill(0.0);
    failedRight.fill(0.0);
    require(
        unselected.ready()
            && renderStereoInputAndCount(
                unselected,
                {unselectedInputs.data(), unselectedInputs.size()},
                failedLeft,
                failedRight,
                allocations)
            && allocations == 0
            && std::ranges::all_of(failedLeft, [](double sample) {
                   return std::isfinite(sample);
               })
            && std::ranges::all_of(failedRight, [](double sample) {
                   return std::isfinite(sample);
               }),
        "C23 explicit selection should ignore non-finite samples on unselected connected ports");

    talas::project::ProjectDocument partialStereoDocument;
    partialStereoDocument.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("mix", "talas.overlappingMixer", {
            textParameter("legacyInputs", "in1"),
            {"overlapTime", "0 s"},
            {"left", "0.5"},
            {"right", "-0.25"},
            choiceParameter("sequence", "legacyAllAtOnce"),
        }),
        node("input", "talas.audioInput", {
            choiceParameter("routing", "stereoPair"),
            booleanParameter("channel1", true),
            booleanParameter("channel2", true),
        }),
    };
    partialStereoDocument.graph.connections = {
        connection("input", "audioOut", "mix", "in1"),
        connection("input", "rightOut", "mix", "in2"),
        connection("mix", "leftOut", "out", "audioIn"),
        connection("mix", "rightOut", "out", "rightIn"),
    };
    const auto partialStereoGraph = compile(
        partialStereoDocument, {8.0, 4});
    talas::runtime::RealtimeRenderSession partialStereo(
        partialStereoGraph);
    std::array<float, 4> selectedStereoChannel{
        1.0F, -2.0F, 3.0F, -4.0F};
    std::array<float, 4> unselectedStereoChannel{
        std::numeric_limits<float>::quiet_NaN(),
        std::numeric_limits<float>::infinity(),
        -std::numeric_limits<float>::infinity(),
        std::numeric_limits<float>::quiet_NaN()};
    const std::array<const float*, 2> partialStereoInputs{
        selectedStereoChannel.data(),
        unselectedStereoChannel.data()};
    std::array<double, 4> partialStereoLeft{};
    std::array<double, 4> partialStereoRight{};
    require(
        partialStereo.ready()
            && renderStereoInputAndCount(
                partialStereo,
                {partialStereoInputs.data(), partialStereoInputs.size()},
                partialStereoLeft,
                partialStereoRight,
                allocations)
            && allocations == 0
            && partialStereoLeft
                == std::array<double, 4>{0.5, -1.0, 1.5, -2.0}
            && partialStereoRight
                == std::array<double, 4>{-0.25, 0.5, -0.75, 1.0},
        "C23 should ignore non-finite samples on only the explicitly unselected stereoPair output");

    auto sharedStereoDocument = partialStereoDocument;
    sharedStereoDocument.graph.connections.erase(
        std::remove_if(
            sharedStereoDocument.graph.connections.begin(),
            sharedStereoDocument.graph.connections.end(),
            [](const talas::core::Connection& candidate) {
                return candidate.fromNode == "mix"
                    && candidate.fromPort == "rightOut"
                    && candidate.toNode == "out";
            }),
        sharedStereoDocument.graph.connections.end());
    sharedStereoDocument.graph.connections.push_back(connection(
        "input", "rightOut", "out", "rightIn"));
    const auto sharedStereoGraph = compile(
        sharedStereoDocument, {8.0, 4});
    talas::runtime::RealtimeRenderSession sharedStereo(sharedStereoGraph);
    partialStereoLeft.fill(1.0);
    partialStereoRight.fill(1.0);
    require(
        sharedStereo.ready()
            && !renderStereoInputAndCount(
                sharedStereo,
                {partialStereoInputs.data(), partialStereoInputs.size()},
                partialStereoLeft,
                partialStereoRight,
                allocations)
            && allocations == 0
            && partialStereoLeft == std::array<double, 4>{}
            && partialStereoRight == std::array<double, 4>{},
        "C23 should retain finite validation when an unselected stereoPair output has another live consumer");

    auto probedDocument = partialStereoDocument;
    probedDocument.graph.nodes.push_back(node(
        "ignored", "talas.audioInput", {
            choiceParameter("routing", "stereoPair"),
            booleanParameter("channel1", false),
            booleanParameter("channel2", true),
            booleanParameter("channel3", true),
        }));
    probedDocument.graph.connections.push_back(connection(
        "ignored", "audioOut", "mix", "in3"));
    probedDocument.graph.connections.push_back(connection(
        "ignored", "rightOut", "mix", "in4"));
    auto probedSettings = talas::runtime::RenderSettings{8.0, 4};
    probedSettings.enableRealtimeAnalysisCapture = true;
    probedSettings.realtimeAnalysisTargets.push_back({
        {},
        {},
        "ignored",
        "rightOut",
        talas::runtime::RealtimeAnalysisKind::Oscilloscope,
        talas::runtime::RealtimeAnalysisPayloadKind::AudioBlock,
        1,
        "c23-unselected-right",
    });
    const auto probedGraph = compile(
        probedDocument, std::move(probedSettings));
    talas::runtime::RealtimeRenderSession probed(probedGraph);
    std::array<float, 4> ignoredFiniteChannel{};
    const std::array<const float*, 3> probedInputs{
        selectedStereoChannel.data(),
        ignoredFiniteChannel.data(),
        unselectedStereoChannel.data()};
    partialStereoLeft.fill(1.0);
    partialStereoRight.fill(1.0);
    require(
        probed.ready()
            && !renderStereoInputAndCount(
                probed,
                {probedInputs.data(), probedInputs.size()},
                partialStereoLeft,
                partialStereoRight,
                allocations)
            && allocations == 0
            && partialStereoLeft == std::array<double, 4>{}
            && partialStereoRight == std::array<double, 4>{},
        "C23 should retain finite validation for an analysis-probed unselected AudioInput output");

    auto downstreamDocument = oscillatorDocument;
    downstreamDocument.graph.nodes.push_back(node(
        "formants", "talas.twoFormantElement", {
            {"formant1", "1 hz"},
            {"bandwidth1", "0.5 hz"},
            {"scale1", "0.75"},
            {"formant2", "2 hz"},
            {"bandwidth2", "0.75 hz"},
            {"scale2", "-0.25"},
        }));
    downstreamDocument.graph.nodes.push_back(node(
        "formantControl", "talas.constant", {
            {"value", "!C23DownstreamFormant"},
        }));
    downstreamDocument.graph.connections.erase(
        std::remove_if(
            downstreamDocument.graph.connections.begin(),
            downstreamDocument.graph.connections.end(),
            [](const talas::core::Connection& candidate) {
                return candidate.fromNode == "mix"
                    && candidate.fromPort == "leftOut"
                    && candidate.toNode == "out";
            }),
        downstreamDocument.graph.connections.end());
    downstreamDocument.graph.connections.push_back(connection(
        "mix", "leftOut", "formants", "audioIn"));
    downstreamDocument.graph.connections.push_back(connection(
        "formantControl", "value", "formants", "formant1"));
    downstreamDocument.graph.connections.push_back(connection(
        "formants", "audioOut", "out", "audioIn"));

    auto downstreamSettings = settings;
    downstreamSettings.eventValues.push_back({
        "C23DownstreamFormant", 1.0,
        talas::expr::ValueDomain::Scalar});
    const auto downstreamGraph = compile(
        downstreamDocument, downstreamSettings);
    talas::runtime::RealtimeRenderSession downstreamCandidate(
        downstreamGraph);
    talas::runtime::RealtimeRenderSession downstreamReference(
        downstreamGraph);
    require(
        downstreamCandidate.ready()
            && downstreamReference.ready()
            && downstreamCandidate.scheduleEventValue(
                "C23DownstreamFormant",
                4.0,
                talas::expr::ValueDomain::Scalar,
                2),
        "C23 downstream rollback fixture should prepare and segment");
    failedLeft.fill(1.0);
    failedRight.fill(1.0);
    require(
        !renderStereoAndCount(
            downstreamCandidate,
            failedLeft,
            failedRight,
            allocations)
            && allocations == 0
            && failedLeft == std::array<double, 4>{}
            && failedRight == std::array<double, 4>{},
        "C23 downstream checked failure should publish neither stereo channel");
    require(
        downstreamCandidate.updateEventValue(
            "C23DownstreamFormant",
            1.0,
            talas::expr::ValueDomain::Scalar),
        "C23 downstream control should recover after callback failure");
    candidateLeft.fill(0.0);
    candidateRight.fill(0.0);
    referenceLeft.fill(0.0);
    referenceRight.fill(0.0);
    require(
        renderStereoAndCount(
            downstreamCandidate,
            candidateLeft,
            candidateRight,
            allocations)
            && allocations == 0
            && renderStereoAndCount(
                downstreamReference,
                referenceLeft,
                referenceRight,
                allocations)
            && allocations == 0
            && candidateLeft == referenceLeft
            && candidateRight == referenceRight,
        "C23 downstream failure should restore oscillator and checked successor state exactly");
}

void testRealtimeOverlappingMixerRejectsForgedAuthorityAndAcceptsCheckpointedNeighbors()
{
    const auto compiled = compile(
        makeRealtimeOverlappingMixerDocument(),
        {8.0, 4});
    const auto requireRejected = [&](talas::runtime::RuntimePlan plan,
                                     std::string_view context) {
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), compiled.renderSettings()});
        require(
            !session.ready(),
            "C23 forged authority should reject "
                + std::string{context});
    };
    const auto mutateMixer = [&](auto mutate,
                                 std::string_view context) {
        auto plan = compiled.plan();
        const auto mixer = std::ranges::find(
            plan.steps,
            std::string_view{"talas.overlappingMixer"},
            &talas::runtime::CompileStep::typeId);
        require(
            mixer != plan.steps.end(),
            "C23 forged-authority fixture should expose Overlapping Mixer");
        mutate(plan, *mixer);
        requireRejected(std::move(plan), context);
    };

    mutateMixer(
        [](auto&, auto& mixer) {
            mixer.preparedRealtimeSupport =
                talas::core::ExecutionSupport::Supported;
        },
        "full support");
    mutateMixer(
        [](auto&, auto& mixer) {
            mixer.preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
        },
        "kernel binding");
    mutateMixer(
        [](auto&, auto& mixer) { mixer.supportsReset = true; },
        "state reset");
    mutateMixer(
        [](auto&, auto& mixer) { ++mixer.eventValueScopeId; },
        "Event Value scope");
    mutateMixer(
        [](auto&, auto& mixer) {
            mixer.resolvedLatencyFrames.reset();
        },
        "missing intrinsic latency");
    mutateMixer(
        [](auto&, auto& mixer) {
            mixer.cumulativeOutputLatencyFrames = 1;
        },
        "forged cumulative output latency");
    mutateMixer(
        [](auto& plan, auto& mixer) {
            const auto selected = std::ranges::find(
                mixer.inputs,
                std::string_view{"in3"},
                &talas::runtime::InputBinding::inputPortId);
            require(
                selected != mixer.inputs.end(),
                "C23 latency forge should expose selected in3");
            const auto source = std::ranges::find_if(
                plan.steps,
                [&](const talas::runtime::CompileStep& candidate) {
                    return candidate.nodeId == selected->sourceNodeId
                        && candidate.scopeId == selected->sourceScopeId;
                });
            require(
                source != plan.steps.end(),
                "C23 latency forge should expose selected ancestry");
            const auto inputIndex = static_cast<std::size_t>(
                selected - mixer.inputs.begin());
            source->resolvedLatencyFrames = 1;
            source->cumulativeInputLatencyFrames = 0;
            source->cumulativeOutputLatencyFrames = 1;
            mixer.inputLatencyFrames[inputIndex] = 1;
            mixer.cumulativeInputLatencyFrames = 1;
            mixer.cumulativeOutputLatencyFrames = 1;
        },
        "coherently forged selected-input ancestry latency");
    mutateMixer(
        [](auto&, auto& mixer) {
            mixer.parameters[0].text = "in1 in1";
        },
        "duplicate text selection");
    mutateMixer(
        [](auto&, auto& mixer) {
            mixer.parameters[0].domain =
                talas::expr::ValueDomain::Seconds;
        },
        "inputs text domain");
    mutateMixer(
        [](auto&, auto& mixer) {
            mixer.parameters[0].value = 1.0;
        },
        "inputs text numeric value");
    mutateMixer(
        [](auto&, auto& mixer) {
            mixer.parameters[0].choice = "in3";
        },
        "inputs text choice payload");
    mutateMixer(
        [](auto&, auto& mixer) {
            mixer.parameters[1].domain =
                talas::expr::ValueDomain::Scalar;
        },
        "overlap domain");
    mutateMixer(
        [](auto&, auto& mixer) {
            mixer.parameters[2].expression.reset();
        },
        "missing left expression");
    mutateMixer(
        [](auto&, auto& mixer) {
            mixer.parameters[3].value = 0.5;
        },
        "right expression value mismatch");
    mutateMixer(
        [](auto&, auto& mixer) {
            std::swap(mixer.parameters[0], mixer.parameters[1]);
        },
        "parameter order");
    mutateMixer(
        [](auto&, auto& mixer) {
            require(
                mixer.inputs.size() >= 2,
                "C23 input-order forge requires two inputs");
            std::swap(mixer.inputs[0], mixer.inputs[1]);
        },
        "input binding order");
    mutateMixer(
        [](auto& plan, auto& mixer) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == mixer.nodeId
                        && buffer.scopeId == mixer.scopeId
                        && buffer.portId == "leftOut";
                });
            require(
                output != plan.buffers.end(),
                "C23 duplicate-output forge should expose leftOut");
            plan.buffers.push_back(*output);
        },
        "duplicate output ownership");
    mutateMixer(
        [](auto&, auto& mixer) {
            const auto selected = std::ranges::find(
                mixer.inputs,
                std::string_view{"in3"},
                &talas::runtime::InputBinding::inputPortId);
            require(
                selected != mixer.inputs.end(),
                "C23 selected-producer forge should expose in3");
            selected->sourceNodeId = "forgedSource";
        },
        "selected producer");
    mutateMixer(
        [](auto&, auto& mixer) {
            mixer.soundVariableCellIndex = 0;
        },
        "ancillary playback state");

    {
        auto settings = talas::runtime::RenderSettings{8.0, 4};
        settings.eventValues.push_back({
            "C23NestedLeft", 0.75,
            talas::expr::ValueDomain::Scalar});
        const auto nestedCompiled = compile(
            makeNestedRealtimeOverlappingMixerDocument(),
            settings);
        auto nestedPlan = nestedCompiled.plan();
        const auto nestedMixer = std::ranges::find_if(
            nestedPlan.steps,
            [](const talas::runtime::CompileStep& step) {
                return step.typeId == "talas.overlappingMixer"
                    && step.scopeId
                        != talas::runtime::globalRuntimeScope;
            });
        require(
            nestedMixer != nestedPlan.steps.end()
                && nestedMixer->parameters[0].variableScopeId
                    == talas::runtime::globalRuntimeScope,
            "C23 nested compiler fixture should keep static text in global variable scope");
        nestedMixer->parameters[0].variableScopeId =
            nestedMixer->scopeId;
        talas::runtime::RealtimeRenderSession forgedNestedScope(
            talas::runtime::PreparedRuntimeGraph{
                std::move(nestedPlan), settings});
        require(
            !forgedNestedScope.ready(),
            "C23 should reject a nested inputs text parameter with forged local variable scope");
    }

    auto predecessorDocument =
        makeRealtimeOverlappingMixerDocument();
    predecessorDocument.graph.nodes.push_back(node(
        "lowPassGate", "talas.lowPassGate", lowPassGateParameters()));
    predecessorDocument.graph.connections.erase(
        std::remove_if(
            predecessorDocument.graph.connections.begin(),
            predecessorDocument.graph.connections.end(),
            [](const talas::core::Connection& candidate) {
                return candidate.fromNode == "in3"
                    && candidate.toNode == "mix";
            }),
        predecessorDocument.graph.connections.end());
    predecessorDocument.graph.connections.push_back(connection(
        "in3", "audioOut", "lowPassGate", "audioIn"));
    predecessorDocument.graph.connections.push_back(connection(
        "lowPassGate", "audioOut", "mix", "in3"));
    const auto predecessorGraph = compile(
        predecessorDocument, {8.0, 4});
    talas::runtime::RealtimeRenderSession predecessor(predecessorGraph);
    require(
        predecessor.ready(),
        "C103 Low-Pass Gate should provide dedicated checkpoint coverage as an Overlapping Mixer predecessor: "
            + std::string{predecessor.error()});

    auto successorDocument =
        makeRealtimeOverlappingMixerDocument();
    successorDocument.graph.nodes.push_back(node(
        "lowPassGate", "talas.lowPassGate", lowPassGateParameters()));
    successorDocument.graph.connections.erase(
        std::remove_if(
            successorDocument.graph.connections.begin(),
            successorDocument.graph.connections.end(),
            [](const talas::core::Connection& candidate) {
                return candidate.fromNode == "mix"
                    && candidate.fromPort == "leftOut"
                    && candidate.toNode == "out";
            }),
        successorDocument.graph.connections.end());
    successorDocument.graph.connections.push_back(connection(
        "mix", "leftOut", "lowPassGate", "audioIn"));
    successorDocument.graph.connections.push_back(connection(
        "lowPassGate", "audioOut", "out", "audioIn"));
    const auto successorGraph = compile(
        successorDocument, {8.0, 4});
    talas::runtime::RealtimeRenderSession successor(successorGraph);
    require(
        successor.ready(),
        "C103 Low-Pass Gate should provide dedicated checkpoint coverage as an Overlapping Mixer successor: "
            + std::string{successor.error()});
}

void testRealtimeQuadOscillatorSumsSeparateEnvelopesWithoutAllocations()
{
    const auto graph = compile(
        makeRealtimeQuadOscillatorDocument(true),
        {4.0, 4});
    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        "C22 Quad Oscillator should prepare exact stereo Audio Input ancestry: "
            + std::string{session.error()});

    std::array<float, 4> leftEnvelope{1.0F, 0.5F, 2.0F, 0.25F};
    std::array<float, 4> rightEnvelope{0.5F, 1.0F, 0.25F, 2.0F};
    std::array<const float*, 2> inputs{
        leftEnvelope.data(), rightEnvelope.data()};
    std::array<double, 4> left{};
    std::array<double, 4> right{};
    std::size_t allocations = 0;
    require(
        renderStereoInputAndCount(
            session,
            {inputs.data(), inputs.size()},
            left,
            right,
            allocations),
        "C22 Quad Oscillator should render a borrowed stereo callback");
    require(
        allocations == 0,
        "C22 Quad Oscillator callback should not allocate");

    // The output is the sum of the
    // sine-modulated left and cosine-modulated right Envelope channels.
    constexpr std::array expectedLeft{0.5, 0.5, -0.25, -0.25};
    constexpr auto expectedRight = expectedLeft;
    for (std::size_t frame = 0; frame < left.size(); ++frame)
    {
        requireNear(
            left[frame], expectedLeft[frame], 1.0e-12,
            "C22 Quad Oscillator left quadrature frame "
                + std::to_string(frame));
        requireNear(
            right[frame], expectedRight[frame], 1.0e-12,
            "C22 Quad Oscillator right quadrature frame "
                + std::to_string(frame));
    }
}

void testRealtimeQuadOscillatorCancelsTheOppositeSideband()
{
    // cos(a) sin(b) + sin(a) cos(b) = sin(a + b). The documented
    // negative carrier selects the difference frequency without a mixer.
    constexpr std::size_t frames = 128;
    constexpr double sampleRate = 64.0, envelopeFrequency = 3.0;
    std::array<float, frames> leftEnvelope{}, rightEnvelope{};
    for (std::size_t frame = 0; frame < frames; ++frame)
    {
        const auto angle = 2 * std::numbers::pi * envelopeFrequency * frame / sampleRate;
        leftEnvelope[frame] = static_cast<float>(std::cos(angle));
        rightEnvelope[frame] = static_cast<float>(std::sin(angle));
    }
    for (const auto carrier : {8.0, -8.0})
    {
        auto settings = talas::runtime::RenderSettings{sampleRate, 31};
        settings.audioInputChannels = {
            {1, std::vector<double>(leftEnvelope.begin(), leftEnvelope.end())},
            {2, std::vector<double>(rightEnvelope.begin(), rightEnvelope.end())},
        };
        const auto graph = compile(makeRealtimeQuadOscillatorDocument(
            true, std::to_string(carrier) + " hz"), settings);
        const auto offline = talas::runtime::renderOffline(graph, frames);
        require(offline.ok(), "documented quadrature sideband sum renders offline");
        std::array<double, frames> expected{};
        for (std::size_t frame = 0; frame < frames; ++frame)
        {
            expected[frame] = std::sin(2 * std::numbers::pi
                * (envelopeFrequency + carrier) * frame / sampleRate);
            requireNear(offline.mono[frame], expected[frame], 1.0e-7,
                "documented sum cancels the opposite offline sideband");
            requireNear(offline.right[frame], offline.mono[frame], 0.0,
                "the compatibility right port mirrors the summed mono output");
        }
        for (const auto block : {1U, 7U, 31U})
        {
            talas::runtime::RealtimeRenderSession session(graph);
            require(session.ready(), std::string(session.error()));
            std::array<double, frames> left{}, right{};
            for (std::size_t offset = 0; offset < frames; offset += block)
            {
                const auto count = std::min<std::size_t>(block, frames - offset);
                const std::array<const float*, 2> inputs{
                    leftEnvelope.data() + offset, rightEnvelope.data() + offset};
                std::size_t allocations = 0;
                require(renderStereoInputAndCount(session, {inputs.data(), inputs.size()},
                        std::span(left).subspan(offset, count), std::span(right).subspan(offset, count), allocations)
                        && allocations == 0,
                    "documented sideband sum renders without callback allocation");
            }
            for (std::size_t frame = 0; frame < frames; ++frame)
            {
                requireNear(left[frame], expected[frame], 1.0e-7,
                    "prepared sum cancels the opposite sideband across partitions");
                requireNear(left[frame], offline.mono[frame], 1.0e-12,
                    "both backends produce the same summed signal");
                requireNear(right[frame], left[frame], 0.0,
                    "prepared compatibility port mirrors the summed mono output");
            }
        }
    }
}

void testCheckedQuadOscillatorMathRejectsBeforeCommit()
{
    using namespace talas::runtime::checked_quad_oscillator;

    auto rendered = Frame{11.0, 12.0, 13.0};
    require(
        processSample(4.0, 0.0, 2.0, 0.5, 1.0, rendered),
        "C22 checked quadrature transition should accept the frozen profile");
    requireNear(rendered.left, 0.5, 0.0, "C22 checked summed output at phase zero");
    requireNear(rendered.right, 0.5, 0.0, "C22 checked right phase zero");
    requireNear(
        rendered.nextPhase,
        twoPi * 1.0 / 4.0,
        0.0,
        "C22 checked phase increment order");

    const auto sentinel = Frame{11.0, 12.0, 13.0};
    const auto requireRejectedWithoutCommit = [&](double sampleRate,
                                                   double phase,
                                                   double leftEnvelope,
                                                   double rightEnvelope,
                                                   double frequency,
                                                   std::string_view context) {
        auto candidate = sentinel;
        require(
            !processSample(
                sampleRate,
                phase,
                leftEnvelope,
                rightEnvelope,
                frequency,
                candidate)
                && candidate.left == sentinel.left
                && candidate.right == sentinel.right
                && candidate.nextPhase == sentinel.nextPhase,
            "C22 checked quadrature should reject before commit: "
                + std::string{context});
    };
    requireRejectedWithoutCommit(
        4.0, 0.0, 1.0, 1.0, 2.0,
        "positive Nyquist edge");
    requireRejectedWithoutCommit(
        4.0, 0.0, 1.0, 1.0, -2.0,
        "negative Nyquist edge");
    requireRejectedWithoutCommit(
        4.0,
        0.0,
        std::numeric_limits<double>::infinity(),
        1.0,
        1.0,
        "non-finite left envelope");
    requireRejectedWithoutCommit(
        4.0, twoPi / 8.0,
        std::numeric_limits<double>::max(),
        std::numeric_limits<double>::max(), 0.0,
        "finite quadrature products whose sum overflows");
    requireRejectedWithoutCommit(
        std::numeric_limits<double>::max(),
        0.0,
        1.0,
        1.0,
        std::numeric_limits<double>::max() * 0.25,
        "concealed phase-increment product overflow");
}

void testRealtimeQuadOscillatorMatchesOfflineAcrossPartitionsAndSignedFrequency()
{
    constexpr std::array frequencies{
        std::string_view{"1 hz"},
        std::string_view{"-1 hz"},
        std::string_view{"0 hz"},
    };
    constexpr std::array<float, 9> borrowedEnvelope{
        1.0F, 0.5F, -0.25F, 2.0F, 0.0F,
        0.75F, -1.0F, 0.25F, 1.5F};
    for (const auto frequency : frequencies)
    {
        auto settings = talas::runtime::RenderSettings{8.0, 9};
        settings.audioInputChannels.push_back({
            1,
            std::vector<double>(
                borrowedEnvelope.begin(), borrowedEnvelope.end()),
        });
        const auto graph = compile(
            makeRealtimeQuadOscillatorDocument(
                false, std::string{frequency}),
            settings);
        const auto expected = talas::runtime::renderOffline(graph, 9);
        talas::runtime::RealtimeRenderSession session(graph);
        require(
            expected.ok() && session.ready(),
            "C22 signed/zero partition fixture should prepare: "
                + std::string{frequency} + " "
                + std::string{session.error()});

        std::array<double, 9> left{};
        std::array<double, 9> right{};
        constexpr std::array partitions{
            std::size_t{2}, std::size_t{3}, std::size_t{4}};
        std::size_t offset = 0;
        for (const auto frameCount : partitions)
        {
            std::array<const float*, 1> inputs{
                borrowedEnvelope.data() + offset};
            std::size_t allocations = 0;
            require(
                renderStereoInputAndCount(
                    session,
                    {inputs.data(), inputs.size()},
                    std::span<double>{left}.subspan(offset, frameCount),
                    std::span<double>{right}.subspan(offset, frameCount),
                    allocations)
                    && allocations == 0,
                "C22 partitioned signed/zero callback should render without allocation: "
                    + std::string{frequency});
            offset += frameCount;
        }
        require(expected.mono.size() == left.size()
                && expected.right.size() == right.size(),
            "C22 offline quadrature fixture should expose stereo samples");
        for (std::size_t frame = 0; frame < left.size(); ++frame)
        {
            requireNear(
                left[frame], expected.mono[frame], 1.0e-12,
                "C22 partitioned left parity " + std::string{frequency});
            requireNear(
                right[frame], expected.right[frame], 1.0e-12,
                "C22 partitioned right parity " + std::string{frequency});
        }
    }
}

void testRealtimeQuadOscillatorMatchesDirectAndConnectedEventValues()
{
    const auto requireParity = [](talas::project::ProjectDocument document,
                                  talas::runtime::RenderSettings settings,
                                  std::string_view context) {
        constexpr std::array<float, 6> borrowedEnvelope{
            1.0F, 0.5F, 1.5F, -0.25F, 0.75F, 2.0F};
        settings.audioInputChannels.push_back({
            1,
            std::vector<double>(
                borrowedEnvelope.begin(), borrowedEnvelope.end()),
        });
        const auto graph = compile(document, settings);
        const auto expected = talas::runtime::renderOffline(graph, 6);
        talas::runtime::RealtimeRenderSession session(graph);
        std::array<const float*, 1> inputs{borrowedEnvelope.data()};
        std::array<double, 6> left{};
        std::array<double, 6> right{};
        std::size_t allocations = 0;
        require(
            expected.ok() && session.ready()
                && renderStereoInputAndCount(
                    session,
                    {inputs.data(), inputs.size()},
                    left,
                    right,
                    allocations)
                && allocations == 0,
            "C22 live-frequency fixture should render without allocation: "
                + std::string{context} + " "
                + std::string{session.error()});
        for (std::size_t frame = 0; frame < left.size(); ++frame)
        {
            requireNear(
                left[frame], expected.mono[frame], 1.0e-12,
                "C22 live left parity " + std::string{context});
            requireNear(
                right[frame], expected.right[frame], 1.0e-12,
                "C22 live right parity " + std::string{context});
        }
    };

    auto directSettings = talas::runtime::RenderSettings{8.0, 6};
    directSettings.eventValues.push_back({
        "C22DirectFrequency", 1.0,
        talas::expr::ValueDomain::Hertz});
    directSettings.eventValueChanges.push_back({
        3,
        "C22DirectFrequency",
        -1.0,
        talas::expr::ValueDomain::Hertz,
    });
    requireParity(
        makeRealtimeQuadOscillatorDocument(
            false, "!C22DirectFrequency"),
        std::move(directSettings),
        "direct Event Value");

    auto connected = makeRealtimeQuadOscillatorDocument(
        false, "0.5 hz");
    connected.graph.nodes.push_back(node(
        "c22Frequency", "talas.constant", {
            {"value", "!C22ConnectedFrequency"},
        }));
    connected.graph.connections.push_back(connection(
        "c22Frequency", "value", "quad", "frequency"));
    auto connectedSettings = talas::runtime::RenderSettings{8.0, 6};
    connectedSettings.eventValues.push_back({
        "C22ConnectedFrequency", 1.0,
        talas::expr::ValueDomain::Scalar});
    connectedSettings.eventValueChanges.push_back({
        3,
        "C22ConnectedFrequency",
        -1.0,
        talas::expr::ValueDomain::Scalar,
    });
    requireParity(
        std::move(connected),
        std::move(connectedSettings),
        "connected Event Value");
}

void testRealtimeQuadOscillatorRollsBackInvalidLaterFrequencyAndResets()
{
    auto document = makeRealtimeQuadOscillatorDocument(
        false, "0.5 hz");
    document.graph.nodes.push_back(node(
        "c22Frequency", "talas.constant", {
            {"value", "!C22RollbackFrequency"},
        }));
    document.graph.connections.push_back(connection(
        "c22Frequency", "value", "quad", "frequency"));
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.eventValues.push_back({
        "C22RollbackFrequency", 1.0,
        talas::expr::ValueDomain::Scalar});
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(
        candidate.ready() && reference.ready()
            && candidate.scheduleEventValue(
                "C22RollbackFrequency",
                4.0,
                talas::expr::ValueDomain::Scalar,
                2),
        "C22 rollback fixture should schedule a later Nyquist failure");

    constexpr std::array<float, 4> borrowedEnvelope{
        1.0F, 0.5F, 1.5F, -0.25F};
    std::array<const float*, 1> inputs{borrowedEnvelope.data()};
    std::array<double, 4> failedLeft{1.0, 1.0, 1.0, 1.0};
    std::array<double, 4> failedRight{1.0, 1.0, 1.0, 1.0};
    std::size_t allocations = 0;
    require(
        !renderStereoInputAndCount(
            candidate,
            {inputs.data(), inputs.size()},
            failedLeft,
            failedRight,
            allocations)
            && allocations == 0
            && failedLeft == std::array<double, 4>{}
            && failedRight == std::array<double, 4>{},
        "C22 later frequency failure should publish neither stereo channel");
    require(
        candidate.updateEventValue(
            "C22RollbackFrequency",
            1.0,
            talas::expr::ValueDomain::Scalar),
        "C22 failed callback should recover to a valid connected frequency");

    std::array<double, 4> candidateContinuation{};
    std::array<double, 4> candidateRight{};
    std::array<double, 4> referenceContinuation{};
    std::array<double, 4> referenceRight{};
    require(
        renderStereoInputAndCount(
            candidate,
            {inputs.data(), inputs.size()},
            candidateContinuation,
            candidateRight,
            allocations)
            && allocations == 0
            && renderStereoInputAndCount(
                reference,
                {inputs.data(), inputs.size()},
                referenceContinuation,
                referenceRight,
                allocations)
            && allocations == 0
            && candidateContinuation == referenceContinuation
            && candidateRight == referenceRight,
        "C22 failed callback should restore phase and predecessor state");

    candidate.resetTransport();
    std::array<double, 4> resetLeft{};
    std::array<double, 4> resetRight{};
    require(
        renderStereoInputAndCount(
            candidate,
            {inputs.data(), inputs.size()},
            resetLeft,
            resetRight,
            allocations)
            && allocations == 0
            && resetLeft == referenceContinuation
            && resetRight == referenceRight,
        "C22 reset should restore exact phase zero");
}

void testRealtimeQuadOscillatorRejectsForgedPreparedAuthority()
{
    const auto requireRejected = [](
                                     talas::runtime::RuntimePlan plan,
                                     const talas::runtime::RenderSettings& settings,
                                     std::string_view context) {
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), settings});
        require(
            !session.ready(),
            std::string{context}
                + " should reject forged C22 Quad Oscillator authority");
    };
    const auto compiled = compile(
        makeRealtimeQuadOscillatorDocument(true),
        {8.0, 4});
    const auto findQuad = [](talas::runtime::RuntimePlan& plan) {
        return std::ranges::find(
            plan.steps,
            std::string_view{"talas.quadOscillator"},
            &talas::runtime::CompileStep::typeId);
    };
    const auto mutateQuad = [&](auto mutate,
                                std::string_view context) {
        auto plan = compiled.plan();
        const auto quad = findQuad(plan);
        require(
            quad != plan.steps.end(),
            "C22 forged-authority fixture should expose Quad Oscillator");
        mutate(plan, *quad);
        requireRejected(
            std::move(plan), compiled.renderSettings(), context);
    };

    mutateQuad(
        [](auto&, auto& quad) {
            quad.preparedRealtimeSupport =
                talas::core::ExecutionSupport::Supported;
        },
        "C22 forged full support");
    mutateQuad(
        [](auto&, auto& quad) {
            quad.preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
        },
        "C22 forged kernel binding");
    mutateQuad(
        [](auto&, auto& quad) { quad.supportsReset = false; },
        "C22 forged reset contract");
    mutateQuad(
        [](auto&, auto& quad) { ++quad.eventValueScopeId; },
        "C22 forged Event Value scope");
    mutateQuad(
        [](auto&, auto& quad) {
            quad.resolvedLatencyFrames.reset();
        },
        "C22 missing intrinsic latency");
    mutateQuad(
        [](auto&, auto& quad) {
            quad.cumulativeOutputLatencyFrames = 1;
        },
        "C22 forged cumulative output latency");
    mutateQuad(
        [](auto&, auto& quad) {
            quad.parameters[0].domain =
                talas::expr::ValueDomain::Scalar;
        },
        "C22 forged frequency domain");
    mutateQuad(
        [](auto&, auto& quad) {
            quad.parameters[0].expression.reset();
        },
        "C22 missing frequency expression authority");
    mutateQuad(
        [](auto&, auto& quad) {
            quad.parameters[0].value = 0.5;
        },
        "C22 forged frequency expression value");
    mutateQuad(
        [](auto& plan, auto& quad) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == quad.nodeId
                        && buffer.portId == "audioOut"
                        && buffer.scopeId == quad.scopeId;
                });
            require(
                output != plan.buffers.end(),
                "C22 duplicate-output fixture should expose audioOut");
            plan.buffers.push_back(*output);
        },
        "C22 duplicate output ownership");
    mutateQuad(
        [](auto& plan, auto& quad) {
            const auto envelope = std::ranges::find(
                quad.inputs,
                std::string_view{"envelope"},
                &talas::runtime::InputBinding::inputPortId);
            require(
                envelope != quad.inputs.end(),
                "C22 forged-producer fixture should expose envelope");
            auto forged = plan.buffers[envelope->bufferIndex];
            forged.portId = "forgedAudioOut";
            envelope->sourcePortId = forged.portId;
            envelope->bufferIndex = plan.buffers.size();
            plan.buffers.push_back(std::move(forged));
        },
        "C22 unproduced envelope buffer");
    mutateQuad(
        [](auto& plan, auto& quad) {
            const auto envelope = std::ranges::find(
                quad.inputs,
                std::string_view{"envelope"},
                &talas::runtime::InputBinding::inputPortId);
            require(
                envelope != quad.inputs.end(),
                "C22 latency fixture should expose envelope");
            const auto source = std::ranges::find_if(
                plan.steps,
                [&](const talas::runtime::CompileStep& candidate) {
                    return candidate.nodeId == envelope->sourceNodeId
                        && candidate.scopeId == envelope->sourceScopeId;
                });
            require(
                source != plan.steps.end(),
                "C22 latency fixture should expose source ancestry");
            const auto inputIndex = static_cast<std::size_t>(
                envelope - quad.inputs.begin());
            source->resolvedLatencyFrames = 1;
            source->cumulativeInputLatencyFrames = 0;
            source->cumulativeOutputLatencyFrames = 1;
            quad.inputLatencyFrames[inputIndex] = 1;
            quad.cumulativeInputLatencyFrames = 1;
            quad.cumulativeOutputLatencyFrames = 1;
        },
        "C22 coherently forged envelope ancestry latency");
    mutateQuad(
        [](auto&, auto& quad) {
            require(
                quad.inputs.size() == 2,
                "C22 reorder fixture should expose both envelopes");
            std::swap(quad.inputs[0], quad.inputs[1]);
            std::swap(
                quad.inputLatencyFrames[0],
                quad.inputLatencyFrames[1]);
        },
        "C22 reordered envelope inputs");
}

void testRealtimeQuadOscillatorKeepsNestedStateIsolated()
{
    const auto graph = compile(
        makeNestedRealtimeQuadOscillatorDocument(),
        {8.0, 7});
    std::vector<talas::runtime::RuntimeScopeId> scopes;
    for (const auto& step : graph.plan().steps)
    {
        if (step.typeId == "talas.quadOscillator")
            scopes.push_back(step.scopeId);
    }
    const auto expected = talas::runtime::renderOffline(graph, 7);
    talas::runtime::RealtimeRenderSession session(graph);
    std::array<double, 7> left{};
    std::array<double, 7> right{};
    std::size_t allocations = 0;
    require(
        scopes.size() == 2
            && scopes[0] != scopes[1]
            && scopes[0] != talas::runtime::globalRuntimeScope
            && scopes[1] != talas::runtime::globalRuntimeScope
            && expected.ok()
            && session.ready()
            && renderStereoAndCount(
                session, left, right, allocations)
            && allocations == 0,
        "C22 nested sibling phase state should prepare independently: "
            + std::string{session.error()});
    for (std::size_t frame = 0; frame < left.size(); ++frame)
    {
        requireNear(
            left[frame], expected.mono[frame], 1.0e-12,
            "C22 nested left phase isolation");
        requireNear(
            right[frame], expected.right[frame], 1.0e-12,
            "C22 nested right phase isolation");
    }
}

void testRealtimeQuadOscillatorRollsBackDownstreamAndAcceptsCheckpointedNeighbors()
{
    auto document = makeRealtimeQuadOscillatorDocument();
    document.graph.nodes.push_back(node(
        "formants", "talas.twoFormantElement", {
            {"formant1", "1 hz"},
            {"bandwidth1", "0.5 hz"},
            {"scale1", "0.75"},
            {"formant2", "2 hz"},
            {"bandwidth2", "0.75 hz"},
            {"scale2", "-0.25"},
        }));
    document.graph.nodes.push_back(node(
        "formantControl", "talas.constant", {
            {"value", "!C22DownstreamFormant"},
        }));
    document.graph.connections.erase(
        std::remove_if(
            document.graph.connections.begin(),
            document.graph.connections.end(),
            [](const talas::core::Connection& candidate) {
                return candidate.fromNode == "quad"
                    && candidate.fromPort == "audioOut"
                    && candidate.toNode == "out";
            }),
        document.graph.connections.end());
    document.graph.connections.push_back(connection(
        "quad", "audioOut", "formants", "audioIn"));
    document.graph.connections.push_back(connection(
        "formantControl", "value", "formants", "formant1"));
    document.graph.connections.push_back(connection(
        "formants", "audioOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{8.0, 6};
    settings.eventValues.push_back({
        "C22DownstreamFormant", 1.0,
        talas::expr::ValueDomain::Scalar});
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(
        candidate.ready() && reference.ready()
            && candidate.scheduleEventValue(
                "C22DownstreamFormant",
                4.0,
                talas::expr::ValueDomain::Scalar,
                3),
        "C22 downstream rollback fixture should prepare and segment");
    constexpr std::array<float, 6> envelope{
        1.0F, 0.5F, 1.5F, -0.25F, 0.75F, 2.0F};
    std::array<const float*, 1> inputs{envelope.data()};
    std::array<double, 6> failedLeft{};
    std::array<double, 6> failedRight{};
    failedLeft.fill(1.0);
    failedRight.fill(1.0);
    std::size_t allocations = 0;
    require(
        !renderStereoInputAndCount(
            candidate,
            {inputs.data(), inputs.size()},
            failedLeft,
            failedRight,
            allocations)
            && allocations == 0
            && failedLeft == std::array<double, 6>{}
            && failedRight == std::array<double, 6>{},
        "C22 downstream failure should publish no stereo callback audio");
    require(
        candidate.updateEventValue(
            "C22DownstreamFormant",
            1.0,
            talas::expr::ValueDomain::Scalar),
        "C22 downstream control should recover after failure");
    std::array<double, 6> candidateLeft{};
    std::array<double, 6> candidateRight{};
    std::array<double, 6> referenceLeft{};
    std::array<double, 6> referenceRight{};
    require(
        renderStereoInputAndCount(
            candidate,
            {inputs.data(), inputs.size()},
            candidateLeft,
            candidateRight,
            allocations)
            && allocations == 0
            && renderStereoInputAndCount(
                reference,
                {inputs.data(), inputs.size()},
                referenceLeft,
                referenceRight,
                allocations)
            && allocations == 0
            && candidateLeft == referenceLeft
            && candidateRight == referenceRight,
        "C22 downstream failure should restore Quad and neighbor state");

    auto predecessorDocument = makeRealtimeQuadOscillatorDocument();
    predecessorDocument.graph.nodes.push_back(node(
        "lowPassGate", "talas.lowPassGate", lowPassGateParameters()));
    predecessorDocument.graph.connections.erase(
        std::remove_if(
            predecessorDocument.graph.connections.begin(),
            predecessorDocument.graph.connections.end(),
            [](const talas::core::Connection& candidate) {
                return candidate.fromNode == "left"
                    && candidate.toNode == "quad";
            }),
        predecessorDocument.graph.connections.end());
    predecessorDocument.graph.connections.push_back(connection(
        "left", "audioOut", "lowPassGate", "audioIn"));
    predecessorDocument.graph.connections.push_back(connection(
        "lowPassGate", "audioOut", "quad", "envelope"));
    const auto predecessorGraph = compile(
        predecessorDocument, settings);
    talas::runtime::RealtimeRenderSession predecessor(predecessorGraph);
    require(
        predecessor.ready(),
        "C103 Low-Pass Gate should provide dedicated checkpoint coverage as a Quad Oscillator predecessor");

    auto successorDocument = makeRealtimeQuadOscillatorDocument();
    successorDocument.graph.nodes.push_back(node(
        "lowPassGate", "talas.lowPassGate", lowPassGateParameters()));
    successorDocument.graph.connections.erase(
        std::remove_if(
            successorDocument.graph.connections.begin(),
            successorDocument.graph.connections.end(),
            [](const talas::core::Connection& candidate) {
                return candidate.fromNode == "quad"
                    && candidate.fromPort == "audioOut"
                    && candidate.toNode == "out";
            }),
        successorDocument.graph.connections.end());
    successorDocument.graph.connections.push_back(connection(
        "quad", "audioOut", "lowPassGate", "audioIn"));
    successorDocument.graph.connections.push_back(connection(
        "lowPassGate", "audioOut", "out", "audioIn"));
    const auto successorGraph = compile(
        successorDocument, settings);
    talas::runtime::RealtimeRenderSession successor(successorGraph);
    require(
        successor.ready(),
        "C103 Low-Pass Gate should provide dedicated checkpoint coverage as a Quad Oscillator successor");
}

void testRealtimeHarmonicResonatorMatchesLiveControlsAndCapacityGrowth()
{
    struct ControlCase
    {
        std::string_view id;
        std::string_view value;
    };
    constexpr std::array cases{
        ControlCase{"decayTime", "0.25"},
        ControlCase{"frequency", "4.0"},
        ControlCase{"scale", "-0.5"},
    };
    for (const auto& control : cases)
    {
        auto document = makeRealtimeHarmonicResonatorDocument();
        document.graph.nodes.push_back(node(
            "c20Control", "talas.constant", {
                {"value", std::string{control.value}},
            }));
        document.graph.connections.push_back(connection(
            "c20Control", "value", "resonator",
            std::string{control.id}));
        auto settings = talas::runtime::RenderSettings{8.0, 9};
        settings.maxRealtimeHistoryFrames = 8;
        const auto graph = compile(document, settings);
        const auto expected = talas::runtime::renderOffline(graph, 9);
        talas::runtime::RealtimeRenderSession session(graph);
        std::array<double, 9> actual{};
        std::size_t allocations = 0;
        require(
            expected.ok() && session.ready()
                && renderAndCount(session, actual, allocations)
                && allocations == 0
                && std::ranges::equal(actual, expected.mono),
            "C20 connected Harmonic Resonator control should remain sample-identical: "
                + std::string{control.id} + " "
                + std::string{session.error()});
    }

    auto growth = makeRealtimeHarmonicResonatorDocument();
    const auto resonator = std::ranges::find(
        growth.graph.nodes,
        std::string_view{"resonator"},
        &talas::project::ProjectNode::instanceId);
    require(
        resonator != growth.graph.nodes.end(),
        "C20 growth fixture should expose Harmonic Resonator");
    const auto frequency = std::ranges::find(
        resonator->parameters,
        std::string_view{"frequency"},
        &talas::project::ProjectParameterExpression::parameterId);
    require(
        frequency != resonator->parameters.end(),
        "C20 growth fixture should expose frequency");
    frequency->expression = "4 hz";
    growth.graph.nodes.push_back(node(
        "c20GrowthControl", "talas.constant", {
            {"value", "!C20GrowthFrequency"},
        }));
    growth.graph.connections.push_back(connection(
        "c20GrowthControl", "value", "resonator", "frequency"));
    auto growthSettings = talas::runtime::RenderSettings{4.0, 6};
    growthSettings.maxRealtimeHistoryFrames = 4;
    growthSettings.eventValues = {{
        "C20GrowthFrequency", 4.0,
        talas::expr::ValueDomain::Scalar}};
    growthSettings.eventValueChanges = {{
        2, "C20GrowthFrequency", 2.0,
        talas::expr::ValueDomain::Scalar}};
    const auto growthGraph = compile(growth, growthSettings);
    const auto expected = talas::runtime::renderOffline(
        growthGraph, 6);
    talas::runtime::RealtimeRenderSession realtime(growthGraph);
    require(
        realtime.ready(),
        "C20 capacity-growth realtime fixture should prepare: "
            + std::string{realtime.error()});
    std::array<double, 2> actualFirst{};
    std::array<double, 4> actualSecond{};
    std::size_t allocations = 0;
    require(
        expected.ok() && expected.mono.size() == 6
            && renderAndCount(realtime, actualFirst, allocations)
            && allocations == 0
            && renderAndCount(realtime, actualSecond, allocations)
            && allocations == 0
            && std::ranges::equal(
                actualFirst,
                std::span<const double>{expected.mono}.first(2))
            && std::ranges::equal(
                actualSecond,
                std::span<const double>{expected.mono}.subspan(2)),
        "C20 logical delay-capacity growth should match offline across session calls");
}

void testRealtimeHarmonicResonatorMatchesDirectAndConnectedEventValues()
{
    struct ControlCase
    {
        std::string_view id;
        talas::expr::ValueDomain domain;
        double initialValue;
        double updatedValue;
    };
    constexpr std::array cases{
        ControlCase{"decayTime", talas::expr::ValueDomain::Seconds,
                    0.5, 0.25},
        ControlCase{"frequency", talas::expr::ValueDomain::Hertz,
                    2.0, 4.0},
        ControlCase{"scale", talas::expr::ValueDomain::Scalar,
                    0.75, -0.5},
    };
    const auto setExpression = [](
                                   talas::project::ProjectDocument& document,
                                   std::string_view id,
                                   std::string expression) {
        const auto resonator = std::ranges::find(
            document.graph.nodes,
            std::string_view{"resonator"},
            &talas::project::ProjectNode::instanceId);
        require(
            resonator != document.graph.nodes.end(),
            "C20 Event Value fixture should expose Harmonic Resonator");
        const auto parameter = std::ranges::find(
            resonator->parameters,
            id,
            &talas::project::ProjectParameterExpression::parameterId);
        require(
            parameter != resonator->parameters.end(),
            "C20 Event Value fixture should expose its parameter");
        parameter->expression = std::move(expression);
    };

    for (const auto& control : cases)
    {
        auto direct = makeRealtimeHarmonicResonatorDocument();
        setExpression(direct, control.id, "!C20DirectControl");
        auto connected = makeRealtimeHarmonicResonatorDocument();
        connected.graph.nodes.push_back(node(
            "c20EventControl", "talas.constant", {
                {"value", "!C20ConnectedControl"},
            }));
        connected.graph.connections.push_back(connection(
            "c20EventControl", "value", "resonator",
            std::string{control.id}));

        auto settings = talas::runtime::RenderSettings{8.0, 4};
        settings.maxRealtimeHistoryFrames = 8;
        settings.eventValues = {
            {"C20DirectControl", control.initialValue,
             control.domain},
            {"C20ConnectedControl", control.initialValue,
             talas::expr::ValueDomain::Scalar},
        };
        const auto directGraph = compile(direct, settings);
        const auto connectedGraph = compile(connected, settings);
        talas::runtime::RealtimeRenderSession directSession(directGraph);
        talas::runtime::RealtimeRenderSession connectedSession(
            connectedGraph);
        require(
            directSession.ready() && connectedSession.ready(),
            "C20 direct/connected Event Value fixtures should prepare: "
                + std::string{control.id} + " "
                + std::string{directSession.ready()
                    ? connectedSession.error()
                    : directSession.error()});
        const auto renderEqual = [&](std::size_t frames) {
            std::vector<double> directOutput(frames);
            std::vector<double> connectedOutput(frames);
            std::size_t allocations = 0;
            require(
                renderAndCount(
                    directSession, directOutput, allocations)
                    && allocations == 0
                    && renderAndCount(
                        connectedSession,
                        connectedOutput,
                        allocations)
                    && allocations == 0
                    && directOutput == connectedOutput,
                "C20 direct and connected Event Values should match: "
                    + std::string{control.id});
        };
        renderEqual(3);
        require(
            directSession.updateEventValue(
                "C20DirectControl",
                control.updatedValue,
                control.domain)
                && connectedSession.updateEventValue(
                    "C20ConnectedControl",
                    control.updatedValue,
                    talas::expr::ValueDomain::Scalar),
            "C20 equivalent Event Value updates should publish: "
                + std::string{control.id});
        renderEqual(4);
    }
}

void testRealtimeHarmonicResonatorEnforcesPreparedHistoryBounds()
{
    auto oversized = makeRealtimeHarmonicResonatorDocument();
    const auto oversizedResonator = std::ranges::find(
        oversized.graph.nodes,
        std::string_view{"resonator"},
        &talas::project::ProjectNode::instanceId);
    const auto oversizedFrequency = std::ranges::find(
        oversizedResonator->parameters,
        std::string_view{"frequency"},
        &talas::project::ProjectParameterExpression::parameterId);
    oversizedFrequency->expression = "0.5 hz";
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.maxRealtimeHistoryFrames = 8;
    const auto oversizedGraph = compile(oversized, settings);
    talas::runtime::RealtimeRenderSession oversizedSession(
        oversizedGraph);
    require(
        !oversizedSession.ready(),
        "C20 static period beyond prepared history should reject preparation");

    auto zeroDelay = makeRealtimeHarmonicResonatorDocument();
    const auto zeroResonator = std::ranges::find(
        zeroDelay.graph.nodes,
        std::string_view{"resonator"},
        &talas::project::ProjectNode::instanceId);
    const auto zeroFrequency = std::ranges::find(
        zeroResonator->parameters,
        std::string_view{"frequency"},
        &talas::project::ProjectParameterExpression::parameterId);
    zeroFrequency->expression = "32 hz";
    const auto zeroGraph = compile(zeroDelay, settings);
    const auto zeroExpected = talas::runtime::renderOffline(zeroGraph, 4);
    talas::runtime::RealtimeRenderSession zeroSession(zeroGraph);
    std::array<double, 4> zeroActual{};
    std::size_t allocations = 0;
    require(
        zeroExpected.ok() && zeroSession.ready()
            && renderAndCount(zeroSession, zeroActual, allocations)
            && allocations == 0
            && std::ranges::equal(zeroActual, zeroExpected.mono),
        "C20 static rounded zero-delay profile should preserve excitation passthrough");

    auto liveZero = makeRealtimeHarmonicResonatorDocument();
    const auto liveResonator = std::ranges::find(
        liveZero.graph.nodes,
        std::string_view{"resonator"},
        &talas::project::ProjectNode::instanceId);
    const auto liveFrequency = std::ranges::find(
        liveResonator->parameters,
        std::string_view{"frequency"},
        &talas::project::ProjectParameterExpression::parameterId);
    liveFrequency->expression = "!C20Frequency";
    settings.eventValues = {{
        "C20Frequency", 2.0,
        talas::expr::ValueDomain::Hertz}};
    const auto liveGraph = compile(liveZero, settings);
    talas::runtime::RealtimeRenderSession liveSession(liveGraph);
    require(
        liveSession.ready()
            && liveSession.updateEventValue(
                "C20Frequency", 32.0,
                talas::expr::ValueDomain::Hertz),
        "C20 live zero-delay update should publish before consumer validation");
    std::array<double, 4> rejected{1.0, 1.0, 1.0, 1.0};
    require(
        !renderAndCount(liveSession, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 4>{},
        "C20 live rounded zero-delay period should fail the complete callback closed");
}

void testRealtimeHarmonicResonatorResetNestedAndRollbackStayExact()
{
    auto settings = talas::runtime::RenderSettings{8.0, 8};
    settings.maxRealtimeHistoryFrames = 8;
    const auto graph = compile(
        makeRealtimeHarmonicResonatorDocument(),
        settings);
    talas::runtime::RealtimeRenderSession session(graph);
    std::array<double, 8> first{};
    std::array<double, 8> reset{};
    std::size_t allocations = 0;
    require(
        session.ready()
            && renderAndCount(session, first, allocations)
            && allocations == 0,
        "C20 lifecycle fixture should render initially");
    session.resetTransport();
    require(
        renderAndCount(session, reset, allocations)
            && allocations == 0
            && reset == first,
        "C20 reset should restore delay, index, brightness, and journal state");

    const auto nestedGraph = compile(
        makeNestedRealtimeHarmonicResonatorDocument(),
        settings);
    std::vector<talas::runtime::RuntimeScopeId> scopes;
    for (const auto& step : nestedGraph.plan().steps)
    {
        if (step.typeId == "talas.harmonicResonator")
            scopes.push_back(step.scopeId);
    }
    const auto nestedExpected = talas::runtime::renderOffline(
        nestedGraph, 8);
    talas::runtime::RealtimeRenderSession nestedSession(nestedGraph);
    std::array<double, 8> nestedActual{};
    require(
        scopes.size() == 2
            && scopes[0] != scopes[1]
            && scopes[0] != talas::runtime::globalRuntimeScope
            && scopes[1] != talas::runtime::globalRuntimeScope
            && nestedExpected.ok()
            && nestedSession.ready()
            && renderAndCount(
                nestedSession, nestedActual, allocations)
            && allocations == 0
            && std::ranges::equal(
                nestedActual, nestedExpected.mono),
        "C20 nested sibling state should stay structurally isolated and sample-identical");

    auto rollbackDocument = makeRealtimeHarmonicResonatorDocument();
    const auto rollbackResonator = std::ranges::find(
        rollbackDocument.graph.nodes,
        std::string_view{"resonator"},
        &talas::project::ProjectNode::instanceId);
    const auto rollbackFrequency = std::ranges::find(
        rollbackResonator->parameters,
        std::string_view{"frequency"},
        &talas::project::ProjectParameterExpression::parameterId);
    rollbackFrequency->expression = "8 hz";
    rollbackDocument.graph.nodes.push_back(node(
        "c20Frequency", "talas.constant", {
            {"value", "!C20RollbackFrequency"},
        }));
    rollbackDocument.graph.connections.push_back(connection(
        "c20Frequency", "value", "resonator", "frequency"));
    settings.eventValues = {{
        "C20RollbackFrequency", 8.0,
        talas::expr::ValueDomain::Scalar}};
    const auto rollbackGraph = compile(
        rollbackDocument, settings);
    talas::runtime::RealtimeRenderSession candidate(rollbackGraph);
    talas::runtime::RealtimeRenderSession reference(rollbackGraph);
    require(
        candidate.ready() && reference.ready()
            && candidate.scheduleEventValue(
                "C20RollbackFrequency", 0.5,
                talas::expr::ValueDomain::Scalar, 3),
        "C20 rollback fixture should prepare and schedule a bounded-history failure");
    std::array<double, 4> failed{1.0, 1.0, 1.0, 1.0};
    require(
        !renderAndCount(candidate, failed, allocations)
            && allocations == 0
            && failed == std::array<double, 4>{},
        "C20 later segment failure should publish no callback audio");
    require(
        candidate.updateEventValue(
            "C20RollbackFrequency", 8.0,
            talas::expr::ValueDomain::Scalar),
        "C20 rollback control should recover after failure");
    std::array<double, 8> candidateContinuation{};
    std::array<double, 8> referenceContinuation{};
    require(
        renderAndCount(
            candidate, candidateContinuation, allocations)
            && allocations == 0
            && renderAndCount(
                reference, referenceContinuation, allocations)
            && allocations == 0
            && candidateContinuation == referenceContinuation,
        "C20 reverse journal should restore repeated writes, growth, index, brightness, and oscillator state");
}

