void testRealtimeHarmonicResonatorRejectsForgedPreparedAuthority()
{
    const auto requireRejected = [](
                                     talas::runtime::RuntimePlan plan,
                                     const talas::runtime::RenderSettings& settings,
                                     std::string_view context) {
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), settings});
        require(
            !session.ready(),
            std::string{context}
                + " should reject forged C20 Harmonic Resonator authority");
    };
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.maxRealtimeHistoryFrames = 8;
    const auto compiled = compile(
        makeRealtimeHarmonicResonatorDocument(), settings);
    const auto findResonator = [](talas::runtime::RuntimePlan& plan) {
        return std::ranges::find(
            plan.steps,
            std::string_view{"talas.harmonicResonator"},
            &talas::runtime::CompileStep::typeId);
    };
    const auto mutateResonator = [&](auto mutate,
                                     std::string_view context) {
        auto plan = compiled.plan();
        const auto resonator = findResonator(plan);
        require(
            resonator != plan.steps.end(),
            "C20 forged-authority fixture should expose Harmonic Resonator");
        mutate(plan, *resonator);
        requireRejected(
            std::move(plan), compiled.renderSettings(), context);
    };
    mutateResonator(
        [](auto&, auto& resonator) {
            resonator.preparedRealtimeSupport =
                talas::core::ExecutionSupport::Supported;
        },
        "C20 forged full support");
    mutateResonator(
        [](auto&, auto& resonator) {
            resonator.preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
        },
        "C20 forged kernel binding");
    mutateResonator(
        [](auto&, auto& resonator) {
            resonator.supportsReset = false;
        },
        "C20 forged reset contract");
    mutateResonator(
        [](auto&, auto& resonator) {
            ++resonator.eventValueScopeId;
        },
        "C20 forged Event Value scope");
    mutateResonator(
        [](auto&, auto& resonator) {
            resonator.resolvedLatencyFrames = 1;
        },
        "C20 forged intrinsic latency");
    mutateResonator(
        [](auto&, auto& resonator) {
            std::swap(
                resonator.parameters[0],
                resonator.parameters[1]);
        },
        "C20 reordered parameters");
    mutateResonator(
        [](auto&, auto& resonator) {
            resonator.parameters[0].domain =
                talas::expr::ValueDomain::Hertz;
        },
        "C20 forged decay domain");
    mutateResonator(
        [](auto&, auto& resonator) {
            resonator.parameters[0].expression.reset();
        },
        "C20 missing numeric expression authority");
    mutateResonator(
        [](auto&, auto& resonator) {
            resonator.parameters[0].value = 0.25;
        },
        "C20 forged expression value");
    mutateResonator(
        [](auto&, auto& resonator) {
            resonator.parameters[1].value = -1.0;
        },
        "C20 negative brightness");
    mutateResonator(
        [](auto&, auto& resonator) {
            resonator.parameters[3].resource = "Shared";
        },
        "C20 named delay memory");
    mutateResonator(
        [](auto&, auto& resonator) {
            resonator.parameters[4].value = 1.0;
        },
        "C20 forged prezero shape");
    mutateResonator(
        [](auto& plan, auto& resonator) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == resonator.nodeId
                        && buffer.portId == "audioOut"
                        && buffer.scopeId == resonator.scopeId;
                });
            require(
                output != plan.buffers.end(),
                "C20 output fixture should expose audioOut");
            plan.buffers.push_back(*output);
        },
        "C20 duplicate output ownership");
    mutateResonator(
        [](auto& plan, auto& resonator) {
            const auto audioInput = std::ranges::find(
                resonator.inputs,
                std::string_view{"audioIn"},
                &talas::runtime::InputBinding::inputPortId);
            require(
                audioInput != resonator.inputs.end(),
                "C20 producer fixture should expose audioIn");
            auto forged = plan.buffers[audioInput->bufferIndex];
            forged.portId = "forgedAudioOut";
            audioInput->sourcePortId = forged.portId;
            audioInput->bufferIndex = plan.buffers.size();
            plan.buffers.push_back(std::move(forged));
        },
        "C20 unproduced audio buffer");
    mutateResonator(
        [](auto& plan, auto& resonator) {
            const auto oscillator = std::ranges::find(
                plan.steps,
                std::string_view{"talas.oscillator"},
                &talas::runtime::CompileStep::typeId);
            require(
                oscillator != plan.steps.end(),
                "C20 latency fixture should expose oscillator");
            oscillator->resolvedLatencyFrames = 1;
            oscillator->cumulativeInputLatencyFrames = 0;
            oscillator->cumulativeOutputLatencyFrames = 1;
            resonator.inputLatencyFrames.front() = 1;
            resonator.cumulativeInputLatencyFrames = 1;
            resonator.cumulativeOutputLatencyFrames = 1;
        },
        "C20 coherently forged audio ancestry latency");

    auto connectedDocument = makeRealtimeHarmonicResonatorDocument();
    connectedDocument.graph.nodes.push_back(node(
        "c20Control", "talas.constant", {{"value", "0.25"}}));
    connectedDocument.graph.connections.push_back(connection(
        "c20Control", "value", "resonator", "decayTime"));
    const auto connected = compile(connectedDocument, settings);
    auto connectedPlan = connected.plan();
    const auto connectedResonator = findResonator(connectedPlan);
    require(
        connectedResonator != connectedPlan.steps.end()
            && connectedResonator->inputs.size() == 2,
        "C20 connected authority fixture should expose two inputs");
    std::swap(
        connectedResonator->inputs[0],
        connectedResonator->inputs[1]);
    std::swap(
        connectedResonator->inputLatencyFrames[0],
        connectedResonator->inputLatencyFrames[1]);
    requireRejected(
        std::move(connectedPlan),
        connected.renderSettings(),
        "C20 reordered input bindings");
}

void testRealtimeVcfMatchesAllConnectedControls()
{
    struct ControlCase
    {
        std::string_view id;
        std::string_view value;
    };
    constexpr std::array cases{
        ControlCase{"amplitude", "0.5"},
        ControlCase{"cutoff", "1.5"},
        ControlCase{"cutoffModulator", "-0.25"},
        ControlCase{"cutoffModRange", "0.5"},
        ControlCase{"resonance", "0.75"},
    };
    for (const auto& control : cases)
    {
        auto document = makeRealtimeVcfDocument();
        document.graph.nodes.push_back(node(
            "c19Control", "talas.constant", {
                {"value", std::string{control.value}},
            }));
        document.graph.connections.push_back(connection(
            "c19Control", "value", "vcf", std::string{control.id}));
        constexpr std::size_t frameCount = 9;
        const auto graph = compile(
            document,
            talas::runtime::RenderSettings{8.0, frameCount});
        const auto expected = talas::runtime::renderOffline(
            graph, frameCount);
        talas::runtime::RealtimeRenderSession session(graph);
        require(
            expected.ok() && session.ready(),
            "C19 connected VCF control should render offline and prepare: "
                + std::string{control.id} + " "
                + std::string{session.error()});
        std::array<double, frameCount> actual{};
        std::size_t allocations = 0;
        require(
            renderAndCount(session, actual, allocations)
                && allocations == 0
                && std::ranges::equal(actual, expected.mono),
            "C19 connected VCF control should remain sample-identical: "
                + std::string{control.id});
    }
}

void testRealtimeVcfMatchesDirectAndConnectedEventValues()
{
    struct ControlCase
    {
        std::string_view id;
        talas::expr::ValueDomain domain;
        double initialValue;
        double updatedValue;
    };
    constexpr std::array cases{
        ControlCase{"amplitude", talas::expr::ValueDomain::Scalar, 0.75, 0.5},
        ControlCase{"cutoff", talas::expr::ValueDomain::Hertz, 2.0, 1.5},
        ControlCase{"cutoffModulator", talas::expr::ValueDomain::Scalar, 0.25, -0.25},
        ControlCase{"cutoffModRange", talas::expr::ValueDomain::Hertz, 1.0, 0.5},
        ControlCase{"resonance", talas::expr::ValueDomain::Scalar, 0.25, 0.75},
    };
    const auto setExpression = [](
                                   talas::project::ProjectDocument& document,
                                   std::string_view id,
                                   std::string expression) {
        const auto vcf = std::ranges::find(
            document.graph.nodes,
            std::string_view{"vcf"},
            &talas::project::ProjectNode::instanceId);
        require(vcf != document.graph.nodes.end(),
                "C19 Event Value fixture should expose VCF");
        const auto parameter = std::ranges::find(
            vcf->parameters,
            id,
            &talas::project::ProjectParameterExpression::parameterId);
        require(parameter != vcf->parameters.end(),
                "C19 Event Value fixture should expose its parameter");
        parameter->expression = std::move(expression);
    };

    for (const auto& control : cases)
    {
        auto direct = makeRealtimeVcfDocument();
        setExpression(direct, control.id, "!C19DirectControl");
        auto connected = makeRealtimeVcfDocument();
        connected.graph.nodes.push_back(node(
            "c19EventControl", "talas.constant", {
                {"value", "!C19ConnectedControl"},
            }));
        connected.graph.connections.push_back(connection(
            "c19EventControl", "value", "vcf",
            std::string{control.id}));

        auto settings = talas::runtime::RenderSettings{8.0, 4};
        settings.eventValues = {
            {"C19DirectControl", control.initialValue, control.domain},
            {"C19ConnectedControl", control.initialValue,
             talas::expr::ValueDomain::Scalar},
        };
        const auto directGraph = compile(direct, settings);
        const auto connectedGraph = compile(connected, settings);
        talas::runtime::RealtimeRenderSession directSession(directGraph);
        talas::runtime::RealtimeRenderSession connectedSession(
            connectedGraph);
        require(
            directSession.ready() && connectedSession.ready(),
            "C19 direct/connected VCF Event Value fixtures should prepare: "
                + std::string{control.id} + " "
                + std::string{directSession.ready()
                    ? connectedSession.error() : directSession.error()});

        const auto renderEqual = [&](std::size_t frames) {
            std::vector<double> directOutput(frames);
            std::vector<double> connectedOutput(frames);
            std::size_t allocations = 0;
            require(
                renderAndCount(
                    directSession, directOutput, allocations)
                    && allocations == 0
                    && renderAndCount(
                        connectedSession,
                        connectedOutput,
                        allocations)
                    && allocations == 0
                    && directOutput == connectedOutput,
                "C19 direct and connected VCF Event Values should match: "
                    + std::string{control.id});
        };
        renderEqual(3);
        require(
            directSession.updateEventValue(
                "C19DirectControl",
                control.updatedValue,
                control.domain)
                && connectedSession.updateEventValue(
                    "C19ConnectedControl",
                    control.updatedValue,
                    talas::expr::ValueDomain::Scalar),
            "C19 equivalent VCF Event Value updates should publish: "
                + std::string{control.id});
        renderEqual(4);
    }

    auto invalidDirect = makeRealtimeVcfDocument();
    setExpression(invalidDirect, "cutoff", "!C19Cutoff");
    auto invalidSettings = talas::runtime::RenderSettings{8.0, 2};
    invalidSettings.eventValues.push_back({
        "C19Cutoff", 2.0, talas::expr::ValueDomain::Hertz});
    const auto invalidDirectGraph = compile(
        invalidDirect, invalidSettings);
    talas::runtime::RealtimeRenderSession invalidDirectSession(
        invalidDirectGraph);
    require(
        invalidDirectSession.ready()
            && !invalidDirectSession.updateEventValue(
                "C19Cutoff", std::numeric_limits<double>::quiet_NaN(),
                talas::expr::ValueDomain::Hertz),
        // A cutoff at Nyquist saturates below it (owner, 2026-10-12).
        "C19 direct cutoff should reject one that is not a number at publication");

    auto invalidConnected = makeRealtimeVcfDocument();
    invalidConnected.graph.nodes.push_back(node(
        "c19InvalidControl", "talas.constant", {
            {"value", "!C19ConnectedCutoff"},
        }));
    invalidConnected.graph.connections.push_back(connection(
        "c19InvalidControl", "value", "vcf", "cutoff"));
    invalidSettings.eventValues = {{
        "C19ConnectedCutoff", 2.0,
        talas::expr::ValueDomain::Scalar}};
    const auto invalidConnectedGraph = compile(
        invalidConnected, invalidSettings);
    talas::runtime::RealtimeRenderSession invalidConnectedSession(
        invalidConnectedGraph);
    require(
        invalidConnectedSession.ready()
            && invalidConnectedSession.updateEventValue(
                "C19ConnectedCutoff", 4.0,
                talas::expr::ValueDomain::Scalar),
        "C19 connected cutoff should schedule before consumer validation");
    std::array<double, 2> rejected{1.0, 1.0};
    std::size_t allocations = 0;
    require(
        !renderAndCount(
            invalidConnectedSession, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 2>{},
        "C19 connected cutoff should fail closed at Nyquist in callback");
}

void testRealtimeVcfRejectsForgedPreparedAuthority()
{
    const auto requireRejected = [](
                                     talas::runtime::RuntimePlan plan,
                                     const talas::runtime::RenderSettings& settings,
                                     std::string_view context) {
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), settings});
        require(
            !session.ready(),
            std::string{context}
                + " should reject forged C19 VCF authority");
    };
    const auto compiled = compile(
        makeRealtimeVcfDocument(),
        talas::runtime::RenderSettings{8.0, 2});
    const auto findVcf = [](talas::runtime::RuntimePlan& plan) {
        return std::ranges::find(
            plan.steps,
            std::string_view{"talas.vcf"},
            &talas::runtime::CompileStep::typeId);
    };
    const auto mutateVcf = [&](auto mutate, std::string_view context) {
        auto plan = compiled.plan();
        const auto vcf = findVcf(plan);
        require(vcf != plan.steps.end(),
                "C19 forged-authority fixture should expose VCF");
        mutate(plan, *vcf);
        requireRejected(
            std::move(plan), compiled.renderSettings(), context);
    };
    mutateVcf(
        [](auto&, auto& vcf) {
            vcf.preparedRealtimeSupport =
                talas::core::ExecutionSupport::Supported;
        },
        "C19 VCF forged full support");
    mutateVcf(
        [](auto&, auto& vcf) {
            vcf.preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
        },
        "C19 VCF forged kernel binding");
    mutateVcf(
        [](auto&, auto& vcf) { vcf.supportsReset = false; },
        "C19 VCF forged reset contract");
    mutateVcf(
        [](auto&, auto& vcf) {
            vcf.eventValueScopeId = vcf.scopeId + 1;
        },
        "C19 VCF forged Event Value scope");
    mutateVcf(
        [](auto&, auto& vcf) { vcf.resolvedLatencyFrames = 1; },
        "C19 VCF forged intrinsic latency");
    mutateVcf(
        [](auto&, auto& vcf) {
            std::swap(vcf.parameters[0], vcf.parameters[1]);
        },
        "C19 VCF reordered parameters");
    mutateVcf(
        [](auto&, auto& vcf) {
            vcf.parameters.front().domain =
                talas::expr::ValueDomain::Hertz;
        },
        "C19 VCF forged amplitude domain");
    mutateVcf(
        [](auto&, auto& vcf) {
            vcf.parameters.front().expression.reset();
        },
        "C19 VCF missing numeric expression authority");
    mutateVcf(
        [](auto&, auto& vcf) {
            vcf.parameters.front().value = 0.25;
        },
        "C19 VCF forged static expression value");
    mutateVcf(
        [](auto&, auto& vcf) {
            ++vcf.parameters.front().variableScopeId;
        },
        "C19 VCF forged static variable scope");
    mutateVcf(
        [](auto&, auto& vcf) {
            vcf.parameters.pop_back();
        },
        "C19 VCF missing resonance parameter");
    mutateVcf(
        [](auto& plan, auto& vcf) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == vcf.nodeId
                        && buffer.portId == "audioOut"
                        && buffer.scopeId == vcf.scopeId;
                });
            require(output != plan.buffers.end(),
                    "C19 output fixture should expose VCF audioOut");
            plan.buffers.push_back(*output);
        },
        "C19 VCF duplicate output ownership");
    mutateVcf(
        [](auto& plan, auto& vcf) {
            const auto audioInput = std::ranges::find(
                vcf.inputs,
                std::string_view{"audioIn"},
                &talas::runtime::InputBinding::inputPortId);
            require(audioInput != vcf.inputs.end(),
                    "C19 pseudo-producer fixture should expose audioIn");
            auto forged = plan.buffers[audioInput->bufferIndex];
            forged.portId = "forgedAudioOut";
            audioInput->sourcePortId = forged.portId;
            audioInput->bufferIndex = plan.buffers.size();
            plan.buffers.push_back(std::move(forged));
        },
        "C19 VCF unproduced audio buffer");
    mutateVcf(
        [](auto& plan, auto& vcf) {
            const auto oscillator = std::ranges::find(
                plan.steps,
                std::string_view{"talas.oscillator"},
                &talas::runtime::CompileStep::typeId);
            require(
                oscillator != plan.steps.end()
                    && vcf.inputLatencyFrames.front().has_value(),
                "C19 audio latency fixture should expose oscillator authority");
            oscillator->resolvedLatencyFrames = 1;
            oscillator->cumulativeInputLatencyFrames = 0;
            oscillator->cumulativeOutputLatencyFrames = 1;
            vcf.inputLatencyFrames.front() = 1;
            vcf.cumulativeInputLatencyFrames = 1;
            vcf.cumulativeOutputLatencyFrames = 1;
        },
        "C19 VCF coherently forged audio ancestry latency");

    auto connectedDocument = makeRealtimeVcfDocument();
    connectedDocument.graph.nodes.push_back(node(
        "c19Control", "talas.constant", {{"value", "0.5"}}));
    connectedDocument.graph.connections.push_back(connection(
        "c19Control", "value", "vcf", "amplitude"));
    const auto connected = compile(
        connectedDocument,
        talas::runtime::RenderSettings{8.0, 2});
    const auto mutateConnected = [&](auto mutate, std::string_view context) {
        auto plan = connected.plan();
        const auto vcf = findVcf(plan);
        require(vcf != plan.steps.end(),
                "C19 connected forged fixture should expose VCF");
        mutate(plan, *vcf);
        requireRejected(
            std::move(plan), connected.renderSettings(), context);
    };
    mutateConnected(
        [](auto&, auto& vcf) {
            std::swap(vcf.inputs[0], vcf.inputs[1]);
            std::swap(
                vcf.inputLatencyFrames[0],
                vcf.inputLatencyFrames[1]);
        },
        "C19 VCF reordered input bindings");
    mutateConnected(
        [](auto&, auto& vcf) {
            vcf.inputs.push_back(vcf.inputs.back());
            vcf.inputLatencyFrames.push_back(
                vcf.inputLatencyFrames.back());
        },
        "C19 VCF duplicate control binding");
    mutateConnected(
        [](auto&, auto& vcf) {
            require(
                !vcf.inputLatencyFrames[1].has_value(),
                "C19 Control latency fixture should begin nullopt");
            vcf.inputLatencyFrames[1] = 0;
        },
        "C19 VCF forged Control input latency");
    mutateConnected(
        [](auto& plan, auto&) {
            const auto control = std::ranges::find(
                plan.steps,
                std::string_view{"talas.constant"},
                &talas::runtime::CompileStep::typeId);
            require(control != plan.steps.end(),
                    "C19 Control ancestry fixture should expose Constant");
            control->resolvedLatencyFrames = 1;
            control->cumulativeInputLatencyFrames = 0;
            control->cumulativeOutputLatencyFrames = 1;
        },
        "C19 VCF forged Control-source latency");
    mutateConnected(
        [](auto&, auto& vcf) {
            vcf.parameters.front().value = 0.25;
        },
        "C19 VCF forged connected fallback value");
    mutateConnected(
        [](auto&, auto& vcf) {
            ++vcf.parameters.front().variableScopeId;
        },
        "C19 VCF forged connected fallback scope");
    mutateConnected(
        [](auto&, auto& vcf) {
            const auto parsed = talas::expr::parse("!C19Missing");
            require(
                parsed.ok(),
                "C19 unresolved Event fixture should parse");
            vcf.parameters.front().expression = *parsed.expression;
        },
        "C19 VCF unresolved connected fallback Event reference");
    mutateConnected(
        [](auto& plan, auto&) {
            const auto control = std::ranges::find(
                plan.steps,
                std::string_view{"talas.constant"},
                &talas::runtime::CompileStep::typeId);
            require(
                control != plan.steps.end()
                    && control->resolvedLatencyFrames == 0
                    && control->cumulativeOutputLatencyFrames == 0,
                "C127 Constant latency fixture should begin with exact zero latency");
            control->resolvedLatencyFrames.reset();
            control->cumulativeOutputLatencyFrames.reset();
        },
        "C127 VCF coherently forged unknown-latency Constant ancestry");
    mutateConnected(
        [](auto& plan, auto&) {
            const auto control = std::ranges::find(
                plan.steps,
                std::string_view{"talas.constant"},
                &talas::runtime::CompileStep::typeId);
            require(control != plan.steps.end(),
                    "C19 binding fixture should expose Constant");
            control->preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
            control->kernelKind = talas::runtime::KernelKind::Clock;
            control->resolvedLatencyFrames = 0;
            control->cumulativeOutputLatencyFrames = 0;
        },
        "C19 VCF coherently forged Constant kernel authority");
    mutateConnected(
        [](auto& plan, auto&) {
            const auto control = std::ranges::find(
                plan.steps,
                std::string_view{"talas.constant"},
                &talas::runtime::CompileStep::typeId);
            require(control != plan.steps.end(),
                    "C19 output-schema fixture should expose Constant");
            plan.buffers.push_back({
                control->nodeId,
                "forgedAudioOut",
                talas::core::PortType::Audio,
                plan.buffers.front().frames,
                control->scopeId,
            });
            control->resolvedLatencyFrames = 0;
            control->cumulativeOutputLatencyFrames = 0;
        },
        "C19 VCF forged Constant Audio output authority");

    auto variableDocument = makeRealtimeVcfDocument();
    variableDocument.expressionLanguage =
        talas::expr::ExpressionLanguageVersion::VariablesV1;
    talas::project::ProjectVariableDeclaration amplitudeVariable;
    amplitudeVariable.variableId = "c19Amplitude";
    amplitudeVariable.displayName = "C19 amplitude";
    amplitudeVariable.initialValue = 0.75;
    amplitudeVariable.snapshotEligible = false;
    auto otherVariable = amplitudeVariable;
    otherVariable.variableId = "c19Other";
    otherVariable.displayName = "C19 other";
    variableDocument.variableLibrary.variables = {
        amplitudeVariable, otherVariable};
    const auto variableVcfNode = std::ranges::find(
        variableDocument.graph.nodes,
        std::string_view{"vcf"},
        &talas::project::ProjectNode::instanceId);
    require(
        variableVcfNode != variableDocument.graph.nodes.end(),
        "C19 variable authority fixture should expose VCF");
    const auto variableAmplitude = std::ranges::find(
        variableVcfNode->parameters,
        std::string_view{"amplitude"},
        &talas::project::ProjectParameterExpression::parameterId);
    require(
        variableAmplitude != variableVcfNode->parameters.end(),
        "C19 variable authority fixture should expose amplitude");
    variableAmplitude->expression = "@c19Amplitude";
    const auto variableCompiled = compile(
        variableDocument,
        talas::runtime::RenderSettings{8.0, 2});
    const auto otherCell = std::ranges::find_if(
        variableCompiled.preparedVariables().cells,
        [](const auto& cell) {
            return cell.identity.variableId == "c19Other";
        });
    require(
        otherCell != variableCompiled.preparedVariables().cells.end(),
        "C19 variable authority fixture should expose alternate cell");
    const auto otherCellIndex = static_cast<std::uint32_t>(
        std::distance(
            variableCompiled.preparedVariables().cells.begin(),
            otherCell));
    const auto mutateVariable = [&](auto mutate, std::string_view context) {
        auto plan = variableCompiled.plan();
        const auto vcf = findVcf(plan);
        require(
            vcf != plan.steps.end(),
            "C19 variable forged fixture should expose VCF");
        mutate(*vcf);
        requireRejected(
            std::move(plan),
            variableCompiled.renderSettings(),
            context);
    };
    mutateVariable(
        [&](auto& vcf) {
            vcf.parameters.front().variableCellIndices.front() =
                otherCellIndex;
        },
        "C19 VCF forged variable-cell identity");
    mutateVariable(
        [&](auto& vcf) {
            const auto parsed = talas::expr::parse(
                "@c19Other",
                talas::expr::ExpressionLanguageVersion::VariablesV1);
            require(
                parsed.ok(),
                "C19 alternate variable fixture should parse");
            vcf.parameters.front().expression = *parsed.expression;
        },
        "C19 VCF forged variable reference mapping");
    mutateVariable(
        [&](auto& vcf) {
            vcf.parameters.front().variableCellIndices.front() =
                static_cast<std::uint32_t>(
                    variableCompiled.preparedVariables().cells.size());
        },
        "C19 VCF out-of-bounds variable-cell authority");

    auto connectedVariableDocument = variableDocument;
    connectedVariableDocument.graph.nodes.push_back(node(
        "c19VariableControl", "talas.constant", {{"value", "0.75"}}));
    connectedVariableDocument.graph.connections.push_back(connection(
        "c19VariableControl", "value", "vcf", "amplitude"));
    const auto connectedVariable = compile(
        connectedVariableDocument,
        talas::runtime::RenderSettings{8.0, 2});
    auto connectedVariablePlan = connectedVariable.plan();
    const auto connectedVariableVcf = findVcf(connectedVariablePlan);
    require(
        connectedVariableVcf != connectedVariablePlan.steps.end(),
        "C19 connected variable fixture should expose VCF");
    connectedVariableVcf->parameters.front().variableCellIndices.front() =
        otherCellIndex;
    requireRejected(
        std::move(connectedVariablePlan),
        connectedVariable.renderSettings(),
        "C19 VCF forged connected fallback variable cell");

    auto clockDocument = makeRealtimeVcfDocument();
    clockDocument.graph.nodes.push_back(node(
        "c19Clock", "talas.clock", {
            {"frequency", "1 hz"},
            {"dutyCycle", "0.5"},
        }));
    clockDocument.graph.connections.push_back(connection(
        "c19Clock", "gate", "vcf", "amplitude"));
    const auto clockCompiled = compile(
        clockDocument,
        talas::runtime::RenderSettings{8.0, 2});
    auto clockPlan = clockCompiled.plan();
    const auto clock = std::ranges::find(
        clockPlan.steps,
        std::string_view{"talas.clock"},
        &talas::runtime::CompileStep::typeId);
    require(
        clock != clockPlan.steps.end()
            && clock->resolvedLatencyFrames == 0
            && clock->cumulativeOutputLatencyFrames == 0,
        "C19 Clock latency fixture should begin 0/0");
    clock->resolvedLatencyFrames.reset();
    clock->cumulativeOutputLatencyFrames.reset();
    requireRejected(
        std::move(clockPlan),
        clockCompiled.renderSettings(),
        "C19 VCF coherently forged unknown-latency Clock ancestry");
}

void testRealtimeVcfResetRestageAndNestedStateStayExact()
{
    const auto graph = compile(
        makeRealtimeVcfDocument(),
        talas::runtime::RenderSettings{8.0, 7});
    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        "C19 VCF lifecycle fixture should prepare: "
            + std::string{session.error()});
    std::array<double, 7> first{};
    std::array<double, 7> reset{};
    std::size_t allocations = 0;
    require(
        renderAndCount(session, first, allocations)
            && allocations == 0,
        "C19 VCF initial state trajectory should render without allocation");
    session.resetTransport();
    require(
        renderAndCount(session, reset, allocations)
            && allocations == 0
            && reset == first,
        "C19 VCF reset should reproduce four exact zero states");

    talas::runtime::RealtimeRenderSession restaged(graph);
    talas::runtime::RealtimeRenderSession fresh(graph);
    std::array<double, 5> restagedOutput{};
    std::array<double, 5> freshOutput{};
    require(
        restaged.ready() && fresh.ready()
            && renderAndCount(
                restaged, restagedOutput, allocations)
            && renderAndCount(fresh, freshOutput, allocations)
            && allocations == 0
            && restagedOutput == freshOutput,
        "C19 replacement/restage should create independent zeroed VCF states");

    const auto nestedGraph = compile(
        makeNestedRealtimeVcfDocument(),
        talas::runtime::RenderSettings{8.0, 9});
    std::vector<talas::runtime::RuntimeScopeId> scopes;
    for (const auto& step : nestedGraph.plan().steps)
    {
        if (step.typeId == "talas.vcf")
            scopes.push_back(step.scopeId);
    }
    require(
        scopes.size() == 2
            && scopes[0] != scopes[1]
            && scopes[0] != talas::runtime::globalRuntimeScope
            && scopes[1] != talas::runtime::globalRuntimeScope,
        "C19 nested VCF siblings should own distinct structural state scopes");
    const auto nestedExpected = talas::runtime::renderOffline(
        nestedGraph, 9);
    talas::runtime::RealtimeRenderSession nestedSession(nestedGraph);
    std::array<double, 9> nestedActual{};
    require(
        nestedExpected.ok() && nestedSession.ready()
            && renderAndCount(
                nestedSession, nestedActual, allocations)
            && allocations == 0
            && std::ranges::equal(
                nestedActual, nestedExpected.mono),
        "C19 nested VCF siblings should remain isolated and sample-identical");
}

void testRealtimeVcfRollsBackWholeSegmentedCallback()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("formants", "talas.twoFormantElement", {
            {"formant1", "1 hz"},
            {"bandwidth1", "0.5 hz"},
            {"scale1", "0.75"},
            {"formant2", "2 hz"},
            {"bandwidth2", "0.75 hz"},
            {"scale2", "-0.25"},
        }),
        node("vcf", "talas.vcf", {
            {"amplitude", "0.75"},
            {"cutoff", "2 hz"},
            {"cutoffModulator", "0.25"},
            {"cutoffModRange", "1 hz"},
            {"resonance", "0.25"},
        }),
        node("oscillator", "talas.oscillator", {
            {"frequency", "1 hz"}, {"amplitude", "0.75"},
        }),
        node("formantControl", "talas.constant", {
            {"value", "!C19DownstreamFormant"},
        }),
    };
    document.graph.connections = {
        connection("oscillator", "audioOut", "vcf", "audioIn"),
        connection("vcf", "audioOut", "formants", "audioIn"),
        connection("formantControl", "value", "formants", "formant1"),
        connection("formants", "audioOut", "out", "audioIn"),
    };
    auto settings = talas::runtime::RenderSettings{8.0, 7};
    settings.eventValues.push_back({
        "C19DownstreamFormant", 1.0,
        talas::expr::ValueDomain::Scalar});
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(
        candidate.ready() && reference.ready(),
        "C19 whole-callback rollback fixtures should prepare");
    require(
        candidate.scheduleEventValue(
            "C19DownstreamFormant",
            4.0,
            talas::expr::ValueDomain::Scalar,
            1),
        "C19 invalid downstream formant should split the callback at frame one");
    std::array<double, 2> failed{1.0, 1.0};
    std::size_t allocations = 0;
    require(
        !renderAndCount(candidate, failed, allocations)
            && allocations == 0
            && failed == std::array<double, 2>{},
        "C19 later successor failure should publish no callback audio");
    require(
        candidate.updateEventValue(
            "C19DownstreamFormant", 1.0,
            talas::expr::ValueDomain::Scalar),
        "C19 downstream control should recover after failure");
    std::array<double, 7> candidateContinuation{};
    std::array<double, 7> referenceContinuation{};
    const auto candidateRendered = renderAndCount(
            candidate, candidateContinuation, allocations)
        && allocations == 0;
    const auto referenceRendered = renderAndCount(
        reference, referenceContinuation, allocations)
        && allocations == 0;
    require(
        candidateRendered && referenceRendered
            && candidateContinuation == referenceContinuation,
        "C19 failed callback must roll back oscillator, all four VCF stages, and successor state");
}

void testRealtimeVcfRollsBackSegmentedDiskRecorderState()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("recorder", "talas.diskRecorder", {
            resourceParameter("fileName", "Recordings/C19Rollback"),
            textParameter("format", "WAV"),
            textParameter("wordSize", "16"),
            choiceParameter("channels", "mono"),
            {"trigger", "1"},
            {"captureDuration", "0.25 s"},
            booleanParameter("gated", false),
        }),
        node("vcf", "talas.vcf", {
            {"amplitude", "1"}, {"cutoff", "2 hz"},
            {"cutoffModulator", "0"},
            {"cutoffModRange", "0 hz"}, {"resonance", "0.25"},
        }),
        node("cutoff", "talas.constant", {
            {"value", "!C19RecorderCutoff"},
        }),
        node("trigger", "talas.constant", {{"value", "1"}}),
        node("input", "talas.audioInput", {
            booleanParameter("channel1", true),
            booleanParameter("channel2", false),
        }),
    };
    document.graph.connections = {
        connection("input", "audioOut", "vcf", "audioIn"),
        connection("cutoff", "value", "vcf", "cutoff"),
        connection("vcf", "audioOut", "recorder", "audioIn"),
        connection("trigger", "value", "recorder", "trigger"),
    };
    auto settings = talas::runtime::RenderSettings{8.0, 2};
    settings.eventValues.push_back({
        "C19RecorderCutoff", 2.0,
        talas::expr::ValueDomain::Scalar});
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(
        candidate.ready() && reference.ready(),
        "C19 VCF→Disk Recorder rollback fixtures should prepare");
    require(
        candidate.scheduleEventValue(
            "C19RecorderCutoff", 4.0,
            talas::expr::ValueDomain::Scalar, 1),
        "C19 recorder fixture should split before invalid VCF cutoff");

    const auto renderInputAndCount = [](
                                         talas::runtime::RealtimeRenderSession& session,
                                         talas::runtime::RealtimeAudioInputBlock input,
                                         std::span<double> output,
                                         std::size_t& allocationResult) {
        std::array<double*, 1> channels{output.data()};
        AllocationCounter counter;
        const auto rendered = session.render(
            input,
            channels.data(),
            channels.size(),
            output.size());
        allocationResult = counter.count();
        return rendered;
    };
    std::array<float, 2> failedInput{0.5F, 0.25F};
    std::array<const float*, 1> failedChannels{failedInput.data()};
    std::array<double, 2> failedOutput{1.0, 1.0};
    std::size_t allocations = 0;
    require(
        !renderInputAndCount(
            candidate,
            {failedChannels.data(), failedChannels.size()},
            failedOutput,
            allocations)
            && allocations == 0
            && failedOutput == std::array<double, 2>{},
        "C19 VCF failure after recorder prefix should publish no audio");
    require(
        candidate.updateEventValue(
            "C19RecorderCutoff", 2.0,
            talas::expr::ValueDomain::Scalar),
        "C19 recorder cutoff should recover after failure");

    std::array<float, 2> continuationInput{0.25F, 0.125F};
    std::array<const float*, 1> continuationChannels{
        continuationInput.data()};
    std::array<double, 2> candidateContinuation{};
    std::array<double, 2> referenceContinuation{};
    const talas::runtime::RealtimeAudioInputBlock continuationBlock{
        continuationChannels.data(), continuationChannels.size()};
    require(
        renderInputAndCount(
            candidate,
            continuationBlock,
            candidateContinuation,
            allocations)
            && allocations == 0
            && renderInputAndCount(
                reference,
                continuationBlock,
                referenceContinuation,
                allocations)
            && allocations == 0
            && candidateContinuation == referenceContinuation,
        "C19 failed callback must roll back VCF and Disk Recorder capture fields");
}

