void testCheckedFirRejectsCancelledOverflowBeforeCommit()
{
    const std::array<double, 3> coefficients{
        1.0e308, 1.0e308, -1.0e308};
    std::array<double, 2> history{1.0, 1.0};
    const auto originalHistory = history;
    double output = 17.0;
    require(
        !talas::runtime::checked_fir::processSample(
            coefficients, history, 1.0, output),
        "C18 FIR should reject an overflowing ordered sum before later cancellation");
    require(
        history == originalHistory && output == 17.0,
        "failed C18 FIR arithmetic must not commit output or history");

    const std::array<double, 2> productOverflowCoefficients{
        1.0, 1.0e308};
    std::array<double, 1> productOverflowHistory{2.0};
    const auto productOverflowOriginal = productOverflowHistory;
    output = 23.0;
    require(
        !talas::runtime::checked_fir::processSample(
            productOverflowCoefficients,
            productOverflowHistory,
            0.0,
            output),
        "C18 FIR should reject a non-finite tap product");
    require(
        productOverflowHistory == productOverflowOriginal
            && output == 23.0,
        "failed C18 FIR product must not commit output or history");
}

void testCheckedTptVcfRejectsOverflowBeforeStateCommit()
{
    constexpr auto maximum = std::numeric_limits<double>::max();
    const auto requireRejected = [](
                                     double sampleRate,
                                     double input,
                                     double amplitude,
                                     double cutoff,
                                     double cutoffModulator,
                                     double cutoffModRange,
                                     double resonance,
                                     talas::runtime::checked_tpt_vcf::Stages state,
                                     std::string_view context) {
        const auto original = state;
        double output = 17.0;
        require(
            !talas::runtime::checked_tpt_vcf::processSample(
                sampleRate,
                input,
                amplitude,
                cutoff,
                cutoffModulator,
                cutoffModRange,
                resonance,
                state,
                output),
            std::string{context} + " should reject ordered overflow");
        require(
            std::ranges::equal(
                state,
                original,
                {},
                [](const auto& stage) {
                    return std::pair{stage.ic1eq, stage.ic2eq};
                },
                [](const auto& stage) {
                    return std::pair{stage.ic1eq, stage.ic2eq};
                }),
            std::string{context}
                + " should preserve all four prior stages");
        require(
            output == 17.0,
            std::string{context}
                + " should not publish an output candidate");
    };

    talas::runtime::checked_tpt_vcf::Stages stageDifference{};
    stageDifference.front().ic1eq = -maximum;
    requireRejected(
        8.0, maximum, 1.0, 2.0, 0.0, 0.0, 0.0,
        stageDifference,
        "C19 stage difference");

    requireRejected(
        maximum, 0.0, 1.0, 1.0, -maximum, 2.0, 0.0, {},
        "C19 modulation product before clamping cancellation");
    requireRejected(
        maximum, 0.0, 1.0, maximum * 0.25,
        maximum, 1.0, 0.0, {},
        "C19 modulation sum before clamping");
    requireRejected(
        maximum, 0.0, 1.0, maximum * 0.49,
        0.0, 0.0, 0.0, {},
        "C19 coefficient angle product");
    requireRejected(
        8.0, maximum, 2.0, 2.0, 0.0, 0.0, 0.0, {},
        "C19 amplitude product before feedback cancellation");

    talas::runtime::checked_tpt_vcf::Stages stateSumOverflow{};
    stateSumOverflow[0].ic1eq = maximum;
    stateSumOverflow[1].ic1eq = maximum;
    requireRejected(
        8.0, 0.0, 1.0, 2.0, 0.0, 0.0, 0.0,
        stateSumOverflow,
        "C19 zero-delay feedback state sum");

    talas::runtime::checked_tpt_vcf::Stages feedbackProduct{};
    feedbackProduct.back().ic1eq = maximum;
    requireRejected(
        8.0, 0.0, 1.0, 2.0, 0.0, 0.0, 1.0,
        feedbackProduct,
        "C19 resonance feedback product");

    talas::runtime::checked_tpt_vcf::Stages feedbackSubtraction{};
    feedbackSubtraction.back().ic1eq = -maximum * 0.5;
    requireRejected(
        8.0, maximum * 0.75, 1.0, 2.0, 0.0, 0.0, 1.0,
        feedbackSubtraction,
        "C19 input-feedback subtraction");

    talas::runtime::checked_tpt_vcf::Stages stageSum{};
    stageSum.front().ic1eq = maximum * 0.75;
    requireRejected(
        8.0, maximum, 1.0, 3.999, 0.0, 0.0, 0.0,
        stageSum,
        "C19 stage state sum");
}

void testCheckedHarmonicResonatorMathRejectsBeforeCommit()
{
    using namespace talas::runtime::checked_harmonic_resonator;

    Period period;
    require(
        preparePeriod(8.0, 2.0, 8, period)
            && period.seconds == 0.5
            && period.delaySamples == 4,
        "C20 checked period preparation should preserve reciprocal and rounding");
    require(
        preparePeriod(8.0, 1.0, 8, period)
            && period.seconds == 1.0
            && period.delaySamples == 8,
        "C20 checked period preparation should admit the exact prepared-history bound");
    require(
        preparePeriod(3.0, 2.0, 2, period)
            && period.seconds == 0.5
            && period.delaySamples == 2,
        "C20 checked period preparation should round an exact positive half-sample tie upward");
    require(
        preparePeriod(
            3.0,
            std::nextafter(
                2.0,
                std::numeric_limits<double>::infinity()),
            2,
            period)
            && period.delaySamples == 1,
        "C20 checked period preparation should round just below the half-sample tie downward");
    require(
        preparePeriod(
            3.0,
            std::nextafter(2.0, 0.0),
            2,
            period)
            && period.delaySamples == 2,
        "C20 checked period preparation should round just above the half-sample tie upward");
    const auto originalPeriod = period;
    require(
        !preparePeriod(8.0, 2.0, 3, period)
            && period.seconds == originalPeriod.seconds
            && period.delaySamples == originalPeriod.delaySamples,
        "C20 checked period preparation should reject the first sample beyond the prepared bound");

    double feedback = 17.0;
    require(
        computeFeedback(0.5, 0.5, feedback)
            && feedback == 0.001,
        "C20 checked feedback should preserve the sixty-decibel decay law");
    require(
        computeFeedback(
            1.0,
            std::numeric_limits<double>::min(),
            feedback)
            && feedback == 0.0,
        "C20 checked feedback should accept finite-ratio power underflow as exact extinction");
    const auto originalFeedback = feedback;
    require(
        !computeFeedback(
            std::numeric_limits<double>::max(),
            std::numeric_limits<double>::min(),
            feedback)
            && feedback == originalFeedback,
        "C20 checked feedback should reject an overflowing decay ratio before commit");

    FrameCandidate candidate{11.0, 13.0, 17.0};
    const auto originalCandidate = candidate;
    require(
        !processFrame(
            std::numeric_limits<double>::max(),
            2.0,
            1.0,
            0.5,
            1,
            0.0,
            0.0,
            candidate)
            && candidate == originalCandidate,
        "C20 checked frame transition should reject excitation overflow before commit");
    require(
        !processFrame(
            0.0,
            1.0,
            0.0,
            0.0,
            1,
            std::numeric_limits<double>::max(),
            -std::numeric_limits<double>::max(),
            candidate)
            && candidate == originalCandidate,
        "C20 checked frame transition should reject a concealed brightness-difference overflow before reassociation or commit");
    require(
        !processFrame(
            0.0,
            1.0,
            2.0,
            0.0,
            1,
            std::numeric_limits<double>::max(),
            0.0,
            candidate)
            && candidate == originalCandidate,
        "C20 checked frame transition should reject brightness recombination overflow before commit");
    require(
        processFrame(
            0.25,
            0.75,
            1.0,
            0.5,
            1,
            0.125,
            0.0,
            candidate)
            && candidate.output == 0.125
            && candidate.writeSample == 0.25
            && candidate.brightnessLowPass == 0.0,
        "C20 checked frame transition should preserve the accepted arithmetic order");
}

void testRealtimeStaticFirFamilyEnforcesPreparedTapAndResourceBounds()
{
    const auto coefficientText = [](std::size_t count) {
        std::string text;
        text.reserve(count * 2);
        for (std::size_t index = 0; index < count; ++index)
            text += "1 ";
        return text;
    };
    const auto firDocument = [&](std::size_t count) {
        auto document = makeRealtimeFirFilterDocument();
        const auto fir = std::ranges::find(
            document.graph.nodes,
            std::string_view{"fir"},
            &talas::project::ProjectNode::instanceId);
        require(
            fir != document.graph.nodes.end(),
            "C18 FIR tap-bound fixture should expose its node");
        fir->parameters.front() = textParameter(
            "coefficients", coefficientText(count));
        return document;
    };

    auto maximumGraph = compile(
        firDocument(talas::runtime::checked_fir::maximumPreparedTapCount),
        talas::runtime::RenderSettings{8.0, 1});
    talas::runtime::RealtimeRenderSession maximumSession(maximumGraph);
    require(
        maximumSession.ready(),
        "C18 FIR should admit exactly 4096 taps: "
            + std::string{maximumSession.error()});
    std::array<double, 1> maximumOutput{};
    std::size_t allocations = 0;
    require(
        renderAndCount(maximumSession, maximumOutput, allocations)
            && allocations == 0,
        "C18 maximum-tap FIR callback should render without allocation");

    auto oversizedGraph = compile(
        firDocument(
            talas::runtime::checked_fir::maximumPreparedTapCount + 1),
        talas::runtime::RenderSettings{8.0, 1});
    talas::runtime::RealtimeRenderSession oversizedSession(oversizedGraph);
    require(
        !oversizedSession.ready(),
        "C18 FIR should reject more than 4096 prepared taps");

    auto missingSettings = talas::runtime::RenderSettings{8.0, 1};
    auto missingGraph = compile(
        makeRealtimeReResonatorDocument(), missingSettings);
    talas::runtime::RealtimeRenderSession missingSession(missingGraph);
    require(
        !missingSession.ready(),
        "C18 RE Resonator should reject a missing immutable table");

    auto oversizedReSettings = talas::runtime::RenderSettings{8.0, 1};
    oversizedReSettings.tableResources.push_back({
        "Tables/C18/RE",
        std::vector<double>(
            talas::runtime::checked_fir::maximumPreparedTapCount + 1,
            1.0)});
    auto oversizedReGraph = compile(
        makeRealtimeReResonatorDocument(), oversizedReSettings);
    talas::runtime::RealtimeRenderSession oversizedReSession(
        oversizedReGraph);
    require(
        !oversizedReSession.ready(),
        "C18 RE Resonator should reject more than 4096 prepared taps");

    auto validReSettings = talas::runtime::RenderSettings{8.0, 1};
    validReSettings.tableResources.push_back({
        "Tables/C18/RE", {1.0}});
    const auto validReGraph = compile(
        makeRealtimeReResonatorDocument(), validReSettings);
    auto duplicateSettings = validReGraph.renderSettings();
    duplicateSettings.tableResources.push_back({
        "Tables/C18/RE", {1.0}});
    talas::runtime::RealtimeRenderSession duplicateSession(
        talas::runtime::PreparedRuntimeGraph{
            validReGraph.plan(), std::move(duplicateSettings)});
    require(
        !duplicateSession.ready(),
        "C18 RE Resonator should reject duplicate resource identity");

    constexpr std::size_t preparationLargestAllocationBudget =
        256U * 1024U;
    const auto hugeFirGraph = compile(
        firDocument(65536),
        talas::runtime::RenderSettings{8.0, 1});
    std::size_t hugeFirLargestAllocation = 0;
    bool hugeFirReady = false;
    {
        AllocationCounter counter;
        talas::runtime::RealtimeRenderSession session(hugeFirGraph);
        hugeFirReady = session.ready();
        hugeFirLargestAllocation = counter.largest();
    }
    require(
        !hugeFirReady
            && hugeFirLargestAllocation
                < preparationLargestAllocationBudget,
        "C18 FIR must stop parsing at tap 4097 without materializing an unbounded coefficient vector; largest allocation="
            + std::to_string(hugeFirLargestAllocation));

    auto hugeReSettings = talas::runtime::RenderSettings{8.0, 1};
    hugeReSettings.tableResources.push_back({
        "Tables/C18/RE", std::vector<double>(65536, 1.0)});
    const auto hugeReGraph = compile(
        makeRealtimeReResonatorDocument(), std::move(hugeReSettings));
    std::size_t hugeReLargestAllocation = 0;
    bool hugeReReady = false;
    {
        AllocationCounter counter;
        talas::runtime::RealtimeRenderSession session(hugeReGraph);
        hugeReReady = session.ready();
        hugeReLargestAllocation = counter.largest();
    }
    require(
        !hugeReReady
            && hugeReLargestAllocation
                < preparationLargestAllocationBudget,
        "C18 RE Resonator must validate the table bound before copying coefficients; largest allocation="
            + std::to_string(hugeReLargestAllocation));
}

void testRealtimeStaticFirFamilyResetsAndRollsBackExactHistory()
{
    const auto requireReset = [](
                                  const talas::project::ProjectDocument& document,
                                  talas::runtime::RenderSettings settings,
                                  std::string_view context) {
        auto graph = compile(document, std::move(settings));
        talas::runtime::RealtimeRenderSession session(graph);
        require(
            session.ready(),
            std::string{context} + " reset fixture should prepare: "
                + std::string{session.error()});
        std::array<double, 5> first{};
        std::array<double, 5> reset{};
        std::size_t allocations = 0;
        require(
            renderAndCount(session, first, allocations)
                && allocations == 0,
            std::string{context}
                + " initial history should render without allocation");
        session.resetTransport();
        require(
            renderAndCount(session, reset, allocations)
                && allocations == 0
                && reset == first,
            std::string{context}
                + " reset should reproduce the exact initial FIR history");
    };

    requireReset(
        makeRealtimeFirFilterDocument(),
        talas::runtime::RenderSettings{8.0, 5},
        "C18 FIR Filter");
    auto reSettings = talas::runtime::RenderSettings{8.0, 5};
    reSettings.tableResources.push_back({
        "Tables/C18/RE", {0.5, 0.25, -0.125}});
    requireReset(
        makeRealtimeReResonatorDocument(),
        std::move(reSettings),
        "C18 RE Resonator");

    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "formants", "talas.twoFormantElement", {
            {"formant1", "1 hz"}, {"bandwidth1", "0.5 hz"},
            {"scale1", "!C18Scale"}, {"formant2", "2 hz"},
            {"bandwidth2", "0.75 hz"}, {"scale2", "-0.25"},
        }));
    document.graph.nodes.push_back(node(
        "fir", "talas.firFilter", {
            textParameter("coefficients", "0.5 0.25 -0.125"),
        }));
    document.graph.nodes.push_back(node("input", "talas.audioInput", {
        booleanParameter("channel1", true),
        booleanParameter("channel2", false),
    }));
    document.graph.connections.push_back(connection(
        "input", "audioOut", "fir", "audioIn"));
    document.graph.connections.push_back(connection(
        "fir", "audioOut", "formants", "audioIn"));
    document.graph.connections.push_back(connection(
        "formants", "audioOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{8.0, 2};
    settings.eventValues.push_back({
        "C18Scale", 0.75, talas::expr::ValueDomain::Scalar});
    auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(
        candidate.ready() && reference.ready(),
        "C18 FIR→C17 rollback fixtures should prepare");
    require(
        candidate.scheduleEventValue(
            "C18Scale",
            1.0e308,
            talas::expr::ValueDomain::Scalar,
            1),
        "C18 downstream overflow should schedule in the second segment");
    const auto renderInputAndCount = [](
                                         talas::runtime::RealtimeRenderSession& session,
                                         talas::runtime::RealtimeAudioInputBlock input,
                                         std::span<double> output,
                                         std::size_t& allocationResult) {
        std::array<double*, 1> channels{output.data()};
        AllocationCounter counter;
        const auto rendered = session.render(
            input,
            channels.data(),
            channels.size(),
            output.size());
        allocationResult = counter.count();
        return rendered;
    };
    std::array<float, 2> failedInput{
        0.5F, std::numeric_limits<float>::max()};
    std::array<const float*, 1> failedInputChannels{
        failedInput.data()};
    std::array<double, 2> failed{1.0, 1.0};
    std::size_t allocations = 0;
    require(
        !renderInputAndCount(
            candidate,
            {failedInputChannels.data(), failedInputChannels.size()},
            failed,
            allocations)
            && allocations == 0
            && failed == std::array<double, 2>{},
        "failed C18 callback should publish no partial audio");
    require(
        candidate.updateEventValue(
            "C18Scale", 0.75, talas::expr::ValueDomain::Scalar),
        "C18 downstream scale should recover after failure");
    std::array<double, 2> candidateContinuation{};
    std::array<double, 2> referenceContinuation{};
    std::array<float, 2> validInput{0.5F, -0.25F};
    std::array<const float*, 1> validInputChannels{validInput.data()};
    const talas::runtime::RealtimeAudioInputBlock validInputBlock{
        validInputChannels.data(), validInputChannels.size()};
    require(
        renderInputAndCount(
            candidate,
            validInputBlock,
            candidateContinuation,
            allocations)
            && allocations == 0
            && renderInputAndCount(
                reference,
                validInputBlock,
                referenceContinuation,
                allocations)
            && allocations == 0
            && candidateContinuation == referenceContinuation,
        "failed C18 callback must roll back FIR and downstream C17 state");

    talas::project::ProjectDocument oscillatorDocument;
    oscillatorDocument.graph.nodes.push_back(node("out", "talas.audioOutput"));
    oscillatorDocument.graph.nodes.push_back(node(
        "fir", "talas.firFilter", {
            textParameter("coefficients", "2"),
        }));
    oscillatorDocument.graph.nodes.push_back(node(
        "oscillator", "talas.oscillator", {
            {"frequency", "1 hz"}, {"amplitude", "!C18Amplitude"},
        }));
    oscillatorDocument.graph.connections = {
        connection("oscillator", "audioOut", "fir", "audioIn"),
        connection("fir", "audioOut", "out", "audioIn"),
    };
    auto oscillatorSettings = talas::runtime::RenderSettings{8.0, 4};
    oscillatorSettings.eventValues.push_back({
        "C18Amplitude", std::numeric_limits<double>::max(),
        talas::expr::ValueDomain::Scalar});
    const auto oscillatorGraph = compile(
        oscillatorDocument, std::move(oscillatorSettings));
    talas::runtime::RealtimeRenderSession oscillatorCandidate(
        oscillatorGraph);
    talas::runtime::RealtimeRenderSession oscillatorReference(
        oscillatorGraph);
    require(
        oscillatorCandidate.ready() && oscillatorReference.ready(),
        "C18 oscillator rollback fixtures should prepare");
    std::array<double, 2> oscillatorFailed{1.0, 1.0};
    require(
        !renderAndCount(
            oscillatorCandidate, oscillatorFailed, allocations)
            && allocations == 0
            && oscillatorFailed == std::array<double, 2>{},
        "C18 oscillator→FIR overflow should fail without publishing audio");
    require(
        oscillatorCandidate.updateEventValue(
            "C18Amplitude", 0.5,
            talas::expr::ValueDomain::Scalar)
            && oscillatorReference.updateEventValue(
                "C18Amplitude", 0.5,
                talas::expr::ValueDomain::Scalar),
        "C18 oscillator rollback fixtures should recover their live amplitude");
    std::array<double, 4> oscillatorCandidateContinuation{};
    std::array<double, 4> oscillatorReferenceContinuation{};
    require(
        renderAndCount(
            oscillatorCandidate,
            oscillatorCandidateContinuation,
            allocations)
            && allocations == 0
            && renderAndCount(
                oscillatorReference,
                oscillatorReferenceContinuation,
                allocations)
            && allocations == 0
            && oscillatorCandidateContinuation
                == oscillatorReferenceContinuation,
        "failed C18 callback must roll back a mutable oscillator predecessor");

    talas::project::ProjectDocument delaySuccessorDocument;
    delaySuccessorDocument.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("delay", "talas.delayWithFeedback", {
            {"delay", "250 ms"}, {"feedback", "0.25"}, {"mix", "1"},
        }),
        node("fir", "talas.firFilter", {
            textParameter("coefficients", "0.5 0.25"),
        }),
        node("oscillator", "talas.oscillator", {
            {"frequency", "1 hz"}, {"amplitude", "4"},
        }),
    };
    delaySuccessorDocument.graph.connections = {
        connection("oscillator", "audioOut", "fir", "audioIn"),
        connection("fir", "audioOut", "delay", "audioIn"),
        connection("delay", "audioOut", "out", "audioIn"),
    };
    delaySuccessorDocument.graph.nodes.push_back(node("gain", "talas.constant", {{"value", "!C18DelayGain"}}));
    delaySuccessorDocument.graph.nodes.push_back(node("post", "talas.vca"));
    delaySuccessorDocument.graph.connections.back() = connection("delay", "audioOut", "post", "audioIn");
    delaySuccessorDocument.graph.connections.push_back(connection("gain", "value", "post", "gain"));
    delaySuccessorDocument.graph.connections.push_back(connection("post", "audioOut", "out", "audioIn"));
    talas::runtime::RenderSettings delaySettings{8.0, 4};
    delaySettings.eventValues = {{"C18DelayGain", 1.0, talas::expr::ValueDomain::Scalar}};
    const auto delaySuccessorGraph = compile(delaySuccessorDocument, delaySettings);
    talas::runtime::RealtimeRenderSession delaySuccessorSession(delaySuccessorGraph);
    require(delaySuccessorSession.ready(), "C18 must admit its now-checkpointed mutable delay successor");
    const auto delayExpected = talas::runtime::renderOffline(delaySuccessorGraph, 16);
    require(delayExpected.ok(), "C18 delay successor offline oracle must render");
    std::array<double, 16> delayOracle{};
    for (std::size_t frame = 2; frame < delayOracle.size(); ++frame)
    {
        const auto source = frame - 2;
        const auto fir = 2 * std::sin(2 * std::numbers::pi_v<double> * source / 8)
            + (source == 0 ? 0 : std::sin(2 * std::numbers::pi_v<double> * (source - 1) / 8));
        delayOracle[frame] = fir + 0.25 * delayOracle[frame - 2];
    }
    std::size_t delayPosition = 0;
    const auto renderDelay = [&](std::size_t frames) {
        std::array<double, 4> actual{};
        allocations = 0;
        require(renderAndCount(delaySuccessorSession, std::span{actual}.first(frames), allocations) && allocations == 0,
            "C18 FIR/delay continuation must render without callback allocation");
        for (std::size_t frame = 0; frame < frames; ++frame)
        {
            requireNear(actual[frame], delayOracle[delayPosition + frame], 1e-12,
                "C18 checkpointed successor must match independent FIR/feedback recurrence");
            requireNear(actual[frame], delayExpected.mono[delayPosition + frame], 1e-12,
                "C18 checkpointed successor must retain offline agreement");
        }
        delayPosition += frames;
    };
    renderDelay(3);
    require(delaySuccessorSession.updateEventValue("C18DelayGain", 1e308, talas::expr::ValueDomain::Scalar),
        "C18 delay successor high gain must be accepted before late overflow");
    for (int attempt = 0; attempt < 2; ++attempt)
    {
        std::array<double, 4> failed{1, 1, 1, 1};
        allocations = 0;
        require(!renderAndCount(delaySuccessorSession, failed, allocations) && allocations == 0
                && failed == std::array<double, 4>{},
            "C18 delay successor overflow must roll back every checkpoint and silence repeated failures");
    }
    require(delaySuccessorSession.updateEventValue("C18DelayGain", 1.0, talas::expr::ValueDomain::Scalar),
        "C18 delay successor gain must recover after failure");
    for (std::size_t frames : {4, 4, 4, 1}) renderDelay(frames);
    delaySuccessorSession.resetTransport();
    delayPosition = 0;
    renderDelay(4);

    auto frequencySuccessorDocument = delaySuccessorDocument;
    *std::ranges::find(frequencySuccessorDocument.graph.nodes, std::string_view{"delay"},
        &talas::project::ProjectNode::instanceId) = node("delay", "talas.frequencyScale", {
            {"frequencyScale", "1"}, {"maxScale", "1"}, resourceParameter("window", "Private"), {"delay", "0.25"},
        });
    frequencySuccessorDocument.graph.nodes.push_back(node("tracker", "talas.constant", {{"value", "440"}}));
    frequencySuccessorDocument.graph.connections.push_back(connection("tracker", "value", "delay", "freqTracker"));
    const auto frequencySuccessorGraph = compile(frequencySuccessorDocument, delaySettings);
    talas::runtime::RealtimeRenderSession frequencySuccessorSession(frequencySuccessorGraph);
    require(frequencySuccessorSession.ready(),
        "C18 must admit Frequency Scale with a general callback checkpoint");

}

void testRealtimeStaticFirRollsBackSegmentedDiskRecorderCapture()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("recorder", "talas.diskRecorder", {
            resourceParameter("fileName", "Recordings/C18Rollback"),
            textParameter("format", "WAV"),
            textParameter("wordSize", "16"),
            choiceParameter("channels", "mono"),
            {"trigger", "!C18RecorderTrigger"},
            {"captureDuration", "0.25 s"},
            booleanParameter("gated", false),
        }),
        node("fir", "talas.firFilter", {
            textParameter("coefficients", "1e308"),
        }),
        node("trigger", "talas.constant", {
            {"value", "!C18RecorderTrigger"},
        }),
        node("input", "talas.audioInput", {
            booleanParameter("channel1", true),
            booleanParameter("channel2", false),
        }),
    };
    document.graph.connections = {
        connection("input", "audioOut", "fir", "audioIn"),
        connection("fir", "audioOut", "recorder", "audioIn"),
        connection("trigger", "value", "recorder", "trigger"),
    };

    auto settings = talas::runtime::RenderSettings{8.0, 2};
    settings.eventValues.push_back({
        "C18RecorderTrigger", 1.0, talas::expr::ValueDomain::Scalar});
    const auto graph = compile(document, std::move(settings));
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(
        candidate.ready() && reference.ready(),
        "C18 FIR→Disk Recorder rollback fixtures should prepare");
    require(
        candidate.scheduleEventValue(
            "C18RecorderTrigger",
            1.0,
            talas::expr::ValueDomain::Scalar,
            1),
        "C18 Disk Recorder fixture should split before the failing FIR frame");

    const auto renderInputAndCount = [](
                                         talas::runtime::RealtimeRenderSession& session,
                                         talas::runtime::RealtimeAudioInputBlock input,
                                         std::span<double> output,
                                         std::size_t& allocationResult) {
        std::array<double*, 1> channels{output.data()};
        AllocationCounter counter;
        const auto rendered = session.render(
            input,
            channels.data(),
            channels.size(),
            output.size());
        allocationResult = counter.count();
        return rendered;
    };

    std::array<float, 2> failedInput{
        0.5F, std::numeric_limits<float>::max()};
    std::array<const float*, 1> failedChannels{failedInput.data()};
    std::array<double, 2> failedOutput{1.0, 1.0};
    std::size_t allocations = 0;
    require(
        !renderInputAndCount(
            candidate,
            {failedChannels.data(), failedChannels.size()},
            failedOutput,
            allocations)
            && allocations == 0
            && failedOutput == std::array<double, 2>{},
        "later FIR segment failure should publish no Disk Recorder audio");
    require(
        candidate.updateEventValue(
            "C18RecorderTrigger",
            1.0,
            talas::expr::ValueDomain::Scalar),
        "C18 Disk Recorder trigger should remain usable after failure");

    std::array<float, 2> continuationInput{0.25F, 0.125F};
    std::array<const float*, 1> continuationChannels{
        continuationInput.data()};
    std::array<double, 2> candidateContinuation{};
    std::array<double, 2> referenceContinuation{};
    const talas::runtime::RealtimeAudioInputBlock continuationBlock{
        continuationChannels.data(), continuationChannels.size()};
    require(
        renderInputAndCount(
            candidate,
            continuationBlock,
            candidateContinuation,
            allocations)
            && allocations == 0
            && renderInputAndCount(
                reference,
                continuationBlock,
                referenceContinuation,
                allocations)
            && allocations == 0
            && candidateContinuation == referenceContinuation,
        "failed segmented C18 callback must roll back Disk Recorder trigger and capture progress");
}

void testRealtimeStaticFirFamilyChainsAndNestedRestageStayIsolated()
{
    const auto makeChain = [](bool reFirst) {
        talas::project::ProjectDocument document;
        document.graph.nodes.push_back(node("out", "talas.audioOutput"));
        document.graph.nodes.push_back(node(
            "fir", "talas.firFilter", {
                textParameter("coefficients", "0.5 0.25 -0.125"),
            }));
        document.graph.nodes.push_back(node(
            "resonator", "talas.reResonator", {
                resourceParameter("wavetable", "Tables/C18/RE"),
                {"timeIndex", "0"},
                choiceParameter("filterForm", "legacyFir"),
            }));
        document.graph.nodes.push_back(node(
            "oscillator", "talas.oscillator", {
                {"frequency", "1 hz"}, {"amplitude", "0.75"},
            }));
        if (reFirst)
        {
            document.graph.connections = {
                connection(
                    "oscillator", "audioOut", "resonator", "audioIn"),
                connection(
                    "resonator", "audioOut", "fir", "audioIn"),
                connection("fir", "audioOut", "out", "audioIn"),
            };
        }
        else
        {
            document.graph.connections = {
                connection("oscillator", "audioOut", "fir", "audioIn"),
                connection(
                    "fir", "audioOut", "resonator", "audioIn"),
                connection(
                    "resonator", "audioOut", "out", "audioIn"),
            };
        }
        return document;
    };

    for (const auto reFirst : {false, true})
    {
        auto settings = talas::runtime::RenderSettings{8.0, 9};
        settings.tableResources.push_back({
            "Tables/C18/RE", {0.25, -0.5, 0.125}});
        auto graph = compile(makeChain(reFirst), settings);
        const auto expected = talas::runtime::renderOffline(graph, 9);
        require(
            expected.ok() && expected.mono.size() == 9,
            "C18 FIR/RE chain offline reference should render");
        talas::runtime::RealtimeRenderSession session(graph);
        require(
            session.ready(),
            "C18 FIR/RE chain should prepare in either order: "
                + std::string{session.error()});
        std::array<double, 9> actual{};
        constexpr std::array<std::size_t, 4> partitions{2, 1, 4, 2};
        std::size_t offset = 0;
        for (const auto partition : partitions)
        {
            std::size_t allocations = 0;
            require(
                renderAndCount(
                    session,
                    std::span<double>{actual}.subspan(offset, partition),
                    allocations)
                    && allocations == 0,
                "C18 FIR/RE chain should remain allocation-free across partitions");
            offset += partition;
        }
        require(
            std::ranges::equal(actual, expected.mono),
            "C18 FIR/RE chain should remain sample-identical in either order");
    }

    auto graph = compile(
        makeNestedRealtimeFirFilterDocument(),
        talas::runtime::RenderSettings{8.0, 7});
    std::vector<talas::runtime::RuntimeScopeId> firScopes;
    for (const auto& step : graph.plan().steps)
    {
        if (step.typeId == "talas.firFilter")
            firScopes.push_back(step.scopeId);
    }
    require(
        firScopes.size() == 2
            && firScopes[0] != firScopes[1]
            && firScopes[0] != talas::runtime::globalRuntimeScope
            && firScopes[1] != talas::runtime::globalRuntimeScope,
        "nested C18 FIR siblings should own distinct structural state scopes");

    const auto expected = talas::runtime::renderOffline(graph, 7);
    talas::runtime::RealtimeRenderSession session(graph);
    require(
        expected.ok() && session.ready(),
        "nested C18 FIR siblings should render offline and prepare realtime");
    std::array<double, 7> actual{};
    std::size_t allocations = 0;
    require(
        renderAndCount(session, actual, allocations)
            && allocations == 0
            && std::ranges::equal(actual, expected.mono),
        "nested C18 FIR siblings should remain isolated and sample-identical");

    talas::runtime::RealtimeRenderSession restaged(graph);
    talas::runtime::RealtimeRenderSession fresh(graph);
    std::array<double, 4> advanced{};
    std::array<double, 4> restagedOutput{};
    std::array<double, 4> freshOutput{};
    require(
        restaged.ready() && fresh.ready()
            && renderAndCount(session, advanced, allocations)
            && renderAndCount(restaged, restagedOutput, allocations)
            && renderAndCount(fresh, freshOutput, allocations)
            && allocations == 0
            && restagedOutput == freshOutput,
        "C18 replacement/restage should create independent zeroed FIR histories");

    auto nestedReSettings = talas::runtime::RenderSettings{8.0, 7};
    nestedReSettings.tableResources.push_back({
        "Tables/C18/RE", {0.5, 0.25, -0.125}});
    auto nestedReGraph = compile(
        makeNestedRealtimeReResonatorDocument(),
        nestedReSettings);
    std::vector<talas::runtime::RuntimeScopeId> resonatorScopes;
    for (const auto& step : nestedReGraph.plan().steps)
    {
        if (step.typeId == "talas.reResonator")
            resonatorScopes.push_back(step.scopeId);
    }
    require(
        resonatorScopes.size() == 2
            && resonatorScopes[0] != resonatorScopes[1]
            && resonatorScopes[0] != talas::runtime::globalRuntimeScope
            && resonatorScopes[1] != talas::runtime::globalRuntimeScope,
        "nested C18 RE Resonator siblings should own distinct structural state scopes");
    const auto nestedReExpected =
        talas::runtime::renderOffline(nestedReGraph, 7);
    talas::runtime::RealtimeRenderSession nestedReSession(nestedReGraph);
    std::array<double, 7> nestedReActual{};
    require(
        nestedReExpected.ok() && nestedReSession.ready()
            && renderAndCount(
                nestedReSession, nestedReActual, allocations)
            && allocations == 0
            && std::ranges::equal(
                nestedReActual, nestedReExpected.mono),
        "nested C18 RE Resonator siblings should remain isolated and sample-identical");
}

void testRealtimeStaticFirFamilyRejectsForgedPreparedAuthority()
{
    const auto requireRejected = [](
                                     talas::runtime::RuntimePlan plan,
                                     const talas::runtime::RenderSettings& settings,
                                     std::string_view context) {
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), settings});
        require(
            !session.ready(),
            std::string{context}
                + " should reject forged C18 prepared authority");
    };
    const auto verify = [&requireRejected](
                            const talas::project::ProjectDocument& document,
                            talas::runtime::RenderSettings settings,
                            std::string_view typeId) {
        const auto compiled = compile(document, settings);
        const auto findTarget = [typeId](talas::runtime::RuntimePlan& plan) {
            return std::ranges::find(
                plan.steps,
                typeId,
                &talas::runtime::CompileStep::typeId);
        };
        {
            auto plan = compiled.plan();
            const auto target = findTarget(plan);
            require(target != plan.steps.end(),
                    "C18 support fixture should expose its target");
            target->preparedRealtimeSupport =
                talas::core::ExecutionSupport::Supported;
            requireRejected(
                std::move(plan), compiled.renderSettings(),
                std::string{typeId} + " forged full support");
        }
        {
            auto plan = compiled.plan();
            const auto target = findTarget(plan);
            require(target != plan.steps.end(),
                    "C18 reset fixture should expose its target");
            target->supportsReset = false;
            requireRejected(
                std::move(plan), compiled.renderSettings(),
                std::string{typeId} + " forged reset contract");
        }
        {
            auto plan = compiled.plan();
            const auto target = findTarget(plan);
            require(target != plan.steps.end(),
                    "C18 latency fixture should expose its target");
            target->resolvedLatencyFrames = 1;
            requireRejected(
                std::move(plan), compiled.renderSettings(),
                std::string{typeId} + " forged latency");
        }
        {
            auto plan = compiled.plan();
            const auto target = findTarget(plan);
            require(
                target != plan.steps.end()
                    && target->inputLatencyFrames.size() == 1
                    && target->inputLatencyFrames.front().has_value()
                    && target->cumulativeInputLatencyFrames.has_value()
                    && target->cumulativeOutputLatencyFrames.has_value(),
                "C18 input-latency fixture should expose exact source authority");
            ++*target->inputLatencyFrames.front();
            ++*target->cumulativeInputLatencyFrames;
            ++*target->cumulativeOutputLatencyFrames;
            requireRejected(
                std::move(plan), compiled.renderSettings(),
                std::string{typeId}
                    + " forged predecessor latency authority");
        }
        {
            auto plan = compiled.plan();
            const auto target = findTarget(plan);
            require(target != plan.steps.end(),
                    "C18 duplicate output fixture should expose its target");
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == target->nodeId
                        && buffer.portId == "audioOut"
                        && buffer.scopeId == target->scopeId;
                });
            require(output != plan.buffers.end(),
                    "C18 duplicate output fixture should expose audioOut");
            plan.buffers.push_back(*output);
            requireRejected(
                std::move(plan), compiled.renderSettings(),
                std::string{typeId} + " duplicate output");
        }
    };

    verify(
        makeRealtimeFirFilterDocument(),
        talas::runtime::RenderSettings{8.0, 2},
        "talas.firFilter");

    const auto firCompiled = compile(
        makeRealtimeFirFilterDocument(),
        talas::runtime::RenderSettings{8.0, 2});
    const auto findFir = [](talas::runtime::RuntimePlan& plan) {
        return std::ranges::find(
            plan.steps,
            std::string_view{"talas.firFilter"},
            &talas::runtime::CompileStep::typeId);
    };
    {
        auto plan = firCompiled.plan();
        const auto target = findFir(plan);
        require(
            target != plan.steps.end() && target->inputs.size() == 1,
            "C18 duplicate-input fixture should expose exact FIR audioIn");
        target->inputs.push_back(target->inputs.front());
        target->inputLatencyFrames.push_back(
            target->inputLatencyFrames.front());
        requireRejected(
            std::move(plan), firCompiled.renderSettings(),
            "talas.firFilter duplicate audioIn binding");
    }
    {
        auto plan = firCompiled.plan();
        const auto target = findFir(plan);
        require(
            target != plan.steps.end() && target->inputs.size() == 1
                && target->inputs.front().bufferIndex
                    < plan.buffers.size(),
            "C18 pseudo-producer fixture should expose FIR source buffer");
        auto forgedBuffer =
            plan.buffers[target->inputs.front().bufferIndex];
        forgedBuffer.portId = "forgedAudioOut";
        target->inputs.front().sourcePortId = forgedBuffer.portId;
        target->inputs.front().bufferIndex = plan.buffers.size();
        plan.buffers.push_back(std::move(forgedBuffer));
        requireRejected(
            std::move(plan), firCompiled.renderSettings(),
            "talas.firFilter unproduced audio input buffer");
    }
    {
        auto plan = firCompiled.plan();
        std::ranges::stable_sort(
            plan.steps,
            [](const talas::runtime::CompileStep& left,
               const talas::runtime::CompileStep& right) {
                const auto rank = [](std::string_view typeId) {
                    if (typeId == "talas.firFilter")
                        return 0;
                    if (typeId == "talas.oscillator")
                        return 1;
                    return 2;
                };
                return rank(left.typeId) < rank(right.typeId);
            });
        requireRejected(
            std::move(plan), firCompiled.renderSettings(),
            "talas.firFilter consumer-before-source order");
    }
    {
        auto plan = firCompiled.plan();
        const auto target = findFir(plan);
        const auto oscillator = std::ranges::find(
            plan.steps,
            std::string_view{"talas.oscillator"},
            &talas::runtime::CompileStep::typeId);
        require(
            target != plan.steps.end()
                && oscillator != plan.steps.end()
                && target->inputLatencyFrames.size() == 1
                && target->inputLatencyFrames.front().has_value()
                && target->cumulativeInputLatencyFrames.has_value()
                && target->cumulativeOutputLatencyFrames.has_value()
                && oscillator->cumulativeInputLatencyFrames.has_value()
                && oscillator->cumulativeOutputLatencyFrames.has_value(),
            "C18 coherent-latency fixture should expose oscillator and FIR authority");
        *oscillator->cumulativeInputLatencyFrames = 1;
        *oscillator->cumulativeOutputLatencyFrames = 1;
        *target->inputLatencyFrames.front() = 1;
        *target->cumulativeInputLatencyFrames = 1;
        *target->cumulativeOutputLatencyFrames = 1;
        requireRejected(
            std::move(plan), firCompiled.renderSettings(),
            "talas.firFilter coherently forged source latency metadata");
    }
    {
        talas::project::ProjectDocument ancestryDocument;
        ancestryDocument.graph.nodes = {
            node("out", "talas.audioOutput"),
            node("fir", "talas.firFilter", {
                textParameter("coefficients", "0.5 0.25"),
            }),
            node("level", "talas.level", {
                {"left", "1"}, {"right", "0"},
                booleanParameter("noGain", false),
            }),
            node("oscillator", "talas.oscillator", {
                {"frequency", "1 hz"}, {"amplitude", "0.5"},
            }),
        };
        ancestryDocument.graph.connections = {
            connection("oscillator", "audioOut", "level", "audioIn"),
            connection("level", "leftOut", "fir", "audioIn"),
            connection("fir", "audioOut", "out", "audioIn"),
        };
        const auto ancestryCompiled = compile(
            ancestryDocument,
            talas::runtime::RenderSettings{8.0, 2});
        auto plan = ancestryCompiled.plan();
        const auto level = std::ranges::find(
            plan.steps,
            std::string_view{"talas.level"},
            &talas::runtime::CompileStep::typeId);
        require(
            level != plan.steps.end()
                && level->inputs.size() == 1
                && level->inputLatencyFrames.size() == 1
                && level->inputLatencyFrames.front()
                       == std::optional<std::size_t>{0},
            "C18 ancestor-latency fixture should expose exact Level audio latency");
        level->inputLatencyFrames.front() = std::nullopt;
        requireRejected(
            std::move(plan),
            ancestryCompiled.renderSettings(),
            "talas.firFilter forged null ancestor audio latency");
    }
    {
        auto plan = firCompiled.plan();
        const auto target = findFir(plan);
        require(
            target != plan.steps.end()
                && target->parameters.size() == 1,
            "C18 FIR parameter-shape fixture should expose coefficients");
        target->parameters.front().domain = talas::expr::ValueDomain::Hertz;
        requireRejected(
            std::move(plan), firCompiled.renderSettings(),
            "talas.firFilter forged coefficient domain");
    }
    {
        auto plan = firCompiled.plan();
        const auto target = findFir(plan);
        require(
            target != plan.steps.end()
                && target->parameters.size() == 1,
            "C18 FIR parameter-value fixture should expose coefficients");
        target->parameters.front().value = 1.0;
        requireRejected(
            std::move(plan), firCompiled.renderSettings(),
            "talas.firFilter forged text compatibility value");
    }
    {
        auto plan = firCompiled.plan();
        const auto target = findFir(plan);
        require(
            target != plan.steps.end()
                && target->parameters.size() == 1,
            "C18 FIR parameter-scope fixture should expose coefficients");
        target->parameters.front().variableScopeId =
            talas::runtime::globalRuntimeScope + 1;
        requireRejected(
            std::move(plan), firCompiled.renderSettings(),
            "talas.firFilter forged text compatibility scope");
    }


    const auto nested = compile(
        makeNestedRealtimeFirFilterDocument(),
        talas::runtime::RenderSettings{8.0, 2});
    auto nestedPlan = nested.plan();
    const auto nestedFir = std::ranges::find_if(
        nestedPlan.steps,
        [](const talas::runtime::CompileStep& step) {
            return step.typeId == "talas.firFilter"
                && step.scopeId != talas::runtime::globalRuntimeScope;
        });
    require(
        nestedFir != nestedPlan.steps.end()
            && nestedFir->eventValueScopeId == nestedFir->scopeId,
        "nested C18 FIR should expose exact structural authority scope");
    nestedFir->eventValueScopeId = talas::runtime::globalRuntimeScope;
    requireRejected(
        std::move(nestedPlan), nested.renderSettings(),
        "talas.firFilter forged nested authority scope");
}

void testRealtimeCheckedBiquadFamilyMatchesConnectedControls()
{
    const std::vector<double> control{
        0.5, 1.0, 1.5, 2.0, 1.0, 0.75, 1.25};
    const auto requireParity = [&control](
                                   talas::project::ProjectDocument document,
                                   talas::runtime::RenderSettings settings,
                                   std::string targetNodeId,
                                   std::string targetPortId,
                                   std::string_view context) {
        constexpr std::size_t frameCount = 7;
        connectRealtimeC17Control(
            document, std::move(targetNodeId), std::move(targetPortId));
        settings.maxBlockFrames = frameCount;
        settings.tableResources.push_back({
            "Tables/C17/Control", control});
        auto graph = compile(document, std::move(settings));
        const auto expected = talas::runtime::renderOffline(graph, frameCount);
        require(
            expected.ok() && expected.mono.size() == frameCount,
            std::string{context} + " connected offline reference should render");

        talas::runtime::RealtimeRenderSession session(graph);
        require(
            session.ready(),
            std::string{context} + " connected fixture should prepare: "
                + std::string{session.error()});
        std::array<double, frameCount> left{};
        std::array<double, frameCount> right{};
        std::size_t allocations = 0;
        const auto rendered = expected.right.empty()
            ? renderAndCount(session, left, allocations)
            : renderStereoAndCount(session, left, right, allocations);
        require(
            rendered,
            std::string{context} + " connected callback should render");
        require(
            allocations == 0,
            std::string{context} + " connected callback should not allocate");
        for (std::size_t frame = 0; frame < frameCount; ++frame)
        {
            requireNear(
                left[frame], expected.mono[frame], 1.0e-12,
                std::string{context} + " connected left parity frame");
            if (!expected.right.empty())
            {
                requireNear(
                    right[frame], expected.right[frame], 1.0e-12,
                    std::string{context} + " connected right parity frame");
            }
        }
    };

    requireParity(
        makeRealtimeTwoFormantElementDocument({
            {"formant1", "1 hz"}, {"bandwidth1", "0.5 hz"},
            {"scale1", "0.75"}, {"formant2", "2 hz"},
            {"bandwidth2", "0.75 hz"}, {"scale2", "-0.25"},
        }),
        talas::runtime::RenderSettings{8.0, 7},
        "formants", "scale1", "C17 Two Formant Element");
    requireParity(
        makeRealtimeTwoFormantVoiceElementDocument(),
        talas::runtime::RenderSettings{8.0, 7},
        "voice", "frequency", "C17 Two Formant Voice Element");
    requireParity(
        makeRealtimeDualParallelTwoPoleDocument(),
        talas::runtime::RenderSettings{8.0, 7},
        "twoPole", "scale1", "C17 Dual Parallel Two Pole Filter");
    requireParity(
        makeRealtimeGraphicEqDocument(),
        talas::runtime::RenderSettings{48000.0, 7},
        "eq", "cf500Hz", "C17 Graphic EQ");
    requireParity(
        makeRealtimeAnalysisFilterDocument(),
        talas::runtime::RenderSettings{8.0, 7},
        "analysis", "harmonic", "C17 Analysis Filter");
}

void testRealtimeCheckedBiquadFamilyMatchesDirectAndConnectedEventValues()
{
    const auto run = [](
                         talas::project::ProjectDocument direct,
                         talas::project::ProjectDocument connected,
                         talas::runtime::RenderSettings settings,
                         std::string targetNodeId,
                         std::string targetPortId,
                         talas::expr::ValueDomain directDomain,
                         double initialValue,
                         double updatedValue,
                         double rejectedValue,
                         bool stereo,
                         bool directRejectsAtSchedule,
                         bool connectedRejectsAtSchedule,
                         std::string_view context) {
        const auto setParameterExpression = [&targetNodeId, &targetPortId](
                                                talas::project::ProjectDocument& document,
                                                std::string expression) {
            for (auto& graphNode : document.graph.nodes)
            {
                if (graphNode.instanceId != targetNodeId)
                    continue;
                for (auto& parameter : graphNode.parameters)
                {
                    if (parameter.parameterId == targetPortId)
                    {
                        parameter.expression = std::move(expression);
                        return;
                    }
                }
            }
            require(false, "C17 Event Value fixture target parameter must exist");
        };

        setParameterExpression(direct, "!DirectControl");
        connected.graph.nodes.push_back(node(
            "eventControl", "talas.constant", {{"value", "!ConnectedControl"}}));
        connected.graph.connections.push_back(connection(
            "eventControl", "value", targetNodeId, targetPortId));
        settings.eventValues = {
            {"DirectControl", initialValue, directDomain},
            {"ConnectedControl", initialValue, talas::expr::ValueDomain::Scalar},
        };

        auto directGraph = compile(direct, settings);
        auto connectedGraph = compile(connected, settings);
        talas::runtime::RealtimeRenderSession directSession(directGraph);
        talas::runtime::RealtimeRenderSession connectedSession(connectedGraph);
        require(
            directSession.ready() && connectedSession.ready(),
            std::string{context}
                + " direct and connected Event Value sessions should prepare: "
                + std::string{directSession.ready()
                    ? connectedSession.error() : directSession.error()});

        const auto renderEqual = [&](std::size_t frames, std::string_view stage) {
            std::vector<double> directLeft(frames);
            std::vector<double> directRight(frames);
            std::vector<double> connectedLeft(frames);
            std::vector<double> connectedRight(frames);
            std::size_t allocations = 0;
            const auto directRendered = stereo
                ? renderStereoAndCount(
                    directSession, directLeft, directRight, allocations)
                : renderAndCount(directSession, directLeft, allocations);
            require(
                directRendered && allocations == 0,
                std::string{context} + " direct Event Value "
                    + std::string{stage}
                    + " should render without allocation");
            const auto connectedRendered = stereo
                ? renderStereoAndCount(
                    connectedSession,
                    connectedLeft,
                    connectedRight,
                    allocations)
                : renderAndCount(
                    connectedSession, connectedLeft, allocations);
            require(
                connectedRendered && allocations == 0,
                std::string{context} + " connected Event Value "
                    + std::string{stage}
                    + " should render without allocation");
            for (std::size_t frame = 0; frame < frames; ++frame)
            {
                requireNear(
                    directLeft[frame], connectedLeft[frame], 1.0e-12,
                    std::string{context}
                        + " direct/connected Event Value left parity "
                        + std::string{stage});
                if (stereo)
                {
                    requireNear(
                        directRight[frame], connectedRight[frame], 1.0e-12,
                        std::string{context}
                            + " direct/connected Event Value right parity "
                            + std::string{stage});
                }
            }
        };

        renderEqual(3, "initial block");
        require(
            directSession.updateEventValue(
                "DirectControl", updatedValue, directDomain)
                && connectedSession.updateEventValue(
                    "ConnectedControl",
                    updatedValue,
                    talas::expr::ValueDomain::Scalar),
            std::string{context}
                + " should accept equivalent direct and connected Event Value updates");
        renderEqual(4, "updated block");
        // A direct value past its range saturates (owner, 2026-10-12), so
        // one refused at schedule is one that is not a number.
        const auto directAccepted = directSession.updateEventValue(
            "DirectControl",
            directRejectsAtSchedule ? std::numeric_limits<double>::quiet_NaN() : rejectedValue,
            directDomain);
        if (directRejectsAtSchedule)
        {
            require(
                !directAccepted,
                std::string{context}
                    + " should reject an invalid direct Event Value transaction");
        }
        else
        {
            require(
                directAccepted,
                std::string{context}
                    + " cross-parameter direct control should schedule before consumer validation");
            std::vector<double> rejectedLeft(2);
            std::vector<double> rejectedRight(2);
            std::size_t allocations = 0;
            const auto rendered = stereo
                ? renderStereoAndCount(
                    directSession,
                    rejectedLeft,
                    rejectedRight,
                    allocations)
                : renderAndCount(
                    directSession, rejectedLeft, allocations);
            require(
                !rendered && allocations == 0,
                std::string{context}
                    + " should reject the invalid direct control in the callback without allocation");
        }
        const auto connectedAccepted = connectedSession.updateEventValue(
            "ConnectedControl",
            rejectedValue,
            talas::expr::ValueDomain::Scalar);
        if (connectedRejectsAtSchedule)
        {
            require(
                !connectedAccepted,
                std::string{context}
                    + " should reject a non-finite connected Event Value transaction");
        }
        else
        {
            require(
                connectedAccepted,
                std::string{context}
                    + " finite connected control should schedule before consumer validation");
            std::vector<double> rejectedLeft(2);
            std::vector<double> rejectedRight(2);
            std::size_t allocations = 0;
            const auto rendered = stereo
                ? renderStereoAndCount(
                    connectedSession,
                    rejectedLeft,
                    rejectedRight,
                    allocations)
                : renderAndCount(
                    connectedSession, rejectedLeft, allocations);
            require(
                !rendered && allocations == 0,
                std::string{context}
                    + " should reject the invalid connected control in the callback without allocation");
        }
        directSession.resetTransport();
        connectedSession.resetTransport();
        require(
            directSession.updateEventValue(
                "DirectControl", updatedValue, directDomain)
                && connectedSession.updateEventValue(
                    "ConnectedControl",
                    updatedValue,
                    talas::expr::ValueDomain::Scalar),
            std::string{context}
                + " should accept valid controls after the rejected transaction and reset");
        renderEqual(2, "after rejected transaction");
    };

    run(
        makeRealtimeTwoFormantElementDocument({
            {"formant1", "1 hz"}, {"bandwidth1", "0.5 hz"},
            {"scale1", "0.75"}, {"formant2", "2 hz"},
            {"bandwidth2", "0.75 hz"}, {"scale2", "-0.25"},
        }),
        makeRealtimeTwoFormantElementDocument({
            {"formant1", "1 hz"}, {"bandwidth1", "0.5 hz"},
            {"scale1", "0.75"}, {"formant2", "2 hz"},
            {"bandwidth2", "0.75 hz"}, {"scale2", "-0.25"},
        }),
        talas::runtime::RenderSettings{8.0, 4},
        "formants", "formant1", talas::expr::ValueDomain::Hertz,
        1.0, 1.5, 4.0, false, true, false,
        "C17 Two Formant Element");
    run(
        makeRealtimeTwoFormantVoiceElementDocument(),
        makeRealtimeTwoFormantVoiceElementDocument(),
        talas::runtime::RenderSettings{8.0, 4},
        "voice", "frequency", talas::expr::ValueDomain::Hertz,
        1.0, 1.5, 4.0, false, true, false,
        "C17 Two Formant Voice Element");
    run(
        makeRealtimeDualParallelTwoPoleDocument(),
        makeRealtimeDualParallelTwoPoleDocument(),
        talas::runtime::RenderSettings{8.0, 4},
        "twoPole", "scale1", talas::expr::ValueDomain::Scalar,
        0.75, 0.5, std::numeric_limits<double>::infinity(), false, true, true,
        "C17 Dual Parallel Two Pole Filter");
    run(
        makeRealtimeGraphicEqDocument(),
        makeRealtimeGraphicEqDocument(),
        talas::runtime::RenderSettings{48000.0, 4},
        "eq", "cf500Hz", talas::expr::ValueDomain::Scalar,
        1.0, 0.5, -1.0, false, true, false,
        "C17 Graphic EQ");
    run(
        makeRealtimeAnalysisFilterDocument(),
        makeRealtimeAnalysisFilterDocument(),
        talas::runtime::RenderSettings{8.0, 4},
        "analysis", "harmonic", talas::expr::ValueDomain::Scalar,
        2.0, 1.5, 4.0, true, false, false,
        "C17 Analysis Filter");
}

void testAnalysisFilterRequiresExactCompilerOwnedAuthority()
{
    const auto settings = talas::runtime::RenderSettings{8.0, 4};
    const auto document = makeRealtimeAnalysisFilterDocument();
    const auto compiled = compile(document, settings);
    const auto analysis = std::ranges::find(
        compiled.plan().steps,
        std::string_view{"talas.analysisFilter"},
        &talas::runtime::CompileStep::typeId);
    require(analysis != compiled.plan().steps.end()
            && analysis->offlineSupport
                == talas::core::ExecutionSupport::Supported
            && analysis->preparedRealtimeSupport
                == talas::core::ExecutionSupport::Supported
            && analysis->supportsReset
            && analysis->resolvedLatencyFrames == 0,
        "C164 exact Analysis Filter should carry promoted offline/prepared authority");
    talas::runtime::RealtimeRenderSession exactRealtime{compiled};
    const auto exactOffline = talas::runtime::renderOffline(compiled, 4);
    require(exactRealtime.ready() && exactOffline.ok(),
        "C164 exact built-in Analysis Filter authority should render offline and prepare realtime");

    const auto requireRejected = [](auto graph,
                                    std::string_view context) {
        talas::runtime::RealtimeRenderSession realtime{graph};
        const auto offline = talas::runtime::renderOffline(graph, 4);
        require(!realtime.ready() && !offline.ok()
                && offline.mono.empty() && offline.right.empty(),
            "C164 Analysis Filter should reject "
                + std::string{context});
    };
    requireRejected(
        makePublicCompatibilityGraphWithSubsetOscillators(compiled),
        "a public reconstruction without the compiler seal");

    const auto requirePlanMutationRejected = [&] (
        auto mutate, std::string_view context) {
        auto graph = compiled;
        auto& plan = mutablePlanForTest(graph);
        const auto step = std::ranges::find(
            plan.steps,
            std::string_view{"talas.analysisFilter"},
            &talas::runtime::CompileStep::typeId);
        require(step != plan.steps.end(),
            "C164 mutation fixture should expose Analysis Filter");
        mutate(plan, *step);
        requireRejected(std::move(graph), context);
    };
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.parameters.front().value = std::nextafter(
            step.parameters.front().value,
            std::numeric_limits<double>::infinity());
    }, "sealed parameter mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.inputs.front().sourcePortId += "Forged";
    }, "sealed input-binding mutation");
    requirePlanMutationRejected([] (auto& plan, auto& step) {
        const auto output = std::ranges::find_if(
            plan.buffers,
            [&] (const auto& buffer) {
                return buffer.nodeId == step.nodeId
                    && buffer.scopeId == step.scopeId
                    && buffer.portId == "rightOut";
            });
        require(output != plan.buffers.end(),
            "C164 mutation fixture should expose rightOut");
        ++output->frames;
    }, "sealed output-buffer mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        ++step.scopeId;
    }, "sealed scope mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.resolvedLatencyFrames = 1;
    }, "sealed latency mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.preparedRealtimeSupport =
            talas::core::ExecutionSupport::Subset;
    }, "sealed support mutation");
    auto changedSettings = compiled;
    ++mutableSettingsForTest(changedSettings).maxBlockFrames;
    requireRejected(std::move(changedSettings),
        "sealed RenderSettings mutation");
    auto changedResource = compiled;
    mutableSettingsForTest(changedResource).tableResources.push_back({
        "C164Forged", {1.0}});
    requireRejected(std::move(changedResource),
        "a forged resource in resource-free authority");
    auto changedSnapshot = compiled;
    mutableSettingsForTest(changedSnapshot).resourceSnapshots.push_back(
        std::make_shared<talas::core::ResourceSnapshot>());
    requireRejected(std::move(changedSnapshot),
        "a forged immutable snapshot in resource-free authority");

    auto subsetRegistry = talas::core::makeBuiltinNodeRegistry();
    subsetRegistry.setNodeTypeOfflineSupport(
        "talas.analysisFilter", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    subsetRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.analysisFilter", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto subset = talas::runtime::compileProject(
        document, subsetRegistry, settings);
    require(subset.ok(),
        "C164 explicit custom both-Subset Analysis Filter should compile");
    talas::runtime::RealtimeRenderSession subsetRealtime{*subset.graph};
    const auto subsetOffline = talas::runtime::renderOffline(
        *subset.graph, 4);
    const auto publicSubset =
        makePublicCompatibilityGraphWithSubsetOscillators(*subset.graph);
    talas::runtime::RealtimeRenderSession publicSubsetRealtime{publicSubset};
    const auto publicSubsetOffline = talas::runtime::renderOffline(
        publicSubset, 4);
    require(subsetRealtime.ready() && subsetOffline.ok()
            && publicSubsetRealtime.ready()
            && publicSubsetOffline.ok(),
        "C164 coherent custom both-Subset Analysis Filter should retain legacy compatibility");

    auto mixedRegistry = talas::core::makeBuiltinNodeRegistry();
    mixedRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.analysisFilter", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto mixed = talas::runtime::compileProject(
        document, mixedRegistry, settings);
    require(mixed.ok(),
        "C164 mixed-support descriptor fixture should compile before authority rejection");
    requireRejected(*mixed.graph,
        "mixed offline/prepared descriptor support");

    auto divergentRegistry = talas::core::makeBuiltinNodeRegistry();
    divergentRegistry.setNodeTypeFanInLatencyPolicy(
        "talas.analysisFilter",
        talas::core::FanInLatencyPolicy::PreserveRelative);
    const auto divergent = talas::runtime::compileProject(
        document, divergentRegistry, settings);
    require(divergent.ok(),
        "C164 divergent descriptor fixture should compile before authority rejection");
    requireRejected(*divergent.graph,
        "a divergent Supported descriptor");

    auto combined = document;
    combined.graph.nodes.push_back(node(
        "contextual", "talas.analysisFilter", {
            {"fundamental", "0.5 hz + 0.5 hz"},
            {"harmonic", "2"},
        }));
    std::erase_if(combined.graph.connections, [](const auto& edge) {
        return edge.fromNode == "analysis" && edge.toNode == "out";
    });
    combined.graph.connections.push_back(connection(
        "analysis", "leftOut", "contextual", "audioIn"));
    combined.graph.connections.push_back(connection(
        "contextual", "leftOut", "out", "audioIn"));
    combined.graph.connections.push_back(connection(
        "contextual", "rightOut", "out", "rightIn"));
    const auto combinedGraph = compile(combined, settings);
    std::size_t promotedCount = 0;
    std::size_t subsetCount = 0;
    for (const auto& step : combinedGraph.plan().steps)
    {
        if (step.typeId != "talas.analysisFilter")
            continue;
        if (step.offlineSupport
                == talas::core::ExecutionSupport::Supported
            && step.preparedRealtimeSupport
                == talas::core::ExecutionSupport::Supported)
        {
            ++promotedCount;
        }
        else if (step.offlineSupport
                    == talas::core::ExecutionSupport::Subset
                 && step.preparedRealtimeSupport
                    == talas::core::ExecutionSupport::Subset)
        {
            ++subsetCount;
        }
    }
    talas::runtime::RealtimeRenderSession combinedRealtime{combinedGraph};
    const auto combinedOffline = talas::runtime::renderOffline(
        combinedGraph, 4);
    require(promotedCount == 1 && subsetCount == 1
            && combinedRealtime.ready() && combinedOffline.ok(),
        "C164 exact and compiler-demoted Analysis Filter instances should coexist without overclaiming authority");
}

void testPhaseShiftBy90RequiresExactCompilerOwnedAuthority()
{
    const auto settings = talas::runtime::RenderSettings{4.0, 4};
    const auto document = makePhaseShiftBy90Document();
    const auto compiled = compile(document, settings);
    const auto phase = std::ranges::find(
        compiled.plan().steps,
        std::string_view{"talas.phaseShiftBy90"},
        &talas::runtime::CompileStep::typeId);
    require(phase != compiled.plan().steps.end()
            && phase->offlineSupport
                == talas::core::ExecutionSupport::Supported
            && phase->preparedRealtimeSupport
                == talas::core::ExecutionSupport::Supported
            && phase->supportsReset
            && phase->resolvedLatencyFrames == 0,
        "C165 exact Phase Shift By 90 should carry promoted offline/prepared authority");
    talas::runtime::RealtimeRenderSession exactRealtime{compiled};
    const auto exactOffline = talas::runtime::renderOffline(compiled, 4);
    require(exactRealtime.ready() && exactOffline.ok(),
        "C165 exact built-in Phase Shift By 90 authority should render offline and prepare realtime");

    const auto requireRejected = [](auto graph,
                                    std::string_view context) {
        talas::runtime::RealtimeRenderSession realtime{graph};
        const auto offline = talas::runtime::renderOffline(graph, 4);
        require(!realtime.ready() && !offline.ok()
                && offline.mono.empty(),
            "C165 Phase Shift By 90 should reject "
                + std::string{context});
    };
    requireRejected(
        makePublicCompatibilityGraphWithSubsetOscillators(compiled),
        "a public reconstruction without the compiler seal");

    const auto requirePlanMutationRejected = [&] (
        auto mutate, std::string_view context) {
        auto graph = compiled;
        auto& plan = mutablePlanForTest(graph);
        const auto step = std::ranges::find(
            plan.steps,
            std::string_view{"talas.phaseShiftBy90"},
            &talas::runtime::CompileStep::typeId);
        require(step != plan.steps.end(),
            "C165 mutation fixture should expose Phase Shift By 90");
        mutate(plan, *step);
        requireRejected(std::move(graph), context);
    };
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.parameters.front().value = std::nextafter(
            step.parameters.front().value,
            std::numeric_limits<double>::infinity());
    }, "a sealed parameter mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.inputs.front().sourcePortId += "Forged";
    }, "a sealed input-binding mutation");
    requirePlanMutationRejected([] (auto& plan, auto& step) {
        require(step.inputs.front().bufferIndex < plan.buffers.size(),
            "C165 producer fixture should expose its source buffer");
        auto& source = plan.buffers[step.inputs.front().bufferIndex];
        require(source.nodeId == step.inputs.front().sourceNodeId
                && source.portId
                    == step.inputs.front().sourcePortId,
            "C165 producer fixture should retain exact source metadata");
        source.nodeId += "Forged";
    }, "a sealed producer source-buffer mutation");
    requirePlanMutationRejected([] (auto& plan, auto& step) {
        const auto output = std::ranges::find_if(
            plan.buffers,
            [&] (const auto& buffer) {
                return buffer.nodeId == step.nodeId
                    && buffer.scopeId == step.scopeId
                    && buffer.portId == "audioOut";
            });
        require(output != plan.buffers.end(),
            "C165 mutation fixture should expose audioOut");
        ++output->frames;
    }, "a sealed output-buffer mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        ++step.scopeId;
    }, "a sealed scope mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.resolvedLatencyFrames = 1;
    }, "a sealed latency mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.preparedRealtimeSupport =
            talas::core::ExecutionSupport::Subset;
    }, "a sealed support mutation");

    auto changedSettings = compiled;
    ++mutableSettingsForTest(changedSettings).maxBlockFrames;
    requireRejected(std::move(changedSettings),
        "a sealed RenderSettings mutation");
    auto changedResource = compiled;
    mutableSettingsForTest(changedResource).tableResources.push_back({
        "C165Forged", {1.0}});
    requireRejected(std::move(changedResource),
        "a forged resource in resource-free authority");
    auto changedSnapshot = compiled;
    mutableSettingsForTest(changedSnapshot).resourceSnapshots.push_back(
        std::make_shared<talas::core::ResourceSnapshot>());
    requireRejected(std::move(changedSnapshot),
        "a forged immutable snapshot in resource-free authority");

    auto subsetRegistry = talas::core::makeBuiltinNodeRegistry();
    subsetRegistry.setNodeTypeOfflineSupport(
        "talas.phaseShiftBy90", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    subsetRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.phaseShiftBy90", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto subset = talas::runtime::compileProject(
        document, subsetRegistry, settings);
    require(subset.ok(),
        "C165 explicit custom both-Subset Phase Shift By 90 should compile");
    talas::runtime::RealtimeRenderSession subsetRealtime{*subset.graph};
    const auto subsetOffline = talas::runtime::renderOffline(
        *subset.graph, 4);
    const auto publicSubset =
        makePublicCompatibilityGraphWithSubsetOscillators(*subset.graph);
    talas::runtime::RealtimeRenderSession publicSubsetRealtime{publicSubset};
    const auto publicSubsetOffline = talas::runtime::renderOffline(
        publicSubset, 4);
    require(subsetRealtime.ready() && subsetOffline.ok()
            && publicSubsetRealtime.ready()
            && publicSubsetOffline.ok(),
        "C165 coherent custom both-Subset Phase Shift By 90 should retain legacy compatibility");

    auto mixedRegistry = talas::core::makeBuiltinNodeRegistry();
    mixedRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.phaseShiftBy90", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto mixed = talas::runtime::compileProject(
        document, mixedRegistry, settings);
    require(mixed.ok(),
        "C165 mixed-support descriptor fixture should compile before authority rejection");
    requireRejected(*mixed.graph,
        "mixed offline/prepared descriptor support");

    auto divergentRegistry = talas::core::makeBuiltinNodeRegistry();
    divergentRegistry.setNodeTypeFanInLatencyPolicy(
        "talas.phaseShiftBy90",
        talas::core::FanInLatencyPolicy::PreserveRelative);
    const auto divergent = talas::runtime::compileProject(
        document, divergentRegistry, settings);
    require(divergent.ok(),
        "C165 divergent descriptor fixture should compile before authority rejection");
    requireRejected(*divergent.graph,
        "a divergent Supported descriptor");

    auto combined = document;
    combined.graph.nodes.push_back(node(
        "contextual", "talas.phaseShiftBy90", {
            {"frequency", "0.5 hz + 0.5 hz"},
            choiceParameter("overflow", "unclipped"),
        }));
    std::erase_if(combined.graph.connections, [](const auto& edge) {
        return edge.fromNode == "phase" && edge.toNode == "out";
    });
    combined.graph.connections.push_back(connection(
        "phase", "audioOut", "contextual", "audioIn"));
    combined.graph.connections.push_back(connection(
        "contextual", "audioOut", "out", "audioIn"));
    const auto combinedGraph = compile(combined, settings);
    std::size_t promotedCount = 0;
    std::size_t subsetCount = 0;
    for (const auto& step : combinedGraph.plan().steps)
    {
        if (step.typeId != "talas.phaseShiftBy90")
            continue;
        if (step.offlineSupport
                == talas::core::ExecutionSupport::Supported
            && step.preparedRealtimeSupport
                == talas::core::ExecutionSupport::Supported)
        {
            ++promotedCount;
        }
        else if (step.offlineSupport
                    == talas::core::ExecutionSupport::Subset
                 && step.preparedRealtimeSupport
                    == talas::core::ExecutionSupport::Subset)
        {
            ++subsetCount;
        }
    }
    talas::runtime::RealtimeRenderSession combinedRealtime{combinedGraph};
    const auto combinedOffline = talas::runtime::renderOffline(
        combinedGraph, 4);
    require(promotedCount == 1 && subsetCount == 1
            && combinedRealtime.ready() && combinedOffline.ok(),
        "C165 exact and compiler-demoted Phase Shift By 90 instances should coexist without overclaiming authority");
}

