void testAnalysisFilterScheduledControlsMatchOfflinePreparedAndLifecycle()
{
    const auto document = makeRealtimeAnalysisFilterDocument();
    auto scheduledDocument = document;
    const auto analysis = std::ranges::find(
        scheduledDocument.graph.nodes,
        std::string_view{"analysis"},
        &talas::project::ProjectNode::instanceId);
    require(analysis != scheduledDocument.graph.nodes.end(),
        "C164 scheduled fixture should expose Analysis Filter");
    analysis->parameters = {
        {"fundamental", "!C164Fundamental"},
        {"harmonic", "!C164Harmonic"},
    };
    auto preparedSettings = talas::runtime::RenderSettings{8.0, 8};
    preparedSettings.maxRealtimeEventTransactions = 8;
    preparedSettings.eventValues = {
        {"C164Fundamental", 0.5, talas::expr::ValueDomain::Hertz},
        {"C164Harmonic", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto offlineSettings = preparedSettings;
    offlineSettings.eventValueChanges = {
        {2, "C164Fundamental", 0.25, talas::expr::ValueDomain::Hertz},
        {2, "C164Harmonic", 1.5, talas::expr::ValueDomain::Scalar},
        {4, "C164Fundamental", 0.5, talas::expr::ValueDomain::Hertz},
        {4, "C164Harmonic", 1.5, talas::expr::ValueDomain::Scalar},
        {6, "C164Fundamental", 0.25, talas::expr::ValueDomain::Hertz},
        {6, "C164Harmonic", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto offlineGraph = compile(
        scheduledDocument, offlineSettings);
    const auto preparedGraph = compile(
        scheduledDocument, preparedSettings);
    const auto offline = talas::runtime::renderOffline(offlineGraph, 8);
    talas::runtime::RealtimeRenderSession prepared{preparedGraph};
    require(offline.ok() && prepared.ready(),
        "C164 paired direct-control schedule should render offline and prepare realtime");
    const auto schedule = [](auto& session) {
        const std::array frame2{
            talas::runtime::RealtimeEventValueUpdate{
                "C164Fundamental", 0.25,
                talas::expr::ValueDomain::Hertz},
            talas::runtime::RealtimeEventValueUpdate{
                "C164Harmonic", 1.5,
                talas::expr::ValueDomain::Scalar},
        };
        const std::array frame4{
            talas::runtime::RealtimeEventValueUpdate{
                "C164Fundamental", 0.5,
                talas::expr::ValueDomain::Hertz},
            talas::runtime::RealtimeEventValueUpdate{
                "C164Harmonic", 1.5,
                talas::expr::ValueDomain::Scalar},
        };
        const std::array frame6{
            talas::runtime::RealtimeEventValueUpdate{
                "C164Fundamental", 0.25,
                talas::expr::ValueDomain::Hertz},
            talas::runtime::RealtimeEventValueUpdate{
                "C164Harmonic", 1.0,
                talas::expr::ValueDomain::Scalar},
        };
        return session.scheduleEventValues(frame2, 2)
            && session.scheduleEventValues(frame4, 4)
            && session.scheduleEventValues(frame6, 6);
    };
    std::array<double, 8> left{};
    std::array<double, 8> right{};
    std::size_t allocations = 0;
    const auto emptyRendered =
        renderEmptyStereoAndCount(prepared, allocations);
    require(emptyRendered,
        "C164 zero-frame callback should succeed before scheduled rendering: "
            + std::string{prepared.error()});
    require(allocations == 0,
        "C164 zero-frame callback should not allocate before scheduled rendering; allocations="
            + std::to_string(allocations));
    require(schedule(prepared),
        "C164 same-frame fundamental/harmonic batches should stage atomically");
    require(renderStereoAndCount(
                prepared,
                std::span<double>{left}.subspan(0, 1),
                std::span<double>{right}.subspan(0, 1),
                allocations)
            && allocations == 0,
        "C164 first irregular prepared partition should render without allocation");
    require(renderStereoAndCount(
                prepared,
                std::span<double>{left}.subspan(1, 2),
                std::span<double>{right}.subspan(1, 2),
                allocations)
            && allocations == 0,
        "C164 second irregular prepared partition should render without allocation");
    require(renderStereoAndCount(
                prepared,
                std::span<double>{left}.subspan(3, 5),
                std::span<double>{right}.subspan(3, 5),
                allocations)
            && allocations == 0,
        "C164 final irregular prepared partition should render without allocation");
    for (std::size_t frame = 0; frame < left.size(); ++frame)
    {
        requireNear(left[frame], offline.mono[frame], 1.0e-12,
            "C164 scheduled prepared/offline left parity frame "
                + std::to_string(frame));
        requireNear(right[frame], offline.right[frame], 1.0e-12,
            "C164 scheduled prepared/offline right parity frame "
                + std::to_string(frame));
    }

    prepared.resetTransport();
    talas::runtime::RealtimeRenderSession replacement{preparedGraph};
    std::array<double, 8> resetLeft{};
    std::array<double, 8> resetRight{};
    std::array<double, 8> freshLeft{};
    std::array<double, 8> freshRight{};
    require(replacement.ready()
            && renderEmptyStereoAndCount(prepared, allocations)
            && allocations == 0
            && renderStereoAndCount(
                prepared, resetLeft, resetRight, allocations)
            && allocations == 0
            && renderStereoAndCount(
                replacement, freshLeft, freshRight, allocations)
            && allocations == 0
            && resetLeft == freshLeft && resetRight == freshRight,
        "C164 zero-frame and transport reset should reproduce a fresh stereo Analysis Filter exactly");
}

void testAnalysisFilterConnectedPrecedenceAndLateFailureRollback()
{
    auto connectedDocument = makeRealtimeAnalysisFilterDocument();
    const auto analysis = std::ranges::find(
        connectedDocument.graph.nodes,
        std::string_view{"analysis"},
        &talas::project::ProjectNode::instanceId);
    require(analysis != connectedDocument.graph.nodes.end(),
        "C164 connected-precedence fixture should expose Analysis Filter");
    analysis->parameters = {
        {"fundamental", "5000 hz"},
        {"harmonic", "1000"},
    };
    connectedDocument.graph.nodes.push_back(node(
        "fundamentalControl", "talas.constant", {{"value", "0.5"}}));
    connectedDocument.graph.nodes.push_back(node(
        "harmonicControl", "talas.constant", {{"value", "1"}}));
    connectedDocument.graph.connections.push_back(connection(
        "fundamentalControl", "value", "analysis", "fundamental"));
    connectedDocument.graph.connections.push_back(connection(
        "harmonicControl", "value", "analysis", "harmonic"));
    const auto connectedGraph = compile(
        connectedDocument, talas::runtime::RenderSettings{8.0, 4});
    const auto connectedStep = std::ranges::find(
        connectedGraph.plan().steps,
        std::string_view{"talas.analysisFilter"},
        &talas::runtime::CompileStep::typeId);
    talas::runtime::RealtimeRenderSession connectedRealtime{connectedGraph};
    const auto connectedOffline = talas::runtime::renderOffline(
        connectedGraph, 4);
    std::array<double, 4> connectedLeft{};
    std::array<double, 4> connectedRight{};
    std::size_t allocations = 0;
    require(connectedStep != connectedGraph.plan().steps.end(),
        "C164 connected-precedence fixture should compile Analysis Filter");
    require(connectedStep->offlineSupport
                == talas::core::ExecutionSupport::Supported
            && connectedStep->preparedRealtimeSupport
                == talas::core::ExecutionSupport::Supported,
        "C164 connected controls should retain promoted Analysis Filter support");
    require(connectedRealtime.ready(),
        "C164 connected controls should prepare despite invalid hidden fallbacks: "
            + std::string{connectedRealtime.error()});
    require(connectedOffline.ok(),
        "C164 connected controls should render offline despite invalid hidden fallbacks"
            + (connectedOffline.diagnostics.empty()
                ? std::string{}
                : ": " + connectedOffline.diagnostics.front().message));
    require(renderStereoAndCount(
                connectedRealtime, connectedLeft, connectedRight,
                allocations),
        "C164 connected controls should render prepared despite invalid hidden fallbacks");
    require(allocations == 0,
        "C164 connected-control callback should not allocate");
    require(std::ranges::equal(connectedLeft, connectedOffline.mono)
            && std::ranges::equal(connectedRight, connectedOffline.right),
        "C164 connected controls should match offline on both quadrature channels");

    auto contextualDocument = connectedDocument;
    const auto contextualAnalysis = std::ranges::find(
        contextualDocument.graph.nodes,
        std::string_view{"analysis"},
        &talas::project::ProjectNode::instanceId);
    require(contextualAnalysis != contextualDocument.graph.nodes.end(),
        "C164 contextual connected fixture should expose Analysis Filter");
    contextualAnalysis->parameters = {
        {"fundamental", "1e200 * 1e200"},
        {"harmonic", "1"},
    };
    const auto contextual = talas::runtime::compileProject(
        contextualDocument,
        talas::core::makeBuiltinNodeRegistry(),
        talas::runtime::RenderSettings{8.0, 4});
    require(contextual.ok(),
        "C164 connected precedence should suppress one exact NonFiniteResult fallback");
    const auto contextualStep = std::ranges::find(
        contextual.graph->plan().steps,
        std::string_view{"talas.analysisFilter"},
        &talas::runtime::CompileStep::typeId);
    require(contextualStep != contextual.graph->plan().steps.end()
            && contextualStep->offlineSupport
                == talas::core::ExecutionSupport::Subset
            && contextualStep->preparedRealtimeSupport
                == talas::core::ExecutionSupport::Subset,
        "C164 suppressed compound fallback should remain contextual both-Subset rather than minting promoted authority");
    talas::runtime::RealtimeRenderSession contextualRealtime{
        *contextual.graph};
    const auto contextualOffline = talas::runtime::renderOffline(
        *contextual.graph, 4);
    require(contextualRealtime.ready() && contextualOffline.ok(),
        "C164 contextual connected NonFiniteResult fallback should remain admissible offline and prepared: "
            + std::string{contextualRealtime.error()});

    auto unresolvedDocument = connectedDocument;
    const auto unresolvedAnalysis = std::ranges::find(
        unresolvedDocument.graph.nodes,
        std::string_view{"analysis"},
        &talas::project::ProjectNode::instanceId);
    require(unresolvedAnalysis != unresolvedDocument.graph.nodes.end(),
        "C164 unresolved connected fixture should expose Analysis Filter");
    unresolvedAnalysis->parameters = {
        {"fundamental", "!C164MissingFundamental"},
        {"harmonic", "1"},
    };
    const auto unresolved = talas::runtime::compileProject(
        unresolvedDocument,
        talas::core::makeBuiltinNodeRegistry(),
        talas::runtime::RenderSettings{8.0, 4});
    require(!unresolved.ok(),
        "C164 connected precedence must not hide unresolved fallback authority");

    auto rollbackDocument = makeRealtimeAnalysisFilterDocument();
    const auto rollbackAnalysis = std::ranges::find(
        rollbackDocument.graph.nodes,
        std::string_view{"analysis"},
        &talas::project::ProjectNode::instanceId);
    require(rollbackAnalysis != rollbackDocument.graph.nodes.end(),
        "C164 rollback fixture should expose Analysis Filter");
    rollbackAnalysis->parameters = {
        {"fundamental", "!C164RollbackFundamental"},
        {"harmonic", "!C164RollbackHarmonic"},
    };
    std::erase_if(rollbackDocument.graph.connections, [](const auto& edge) {
        return edge.fromNode == "analysis" && edge.toNode == "out";
    });
    rollbackDocument.graph.nodes.push_back(node(
        "downstreamLeft", "talas.level", {
            {"left", "!C164RollbackGain"},
            {"right", "0"},
            booleanParameter("noGain", false),
        }));
    rollbackDocument.graph.nodes.push_back(node(
        "downstreamRight", "talas.level", {
            {"left", "!C164RollbackGain"},
            {"right", "0"},
            booleanParameter("noGain", false),
        }));
    rollbackDocument.graph.nodes.push_back(node(
        "outputScaleLeft", "talas.level", {
            {"left", "100"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    rollbackDocument.graph.nodes.push_back(node(
        "outputScaleRight", "talas.level", {
            {"left", "100"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    rollbackDocument.graph.connections.push_back(connection(
        "analysis", "leftOut", "downstreamLeft", "audioIn"));
    rollbackDocument.graph.connections.push_back(connection(
        "analysis", "rightOut", "downstreamRight", "audioIn"));
    rollbackDocument.graph.connections.push_back(connection(
        "downstreamLeft", "leftOut", "outputScaleLeft", "audioIn"));
    rollbackDocument.graph.connections.push_back(connection(
        "downstreamRight", "leftOut", "outputScaleRight", "audioIn"));
    rollbackDocument.graph.connections.push_back(connection(
        "outputScaleLeft", "leftOut", "out", "audioIn"));
    rollbackDocument.graph.connections.push_back(connection(
        "outputScaleRight", "leftOut", "out", "rightIn"));
    auto settings = talas::runtime::RenderSettings{8.0, 2};
    settings.maxRealtimeEventTransactions = 4;
    settings.eventValues = {
        {"C164RollbackFundamental", 0.5,
            talas::expr::ValueDomain::Hertz},
        {"C164RollbackHarmonic", 1.0,
            talas::expr::ValueDomain::Scalar},
        {"C164RollbackGain", 1.0,
            talas::expr::ValueDomain::Scalar},
    };
    const auto rollbackGraph = compile(rollbackDocument, settings);
    talas::runtime::RealtimeRenderSession candidate{rollbackGraph};
    talas::runtime::RealtimeRenderSession reference{rollbackGraph};
    const std::array paired{
        talas::runtime::RealtimeEventValueUpdate{
            "C164RollbackFundamental", 0.25,
            talas::expr::ValueDomain::Hertz},
        talas::runtime::RealtimeEventValueUpdate{
            "C164RollbackHarmonic", 1.5,
            talas::expr::ValueDomain::Scalar},
    };
    require(candidate.ready() && reference.ready()
            && candidate.scheduleEventValues(paired, 1)
            && reference.scheduleEventValues(paired, 1)
            && candidate.scheduleEventValue(
                "C164RollbackGain",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar, 1),
        "C164 rollback fixture should stage paired Analysis Filter controls and a later downstream failure");
    const auto checkpoint =
        talas::runtime::RealtimeRenderSessionTestAccess::
            callbackTimelineState(candidate);
    std::array<double, 2> rejectedLeft{};
    std::array<double, 2> rejectedRight{};
    for (auto attempt = 0; attempt < 2; ++attempt)
    {
        rejectedLeft.fill(164.0);
        rejectedRight.fill(164.0);
        require(!renderStereoAndCount(
                    candidate, rejectedLeft, rejectedRight,
                    allocations)
                && allocations == 0
                && rejectedLeft == std::array<double, 2>{}
                && rejectedRight == std::array<double, 2>{}
                && talas::runtime::RealtimeRenderSessionTestAccess::
                        callbackTimelineState(candidate)
                    == checkpoint,
            "C164 repeated late failure should publish no stereo prefix and restore the callback cursor");
    }
    std::array<double, 2> actualLeft{};
    std::array<double, 2> actualRight{};
    std::array<double, 2> expectedLeft{};
    std::array<double, 2> expectedRight{};
    require(candidate.updateEventValue(
                "C164RollbackGain", 1.0,
                talas::expr::ValueDomain::Scalar)
            && renderStereoAndCount(
                candidate, actualLeft, actualRight, allocations)
            && allocations == 0
            && renderStereoAndCount(
                reference, expectedLeft, expectedRight, allocations)
            && allocations == 0
            && actualLeft == expectedLeft
            && actualRight == expectedRight,
        "C164 repaired retry should restore both allpass histories and paired schedules exactly");
}

void testRealtimeGraphicEqValidatesInactiveConnectedBands()
{
    auto document = makeRealtimeGraphicEqDocument();
    document.graph.nodes.push_back(node(
        "inactiveLevel", "talas.constant", {
            {"value", "!InactiveLevel"},
        }));
    document.graph.connections.push_back(connection(
        "inactiveLevel", "value", "eq", "cf500Hz"));

    talas::runtime::RenderSettings settings{800.0, 4};
    settings.eventValues.push_back({
        "InactiveLevel", -1.0, talas::expr::ValueDomain::Scalar});
    auto graph = compile(document, settings);
    const auto offline = talas::runtime::renderOffline(graph, 4);
    require(
        !offline.ok(),
        "offline Graphic EQ should reject an invalid connected level for an inactive band");

    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        "realtime Graphic EQ inactive-band validation fixture should prepare: "
            + std::string{session.error()});
    std::array<double, 4> output{1.0, 1.0, 1.0, 1.0};
    std::size_t allocations = 0;
    require(
        !renderAndCount(session, output, allocations)
            && allocations == 0
            && output == std::array<double, 4>{},
        "realtime Graphic EQ must reject an invalid connected level even when its band is at or above Nyquist");
}

void testRealtimeCheckedBiquadFamilyDistinguishesTransactionalPredecessors()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "formants", "talas.twoFormantElement", {
            {"formant1", "500 hz"},
            {"bandwidth1", "100 hz"},
            {"scale1", "0.75"},
            {"formant2", "1000 hz"},
            {"bandwidth2", "150 hz"},
            {"scale2", "-0.25"},
        }));
    document.graph.nodes.push_back(node(
        "pitch", "talas.simplePitchShifter", {
            {"interval", "12"},
            {"minInputPitch", "20 hz"},
            {"maxInputPitch", "2000 hz"},
        }));
    document.graph.nodes.push_back(node(
        "oscillator", "talas.oscillator", {
            {"frequency", "220 hz"}, {"amplitude", "0.75"},
        }));
    document.graph.connections.push_back(connection(
        "oscillator", "audioOut", "pitch", "audioIn"));
    document.graph.connections.push_back(connection(
        "pitch", "audioOut", "formants", "audioIn"));
    document.graph.connections.push_back(connection(
        "formants", "audioOut", "out", "audioIn"));

    auto graph = compile(
        document, talas::runtime::RenderSettings{48000.0, 257});
    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        "C142 preparation should accept a Simple Pitch Shifter predecessor with a dedicated callback checkpoint: "
            + std::string{session.error()});

    talas::project::ProjectDocument delayDocument;
    delayDocument.graph.nodes.push_back(node("out", "talas.audioOutput"));
    delayDocument.graph.nodes.push_back(node(
        "formants", "talas.twoFormantElement", {
            {"formant1", "500 hz"},
            {"bandwidth1", "100 hz"},
            {"scale1", "0.75"},
            {"formant2", "1000 hz"},
            {"bandwidth2", "150 hz"},
            {"scale2", "-0.25"},
        }));
    delayDocument.graph.nodes.push_back(node(
        "delay", "talas.delayWithFeedback", {
            {"delay", "250 ms"},
            {"feedback", "0.25"},
            {"mix", "1"},
        }));
    delayDocument.graph.nodes.push_back(node(
        "oscillator", "talas.oscillator", {
            {"frequency", "220 hz"}, {"amplitude", "0.75"},
        }));
    delayDocument.graph.connections.push_back(connection(
        "oscillator", "audioOut", "delay", "audioIn"));
    delayDocument.graph.connections.push_back(connection(
        "delay", "audioOut", "formants", "audioIn"));
    delayDocument.graph.connections.push_back(connection(
        "formants", "audioOut", "out", "audioIn"));

    delayDocument.graph.nodes.push_back(node("formantControl", "talas.constant", {{"value", "!C17DelayFormant"}}));
    delayDocument.graph.connections.push_back(connection("formantControl", "value", "formants", "formant1"));
    talas::runtime::RenderSettings delaySettings{48000.0, 257};
    delaySettings.eventValues = {{"C17DelayFormant", 500.0, talas::expr::ValueDomain::Scalar}};
    auto delayGraph = compile(delayDocument, delaySettings);
    talas::runtime::RealtimeRenderSession delaySession(delayGraph);
    require(delaySession.ready(), "C17 must admit its now-checkpointed mutable delay predecessor");
    const auto expectedDelay = talas::runtime::renderOffline(delayGraph, 49 * 257);
    require(expectedDelay.ok(), "C17 delayed biquad offline reference must render beyond the delay length");
    std::array<double, 257> delayed{};
    std::size_t allocations = 0;
    bool audibleDelay = false;
    for (std::size_t block = 0; block < 49; ++block)
    {
        if (block == 48)
        {
            for (int attempt = 0; attempt < 2; ++attempt)
            {
                require(delaySession.scheduleEventValue("C17DelayFormant", 24000.0, talas::expr::ValueDomain::Scalar, 17),
                    "C17 delay predecessor fixture must schedule a late invalid formant");
                allocations = 0;
                require(!renderAndCount(delaySession, delayed, allocations) && allocations == 0
                        && delayed == std::array<double, 257>{},
                    "C17 late biquad failure must silence output after the delay has advanced");
                require(delaySession.updateEventValue("C17DelayFormant", 500.0, talas::expr::ValueDomain::Scalar),
                    "C17 delayed biquad must accept corrected live formant authority");
            }
        }
        allocations = 0;
        require(renderAndCount(delaySession, delayed, allocations) && allocations == 0,
            "C17 checkpointed delay predecessor must continue without allocation");
        for (std::size_t frame = 0; frame < delayed.size(); ++frame)
        {
            requireNear(delayed[frame], expectedDelay.mono[block * delayed.size() + frame], 1e-12,
                "C17 delay/biquad histories must survive repeated late failure and corrected retry");
            audibleDelay |= std::abs(delayed[frame]) > 1e-8;
        }
    }
    require(audibleDelay, "C17 delay predecessor must exercise an audible filled history");
    delaySession.resetTransport();
    allocations = 0;
    require(renderAndCount(delaySession, delayed, allocations) && allocations == 0
            && delayed == std::array<double, 257>{},
        "C17 transport reset must clear the delay and biquad histories");

    auto frequencyPredecessorDocument = delayDocument;
    *std::ranges::find(frequencyPredecessorDocument.graph.nodes, std::string_view{"delay"},
        &talas::project::ProjectNode::instanceId) = node("delay", "talas.frequencyScale", {
            {"frequencyScale", "1"}, {"maxScale", "1"}, resourceParameter("window", "Private"), {"delay", "0.25"},
        });
    frequencyPredecessorDocument.graph.nodes.push_back(node("tracker", "talas.constant", {{"value", "440"}}));
    frequencyPredecessorDocument.graph.connections.push_back(connection("tracker", "value", "delay", "freqTracker"));
    talas::runtime::RealtimeRenderSession frequencyPredecessorSession(compile(frequencyPredecessorDocument, delaySettings));
    require(frequencyPredecessorSession.ready(),
        "C17 must admit a Frequency Scale predecessor with a general checkpoint");

}

