void testRealtimeMixingNodesApplyDirectEventValueUpdates()
{
    std::array<float, 1> input1{1.0F};
    std::array<float, 1> input2{2.0F};
    std::array<const float*, 2> channels{input1.data(), input2.data()};

    const auto run = [&](const talas::project::ProjectDocument& document,
                         double expectedInitialLeft,
                         double expectedInitialRight,
                         double expectedUpdatedLeft,
                         double expectedUpdatedRight,
                         std::string_view context) {
        talas::runtime::RenderSettings settings{8.0, 1};
        settings.eventValues.push_back({
            "MixControl", 0.0, talas::expr::ValueDomain::Scalar});
        auto graph = compile(document, settings);
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(), std::string(session.error()));
        std::array<double, 1> left{};
        std::array<double, 1> right{};
        std::size_t allocations = 0;
        require(
            renderStereoInputAndCount(
                session,
                {channels.data(), channels.size()},
                left,
                right,
                allocations),
            std::string(context) + " initial Event Value block should render");
        require(allocations == 0, std::string(context) + " should not allocate");
        requireNear(left[0], expectedInitialLeft, 1.0e-12,
                    std::string(context) + " initial left");
        requireNear(right[0], expectedInitialRight, 1.0e-12,
                    std::string(context) + " initial right");
        require(
            session.updateEventValue(
                "MixControl", 1.0, talas::expr::ValueDomain::Scalar),
            std::string(context) + " Event Value update should be accepted");
        require(
            renderStereoInputAndCount(
                session,
                {channels.data(), channels.size()},
                left,
                right,
                allocations),
            std::string(context) + " updated Event Value block should render");
        require(allocations == 0, std::string(context) + " update should not allocate");
        requireNear(left[0], expectedUpdatedLeft, 1.0e-12,
                    std::string(context) + " updated left");
        requireNear(right[0], expectedUpdatedRight, 1.0e-12,
                    std::string(context) + " updated right");
    };

    run(
        makeRealtimePanDocument(
            {{"pan", "!MixControl"}, {"scale", "1"},
             choiceParameter("type", "linear")}),
        1.0, 0.0, 0.0, 1.0, "prepared Pan");
    run(
        makeRealtimeCrossfadeDocument(
            {{"pan", "0"}, {"scale", "1"},
             {"fade", "!MixControl"},
             choiceParameter("type", "linear")}),
        1.0, 0.0, 2.0, 0.0, "prepared Crossfade");
    run(
        makeRealtimeStereoMix2Document(
            {{"left", "1"}, {"right", "1"},
             {"pan1", "!MixControl"}, {"scale1", "1"},
             {"pan2", "1"}, {"scale2", "0"}}),
        1.0, 0.0, 0.0, 1.0, "prepared Stereo Mix 2");

    std::array<float, 1> input3{4.0F};
    std::array<float, 1> input4{8.0F};
    std::array<const float*, 4> fourChannels{
        input1.data(), input2.data(), input3.data(), input4.data()};
    talas::runtime::RenderSettings settings{8.0, 1};
    settings.eventValues.push_back({
        "MixControl", 0.0, talas::expr::ValueDomain::Scalar});
    auto graph = compile(
        makeRealtimeStereoMix4Document({
            {"left", "1"}, {"right", "1"},
            {"pan1", "0"}, {"scale1", "0"},
            {"pan2", "0"}, {"scale2", "0"},
            {"pan3", "!MixControl"}, {"scale3", "1"},
            {"pan4", "1"}, {"scale4", "0"},
        }),
        std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    std::array<double, 1> left{};
    std::array<double, 1> right{};
    std::size_t allocations = 0;
    require(renderStereoInputAndCount(
                session,
                {fourChannels.data(), fourChannels.size()},
                left,
                right,
                allocations),
            "prepared Stereo Mix 4 initial Event Value block should render");
    requireNear(left[0], 4.0, 1.0e-12,
                "prepared Stereo Mix 4 initial pan should be left");
    requireNear(right[0], 0.0, 1.0e-12,
                "prepared Stereo Mix 4 initial right should be silent");
    require(session.updateEventValue(
                "MixControl", 1.0, talas::expr::ValueDomain::Scalar),
            "prepared Stereo Mix 4 Event Value update should be accepted");
    require(renderStereoInputAndCount(
                session,
                {fourChannels.data(), fourChannels.size()},
                left,
                right,
                allocations),
            "prepared Stereo Mix 4 updated Event Value block should render");
    requireNear(left[0], 0.0, 1.0e-12,
                "prepared Stereo Mix 4 updated left should be silent");
    requireNear(right[0], 4.0, 1.0e-12,
                "prepared Stereo Mix 4 updated pan should be right");
}

void connectOverflowingMixControl(
    talas::project::ProjectDocument& document,
    std::string targetNode,
    std::string targetPort)
{
    document.graph.nodes.push_back(node(
        "overflowLeft", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node(
        "overflowRight", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node("overflow", "talas.add"));
    document.graph.connections.push_back(connection(
        "overflowLeft", "value", "overflow", "left"));
    document.graph.connections.push_back(connection(
        "overflowRight", "value", "overflow", "right"));
    document.graph.connections.push_back(connection(
        "overflow", "value", std::move(targetNode), std::move(targetPort)));
}

void testRealtimeMixingNodesRejectInvalidConnectedControlsWithoutAllocations()
{
    auto pan = makeRealtimePanDocument(
        {{"pan", "0"}, {"scale", "1"},
         choiceParameter("type", "power")});
    connectOverflowingMixControl(pan, "pan", "pan");
    auto crossfade = makeRealtimeCrossfadeDocument(
        {{"pan", "0"}, {"scale", "1"}, {"fade", "0"},
         choiceParameter("type", "power")});
    connectOverflowingMixControl(crossfade, "crossfade", "fade");
    auto stereoMix = makeRealtimeStereoMix2Document({
        {"left", "1"}, {"right", "1"},
        {"pan1", "0"}, {"scale1", "1"},
        {"pan2", "1"}, {"scale2", "1"},
    });
    connectOverflowingMixControl(stereoMix, "mix", "left");
    auto stereoMix4 = makeRealtimeStereoMix4Document({
        {"left", "1"}, {"right", "1"},
        {"pan1", "0"}, {"scale1", "1"},
        {"pan2", "1"}, {"scale2", "1"},
        {"pan3", "0"}, {"scale3", "1"},
        {"pan4", "1"}, {"scale4", "1"},
    });
    connectOverflowingMixControl(stereoMix4, "mix", "scale4");

    for (const auto* document : {&pan, &crossfade, &stereoMix, &stereoMix4})
    {
        auto graph = compile(*document, {8.0, 1});
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(), std::string(session.error()));
        std::array<float, 1> input1{1.0F};
        std::array<float, 1> input2{2.0F};
        std::array<float, 1> input3{3.0F};
        std::array<float, 1> input4{4.0F};
        std::array<const float*, 4> channels{
            input1.data(), input2.data(), input3.data(), input4.data()};
        std::array<double, 1> left{};
        std::array<double, 1> right{};
        std::size_t allocations = 0;
        require(
            !renderStereoInputAndCount(
                session,
                {channels.data(), channels.size()},
                left,
                right,
                allocations),
            "prepared mixing node should reject a non-finite connected control");
        require(
            allocations == 0,
            "prepared mixing-node rejection should not allocate");
    }
}

void testRealtimeSessionRendersBlankLimeInterpreterAcrossBlocksWithoutAllocations()
{
    talas::runtime::RenderSettings settings{4.0, 3};
    auto graph = compile(makeLimeInterpreterDocument({
        resourceParameter("fileName", ""), textParameter("script", ""),
        {"left", "0.25"}, {"right", "-0.5"},
    }), std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 6);
    require(expected.ok(), "offline blank Lime Interpreter reference should render");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 3> leftFirst{};
    std::array<double, 3> rightFirst{};
    std::array<double, 3> leftSecond{};
    std::array<double, 3> rightSecond{};
    std::size_t allocations = 0;
    require(renderStereoAndCount(session, leftFirst, rightFirst, allocations), "first blank Lime Interpreter block should render");
    require(allocations == 0, "first blank Lime Interpreter block should not allocate");
    require(renderStereoAndCount(session, leftSecond, rightSecond, allocations), "second blank Lime Interpreter block should render");
    require(allocations == 0, "second blank Lime Interpreter block should not allocate");
    for (std::size_t frame = 0; frame < leftFirst.size(); ++frame)
    {
        requireNear(leftFirst[frame], expected.mono[frame], 1.0e-12, "first Lime Interpreter left should match offline");
        requireNear(rightFirst[frame], expected.right[frame], 1.0e-12, "first Lime Interpreter right should match offline");
        requireNear(leftSecond[frame], expected.mono[leftFirst.size() + frame], 1.0e-12, "second Lime Interpreter left should match offline");
        requireNear(rightSecond[frame], expected.right[rightFirst.size() + frame], 1.0e-12, "second Lime Interpreter right should match offline");
    }
}

