void testC61RealtimeStandaloneSumOfSinesRollsBackLateControlFailure()
{
    talas::runtime::RenderSettings settings{16.0, 4};
    settings.eventValues = {
        {"C61Frequency", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.tableResources = {
        {"Tables/Partials", {1.0}},
    };
    auto document = makeSumOfSinesDocument(sumOfSinesParameters({
        {"frequency0", "1 hz"},
        {"frequency1", "1 hz"},
        {"nbrPartials", "1"},
        {"bankSize", "1"},
        {"envelope", "1"},
    }));
    document.graph.nodes.push_back(node(
        "frequency", "talas.constant", {{"value", "!C61Frequency"}}));
    document.graph.connections.push_back(connection(
        "frequency", "value", "sum", "frequency0"));

    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession pristine(graph);
    require(candidate.ready() && pristine.ready(),
            "C61 standalone rollback fixtures should prepare");
    require(candidate.scheduleEventValue(
                "C61Frequency",
                0.0,
                talas::expr::ValueDomain::Scalar,
                2),
            "C61 standalone rollback fixture should schedule a late connected-zero failure");

    std::array<double, 4> rejected{1.0, 1.0, 1.0, 1.0};
    std::size_t allocations = 0;
    require(!renderAndCount(candidate, rejected, allocations)
                && allocations == 0
                && rejected == std::array<double, 4>{},
            "C61 standalone late failure should publish no output and allocate nothing");
    require(candidate.updateEventValue(
                "C61Frequency",
                1.0,
                talas::expr::ValueDomain::Scalar),
            "C61 standalone failed callback should accept a corrected frequency");

    std::array<double, 4> actual{};
    std::array<double, 4> expected{};
    require(renderAndCount(candidate, actual, allocations)
                && allocations == 0
                && renderAndCount(pristine, expected, allocations)
                && allocations == 0
                && actual == expected,
            "C61 standalone failed callback should roll back phase and rendered-frame state before retry");
}

