void testRealtimeSosOscillatorsMatchesWavetableAcrossPartitionsResetAndResourceGeneration()
{
    talas::runtime::RenderSettings settings{16.0, 5};
    settings.tableResources = {
        {"Tables/C102Wave", {0.0, 1.0, 0.0, -1.0}},
    };
    const auto document = makeSosOscillatorsDocument({
        {"nbrOscillators", "2"},
        {"firstOscillator", "1"},
        resourceParameter("wavetable", "Tables/C102Wave"),
    });
    auto graph = compile(document, settings);
    const auto expected = talas::runtime::renderOffline(graph, 11);
    require(expected.ok(),
        "C102 offline wavetable partition reference should render");

    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string{session.error()});
    auto& mutableSettings = const_cast<talas::runtime::RenderSettings&>(
        graph.renderSettings());
    mutableSettings.tableResources[0].samples = {
        0.5, 0.5, 0.5, 0.5};

    std::array<double, 11> actual{};
    constexpr std::array<std::size_t, 3> partitions{2, 5, 4};
    std::size_t offset = 0;
    std::size_t allocations = 0;
    for (const auto partition : partitions)
    {
        require(renderAndCount(
                    session,
                    std::span<double>{actual}.subspan(offset, partition),
                    allocations),
            "C102 irregular prepared wavetable partition should render");
        require(allocations == 0,
            "C102 prepared wavetable partition should not allocate");
        offset += partition;
    }
    for (std::size_t frame = 0; frame < actual.size(); ++frame)
    {
        requireNear(actual[frame], expected.mono[frame], 1.0e-12,
            "C102 prepared wavetable partition should match the frozen offline generation");
    }

    session.resetTransport();
    std::array<double, 5> reset{};
    require(renderAndCount(session, reset, allocations)
                && allocations == 0,
        "C102 reset wavetable callback should render without allocation");
    for (std::size_t frame = 0; frame < reset.size(); ++frame)
    {
        requireNear(reset[frame], expected.mono[frame], 1.0e-12,
            "C102 reset should replay the frozen initial wavetable phase");
    }

    talas::runtime::RealtimeRenderSession staleReplacement(graph);
    require(!staleReplacement.ready(),
        "C160 compiler-owned Oscillator authority should reject a stale graph whose unrelated Table DTO changed");
    auto replacementSettings = settings;
    replacementSettings.tableResources.front().samples = {
        0.5, 0.5, 0.5, 0.5};
    const auto replacementGraph = compile(
        document, std::move(replacementSettings));
    talas::runtime::RealtimeRenderSession replacement(replacementGraph);
    require(replacement.ready(), std::string{replacement.error()});
    std::array<double, 5> replaced{};
    require(renderAndCount(replacement, replaced, allocations)
                && allocations == 0,
        "C102 replacement wavetable generation should render without allocation");
    require(replaced != reset,
        "C102 existing session should retain its immutable wavetable generation while a recompiled replacement observes the new generation");

    auto duplicateSettings = settings;
    duplicateSettings.tableResources.push_back(
        {"Tables/C102Wave", {1.0}});
    talas::runtime::RealtimeRenderSession duplicate(
        talas::runtime::PreparedRuntimeGraph{
            graph.plan(), std::move(duplicateSettings)});
    require(!duplicate.ready(),
        "C102 should reject duplicate named wavetable generations");
}

void testRealtimeSosOscillatorsRollsBackLateDownstreamFailure()
{
    auto document = makeSosOscillatorsDocument();
    const auto cascade = std::ranges::find(
        document.graph.nodes,
        std::string_view{"cascade"},
        &talas::project::ProjectNode::instanceId);
    require(cascade != document.graph.nodes.end(),
        "C102 rollback fixture should expose its cascade oscillator");
    const auto amplitude = std::ranges::find(
        cascade->parameters,
        std::string_view{"amplitude"},
        &talas::project::ProjectParameterExpression::parameterId);
    require(amplitude != cascade->parameters.end(),
        "C102 rollback fixture should expose cascade amplitude");
    amplitude->expression = "2";
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C102Downstream"},
            {"right", "0"},
            booleanParameter("noGain", false),
        }));
    std::erase_if(document.graph.connections, [](const auto& edge) {
        return edge.fromNode == "sos" && edge.toNode == "out";
    });
    document.graph.connections.push_back(connection(
        "sos", "audioOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{16.0, 4};
    settings.eventValues = {
        {"C102Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession pristine(graph);
    require(candidate.ready() && pristine.ready(),
        "C102 downstream rollback fixtures should prepare: "
            + std::string{candidate.error()});
    std::array<double, 4> candidateSeed{};
    std::array<double, 4> pristineSeed{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, candidateSeed, allocations)
                && allocations == 0
                && renderAndCount(pristine, pristineSeed, allocations)
                && allocations == 0
                && candidateSeed == pristineSeed,
        "C102 rollback fixture should establish matching non-zero cascade and SOS phase state");
    require(candidate.updateEventValue(
                "C102Downstream",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C102 rollback fixture should arm its late downstream failure");

    std::array<double, 4> rejected{1.0, 1.0, 1.0, 1.0};
    require(!renderAndCount(candidate, rejected, allocations)
                && allocations == 0
                && rejected == std::array<double, 4>{},
        "C102 late downstream failure should publish no callback audio");
    require(candidate.updateEventValue(
                "C102Downstream",
                1.0,
                talas::expr::ValueDomain::Scalar),
        "C102 rollback fixture should repair its downstream control");

    std::array<double, 4> actual{};
    std::array<double, 4> expected{};
    require(renderAndCount(candidate, actual, allocations)
                && allocations == 0
                && renderAndCount(pristine, expected, allocations)
                && allocations == 0
                && actual == expected,
        "C102 should restore cascade and SOS phase before downstream-failure retry");
}

void testRealtimeSosOscillatorsAdmitsMaximumAndLastSelectedRange()
{
    std::string amplitudes;
    std::string frequencies;
    std::string bandwidths;
    for (std::size_t partial = 0; partial < 4096; ++partial)
    {
        if (partial != 0)
        {
            amplitudes += ' ';
            frequencies += ' ';
            bandwidths += ' ';
        }
        amplitudes += partial == 4095 ? "1" : "0";
        frequencies += "1";
        bandwidths += "0";
    }
    const auto maximumGraph = compile(
        makeSosOscillatorsDocument({
                {"nbrOscillators", "4096"},
                {"firstOscillator", "1"},
                resourceParameter("wavetable", ""),
            },
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "4096"},
                {"envelope", "1"},
                textParameter("amplitudes", amplitudes),
                textParameter("frequencies", frequencies),
                textParameter("bandwidths", bandwidths),
            })),
        {8.0, 2});
    const auto expected = talas::runtime::renderOffline(maximumGraph, 2);
    talas::runtime::RealtimeRenderSession maximum(maximumGraph);
    std::array<double, 2> actual{};
    std::size_t allocations = 0;
    require(expected.ok()
            && maximum.ready()
            && renderAndCount(maximum, actual, allocations)
            && allocations == 0
            && std::ranges::equal(actual, expected.mono),
        "C102 maximum 4096-partial selection should remain exact, bounded, and allocation-free: "
            + std::string{maximum.error()});

    const auto lastGraph = compile(
        makeSosOscillatorsDocument({
                {"nbrOscillators", "1"},
                {"firstOscillator", "4096"},
                resourceParameter("wavetable", ""),
            },
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "4096"},
                {"envelope", "1"},
                textParameter("amplitudes", std::move(amplitudes)),
                textParameter("frequencies", std::move(frequencies)),
                textParameter("bandwidths", std::move(bandwidths)),
            })),
        {8.0, 2});
    const auto lastExpected = talas::runtime::renderOffline(lastGraph, 2);
    talas::runtime::RealtimeRenderSession last(lastGraph);
    std::array<double, 2> lastActual{};
    require(lastExpected.ok()
            && last.ready()
            && renderAndCount(last, lastActual, allocations)
            && allocations == 0
            && std::ranges::equal(lastActual, lastExpected.mono)
            && lastActual[1] != 0.0,
        "C102 one-based last-partial selection should observe exact Spectrum index 4096");

    const auto invalidGraph = compile(
        makeSosOscillatorsDocument({
            {"nbrOscillators", "2"},
            {"firstOscillator", "2"},
            resourceParameter("wavetable", ""),
        }),
        {16.0, 2});
    talas::runtime::RealtimeRenderSession invalid(invalidGraph);
    std::array<double, 2> rejected{1.0, 1.0};
    require(invalid.ready()
            && !renderAndCount(invalid, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 2>{},
        "C102 selected partial range beyond the static Spectrum should reject the complete callback");
}

void testRealtimeSosOscillatorsRejectsForgedPreparedAuthority()
{
    const auto graph = compile(
        makeSosOscillatorsDocument(),
        talas::runtime::RenderSettings{16.0, 4});
    const auto requireRejected = [&](auto mutate,
                                     std::string_view context) {
        auto plan = graph.plan();
        const auto step = std::ranges::find(
            plan.steps,
            std::string_view{"talas.sosOscillators"},
            &talas::runtime::CompileStep::typeId);
        require(step != plan.steps.end(),
            "C102 forged-authority fixture should expose SOS Oscillators");
        mutate(plan, *step);
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), graph.renderSettings()});
        require(!session.ready(), std::string{context}
                + " should reject forged C102 SOS Oscillators authority");
    };
    requireRejected(
        [](auto&, auto& step) { step.supportsReset = false; },
        "forged reset capability");
    requireRejected(
        [](auto&, auto& step) { step.resolvedLatencyFrames = 1; },
        "forged intrinsic latency");
    requireRejected(
        [](auto&, auto& step) {
            step.offlineBinding = talas::core::ExecutionBinding::Kernel;
            step.kernelKind = talas::runtime::KernelKind::Gate;
        },
        "forged offline binding");
    requireRejected(
        [](auto&, auto& step) {
            std::swap(step.parameters[0], step.parameters[1]);
        },
        "forged parameter order");
    requireRejected(
        [](auto&, auto& step) {
            std::swap(step.inputs[0], step.inputs[1]);
        },
        "forged input order");
    requireRejected(
        [](auto&, auto& step) {
            step.parameters[2].text = "forged";
        },
        "forged wavetable resource shape");
    requireRejected(
        [](auto& plan, auto& step) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == step.nodeId
                        && buffer.scopeId == step.scopeId
                        && buffer.portId == "audioOut";
                });
            require(output != plan.buffers.end(),
                "C102 forged-authority fixture should expose mono output");
            output->frames -= 1;
        },
        "forged output frame capacity");
    requireRejected(
        [](auto&, auto& step) { step.structuralScopeId += 1; },
        "forged structural scope");
}

void testSosOscillatorsRequiresExactCompilerOwnedAuthority()
{
    const auto settings = talas::runtime::RenderSettings{16.0, 4};
    const auto document = makeSosOscillatorsDocument();
    const auto compiled = compile(document, settings);
    const auto sos = std::ranges::find(
        compiled.plan().steps,
        std::string_view{"talas.sosOscillators"},
        &talas::runtime::CompileStep::typeId);
    require(sos != compiled.plan().steps.end()
            && sos->offlineSupport
                == talas::core::ExecutionSupport::Supported
            && sos->preparedRealtimeSupport
                == talas::core::ExecutionSupport::Supported
            && sos->supportsReset
            && sos->resolvedLatencyFrames == 0,
        "C167 exact SOS Oscillators should carry promoted offline/prepared authority");
    talas::runtime::RealtimeRenderSession exactRealtime{compiled};
    const auto exactOffline = talas::runtime::renderOffline(compiled, 4);
    require(exactRealtime.ready() && exactOffline.ok(),
        "C167 exact built-in SOS Oscillators authority should render offline and prepare realtime");

    const auto requireRejected = [](auto graph,
                                    std::string_view context) {
        talas::runtime::RealtimeRenderSession realtime{graph};
        const auto offline = talas::runtime::renderOffline(graph, 4);
        require(!realtime.ready() && !offline.ok()
                && offline.mono.empty(),
            "C167 SOS Oscillators should reject "
                + std::string{context});
    };
    requireRejected(
        makePublicCompatibilityGraphWithSubsetOscillators(compiled),
        "a public reconstruction without the compiler seal");

    const auto requirePlanMutationRejected = [&] (
        auto mutate, std::string_view context) {
        auto graph = compiled;
        auto& plan = mutablePlanForTest(graph);
        const auto step = std::ranges::find(
            plan.steps,
            std::string_view{"talas.sosOscillators"},
            &talas::runtime::CompileStep::typeId);
        require(step != plan.steps.end(),
            "C167 plan mutation fixture should expose SOS Oscillators");
        mutate(plan, *step);
        requireRejected(std::move(graph), context);
    };
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.parameters.front().value = std::nextafter(
            step.parameters.front().value,
            std::numeric_limits<double>::infinity());
    }, "a sealed selection mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.inputs.front().sourcePortId += "Forged";
    }, "a sealed Spectrum input-binding mutation");
    requirePlanMutationRejected([] (auto& plan, auto& step) {
        require(step.inputs.front().bufferIndex < plan.buffers.size(),
            "C167 Spectrum producer fixture should expose its source buffer");
        auto& source = plan.buffers[step.inputs.front().bufferIndex];
        require(source.nodeId == step.inputs.front().sourceNodeId
                && source.portId == step.inputs.front().sourcePortId,
            "C167 Spectrum producer fixture should retain exact source metadata");
        source.nodeId += "Forged";
    }, "a sealed Spectrum producer-buffer mutation");
    requirePlanMutationRejected([] (auto& plan, auto& step) {
        const auto output = std::ranges::find_if(
            plan.buffers,
            [&] (const auto& buffer) {
                return buffer.nodeId == step.nodeId
                    && buffer.scopeId == step.scopeId
                    && buffer.portId == "audioOut";
            });
        require(output != plan.buffers.end(),
            "C167 mutation fixture should expose audioOut");
        ++output->frames;
    }, "a sealed output-buffer mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        ++step.scopeId;
    }, "a sealed scope mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.resolvedLatencyFrames = 1;
    }, "a sealed latency mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.preparedRealtimeSupport =
            talas::core::ExecutionSupport::Subset;
    }, "a sealed support mutation");

    auto changedSettings = compiled;
    ++mutableSettingsForTest(changedSettings).maxBlockFrames;
    requireRejected(std::move(changedSettings),
        "a sealed RenderSettings mutation");
    auto changedResource = compiled;
    mutableSettingsForTest(changedResource).tableResources.push_back({
        "C167Forged", {1.0}});
    requireRejected(std::move(changedResource),
        "a forged immutable resource-list mutation");
    auto changedSnapshot = compiled;
    mutableSettingsForTest(changedSnapshot).resourceSnapshots.push_back(
        std::make_shared<talas::core::ResourceSnapshot>());
    requireRejected(std::move(changedSnapshot),
        "a forged immutable resource snapshot");

    auto subsetRegistry = talas::core::makeBuiltinNodeRegistry();
    subsetRegistry.setNodeTypeOfflineSupport(
        "talas.sosOscillators", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    subsetRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.sosOscillators", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto subset = talas::runtime::compileProject(
        document, subsetRegistry, settings);
    require(subset.ok(),
        "C167 explicit custom both-Subset SOS Oscillators should compile");
    talas::runtime::RealtimeRenderSession sealedSubsetRealtime{*subset.graph};
    const auto sealedSubsetOffline = talas::runtime::renderOffline(
        *subset.graph, 4);
    const auto publicSubset =
        makePublicCompatibilityGraphWithSubsetOscillators(*subset.graph);
    talas::runtime::RealtimeRenderSession subsetRealtime{publicSubset};
    const auto subsetOffline = talas::runtime::renderOffline(publicSubset, 4);
    require(sealedSubsetRealtime.ready() && sealedSubsetOffline.ok()
            && subsetRealtime.ready() && subsetOffline.ok(),
        "C167 coherent custom both-Subset SOS Oscillators should retain legacy compatibility");

    auto mixedRegistry = talas::core::makeBuiltinNodeRegistry();
    mixedRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.sosOscillators", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto mixed = talas::runtime::compileProject(
        document, mixedRegistry, settings);
    require(mixed.ok(),
        "C167 mixed-support descriptor fixture should compile before authority rejection");
    requireRejected(*mixed.graph,
        "mixed offline/prepared descriptor support");

    auto divergentRegistry = talas::core::makeBuiltinNodeRegistry();
    divergentRegistry.setNodeTypeFanInLatencyPolicy(
        "talas.sosOscillators",
        talas::core::FanInLatencyPolicy::PreserveRelative);
    const auto divergent = talas::runtime::compileProject(
        document, divergentRegistry, settings);
    require(divergent.ok(),
        "C167 divergent descriptor fixture should compile before authority rejection");
    requireRejected(*divergent.graph,
        "a divergent Supported descriptor");

    auto contextualSettings = settings;
    contextualSettings.eventValues.push_back({
        "C167Count", 2.0, talas::expr::ValueDomain::Scalar});
    std::vector<talas::project::ProjectParameterExpression>
        contextualParameters{
            {"nbrOscillators", "1"},
            {"firstOscillator", "2"},
            resourceParameter("wavetable", ""),
        };
    contextualParameters.front().expression = "!C167Count";
    const auto contextual = compile(
        makeSosOscillatorsDocument(std::move(contextualParameters)),
        contextualSettings);
    const auto contextualSos = std::ranges::find(
        contextual.plan().steps,
        std::string_view{"talas.sosOscillators"},
        &talas::runtime::CompileStep::typeId);
    // NbrOscillators is a constant field: an Event
    // Value there compiles to its starting value, so the instance is as
    // exact as a static one (2026-10-13).
    require(contextualSos != contextual.plan().steps.end()
            && contextualSos->offlineSupport
                == talas::core::ExecutionSupport::Supported
            && contextualSos->preparedRealtimeSupport
                == talas::core::ExecutionSupport::Supported,
        "C167 an SOS count given an Event Value should compile to its starting value with promoted authority");

    auto combinedDocument = document;
    combinedDocument.graph.nodes.push_back(node(
        "contextualSos", "talas.sosOscillators", {
            {"nbrOscillators", "!C167Count"},
            {"firstOscillator", "1"},
            resourceParameter("wavetable", ""),
        }));
    std::erase_if(
        combinedDocument.graph.connections,
        [](const auto& edge) {
            return edge.fromNode == "sos" && edge.toNode == "out";
        });
    combinedDocument.graph.connections.push_back(connection(
        "spectrum", "spectrumOut", "contextualSos", "spectrum"));
    combinedDocument.graph.connections.push_back(connection(
        "sos", "audioOut", "contextualSos", "cascadeInput"));
    combinedDocument.graph.connections.push_back(connection(
        "contextualSos", "audioOut", "out", "audioIn"));
    const auto combined = compile(combinedDocument, contextualSettings);
    std::size_t promotedCount = 0;
    std::size_t subsetCount = 0;
    for (const auto& step : combined.plan().steps)
    {
        if (step.typeId != "talas.sosOscillators")
            continue;
        if (step.offlineSupport
                == talas::core::ExecutionSupport::Supported
            && step.preparedRealtimeSupport
                == talas::core::ExecutionSupport::Supported)
        {
            ++promotedCount;
        }
        else if (step.offlineSupport
                    == talas::core::ExecutionSupport::Subset
                 && step.preparedRealtimeSupport
                    == talas::core::ExecutionSupport::Subset)
        {
            ++subsetCount;
        }
    }
    talas::runtime::RealtimeRenderSession combinedRealtime{combined};
    const auto combinedOffline = talas::runtime::renderOffline(combined, 4);
    std::string combinedOfflineDiagnostics;
    for (const auto& diagnostic : combinedOffline.diagnostics)
    {
        combinedOfflineDiagnostics += diagnostic.nodeId + "."
            + diagnostic.parameterId + ": " + diagnostic.message + "; ";
    }
    require(promotedCount == 2 && subsetCount == 0
            && combinedRealtime.ready() && combinedOffline.ok(),
        "C167 an SOS Oscillators instance whose count starts from an Event Value should be promoted beside an exact one: promoted="
            + std::to_string(promotedCount)
            + " subset=" + std::to_string(subsetCount)
            + " realtime=" + std::string{combinedRealtime.error()}
            + " offline=" + combinedOfflineDiagnostics);
}

// SOSOscillators takes any Spectrum: an instance fed by a
// SpectrumOnDisk, or by a SyntheticSpectrumFromArray whose envelope is
// connected, is compiler-demoted and plays alike offline and prepared.
void testSosOscillatorsPlaysADynamicSpectrumProducerOfflineAndPrepared()
{
    const auto requirePlayed = [&](bool useSpectrumOnDisk,
                                   std::string_view context) {
        talas::runtime::RenderSettings settings{16.0, 4};
        settings.tableResources.push_back({
            "Analysis/C102Dynamic",
            {1.0, 1.0, 0.0, 0.5, 2.0, 0.0},
        });
        auto document =
            makeSosOscillatorsAuthorityProbeDocument(useSpectrumOnDisk);
        for (auto& edge : document.graph.connections)
        {
            if (edge.toNode == "sos" && edge.toPort == "spectrum")
                edge.fromNode = "alternate";
        }
        const auto compiled = talas::runtime::compileProject(
            document, talas::core::makeBuiltinNodeRegistry(), settings);
        require(compiled.ok() && compiled.graph.has_value(),
            std::string{context} + " should compile");
        const auto& graph = *compiled.graph;
        const auto plan = graph.plan();
        const auto sos = std::ranges::find(
            plan.steps,
            std::string_view{"sos"},
            &talas::runtime::CompileStep::nodeId);
        require(sos != plan.steps.end()
                && sos->offlineSupport
                    == talas::core::ExecutionSupport::Subset
                && sos->preparedRealtimeSupport
                    == talas::core::ExecutionSupport::Subset,
            std::string{context} + " should demote SOS Oscillators");
        const auto offline = talas::runtime::renderOffline(graph, 8);
        require(offline.ok() && offline.mono.size() == 8,
            std::string{context} + " should render offline");
        talas::runtime::RealtimeRenderSession prepared(graph);
        require(prepared.ready(),
            std::string{context} + " should prepare: "
                + std::string{prepared.error()});
        std::array<double, 8> actual{};
        std::size_t allocations = 0;
        for (std::size_t offset = 0; offset < actual.size(); offset += 4)
        {
            require(renderAndCount(prepared,
                        std::span<double>{actual}.subspan(offset, 4),
                        allocations)
                    && allocations == 0,
                std::string{context}
                    + " should render without allocation");
        }
        require(std::ranges::equal(actual, offline.mono),
            std::string{context}
                + " should play alike offline and prepared");
    };

    requirePlayed(true, "SpectrumOnDisk producer");
    requirePlayed(false, "connected-envelope SyntheticSpectrum producer");
}

void testSosOscillatorsRejectsNearIntegralForgedSelectionOfflineAndPrepared()
{
    const auto graph = compile(
        makeSosOscillatorsDocument(),
        talas::runtime::RenderSettings{16.0, 4});
    const auto parsed = talas::expr::parse(
        "1.0000000005",
        graph.renderSettings().expressionLanguage,
        graph.renderSettings().expressionDefinitions);
    require(parsed.ok() && parsed.expression.has_value(),
        "C102 near-integral forged expression should parse");

    for (const auto parameterId : {
             std::string_view{"nbrOscillators"},
             std::string_view{"firstOscillator"},
         })
    {
        auto plan = graph.plan();
        const auto sos = std::ranges::find(
            plan.steps,
            std::string_view{"sos"},
            &talas::runtime::CompileStep::nodeId);
        require(sos != plan.steps.end(),
            "C102 near-integral fixture should expose SOS Oscillators");
        const auto parameter = std::ranges::find(
            sos->parameters,
            parameterId,
            &talas::runtime::ParameterValue::id);
        require(parameter != sos->parameters.end(),
            "C102 near-integral fixture should expose "
                + std::string{parameterId});
        parameter->value = 1.0000000005;
        parameter->expression = *parsed.expression;
        const auto forgedGraph = talas::runtime::PreparedRuntimeGraph{
            std::move(plan), graph.renderSettings()};

        const auto offline = talas::runtime::renderOffline(forgedGraph, 4);
        require(!offline.ok() && offline.mono.empty(),
            "C102 offline render should reject forged near-integral "
                + std::string{parameterId});
        talas::runtime::RealtimeRenderSession prepared(forgedGraph);
        require(!prepared.ready(),
            "C102 prepared admission should reject forged near-integral "
                + std::string{parameterId});
    }
}

void testRealtimeLowPassGateRejectsForgedPreparedAuthority()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("input", "talas.oscillator", {
            {"frequency", "1 hz"}, {"amplitude", "0.5"},
        }),
        node("gate", "talas.lowPassGate", {
            {"control", "0.75"},
            {"closedFrequency", "0.5 hz"},
            {"openFrequency", "3 hz"},
            {"attackTime", "0.25 s"},
            {"releaseTime", "0.5 s"},
            {"curve", "2"},
            {"scale", "1"},
        }),
    };
    document.graph.connections = {
        connection("input", "audioOut", "gate", "audioIn"),
        connection("gate", "audioOut", "out", "audioIn"),
    };
    const auto graph = compile(
        document, talas::runtime::RenderSettings{8.0, 4});
    const auto requireRejected = [&](auto mutate,
                                     std::string_view context) {
        auto plan = graph.plan();
        const auto gate = std::ranges::find(
            plan.steps,
            std::string_view{"gate"},
            &talas::runtime::CompileStep::nodeId);
        require(gate != plan.steps.end(),
            "C103 forged-authority fixture should expose Low-Pass Gate");
        mutate(plan, *gate);
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), graph.renderSettings()});
        require(!session.ready(), std::string{context}
                + " should reject forged C103 Low-Pass Gate authority");
    };
    requireRejected(
        [](auto&, auto& gate) { gate.supportsReset = false; },
        "forged reset capability");
    requireRejected(
        [](auto&, auto& gate) {
            gate.offlineSupport = talas::core::ExecutionSupport::Subset;
        },
        "forged offline support");
    requireRejected(
        [](auto&, auto& gate) {
            gate.resolvedLatencyFrames = 1;
        },
        "forged intrinsic latency");
    requireRejected(
        [](auto&, auto& gate) {
            std::swap(gate.parameters[0], gate.parameters[1]);
        },
        "forged parameter order");
    requireRejected(
        [](auto&, auto& gate) { gate.structuralScopeId += 1; },
        "forged structural scope");
    requireRejected(
        [](auto& plan, auto& gate) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == gate.nodeId
                        && buffer.scopeId == gate.scopeId
                        && buffer.portId == "audioOut";
                });
            require(output != plan.buffers.end(),
                "C103 forged-authority fixture should expose mono output");
            output->frames -= 1;
        },
        "forged output capacity");

    auto connected = document;
    const auto gate = std::ranges::find(
        connected.graph.nodes,
        std::string_view{"gate"},
        &talas::project::ProjectNode::instanceId);
    require(gate != connected.graph.nodes.end(),
        "C103 connected-authority fixture should expose Low-Pass Gate");
    gate->parameters.front().expression = "1 / 0";
    connected.graph.nodes.push_back(node(
        "control", "talas.constant", {{"value", "0.75"}}));
    connected.graph.connections.push_back(connection(
        "control", "value", "gate", "control"));
    const auto connectedGraph = compile(
        connected, talas::runtime::RenderSettings{8.0, 4});
    talas::runtime::RealtimeRenderSession connectedSession(connectedGraph);
    require(connectedSession.ready(),
        "C103 connected control should own its valid prepared buffer independently of an invalid hidden fallback: "
            + std::string{connectedSession.error()});

    auto reorderedPlan = connectedGraph.plan();
    const auto reorderedGate = std::ranges::find(
        reorderedPlan.steps,
        std::string_view{"gate"},
        &talas::runtime::CompileStep::nodeId);
    require(reorderedGate != reorderedPlan.steps.end()
            && reorderedGate->inputs.size() == 2,
        "C103 connected-authority fixture should expose two ordered inputs");
    std::swap(reorderedGate->inputs[0], reorderedGate->inputs[1]);
    std::swap(
        reorderedGate->inputLatencyFrames[0],
        reorderedGate->inputLatencyFrames[1]);
    talas::runtime::RealtimeRenderSession reordered(
        talas::runtime::PreparedRuntimeGraph{
            std::move(reorderedPlan), connectedGraph.renderSettings()});
    require(!reordered.ready(),
        "C103 prepared admission should reject forged Low-Pass Gate input order");
}

void testRealtimeLowPassGateOwnsLateDownstreamRollbackAndReset()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("input", "talas.audioInput", {
            choiceParameter("routing", "monoSum"),
            booleanParameter("channel1", true),
            booleanParameter("channel2", false),
        }),
        node("gate", "talas.lowPassGate", {
            {"control", "1"},
            {"closedFrequency", "0.5 hz"},
            {"openFrequency", "3 hz"},
            {"attackTime", "0.25 s"},
            {"releaseTime", "0.5 s"},
            {"curve", "2"},
            {"scale", "1"},
        }),
        node("downstream", "talas.level", {
            {"left", "!C103Downstream"}, {"right", "0"},
            booleanParameter("noGain", false),
        }),
    };
    document.graph.connections = {
        connection("input", "audioOut", "gate", "audioIn"),
        connection("gate", "audioOut", "downstream", "audioIn"),
        connection("downstream", "leftOut", "out", "audioIn"),
    };
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.eventValues = {
        {"C103Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    talas::runtime::RealtimeRenderSession fresh(graph);
    require(candidate.ready() && reference.ready() && fresh.ready(),
        "C103 module-owned rollback fixtures should prepare: "
            + std::string{candidate.error()});
    require(candidate.updateEventValue(
                "C103Downstream",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C103 rollback fixture should arm its later downstream overflow");

    std::array<float, 4> inputChannel{64.0F, 64.0F, 64.0F, 64.0F};
    std::array<const float*, 1> inputChannels{inputChannel.data()};
    const talas::runtime::RealtimeAudioInputBlock inputBlock{
        inputChannels.data(), inputChannels.size()};
    std::array<double, 4> rejected;
    rejected.fill(100.0);
    std::size_t allocations = 0;
    require(!renderStereoInputAndCount(
                candidate, inputBlock, rejected, {}, allocations)
            && allocations == 0
            && rejected == std::array<double, 4>{},
        "C103 later downstream failure should publish no callback prefix");
    require(candidate.updateEventValue(
                "C103Downstream", 1.0,
                talas::expr::ValueDomain::Scalar),
        "C103 rollback fixture should repair only the downstream control");

    std::array<double, 4> retry{};
    std::array<double, 4> expected{};
    require(renderStereoInputAndCount(
                candidate, inputBlock, retry, {}, allocations)
            && allocations == 0
            && renderStereoInputAndCount(
                reference, inputBlock, expected, {}, allocations)
            && allocations == 0
            && retry == expected,
        "C103 later failure should restore Low-Pass Gate state before exact retry");

    std::size_t resetAllocations = 0;
    {
        AllocationCounter counter;
        candidate.resetTransport();
        resetAllocations = counter.count();
    }
    std::array<double, 4> reset{};
    std::array<double, 4> freshOutput{};
    require(resetAllocations == 0
            && renderStereoInputAndCount(
                candidate, inputBlock, reset, {}, allocations)
            && allocations == 0
            && renderStereoInputAndCount(
                fresh, inputBlock, freshOutput, {}, allocations)
            && allocations == 0
            && reset == freshOutput,
        "C103 transport reset should replay fresh Low-Pass Gate state without allocation");
}

void testAntialiasedOscillatorPreservesCyclePhaseAndExcludesAliasedHarmonics()
{
    using talas::runtime::checked_antialiased_oscillator::buildProfile;
    using talas::runtime::checked_antialiased_oscillator::renderFrame;
    std::vector<double> cycle(7);
    for (std::size_t index = 0; index < cycle.size(); ++index)
    {
        const auto position = 2.0 * std::numbers::pi
            * static_cast<double>(index)
            / static_cast<double>(cycle.size());
        cycle[index] = std::sin(position + 0.4)
            + 0.4 * std::sin(3.0 * position + 0.2);
    }
    const auto profile = buildProfile(cycle, 0.5);
    const auto warped = buildProfile(cycle, 0.3);
    require(profile.has_value() && profile->size() == 7
            && warped.has_value() && warped->size() == 7
            && std::abs((*profile)[1] - (*warped)[1]) > 1.0e-3,
        "AntialiasedOscillator should preserve complex bins and react to DutyCycle");
    double phase = 0.0;
    double fullSample = 0.0;
    require(renderFrame(*profile, 8000.0, 1000.0, 1.0,
                phase, fullSample),
        "AntialiasedOscillator should render a phase-shifted seven-sample cycle");
    requireNear(fullSample, cycle.front(), 1.0e-10,
        "AntialiasedOscillator should reconstruct the source phase at frame zero");
    phase = 0.0;
    double bandlimited = 0.0;
    require(renderFrame(*profile, 8000.0, 1600.0, 1.0,
                phase, bandlimited),
        "AntialiasedOscillator should render below the fundamental Nyquist limit");
    requireNear(bandlimited,
        (*profile)[0] + (*profile)[1] + (*profile)[3], 1.0e-10,
        "AntialiasedOscillator should exclude the third harmonic above Nyquist");
    phase = 0.0;
    double atNyquist = 0.0;
    require(renderFrame(*profile, 8000.0, 4000.0, 1.0,
                phase, atNyquist),
        "AntialiasedOscillator should render at Nyquist without an aliased partial");
    requireNear(atNyquist, (*profile)[0], 1.0e-10,
        "AntialiasedOscillator should exclude a fundamental at Nyquist");
    phase = 0.0;
    double dark = 0.0;
    require(renderFrame(*profile, 8000.0, 1000.0, 0.0,
                phase, dark),
        "AntialiasedOscillator should accept minimum Brightness");
    requireNear(dark, (*profile)[0] + (*profile)[1], 1.0e-10,
        "minimum Brightness should retain DC and the fundamental only");
    require(!buildProfile(std::span<const double>{cycle.data(), 1}, 0.5)
                 .has_value()
            && !buildProfile(cycle, 0.0).has_value(),
        "AntialiasedOscillator should reject short cycles and invalid DutyCycle");

    std::vector<double> longCycle(5003);
    for (std::size_t index = 0; index < longCycle.size(); ++index)
        longCycle[index] = std::sin(
            2.0 * std::numbers::pi * 17.0
            * static_cast<double>(index)
            / static_cast<double>(longCycle.size()));
    const auto longProfile = buildProfile(longCycle, 0.5);
    require(longProfile.has_value() && longProfile->size() == 2049
            && std::hypot((*longProfile)[1 + 2 * 16],
                (*longProfile)[2 + 2 * 16]) > 0.9,
        "AntialiasedOscillator should preserve a non-power-of-two cycle beyond 4096 samples");

    const auto makeDocument = [&](bool connected,
                                  std::string fileName,
                                  std::string staticFrequency,
                                  std::string dutyCycle) {
        talas::project::ProjectDocument document;
        document.graph.nodes.push_back(node("out", "talas.audioOutput"));
        document.graph.nodes.push_back(node(
            "osc", "talas.antialiasedOscillator",
            {resourceParameter("fileName", std::move(fileName)),
             {"frequency", std::move(staticFrequency)},
             {"brightness", "1.0"},
             {"dutyCycle", std::move(dutyCycle)}}));
        if (connected)
        {
            document.graph.nodes.push_back(node(
                "frequency", "talas.linearRamp",
                {{"duration", "2 ms"},
                 {"start", "1000"}, {"end", "1800"}}));
            document.graph.nodes.push_back(node(
                "brightness", "talas.linearRamp",
                {{"duration", "2 ms"},
                 {"start", "0.2"}, {"end", "1.0"}}));
            document.graph.connections.push_back(connection(
                "frequency", "value", "osc", "frequency"));
            document.graph.connections.push_back(connection(
                "brightness", "value", "osc", "brightness"));
        }
        document.graph.connections.push_back(connection(
            "osc", "audioOut", "out", "audioIn"));
        return document;
    };
    const auto registry = talas::core::makeBuiltinNodeRegistry();
    for (std::size_t fixture = 0; fixture < 3; ++fixture)
    {
        const auto connected = fixture == 1;
        const auto longTable = fixture == 2;
        const auto fileName = longTable
            ? std::string{"Cycles/FiveThousandThree"}
            : std::string{"Cycles/Seven"};
        const auto saved = talas::project::serializeProjectDocument(
            makeDocument(connected, fileName,
                longTable ? "100 hz" : "1000 hz",
                connected ? "0.3" : "0.5"), registry);
        const auto reopened = talas::project::parseProjectDocument(saved);
        require(reopened.ok()
                && talas::project::serializeProjectDocument(
                    reopened.document, registry) == saved,
            "AntialiasedOscillator Sound should save and reopen byte-stably");
        talas::runtime::RenderSettings settings{8000.0, 23};
        settings.tableResources.push_back({
            fileName, longTable ? longCycle : cycle});
        auto graph = compile(reopened.document, std::move(settings));
        if (fixture == 0)
        {
            auto forged = graph;
            auto& tables = mutableSettingsForTest(forged).tableResources;
            require(!tables.empty() && !tables.front().samples.empty(),
                "AntialiasedOscillator fixture should expose its sealed cycle");
            tables.front().samples.front() += 0.25;
            talas::runtime::RealtimeRenderSession rejected(forged);
            require(!rejected.ready(),
                "AntialiasedOscillator should reject a changed cycle after compilation");
        }
        const auto offline = talas::runtime::renderOffline(graph, 23);
        require(offline.ok() && offline.mono.size() == 23,
            "AntialiasedOscillator should render offline");
        require(std::ranges::any_of(
                offline.mono, [](double value) {
                    return std::abs(value) > 0.1;
                }),
            "AntialiasedOscillator should retain audible source harmonics");
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(),
            "AntialiasedOscillator should prepare: "
                + std::string{session.error()});
        std::array<double, 7> first{};
        std::array<double, 9> second{};
        std::array<double, 7> third{};
        std::size_t allocations = 0;
        require(renderAndCount(session, first, allocations)
                && renderAndCount(session, second, allocations)
                && renderAndCount(session, third, allocations)
                && allocations == 0,
            "AntialiasedOscillator should render unequal callbacks without allocations");
        std::vector<double> prepared;
        prepared.insert(prepared.end(), first.begin(), first.end());
        prepared.insert(prepared.end(), second.begin(), second.end());
        prepared.insert(prepared.end(), third.begin(), third.end());
        for (std::size_t index = 0; index < prepared.size(); ++index)
            requireNear(prepared[index], offline.mono[index], 1.0e-9,
                "AntialiasedOscillator offline/prepared sample");
        std::size_t resetAllocations = 0;
        {
            AllocationCounter counter;
            session.resetTransport();
            resetAllocations = counter.count();
        }
        std::array<double, 7> reset{};
        require(resetAllocations == 0
                && renderAndCount(session, reset, allocations)
                && allocations == 0
                && reset == first,
            "AntialiasedOscillator should reset phase and controls without allocation");
    }
}

// Parameter fields follow Event Values while a Sound plays: an
// AntialiasedOscillator's Frequency and Brightness do, alike offline and in
// realtime, while DutyCycle shapes the cycle once.
void testAntialiasedOscillatorFollowsLiveFrequencyAndBrightness()
{
    using talas::runtime::checked_antialiased_oscillator::buildProfile;
    using talas::runtime::checked_antialiased_oscillator::renderFrame;
    std::vector<double> cycle(7);
    for (std::size_t index = 0; index < cycle.size(); ++index)
    {
        const auto position = 2.0 * std::numbers::pi
            * static_cast<double>(index)
            / static_cast<double>(cycle.size());
        cycle[index] = std::sin(position + 0.4)
            + 0.4 * std::sin(3.0 * position + 0.2);
    }
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "osc", "talas.antialiasedOscillator",
        {resourceParameter("fileName", "Cycles/Seven"),
         {"frequency", "!Pitch * (1 hz)"},
         {"brightness", "!Bright"},
         {"dutyCycle", "0.5"}}));
    document.graph.connections.push_back(connection(
        "osc", "audioOut", "out", "audioIn"));
    talas::runtime::RenderSettings settings{8000.0, 16};
    settings.tableResources.push_back({"Cycles/Seven", cycle});
    settings.eventValues = {
        {"Pitch", 1000.0, talas::expr::ValueDomain::Scalar},
        {"Bright", 1.0, talas::expr::ValueDomain::Scalar}};
    settings.eventValueChanges = {
        {32, "Pitch", 500.0, talas::expr::ValueDomain::Scalar},
        {48, "Bright", 0.0, talas::expr::ValueDomain::Scalar}};
    const auto graph = compile(document, std::move(settings));
    const auto offline = talas::runtime::renderOffline(graph, 64);
    require(offline.ok() && offline.mono.size() == 64,
        "a live AntialiasedOscillator should render offline");
    const auto profile = buildProfile(cycle, 0.5);
    require(profile.has_value(), "the live AntialiasedOscillator cycle should build");
    double phase = 0.0;
    for (std::size_t frame = 0; frame < offline.mono.size(); ++frame)
    {
        double expected = 0.0;
        require(renderFrame(*profile, 8000.0, frame < 32 ? 1000.0 : 500.0,
                    frame < 48 ? 1.0 : 0.0, phase, expected),
            "the expected AntialiasedOscillator frame should render");
        requireNear(offline.mono[frame], expected, 1.0e-9,
            "the AntialiasedOscillator should follow Frequency and Brightness at frame "
                + std::to_string(frame));
    }

    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(),
        "a live AntialiasedOscillator should prepare: "
            + std::string{session.error()});
    std::array<double, 16> block{};
    for (std::size_t offset = 0; offset < offline.mono.size(); offset += block.size())
    {
        std::size_t allocations = 0;
        require(renderAndCount(session, block, allocations) && allocations == 0,
            "a live AntialiasedOscillator should render without allocations");
        for (std::size_t frame = 0; frame < block.size(); ++frame)
            requireNear(block[frame], offline.mono[offset + frame], 1.0e-9,
                "live AntialiasedOscillator offline/prepared sample");
    }
}

void testHarmonicSpectrumFrequencyAccuracyAcrossSampleRates()
{
    using talas::runtime::checked_harmonic_spectrum::make;
    const auto large = make(5.125, 4096, 0.25);
    require(large.has_value() && large->size() == 4096
            && (*large)[0].frequency == 5.125
            && (*large)[2047].frequency == 10496.0
            && (*large)[4095].frequency == 20992.0
            && (*large)[4095].amplitude == 0.25,
        "HarmonicSpectrum should derive each high harmonic directly from the fundamental");
    require(!make(0.0, 1, 1.0).has_value()
            && !make(440.0, 0, 1.0).has_value()
            && !make(440.0, 4097, 1.0).has_value()
            && !make(440.0, 1, -1.0).has_value()
            && !make(1.0e308, 2, 1.0).has_value(),
        "HarmonicSpectrum should reject invalid counts and non-finite partial frequencies");

    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "harmonics", "talas.harmonicSpectrum",
        {{"frequency", "137.125 hz"},
         {"nbrPartials", "32"},
         {"amplitude", "0.25"}}));
    document.graph.nodes.push_back(node(
        "track", "talas.spectrumTrackSelector", hertzSelector({{"track", "7"}})));
    document.graph.connections.push_back(connection(
        "harmonics", "spectrumOut", "track", "spectrumIn"));
    document.graph.connections.push_back(connection(
        "track", "rightOut", "out", "audioIn"));
    const auto registry = talas::core::makeBuiltinNodeRegistry();
    const auto saved = talas::project::serializeProjectDocument(
        document, registry);
    const auto reopened = talas::project::parseProjectDocument(saved);
    require(reopened.ok()
            && talas::project::serializeProjectDocument(
                reopened.document, registry) == saved,
        "HarmonicSpectrum Sound should save and reopen byte-stably");

    for (const auto sampleRate : {11025.0, 48000.0})
    {
        auto graph = compile(
            reopened.document, talas::runtime::RenderSettings{sampleRate, 11});
        const auto offline = talas::runtime::renderOffline(graph, 11);
        require(offline.ok() && offline.mono.size() == 11,
            "HarmonicSpectrum track selector should render offline");
        for (const auto value : offline.mono)
            requireNear(value, 959.875, 1.0e-10,
                "HarmonicSpectrum seventh partial should retain its Hertz frequency");

        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(),
            "HarmonicSpectrum should prepare: " + std::string{session.error()});
        std::array<double, 3> first{};
        std::array<double, 5> second{};
        std::array<double, 3> third{};
        std::size_t allocations = 0;
        require(renderAndCount(session, first, allocations)
                && renderAndCount(session, second, allocations)
                && renderAndCount(session, third, allocations)
                && allocations == 0,
            "HarmonicSpectrum should render unequal callbacks without allocations");
        std::vector<double> prepared;
        prepared.insert(prepared.end(), first.begin(), first.end());
        prepared.insert(prepared.end(), second.begin(), second.end());
        prepared.insert(prepared.end(), third.begin(), third.end());
        require(prepared == offline.mono,
            "HarmonicSpectrum prepared and offline frequencies should agree exactly");

        auto forged = graph;
        auto& plan = mutablePlanForTest(forged);
        const auto harmonic = std::ranges::find(
            plan.steps, std::string_view{"harmonics"},
            &talas::runtime::CompileStep::nodeId);
        require(harmonic != plan.steps.end(),
            "HarmonicSpectrum should retain its plan step");
        auto& parameter = *std::ranges::find(
            harmonic->parameters, std::string_view{"frequency"},
            &talas::runtime::ParameterValue::id);
        parameter.value += 1.0;
        talas::runtime::RealtimeRenderSession rejected(forged);
        require(!rejected.ready(),
            "HarmonicSpectrum should reject a modified prepared fundamental");
    }

    auto invalid = reopened.document;
    auto& harmonic = *std::ranges::find(
        invalid.graph.nodes, std::string_view{"harmonics"},
        &talas::project::ProjectNode::instanceId);
    auto& count = *std::ranges::find(
        harmonic.parameters, std::string_view{"nbrPartials"},
        &talas::project::ProjectParameterExpression::parameterId);
    count.expression = "2.5";
    require(!talas::runtime::compileProject(
                 invalid, registry, talas::runtime::RenderSettings{48000.0, 11})
                 .ok(),
        "HarmonicSpectrum should reject fractional partial counts at compile time");
}

void testSingleCycleSpectrumHandlesArbitraryCycleLengthsAndBankPlayback()
{
    const auto makeSine = [](std::size_t length,
                             std::size_t harmonic,
                             double amplitude) {
        std::vector<double> samples(length);
        for (std::size_t index = 0; index < length; ++index)
            samples[index] = amplitude * std::sin(
                2.0 * std::numbers::pi
                * static_cast<double>(harmonic * index)
                / static_cast<double>(length));
        return samples;
    };
    const auto shortCycle = makeSine(7, 1, 1.0);
    const auto longerCycle = makeSine(15, 2, 0.5);
    const auto longNonPowerOfTwoCycle = makeSine(5003, 17, 0.75);
    const auto longSpectrum =
        talas::runtime::checked_single_cycle_spectrum::transform(
            longNonPowerOfTwoCycle, 5.0);
    require(longSpectrum.has_value()
        && longSpectrum->size() == 2501
        && std::abs((*longSpectrum)[16].amplitude - 0.75) < 1.0e-9
        && std::abs((*longSpectrum)[16].frequency - 85.0) < 1.0e-12
        && std::abs((*longSpectrum)[15].amplitude) < 1.0e-9,
        "arbitrary-length cycle FFT should resolve a harmonic beyond 4096 samples");

    const auto makeDocument = [](std::string fileName,
                                  std::size_t oscillators,
                                  std::string frequency) {
        talas::project::ProjectDocument document;
        document.graph.nodes.push_back(node("out", "talas.audioOutput"));
        document.graph.nodes.push_back(node(
            "spectrum", "talas.spectrumFromSingleCycle",
            {resourceParameter("fileName", std::move(fileName)),
             {"frequency", std::move(frequency)}}));
        document.graph.nodes.push_back(node(
            "bank", "talas.oscillatorBank",
            oscillatorBankParameters({
                {"nbrOscillators", std::to_string(oscillators)},
                {"bankSize", std::to_string(oscillators)}})));
        document.graph.connections.push_back(connection(
            "spectrum", "spectrumOut", "bank", "spectrum"));
        document.graph.connections.push_back(connection(
            "bank", "audioOut", "out", "audioIn"));
        return document;
    };
    const auto registry = talas::core::makeBuiltinNodeRegistry();
    const auto renderCycle = [&](std::string fileName,
                                 const std::vector<double>& cycle,
                                 std::size_t oscillators,
                                 std::string frequency) {
        const auto saved = talas::project::serializeProjectDocument(
            makeDocument(fileName, oscillators,
                std::move(frequency)), registry);
        const auto reopened = talas::project::parseProjectDocument(saved);
        require(reopened.ok()
            && talas::project::serializeProjectDocument(
                reopened.document, registry) == saved,
            "SpectrumFromSingleCycle Sound should save and reopen byte-stably");
        talas::runtime::RenderSettings settings{8000.0, 17};
        settings.tableResources.push_back({fileName, cycle});
        auto graph = compile(reopened.document, std::move(settings));
        if (cycle.size() == 7)
        {
            auto forged = graph;
            auto& tables = mutableSettingsForTest(forged).tableResources;
            require(!tables.empty() && !tables.front().samples.empty(),
                "single-cycle fixture should expose its sealed table");
            tables.front().samples.front() += 0.25;
            talas::runtime::RealtimeRenderSession rejected(forged);
            require(!rejected.ready(),
                "single-cycle spectrum should reject a changed table after compilation");
        }
        const auto offline = talas::runtime::renderOffline(graph, 17);
        require(offline.ok() && offline.mono.size() == 17,
            "single-cycle spectrum should feed OscillatorBank offline");
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(),
            "single-cycle spectrum should prepare for OscillatorBank: "
                + std::string{session.error()});
        std::array<double, 5> first{};
        std::array<double, 7> middle{};
        std::array<double, 5> last{};
        std::size_t allocations = 0;
        require(renderAndCount(session, first, allocations)
            && renderAndCount(session, middle, allocations)
            && renderAndCount(session, last, allocations)
            && allocations == 0,
            "single-cycle spectrum should render across unequal callbacks without allocations");
        std::vector<double> prepared;
        prepared.insert(prepared.end(), first.begin(), first.end());
        prepared.insert(prepared.end(), middle.begin(), middle.end());
        prepared.insert(prepared.end(), last.begin(), last.end());
        for (std::size_t index = 0; index < prepared.size(); ++index)
            requireNear(prepared[index], offline.mono[index], 1.0e-8,
                "single-cycle spectrum offline/prepared OscillatorBank sample");
        return offline.mono;
    };
    const auto first = renderCycle(
        "Cycles/Seven", shortCycle, 2, "100 hz");
    const auto second = renderCycle(
        "Cycles/Fifteen", longerCycle, 2, "100 hz");
    const auto beyond4096 = renderCycle(
        "Cycles/FiveThousandThree", longNonPowerOfTwoCycle,
        17, "5 hz");
    require(std::ranges::any_of(first, [](double value) {
            return std::abs(value) > 1.0e-4;
        })
        && std::ranges::any_of(second, [](double value) {
            return std::abs(value) > 1.0e-4;
        })
        && std::ranges::any_of(beyond4096, [](double value) {
            return std::abs(value) > 1.0e-4;
        })
        && !std::equal(first.begin(), first.end(), second.begin(),
            [](double left, double right) {
                return std::abs(left - right) < 1.0e-4;
            }),
        "different cycle lengths and harmonics should drive distinct bank audio");
}

void testRealtimeSessionRendersOscillatorBankAcrossBlocksAndResetWithoutAllocations()
{
    talas::runtime::RenderSettings settings{16.0, 4};
    auto graph = compile(
        makeOscillatorBankRealtimeDocument(), std::move(settings));
    const auto bank = std::ranges::find(
        graph.plan().steps,
        std::string_view{"bank"},
        &talas::runtime::CompileStep::nodeId);
    require(
        bank != graph.plan().steps.end(),
        "Oscillator Bank graph should contain its compiled step");
    require(
        bank->preparedRealtimeSupport
            == talas::core::ExecutionSupport::Subset,
        "Oscillator Bank should compile with prepared subset authority");
    require(
        bank->preparedRealtimeBinding
            == talas::core::ExecutionBinding::LegacyAdapter,
        "Oscillator Bank should compile with its legacy prepared binding");
    require(
        bank->supportsReset,
        "Oscillator Bank should compile with reset authority");
    require(
        bank->resolvedLatencyFrames
            == std::optional<std::size_t>{0},
        "Oscillator Bank should compile with exact zero intrinsic latency");
    require(
        bank->cumulativeOutputLatencyFrames
            == std::optional<std::size_t>{0},
        "Oscillator Bank should compile with exact zero output latency");
    require(
        !bank->preparedSpectralFrameSize.has_value()
            && !bank->preparedSpectralHopSize.has_value(),
        "Oscillator Bank should not claim native spectral frame authority");
    const auto expected = talas::runtime::renderOffline(graph, 8);
    require(expected.ok(), "offline Oscillator Bank reference should render");

    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 4> first{};
    std::array<double, 4> second{};
    std::size_t allocations = 0;
    require(
        renderAndCount(session, first, allocations),
        "first Oscillator Bank block should render");
    require(
        allocations == 0,
        "first Oscillator Bank block should not allocate");
    require(
        renderAndCount(session, second, allocations),
        "second Oscillator Bank block should render");
    require(
        allocations == 0,
        "second Oscillator Bank block should not allocate");
    for (std::size_t frame = 0; frame < first.size(); ++frame)
    {
        requireNear(
            first[frame],
            expected.mono[frame],
            1.0e-12,
            "first Oscillator Bank frame should match offline");
        requireNear(
            second[frame],
            expected.mono[first.size() + frame],
            1.0e-12,
            "second Oscillator Bank frame should match offline");
    }

    session.resetTransport();
    std::array<double, 4> reset{};
    require(
        renderAndCount(session, reset, allocations),
        "reset Oscillator Bank block should render");
    require(
        allocations == 0,
        "reset Oscillator Bank block should not allocate");
    for (std::size_t frame = 0; frame < reset.size(); ++frame)
    {
        requireNear(
            reset[frame],
            first[frame],
            1.0e-12,
            "Oscillator Bank reset should restart absolute-frame phase");
    }
}

void testSerializedOscillatorBankUpdatesOnePartialPerSampleAndRollsBack()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("amps", "talas.audioInput"),
        node("freqs", "talas.audioInput", {
            booleanParameter("channel1", false),
            booleanParameter("channel2", true)}),
        node("bank", "talas.oscillatorBank",
            oscillatorBankParameters({
                resourceParameter("wavetable", "Quarter")})),
        node("gain", "talas.constant", {{"value", "!BridgeGain"}}),
        node("first", "talas.vca"),
        node("second", "talas.vca"),
    };
    document.graph.connections = {
        connection("amps", "audioOut", "bank", "amplitudeIn"),
        connection("freqs", "audioOut", "bank", "frequencyIn"),
        connection("bank", "audioOut", "first", "audioIn"),
        connection("gain", "value", "first", "gain"),
        connection("first", "audioOut", "second", "audioIn"),
        connection("gain", "value", "second", "gain"),
        connection("second", "audioOut", "out", "audioIn"),
    };
    talas::runtime::RenderSettings settings{8.0, 3};
    settings.tableResources = {{"Quarter", {0.0, 1.0, 0.0, -1.0}}};
    settings.audioInputChannels = {
        {1, {0.5, 0.25, 1.0, 0.75, 1.0, 1.0}},
        {2, {1, 2, 2, 1, 1, 2}},
    };
    settings.eventValues = {{"BridgeGain", 1.0,
        talas::expr::ValueDomain::Scalar}};
    const auto graph = compile(document, settings);
    const auto offline = talas::runtime::renderOffline(graph, 6);
    require(offline.ok(),
        "offline serialized OscillatorBank reference should render");
    // Each oscillator advances its own phase by its partial's frequency.
    constexpr std::array<double, 6> expected{
        0.0, 0.25, 1.25, 0.0, -1.375, -1.5};
    for (std::size_t sample = 0; sample < expected.size(); ++sample)
        requireNear(offline.mono[sample], expected[sample], 1.0e-12,
            "offline serialized bank should replace one partial per sample");

    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(),
        "serialized OscillatorBank should prepare: "
            + std::string{session.error()});
    constexpr std::array<float, 6> amplitudes{
        0.5F, 0.25F, 1.0F, 0.75F, 1.0F, 1.0F};
    constexpr std::array<float, 6> frequencies{
        1, 2, 2, 1, 1, 2};
    const auto renderBlock = [&](std::size_t offset,
                                 std::span<double> output) {
        const std::array<const float*, 2> channels{
            amplitudes.data() + offset,
            frequencies.data() + offset};
        std::size_t allocations = 0;
        const auto rendered = renderMonoInputAndCount(session,
            {channels.data(), channels.size()}, output, allocations);
        require(allocations == 0,
            "serialized OscillatorBank callback should not allocate");
        return rendered;
    };
    std::array<double, 3> first{};
    std::array<double, 1> fourth{};
    require(renderBlock(0, first)
            && first == std::array<double, 3>{
                expected[0], expected[1], expected[2]}
            && renderBlock(3, fourth)
            && fourth == std::array<double, 1>{expected[3]},
        "first prepared blocks should leave the next update on partial one");
    require(session.updateEventValue("BridgeGain",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "serialized OscillatorBank should arm late overflow");
    std::array<double, 1> rejected{95};
    require(!renderBlock(4, rejected)
            && rejected == std::array<double, 1>{},
        "late failure should reject a serialized partial update atomically");
    require(session.updateEventValue("BridgeGain", 1.0,
                talas::expr::ValueDomain::Scalar),
        "serialized OscillatorBank should accept repaired gain");
    std::array<double, 1> retry{};
    require(renderBlock(4, retry)
            && retry == std::array<double, 1>{expected[4]},
        "retry should replace the same first partial after rollback");
    std::array<double, 1> tail{};
    require(renderBlock(5, tail)
            && tail == std::array<double, 1>{expected[5]},
        "later frequency changes should preserve the ordered partial phase");
    session.resetTransport();
    std::array<double, 3> restarted{};
    require(renderBlock(0, restarted) && restarted == first,
        "transport reset should clear the serialized oscillator bank");
}

void testSpectrumInRamFeedsPreparedSerializedOscillatorBank()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("source", "talas.spectrumInRam", {
            choiceParameter("pairFrequencies", "legacyHertz"),
            {"frequency", "100 hz"},
            {"level", "0.5"},
            {"timeIndex", "0"},
            resourceParameter("analysis", "Analysis/RAM"),
            {"analysisFrames", "1"},
            {"nbrPartials", "2"},
            {"firstPartial", "2"},
        }),
        node("bank", "talas.oscillatorBank",
            oscillatorBankParameters({
                resourceParameter("wavetable", "Flat")})),
    };
    document.graph.connections = {
        connection("source", "amplitudeOut", "bank", "amplitudeIn"),
        connection("source", "frequencyOut", "bank", "frequencyIn"),
        connection("bank", "audioOut", "out", "audioIn"),
    };
    talas::runtime::RenderSettings settings{1000.0, 3};
    settings.tableResources = {
        {"Analysis/RAM", {
            1.0, 1.0, 0.0,
            0.5, 2.0, 0.0,
            0.25, 3.0, 0.0,
        }},
        {"Flat", {1.0}},
    };
    const auto registry = talas::core::makeBuiltinNodeRegistry();
    const auto saved = talas::project::serializeProjectDocument(
        document, registry);
    const auto reopened = talas::project::parseProjectDocument(saved);
    require(reopened.ok()
            && talas::project::serializeProjectDocument(
                reopened.document, registry) == saved,
        "serialized SpectrumInRAM and OscillatorBank graph should reopen");
    const auto graph = compile(reopened.document, settings);
    const auto offline = talas::runtime::renderOffline(graph, 7);
    require(offline.ok(),
        "SpectrumInRAM should feed serialized bank offline");
    constexpr std::array<double, 7> expected{
        0.25, 0.375, 0.375, 0.375, 0.375, 0.375, 0.375};
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(),
        "SpectrumInRAM serial bank should prepare: "
            + std::string{session.error()});
    const auto renderPartitioned = [&](std::array<double, 7>& samples) {
        std::size_t offset = 0;
        for (const auto frames : {3U, 1U, 3U})
        {
            std::size_t allocations = 0;
            require(renderAndCount(session,
                        std::span{samples}.subspan(offset, frames),
                        allocations)
                    && allocations == 0,
                "SpectrumInRAM serialized bank callback should not allocate");
            offset += frames;
        }
    };
    std::array<double, 7> prepared{};
    renderPartitioned(prepared);
    for (std::size_t sample = 0; sample < expected.size(); ++sample)
    {
        requireNear(offline.mono[sample], expected[sample], 1.0e-12,
            "offline SpectrumInRAM serial bank sample");
        requireNear(prepared[sample], expected[sample], 1.0e-12,
            "prepared SpectrumInRAM serial bank sample");
    }
    session.resetTransport();
    std::array<double, 7> restarted{};
    renderPartitioned(restarted);
    require(restarted == prepared,
        "serial source and bank should restart together after transport reset");

    auto ambiguous = reopened.document;
    ambiguous.graph.connections.push_back(connection(
        "source", "spectrumOut", "bank", "spectrum"));
    talas::runtime::RealtimeRenderSession rejected(
        compile(ambiguous, settings));
    require(!rejected.ready(),
        "OscillatorBank should reject simultaneous Spectrum and serial inputs");
}

void testSyntheticSpectrumFromSoundsStreamsIntoPreparedOscillatorBank()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("amps", "talas.audioInput"),
        node("freqs", "talas.audioInput", {
            booleanParameter("channel1", false),
            booleanParameter("channel2", true)}),
        node("source", "talas.syntheticSpectrumFromSounds",
            syntheticSpectrumFromSoundsParameters()),
        node("bank", "talas.oscillatorBank",
            oscillatorBankParameters({
                resourceParameter("wavetable", "Quarter")})),
    };
    document.graph.connections = {
        connection("amps", "audioOut", "source", "amplitudes"),
        connection("freqs", "audioOut", "source", "frequenciesAndBandwidths"),
        connection("source", "amplitudeOut", "bank", "amplitudeIn"),
        connection("source", "frequencyOut", "bank", "frequencyIn"),
        connection("bank", "audioOut", "out", "audioIn"),
    };
    talas::runtime::RenderSettings settings{8.0, 3};
    settings.tableResources = {
        {"Quarter", {0.0, 1.0, 0.0, -1.0}}};
    settings.audioInputChannels = {
        {1, {0.5, 0.25, 1.0, 0.75, 1.0, 1.0}},
        {2, {1, 2, 2, 1, 1, 2}},
    };
    const auto registry = talas::core::makeBuiltinNodeRegistry();
    const auto saved = talas::project::serializeProjectDocument(
        document, registry);
    const auto reopened = talas::project::parseProjectDocument(saved);
    require(reopened.ok()
            && talas::project::serializeProjectDocument(
                reopened.document, registry) == saved,
        "serialized SyntheticSpectrumFromSounds graph should reopen");
    const auto graph = compile(reopened.document, settings);
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(),
        "serialized SyntheticSpectrumFromSounds should prepare: "
            + std::string{session.error()});
    constexpr std::array<float, 6> amplitudes{
        0.5F, 0.25F, 1.0F, 0.75F, 1.0F, 1.0F};
    constexpr std::array<float, 6> frequencies{
        1, 2, 2, 1, 1, 2};
    // Each oscillator advances its own phase by its partial's frequency.
    constexpr std::array<double, 6> expected{
        0.0, 0.25, 1.25, 0.0, -1.375, -1.5};
    const auto renderPartitioned = [&](std::array<double, 6>& output) {
        std::size_t offset = 0;
        for (const auto frames : {1U, 2U, 1U, 2U})
        {
            const std::array<const float*, 2> channels{
                amplitudes.data() + offset,
                frequencies.data() + offset};
            std::size_t allocations = 0;
            require(renderMonoInputAndCount(session,
                        {channels.data(), channels.size()},
                        std::span{output}.subspan(offset, frames),
                        allocations)
                    && allocations == 0,
                "serialized SyntheticSpectrumFromSounds callback should render without allocation");
            offset += frames;
        }
    };
    std::array<double, 6> prepared{};
    renderPartitioned(prepared);
    require(prepared == expected,
        "serialized SyntheticSpectrumFromSounds should preserve dynamic pairs across blocks");
    session.resetTransport();
    std::array<double, 6> restarted{};
    renderPartitioned(restarted);
    require(restarted == expected,
        "serialized source and bank should restart together");

    auto unsupportedMode = reopened.document;
    for (auto& node : unsupportedMode.graph.nodes)
        if (node.instanceId == "source")
            for (auto& parameter : node.parameters)
                if (parameter.parameterId == "logScale")
                    parameter.boolean = true;
    talas::runtime::RealtimeRenderSession rejected(
        compile(unsupportedMode, settings));
    require(!rejected.ready(),
        "serialized SyntheticSpectrumFromSounds should reject log-scale pairs without conversion");
}

void testSyntheticSpectrumFromArraySerializesPairsAndRollsBack()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("source", "talas.syntheticSpectrumFromArray",
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "2"},
                booleanParameter("sendBandwidths", false),
                {"envelope", "0.5"},
                textParameter("amplitudes", "1 0.5"),
                textParameter("frequencies", "1 2"),
            })),
        node("gain", "talas.constant", {{"value", "!BridgeGain"}}),
        node("first", "talas.vca"),
        node("second", "talas.vca"),
    };
    document.graph.connections = {
        connection("source", "amplitudeOut", "first", "audioIn"),
        connection("gain", "value", "first", "gain"),
        connection("first", "audioOut", "second", "audioIn"),
        connection("gain", "value", "second", "gain"),
        connection("second", "audioOut", "out", "audioIn"),
        connection("source", "frequencyOut", "out", "rightIn"),
    };
    talas::runtime::RenderSettings settings{8.0, 3};
    settings.eventValues = {{"BridgeGain", 1.0,
        talas::expr::ValueDomain::Scalar}};
    const auto registry = talas::core::makeBuiltinNodeRegistry();
    const auto saved = talas::project::serializeProjectDocument(
        document, registry);
    const auto reopened = talas::project::parseProjectDocument(saved);
    require(reopened.ok()
            && talas::project::serializeProjectDocument(
                reopened.document, registry) == saved,
        "serialized SyntheticSpectrumFromArray graph should save and reopen");
    const auto graph = compile(reopened.document, settings);
    const auto offline = talas::runtime::renderOffline(graph, 6);
    require(offline.ok()
            && offline.mono == std::vector<double>{
                0.5, 0.25, 0.5, 0.25, 0.5, 0.25}
            && offline.right == std::vector<double>{
                1, 2, 1, 2, 1, 2},
        "offline SyntheticSpectrumFromArray should emit ordered partial pairs");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(),
        "serialized SyntheticSpectrumFromArray should prepare: "
            + std::string{session.error()});
    const auto renderPartitioned = [&](std::array<double, 6>& left,
                                       std::array<double, 6>& right) {
        std::size_t offset = 0;
        for (const auto frames : {1U, 2U, 1U, 2U})
        {
            std::size_t allocations = 0;
            require(renderStereoAndCount(session,
                        std::span{left}.subspan(offset, frames),
                        std::span{right}.subspan(offset, frames),
                        allocations)
                    && allocations == 0,
                "serialized SyntheticSpectrumFromArray callback should not allocate");
            offset += frames;
        }
    };
    std::array<double, 6> left{};
    std::array<double, 6> right{};
    renderPartitioned(left, right);
    require(std::ranges::equal(left, offline.mono)
            && std::ranges::equal(right, offline.right),
        "prepared partial order should match offline across uneven callbacks");
    session.resetTransport();
    std::array<double, 6> restartedLeft{};
    std::array<double, 6> restartedRight{};
    renderPartitioned(restartedLeft, restartedRight);
    require(restartedLeft == left && restartedRight == right,
        "transport reset should restart SyntheticSpectrumFromArray partial phase");

    talas::runtime::RealtimeRenderSession rollbackSession(graph);
    require(rollbackSession.ready(),
        "serialized source rollback fixture should prepare");
    std::array<double, 3> advanceLeft{};
    std::array<double, 3> advanceRight{};
    std::size_t allocations = 0;
    require(renderStereoAndCount(rollbackSession, advanceLeft, advanceRight,
                allocations)
            && allocations == 0
            && advanceLeft == std::array<double, 3>{0.5, 0.25, 0.5}
            && advanceRight == std::array<double, 3>{1, 2, 1},
        "serialized source should advance to second partial before late failure");
    require(rollbackSession.updateEventValue("BridgeGain",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "late failure should arm downstream VCA overflow");
    std::array<double, 1> failedLeft{95};
    std::array<double, 1> failedRight{95};
    require(!renderStereoAndCount(rollbackSession, failedLeft, failedRight,
                allocations)
            && allocations == 0
            && failedLeft == std::array<double, 1>{}
            && failedRight == std::array<double, 1>{},
        "failed callback should clear both output channels atomically");
    require(rollbackSession.updateEventValue("BridgeGain", 1.0,
                talas::expr::ValueDomain::Scalar),
        "rollback retry should accept repaired gain");
    std::array<double, 1> retryLeft{};
    std::array<double, 1> retryRight{};
    require(renderStereoAndCount(rollbackSession, retryLeft, retryRight,
                allocations)
            && allocations == 0
            && retryLeft == std::array<double, 1>{0.25}
            && retryRight == std::array<double, 1>{2},
        "retry should replay second partial after source phase rollback: left="
            + std::to_string(retryLeft[0])
            + " right=" + std::to_string(retryRight[0])
            + " allocations=" + std::to_string(allocations));
}

void testSyntheticSpectrumFromArrayFeedsPreparedOscillatorBank()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("source", "talas.syntheticSpectrumFromArray",
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "2"},
                booleanParameter("sendBandwidths", false),
                {"envelope", "0.5"},
                textParameter("amplitudes", "1 0.5"),
                textParameter("frequencies", "1 2"),
            })),
        node("bank", "talas.oscillatorBank",
            oscillatorBankParameters({
                resourceParameter("wavetable", "Quarter")})),
    };
    document.graph.connections = {
        connection("source", "amplitudeOut", "bank", "amplitudeIn"),
        connection("source", "frequencyOut", "bank", "frequencyIn"),
        connection("bank", "audioOut", "out", "audioIn"),
    };
    talas::runtime::RenderSettings settings{8.0, 3};
    settings.tableResources = {{"Quarter", {0.0, 1.0, 0.0, -1.0}}};
    const auto graph = compile(document, settings);
    const auto offline = talas::runtime::renderOffline(graph, 7);
    require(offline.ok() && offline.mono.size() == 7
            && std::ranges::any_of(offline.mono,
                [](double sample) { return sample != 0.0; }),
        "offline array source should synthesize through the serialized bank");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(),
        "array source should feed prepared serial bank: "
            + std::string{session.error()});
    std::array<double, 7> prepared{};
    std::size_t offset = 0;
    for (const auto frames : {1U, 2U, 1U, 3U})
    {
        std::size_t allocations = 0;
        require(renderAndCount(session,
                    std::span{prepared}.subspan(offset, frames),
                    allocations)
                && allocations == 0,
            "array source and serial bank should render without allocation");
        offset += frames;
    }
    require(std::ranges::equal(prepared, offline.mono),
        "prepared serial bank should match offline array source across blocks");

    for (const auto mode : {"logScale", "sendBandwidths", "nbrPartials"})
    {
        auto unsupported = document;
        for (auto& candidate : unsupported.graph.nodes)
        {
            if (candidate.instanceId != "source")
                continue;
            for (auto& parameter : candidate.parameters)
            {
                if (parameter.parameterId != mode)
                    continue;
                if (parameter.parameterId == "nbrPartials")
                    parameter.expression = "3";
                else
                    parameter.boolean = true;
            }
        }
        const auto unsupportedGraph = compile(unsupported, settings);
        const auto offlineRejected = talas::runtime::renderOffline(
            unsupportedGraph, 3);
        talas::runtime::RealtimeRenderSession preparedRejected(
            unsupportedGraph);
        require(!offlineRejected.ok() && !preparedRejected.ready(),
            std::string{"serialized array source must reject unsupported "}
                + mode + " mode in both runtimes");
    }
}

void testRealtimeOscillatorBankMatchesWavetableAcrossIrregularPartitions()
{
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.tableResources.push_back({
        "Tables/C24Quarter", {0.0, 1.0, 0.0, -1.0}});
    const auto graph = compile(
        makeOscillatorBankRealtimeDocument(
            oscillatorBankParameters({
                {"nbrOscillators", "1"},
                {"bankSize", "4096"},
                resourceParameter(
                    "wavetable", "Tables/C24Quarter"),
            }),
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "1"},
                {"envelope", "1"},
                textParameter("amplitudes", "0.5"),
                textParameter("frequencies", "1"),
                textParameter("bandwidths", "0"),
            })),
        settings);
    const auto expected = talas::runtime::renderOffline(graph, 7);
    talas::runtime::RealtimeRenderSession session(graph);
    std::array<double, 7> actual{};
    constexpr std::array<std::size_t, 3> partitions{2, 1, 4};
    std::size_t offset = 0;
    for (const auto partition : partitions)
    {
        std::size_t allocations = 0;
        require(
            session.ready()
                && renderAndCount(
                    session,
                    std::span<double>{actual}.subspan(
                        offset, partition),
                    allocations)
                && allocations == 0,
            "C24 wavetable partition should render without allocation: "
                + std::string{session.error()});
        offset += partition;
    }
    require(
        expected.ok() && expected.mono.size() == actual.size(),
        "C24 wavetable offline authority should render");
    for (std::size_t frame = 0; frame < actual.size(); ++frame)
    {
        requireNear(
            actual[frame], expected.mono[frame], 0.0,
            "C24 wavetable partition parity");
    }
}

void testRealtimeOscillatorBankAdmitsMaximumPartialsWithoutAllocations()
{
    std::string amplitudes;
    std::string frequencies;
    std::string bandwidths;
    for (std::size_t partial = 0; partial < 4096; ++partial)
    {
        if (partial != 0)
        {
            amplitudes += ' ';
            frequencies += ' ';
            bandwidths += ' ';
        }
        amplitudes += "0";
        frequencies += "1";
        bandwidths += "0";
    }
    const auto graph = compile(
        makeOscillatorBankRealtimeDocument(
            oscillatorBankParameters({
                {"nbrOscillators", "4096"},
                {"bankSize", "4096"},
            }),
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "4096"},
                {"envelope", "1"},
                textParameter("amplitudes", std::move(amplitudes)),
                textParameter("frequencies", std::move(frequencies)),
                textParameter("bandwidths", std::move(bandwidths)),
            })),
        {8.0, 1});
    talas::runtime::RealtimeRenderSession session(graph);
    std::array<double, 1> output{1.0};
    std::size_t allocations = 0;
    require(
        session.ready()
            && renderAndCount(session, output, allocations)
            && allocations == 0
            && output[0] == 0.0,
        "C24 maximum 4096-partial callback should remain bounded and allocation-free: "
            + std::string{session.error()});
}

void testRealtimeOscillatorBankRejectsNyquistAndRollsBackOverflow()
{
    const auto nyquistGraph = compile(
        makeOscillatorBankRealtimeDocument(
            oscillatorBankParameters({
                {"nbrOscillators", "1"},
                {"bankSize", "1"},
            }),
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "1"},
                {"envelope", "1"},
                textParameter("amplitudes", "1"),
                textParameter("frequencies", "4"),
                textParameter("bandwidths", "0"),
            })),
        {8.0, 1});
    talas::runtime::RealtimeRenderSession nyquist(nyquistGraph);
    std::array<double, 1> rejected{1.0};
    std::size_t allocations = 0;
    require(
        nyquist.ready()
            && !renderAndCount(nyquist, rejected, allocations)
            && allocations == 0
            && rejected[0] == 0.0,
        "C24 exact Nyquist frequency should reject atomically");

    auto document = makeOscillatorBankRealtimeDocument(
        oscillatorBankParameters(),
        syntheticSpectrumFromArrayParameters({
            {"envelope", "0"},
            textParameter("amplitudes", "1.3e308 1.3e308"),
            textParameter("frequencies", "1 1"),
            textParameter("bandwidths", "0 0"),
        }));
    document.graph.nodes.push_back(node(
        "c24Envelope", "talas.constant", {
            {"value", "!C24RollbackEnvelope"},
        }));
    document.graph.connections.push_back(connection(
        "c24Envelope", "value", "spectrum", "envelope"));
    auto settings = talas::runtime::RenderSettings{8.0, 1};
    settings.eventValues.push_back({
        "C24RollbackEnvelope", 1.0,
        talas::expr::ValueDomain::Scalar});
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    std::array<double, 1> first{};
    require(
        candidate.ready()
            && renderAndCount(candidate, first, allocations)
            && allocations == 0
            && first[0] == 0.0,
        "C24 rollback fixture should render its zero-phase first frame");
    rejected[0] = 1.0;
    require(
        !renderAndCount(candidate, rejected, allocations)
            && allocations == 0
            && rejected[0] == 0.0,
        "C24 overflowing later partial sum should publish no audio");
    require(
        candidate.updateEventValue(
            "C24RollbackEnvelope",
            1.0e-308,
            talas::expr::ValueDomain::Scalar),
        "C24 failed callback should accept a finite recovery envelope");

    auto referenceSettings = settings;
    referenceSettings.eventValues.front().value = 1.0e-308;
    const auto referenceGraph = compile(document, referenceSettings);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    std::array<double, 1> referenceFirst{};
    std::array<double, 1> expectedRetry{};
    std::array<double, 1> actualRetry{};
    require(
        reference.ready()
            && renderAndCount(
                reference, referenceFirst, allocations)
            && allocations == 0
            && renderAndCount(
                reference, expectedRetry, allocations)
            && allocations == 0
            && renderAndCount(
                candidate, actualRetry, allocations)
            && allocations == 0,
        "C24 recovered and reference callbacks should render");
    requireNear(
        actualRetry[0], expectedRetry[0], 0.0,
        "C24 failed callback should restore absolute-frame state exactly");
}

void testRealtimeOscillatorBankRollsBackWholeCallbackAndAcceptsCheckpointedNeighbors()
{
    auto segmentedDocument = makeOscillatorBankRealtimeDocument(
        oscillatorBankParameters(),
        syntheticSpectrumFromArrayParameters({
            {"envelope", "1e-308"},
            textParameter("amplitudes", "1.3e308 1.3e308"),
            textParameter("frequencies", "1 1"),
            textParameter("bandwidths", "0 0"),
        }));
    segmentedDocument.graph.nodes.push_back(node(
        "c24SegmentEnvelope", "talas.constant", {
            {"value", "!C24SegmentEnvelope"},
        }));
    segmentedDocument.graph.connections.push_back(connection(
        "c24SegmentEnvelope", "value", "spectrum", "envelope"));
    auto segmentedSettings = talas::runtime::RenderSettings{8.0, 4};
    segmentedSettings.eventValues.push_back({
        "C24SegmentEnvelope", 1.0e-308,
        talas::expr::ValueDomain::Scalar});
    const auto segmentedGraph = compile(
        segmentedDocument, segmentedSettings);
    talas::runtime::RealtimeRenderSession segmentedCandidate(
        segmentedGraph);
    talas::runtime::RealtimeRenderSession segmentedReference(
        segmentedGraph);
    require(
        segmentedCandidate.ready()
            && segmentedReference.ready()
            && segmentedCandidate.scheduleEventValue(
                "C24SegmentEnvelope",
                1.0,
                talas::expr::ValueDomain::Scalar,
                2),
        "C24 segmented rollback fixture should prepare and schedule a later failure");
    std::array<double, 4> failed{1.0, 1.0, 1.0, 1.0};
    std::size_t allocations = 0;
    require(
        !renderAndCount(
            segmentedCandidate, failed, allocations)
            && allocations == 0
            && failed == std::array<double, 4>{},
        "C24 later-segment failure should publish no callback audio");
    require(
        segmentedCandidate.updateEventValue(
            "C24SegmentEnvelope",
            1.0e-308,
            talas::expr::ValueDomain::Scalar),
        "C24 segmented rollback control should recover after failure");
    std::array<double, 4> segmentedActual{};
    std::array<double, 4> segmentedExpected{};
    require(
        renderAndCount(
            segmentedCandidate, segmentedActual, allocations)
            && allocations == 0
            && renderAndCount(
                segmentedReference, segmentedExpected, allocations)
            && allocations == 0
            && segmentedActual == segmentedExpected,
        "C24 later-segment failure should restore the absolute-frame counter");

    auto downstreamDocument = makeOscillatorBankRealtimeDocument(
        oscillatorBankParameters({
            {"nbrOscillators", "1"},
            {"bankSize", "1"},
        }),
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "1"},
            {"envelope", "1"},
            textParameter("amplitudes", "2"),
            textParameter("frequencies", "1"),
            textParameter("bandwidths", "0"),
        }));
    downstreamDocument.graph.nodes.push_back(node(
        "c24Level", "talas.level", {
            {"left", "1"},
            {"right", "0"},
            booleanParameter("noGain", false),
        }));
    downstreamDocument.graph.nodes.push_back(node(
        "c24LevelControl", "talas.constant", {
            {"value", "!C24DownstreamLevel"},
        }));
    downstreamDocument.graph.connections.erase(
        std::remove_if(
            downstreamDocument.graph.connections.begin(),
            downstreamDocument.graph.connections.end(),
            [](const talas::core::Connection& candidate) {
                return candidate.fromNode == "bank"
                    && candidate.toNode == "out";
            }),
        downstreamDocument.graph.connections.end());
    downstreamDocument.graph.connections.push_back(connection(
        "bank", "audioOut", "c24Level", "audioIn"));
    downstreamDocument.graph.connections.push_back(connection(
        "c24LevelControl", "value", "c24Level", "left"));
    downstreamDocument.graph.connections.push_back(connection(
        "c24Level", "leftOut", "out", "audioIn"));
    auto downstreamSettings = talas::runtime::RenderSettings{8.0, 4};
    downstreamSettings.eventValues.push_back({
        "C24DownstreamLevel", 1.0,
        talas::expr::ValueDomain::Scalar});
    const auto downstreamGraph = compile(
        downstreamDocument, downstreamSettings);
    talas::runtime::RealtimeRenderSession downstreamCandidate(
        downstreamGraph);
    talas::runtime::RealtimeRenderSession downstreamReference(
        downstreamGraph);
    require(
        downstreamCandidate.ready()
            && downstreamReference.ready()
            && downstreamCandidate.scheduleEventValue(
                "C24DownstreamLevel",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar,
                2),
        "C24 downstream rollback fixture should prepare and segment");
    failed.fill(1.0);
    require(
        !renderAndCount(
            downstreamCandidate, failed, allocations)
            && allocations == 0
            && failed == std::array<double, 4>{},
        "C24 downstream failure should publish no callback audio");
    require(
        downstreamCandidate.updateEventValue(
            "C24DownstreamLevel",
            1.0,
            talas::expr::ValueDomain::Scalar),
        "C24 downstream rollback control should recover after failure");
    std::array<double, 4> downstreamActual{};
    std::array<double, 4> downstreamExpected{};
    require(
        renderAndCount(
            downstreamCandidate, downstreamActual, allocations)
            && allocations == 0
            && renderAndCount(
                downstreamReference, downstreamExpected, allocations)
            && allocations == 0
            && downstreamActual == downstreamExpected,
        "C24 downstream failure should restore Oscillator Bank state");

    auto successorDocument = makeOscillatorBankRealtimeDocument();
    successorDocument.graph.nodes.push_back(node(
        "c24LowPassGate", "talas.lowPassGate", lowPassGateParameters()));
    successorDocument.graph.connections.erase(
        std::remove_if(
            successorDocument.graph.connections.begin(),
            successorDocument.graph.connections.end(),
            [](const talas::core::Connection& candidate) {
                return candidate.fromNode == "bank"
                    && candidate.toNode == "out";
            }),
        successorDocument.graph.connections.end());
    successorDocument.graph.connections.push_back(connection(
        "bank", "audioOut", "c24LowPassGate", "audioIn"));
    successorDocument.graph.connections.push_back(connection(
        "c24LowPassGate", "audioOut", "out", "audioIn"));
    const auto successorGraph = compile(
        successorDocument, {8.0, 4});
    talas::runtime::RealtimeRenderSession successor(successorGraph);
    require(
        successor.ready(),
        "C103 Low-Pass Gate should provide dedicated checkpoint coverage as an Oscillator Bank successor");
}

void testRealtimeOscillatorBankRejectsForgedPreparedAuthority()
{
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.tableResources.push_back({
        "Tables/C24", {0.0, 1.0, 0.0, -1.0}});
    const auto compiled = compile(
        makeOscillatorBankRealtimeDocument(
            oscillatorBankParameters({
                resourceParameter("wavetable", "Tables/C24"),
            })),
        settings);
    const auto requireRejected = [](
                                     talas::runtime::RuntimePlan plan,
                                     talas::runtime::RenderSettings settings,
                                     std::string_view context) {
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), std::move(settings)});
        require(
            !session.ready(),
            std::string{context}
                + " should reject forged C24 Oscillator Bank authority");
    };
    const auto mutateBank = [&](auto mutate,
                                std::string_view context) {
        auto plan = compiled.plan();
        const auto bank = std::ranges::find(
            plan.steps,
            std::string_view{"talas.oscillatorBank"},
            &talas::runtime::CompileStep::typeId);
        require(
            bank != plan.steps.end(),
            "C24 forged-authority fixture should expose Oscillator Bank");
        mutate(plan, *bank);
        requireRejected(
            std::move(plan), compiled.renderSettings(), context);
    };

    mutateBank(
        [](auto&, auto& bank) {
            bank.preparedRealtimeSupport =
                talas::core::ExecutionSupport::Supported;
        },
        "C24 forged full support");
    mutateBank(
        [](auto&, auto& bank) { bank.supportsReset = false; },
        "C24 forged reset contract");
    mutateBank(
        [](auto&, auto& bank) { ++bank.eventValueScopeId; },
        "C24 forged Event Value scope");
    mutateBank(
        [](auto&, auto& bank) {
            bank.cumulativeOutputLatencyFrames = 1;
        },
        "C24 forged output latency");
    mutateBank(
        [](auto&, auto& bank) {
            bank.preparedSpectralFrameSize = 1024;
        },
        "C24 forged native spectral frame authority");
    mutateBank(
        [](auto&, auto& bank) {
            bank.parameters[0].domain =
                talas::expr::ValueDomain::Hertz;
        },
        "C24 forged oscillator-count domain");
    mutateBank(
        [](auto&, auto& bank) {
            bank.parameters[0].expression.reset();
        },
        "C24 missing oscillator-count expression");
    mutateBank(
        [](auto&, auto& bank) {
            bank.parameters[2].value = 1.0;
        },
        "C24 forged resource value");
    mutateBank(
        [](auto&, auto& bank) {
            std::swap(bank.parameters[0], bank.parameters[1]);
        },
        "C24 reordered parameters");
    mutateBank(
        [](auto& plan, auto& bank) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == bank.nodeId
                        && buffer.portId == "audioOut"
                        && buffer.scopeId == bank.scopeId;
                });
            require(
                output != plan.buffers.end(),
                "C24 duplicate-output fixture should expose audioOut");
            plan.buffers.push_back(*output);
        },
        "C24 duplicate output ownership");
    mutateBank(
        [](auto& plan, auto& bank) {
            auto& spectrum = bank.inputs.front();
            auto forged = plan.buffers[spectrum.bufferIndex];
            forged.portId = "forgedSpectrumOut";
            spectrum.sourcePortId = forged.portId;
            spectrum.bufferIndex = plan.buffers.size();
            plan.buffers.push_back(std::move(forged));
        },
        "C24 unproduced Spectrum buffer");
    mutateBank(
        [](auto& plan, auto& bank) {
            const auto source = std::ranges::find_if(
                plan.steps,
                [&](const talas::runtime::CompileStep& candidate) {
                    return candidate.nodeId
                            == bank.inputs.front().sourceNodeId
                        && candidate.scopeId
                            == bank.inputs.front().sourceScopeId;
                });
            require(
                source != plan.steps.end(),
                "C24 latency fixture should expose Spectrum source");
            source->resolvedLatencyFrames = 1;
            source->cumulativeInputLatencyFrames = 0;
            source->cumulativeOutputLatencyFrames = 1;
            bank.inputLatencyFrames[0] = 1;
            bank.cumulativeInputLatencyFrames = 1;
            bank.cumulativeOutputLatencyFrames = 1;
        },
        "C24 coherently forged Spectrum ancestry latency");

    const auto mutateSpectrum = [&](auto mutate,
                                    std::string_view context) {
        auto plan = compiled.plan();
        const auto spectrum = std::ranges::find(
            plan.steps,
            std::string_view{"talas.syntheticSpectrumFromArray"},
            &talas::runtime::CompileStep::typeId);
        require(
            spectrum != plan.steps.end(),
            "C24 forged-source fixture should expose Synthetic Spectrum");
        mutate(plan, *spectrum);
        requireRejected(
            std::move(plan), compiled.renderSettings(), context);
    };
    mutateSpectrum(
        [](auto&, auto& spectrum) {
            spectrum.preparedRealtimeSupport =
                talas::core::ExecutionSupport::Supported;
        },
        "C24 forged Spectrum source support");
    mutateSpectrum(
        [](auto&, auto& spectrum) {
            spectrum.supportsReset = false;
        },
        "C24 forged Spectrum source reset contract");
    mutateSpectrum(
        [](auto&, auto& spectrum) {
            std::swap(
                spectrum.parameters[0],
                spectrum.parameters[1]);
        },
        "C24 reordered Spectrum source parameters");
    mutateSpectrum(
        [](auto& plan, auto& spectrum) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == spectrum.nodeId
                        && buffer.scopeId == spectrum.scopeId
                        && buffer.portId == "spectrumOut";
                });
            require(
                output != plan.buffers.end(),
                "C24 duplicate Spectrum output fixture should expose spectrumOut");
            plan.buffers.push_back(*output);
        },
        "C24 duplicate Spectrum source output ownership");

    auto duplicateSettings = compiled.renderSettings();
    duplicateSettings.tableResources.push_back(
        duplicateSettings.tableResources.front());
    requireRejected(
        compiled.plan(),
        std::move(duplicateSettings),
        "C24 duplicate wavetable identity");
}

void testRealtimeFormantBankMatchesOfflineAcrossPartitionsAndReset()
{
    const auto graph = compile(
        makeFormantBankRealtimeDocument(
            formantBankParameters({
                {"frequency", "1 hz"},
                {"nbrFormants", "2"},
                {"bankSize", "1"},
            }),
            syntheticSpectrumFromArrayParameters({
                {"envelope", "1"},
                textParameter("amplitudes", "1 -0.25"),
                textParameter("frequencies", "1 2"),
                textParameter("bandwidths", "0 0"),
            })),
        {16.0, 5});
    const auto expected = talas::runtime::renderOffline(graph, 8);
    talas::runtime::RealtimeRenderSession session(graph);
    std::array<double, 3> first{};
    std::array<double, 5> second{};
    std::array<double, 3> reset{};
    std::size_t allocations = 0;
    require(
        expected.ok()
            && session.ready()
            && renderAndCount(session, first, allocations)
            && allocations == 0
            && renderAndCount(session, second, allocations)
            && allocations == 0,
        "C25 Formant Bank should prepare and render irregular partitions: "
            + std::string{session.error()});
    for (std::size_t frame = 0; frame < first.size(); ++frame)
    {
        requireNear(
            first[frame], expected.mono[frame], 0.0,
            "C25 first Formant Bank partition");
    }
    for (std::size_t frame = 0; frame < second.size(); ++frame)
    {
        requireNear(
            second[frame], expected.mono[first.size() + frame], 0.0,
            "C25 second Formant Bank partition");
    }
    session.resetTransport();
    require(
        renderAndCount(session, reset, allocations)
            && allocations == 0
            && reset == first,
        "C25 Formant Bank reset should restore exact positive-zero phases");
}

