void testSpectrumLinearToLogConvertsAndRoundTripsOfflineAndPrepared()
{
    for (const auto track : {std::size_t{1}, std::size_t{2}})
    {
        for (const auto roundTrip : {false, true})
        {
            const auto document =
                makeSpectrumLinearToLogTrackSelectorDocument(
                    track, roundTrip);
            const auto saved = talas::project::serializeProjectDocument(
                document, talas::core::makeBuiltinNodeRegistry());
            const auto reopened = talas::project::parseProjectDocument(saved);
            require(reopened.ok()
                        && talas::project::serializeProjectDocument(
                               reopened.document,
                               talas::core::makeBuiltinNodeRegistry()) == saved,
                "SpectrumLinearToLog Sound should save and reopen byte-stably");
            const auto graph = compile(reopened.document, {8000.0, 5});
            const auto offline = talas::runtime::renderOffline(graph, 5);
            require(offline.ok() && offline.mono.size() == 5
                        && offline.right.size() == 5,
                "SpectrumLinearToLog should render both selected partials");
            const auto expectedAmplitude = track == 1 ? 0.5 : 0.25;
            const auto expectedFrequency = roundTrip
                ? (track == 1 ? 440.0 : 880.0)
                : (track == 1 ? 69.0 : 81.0);
            for (std::size_t frame = 0; frame < 5; ++frame)
            {
                requireNear(offline.mono[frame], expectedAmplitude,
                    1.0e-12,
                    "SpectrumLinearToLog should preserve partial amplitude");
                requireNear(offline.right[frame], expectedFrequency,
                    1.0e-12,
                    "SpectrumLinearToLog should convert or round-trip each frequency");
            }

            talas::runtime::RealtimeRenderSession prepared(graph);
            require(prepared.ready(), std::string{prepared.error()});
            std::array<double, 2> firstLeft{};
            std::array<double, 2> firstRight{};
            std::array<double, 3> secondLeft{};
            std::array<double, 3> secondRight{};
            std::size_t allocations = 0;
            require(renderStereoAndCount(prepared,
                        firstLeft, firstRight, allocations)
                    && allocations == 0,
                "SpectrumLinearToLog first prepared callback should not allocate");
            require(renderStereoAndCount(prepared,
                        secondLeft, secondRight, allocations)
                    && allocations == 0,
                "SpectrumLinearToLog second prepared callback should not allocate");
            for (std::size_t frame = 0; frame < 5; ++frame)
            {
                const auto left = frame < 2 ? firstLeft[frame]
                    : secondLeft[frame - 2];
                const auto right = frame < 2 ? firstRight[frame]
                    : secondRight[frame - 2];
                requireNear(left, offline.mono[frame], 1.0e-12,
                    "SpectrumLinearToLog prepared amplitude should match offline");
                requireNear(right, offline.right[frame], 1.0e-12,
                    "SpectrumLinearToLog prepared frequency should match offline");
            }
        }
    }

    const auto invalid = compile(
        makeSpectrumLinearToLogTrackSelectorDocument(
            1, false, "0 880"),
        {8000.0, 2});
    const auto offlineFailure = talas::runtime::renderOffline(invalid, 2);
    require(!offlineFailure.ok() && offlineFailure.mono.empty()
                && std::ranges::any_of(
                    offlineFailure.diagnostics,
                    [](const auto& diagnostic) {
                        return diagnostic.nodeId == "log";
                    }),
        "SpectrumLinearToLog should reject a zero-Hertz partial");
    talas::runtime::RealtimeRenderSession preparedFailure(invalid);
    require(preparedFailure.ready(),
        std::string{preparedFailure.error()});
    std::array<double, 2> left{17.0, 17.0};
    std::array<double, 2> right{19.0, 19.0};
    std::size_t allocations = 0;
    const auto rendered = renderStereoAndCount(
        preparedFailure, left, right, allocations);
    require(!rendered,
        "SpectrumLinearToLog prepared render should reject zero Hertz");
    require(allocations == 0,
        "SpectrumLinearToLog rejected callback should not allocate");
    require(left == std::array<double, 2>{}
                && right == std::array<double, 2>{},
        "SpectrumLinearToLog rejected callback should publish silence");
}

