void testRealtimeSessionRejectsMissingSpectrumSourceAuthority()
{
    talas::runtime::RuntimePlan plan;
    plan.steps = {
        {
            "fundamental",
            "talas.spectrumFundamental",
            {{"spectrumIn", "source", "spectrumOut", 0}},
            {},
        },
        {
            "out",
            "talas.audioOutput",
            {{"audioIn", "fundamental", "leftOut", 1}, {"rightIn", "fundamental", "rightOut", 2}},
            {},
        },
    };
    plan.buffers = {
        {"source", "spectrumOut", talas::core::PortType::Spectrum, 3},
        {"fundamental", "leftOut", talas::core::PortType::Audio, 3},
        {"fundamental", "rightOut", talas::core::PortType::Audio, 3},
    };
    plan.outputBufferIndex = 1;
    plan.rightOutputBufferIndex = 2;
    plan.outputBufferIndices = {1, 2};
    talas::runtime::PreparedRuntimeGraph graph{std::move(plan), {4.0, 3}};
    talas::runtime::RealtimeRenderSession session(graph);
    require(
        !session.ready()
            && session.error().find("exact input source step")
                != std::string_view::npos,
        "a hand-built Spectrum plan must not omit canonical source-step authority");
}

