    document.graph.connections.push_back(connection("spacing", "value", "shape", "spacing"));
    document.graph.connections.push_back(connection("scale", "value", "shape", "scale"));
    auto graph = compile(document, std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 6);
    require(expected.ok(), "offline connected SpectralShape reference should render");
    requireNear(expected.mono[0], 1.0, 1.0e-12, "connected SpectralShape should override amplitude scale");
    requireNear(expected.right[0], 225.0, 1.0e-12, "connected SpectralShape should override frequency and spacing");
