void testSpectrumInRamSerializesPartialPairsWithoutAllocations()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("source", "talas.spectrumInRam", {
            choiceParameter("pairFrequencies", "legacyHertz"),
            {"frequency", "100 hz"},
            {"level", "0.5"},
            {"timeIndex", "0"},
            resourceParameter("analysis", "Analysis/RAM"),
            {"analysisFrames", "1"},
            {"nbrPartials", "2"},
            {"firstPartial", "2"},
        }),
    };
    document.graph.connections = {
        connection("source", "amplitudeOut", "out", "audioIn"),
        connection("source", "frequencyOut", "out", "rightIn"),
    };
    talas::runtime::RenderSettings settings{1000.0, 3};
    settings.tableResources = {{"Analysis/RAM", {
        1.0, 1.0, 0.0,
        0.5, 2.0, 0.0,
        0.25, 3.0, 0.0,
    }}};
    const auto registry = talas::core::makeBuiltinNodeRegistry();
    const auto saved = talas::project::serializeProjectDocument(
        document, registry);
    const auto reopened = talas::project::parseProjectDocument(saved);
    require(reopened.ok()
            && talas::project::serializeProjectDocument(
                reopened.document, registry) == saved,
        "serialized SpectrumInRAM graph should save and reopen byte-stably");
    const auto graph = compile(reopened.document, settings);
    const auto offline = talas::runtime::renderOffline(graph, 7);
    require(offline.ok()
            && offline.mono == std::vector<double>{
                0.25, 0.125, 0.25, 0.125, 0.25, 0.125, 0.25}
            && offline.right == std::vector<double>{
                200, 300, 200, 300, 200, 300, 200},
        "offline SpectrumInRAM should serialize the selected partial range");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(),
        "serialized SpectrumInRAM should prepare: "
            + std::string{session.error()});
    const auto renderPartitioned = [&](std::array<double, 7>& left,
                                       std::array<double, 7>& right) {
        std::size_t offset = 0;
        for (const auto frames : {3U, 1U, 3U})
        {
            std::size_t allocations = 0;
            require(renderStereoAndCount(session,
                        std::span{left}.subspan(offset, frames),
                        std::span{right}.subspan(offset, frames),
                        allocations)
                    && allocations == 0,
                "serialized SpectrumInRAM callback should not allocate");
            offset += frames;
        }
    };
    std::array<double, 7> left{};
    std::array<double, 7> right{};
    renderPartitioned(left, right);
    require(std::ranges::equal(left, offline.mono)
            && std::ranges::equal(right, offline.right),
        "prepared SpectrumInRAM pair order should match offline across callbacks");
    session.resetTransport();
    std::array<double, 7> restartedLeft{};
    std::array<double, 7> restartedRight{};
    renderPartitioned(restartedLeft, restartedRight);
    require(restartedLeft == left && restartedRight == right,
        "transport reset should restart SpectrumInRAM at the first partial");
}

void testSpectrumInRamSerializedPhaseRollsBackAfterLateFailure()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("source", "talas.spectrumInRam", {
            choiceParameter("pairFrequencies", "legacyHertz"),
            {"frequency", "100 hz"},
            {"level", "0.5"},
            {"timeIndex", "0"},
            resourceParameter("analysis", "Analysis/RAM"),
            {"analysisFrames", "1"},
            {"nbrPartials", "2"},
        }),
        node("gain", "talas.constant", {{"value", "!BridgeGain"}}),
        node("first", "talas.vca"),
        node("second", "talas.vca"),
    };
    document.graph.connections = {
        connection("source", "amplitudeOut", "first", "audioIn"),
        connection("gain", "value", "first", "gain"),
        connection("first", "audioOut", "second", "audioIn"),
        connection("gain", "value", "second", "gain"),
        connection("second", "audioOut", "out", "audioIn"),
        connection("source", "frequencyOut", "out", "rightIn"),
    };
    talas::runtime::RenderSettings settings{1000.0, 3};
    settings.tableResources = {{"Analysis/RAM", {
        0.5, 2.0, 0.0,
        0.25, 3.0, 0.0,
    }}};
    settings.eventValues = {{"BridgeGain", 1.0,
        talas::expr::ValueDomain::Scalar}};
    talas::runtime::RealtimeRenderSession session(
        compile(document, settings));
    require(session.ready(),
        "serialized SpectrumInRAM rollback graph should prepare: "
            + std::string{session.error()});
    std::array<double, 3> firstLeft{};
    std::array<double, 3> firstRight{};
    std::size_t allocations = 0;
    require(renderStereoAndCount(session, firstLeft, firstRight,
                allocations)
            && allocations == 0
            && firstLeft == std::array<double, 3>{
                0.25, 0.125, 0.25}
            && firstRight == std::array<double, 3>{
                200, 300, 200},
        "first SpectrumInRAM block should leave phase at second partial");
    require(session.updateEventValue("BridgeGain",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "serialized SpectrumInRAM rollback should arm late overflow");
    std::array<double, 1> failedLeft{95};
    std::array<double, 1> failedRight{95};
    require(!renderStereoAndCount(session, failedLeft, failedRight,
                allocations)
            && allocations == 0
            && failedLeft == std::array<double, 1>{}
            && failedRight == std::array<double, 1>{},
        "late failure should reject serialized SpectrumInRAM output atomically");
    require(session.updateEventValue("BridgeGain", 1.0,
                talas::expr::ValueDomain::Scalar),
        "serialized SpectrumInRAM rollback should accept repaired gain");
    std::array<double, 1> retryLeft{};
    std::array<double, 1> retryRight{};
    require(renderStereoAndCount(session, retryLeft, retryRight,
                allocations)
            && allocations == 0
            && retryLeft == std::array<double, 1>{0.125}
            && retryRight == std::array<double, 1>{300},
        "retry should replay the second partial after rollback");
}

