void testC60SpectrumOnDiskEmptyTransactionsResolveDefaultsAndAdvanceOnce()
{
    talas::runtime::RenderSettings settings{1000.0, 3};
    settings.tableResources.push_back({"Analysis/Disk", {
        0.2, 1.0, 0.1,
        0.4, 2.0, 0.2,
        0.6, 3.0, 0.3,
        0.8, 1.5, 0.15,
        1.0, 2.5, 0.25,
        1.2, 3.5, 0.35,
    }});
    auto document = makeSpectrumOnDiskTrackSelectorDocument({
        resourceParameter("fileName", "Analysis/Disk"),
        {"analysisFrames", "2"},
        {"analysisFrequency", "125 hz"},
        {"rateScale", "1"},
    });
    const auto selector = std::ranges::find(
        document.graph.nodes,
        std::string_view{"selector"},
        &talas::project::ProjectNode::instanceId);
    require(
        selector != document.graph.nodes.end(),
        "C60 empty-transaction fixture should contain selector authority");
    const auto track = std::ranges::find(
        selector->parameters,
        std::string_view{"track"},
        &talas::project::ProjectParameterExpression::parameterId);
    require(
        track != selector->parameters.end(),
        "C60 empty-transaction fixture should contain selector track");
    track->expression = "2";
    document.graph.nodes.push_back(node(
        "firstPartial", "talas.constant", {{"value", "2"}}));
    document.graph.connections.push_back(connection(
        "firstPartial", "value", "source", "firstPartial"));
    const auto graph = compile(document, std::move(settings));

    talas::runtime::OfflineRenderSession offline(graph);
    const auto offlineEmpty = offline.render(0);
    const auto offlineAfterEmpty = offline.render(3);
    require(
        offlineEmpty.ok() && offlineEmpty.mono.empty()
            && offlineAfterEmpty.ok(),
        "C60 offline empty transaction should resolve defaults and publish no samples");

    talas::runtime::RealtimeRenderSession realtime(graph);
    require(
        realtime.ready(),
        "C60 empty-transaction fixture should prepare: "
            + std::string{realtime.error()});
    std::size_t allocations = 0;
    require(
        renderEmptyStereoAndCount(realtime, allocations)
            && allocations == 0,
        "C60 prepared empty default transaction should advance without allocation");
    std::array<double, 3> left{};
    std::array<double, 3> right{};
    require(
        renderStereoAndCount(realtime, left, right, allocations)
            && allocations == 0,
        "C60 prepared transaction after empty default resolution should render without allocation");
    for (std::size_t frame = 0; frame < left.size(); ++frame)
    {
        requireNear(
            left[frame], offlineAfterEmpty.mono[frame], 0.0,
            "C60 empty transaction should preserve exact offline/prepared amplitude parity");
        requireNear(
            right[frame], offlineAfterEmpty.right[frame], 0.0,
            "C60 empty transaction should preserve exact offline/prepared pitch parity");
        requireNear(
            left[frame], 1.2, 1.0e-12,
            "C60 empty transaction should advance exactly once to the final-frame tail");
        requireNear(
            right[frame], 437.5, 1.0e-12,
            "C60 empty transaction should use analysis metadata after advancing");
    }

    realtime.resetTransport();
    require(
        renderStereoAndCount(realtime, left, right, allocations)
            && allocations == 0
            && left.front() == 0.6
            && right.front() == 375.0,
        "C60 reset should restore empty-transaction defaults and initial scan state");
}

