void testRealtimeSessionOwnsMaximumGenericSourceSampleAndResetsPlayback()
{
    std::vector<double> samples(1'048'576, 0.0);
    samples[0] = 2.0;
    samples[1] = -4.0;
    samples[2] = 6.0;
    talas::runtime::RenderSettings settings{8.0, 4};
    settings.tableResources = {{"Samples/C33", std::move(samples)}};
    auto graph = compile(
        makeGenericSourceRamSampleOutputDocument(),
        std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 4);
    require(expected.ok(), "offline maximum C33 reference should render");
    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        "exact-1048576 C33 RAM sample should prepare");

    auto& callerSettings = const_cast<talas::runtime::RenderSettings&>(
        graph.renderSettings());
    std::ranges::fill(
        callerSettings.tableResources.front().samples,
        std::numeric_limits<double>::quiet_NaN());

    std::array<double, 4> leftFirst{};
    std::array<double, 4> rightFirst{};
    std::array<double, 4> leftReset{};
    std::array<double, 4> rightReset{};
    std::size_t allocations = 0;
    require(
        renderStereoAndCount(
            session, leftFirst, rightFirst, allocations),
        "maximum C33 render should use its owned sample copy");
    require(allocations == 0, "maximum C33 render should not allocate");
    session.resetTransport();
    require(
        renderStereoAndCount(
            session, leftReset, rightReset, allocations),
        "reset maximum C33 render should succeed");
    require(allocations == 0, "reset maximum C33 render should not allocate");
    for (std::size_t frame = 0; frame < leftFirst.size(); ++frame)
    {
        requireNear(
            leftFirst[frame], expected.mono[frame], 1.0e-12,
            "maximum C33 owned-copy render should match offline");
        requireNear(
            leftReset[frame], leftFirst[frame], 1.0e-12,
            "C33 reset should restore pristine playback");
        requireNear(
            rightReset[frame], rightFirst[frame], 1.0e-12,
            "C33 reset should restore pristine right playback");
    }
}

void testRealtimeSessionRejectsInvalidGenericSourceResourcesAndModes()
{
    const auto prepare = [] (
        std::vector<talas::runtime::TableResource> tables,
        std::string sourceMode = "sample",
        std::string sampleId = "Samples/C33",
        bool left = true,
        bool right = true) {
        talas::runtime::RenderSettings settings{8.0, 4};
        settings.tableResources = std::move(tables);
        return compile(
            makeGenericSourceRamSampleOutputDocument({
                textParameter("source", std::move(sourceMode)),
                booleanParameter("leftChannel", left),
                booleanParameter("rightChannel", right),
                resourceParameter("sample", std::move(sampleId)),
                booleanParameter("autoloop", false),
                {"trigger", "1"},
                {"attackTime", "0 s"},
                {"releaseTime", "0 s"},
                {"scale", "1"},
                {"frequency", "440 hz"},
            }),
            std::move(settings));
    };
    for (auto graph : {
             prepare({}),
             prepare({{"Samples/C33", {}}}),
             prepare({{"Samples/C33", {
                 std::numeric_limits<double>::infinity()}}}),
             prepare({{"Samples/C33", std::vector<double>(
                 1'048'577, 0.0)}}),
             prepare({{"Samples/C33", {1.0}}}, "network stream"),
             prepare({{"Samples/C33", {1.0}}}, "sample", "Samples/C33", false, false),
         })
    {
        talas::runtime::RealtimeRenderSession session(graph);
        require(
            !session.ready(),
            "invalid C33 resource or source mode should reject preparation");
    }
    {
        auto graph = prepare({{"Samples/C33", {1.0}}});
        auto forgedSettings = graph.renderSettings();
        forgedSettings.tableResources.push_back(
            forgedSettings.tableResources.front());
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                graph.plan(), std::move(forgedSettings)});
        require(
            !session.ready(),
            "duplicate C33 resource identities should reject preparation");
    }
}

void testRealtimeSessionRejectsInvalidGenericSourceControls()
{
    talas::runtime::RenderSettings settings{8.0, 4};
    settings.tableResources = {{"Samples/C33", {1.0, 2.0}}};
    const auto compiled = compile(
        makeGenericSourceRamSampleOutputDocument(), settings);
    for (const auto& [parameterIndex, invalidValue, expression] :
         std::array{
             std::tuple<std::size_t, double, std::string_view>{
                 6, -1.0, "-1 s"},
             std::tuple<std::size_t, double, std::string_view>{
                 7, -1.0, "-1 s"},
             std::tuple<std::size_t, double, std::string_view>{
                 9, -1.0, "-1 hz"},
             std::tuple<std::size_t, double, std::string_view>{
                 6, 1.0e308, "1e308 s"},
             std::tuple<std::size_t, double, std::string_view>{
                 7, 1.0e308, "1e308 s"},
         })
    {
        auto plan = compiled.plan();
        const auto source = std::ranges::find(
            plan.steps,
            std::string_view{"talas.genericSource"},
            &talas::runtime::CompileStep::typeId);
        require(
            source != plan.steps.end(),
            "invalid C33 static-control fixture should expose Generic Source");
        const auto parsed = talas::expr::parse(
            expression,
            talas::expr::ExpressionLanguageVersion::SessionV1);
        require(
            parsed.ok(),
            "invalid C33 static-control expression should parse");
        source->parameters[parameterIndex].value = invalidValue;
        source->parameters[parameterIndex].expression = *parsed.expression;
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), compiled.renderSettings()});
        require(
            !session.ready()
                && session.error()
                    == "Realtime Generic Source requires finite admitted static controls",
            "invalid static C33 envelope or frequency should reach its exact preparation boundary");
    }

    for (const auto port : {
             std::string_view{"attackTime"},
             std::string_view{"releaseTime"},
         })
    {
        talas::runtime::RenderSettings settings{8.0, 4};
        settings.tableResources = {{"Samples/C33", {1.0, 2.0}}};
        auto document = makeGenericSourceRamSampleOutputDocument();
        document.graph.nodes.push_back(node(
            "invalid", "talas.constant", {{"value", "-1"}}));
        document.graph.connections.push_back(connection(
            "invalid", "value", "source", std::string{port}));
        const auto graph = compile(document, std::move(settings));
        talas::runtime::RealtimeRenderSession session(graph);
        require(
            session.ready(),
            "connected C33 envelope rejection fixture should prepare");
        std::array<double, 4> left{1.0, 1.0, 1.0, 1.0};
        std::array<double, 4> right{1.0, 1.0, 1.0, 1.0};
        std::size_t allocations = 0;
        require(
            !renderStereoAndCount(
                session, left, right, allocations)
                && allocations == 0
                && left == std::array<double, 4>{}
                && right == std::array<double, 4>{},
            "negative connected C33 envelope should reject atomically without allocation");
    }
}

