void testRealtimeMidiNoteMatchesOfflineAcrossIrregularPartitions()
{
    talas::runtime::RenderSettings settings{8.0, 6};
    settings.eventValues = {
        {"Frequency", 440.0, talas::expr::ValueDomain::Scalar},
        {"Amplitude", 1.0, talas::expr::ValueDomain::Scalar},
        {"Channel", 2.0, talas::expr::ValueDomain::Scalar},
        {"Gate", 0.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {1, "Gate", 1.0, talas::expr::ValueDomain::Scalar},
        {2, "Frequency", 880.0, talas::expr::ValueDomain::Scalar},
        {2, "Amplitude", 0.5, talas::expr::ValueDomain::Scalar},
        {2, "Channel", 3.0, talas::expr::ValueDomain::Scalar},
        {3, "Gate", 0.0, talas::expr::ValueDomain::Scalar},
        {4, "Gate", 1.0, talas::expr::ValueDomain::Scalar},
        {5, "Gate", 0.0, talas::expr::ValueDomain::Scalar},
    };
    auto graph = compile(makeConnectedMidiNoteTerminalDocument(), settings);
    const auto offline = talas::runtime::renderOffline(graph, 6);
    require(
        offline.ok() && offline.midiEvents.size() == 4
            && offline.midiEvents[0].bytes
                == std::vector<std::uint8_t>{0x91, 69, 127}
            && offline.midiEvents[1].bytes
                == std::vector<std::uint8_t>{0x81, 69, 0}
            && offline.midiEvents[2].bytes
                == std::vector<std::uint8_t>{0x92, 81, 64}
            && offline.midiEvents[3].bytes
                == std::vector<std::uint8_t>{0x82, 81, 0},
        "C41 offline oracle should retain active note/channel ownership");

    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string{session.error()});
    std::array<talas::runtime::RealtimeMidiOutputEvent, 6> events{};
    talas::runtime::RealtimeTerminalOutputBlock output{events};
    std::size_t allocations = 0;
    std::size_t absoluteStart = 0;
    std::size_t expectedIndex = 0;
    for (const auto blockSize : {std::size_t{2}, std::size_t{1}, std::size_t{3}})
    {
        require(
            renderTerminalAndCount(session, blockSize, output, allocations)
                    == talas::runtime::RealtimeTerminalRenderResult::Rendered
                && allocations == 0,
            "C41 irregular note callback should render without allocation");
        for (std::size_t index = 0; index < output.midiEventCount; ++index)
        {
            const auto& expected = offline.midiEvents[expectedIndex++];
            require(
                events[index].frameOffset
                        == expected.frame - absoluteStart
                    && events[index].byteCount == expected.bytes.size()
                    && std::equal(
                        events[index].bytes.begin(),
                        events[index].bytes.begin() + 3,
                        expected.bytes.begin()),
                "C41 irregular note event should match offline");
        }
        absoluteStart += blockSize;
    }
    require(
        expectedIndex == offline.midiEvents.size(),
        "C41 irregular partitions should consume every offline note event");

    session.resetTransport();
    require(
        renderTerminalAndCount(session, 6, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 4
            && allocations == 0,
        "C41 reset should replay pristine connected gate ownership");
}

void testRealtimeMidiNoteRollsBackCapacityAndInvalidControls()
{
    talas::runtime::RenderSettings settings{8.0, 5};
    settings.eventValues = {
        {"Frequency", 440.0, talas::expr::ValueDomain::Scalar},
        {"Amplitude", 1.0, talas::expr::ValueDomain::Scalar},
        {"Channel", 2.0, talas::expr::ValueDomain::Scalar},
        {"Gate", 0.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {1, "Gate", 1.0, talas::expr::ValueDomain::Scalar},
        {2, "Gate", 0.0, talas::expr::ValueDomain::Scalar},
        {3, "Gate", 1.0, talas::expr::ValueDomain::Scalar},
        {4, "Gate", 0.0, talas::expr::ValueDomain::Scalar},
    };
    auto graph = compile(makeConnectedMidiNoteTerminalDocument(), settings);
    talas::runtime::RealtimeRenderSession capacity(graph);
    require(capacity.ready(), std::string{capacity.error()});
    std::array<talas::runtime::RealtimeMidiOutputEvent, 2> smallEvents{};
    smallEvents[0].frameOffset = 91;
    smallEvents[0].byteCount = 1;
    smallEvents[0].bytes[0] = 42;
    talas::runtime::RealtimeTerminalOutputBlock smallOutput{smallEvents};
    std::size_t allocations = 0;
    require(
        renderTerminalAndCount(capacity, 5, smallOutput, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::CapacityExceeded
            && smallOutput.midiEventCount == 0
            && smallEvents[0].frameOffset == 91
            && smallEvents[0].byteCount == 1
            && smallEvents[0].bytes[0] == 42
            && allocations == 0,
        "C41 capacity failure should publish nothing");
    std::array<talas::runtime::RealtimeMidiOutputEvent, 5> retryEvents{};
    talas::runtime::RealtimeTerminalOutputBlock retryOutput{retryEvents};
    require(
        renderTerminalAndCount(capacity, 5, retryOutput, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && retryOutput.midiEventCount == 4
            && retryEvents[0].frameOffset == 1
            && retryEvents[3].frameOffset == 4
            && allocations == 0,
        "C41 corrected capacity retry should replay exact gate edges");

    auto requireCorrectedRetry = [](
        std::string eventName,
        talas::expr::ValueDomain domain,
        double invalidValue,
        double correctedValue) {
        talas::runtime::RenderSettings failureSettings{8.0, 4};
        failureSettings.eventValues = {
            {"Frequency", 440.0, talas::expr::ValueDomain::Scalar},
            {"Amplitude", 1.0, talas::expr::ValueDomain::Scalar},
            {"Channel", 2.0, talas::expr::ValueDomain::Scalar},
            {"Gate", 0.0, talas::expr::ValueDomain::Scalar},
        };
        failureSettings.eventValueChanges = {
            {1, "Gate", 1.0, talas::expr::ValueDomain::Scalar},
            {2, "Gate", 0.0, talas::expr::ValueDomain::Scalar},
            {3, eventName, invalidValue, domain},
            {3, "Gate", 1.0, talas::expr::ValueDomain::Scalar},
        };
        auto failureGraph = compile(
            makeConnectedMidiNoteTerminalDocument(), failureSettings);
        talas::runtime::RealtimeRenderSession candidate(failureGraph);
        require(candidate.ready(), std::string{candidate.error()});
        std::array<talas::runtime::RealtimeMidiOutputEvent, 4> events{};
        events[0].frameOffset = 77;
        events[0].byteCount = 1;
        events[0].bytes[0] = 43;
        talas::runtime::RealtimeTerminalOutputBlock output{events};
        std::size_t allocations = 0;
        require(
            renderTerminalAndCount(candidate, 4, output, allocations)
                    == talas::runtime::RealtimeTerminalRenderResult::EvaluationFailure
                && output.midiEventCount == 0
                && events[0].frameOffset == 77
                && events[0].byteCount == 1
                && events[0].bytes[0] == 43
                && allocations == 0,
            "C41 invalid late note control should publish no earlier edges");
        require(
            candidate.updateEventValue(eventName, correctedValue, domain),
            "C41 rejected callback should accept corrected recovery value");
        require(
            renderTerminalAndCount(candidate, 4, output, allocations)
                    == talas::runtime::RealtimeTerminalRenderResult::Rendered
                && output.midiEventCount == 3
                && events[0].frameOffset == 1
                && events[1].frameOffset == 2
                && events[2].frameOffset == 3
                && allocations == 0,
            "C41 corrected retry should match pristine note ownership");
    };
    requireCorrectedRetry(
        "Frequency", talas::expr::ValueDomain::Scalar, -1.0, 880.0);
    requireCorrectedRetry(
        "Amplitude", talas::expr::ValueDomain::Scalar, 1.5, 0.5);
    requireCorrectedRetry(
        "Channel", talas::expr::ValueDomain::Scalar, 17.0, 3.0);

}

void testRealtimeMidiNoteRejectsForgedPreparedAuthority()
{
    talas::runtime::RenderSettings settings{8.0, 4};
    settings.eventValues = {
        {"Frequency", 440.0, talas::expr::ValueDomain::Scalar},
        {"Amplitude", 1.0, talas::expr::ValueDomain::Scalar},
        {"Channel", 2.0, talas::expr::ValueDomain::Scalar},
        {"Gate", 0.0, talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = compile(
        makeConnectedMidiNoteTerminalDocument(), settings);
    const auto requireRejected = [&](talas::runtime::RuntimePlan plan) {
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), compiled.renderSettings()});
        require(!session.ready(), "C41 forged note authority should reject");
    };
    const auto mutateTerminal = [&](auto mutation) {
        auto plan = compiled.plan();
        auto terminal = std::ranges::find(
            plan.steps,
            std::string_view{"talas.midiOutputEvent"},
            &talas::runtime::CompileStep::typeId);
        require(terminal != plan.steps.end(), "C41 forged fixture terminal");
        mutation(plan, *terminal);
        requireRejected(std::move(plan));
    };
    mutateTerminal([](auto&, auto& terminal) {
        terminal.parameters[0].id = "forgedFrequency";
    });
    mutateTerminal([](auto&, auto& terminal) {
        std::swap(terminal.inputs[0], terminal.inputs[1]);
    });
    mutateTerminal([](auto&, auto& terminal) {
        terminal.supportsReset = false;
    });
    mutateTerminal([](auto&, auto& terminal) {
        terminal.resolvedLatencyFrames = 1;
    });
    mutateTerminal([](auto&, auto& terminal) {
        terminal.scopeId = 7;
    });
    mutateTerminal([](auto& plan, auto&) {
        plan.outputBufferIndices.push_back(0);
    });

}

void testRealtimeSessionRendersBoundedMidiFileEcho()
{
    talas::runtime::RenderSettings settings{8.0, 5};
    settings.binaryResources.push_back({
        "Sequences/C42.mid", boundedMidiFileEchoFixture()});
    auto graph = compile(
        makeBoundedMidiFileEchoTerminalDocument(), settings);
    const auto offline = talas::runtime::renderOffline(graph, 8);
    require(
        offline.ok()
            && offline.midiEvents.size() == 2
            && offline.midiEvents[0].frame == 0
            && offline.midiEvents[0].bytes
                == std::vector<std::uint8_t>({0x90, 0x3c, 0x40})
            && offline.midiEvents[1].frame == 4
            && offline.midiEvents[1].bytes
                == std::vector<std::uint8_t>({0x80, 0x3c, 0x00}),
        "C42 RED offline MIDI File Echo reference should remain exact");

    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        "C42 MIDI File Echo should prepare: "
            + std::string{session.error()});
    std::array<talas::runtime::RealtimeMidiOutputEvent, 2> events{};
    talas::runtime::RealtimeTerminalOutputBlock output{events};
    std::size_t allocations = 0;
    require(
        renderTerminalAndCount(session, 5, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 2
            && events[0].frameOffset == 0
            && events[0].byteCount == 3
            && events[0].bytes[0] == 0x90
            && events[0].bytes[1] == 0x3c
            && events[0].bytes[2] == 0x40
            && events[1].frameOffset == 4
            && events[1].byteCount == 3
            && events[1].bytes[0] == 0x80
            && events[1].bytes[1] == 0x3c
            && events[1].bytes[2] == 0x00
            && allocations == 0,
        "C42 prepared MIDI File Echo should match offline without allocation");
    require(
        renderTerminalAndCount(session, 3, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 0
            && allocations == 0,
        "C42 MIDI File Echo should not repeat consumed events");
    session.resetTransport();
    require(
        renderTerminalAndCount(session, 5, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 2
            && events[1].frameOffset == 4
            && allocations == 0,
        "C42 reset should replay the pristine MIDI file schedule");
}

void testRealtimeMidiFileEchoPartitionsCapacityAndFiltering()
{
    talas::runtime::RenderSettings settings{8.0, 5};
    settings.maxRealtimeTerminalEvents = 2;
    settings.binaryResources.push_back({
        "Sequences/C42.mid", boundedMidiFileEchoFixture()});
    auto graph = compile(
        makeBoundedMidiFileEchoTerminalDocument(), settings);
    const auto offline = talas::runtime::renderOffline(graph, 8);
    require(
        offline.ok() && offline.midiEvents.size() == 2,
        "C42 partition reference should contain two events");

    talas::runtime::RealtimeRenderSession partitioned(graph);
    require(partitioned.ready(), std::string{partitioned.error()});
    std::array<talas::runtime::RealtimeMidiOutputEvent, 2> events{};
    talas::runtime::RealtimeTerminalOutputBlock output{events};
    std::size_t allocations = 0;
    require(
        renderTerminalAndCount(partitioned, 3, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 1
            && events[0].frameOffset == 0
            && events[0].bytes[0] == 0x90
            && allocations == 0,
        "C42 first irregular block should emit only note-on");
    require(
        renderTerminalAndCount(partitioned, 2, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 1
            && events[0].frameOffset == 1
            && events[0].bytes[0] == 0x80
            && allocations == 0,
        "C42 second irregular block should retain exact note-off frame");
    require(
        renderTerminalAndCount(partitioned, 3, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 0
            && allocations == 0,
        "C42 final irregular block should be empty");

    talas::runtime::RealtimeRenderSession capacity(graph);
    require(capacity.ready(), std::string{capacity.error()});
    std::array<talas::runtime::RealtimeMidiOutputEvent, 1> smallEvents{};
    smallEvents[0].frameOffset = 91;
    smallEvents[0].byteCount = 1;
    smallEvents[0].bytes[0] = 42;
    talas::runtime::RealtimeTerminalOutputBlock smallOutput{smallEvents};
    require(
        renderTerminalAndCount(capacity, 5, smallOutput, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::CapacityExceeded
            && smallOutput.midiEventCount == 0
            && smallEvents[0].frameOffset == 91
            && smallEvents[0].byteCount == 1
            && smallEvents[0].bytes[0] == 42
            && allocations == 0,
        "C42 caller-capacity failure should publish nothing");
    require(
        renderTerminalAndCount(capacity, 5, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 2
            && events[0].frameOffset == 0
            && events[1].frameOffset == 4
            && allocations == 0,
        "C42 corrected capacity retry should replay the rejected callback");

    talas::runtime::RealtimeRenderSession filtered(compile(
        makeBoundedMidiFileEchoTerminalDocument(
            "Sequences/C42.mid", "2", "16"),
        settings));
    require(
        filtered.ready()
            && renderTerminalAndCount(
                filtered, 5, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 0
            && allocations == 0,
        "C42 prepared channel filter should exclude channel one");

    talas::runtime::RealtimeRenderSession blank(compile(
        makeBoundedMidiFileEchoTerminalDocument(""),
        talas::runtime::RenderSettings{8.0, 5}));
    require(
        blank.ready()
            && renderTerminalAndCount(blank, 5, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 0
            && allocations == 0,
        "C42 blank resource should remain a silent terminal");

    talas::runtime::RealtimeRenderSession late(graph);
    late.setTransportFrameBeforeFirstRender(4);
    require(
        late.ready()
            && renderTerminalAndCount(late, 1, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 1
            && events[0].frameOffset == 0
            && events[0].bytes[0] == 0x80
            && allocations == 0,
        "C42 late transport adoption should skip prior events and publish the exact due frame");

    talas::runtime::RealtimeRenderSession discontinuous(graph);
    require(discontinuous.ready(), std::string{discontinuous.error()});
    const auto transport = [](
        std::uint64_t frame,
        std::uint64_t epoch,
        std::uint64_t discontinuitySequence) {
        return talas::runtime::RealtimeTransportSnapshot{
            .epoch = epoch,
            .absoluteFrame = frame,
            .playheadFrame = frame,
            .sampleRate = 8.0,
            .loopStartFrame = 0,
            .loopEndFrame = 0,
            .discontinuitySequence = discontinuitySequence,
            .playing = true,
            .loopEnabled = false,
        };
    };
    discontinuous.setTransportSnapshotBeforeRender(transport(4, 1, 1));
    require(
        renderTerminalAndCount(discontinuous, 1, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 1
            && events[0].frameOffset == 0
            && events[0].bytes[0] == 0x80
            && allocations == 0,
        "C42 forward discontinuity should skip the prior note-on");
    discontinuous.setTransportSnapshotBeforeRender(transport(0, 2, 2));
    require(
        renderTerminalAndCount(discontinuous, 1, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 1
            && events[0].frameOffset == 0
            && events[0].bytes[0] == 0x90
            && allocations == 0,
        "C42 backward discontinuity should replay the note-on");
}

void testRealtimeMidiFileEchoRejectsMalformedAndForgedAuthority()
{
    talas::runtime::RenderSettings malformedSettings{8.0, 5};
    malformedSettings.binaryResources.push_back({
        "Sequences/C42.mid", {0x00}});
    talas::runtime::RealtimeRenderSession malformed(compile(
        makeBoundedMidiFileEchoTerminalDocument(), malformedSettings));
    require(
        !malformed.ready(),
        "C42 malformed SMF should fail during preparation");

    talas::runtime::RenderSettings boundedSettings{8.0, 5};
    boundedSettings.maxRealtimeTerminalEvents = 1;
    boundedSettings.binaryResources.push_back({
        "Sequences/C42.mid", boundedMidiFileEchoFixture()});
    talas::runtime::RealtimeRenderSession bounded(compile(
        makeBoundedMidiFileEchoTerminalDocument(), boundedSettings));
    require(
        !bounded.ready(),
        "C42 prepared schedule should reject more events than its bound");

    talas::runtime::RenderSettings settings{8.0, 5};
    settings.binaryResources.push_back({
        "Sequences/C42.mid", boundedMidiFileEchoFixture()});
    const auto compiled = compile(
        makeBoundedMidiFileEchoTerminalDocument(), settings);
    const auto requireRejected = [&] (
        talas::runtime::RuntimePlan plan,
        talas::runtime::RenderSettings forgedSettings,
        std::string_view context) {
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), std::move(forgedSettings)});
        require(
            !session.ready(),
            "C42 forged authority should reject "
                + std::string{context});
    };
    const auto mutateTerminal = [&] (
        auto mutation,
        std::string_view context) {
        auto plan = compiled.plan();
        auto terminal = std::ranges::find(
            plan.steps,
            std::string_view{"talas.midiFileEcho"},
            &talas::runtime::CompileStep::typeId);
        require(
            terminal != plan.steps.end(),
            "C42 forged fixture should expose MIDI file terminal");
        mutation(plan, *terminal);
        requireRejected(
            std::move(plan), compiled.renderSettings(), context);
    };
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.parameters[0].id = "forgedLowChannel";
        },
        "parameter identity");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.supportsReset = false;
        },
        "reset authority");
    mutateTerminal(
        [](auto&, auto& terminal) {
            terminal.resolvedLatencyFrames = 1;
        },
        "zero latency authority");
    mutateTerminal(
        [](auto& plan, auto&) {
            plan.outputBufferIndices.push_back(0);
        },
        "terminal-only topology");

    auto duplicateSettings = compiled.renderSettings();
    duplicateSettings.resourceSnapshots.push_back(
        duplicateSettings.resourceSnapshots.front());
    requireRejected(
        compiled.plan(), std::move(duplicateSettings),
        "unique immutable resource identity");

    auto missingSettings = compiled.renderSettings();
    missingSettings.resourceSnapshots.clear();
    requireRejected(
        compiled.plan(), std::move(missingSettings),
        "missing immutable resource");

    auto forgedKindSettings = compiled.renderSettings();
    auto forgedSnapshot = std::make_shared<talas::core::ResourceSnapshot>(
        *forgedKindSettings.resourceSnapshots.front());
    forgedSnapshot->kind = talas::core::ResourceSnapshotKind::Table;
    forgedSnapshot->tableSamples = {1.0};
    forgedKindSettings.resourceSnapshots.front() =
        std::move(forgedSnapshot);
    requireRejected(
        compiled.plan(), std::move(forgedKindSettings),
        "binary resource kind and payload");

    auto forgedBytesSettings = compiled.renderSettings();
    auto forgedBytesSnapshot = std::make_shared<talas::core::ResourceSnapshot>(
        *forgedBytesSettings.resourceSnapshots.front());
    require(
        forgedBytesSnapshot->binaryBytes.size() > 24,
        "C42 forged byte fixture should expose the first note byte");
    forgedBytesSnapshot->binaryBytes[24] = 0x3d;
    forgedBytesSettings.resourceSnapshots.front() =
        std::move(forgedBytesSnapshot);
    requireRejected(
        compiled.plan(), std::move(forgedBytesSettings),
        "offline and immutable snapshot byte identity");
}

void testRealtimeMidiFileEchoRejectsRunningStatusAfterSystemEvents()
{
    const auto requireRejected = [](bool metaEvent) {
        talas::runtime::RenderSettings settings{8.0, 5};
        settings.binaryResources.push_back({
            "Sequences/C42.mid",
            midiFileEchoRunningStatusAfterSystemFixture(metaEvent)});
        auto graph = compile(
            makeBoundedMidiFileEchoTerminalDocument(), settings);
        const auto offline = talas::runtime::renderOffline(graph, 5);
        require(
            !offline.ok(),
            std::string{"C42 offline parser should cancel running status after "}
                + (metaEvent ? "Meta" : "SysEx"));
        talas::runtime::RealtimeRenderSession session(graph);
        require(
            !session.ready(),
            std::string{"C42 prepared parser should cancel running status after "}
                + (metaEvent ? "Meta" : "SysEx"));
    };
    requireRejected(true);
    requireRejected(false);
}

void testRealtimeMidiFileEchoMaximumScheduleIsBoundedAndAllocationFree()
{
    constexpr std::size_t eventCount = 4096;
    talas::runtime::RenderSettings settings{8.0, 1};
    settings.maxRealtimeTerminalEvents = eventCount;
    settings.binaryResources.push_back({
        "Sequences/C42.mid",
        maximumBoundedMidiFileEchoFixture(eventCount)});
    auto graph = compile(
        makeBoundedMidiFileEchoTerminalDocument(),
        std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        "C42 exact maximum schedule should prepare: "
            + std::string{session.error()});

    std::vector<talas::runtime::RealtimeMidiOutputEvent> events(eventCount);
    talas::runtime::RealtimeTerminalOutputBlock output{events};
    std::size_t allocations = 0;
    require(
        renderTerminalAndCount(session, 1, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == eventCount
            && allocations == 0,
        "C42 exact 4096-event callback should remain bounded and allocation-free");
    for (std::size_t index = 0; index < eventCount; ++index)
    {
        require(
            events[index].frameOffset == 0
                && events[index].byteCount == 3
                && events[index].bytes[0] == 0x90
                && events[index].bytes[1]
                    == static_cast<std::uint8_t>(index % 128)
                && events[index].bytes[2]
                    == static_cast<std::uint8_t>((index % 127) + 1),
            "C42 maximum schedule should retain every running-status message in stable order");
    }
    require(
        renderTerminalAndCount(session, 1, output, allocations)
                == talas::runtime::RealtimeTerminalRenderResult::Rendered
            && output.midiEventCount == 0
            && allocations == 0,
        "C42 maximum schedule should consume each event exactly once");
}

