void testRealtimeKeyMappedMultisampleRejectsMutatedSamplingResourceAuthority()
{
    talas::runtime::RenderSettings settings{8.0, 4};
    settings.tableResources = {
        {"Samples/C36Root", {1.0, 2.0, 3.0}},
        {"Samples/C108Unused", {7.0, 8.0}},
    };
    const auto compiled = compile(
        makeBoundedKeyMappedMultisampleOutputDocument(),
        std::move(settings));

    const auto requireRejected = [] (
        talas::runtime::PreparedRuntimeGraph forgedGraph,
        std::string_view context) {
        talas::runtime::RealtimeRenderSession session(forgedGraph);
        require(
            !session.ready(),
            std::string{context}
                + " should reject forged C108 Key-Mapped Multisample sampling authority");
    };

    talas::runtime::RenderSettings aliasedSettings{8.0, 4};
    auto mutableSelectedSnapshot =
        std::make_shared<talas::core::ResourceSnapshot>();
    mutableSelectedSnapshot->id = "Samples/C36Root";
    mutableSelectedSnapshot->generation = 1;
    mutableSelectedSnapshot->contentHash = std::string(64, 'a');
    mutableSelectedSnapshot->tableSamples = {1.0, 2.0, 3.0};
    auto mutableUnusedSnapshot =
        std::make_shared<talas::core::ResourceSnapshot>();
    mutableUnusedSnapshot->id = "Samples/C108Unused";
    mutableUnusedSnapshot->generation = 1;
    mutableUnusedSnapshot->contentHash = std::string(64, 'b');
    mutableUnusedSnapshot->tableSamples = {7.0, 8.0};
    aliasedSettings.resourceSnapshots = {
        mutableSelectedSnapshot,
        mutableUnusedSnapshot,
    };
    auto aliasedGraph = compile(
        makeBoundedKeyMappedMultisampleOutputDocument(),
        std::move(aliasedSettings));
    mutableSelectedSnapshot->tableSamples.front() = 99.0;
    auto& aliasedGraphSettings = mutableSettingsForTest(aliasedGraph);
    const auto selectedTable = std::ranges::find(
        aliasedGraphSettings.tableResources,
        std::string_view{"Samples/C36Root"},
        &talas::runtime::TableResource::id);
    require(
        selectedTable != aliasedGraphSettings.tableResources.end(),
        "C108 mutable-alias fixture should expose its compatibility table");
    selectedTable->samples.front() = 99.0;
    requireRejected(
        std::move(aliasedGraph),
        "post-compile mutable Key-Mapped resource alias with matching public table DTO");

    const auto mutateSettings = [&] (
        auto mutate,
        std::string_view context) {
        auto forgedGraph = compiled;
        mutate(mutableSettingsForTest(forgedGraph));
        requireRejected(std::move(forgedGraph), context);
    };
    mutateSettings(
        [] (auto& forgedSettings) {
            forgedSettings.tableResources[0].samples[0] = 99.0;
        },
        "selected Key-Mapped table payload mutation");
    mutateSettings(
        [] (auto& forgedSettings) {
            forgedSettings.tableResources[1].samples[0] = -7.0;
        },
        "unselected Key-Mapped table payload mutation");
    mutateSettings(
        [] (auto& forgedSettings) {
            forgedSettings.tableResources.push_back(
                forgedSettings.tableResources.back());
        },
        "duplicated unselected Key-Mapped table");
    mutateSettings(
        [] (auto& forgedSettings) {
            forgedSettings.tableResources.pop_back();
        },
        "omitted unselected Key-Mapped table");
    mutateSettings(
        [] (auto& forgedSettings) {
            forgedSettings.tableResources.push_back(
                {"Samples/C108Extra", {9.0}});
        },
        "extra uncompiled Key-Mapped table");
    mutateSettings(
        [] (auto& forgedSettings) {
            forgedSettings.resourceSnapshots.push_back(
                forgedSettings.resourceSnapshots.back());
        },
        "extra Key-Mapped resource snapshot");
    mutateSettings(
        [] (auto& forgedSettings) {
            forgedSettings.resourceSnapshots.pop_back();
        },
        "missing Key-Mapped resource snapshot");
    mutateSettings(
        [] (auto& forgedSettings) {
            forgedSettings.resourceSnapshots.front().reset();
        },
        "null Key-Mapped resource snapshot");

    const auto mutateSnapshot = [&] (
        auto mutate,
        std::string_view context) {
        auto forgedGraph = compiled;
        auto& forgedSettings = mutableSettingsForTest(forgedGraph);
        require(
            !forgedSettings.resourceSnapshots.empty()
                && forgedSettings.resourceSnapshots.front() != nullptr,
            "C108 snapshot mutation fixture should expose one immutable snapshot");
        auto forgedSnapshot =
            std::make_shared<talas::core::ResourceSnapshot>(
                *forgedSettings.resourceSnapshots.front());
        mutate(*forgedSnapshot);
        forgedSettings.resourceSnapshots.front() =
            std::move(forgedSnapshot);
        requireRejected(std::move(forgedGraph), context);
    };
    mutateSnapshot(
        [] (auto& snapshot) { snapshot.id += "Forged"; },
        "Key-Mapped snapshot identity mutation");
    mutateSnapshot(
        [] (auto& snapshot) { ++snapshot.generation; },
        "Key-Mapped snapshot generation mutation");
    mutateSnapshot(
        [] (auto& snapshot) {
            snapshot.tableSamples.front() = std::nextafter(
                snapshot.tableSamples.front(),
                std::numeric_limits<double>::infinity());
        },
        "Key-Mapped snapshot table-sample bit mutation");
    mutateSnapshot(
        [] (auto& snapshot) { snapshot.binaryBytes.push_back(1); },
        "Key-Mapped snapshot non-table field mutation");
    mutateSnapshot(
        [] (auto& snapshot) { snapshot.sampleRate = -0.0; },
        "Key-Mapped snapshot floating-point bit mutation");
    mutateSnapshot(
        [] (auto& snapshot) { snapshot.provenance = "forged"; },
        "Key-Mapped snapshot provenance mutation");

    auto reorderedSnapshots = compiled;
    auto& reorderedSettings = mutableSettingsForTest(
        reorderedSnapshots);
    require(
        reorderedSettings.resourceSnapshots.size() >= 2,
        "C108 resource-order fixture should expose two snapshots");
    std::swap(
        reorderedSettings.resourceSnapshots[0],
        reorderedSettings.resourceSnapshots[1]);
    requireRejected(
        std::move(reorderedSnapshots),
        "reordered Key-Mapped resource snapshot identities");
}

void testRealtimeSamplingAuthorityCoexistsAcrossBothMultisampleVariants()
{
    talas::runtime::RenderSettings settings{8.0, 4};
    settings.tableResources = {
        {"Samples/C36Root", {1.0, 2.0, 3.0}},
        {"Samples/C35Hit", {4.0, 5.0, 6.0}},
        {"Samples/C35Alt", {7.0, 8.0, 9.0}},
    };
    auto document = makeBoundedKeyMappedMultisampleOutputDocument(
        boundedKeyMappedMultisampleParameters({
            {"velocity", "1"}, {"scale", "1"}}));
    document.graph.nodes.push_back(node(
        "multisample",
        "talas.multisample",
        boundedMultisampleParameters()));
    document.graph.nodes.push_back(node(
        "samplingMix",
        "talas.mixer",
        {{"gain1", "1"}, {"gain2", "1"}}));
    std::erase_if(document.graph.connections, [](const auto& edge) {
        return edge.fromNode == "keymap" && edge.toNode == "out";
    });
    document.graph.connections.push_back(connection(
        "keymap", "audioOut", "samplingMix", "in1"));
    document.graph.connections.push_back(connection(
        "multisample", "audioOut", "samplingMix", "in2"));
    document.graph.connections.push_back(connection(
        "samplingMix", "audioOut", "out", "audioIn"));
    const auto graph = compile(document, std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        "C108 graph containing both Multisample variants should admit one shared compiler-sealed sampling authority: "
            + std::string{session.error()});
    std::array<double, 4> left{};
    std::array<double, 4> right{};
    std::size_t allocations = 0;
    require(
        renderStereoAndCount(session, left, right, allocations)
            && allocations == 0
            && std::ranges::all_of(left, [](const auto value) {
                return std::isfinite(value);
            })
            && right == left,
        "C108 coexisting sampling variants should render the connected Key-Mapped output without allocation");

    for (const auto typeId : {
             std::string_view{"talas.multisample"},
             std::string_view{"talas.keyMappedMultisample"},
         })
    {
        auto forgedGraph = graph;
        auto& plan = mutablePlanForTest(forgedGraph);
        const auto step = std::ranges::find(
            plan.steps,
            typeId,
            &talas::runtime::CompileStep::typeId);
        require(
            step != plan.steps.end(),
            "C108 coexistence mutation fixture should expose both sampling operations");
        step->cumulativeOutputLatencyFrames = 1;
        talas::runtime::RealtimeRenderSession rejected(forgedGraph);
        require(
            !rejected.ready(),
            "C108 singular sampling seal should reject mutation of either coexisting Multisample variant");
    }
}

void testRealtimeSessionRejectsInvalidKeyMappedMultisampleResourcesAndModes()
{
    const auto requireRejected = [] (
        std::vector<talas::runtime::TableResource> tables,
        std::vector<talas::project::ProjectParameterExpression> overrides,
        std::string_view context) {
        talas::runtime::RenderSettings settings{8.0, 4};
        settings.tableResources = std::move(tables);
        talas::runtime::RealtimeRenderSession session(compile(
            makeBoundedKeyMappedMultisampleOutputDocument(
                boundedKeyMappedMultisampleParameters(
                    std::move(overrides))),
            std::move(settings)));
        require(
            !session.ready(),
            std::string{context}
                + " should reject invalid C36 preparation");
    };
    requireRejected({}, {}, "missing resource");
    requireRejected(
        {{"Samples/C36Root", {}}}, {}, "empty resource");
    requireRejected(
        {{"Samples/C36Root", {
            std::numeric_limits<double>::infinity()}}},
        {},
        "non-finite resource");
    requireRejected(
        {{"Samples/C36Root", std::vector<double>(1'048'577, 0.0)}},
        {},
        "oversized resource");
    {
        talas::runtime::RenderSettings settings{8.0, 4};
        settings.tableResources = {
            {"Samples/C36Root", {1.0}},
        };
        const auto graph = compile(
            makeBoundedKeyMappedMultisampleOutputDocument(),
            std::move(settings));
        auto forgedSettings = graph.renderSettings();
        forgedSettings.tableResources.push_back(
            forgedSettings.tableResources.front());
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                graph.plan(), std::move(forgedSettings)});
        require(
            !session.ready(),
            "duplicate C36 resource identities should reject preparation");
    }
    // Disk mode prepares since a KeyMappedMultisample may read FromDisk
    //, its samples played without their loops.
    {
        talas::runtime::RenderSettings settings{8.0, 4};
        settings.tableResources = {{"Samples/C36Root", {1.0}}};
        talas::runtime::RealtimeRenderSession session(compile(
            makeBoundedKeyMappedMultisampleOutputDocument(
                boundedKeyMappedMultisampleParameters({booleanParameter("fromDisk", true)})),
            std::move(settings)));
        require(session.ready(), "disk mode should prepare: " + std::string{session.error()});
    }
}

void testRealtimeSessionRejectsInvalidConnectedKeyMappedMultisampleControlsAtomically()
{
    for (const auto port : {
             std::string_view{"frequency"},
             std::string_view{"loFreq"},
             std::string_view{"hiFreq"},
             std::string_view{"gate"},
             std::string_view{"scale"},
             std::string_view{"velocity"},
             std::string_view{"attackTime"},
             std::string_view{"releaseTime"},
         })
    {
        talas::runtime::RenderSettings settings{8.0, 4};
        settings.tableResources = {
            {"Samples/C36Root", {1.0, 2.0}},
        };
        auto document = makeBoundedKeyMappedMultisampleOutputDocument(
            boundedKeyMappedMultisampleParameters({{"gate", "0"}}));
        document.graph.nodes.push_back(node(
            "invalidLeft", "talas.constant", {{"value", "1e308"}}));
        document.graph.nodes.push_back(node(
            "invalidRight", "talas.constant", {{"value", "1e308"}}));
        document.graph.nodes.push_back(node("invalid", "talas.add"));
        document.graph.connections.push_back(connection(
            "invalidLeft", "value", "invalid", "left"));
        document.graph.connections.push_back(connection(
            "invalidRight", "value", "invalid", "right"));
        document.graph.connections.push_back(connection(
            "invalid", "value", "keymap", std::string{port}));
        talas::runtime::RealtimeRenderSession session(
            compile(document, std::move(settings)));
        require(
            session.ready(),
            std::string{"invalid connected C36 fixture should prepare: "}
                + std::string{port} + ": " + std::string{session.error()});
        std::array<double, 4> left{1.0, 1.0, 1.0, 1.0};
        std::array<double, 4> right{1.0, 1.0, 1.0, 1.0};
        std::size_t allocations = 0;
        require(
            !renderStereoAndCount(session, left, right, allocations)
                && allocations == 0
                && left == std::array<double, 4>{}
                && right == std::array<double, 4>{},
            std::string{
                "invalid connected C36 control should reject atomically: "}
                + std::string{port});
    }

    for (const auto& [port, value] : {
             std::pair{std::string_view{"frequency"}, std::string_view{"-1"}},
             std::pair{std::string_view{"loFreq"}, std::string_view{"-1"}},
             std::pair{std::string_view{"hiFreq"}, std::string_view{"-1"}},
             std::pair{std::string_view{"velocity"}, std::string_view{"-1"}},
             std::pair{std::string_view{"attackTime"}, std::string_view{"-1"}},
             std::pair{std::string_view{"releaseTime"}, std::string_view{"-1"}},
         })
    {
        talas::runtime::RenderSettings settings{8.0, 4};
        settings.tableResources = {
            {"Samples/C36Root", {1.0, 2.0}},
        };
        auto document = makeBoundedKeyMappedMultisampleOutputDocument(
            boundedKeyMappedMultisampleParameters({{"gate", "0"}}));
        document.graph.nodes.push_back(node(
            "invalid", "talas.constant", {{"value", std::string{value}}}));
        document.graph.connections.push_back(connection(
            "invalid", "value", "keymap", std::string{port}));
        talas::runtime::RealtimeRenderSession session(
            compile(document, std::move(settings)));
        require(
            session.ready(),
            "negative connected C36 fixture should prepare: "
                + std::string{session.error()});
        std::array<double, 4> left{1.0, 1.0, 1.0, 1.0};
        std::array<double, 4> right{1.0, 1.0, 1.0, 1.0};
        std::size_t allocations = 0;
        require(
            !renderStereoAndCount(session, left, right, allocations)
                && allocations == 0
                && left == std::array<double, 4>{}
                && right == std::array<double, 4>{},
            "C36 should validate connected controls while gate is closed");
    }
}

void testRealtimeSessionRollsBackKeyMappedMultisampleFailures()
{
    const auto makeOverflowGraph = [] (bool downstream) {
        talas::runtime::RenderSettings settings{8.0, 4};
        settings.tableResources = {
            {"Samples/C36Root", {
                1.0e-308, 1.0e308, 1.0e-308, 1.0e-308}},
        };
        auto document = makeBoundedKeyMappedMultisampleOutputDocument(
            boundedKeyMappedMultisampleParameters({
                {"velocity", "1"}, {"scale", "1"}}));
        if (downstream)
        {
            document.graph.nodes.push_back(node(
                "level", "talas.level", {
                    {"left", "1e308"},
                    {"right", "1"},
                    booleanParameter("noGain", false),
                }));
            document.graph.connections.clear();
            document.graph.connections.push_back(connection(
                "keymap", "audioOut", "level", "audioIn"));
            document.graph.connections.push_back(connection(
                "level", "leftOut", "out", "audioIn"));
        }
        else
        {
            document.graph.nodes.push_back(node(
                "scale", "talas.constant", {{"value", "1e308"}}));
            document.graph.connections.push_back(connection(
                "scale", "value", "keymap", "scale"));
        }
        return compile(document, std::move(settings));
    };

    for (const auto downstream : {false, true})
    {
        talas::runtime::RealtimeRenderSession session(
            makeOverflowGraph(downstream));
        require(
            session.ready(),
            "C36 rollback fixture should prepare: "
                + std::string{session.error()});
        std::array<double, 4> left{};
        std::array<double, 4> right{};
        std::size_t allocations = 0;
        require(
            !renderStereoAndCount(session, left, right, allocations)
                && allocations == 0
                && left == std::array<double, 4>{}
                && right == std::array<double, 4>{},
            downstream
                ? "downstream C36 failure should reject atomically"
                : "C36 output overflow should reject atomically");
        require(
            !renderStereoAndCount(session, left, right, allocations)
                && allocations == 0
                && left == std::array<double, 4>{}
                && right == std::array<double, 4>{},
            downstream
                ? "retried downstream C36 failure should restore playback"
                : "retried C36 failure should restore playback");
    }
}

void testRealtimeKeyMappedMultisampleDownstreamRetryRestoresEnvelopeState()
{
    const auto makeRetryGraph = [] {
        talas::runtime::RenderSettings settings{8.0, 2};
        settings.tableResources = {
            {"Samples/C36Root", std::vector<double>(8, 1.0e308)},
        };
        settings.eventValues = {
            {"C108RetryGain", 1.0e-308,
                talas::expr::ValueDomain::Scalar},
        };
        auto document = makeBoundedKeyMappedMultisampleOutputDocument(
            boundedKeyMappedMultisampleParameters({
                {"velocity", "1"},
                {"scale", "1"},
                {"attackTime", "1 s"},
                {"releaseTime", "1 s"},
                booleanParameter("loop", true),
            }));
        document.graph.nodes.push_back(node(
            "level", "talas.level", {
                {"left", "!C108RetryGain"},
                {"right", "1"},
                booleanParameter("noGain", false),
            }));
        document.graph.connections.clear();
        document.graph.connections.push_back(connection(
            "keymap", "audioOut", "level", "audioIn"));
        document.graph.connections.push_back(connection(
            "level", "leftOut", "out", "audioIn"));
        return compile(document, std::move(settings));
    };

    talas::runtime::RealtimeRenderSession candidate(makeRetryGraph());
    talas::runtime::RealtimeRenderSession pristine(makeRetryGraph());
    require(candidate.ready() && pristine.ready(),
        "C108 repaired-retry envelope fixtures should prepare");

    std::array<double, 2> candidateLeft{};
    std::array<double, 2> candidateRight{};
    std::array<double, 2> pristineLeft{};
    std::array<double, 2> pristineRight{};
    std::size_t candidateAllocations = 0;
    std::size_t pristineAllocations = 0;
    require(
        renderStereoAndCount(
            candidate,
            candidateLeft,
            candidateRight,
            candidateAllocations)
            && renderStereoAndCount(
                pristine,
                pristineLeft,
                pristineRight,
                pristineAllocations)
            && candidateAllocations == 0
            && pristineAllocations == 0
            && candidateLeft == pristineLeft
            && candidateRight == pristineRight,
        "C108 repaired-retry fixtures should establish identical active envelope state");

    require(candidate.updateEventValue(
            "C108RetryGain",
            1.0e308,
            talas::expr::ValueDomain::Scalar),
        "C108 candidate should accept a late-failure Event Value");
    candidateLeft.fill(1.0);
    candidateRight.fill(1.0);
    require(
        !renderStereoAndCount(
            candidate,
            candidateLeft,
            candidateRight,
            candidateAllocations)
            && candidateAllocations == 0
            && candidateLeft == std::array<double, 2>{}
            && candidateRight == std::array<double, 2>{},
        "C108 late downstream failure should publish no output or envelope state");

    require(candidate.updateEventValue(
            "C108RetryGain",
            1.0e-308,
            talas::expr::ValueDomain::Scalar),
        "C108 candidate should accept the repaired Event Value");
    require(
        renderStereoAndCount(
            candidate,
            candidateLeft,
            candidateRight,
            candidateAllocations)
            && renderStereoAndCount(
                pristine,
                pristineLeft,
                pristineRight,
                pristineAllocations)
            && candidateAllocations == 0
            && pristineAllocations == 0
            && candidateLeft == pristineLeft
            && candidateRight == pristineRight,
        "C108 repaired downstream retry should restore exact Key-Mapped Multisample elapsed-envelope state and match a fresh session");
}

void testRealtimeKeyMappedMultisampleRejectsForgedPreparedAuthority()
{
    talas::runtime::RenderSettings settings{8.0, 4};
    settings.tableResources = {
        {"Samples/C36Root", {1.0, 2.0, 3.0}},
    };
    auto document = makeBoundedKeyMappedMultisampleOutputDocument();
    for (const auto port : {
             std::string_view{"frequency"},
             std::string_view{"loFreq"},
             std::string_view{"hiFreq"},
             std::string_view{"gate"},
             std::string_view{"scale"},
             std::string_view{"velocity"},
             std::string_view{"attackTime"},
             std::string_view{"releaseTime"},
         })
    {
        document.graph.nodes.push_back(node(
            std::string{port},
            "talas.constant",
            {{"value", port == "frequency" ? "440" :
                (port == "hiFreq" ? "880" :
                    (port == "loFreq" ? "220" : "0"))}}));
        document.graph.connections.push_back(connection(
            std::string{port}, "value", "keymap", std::string{port}));
    }
    const auto compiled = compile(document, std::move(settings));
    talas::runtime::RealtimeRenderSession publiclyConstructedSession(
        talas::runtime::PreparedRuntimeGraph{
            compiled.plan(), compiled.renderSettings()});
    require(
        !publiclyConstructedSession.ready(),
        "C108 Key-Mapped Multisample should require privately compiler-sealed sampling authority");
    const auto mutateKeymap = [&] (auto mutate, std::string_view context) {
        auto forgedGraph = compiled;
        auto& plan = mutablePlanForTest(forgedGraph);
        const auto keymap = std::ranges::find(
            plan.steps,
            std::string_view{"talas.keyMappedMultisample"},
            &talas::runtime::CompileStep::typeId);
        require(
            keymap != plan.steps.end(),
            "C36 forged-authority fixture should expose node");
        mutate(plan, *keymap);
        talas::runtime::RealtimeRenderSession session(forgedGraph);
        require(
            !session.ready(),
            std::string{context}
                + " should reject forged C36 authority");
    };
    mutateKeymap(
        [] (auto&, auto& keymap) {
            keymap.preparedRealtimeSupport =
                talas::core::ExecutionSupport::Supported;
        },
        "forged full support");
    mutateKeymap(
        [] (auto&, auto& keymap) {
            keymap.preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
        },
        "forged native binding");
    mutateKeymap(
        [] (auto&, auto& keymap) {
            keymap.supportsReset = false;
        },
        "forged reset contract");
    mutateKeymap(
        [] (auto&, auto& keymap) {
            ++keymap.eventValueScopeId;
        },
        "forged Event Value scope");
    mutateKeymap(
        [] (auto&, auto& keymap) {
            keymap.parameters[0].value = -0.0;
        },
        "bit-different connected fallback value");
    mutateKeymap(
        [] (auto&, auto& keymap) {
            std::swap(keymap.parameters[0], keymap.parameters[1]);
        },
        "reordered parameters");
    mutateKeymap(
        [] (auto&, auto& keymap) {
            keymap.parameters[3].resource.reset();
        },
        "missing resource authority");
    mutateKeymap(
        [] (auto&, auto& keymap) {
            std::swap(keymap.inputs[0], keymap.inputs[1]);
        },
        "reordered inputs");
    mutateKeymap(
        [] (auto&, auto& keymap) {
            keymap.inputs.front().sourceNodeId += "Forged";
        },
        "forged producer");
    mutateKeymap(
        [] (auto&, auto& keymap) {
            ++keymap.inputs.front().sourceScopeId;
        },
        "forged producer scope");
    mutateKeymap(
        [] (auto& plan, auto& keymap) {
            ++plan.buffers[keymap.inputs.front().bufferIndex].frames;
        },
        "forged input capacity");
    mutateKeymap(
        [] (auto& plan, auto& keymap) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&] (const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == keymap.nodeId
                        && buffer.scopeId == keymap.scopeId
                        && buffer.portId == "audioOut";
                });
            require(
                output != plan.buffers.end(),
                "C36 forged output fixture should expose audioOut");
            ++output->frames;
        },
        "forged output capacity");
    mutateKeymap(
        [] (auto& plan, auto& keymap) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&] (const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == keymap.nodeId
                        && buffer.scopeId == keymap.scopeId
                        && buffer.portId == "audioOut";
                });
            require(
                output != plan.buffers.end(),
                "C108 forged output-scope fixture should expose audioOut");
            ++output->scopeId;
        },
        "forged output scope");
    mutateKeymap(
        [] (auto& plan, auto& keymap) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&] (const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == keymap.nodeId
                        && buffer.scopeId == keymap.scopeId
                        && buffer.portId == "audioOut";
                });
            require(
                output != plan.buffers.end(),
                "C108 duplicate-output fixture should expose audioOut");
            plan.buffers.push_back(*output);
        },
        "duplicate output ownership");
    mutateKeymap(
        [] (auto&, auto& keymap) {
            keymap.resolvedLatencyFrames = 1;
        },
        "forged resolved latency");
    mutateKeymap(
        [] (auto&, auto& keymap) {
            keymap.cumulativeInputLatencyFrames = 1;
        },
        "forged cumulative input latency");
    mutateKeymap(
        [] (auto&, auto& keymap) {
            keymap.inputLatencyFrames.front() = 1;
        },
        "forged input ancestry latency");
    mutateKeymap(
        [] (auto&, auto& keymap) {
            keymap.cumulativeOutputLatencyFrames = 1;
        },
        "forged output latency");
}

void testRealtimeKeyMappedMultisampleAdmitsCheckpointedPredecessorAndSuccessor()
{
    talas::runtime::RenderSettings settings{48'000.0, 4};
    settings.tableResources = {
        {"Samples/C36Root", {1.0, 2.0, 3.0}},
    };

    auto predecessorDocument =
        makeBoundedKeyMappedMultisampleOutputDocument();
    predecessorDocument.graph.nodes.push_back(node(
        "holdValue", "talas.constant", {{"value", "1"}}));
    predecessorDocument.graph.nodes.push_back(node(
        "hold", "talas.sampleAndHold"));
    predecessorDocument.graph.connections.push_back(connection(
        "holdValue", "value", "hold", "value"));
    predecessorDocument.graph.connections.push_back(connection(
        "hold", "value", "keymap", "scale"));
    talas::runtime::RealtimeRenderSession predecessor(
        compile(predecessorDocument, settings));
    require(
        predecessor.ready(),
        "C98 Key-Mapped Multisample should admit a checkpointed Sample And Hold predecessor: "
            + std::string{predecessor.error()});

    auto successorDocument =
        makeBoundedKeyMappedMultisampleOutputDocument();
    successorDocument.graph.nodes.push_back(node(
        "lowPassGate", "talas.lowPassGate", lowPassGateParameters()));
    successorDocument.graph.connections.clear();
    successorDocument.graph.connections.push_back(connection(
        "keymap", "audioOut", "lowPassGate", "audioIn"));
    successorDocument.graph.connections.push_back(connection(
        "lowPassGate", "audioOut", "out", "audioIn"));
    talas::runtime::RealtimeRenderSession successor(
        compile(successorDocument, settings));
    require(
        successor.ready(),
        "C103 Low-Pass Gate should provide dedicated checkpoint coverage as a Key-Mapped Multisample successor: "
            + std::string{successor.error()});
}

void testRealtimeSessionRendersBoundedGaOscillatorsWithoutAllocations()
{
    talas::runtime::RenderSettings settings{16.0, 5};
    settings.tableResources = {
        {"Tables/GA0", {1.0, 0.5}},
        {"Tables/GA1", {0.0, 1.0}},
    };
    auto graph = compile(
        makeGaOscillatorsOutputDocument(), std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 10);
    require(expected.ok(), "offline C32 GA Oscillators reference should render");

    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        std::string("bounded C32 GA Oscillators should prepare: ")
            + std::string(session.error()));

    std::array<double, 5> leftFirst{};
    std::array<double, 5> rightFirst{};
    std::array<double, 5> leftSecond{};
    std::array<double, 5> rightSecond{};
    std::size_t allocations = 0;
    require(
        renderStereoAndCount(session, leftFirst, rightFirst, allocations),
        "first bounded C32 GA Oscillators block should render");
    require(
        allocations == 0,
        "first bounded C32 GA Oscillators block should not allocate");
    require(
        renderStereoAndCount(session, leftSecond, rightSecond, allocations),
        "second bounded C32 GA Oscillators block should render");
    require(
        allocations == 0,
        "second bounded C32 GA Oscillators block should not allocate");
    for (std::size_t frame = 0; frame < leftFirst.size(); ++frame)
    {
        requireNear(
            leftFirst[frame], expected.mono[frame], 1.0e-12,
            "first bounded C32 GA Oscillators block should match offline");
        requireNear(
            rightFirst[frame], expected.mono[frame], 1.0e-12,
            "first bounded C32 GA Oscillators right should match offline");
        requireNear(
            leftSecond[frame], expected.mono[leftFirst.size() + frame],
            1.0e-12,
            "second bounded C32 GA Oscillators block should match offline");
        requireNear(
            rightSecond[frame], expected.mono[rightFirst.size() + frame],
            1.0e-12,
            "second bounded C32 GA Oscillators right should match offline");
    }
}

void testRealtimeSessionRendersConnectedGaOscillatorsAcrossIrregularPartitions()
{
    talas::runtime::RenderSettings settings{16.0, 5};
    settings.tableResources = {
        {"Tables/GA0", {1.0, 0.5}},
        {"Tables/GA1", {0.0, 1.0}},
        {"Tables/Envelope", {
            1.0, 0.75, 0.5, 0.25, 1.0,
            0.5, 1.0, 0.25, 0.75, 1.0,
        }},
        {"Tables/Frequency", {
            1.0, 1.25, 1.5, 1.75, 2.0,
            1.0, 1.5, 2.0, 1.25, 1.75,
        }},
        {"Tables/Morph", {
            0.0, 0.25, 0.5, 0.75, 1.0,
            1.0, 0.75, 0.5, 0.25, 0.0,
        }},
    };
    auto document = makeGaOscillatorsOutputDocument();
    for (const auto& [nodeId, resourceId] : {
             std::pair{"envelope", "Tables/Envelope"},
             std::pair{"frequency", "Tables/Frequency"},
             std::pair{"morph", "Tables/Morph"},
         })
    {
        document.graph.nodes.push_back(node(
            nodeId,
            "talas.triggeredTableRead",
            {
                {"trigger", "1"},
                resourceParameter("wavetable", resourceId),
                {"gate", "1"},
                booleanParameter("ignoreLoops", true),
                booleanParameter("fromMemoryWriter", false),
            }));
        document.graph.connections.push_back(connection(
            nodeId, "value", "ga", nodeId));
    }
    auto graph = compile(document, std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 10);
    require(
        expected.ok(),
        "offline connected C32 GA Oscillators reference should render");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 3> leftFirst{};
    std::array<double, 3> rightFirst{};
    std::array<double, 2> leftSecond{};
    std::array<double, 2> rightSecond{};
    std::array<double, 5> leftThird{};
    std::array<double, 5> rightThird{};
    std::size_t allocations = 0;
    require(
        renderStereoAndCount(
            session, leftFirst, rightFirst, allocations),
        "first irregular connected C32 GA Oscillators block should render");
    require(allocations == 0, "first irregular C32 block should not allocate");
    require(
        renderStereoAndCount(
            session, leftSecond, rightSecond, allocations),
        "second irregular connected C32 GA Oscillators block should render");
    require(allocations == 0, "second irregular C32 block should not allocate");
    require(
        renderStereoAndCount(
            session, leftThird, rightThird, allocations),
        "third irregular connected C32 GA Oscillators block should render");
    require(allocations == 0, "third irregular C32 block should not allocate");

    std::size_t expectedFrame = 0;
    const auto requireBlock = [&] (const auto& left, const auto& right) {
        for (std::size_t frame = 0; frame < left.size(); ++frame)
        {
            requireNear(
                left[frame], expected.mono[expectedFrame], 1.0e-12,
                "irregular connected C32 left should match offline");
            requireNear(
                right[frame], expected.mono[expectedFrame], 1.0e-12,
                "irregular connected C32 right should match offline");
            ++expectedFrame;
        }
    };
    requireBlock(leftFirst, rightFirst);
    requireBlock(leftSecond, rightSecond);
    requireBlock(leftThird, rightThird);
}

void testRealtimeSessionOwnsMaximumGaOscillatorAnalysisAndResetsPhases()
{
    std::vector<double> amplitudes(4096, 0.0);
    amplitudes.front() = 0.5;
    talas::runtime::RenderSettings settings{16.0, 5};
    settings.tableResources = {
        {"Tables/GA0", std::move(amplitudes)},
    };
    auto graph = compile(
        makeGaOscillatorsOutputDocument({
            {"timeIndex", "0"},
            resourceParameter("analysis0", "Tables/GA0"),
            resourceParameter("analysis1", ""),
            {"envelope", "1"},
            {"frequency", "1 hz"},
            {"morph", "0"},
        }),
        std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 5);
    require(expected.ok(), "offline maximum C32 reference should render");
    talas::runtime::RealtimeRenderSession session(graph);
    require(
        session.ready(),
        "exact-4096 GA Oscillators analysis should prepare");

    auto& callerSettings = const_cast<talas::runtime::RenderSettings&>(
        graph.renderSettings());
    std::ranges::fill(
        callerSettings.tableResources.front().samples,
        std::numeric_limits<double>::quiet_NaN());

    std::array<double, 5> leftFirst{};
    std::array<double, 5> rightFirst{};
    std::array<double, 5> leftReset{};
    std::array<double, 5> rightReset{};
    std::size_t allocations = 0;
    require(
        renderStereoAndCount(
            session, leftFirst, rightFirst, allocations),
        "maximum C32 render should use its operation-owned analysis");
    require(allocations == 0, "maximum C32 render should not allocate");
    session.resetTransport();
    require(
        renderStereoAndCount(
            session, leftReset, rightReset, allocations),
        "reset maximum C32 render should succeed");
    require(allocations == 0, "reset maximum C32 render should not allocate");
    for (std::size_t frame = 0; frame < leftFirst.size(); ++frame)
    {
        requireNear(
            leftFirst[frame], expected.mono[frame], 1.0e-12,
            "maximum C32 owned-copy render should match offline");
        requireNear(
            leftReset[frame], leftFirst[frame], 1.0e-12,
            "C32 reset should restore the initial phase sequence");
        requireNear(
            rightReset[frame], rightFirst[frame], 1.0e-12,
            "C32 reset should restore the right initial phase sequence");
    }
}

void testRealtimeSessionRejectsInvalidGaOscillatorResources()
{
    const auto prepare = [] (
        std::vector<talas::runtime::TableResource> tables,
        std::string analysis1Id = "Tables/GA1",
        std::string morph = "0.25") {
        talas::runtime::RenderSettings settings{16.0, 5};
        settings.tableResources = std::move(tables);
        return compile(
            makeGaOscillatorsOutputDocument({
                {"timeIndex", "0"},
                resourceParameter("analysis0", "Tables/GA0"),
                resourceParameter("analysis1", std::move(analysis1Id)),
                {"envelope", "1"},
                {"frequency", "1 hz"},
                {"morph", std::move(morph)},
            }),
            std::move(settings));
    };
    for (auto graph : {
             prepare({}),
             prepare({{"Tables/GA0", {}}}, "", "0"),
             prepare({{"Tables/GA0", {
                 std::numeric_limits<double>::infinity()}}}, "", "0"),
             prepare({
                 {"Tables/GA0", std::vector<double>(4097, 0.0)}},
                 "",
                 "0"),
             prepare({
                 {"Tables/GA0", {1.0, 0.5}},
                 {"Tables/GA1", {1.0}},
             }),
             prepare({{"Tables/GA0", {1.0, 0.5}}}),
         })
    {
        talas::runtime::RealtimeRenderSession session(graph);
        require(
            !session.ready(),
            "invalid C32 analysis resources should reject preparation");
    }
    {
        auto graph = prepare(
            {
                {"Tables/GA0", {1.0}},
                {"Tables/GA1", {0.5}},
            });
        auto forgedSettings = graph.renderSettings();
        forgedSettings.tableResources.push_back(
            forgedSettings.tableResources.front());
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                graph.plan(), std::move(forgedSettings)});
        require(
            !session.ready(),
            "duplicate C32 analysis identities should reject preparation");
    }
    {
        talas::runtime::RenderSettings settings{16.0, 5};
        settings.tableResources = {{"Tables/GA0", {1.0, 0.5}}};
        auto document = makeGaOscillatorsOutputDocument({
            {"timeIndex", "0"},
            resourceParameter("analysis0", "Tables/GA0"),
            resourceParameter("analysis1", ""),
            {"envelope", "1"},
            {"frequency", "1 hz"},
            {"morph", "0.5"},
        });
        document.graph.nodes.push_back(node(
            "morph", "talas.constant", {{"value", "0"}}));
        document.graph.connections.push_back(connection(
            "morph", "value", "ga", "morph"));
        auto graph = compile(document, std::move(settings));
        require(
            !talas::runtime::renderOffline(graph, 5).ok(),
            "offline authority should reject missing analysis1 from the stored nonzero morph fallback");
        talas::runtime::RealtimeRenderSession session(graph);
        require(
            !session.ready(),
            "prepared C32 should preserve offline missing-analysis1 admission with connected morph");
    }
}

void testRealtimeSessionRollsBackRejectedGaOscillatorCallbackWithoutAllocations()
{
    talas::runtime::RenderSettings settings{16.0, 5};
    settings.tableResources = {
        {"Tables/GA0", {1.0e308}},
        {"Tables/Envelope", {
            1.0e308, 1.0e308, 1.0e308, 1.0e308, 1.0e308,
            1.0e-308, 1.0e-308, 1.0e-308, 1.0e-308, 1.0e-308,
        }},
    };
    auto document = makeGaOscillatorsOutputDocument({
        {"timeIndex", "0"},
        resourceParameter("analysis0", "Tables/GA0"),
        resourceParameter("analysis1", ""),
        {"envelope", "1"},
        {"frequency", "1 hz"},
        {"morph", "0"},
    });
    document.graph.nodes.push_back(node(
        "envelope",
        "talas.triggeredTableRead",
        {
            {"trigger", "1"},
            resourceParameter("wavetable", "Tables/Envelope"),
            {"gate", "1"},
            booleanParameter("ignoreLoops", true),
            booleanParameter("fromMemoryWriter", false),
        }));
    document.graph.connections.push_back(connection(
        "envelope", "value", "ga", "envelope"));
    auto graph = compile(document, std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 5> left{};
    std::array<double, 5> right{};
    std::size_t allocations = 0;
    require(
        !renderStereoAndCount(session, left, right, allocations),
        "C32 finite final-product overflow should reject");
    require(allocations == 0, "rejected C32 overflow should not allocate");
    require(
        !renderStereoAndCount(session, left, right, allocations),
        "retried C32 overflow should replay the rejected callback");
    require(allocations == 0, "retried C32 overflow should not allocate");
}

