void testRealtimeSessionEmitsC57VoicedUnvoicedTransitionFramesWithoutAllocations()
{
    talas::runtime::RenderSettings settings{1000.0, 1};
    settings.tableResources = {{"Analysis/C57", {
        1.0, 1.0, 0.1, 0.5, 2.0, 0.2,
        1.0, 1.0, 0.1, 0.5, 2.6, 0.2,
        1.0, 1.0, 0.1, 0.5, 2.6, 0.2,
        1.0, 1.0, 0.1, 0.5, 2.0, 0.2,
        1.0, 1.0, 0.1, 0.5, 2.0, 0.2,
    }}};
    auto graph = compile(
        makeSpectrumOnDiskVoicedUnvoicedDocument({
            {"frequency", "100 hz"},
            {"level", "1"},
            {"rateScale", "1"},
            {"trigger", "0"},
            resourceParameter("fileName", "Analysis/C57"),
            {"analysisFrames", "5"},
            {"nbrPartials", "2"},
            {"firstPartial", "1"},
        }),
        std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    const std::array expected{1.0, 0.5, 0.0, 0.5, 1.0};
    for (std::size_t transaction = 0;
         transaction < expected.size(); ++transaction)
    {
        std::array<double, 1> left{};
        std::array<double, 1> right{};
        std::size_t allocations = 0;
        require(
            renderStereoAndCount(session, left, right, allocations),
            "C57 prepared transition transaction should render");
        require(
            allocations == 0,
            "C57 prepared transition transaction should not allocate");
        requireNear(
            left[0], expected[transaction], 1.0e-12,
            "C57 prepared left transition transaction "
                + std::to_string(transaction));
        requireNear(
            right[0], expected[transaction], 1.0e-12,
            "C57 prepared right transition transaction "
                + std::to_string(transaction));
    }

    session.resetTransport();
    std::array<double, 1> resetLeft{};
    std::array<double, 1> resetRight{};
    std::size_t resetAllocations = 0;
    require(
        renderStereoAndCount(
            session, resetLeft, resetRight, resetAllocations)
            && resetAllocations == 0
            && resetLeft[0] == 1.0 && resetRight[0] == 1.0,
        "C57 prepared reset should clear transition history and source scan");
    require(
        renderStereoAndCount(
            session, resetLeft, resetRight, resetAllocations)
            && resetAllocations == 0 && resetLeft[0] == 0.5,
        "C57 prepared lifecycle fixture should re-enter transition state");
    session.setTransportSnapshotBeforeRender({
        .epoch = 2,
        .absoluteFrame = 100,
        .playheadFrame = 100,
        .sampleRate = 1000.0,
        .discontinuitySequence = 1,
        .playing = true,
    });
    require(
        renderStereoAndCount(
            session, resetLeft, resetRight, resetAllocations)
            && resetAllocations == 0
            && resetLeft[0] == 1.0 && resetRight[0] == 1.0,
        "C57 transport discontinuity should clear transition history and source scan");

    talas::runtime::RealtimeRenderSession emptySession(graph);
    require(emptySession.ready(), std::string(emptySession.error()));
    std::array<double, 1> left{};
    std::array<double, 1> right{};
    std::size_t allocations = 0;
    require(
        renderStereoAndCount(emptySession, left, right, allocations)
            && allocations == 0 && left[0] == 1.0,
        "C57 prepared empty fixture should publish its initial endpoint");
    require(
        renderEmptyStereoAndCount(emptySession, allocations)
            && allocations == 0,
        "C57 prepared empty callback should publish without allocation");
    require(
        renderStereoAndCount(emptySession, left, right, allocations)
            && allocations == 0
            && left[0] == 0.0 && right[0] == 0.0,
        "C57 prepared empty callback should consume exactly one transition frame");

    auto staticGraph = compile(
        makeSpectrumVoicedUnvoicedDocument(),
        talas::runtime::RenderSettings{1000.0, 1});
    talas::runtime::RealtimeRenderSession staticEmptySession(staticGraph);
    require(
        staticEmptySession.ready(),
        std::string(staticEmptySession.error()));
    require(
        renderEmptyStereoAndCount(staticEmptySession, allocations)
            && allocations == 0,
        "C57 prepared empty callback should be independent of the Spectrum "
        "source");
    require(
        renderStereoAndCount(
            staticEmptySession, left, right, allocations)
            && allocations == 0
            && left[0] == 1.0 && right[0] == 1.0,
        "C57 source-independent empty callback should commit its initial endpoint");

    talas::runtime::RenderSettings unsupportedSettings{1000.0, 1};
    unsupportedSettings.tableResources.push_back({
        "Analysis/RAM", {1.0, 1.0, 0.1, 0.5, 2.0, 0.2}});
    auto unsupportedGraph = compile(
        makeSpectrumInRamVoicedUnvoicedDocument(),
        std::move(unsupportedSettings));
    talas::runtime::RealtimeRenderSession unsupported(unsupportedGraph);
    talas::runtime::RealtimeRenderSession unsupportedReference(
        unsupportedGraph);
    require(
        unsupported.ready() && unsupportedReference.ready(),
        "C57 unsupported empty-source fixture should prepare");
    require(
        renderStereoAndCount(unsupported, left, right, allocations)
            && allocations == 0 && left[0] == 1.0
            && renderStereoAndCount(
                unsupportedReference, left, right, allocations)
            && allocations == 0 && left[0] == 1.0,
        "C57 unsupported empty-source fixture should prime persistent buffers");
    require(
        !renderEmptyStereoAndCount(unsupported, allocations)
            && allocations == 0,
        "C57 empty callback should reject a stale unsupported Spectrum source");
    std::array<double, 1> unsupportedLeft{};
    std::array<double, 1> unsupportedRight{};
    std::array<double, 1> referenceLeft{};
    std::array<double, 1> referenceRight{};
    require(
        renderStereoAndCount(
            unsupported, unsupportedLeft, unsupportedRight, allocations)
            && allocations == 0
            && renderStereoAndCount(
                unsupportedReference,
                referenceLeft,
                referenceRight,
                allocations)
            && allocations == 0
            && unsupportedLeft == referenceLeft
            && unsupportedRight == referenceRight,
        "C57 rejected empty callback should preserve subsequent state and output");
}

void testRealtimeSessionKeepsC57TransitionTransactionalAcrossSegmentsAndFailure()
{
    auto settings = talas::runtime::RenderSettings{1000.0, 5};
    settings.tableResources = {{"Analysis/C57", {
        1.0, 1.0, 0.1, 0.5, 2.0, 0.2,
        1.0, 1.0, 0.1, 0.5, 2.6, 0.2,
        1.0, 1.0, 0.1, 0.5, 2.6, 0.2,
    }}};
    settings.eventValues.push_back({
        "C57Gain", 1.0, talas::expr::ValueDomain::Scalar});
    auto document = makeSpectrumOnDiskVoicedUnvoicedDocument({
        {"frequency", "100 hz"},
        {"level", "1"},
        {"rateScale", "1"},
        {"trigger", "0"},
        resourceParameter("fileName", "Analysis/C57"),
        {"analysisFrames", "3"},
        {"nbrPartials", "2"},
        {"firstPartial", "1"},
    });
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "1"}, {"right", "1"},
            booleanParameter("noGain", false),
        }));
    document.graph.nodes.push_back(node(
        "gain", "talas.constant", {{"value", "!C57Gain"}}));
    document.graph.nodes.push_back(node(
        "overflow", "talas.level", {
            {"left", "2"}, {"right", "2"},
            booleanParameter("noGain", false),
        }));
    std::erase_if(
        document.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "voiced" && edge.toNode == "out";
        });
    document.graph.connections.push_back(connection(
        "voiced", "leftOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "gain", "value", "downstream", "left"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "overflow", "audioIn"));
    document.graph.connections.push_back(connection(
        "overflow", "leftOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "overflow", "rightOut", "out", "rightIn"));

    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(
        candidate.ready() && reference.ready()
            && candidate.scheduleEventValue(
                "C57Gain", std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar, 2),
        "C57 segmented rollback fixture should prepare");

    std::array<double, 5> rejectedLeft{1, 1, 1, 1, 1};
    std::array<double, 5> rejectedRight{1, 1, 1, 1, 1};
    std::size_t allocations = 0;
    require(
        !renderStereoAndCount(
            candidate, rejectedLeft, rejectedRight, allocations)
            && allocations == 0
            && rejectedLeft == std::array<double, 5>{}
            && rejectedRight == std::array<double, 5>{},
        "C57 late downstream failure should publish no callback prefix");
    require(
        candidate.updateEventValue(
            "C57Gain", 1.0, talas::expr::ValueDomain::Scalar),
        "C57 downstream control should recover after rejection");

    const auto renderExpected = [&](double expected) {
        std::array<double, 5> actualLeft{};
        std::array<double, 5> actualRight{};
        std::array<double, 5> expectedLeft{};
        std::array<double, 5> expectedRight{};
        require(
            renderStereoAndCount(
                candidate, actualLeft, actualRight, allocations)
                && allocations == 0
                && renderStereoAndCount(
                    reference, expectedLeft, expectedRight, allocations)
                && allocations == 0
                && actualLeft == expectedLeft
                && actualRight == expectedRight,
            "C57 rejected segmented callback should retry bit-identically");
        for (const auto sample : actualLeft)
        {
            requireNear(
                sample, expected, 1.0e-12,
                "C57 public transition should be reused across scheduler segments");
        }
    };
    renderExpected(2.0);
    renderExpected(1.0);
    renderExpected(0.0);
}

void testRealtimeSessionAdvancesC56EmptyTransactionsFromConnectedSnapshots()
{
    auto settings = talas::runtime::RenderSettings{1000.0, 1};
    settings.tableResources = {{"Analysis/Disk", {
        0.1, 1.0, 0.1,
        0.5, 2.0, 0.2,
        0.9, 3.0, 0.3,
    }}};
    settings.eventValues = {
        {"C56Rate", 1.0, talas::expr::ValueDomain::Scalar},
        {"C56Trigger", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto document = makeSpectrumOnDiskTrackSelectorDocument({
        {"frequency", "100 hz"},
        {"level", "1"},
        {"rateScale", "0"},
        {"trigger", "-1"},
        resourceParameter("fileName", "Analysis/Disk"),
        {"analysisFrames", "3"},
        {"nbrPartials", "1"},
        {"firstPartial", "1"},
    });
    document.graph.nodes.push_back(node(
        "rateControl", "talas.constant", {{"value", "!C56Rate"}}));
    document.graph.nodes.push_back(node(
        "triggerControl", "talas.constant", {{"value", "!C56Trigger"}}));
    document.graph.connections.push_back(connection(
        "rateControl", "value", "source", "rateScale"));
    document.graph.connections.push_back(connection(
        "triggerControl", "value", "source", "trigger"));

    talas::runtime::RealtimeRenderSession session(
        compile(document, std::move(settings)));
    require(session.ready(), std::string(session.error()));
    std::size_t allocations = 0;
    const auto emptyRendered =
        renderEmptyStereoAndCount(session, allocations);
    require(
        emptyRendered && allocations == 0,
        "C56 zero-length callback should commit exactly one connected-control transaction without allocation: rendered="
            + std::to_string(emptyRendered) + ", allocations="
            + std::to_string(allocations));

    std::array<double, 1> left{};
    std::array<double, 1> right{};
    require(
        renderStereoAndCount(session, left, right, allocations)
            && allocations == 0
            && left[0] == 0.5
            && right[0] == 200.0,
        "C56 zero-length callback must use connected rate/trigger precedence and advance once");

    session.resetTransport();
    require(
        renderStereoAndCount(session, left, right, allocations)
            && allocations == 0
            && left[0] == 0.1
            && right[0] == 100.0,
        "C56 reset after an empty transaction must restore pristine scan state");
}

void testRealtimeSessionRejectsInvalidC56EmptyFrameWithoutAdvancingState()
{
    auto settings = talas::runtime::RenderSettings{1000.0, 1};
    settings.tableResources = {{"Analysis/Disk", {
        1.0, 2.0, 0.0,
        0.5, 3.0, 0.0,
    }}};
    settings.eventValues = {
        {"C56Frequency", 1.0e308, talas::expr::ValueDomain::Scalar},
        {"C56Trigger", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto document = makeSpectrumOnDiskTrackSelectorDocument({
        {"frequency", "100 hz"}, {"level", "1"},
        {"rateScale", "1"}, {"trigger", "0"},
        resourceParameter("fileName", "Analysis/Disk"),
        {"analysisFrames", "2"}, {"nbrPartials", "1"},
        {"firstPartial", "1"},
    });
    document.graph.nodes.push_back(node(
        "frequencyControl", "talas.constant",
        {{"value", "!C56Frequency"}}));
    document.graph.nodes.push_back(node(
        "triggerControl", "talas.constant",
        {{"value", "!C56Trigger"}}));
    document.graph.connections.push_back(connection(
        "frequencyControl", "value", "source", "frequency"));
    document.graph.connections.push_back(connection(
        "triggerControl", "value", "source", "trigger"));
    const auto graph = compile(document, settings);

    talas::runtime::OfflineRenderSession offline(graph);
    const auto offlineRejected = offline.render(0);
    require(
        !offlineRejected.ok() && offlineRejected.mono.empty(),
        "offline C56 empty transaction must reject scaled frame overflow");

    talas::runtime::RealtimeRenderSession realtime(graph);
    require(realtime.ready(), std::string(realtime.error()));
    std::size_t allocations = 0;
    require(
        !renderEmptyStereoAndCount(realtime, allocations)
            && allocations == 0,
        "prepared C56 empty transaction must reject scaled frame overflow without allocation");
    require(
        realtime.updateEventValue(
            "C56Frequency", 1.0, talas::expr::ValueDomain::Scalar),
        "C56 empty overflow fixture should accept a finite recovery frequency");
    std::array<double, 1> left{};
    std::array<double, 1> right{};
    require(
        renderStereoAndCount(realtime, left, right, allocations)
            && allocations == 0
            && left[0] == 1.0 && right[0] == 2.0,
        "rejected C56 empty transaction must preserve cursor and rising-trigger retry state");
}

void testRealtimeSessionKeepsNestedC56ScopesIndependent()
{
    talas::project::ProjectSoundDefinition definition;
    definition.definitionId = "c56Cell";
    definition.displayName = "C56 Cell";
    definition.graph.nodes = {
        node("source", "talas.spectrumOnDisk", {
            {"frequency", "100 hz"}, {"level", "1"},
            {"rateScale", "1"}, {"trigger", "0"},
            resourceParameter("fileName", "Analysis/Disk"),
            {"analysisFrames", "3"}, {"nbrPartials", "1"},
            {"firstPartial", "1"},
        }),
        node("selector", "talas.spectrumTrackSelector", hertzSelector({
            {"track", "1"},
            booleanParameter("amp", true),
            booleanParameter("freq", true),
        })),
    };
    definition.graph.connections = {connection(
        "source", "spectrumOut", "selector", "spectrumIn")};
    definition.outputs = {
        {"leftOut", talas::core::PortType::Audio, "selector", "leftOut"},
        {"rightOut", talas::core::PortType::Audio, "selector", "rightOut"},
    };
    talas::project::ProjectNode first;
    first.instanceId = "firstCell";
    first.soundDefinitionId = definition.definitionId;
    talas::project::ProjectNode second;
    second.instanceId = "secondCell";
    second.soundDefinitionId = definition.definitionId;

    talas::project::ProjectDocument document;
    document.soundDefinitions.push_back(std::move(definition));
    document.graph.nodes = {
        std::move(first), std::move(second), node("out", "talas.audioOutput")};
    document.graph.connections = {
        connection("firstCell", "leftOut", "out", "audioIn"),
        connection("secondCell", "leftOut", "out", "rightIn"),
    };
    auto settings = talas::runtime::RenderSettings{1000.0, 1};
    settings.tableResources = {{"Analysis/Disk", {
        0.1, 1.0, 0.1,
        0.5, 2.0, 0.2,
        0.9, 3.0, 0.3,
    }}};
    const auto graph = compile(document, std::move(settings));
    std::vector<talas::runtime::RuntimeScopeId> scopes;
    for (const auto& step : graph.plan().steps)
    {
        if (step.typeId == "talas.spectrumOnDisk")
            scopes.push_back(step.scopeId);
    }
    require(
        scopes.size() == 2 && scopes[0] != scopes[1]
            && scopes[0] != talas::runtime::globalRuntimeScope
            && scopes[1] != talas::runtime::globalRuntimeScope,
        "nested prepared C56 instances must own distinct scopes");

    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    std::array<double, 1> left{};
    std::array<double, 1> right{};
    std::size_t allocations = 0;
    require(
        renderStereoAndCount(session, left, right, allocations)
            && allocations == 0
            && left[0] == 0.1 && right[0] == 0.1,
        "nested prepared C56 scopes must begin from identical independent state");
    require(
        renderStereoAndCount(session, left, right, allocations)
            && allocations == 0
            && left[0] == 0.5 && right[0] == 0.5,
        "nested prepared C56 scopes must advance independently without allocation");
}

void testRealtimeSessionAppliesC56SpectrumOnDiskRateTriggerAndResetLifecycle()
{
    const auto makeGraph = [](std::string rateScale) {
        talas::runtime::RenderSettings settings{1000.0, 1};
        settings.tableResources = {{"Analysis/Disk", {
            0.1, 1.0, 0.1,
            0.5, 2.0, 0.2,
            0.9, 3.0, 0.3,
        }}};
        return compile(
            makeSpectrumOnDiskTrackSelectorDocument({
                {"frequency", "100 hz"},
                {"level", "1"},
                {"rateScale", std::move(rateScale)},
                {"trigger", "0"},
                resourceParameter("fileName", "Analysis/Disk"),
                {"analysisFrames", "3"},
                {"nbrPartials", "1"},
                {"firstPartial", "1"},
            }),
            std::move(settings));
    };
    const auto renderOne = [](talas::runtime::RealtimeRenderSession& session) {
        std::array<double, 1> left{};
        std::array<double, 1> right{};
        std::size_t allocations = 0;
        require(
            renderStereoAndCount(session, left, right, allocations)
                && allocations == 0,
            "C56 lifecycle transaction should render without allocations");
        return std::pair{left[0], right[0]};
    };

    {
        talas::runtime::RealtimeRenderSession frozen(makeGraph("0"));
        require(frozen.ready(), std::string(frozen.error()));
        require(
            renderOne(frozen) == std::pair{0.1, 100.0}
                && renderOne(frozen) == std::pair{0.1, 100.0},
            "C56 zero rate should freeze the logical frame cursor");
    }
    {
        talas::runtime::RealtimeRenderSession skipped(makeGraph("2"));
        require(skipped.ready(), std::string(skipped.error()));
        require(
            renderOne(skipped) == std::pair{0.1, 100.0}
                && renderOne(skipped) == std::pair{0.9, 300.0}
                && renderOne(skipped) == std::pair{0.9, 300.0},
            "C56 fast rate should skip and clamp at the final frame");
    }

    auto settings = talas::runtime::RenderSettings{1000.0, 1};
    settings.tableResources = {{"Analysis/Disk", {
        0.1, 1.0, 0.1,
        0.5, 2.0, 0.2,
        0.9, 3.0, 0.3,
    }}};
    settings.eventValues.push_back({
        "C56Trigger", 0.0, talas::expr::ValueDomain::Scalar});
    auto document = makeSpectrumOnDiskTrackSelectorDocument({
        {"frequency", "100 hz"},
        {"level", "1"},
        {"rateScale", "1"},
        {"trigger", "0"},
        resourceParameter("fileName", "Analysis/Disk"),
        {"analysisFrames", "3"},
        {"nbrPartials", "1"},
        {"firstPartial", "1"},
    });
    document.graph.nodes.push_back(node(
        "triggerControl", "talas.constant", {{"value", "!C56Trigger"}}));
    document.graph.connections.push_back(connection(
        "triggerControl", "value", "source", "trigger"));
    const auto graph = compile(document, std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    require(
        renderOne(session) == std::pair{0.1, 100.0}
            && renderOne(session) == std::pair{0.5, 200.0}
            && session.updateEventValue(
                "C56Trigger", 1.0, talas::expr::ValueDomain::Scalar)
            && renderOne(session) == std::pair{0.1, 100.0}
            && renderOne(session) == std::pair{0.5, 200.0}
            && session.updateEventValue(
                "C56Trigger", 0.0, talas::expr::ValueDomain::Scalar)
            && renderOne(session) == std::pair{0.9, 300.0}
            && session.updateEventValue(
                "C56Trigger", 1.0, talas::expr::ValueDomain::Scalar)
            && renderOne(session) == std::pair{0.1, 100.0},
        "C56 trigger should restart only on a rising-positive edge");
    session.resetTransport();
    require(
        renderOne(session) == std::pair{0.1, 100.0}
            && renderOne(session) == std::pair{0.5, 200.0},
        "C56 transport reset should clear cursor and trigger history");
    session.setTransportSnapshotBeforeRender({
        .epoch = 2,
        .absoluteFrame = 100,
        .playheadFrame = 100,
        .sampleRate = 1000.0,
        .discontinuitySequence = 1,
        .playing = true,
    });
    require(
        renderOne(session) == std::pair{0.1, 100.0},
        "C56 adopted discontinuity should clear cursor and trigger history");
}

void testRealtimeSessionKeepsC56SpectrumOnDiskRateForTheCallback()
{
    auto settings = talas::runtime::RenderSettings{1000.0, 5};
    settings.tableResources = {{"Analysis/Disk", {
        0.1, 1.0, 0.1,
        0.5, 2.0, 0.2,
        0.9, 3.0, 0.3,
    }}};
    settings.eventValues.push_back({
        "C56Rate", 0.5, talas::expr::ValueDomain::Scalar});
    auto document = makeSpectrumOnDiskTrackSelectorDocument({
        {"frequency", "100 hz"},
        {"level", "1"},
        {"rateScale", "0.5"},
        {"trigger", "0"},
        resourceParameter("fileName", "Analysis/Disk"),
        {"analysisFrames", "3"},
        {"nbrPartials", "1"},
        {"firstPartial", "1"},
    });
    document.graph.nodes.push_back(node(
        "rateControl", "talas.constant", {{"value", "!C56Rate"}}));
    document.graph.connections.push_back(connection(
        "rateControl", "value", "source", "rateScale"));
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(
        candidate.ready() && reference.ready()
            && candidate.scheduleEventValue(
                "C56Rate", 1.0,
                talas::expr::ValueDomain::Scalar, 2),
        "C56 segmented rollback fixture should prepare");

    // A spectrum file reads its controls once per callback: the rate
    // change inside the callback waits for the next one.
    std::array<double, 5> actualLeft{};
    std::array<double, 5> actualRight{};
    std::array<double, 5> expectedLeft{};
    std::array<double, 5> expectedRight{};
    std::size_t allocations = 0;
    require(
        renderStereoAndCount(
            candidate, actualLeft, actualRight, allocations)
            && allocations == 0
            && renderStereoAndCount(
                reference, expectedLeft, expectedRight, allocations)
            && allocations == 0
            && actualLeft == expectedLeft
            && actualRight == expectedRight
            && actualLeft.front() == 0.1
            && actualRight.front() == 100.0,
        "C56 segmented callback should keep the rate it started with");
}

void testC60RealtimeSpectrumOnDiskDefersScheduledControlChangesToTheNextCallback()
{
    struct ControlCase
    {
        std::string_view port;
        double initialValue;
        double changedValue;
    };
    constexpr std::array cases{
        ControlCase{"frequency", 100.0, 125.0},
        ControlCase{"level", 1.0, 0.5},
        ControlCase{"rateScale", 1.0, 0.5},
        ControlCase{"trigger", 0.0, 1.0},
        ControlCase{"nbrPartials", 2.0, 1.0},
        ControlCase{"firstPartial", 1.0, 2.0},
    };

    for (const auto& controlCase : cases)
    {
        auto settings = talas::runtime::RenderSettings{1000.0, 5};
        settings.tableResources = {{"Analysis/Disk", {
            0.2, 1.0, 0.1,
            0.4, 2.0, 0.2,
            0.6, 3.0, 0.3,
            0.8, 1.5, 0.15,
            1.0, 2.5, 0.25,
            1.2, 3.5, 0.35,
        }}};
        settings.eventValues.push_back({
            "C60Control", controlCase.initialValue,
            talas::expr::ValueDomain::Scalar,
        });
        auto document = makeSpectrumOnDiskTrackSelectorDocument({
            {"frequency", "100 hz"},
            {"level", "1"},
            {"rateScale", "1"},
            {"trigger", "0"},
            resourceParameter("fileName", "Analysis/Disk"),
            {"analysisFrames", "2"},
            {"analysisFrequency", "100 hz"},
            {"nbrPartials", "2"},
            {"firstPartial", "1"},
        });
        document.graph.nodes.push_back(node(
            "control", "talas.constant", {{"value", "!C60Control"}}));
        document.graph.connections.push_back(connection(
            "control", "value", "source",
            std::string{controlCase.port}));
        const auto graph = compile(document, settings);
        talas::runtime::RealtimeRenderSession candidate(graph);
        talas::runtime::RealtimeRenderSession reference(graph);
        require(
            candidate.ready() && reference.ready()
                && candidate.scheduleEventValue(
                    "C60Control", controlCase.changedValue,
                    talas::expr::ValueDomain::Scalar, 2),
            std::string{"C60 scheduled "}
                + std::string{controlCase.port}
                + " transaction fixture should prepare");

        std::array<double, 5> actualLeft{};
        std::array<double, 5> actualRight{};
        std::array<double, 5> expectedLeft{};
        std::array<double, 5> expectedRight{};
        std::size_t allocations = 0;
        require(
            renderStereoAndCount(
                candidate, actualLeft, actualRight, allocations)
                && allocations == 0
                && renderStereoAndCount(
                    reference, expectedLeft, expectedRight, allocations)
                && allocations == 0
                && actualLeft == expectedLeft
                && actualRight == expectedRight,
            std::string{"C60 scheduled "}
                + std::string{controlCase.port}
                + " change should wait for the next callback");
    }
}

