void testC59RealtimeSpectrumInRamRejectsForgedParameterAuthority()
{
    talas::runtime::RenderSettings settings{1000.0, 3};
    settings.tableResources.push_back({"Analysis/RAM", {
        0.2, 1.0, 0.1,
        0.4, 2.0, 0.2,
    }});
    auto graph = compile(
        makeSpectrumInRamTrackSelectorDocument({
            resourceParameter("analysis", "Analysis/RAM"),
            {"analysisFrequency", "125 hz"},
        }),
        std::move(settings));
    auto forgedPlan = graph.plan();
    const auto source = std::ranges::find(
        forgedPlan.steps,
        std::string_view{"source"},
        &talas::runtime::CompileStep::nodeId);
    require(
        source != forgedPlan.steps.end()
            && source->parameters.size() == 9,
        "C59 forged authority fixture should expose the exact source parameter vector");
    std::swap(source->parameters[5], source->parameters[6]);
    talas::runtime::RealtimeRenderSession forged(
        talas::runtime::PreparedRuntimeGraph{
            std::move(forgedPlan), graph.renderSettings()});
    require(
        !forged.ready(),
        "C59 prepared SpectrumInRAM should reject reordered metadata/count authority");
}

