void testC58RealtimeSpectrumInRamControlsHoldForEachPublicCallback()
{
    const std::array cases{
        std::pair{"frequency", std::pair{100.0, 200.0}},
        std::pair{"level", std::pair{0.5, 1.0}},
        std::pair{"timeIndex", std::pair{-1.0, 1.0}},
        std::pair{"nbrPartials", std::pair{2.0, 1.0}},
        std::pair{"firstPartial", std::pair{1.0, 2.0}},
    };
    for (const auto& [port, values] : cases)
    {
        const auto eventName = std::string("C58_") + port;
        auto document = makeSpectrumInRamTrackSelectorDocument({
            {"frequency", "100 hz"}, {"level", "0.5"},
            {"timeIndex", "-1"},
            resourceParameter("analysis", "Analysis/RAM"),
            {"analysisFrames", "2"}, {"nbrPartials", "2"},
            {"firstPartial", "1"},
        });
        document.graph.nodes.push_back(node(
            "control", "talas.constant", {{"value", "!" + eventName}}));
        document.graph.connections.push_back(connection(
            "control", "value", "source", port));
        auto settings = talas::runtime::RenderSettings{1000.0, 4};
        settings.eventValues.push_back({
            eventName, values.first, talas::expr::ValueDomain::Scalar});
        settings.tableResources.push_back({"Analysis/RAM", {
            1.0, 1.0, 0.1,
            0.5, 2.0, 0.2,
            0.25, 3.0, 0.3,
            0.125, 4.0, 0.4,
        }});
        auto graph = compile(document, std::move(settings));
        talas::runtime::RealtimeRenderSession session(graph);
        talas::runtime::RealtimeRenderSession reference(graph);
        require(
            session.ready() && reference.ready()
                && session.scheduleEventValue(
                    eventName,
                    values.second,
                    talas::expr::ValueDomain::Scalar,
                    2),
            "C58 scheduled callback-control fixture should prepare");
        std::array<double, 4> left{1.0, 1.0, 1.0, 1.0};
        std::array<double, 4> right{1.0, 1.0, 1.0, 1.0};
        std::array<double, 4> expectedLeft{};
        std::array<double, 4> expectedRight{};
        std::size_t allocations = 0;
        require(
            renderStereoAndCount(session, left, right, allocations)
                && allocations == 0
                && renderStereoAndCount(reference, expectedLeft, expectedRight, allocations)
                && left == expectedLeft
                && right == expectedRight,
            std::string("C58 SpectrumInRAM should keep its ")
                + port + " through a public callback that changes it");
    }

    auto document = makeSpectrumInRamTrackSelectorDocument({
        {"frequency", "100 hz"}, {"level", "0.5"},
        {"timeIndex", "-1"},
        resourceParameter("analysis", "Analysis/RAM"),
        {"analysisFrames", "2"}, {"nbrPartials", "2"},
        {"firstPartial", "1"},
    });
    document.graph.nodes.push_back(node(
        "control", "talas.constant", {{"value", "!C58TimeIndex"}}));
    document.graph.connections.push_back(connection(
        "control", "value", "source", "timeIndex"));
    auto settings = talas::runtime::RenderSettings{1000.0, 2};
    settings.eventValues.push_back({
        "C58TimeIndex", -1.0, talas::expr::ValueDomain::Scalar});
    settings.tableResources.push_back({"Analysis/RAM", {
        1.0, 1.0, 0.1,
        0.5, 2.0, 0.2,
        0.25, 3.0, 0.3,
        0.125, 4.0, 0.4,
    }});
    auto graph = compile(document, std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    std::array<double, 2> first{};
    std::array<double, 2> firstRight{};
    std::array<double, 2> second{};
    std::array<double, 2> secondRight{};
    std::size_t allocations = 0;
    require(session.ready(), "C58 callback-boundary fixture should prepare");
    require(
        renderStereoAndCount(session, first, firstRight, allocations)
            && allocations == 0,
        "C58 first public callback should render without allocations");
    require(
        session.updateEventValue(
            "C58TimeIndex", 1.0,
            talas::expr::ValueDomain::Scalar),
        "C58 control should update between public callbacks");
    require(
        renderStereoAndCount(
            session, second, secondRight, allocations)
            && allocations == 0,
        "C58 second public callback should render without allocations");
    requireNear(
        first[0], 0.5, 0.0,
        "C58 first public callback should select normalized -1");
    requireNear(
        second[0], 0.125, 0.0,
        "C58 second public callback should select normalized 1");
}

void testRealtimeSessionUsesConnectedSpectrumInRamControlsWithoutAllocations()
{
    talas::runtime::RenderSettings settings{1000.0, 3};
    settings.tableResources.push_back({"Analysis/RAM", {
        1.0, 1.0, 0.1, 0.25, 2.0, 0.2,
        0.5, 4.0, 0.4, 0.125, 5.0, 0.5,
    }});
    auto document = makeSpectrumInRamTrackSelectorDocument();
    document.graph.nodes[1].parameters[4].expression = "2";
    document.graph.nodes.push_back(node("timeIndex", "talas.constant", {{"value", "0"}}));
    document.graph.nodes.push_back(node("level", "talas.constant", {{"value", "2"}}));
    document.graph.nodes.push_back(node("frequency", "talas.constant", {{"value", "200"}}));
    document.graph.nodes.push_back(node("nbrPartials", "talas.constant", {{"value", "1"}}));
    document.graph.nodes.push_back(node("firstPartial", "talas.constant", {{"value", "2"}}));
    document.graph.connections.push_back(connection("timeIndex", "value", "source", "timeIndex"));
    document.graph.connections.push_back(connection("level", "value", "source", "level"));
    document.graph.connections.push_back(connection("frequency", "value", "source", "frequency"));
    document.graph.connections.push_back(connection("nbrPartials", "value", "source", "nbrPartials"));
    document.graph.connections.push_back(connection("firstPartial", "value", "source", "firstPartial"));
    auto graph = compile(document, std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 6);
    require(expected.ok(), "offline connected SpectrumInRam reference should render");
    requireNear(expected.mono[0], 0.375, 1.0e-12, "connected SpectrumInRam should override level and partial range");
    requireNear(expected.right[0], 700.0, 1.0e-12, "connected SpectrumInRam should override frequency, timeIndex, and partial range");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 3> left{};
    std::array<double, 3> right{};
    std::size_t allocations = 0;
    require(renderStereoAndCount(session, left, right, allocations), "connected SpectrumInRam block should render");
    require(allocations == 0, "connected SpectrumInRam block should not allocate");
    for (std::size_t frame = 0; frame < left.size(); ++frame)
    {
        requireNear(left[frame], expected.mono[frame], 1.0e-12, "connected SpectrumInRam left should match offline");
        requireNear(right[frame], expected.right[frame], 1.0e-12, "connected SpectrumInRam right should match offline");
    }
}

