void testRealtimeAmplitudeFollowerOwnOverflowPreservesStateAndCallbackPosition()
{
    auto document = makeConnectedAmplitudeFollowerVcaDocument();
    document.graph.nodes.push_back(node(
        "amplitudeControl", "talas.constant", {{"value", "!C88Amplitude"}}));
    document.graph.connections.push_back(connection(
        "amplitudeControl", "value", "source", "amplitude"));

    auto settings = talas::runtime::RenderSettings{4.0, 2};
    settings.eventValues = {
        {"FollowerTimeConstant", 0.25, talas::expr::ValueDomain::Scalar},
        {"FollowerScale", 1.0, talas::expr::ValueDomain::Scalar},
        {"C88Amplitude", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    std::array<double, 2> established{};
    std::array<double, 2> rejected{};
    std::array<double, 2> candidateRetry{};
    std::array<double, 2> referenceRetry{};
    std::size_t allocations = 0;
    require(
        candidate.ready() && reference.ready()
            && renderAndCount(candidate, established, allocations)
            && allocations == 0
            && renderAndCount(reference, established, allocations)
            && allocations == 0
            && candidate.updateEventValue(
                "C88Amplitude", 1.0e200,
                talas::expr::ValueDomain::Scalar)
            && candidate.updateEventValue(
                "FollowerScale", 1.0e200,
                talas::expr::ValueDomain::Scalar),
        "C88 own-overflow fixture should establish follower state");
    rejected.fill(1.0);
    require(
        !renderAndCount(candidate, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 2>{},
        "C88 scaled-amplitude overflow should fail closed without allocation");
    require(
        candidate.updateEventValue(
            "C88Amplitude", 1.0,
            talas::expr::ValueDomain::Scalar)
            && candidate.updateEventValue(
                "FollowerScale", 1.0,
                talas::expr::ValueDomain::Scalar)
            && renderAndCount(candidate, candidateRetry, allocations)
            && allocations == 0
            && renderAndCount(reference, referenceRetry, allocations)
            && allocations == 0
            && candidateRetry == referenceRetry,
        "C88 failed follower callback should preserve envelope and callback position exactly");
}

