void testRealtimeRmsSquaredStaticSnapshotsPartitionsAndReplacementAreExact()
{
    auto document = makeRmsSquaredVcaDocument();
    auto graph = compile(document, talas::runtime::RenderSettings{8.0, 3});
    const auto offline = talas::runtime::renderOffline(graph, 8);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession replacement(graph);
    talas::runtime::RealtimeRenderSession restaged(graph);
    require(
        offline.ok() && candidate.ready() && replacement.ready()
            && restaged.ready(),
        "C87 RMS Squared lifecycle fixtures should prepare");

    auto& plan = const_cast<talas::runtime::RuntimePlan&>(graph.plan());
    const auto operation = std::ranges::find(
        plan.steps, std::string_view{"talas.rmsSquared"},
        &talas::runtime::CompileStep::typeId);
    require(operation != plan.steps.end(),
        "C87 snapshot fixture should expose RMS Squared");
    const auto timeConstant = std::ranges::find(
        operation->parameters, std::string_view{"timeConstant"},
        &talas::runtime::ParameterValue::id);
    const auto scale = std::ranges::find(
        operation->parameters, std::string_view{"scale"},
        &talas::runtime::ParameterValue::id);
    require(
        timeConstant != operation->parameters.end()
            && scale != operation->parameters.end(),
        "C87 snapshot fixture should expose both static control fallbacks");
    timeConstant->value = 4.0;
    scale->value = 0.0;

    std::array<double, 8> partitioned{};
    std::size_t allocations = 0;
    require(
        renderAndCount(candidate,
            std::span<double>{partitioned}.subspan(0, 2), allocations)
            && allocations == 0
            && renderAndCount(candidate,
                std::span<double>{partitioned}.subspan(2, 1), allocations)
            && allocations == 0
            && renderAndCount(candidate,
                std::span<double>{partitioned}.subspan(3, 3), allocations)
            && allocations == 0
            && renderAndCount(candidate,
                std::span<double>{partitioned}.subspan(6, 2), allocations)
            && allocations == 0
            && std::ranges::equal(partitioned, offline.mono),
        "C87 RMS Squared should use immutable smoothing and scale snapshots across irregular callbacks");

    candidate.resetTransport();
    std::array<double, 3> resetOutput{};
    std::array<double, 3> replacementOutput{};
    std::array<double, 3> restagedOutput{};
    require(
        renderAndCount(candidate, resetOutput, allocations)
            && allocations == 0
            && renderAndCount(replacement, replacementOutput, allocations)
            && allocations == 0
            && renderAndCount(restaged, restagedOutput, allocations)
            && allocations == 0
            && resetOutput == replacementOutput
            && replacementOutput == restagedOutput
            && std::ranges::equal(
                resetOutput, std::span<const double>{offline.mono}.first(3)),
        "C87 transport reset, replacement, and restage should begin from identical zero-envelope state");
}

