void testRealtimeRmsSquaredDirectScheduledControlsMatchOfflinePartitions()
{
    auto document = makeRmsSquaredVcaDocument();
    const auto detector = std::ranges::find(
        document.graph.nodes,
        std::string_view{"detector"},
        &talas::project::ProjectNode::instanceId);
    require(detector != document.graph.nodes.end(),
        "C150 direct-schedule fixture should expose RMS Squared");
    detector->parameters = {
        {"timeConstant", "!C150TimeConstant"},
        {"scale", "!C150Scale"},
    };

    auto preparedSettings = talas::runtime::RenderSettings{8.0, 6};
    preparedSettings.eventValues = {
        {"C150TimeConstant", 0.25,
            talas::expr::ValueDomain::Seconds},
        {"C150Scale", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto offlineSettings = preparedSettings;
    offlineSettings.eventValueChanges = {
        {2, "C150TimeConstant", 0.5,
            talas::expr::ValueDomain::Seconds},
        {4, "C150Scale", 0.25,
            talas::expr::ValueDomain::Scalar},
    };
    const auto preparedGraph = compile(document, preparedSettings);
    const auto offlineGraph = compile(document, offlineSettings);
    const auto offline = talas::runtime::renderOffline(offlineGraph, 6);
    talas::runtime::RealtimeRenderSession prepared{preparedGraph};
    require(offline.ok(),
        "C150 direct scheduled RMS Squared controls should render offline");
    require(prepared.ready(),
        "C150 direct scheduled RMS Squared controls should prepare realtime: "
            + std::string{prepared.error()});

    auto forgedAdmission = offlineGraph;
    require(!mutableSettingsForTest(forgedAdmission)
                 .eventValueChanges.empty(),
        "C150 forged scheduled admission fixture should retain direct changes");
    mutableSettingsForTest(forgedAdmission)
        .eventValueChanges.front().value = 0.75;
    const auto rejectedAdmission = talas::runtime::renderOffline(
        forgedAdmission, 6);
    require(!rejectedAdmission.ok()
            && rejectedAdmission.mono.empty(),
        "C150 offline admission should reject a valid post-compile scheduled-value mutation");

    auto forgedDuringSession = offlineGraph;
    talas::runtime::OfflineRenderSession sealedOffline{
        forgedDuringSession};
    mutableSettingsForTest(forgedDuringSession)
        .eventValueChanges.front().value = 0.75;
    const auto rejectedDuringRender = sealedOffline.render(6);
    require(!rejectedDuringRender.ok()
            && rejectedDuringRender.mono.empty(),
        "C150 offline render should recheck exact scheduled-value authority after session construction");

    require(prepared.scheduleEventValue(
                "C150TimeConstant", 0.5,
                talas::expr::ValueDomain::Seconds, 2),
        "C150 prepared RMS Squared should schedule direct timeConstant");
    require(prepared.scheduleEventValue(
                "C150Scale", 0.25,
                talas::expr::ValueDomain::Scalar, 4),
        "C150 prepared RMS Squared should schedule direct scale");

    std::array<double, 6> actual{};
    std::size_t allocations = 0;
    require(
        renderAndCount(
            prepared, std::span<double>{actual}.subspan(0, 1),
            allocations)
            && allocations == 0
            && renderAndCount(
                prepared, std::span<double>{actual}.subspan(1, 2),
                allocations)
            && allocations == 0
            && renderAndCount(
                prepared, std::span<double>{actual}.subspan(3, 3),
                allocations)
            && allocations == 0,
        "C150 prepared direct schedules should render across irregular callbacks without allocation");
    require(
        std::ranges::equal(actual, offline.mono),
        "C150 direct scheduled timeConstant and scale should be bit-identical offline and prepared at exact frames");
}

void testRealtimeRmsSquaredScheduledFailureAndConnectedPrecedenceAreAtomic()
{
    auto directDocument = makeRmsSquaredVcaDocument();
    const auto directDetector = std::ranges::find(
        directDocument.graph.nodes,
        std::string_view{"detector"},
        &talas::project::ProjectNode::instanceId);
    require(directDetector != directDocument.graph.nodes.end(),
        "C150 rollback fixture should expose RMS Squared");
    directDetector->parameters = {
        {"timeConstant", "!C150TimeConstant"},
        {"scale", "!C150Scale"},
    };
    auto directSettings = talas::runtime::RenderSettings{8.0, 4};
    directSettings.eventValues = {
        {"C150TimeConstant", 0.25,
            talas::expr::ValueDomain::Seconds},
        {"C150Scale", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto directGraph = compile(
        directDocument, directSettings);

    auto initialOverflowSettings = directSettings;
    const auto initialTime = std::ranges::find(
        initialOverflowSettings.eventValues,
        std::string_view{"C150TimeConstant"},
        &talas::runtime::EventValueBinding::name);
    require(initialTime
            != initialOverflowSettings.eventValues.end(),
        "C150 overflow fixture should expose direct timeConstant");
    initialTime->value = std::numeric_limits<double>::max();
    talas::runtime::RealtimeRenderSession initialOverflow{
        compile(directDocument, initialOverflowSettings)};
    require(!initialOverflow.ready(),
        "C150 direct initial timeConstant must reject when time times sample rate overflows");

    const auto acceptedBoundary = std::nextafter(
        std::numeric_limits<double>::max() / 8.0, 0.0);
    const auto rejectedBoundary = std::nextafter(
        std::numeric_limits<double>::max() / 8.0,
        std::numeric_limits<double>::max());
    talas::runtime::RealtimeRenderSession boundaryCandidate{
        directGraph};
    talas::runtime::RealtimeRenderSession overflowCandidate{
        directGraph};
    require(boundaryCandidate.ready() && overflowCandidate.ready()
            && boundaryCandidate.scheduleEventValue(
                "C150TimeConstant", acceptedBoundary,
                talas::expr::ValueDomain::Seconds, 3)
            && !overflowCandidate.scheduleEventValue(
                "C150TimeConstant", rejectedBoundary,
                talas::expr::ValueDomain::Seconds, 1)
            && !overflowCandidate.scheduleEventValue(
                "C150TimeConstant",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Seconds, 1),
        "C150 RMS Squared time validator should own the exact derived finite boundary");

    talas::runtime::RealtimeRenderSession candidate{directGraph};
    talas::runtime::RealtimeRenderSession reference{directGraph};
    require(candidate.ready() && reference.ready()
            // A zero time constant saturates at one sample (owner,
            // 2026-10-12).
            && !candidate.scheduleEventValue(
                "C150TimeConstant", std::numeric_limits<double>::quiet_NaN(),
                talas::expr::ValueDomain::Seconds, 1)
            && !candidate.scheduleEventValue(
                "C150Scale", -1.0,
                talas::expr::ValueDomain::Scalar, 2),
        "C150 invalid direct schedules should reject before publication");
    std::array<double, 4> actual{};
    std::array<double, 4> expected{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, actual, allocations)
            && allocations == 0
            && renderAndCount(reference, expected, allocations)
            && allocations == 0
            && actual == expected,
        "C150 rejected direct schedules should consume no RMS state, predecessor, schedule cursor, or callback position");

    auto connectedDocument = makeConnectedRmsSquaredVcaDocument();
    const auto connectedDetector = std::ranges::find(
        connectedDocument.graph.nodes,
        std::string_view{"detector"},
        &talas::project::ProjectNode::instanceId);
    require(connectedDetector != connectedDocument.graph.nodes.end(),
        "C150 connected-precedence fixture should expose RMS fallbacks");
    connectedDetector->parameters = {
        {"timeConstant", "!C150HiddenTime"},
        {"scale", "!C150HiddenScale"},
    };
    auto connectedSettings = talas::runtime::RenderSettings{8.0, 4};
    connectedSettings.eventValues = {
        {"RmsTimeConstant", 0.25,
            talas::expr::ValueDomain::Scalar},
        {"RmsScale", 1.0, talas::expr::ValueDomain::Scalar},
        {"C150HiddenTime", 0.25,
            talas::expr::ValueDomain::Seconds},
        {"C150HiddenScale", 1.0,
            talas::expr::ValueDomain::Scalar},
    };
    const auto connectedGraph = compile(
        connectedDocument, connectedSettings);
    talas::runtime::RealtimeRenderSession connectedCandidate{
        connectedGraph};
    talas::runtime::RealtimeRenderSession connectedReference{
        connectedGraph};
    require(connectedCandidate.ready()
            && connectedReference.ready()
            && connectedCandidate.scheduleEventValue(
                "C150HiddenTime", 0.0,
                talas::expr::ValueDomain::Seconds, 1)
            && connectedCandidate.scheduleEventValue(
                "C150HiddenScale", -1.0,
                talas::expr::ValueDomain::Scalar, 2),
        "C150 connected-precedence hidden-fallback schedules should prepare");
    require(renderAndCount(
                connectedCandidate, actual, allocations)
            && allocations == 0
            && renderAndCount(
                connectedReference, expected, allocations)
            && allocations == 0
            && actual == expected,
        "C150 connected controls should remain authoritative over invalid scheduled direct fallbacks");
}

void testRealtimeRmsSquaredRequiresExactCompilerOwnedAuthority()
{
    const auto document = makeRmsSquaredVcaDocument();
    const auto exact = compile(
        document, talas::runtime::RenderSettings{8.0, 4});
    talas::runtime::RealtimeRenderSession exactSession{exact};
    const auto exactOffline = talas::runtime::renderOffline(exact, 4);
    require(exactSession.ready() && exactOffline.ok(),
        "C150 exact built-in RMS Squared authority should prepare");

    auto subsetRegistry = talas::core::makeBuiltinNodeRegistry();
    subsetRegistry.setNodeTypeOfflineSupport(
        "talas.rmsSquared", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    subsetRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.rmsSquared", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto subset = talas::runtime::compileProject(
        document, subsetRegistry,
        talas::runtime::RenderSettings{8.0, 4});
    require(subset.ok(),
        "C150 explicit custom Subset RMS Squared should compile");
    talas::runtime::RealtimeRenderSession subsetSession{*subset.graph};
    const auto subsetOffline = talas::runtime::renderOffline(
        *subset.graph, 4);
    require(subsetSession.ready() && subsetOffline.ok(),
        "C150 explicit custom Subset should retain C87 compatibility");

    auto statefulDocument = document;
    const auto statefulDetector = std::ranges::find(
        statefulDocument.graph.nodes, std::string_view{"detector"},
        &talas::project::ProjectNode::instanceId);
    require(statefulDetector != statefulDocument.graph.nodes.end(),
        "C150 stateful direct fixture should expose RMS Squared");
    statefulDetector->parameters = {
        {"timeConstant", "previous(0.25 s, 0.25 s)"},
        {"scale", "1"},
    };
    const auto stateful = talas::runtime::compileProject(
        statefulDocument, talas::core::makeBuiltinNodeRegistry(),
        talas::runtime::RenderSettings{8.0, 4});
    require(stateful.ok(),
        "C150 stateful direct RMS fixture should compile before runtime authority rejection");
    talas::runtime::RealtimeRenderSession statefulSession{*stateful.graph};
    const auto statefulOffline = talas::runtime::renderOffline(
        *stateful.graph, 4);
    require(!statefulSession.ready() && !statefulOffline.ok()
            && statefulOffline.mono.empty(),
        "C150 promoted RMS Squared should reject stateful direct parameter authority offline and prepared");

    auto divergentRegistry = talas::core::makeBuiltinNodeRegistry();
    divergentRegistry.setNodeTypeFanInLatencyPolicy(
        "talas.rmsSquared",
        talas::core::FanInLatencyPolicy::PreserveRelative);
    const auto divergent = talas::runtime::compileProject(
        document, divergentRegistry,
        talas::runtime::RenderSettings{8.0, 4});
    require(divergent.ok(),
        "C150 coherent divergent RMS Squared fixture should compile");
    talas::runtime::RealtimeRenderSession divergentSession{
        *divergent.graph};
    const auto divergentOffline = talas::runtime::renderOffline(
        *divergent.graph, 4);
    require(!divergentSession.ready() && !divergentOffline.ok()
            && divergentOffline.mono.empty(),
        "C150 coherent divergent Supported descriptor should not mint built-in RMS Squared authority");

    auto forgedPlan = exact;
    const auto forgedDetector = std::ranges::find(
        mutablePlanForTest(forgedPlan).steps,
        std::string_view{"talas.rmsSquared"},
        &talas::runtime::CompileStep::typeId);
    require(forgedDetector
            != mutablePlanForTest(forgedPlan).steps.end(),
        "C150 forged plan fixture should expose RMS Squared");
    forgedDetector->supportsReset = false;
    talas::runtime::RealtimeRenderSession forgedPlanSession{forgedPlan};
    const auto forgedPlanOffline = talas::runtime::renderOffline(
        forgedPlan, 4);
    require(!forgedPlanSession.ready() && !forgedPlanOffline.ok()
            && forgedPlanOffline.mono.empty(),
        "C150 compiler-owned RMS Squared should reject sealed plan mutation offline and prepared");

    auto forgedSettings = exact;
    ++mutableSettingsForTest(forgedSettings).maxBlockFrames;
    talas::runtime::RealtimeRenderSession forgedSettingsSession{
        forgedSettings};
    const auto forgedSettingsOffline = talas::runtime::renderOffline(
        forgedSettings, 4);
    require(!forgedSettingsSession.ready()
            && !forgedSettingsOffline.ok()
            && forgedSettingsOffline.mono.empty(),
        "C150 compiler-owned RMS Squared should reject sealed settings mutation offline and prepared");
}

void testRealtimeSessionRendersRunningMaxAcrossBlocksWithoutAllocations()
{
    talas::runtime::RenderSettings settings{4.0, 2};
    settings.eventValues.push_back({"RunningValue", 0.25, talas::expr::ValueDomain::Scalar});
    settings.eventValues.push_back({"RunningReset", 0.0, talas::expr::ValueDomain::Scalar});
    auto graph = compile(makeConnectedRunningExtremumVcaDocument(false), std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 2> first{};
    std::array<double, 2> second{};
    std::array<double, 2> third{};
    std::size_t allocations = 0;
    require(renderAndCount(session, first, allocations), "first Running Max block should render");
    require(allocations == 0, "first Running Max block should not allocate");
    require(session.updateEventValue("RunningValue", 0.5, talas::expr::ValueDomain::Scalar),
            "Running Max source Event Value should update");
    require(renderAndCount(session, second, allocations), "second Running Max block should render");
    require(allocations == 0, "second Running Max block should not allocate");
    require(session.updateEventValue("RunningValue", 0.1, talas::expr::ValueDomain::Scalar),
            "Running Max reset source Event Value should update");
    require(session.updateEventValue("RunningReset", 1.0, talas::expr::ValueDomain::Scalar),
            "Running Max reset Event Value should update");
    require(renderAndCount(session, third, allocations), "reset Running Max block should render");
    require(allocations == 0, "reset Running Max block should not allocate");
    requireNear(first[0], 0.0, 1.0e-12, "Running Max initial frame");
    requireNear(first[1], 0.17677669529663687, 1.0e-12, "Running Max should use its first input");
    requireNear(second[0], 0.5, 1.0e-12, "Running Max should retain a larger value across blocks");
    requireNear(second[1], 0.35355339059327373, 1.0e-12, "Running Max should modulate the second carrier frame");
    requireNear(third[0], 0.0, 1.0e-12, "Running Max reset block first carrier frame");
    requireNear(third[1], -0.07071067811865475, 1.0e-12, "Running Max reset should restart at zero before the current sample");
}

void testRealtimeRunningMaxDirectScheduledResetMatchesOfflinePartitions()
{
    auto document = makeConnectedRunningExtremumVcaDocument(false);
    std::erase_if(
        document.graph.nodes,
        [](const talas::project::ProjectNode& graphNode) {
            return graphNode.instanceId == "reset";
        });
    std::erase_if(
        document.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.toNode == "running" && edge.toPort == "reset";
        });
    const auto running = std::ranges::find(
        document.graph.nodes,
        std::string_view{"running"},
        &talas::project::ProjectNode::instanceId);
    require(running != document.graph.nodes.end(),
        "C151 direct-schedule fixture should expose Running Max");
    running->parameters = {{"reset", "!C151Reset"}};

    auto preparedSettings = talas::runtime::RenderSettings{8.0, 6};
    preparedSettings.eventValues = {
        {"RunningValue", 0.75, talas::expr::ValueDomain::Scalar},
        {"C151Reset", 0.0, talas::expr::ValueDomain::Scalar},
    };
    auto offlineSettings = preparedSettings;
    offlineSettings.eventValueChanges = {
        {2, "RunningValue", 0.25, talas::expr::ValueDomain::Scalar},
        {2, "C151Reset", 1.0, talas::expr::ValueDomain::Scalar},
        {3, "C151Reset", 0.0, talas::expr::ValueDomain::Scalar},
    };
    const auto offlineGraph = compile(document, offlineSettings);
    const auto preparedGraph = compile(document, preparedSettings);
    const auto offline = talas::runtime::renderOffline(offlineGraph, 6);
    talas::runtime::RealtimeRenderSession prepared{preparedGraph};
    require(offline.ok(),
        "C151 direct scheduled Running Max reset should render offline");
    require(prepared.ready(),
        "C151 direct scheduled Running Max reset should prepare realtime: "
            + std::string{prepared.error()});

    auto forgedAdmission = offlineGraph;
    require(!mutableSettingsForTest(forgedAdmission)
                 .eventValueChanges.empty(),
        "C151 forged scheduled admission fixture should retain direct changes");
    mutableSettingsForTest(forgedAdmission)
        .eventValueChanges.front().value = 0.5;
    const auto rejectedAdmission = talas::runtime::renderOffline(
        forgedAdmission, 6);
    require(!rejectedAdmission.ok()
            && rejectedAdmission.mono.empty(),
        "C151 offline admission should reject post-compile scheduled-value mutation");

    auto forgedDuringSession = offlineGraph;
    talas::runtime::OfflineRenderSession sealedOffline{forgedDuringSession};
    mutableSettingsForTest(forgedDuringSession)
        .eventValueChanges.front().value = 0.5;
    const auto rejectedDuringRender = sealedOffline.render(6);
    require(!rejectedDuringRender.ok()
            && rejectedDuringRender.mono.empty(),
        "C151 offline render should recheck scheduled-value authority after session construction");
    require(
        prepared.scheduleEventValue(
            "RunningValue", 0.25,
            talas::expr::ValueDomain::Scalar, 2)
            && prepared.scheduleEventValue(
                "C151Reset", 1.0,
                talas::expr::ValueDomain::Scalar, 2)
            && prepared.scheduleEventValue(
                "C151Reset", 0.0,
                talas::expr::ValueDomain::Scalar, 3),
        "C151 prepared Running Max should accept direct reset schedule");

    std::array<double, 6> actual{};
    std::size_t allocations = 0;
    require(
        renderAndCount(
            prepared, std::span<double>{actual}.subspan(0, 1),
            allocations)
            && allocations == 0
            && renderAndCount(
                prepared, std::span<double>{actual}.subspan(1, 2),
                allocations)
            && allocations == 0
            && renderAndCount(
                prepared, std::span<double>{actual}.subspan(3, 3),
                allocations)
            && allocations == 0,
        "C151 prepared scheduled reset should render irregular callbacks without allocation");
    require(
        std::ranges::equal(actual, offline.mono),
        "C151 direct scheduled reset should be bit-identical offline and prepared at exact frames");
}

