void testRealtimeRunningMaxRequiresExactZeroLatencyAncestry()
{
    const auto insertRunningMax = [](
        talas::project::ProjectDocument document,
        std::string_view sourceNode) {
        document.graph.nodes.push_back(node("running", "talas.runningMax"));
        std::erase_if(
            document.graph.connections,
            [&](const talas::core::Connection& edge) {
                return edge.fromNode == sourceNode
                    && edge.toNode == "vca"
                    && edge.toPort == "gain";
            });
        document.graph.connections.push_back(connection(
            std::string{sourceNode}, "value", "running", "value"));
        document.graph.connections.push_back(connection(
            "running", "value", "vca", "gain"));
        return document;
    };

    const auto zeroLatencyGraph = compile(
        insertRunningMax(makeRmsSquaredVcaDocument(), "detector"),
        talas::runtime::RenderSettings{8.0, 4});
    talas::runtime::RealtimeRenderSession zeroLatency{zeroLatencyGraph};
    require(
        zeroLatency.ready(),
        "C151 Running Max should admit exact zero-latency audio-derived ancestry: "
            + std::string{zeroLatency.error()});

    auto controlOnlyDocument =
        makeConnectedRunningExtremumVcaDocument(false);
    std::erase_if(
        controlOnlyDocument.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "source"
                && edge.toNode == "running"
                && edge.toPort == "value";
        });
    controlOnlyDocument.graph.nodes.push_back(node(
        "c151Ramp", "talas.linearRamp", {
            {"duration", "1 s"}, {"start", "0"}, {"end", "1"},
        }));
    controlOnlyDocument.graph.nodes.push_back(node(
        "c151Point", "talas.constant", {{"value", "0.5"}}));
    controlOnlyDocument.graph.nodes.push_back(node(
        "c151Equality", "talas.equality"));
    controlOnlyDocument.graph.connections.push_back(connection(
        "c151Ramp", "value", "c151Equality", "left"));
    controlOnlyDocument.graph.connections.push_back(connection(
        "c151Point", "value", "c151Equality", "right"));
    controlOnlyDocument.graph.connections.push_back(connection(
        "c151Equality", "value", "running", "value"));
    auto controlOnlySettings = talas::runtime::RenderSettings{8.0, 4};
    controlOnlySettings.eventValues = {
        {"RunningReset", 0.0, talas::expr::ValueDomain::Scalar},
    };
    talas::runtime::RealtimeRenderSession controlOnly{
        compile(controlOnlyDocument, controlOnlySettings)};
    require(
        controlOnly.ready(),
        "C151 Running Max should admit exact zero-latency legacy Control ancestry: "
            + std::string{controlOnly.error()});

    const auto variableDocument = insertRunningMax(
        makeFrequencyTrackerVcaDocument(), "tracker");
    auto variableSettings = talas::runtime::RenderSettings{64.0, 64};
    variableSettings.maxRealtimeHistoryFrames = 128;
    const auto variableGraph = compile(
        variableDocument, variableSettings);
    const auto variableTracker = std::ranges::find(
        variableGraph.plan().steps,
        std::string_view{"talas.frequencyTracker"},
        &talas::runtime::CompileStep::typeId);
    const auto variableRunning = std::ranges::find(
        variableGraph.plan().steps,
        std::string_view{"talas.runningMax"},
        &talas::runtime::CompileStep::typeId);
    require(
        variableTracker != variableGraph.plan().steps.end()
            && variableRunning != variableGraph.plan().steps.end()
            && !variableTracker->resolvedLatencyFrames.has_value()
            && variableRunning->resolvedLatencyFrames == 0,
        "C151 variable-latency fixture should isolate hidden ancestry from the zero-latency Running Max target");
    talas::runtime::RealtimeRenderSession variableLatency{variableGraph};
    require(
        !variableLatency.ready()
            && variableLatency.error()
                == "Realtime renderer requires finite Running Extremum controls",
        "C151 Running Max should reject variable-latency audio-derived ancestry");

    auto fixedRegistry = talas::core::makeBuiltinNodeRegistry();
    fixedRegistry.setNodeTypeProcessingContract(
        "talas.frequencyTracker",
        talas::core::NodeStateModel::SessionStateful,
        true,
        {talas::core::LatencyKind::Fixed, 1});
    const auto fixedGraph = talas::runtime::compileProject(
        variableDocument, fixedRegistry, variableSettings);
    require(
        fixedGraph.ok(),
        "C151 fixed-latency audio-derived ancestry fixture should compile");
    const auto fixedTracker = std::ranges::find(
        fixedGraph.graph->plan().steps,
        std::string_view{"talas.frequencyTracker"},
        &talas::runtime::CompileStep::typeId);
    const auto fixedRunning = std::ranges::find(
        fixedGraph.graph->plan().steps,
        std::string_view{"talas.runningMax"},
        &talas::runtime::CompileStep::typeId);
    require(
        fixedTracker != fixedGraph.graph->plan().steps.end()
            && fixedRunning != fixedGraph.graph->plan().steps.end()
            && fixedTracker->resolvedLatencyFrames == 1
            && fixedRunning->resolvedLatencyFrames == 0,
        "C151 fixed-latency fixture should isolate hidden ancestry from the zero-latency Running Max target");
    talas::runtime::RealtimeRenderSession fixedLatency{*fixedGraph.graph};
    require(
        !fixedLatency.ready()
            && fixedLatency.error()
                == "Realtime renderer requires finite Running Extremum controls",
        "C151 Running Max should reject fixed-latency audio-derived ancestry");
}

void testRealtimeRunningMaxRejectedScheduleAndConnectedPrecedenceAreAtomic()
{
    auto directDocument = makeConnectedRunningExtremumVcaDocument(false);
    std::erase_if(
        directDocument.graph.nodes,
        [](const talas::project::ProjectNode& graphNode) {
            return graphNode.instanceId == "reset";
        });
    std::erase_if(
        directDocument.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.toNode == "running" && edge.toPort == "reset";
        });
    const auto directRunning = std::ranges::find(
        directDocument.graph.nodes, std::string_view{"running"},
        &talas::project::ProjectNode::instanceId);
    require(directRunning != directDocument.graph.nodes.end(),
        "C151 rejected-schedule fixture should expose Running Max");
    directRunning->parameters = {{"reset", "!C151Reset"}};
    auto directSettings = talas::runtime::RenderSettings{8.0, 4};
    directSettings.eventValues = {
        {"RunningValue", 0.75, talas::expr::ValueDomain::Scalar},
        {"C151Reset", 0.0, talas::expr::ValueDomain::Scalar},
    };
    const auto directGraph = compile(directDocument, directSettings);
    talas::runtime::RealtimeRenderSession candidate{directGraph};
    talas::runtime::RealtimeRenderSession reference{directGraph};
    require(candidate.ready() && reference.ready()
            && !candidate.scheduleEventValue(
                "C151Reset",
                std::numeric_limits<double>::infinity(),
                talas::expr::ValueDomain::Scalar, 1),
        "C151 non-finite direct reset schedule should reject before publication");
    std::array<double, 4> actual{};
    std::array<double, 4> expected{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, actual, allocations)
            && allocations == 0
            && renderAndCount(reference, expected, allocations)
            && allocations == 0
            && actual == expected,
        "C151 rejected direct reset schedule should consume no state, cursor, or callback position");

    auto connectedDocument = makeConnectedRunningExtremumVcaDocument(false);
    const auto connectedRunning = std::ranges::find(
        connectedDocument.graph.nodes, std::string_view{"running"},
        &talas::project::ProjectNode::instanceId);
    require(connectedRunning != connectedDocument.graph.nodes.end(),
        "C151 connected-precedence fixture should expose Running Max fallback");
    connectedRunning->parameters = {
        {"reset", "!C151HiddenLeft + !C151HiddenRight"},
    };
    auto connectedSettings = talas::runtime::RenderSettings{8.0, 4};
    connectedSettings.eventValues = {
        {"RunningValue", 0.75, talas::expr::ValueDomain::Scalar},
        {"RunningReset", 0.0, talas::expr::ValueDomain::Scalar},
        {"C151HiddenLeft", 0.0, talas::expr::ValueDomain::Scalar},
        {"C151HiddenRight", 0.0, talas::expr::ValueDomain::Scalar},
    };
    const auto connectedGraph = compile(
        connectedDocument, connectedSettings);
    talas::runtime::RealtimeRenderSession connectedCandidate{connectedGraph};
    talas::runtime::RealtimeRenderSession connectedReference{connectedGraph};
    require(connectedCandidate.ready() && connectedReference.ready()
            && connectedCandidate.scheduleEventValue(
                "C151HiddenLeft",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar, 1)
            && connectedCandidate.scheduleEventValue(
                "C151HiddenRight",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar, 1),
        "C151 connected hidden fallback schedules should publish finite operands");
    require(renderAndCount(connectedCandidate, actual, allocations)
            && allocations == 0
            && renderAndCount(connectedReference, expected, allocations)
            && allocations == 0
            && actual == expected,
        "C151 connected reset should remain authoritative over an overflowing hidden fallback expression");
}

