void testRealtimeThresholdFailureRollsBackLatchAndResetRestoresInactiveState()
{
    auto settings = talas::runtime::RenderSettings{4.0, 2};
    settings.eventValues = {
        {"ThresholdValue", 0.5, talas::expr::ValueDomain::Scalar},
        {"ThresholdControl", 0.5, talas::expr::ValueDomain::Scalar},
        {"ThresholdHysteresis", 0.2, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(
        makeConnectedThresholdVcaDocument(), settings);
    talas::runtime::RealtimeRenderSession resetCandidate(graph);
    talas::runtime::RealtimeRenderSession pristine(graph);
    std::array<double, 2> output{};
    std::array<double, 2> resetOutput{};
    std::array<double, 2> pristineOutput{};
    std::size_t allocations = 0;
    require(
        resetCandidate.ready() && pristine.ready()
            && renderAndCount(resetCandidate, output, allocations)
            && allocations == 0
            && resetCandidate.updateEventValue(
                "ThresholdValue", 0.8,
                talas::expr::ValueDomain::Scalar)
            && renderAndCount(resetCandidate, output, allocations)
            && allocations == 0,
        "C66 reset fixture should activate Threshold without callback allocation");
    resetCandidate.resetTransport();
    require(
        renderAndCount(resetCandidate, resetOutput, allocations)
            && allocations == 0
            && renderAndCount(pristine, pristineOutput, allocations)
            && allocations == 0
            && resetOutput == pristineOutput,
        "C66 transport reset should restore the pristine inactive Threshold latch");

    auto failureSettings = settings;
    failureSettings.eventValues[0].value = 0.8;
    const auto failureGraph = compile(
        makeConnectedThresholdVcaDocument(), failureSettings);
    talas::runtime::RealtimeRenderSession candidate(failureGraph);
    talas::runtime::RealtimeRenderSession reference(failureGraph);
    require(
        candidate.ready() && reference.ready()
            && candidate.scheduleEventValue(
                "ThresholdControl",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar,
                1)
            && candidate.scheduleEventValue(
                "ThresholdHysteresis",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar,
                1),
        "C66 rollback fixture should schedule a derived-boundary overflow");
    output.fill(1.0);
    require(
        !renderAndCount(candidate, output, allocations)
            && allocations == 0
            && output == std::array<double, 2>{},
        "C66 derived Threshold overflow should fail closed without callback allocation");
    require(
        candidate.updateEventValue(
            "ThresholdValue", 0.5,
            talas::expr::ValueDomain::Scalar)
            && candidate.updateEventValue(
                "ThresholdControl", 0.5,
                talas::expr::ValueDomain::Scalar)
            && candidate.updateEventValue(
                "ThresholdHysteresis", 0.2,
                talas::expr::ValueDomain::Scalar)
            && reference.updateEventValue(
                "ThresholdValue", 0.5,
                talas::expr::ValueDomain::Scalar),
        "C66 failed callback should permit a valid recovery publication");
    std::array<double, 2> candidateRetry{};
    std::array<double, 2> referenceRetry{};
    require(
        renderAndCount(candidate, candidateRetry, allocations)
            && allocations == 0
            && renderAndCount(reference, referenceRetry, allocations)
            && allocations == 0
            && candidateRetry == referenceRetry,
        "C66 failed callback should restore Threshold and predecessor state exactly");
}

void testRealtimeThresholdRollsBackDownstreamFailureAndRejectsForgedAuthority()
{
    auto document = makeConnectedThresholdVcaDocument();
    document.graph.nodes.push_back(node(
        "formants", "talas.twoFormantElement", {
            {"formant1", "1 hz"}, {"bandwidth1", "0.5 hz"},
            {"scale1", "0.75"}, {"formant2", "2 hz"},
            {"bandwidth2", "0.75 hz"}, {"scale2", "-0.25"},
        }));
    document.graph.nodes.push_back(node(
        "formantControl", "talas.constant", {
            {"value", "!C66DownstreamFormant"},
        }));
    std::erase_if(
        document.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });
    document.graph.connections.push_back(connection(
        "vca", "audioOut", "formants", "audioIn"));
    document.graph.connections.push_back(connection(
        "formantControl", "value", "formants", "formant1"));
    document.graph.connections.push_back(connection(
        "formants", "audioOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.eventValues = {
        {"ThresholdValue", 0.8, talas::expr::ValueDomain::Scalar},
        {"ThresholdControl", 0.5, talas::expr::ValueDomain::Scalar},
        {"ThresholdHysteresis", 0.2, talas::expr::ValueDomain::Scalar},
        {"C66DownstreamFormant", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    std::array<double, 4> failed{};
    std::array<double, 4> candidateRetry{};
    std::array<double, 4> referenceRetry{};
    std::size_t allocations = 0;
    require(
        candidate.ready() && reference.ready()
            && candidate.scheduleEventValue(
                "C66DownstreamFormant", 4.0,
                talas::expr::ValueDomain::Scalar, 2),
        "C66 downstream rollback fixture should prepare and segment");
    failed.fill(1.0);
    require(
        !renderAndCount(candidate, failed, allocations)
            && allocations == 0
            && failed == std::array<double, 4>{},
        "C66 downstream failure should publish no callback audio");
    require(
        candidate.updateEventValue(
            "C66DownstreamFormant", 1.0,
            talas::expr::ValueDomain::Scalar)
            && renderAndCount(candidate, candidateRetry, allocations)
            && allocations == 0
            && renderAndCount(reference, referenceRetry, allocations)
            && allocations == 0
            && candidateRetry == referenceRetry,
        "C66 downstream failure should restore the entry Threshold latch and predecessors");

    const auto expectForgedThresholdRejected =
        [&](auto mutate, std::string_view contract) {
            auto forgedPlan = graph.plan();
            const auto threshold = std::ranges::find(
                forgedPlan.steps,
                std::string_view{"talas.threshold"},
                &talas::runtime::CompileStep::typeId);
            require(threshold != forgedPlan.steps.end(),
                "C66 forged-authority fixture should expose Threshold");
            mutate(*threshold);
            talas::runtime::RealtimeRenderSession forged{
                talas::runtime::PreparedRuntimeGraph{
                    std::move(forgedPlan), graph.renderSettings()}};
            require(!forged.ready(),
                "C66 prepared Threshold should reject forged "
                    + std::string{contract});
        };
    expectForgedThresholdRejected(
        [](auto& step) { step.supportsReset = false; },
        "reset authority");
    expectForgedThresholdRejected(
        [](auto& step) { step.preparedSpectralFrameSize = 64; },
        "spectral frame authority");
    expectForgedThresholdRejected(
        [](auto& step) {
            step.spectrumModifierProbabilityProfile = {0.5};
        },
        "probability-profile authority");
    expectForgedThresholdRejected(
        [](auto& step) {
            step.soundVariableKind =
                talas::project::ProjectSoundVariableKind::SoundCollection;
        },
        "Sound Variable kind authority");
    expectForgedThresholdRejected(
        [](auto& step) { step.parameters.push_back(step.parameters.front()); },
        "duplicate parameter authority");
    expectForgedThresholdRejected(
        [](auto& step) { std::ranges::swap(step.parameters[0], step.parameters[1]); },
        "parameter order authority");
    expectForgedThresholdRejected(
        [](auto& step) {
            step.parameters.front().domain =
                talas::expr::ValueDomain::Hertz;
        },
        "parameter domain authority");
    expectForgedThresholdRejected(
        [](auto& step) { step.parameters.front().expression.reset(); },
        "parameter expression authority");
    expectForgedThresholdRejected(
        [](auto& step) { step.inputs.push_back(step.inputs.front()); },
        "duplicate input authority");

    const auto expectForgedThresholdPlanRejected =
        [&](auto mutate, std::string_view contract) {
            auto forgedPlan = graph.plan();
            const auto threshold = std::ranges::find(
                forgedPlan.steps,
                std::string_view{"talas.threshold"},
                &talas::runtime::CompileStep::typeId);
            require(threshold != forgedPlan.steps.end(),
                "C66 buffer-authority fixture should expose Threshold");
            mutate(*threshold, forgedPlan);
            talas::runtime::RealtimeRenderSession forged{
                talas::runtime::PreparedRuntimeGraph{
                    std::move(forgedPlan), graph.renderSettings()}};
            require(!forged.ready(),
                "C66 prepared Threshold should reject forged "
                    + std::string{contract});
        };
    expectForgedThresholdPlanRejected(
        [](auto& step, auto& plan) {
            const auto value = std::ranges::find(
                step.inputs,
                std::string_view{"value"},
                &talas::runtime::InputBinding::inputPortId);
            require(value != step.inputs.end()
                    && value->bufferIndex < plan.buffers.size(),
                "C66 forged producer fixture should expose the value buffer");
            plan.buffers.push_back(plan.buffers[value->bufferIndex]);
            value->bufferIndex = plan.buffers.size() - 1;
        },
        "self-consistent unproduced input buffer");
    expectForgedThresholdPlanRejected(
        [](auto& step, auto& plan) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const auto& buffer) {
                    return buffer.nodeId == step.nodeId
                        && buffer.scopeId == step.scopeId
                        && buffer.portId == "value"
                        && buffer.type == talas::core::PortType::Control;
                });
            require(output != plan.buffers.end(),
                "C66 forged output fixture should expose Threshold value");
            plan.buffers.push_back(*output);
        },
        "duplicate output buffer");
}

