void testLinearLogPairRoundTripsOfflineAndPrepared()
{
    auto roundTrip = makeUnaryControlMathVcaDocument(
        "talas.linearToLog", "2.71828182845904523536");
    roundTrip.graph.nodes.push_back(node("inverse", "talas.logToLinear"));
    roundTrip.graph.connections[2] = connection(
        "math", "value", "inverse", "value");
    roundTrip.graph.connections.push_back(connection(
        "inverse", "value", "vca", "gain"));
    const std::array documents{
        makeUnaryControlMathVcaDocument(
            "talas.linearToLog", "2.71828182845904523536"),
        makeUnaryControlMathVcaDocument("talas.logToLinear", "1"),
        makeUnaryControlMathVcaDocument("talas.logToLinear", "-1"),
        std::move(roundTrip),
    };
    const std::array expectedGains{
        1.0, std::numbers::e, 1.0 / std::numbers::e, std::numbers::e};
    for (std::size_t candidate = 0; candidate < documents.size(); ++candidate)
    {
        const auto saved = talas::project::serializeProjectDocument(
            documents[candidate], talas::core::makeBuiltinNodeRegistry());
        const auto reopened = talas::project::parseProjectDocument(saved);
        require(reopened.ok()
                && talas::project::serializeProjectDocument(
                       reopened.document,
                       talas::core::makeBuiltinNodeRegistry()) == saved,
            "LinearToLog and LogToLinear Sounds should save and reopen");
        const auto graph = compile(
            reopened.document, talas::runtime::RenderSettings{4.0, 3});
        const auto offline = talas::runtime::renderOffline(graph, 6);
        require(offline.ok() && offline.mono.size() == 6,
            "linear/log candidate should render offline");
        for (std::size_t frame = 0; frame < 6; ++frame)
            requireNear(
                offline.mono[frame],
                std::sin(std::numbers::pi * frame / 4.0)
                    * expectedGains[candidate],
                1e-12,
                "linear/log candidate should apply analytic gain");
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(),
            "linear/log candidate should prepare: "
                + std::string{session.error()});
        std::array<double, 6> prepared{};
        std::size_t allocations = 0;
        std::size_t offset = 0;
        for (const auto count : {std::size_t{1}, std::size_t{2}, std::size_t{3}})
        {
            require(renderAndCount(
                        session,
                        std::span<double>{prepared}.subspan(offset, count),
                        allocations)
                    && allocations == 0,
                "linear/log prepared callback should not allocate");
            offset += count;
        }
        for (std::size_t frame = 0; frame < prepared.size(); ++frame)
            requireNear(prepared[frame], offline.mono[frame], 1e-12,
                "linear/log prepared and offline outputs should match");
    }

    auto changingSettings = talas::runtime::RenderSettings{4.0, 6};
    changingSettings.eventValues = {{
        "LogValue", 1.0, talas::expr::ValueDomain::Scalar}};
    auto offlineSettings = changingSettings;
    offlineSettings.eventValueChanges = {
        {2, "LogValue", std::numbers::e,
            talas::expr::ValueDomain::Scalar},
        {4, "LogValue", 4.0,
            talas::expr::ValueDomain::Scalar},
    };
    const auto changingDocument = makeUnaryControlMathVcaDocument(
        "talas.linearToLog", "!LogValue");
    const auto changingOffline = talas::runtime::renderOffline(
        compile(changingDocument, offlineSettings), 6);
    require(changingOffline.ok() && changingOffline.mono.size() == 6,
        "LinearToLog should render changing positive controls offline");
    const std::array changingGains{
        0.0, 0.0, 1.0, 1.0, std::log(4.0), std::log(4.0)};
    for (std::size_t frame = 0; frame < changingGains.size(); ++frame)
        requireNear(changingOffline.mono[frame],
            std::sin(std::numbers::pi * frame / 4.0)
                * changingGains[frame], 1e-12,
            "LinearToLog should transform each scheduled control value");
    talas::runtime::RealtimeRenderSession changingPrepared(
        compile(changingDocument, changingSettings));
    require(changingPrepared.ready(),
        "LinearToLog should prepare changing controls: "
            + std::string{changingPrepared.error()});
    require(changingPrepared.scheduleEventValue(
                "LogValue", std::numbers::e,
                talas::expr::ValueDomain::Scalar, 2)
            && changingPrepared.scheduleEventValue(
                "LogValue", 4.0,
                talas::expr::ValueDomain::Scalar, 4),
        "LinearToLog should prepare scheduled positive controls");
    std::array<double, 6> changingOutput{};
    std::size_t changingAllocations = 0;
    require(renderAndCount(
                changingPrepared,
                std::span<double>{changingOutput}.first(3),
                changingAllocations)
            && renderAndCount(
                changingPrepared,
                std::span<double>{changingOutput}.last(3),
                changingAllocations)
            && changingAllocations == 0,
        "LinearToLog scheduled callbacks should not allocate");
    for (std::size_t frame = 0; frame < changingOutput.size(); ++frame)
        requireNear(changingOutput[frame], changingOffline.mono[frame],
            1e-12, "LinearToLog scheduled controls should match offline");

    for (const auto [typeId, value] : {
             std::pair{"talas.linearToLog", "0"},
             std::pair{"talas.linearToLog", "-1"},
             std::pair{"talas.logToLinear", "1000"},
         })
    {
        const auto graph = compile(
            makeUnaryControlMathVcaDocument(typeId, value),
            talas::runtime::RenderSettings{4.0, 3});
        require(!talas::runtime::renderOffline(graph, 3).ok(),
            "linear/log invalid domain or overflow should fail offline");
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(),
            "linear/log invalid runtime value should still prepare");
        std::array<double, 3> output{99.0, 99.0, 99.0};
        std::size_t allocations = 0;
        require(!renderAndCount(session, output, allocations)
                && allocations == 0
                && output == std::array<double, 3>{},
            "linear/log invalid callback should publish no output");
    }
}

void testLinearLogPairProcessesAudioAndControlTogether()
{
    constexpr std::array<float, 6> positive{
        0.25F, 0.5F, 1.0F, 2.0F, 4.0F, 8.0F};
    constexpr std::array<float, 6> logarithmic{
        -2.0F, -1.0F, 0.0F, 1.0F, 2.0F, 3.0F};
    for (std::size_t variant = 0; variant < 4; ++variant)
    {
        const auto& input = variant == 1 ? logarithmic : positive;
        const auto document = makeLinearLogAudioDocument(
            variant == 1 ? "talas.logToLinear" : "talas.linearToLog",
            variant == 2, variant == 3);
        const auto saved = talas::project::serializeProjectDocument(
            document, talas::core::makeBuiltinNodeRegistry());
        const auto reopened = talas::project::parseProjectDocument(saved);
        require(reopened.ok()
                && talas::project::serializeProjectDocument(
                       reopened.document,
                       talas::core::makeBuiltinNodeRegistry()) == saved,
            "linear/log Audio Sound should save and reopen");
        talas::runtime::RenderSettings settings{4.0, 3};
        settings.audioInputChannels = {{
            1, std::vector<double>(input.begin(), input.end())}};
        const auto graph = compile(reopened.document, settings);
        const auto offline = talas::runtime::renderOffline(graph, input.size());
        require(offline.ok() && offline.mono.size() == input.size(),
            "linear/log Audio Sound should render offline"
                + (offline.diagnostics.empty()
                    ? std::string{}
                    : ": " + offline.diagnostics.front().message));
        for (std::size_t frame = 0; frame < input.size(); ++frame)
        {
            const auto expected = variant == 1
                ? std::exp(static_cast<double>(input[frame]))
                : variant == 2
                ? static_cast<double>(input[frame])
                : std::log(static_cast<double>(input[frame]));
            requireNear(offline.mono[frame], expected, 1e-12,
                "linear/log Audio Sound should apply its analytic transform");
        }
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(),
            "linear/log Audio Sound should prepare: "
                + std::string{session.error()});
        std::array<double, 6> prepared{};
        std::size_t allocations = 0;
        std::size_t offset = 0;
        for (const auto count : {
                 std::size_t{1}, std::size_t{2}, std::size_t{3}})
        {
            std::array<const float*, 1> channels{
                input.data() + offset};
            require(renderMonoInputAndCount(
                        session,
                        {channels.data(), channels.size()},
                        std::span<double>{prepared}.subspan(offset, count),
                        allocations)
                    && allocations == 0,
                "linear/log Audio callback should not allocate");
            offset += count;
        }
        for (std::size_t frame = 0; frame < prepared.size(); ++frame)
            requireNear(prepared[frame], offline.mono[frame], 1e-12,
                "linear/log Audio prepared output should match offline");
    }

    constexpr std::array<float, 3> invalid{1.0F, 2.0F, -1.0F};
    talas::runtime::RenderSettings settings{4.0, invalid.size()};
    settings.audioInputChannels = {{
        1, std::vector<double>(invalid.begin(), invalid.end())}};
    const auto graph = compile(
        makeLinearLogAudioDocument("talas.linearToLog"), settings);
    require(!talas::runtime::renderOffline(graph, invalid.size()).ok(),
        "linear/log Audio should reject a late nonpositive sample offline");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(),
        "linear/log invalid Audio input should still prepare");
    std::array<const float*, 1> channels{invalid.data()};
    std::array<double, 3> output{99.0, 99.0, 99.0};
    std::size_t allocations = 0;
    require(!renderMonoInputAndCount(
                session, {channels.data(), channels.size()},
                output, allocations)
            && allocations == 0
            && output == std::array<double, 3>{},
        "linear/log Audio failure should publish no callback prefix");
}

void testRealtimeArcTanRejectsLateNonFiniteInputAndRepairsRetry()
{
    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.eventValues = {{
        "C120Input", -0.75, talas::expr::ValueDomain::Scalar}};
    const auto graph = compile(
        makeLateInvalidArcTanVcaDocument(), settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession pristine(graph);
    require(candidate.ready() && pristine.ready(),
        "C120 late-invalid ArcTan fixtures should prepare");
    require(candidate.scheduleEventValue(
                "C120Input", std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar, 2),
        "C120 ArcTan should admit a late finite input whose predecessor overflows");

    std::array<double, 4> actual;
    actual.fill(120.0);
    std::size_t allocations = 0;
    require(!renderAndCount(candidate, actual, allocations)
            && allocations == 0
            && actual == std::array<double, 4>{},
        "C120 ArcTan should reject a late non-finite predecessor without publishing a callback prefix");
    actual.fill(120.0);
    require(!renderAndCount(candidate, actual, allocations)
            && allocations == 0
            && actual == std::array<double, 4>{},
        "C120 repeated retry should encounter the restored late invalid Event Value without publication");

    require(candidate.updateEventValue(
                "C120Input", -0.5,
                talas::expr::ValueDomain::Scalar)
            && pristine.updateEventValue(
                "C120Input", -0.5,
                talas::expr::ValueDomain::Scalar),
        "C120 repaired-retry fixtures should admit the finite recovery value");
    std::array<double, 4> expected{};
    require(renderAndCount(candidate, actual, allocations),
        "C120 repaired ArcTan candidate retry should render");
    require(allocations == 0,
        "C120 repaired ArcTan retry should not allocate");
    require(renderAndCount(pristine, expected, allocations),
        "C120 pristine ArcTan reference should render");
    require(allocations == 0,
        "C120 pristine ArcTan reference should not allocate");
    require(actual == expected,
        "C120 repaired ArcTan retry should restore the scheduled Event Value cursor and exact output");
}

void testRealtimeArcTanRequiresExactCompilerOwnedAuthority()
{
    const auto compiled = compile(
        makeUnaryControlMathVcaDocument(
            "talas.arcTan", "-0.5"),
        talas::runtime::RenderSettings{4.0, 4});
    talas::runtime::RealtimeRenderSession publiclyConstructed(
        talas::runtime::PreparedRuntimeGraph{
            compiled.plan(), compiled.renderSettings()});
    require(!publiclyConstructed.ready()
            && publiclyConstructed.error()
                == "Realtime renderer requires compiler-owned ArcTan execution authority",
        "C120 ArcTan should require privately compiler-sealed execution authority");

    const auto requireRejected = [](auto forged,
                                    std::string_view context) {
        talas::runtime::RealtimeRenderSession rejected(forged);
        require(!rejected.ready(),
            "C120 ArcTan authority should reject "
                + std::string{context});
    };
    const auto findArcTan = [](auto& graph) -> auto& {
        auto& plan = mutablePlanForTest(graph);
        const auto step = std::ranges::find(
            plan.steps, std::string_view{"talas.arcTan"},
            &talas::runtime::CompileStep::typeId);
        require(step != plan.steps.end(),
            "C120 authority fixture should expose ArcTan");
        return *step;
    };

    auto forgedSupport = compiled;
    findArcTan(forgedSupport).preparedRealtimeSupport =
        talas::core::ExecutionSupport::Subset;
    requireRejected(std::move(forgedSupport),
        "prepared-support mutation");

    auto forgedParameter = compiled;
    findArcTan(forgedParameter).parameters.push_back({});
    requireRejected(std::move(forgedParameter),
        "parameter-shape mutation");

    auto forgedScope = compiled;
    ++findArcTan(forgedScope).scopeId;
    requireRejected(std::move(forgedScope),
        "execution-scope mutation");

    auto forgedAncestry = compiled;
    findArcTan(forgedAncestry).structuralSourcePath += "/forged";
    requireRejected(std::move(forgedAncestry),
        "structural-ancestry mutation");

    auto forgedLatency = compiled;
    findArcTan(forgedLatency).cumulativeOutputLatencyFrames = 1;
    requireRejected(std::move(forgedLatency),
        "latency mutation");

    auto forgedInput = compiled;
    auto& inputStep = findArcTan(forgedInput);
    require(inputStep.inputs.size() == 1,
        "C120 authority fixture should expose one value input");
    ++inputStep.inputs.front().sourceScopeId;
    requireRejected(std::move(forgedInput),
        "input-binding mutation");

    auto forgedProducerIdentity = compiled;
    findArcTan(forgedProducerIdentity)
        .inputs.front().sourceNodeId += "Forged";
    requireRejected(std::move(forgedProducerIdentity),
        "input producer-identity mutation");

    auto forgedInputCapacity = compiled;
    auto& inputCapacityPlan = mutablePlanForTest(forgedInputCapacity);
    const auto inputCapacityIndex =
        findArcTan(forgedInputCapacity).inputs.front().bufferIndex;
    require(inputCapacityIndex < inputCapacityPlan.buffers.size(),
        "C120 authority fixture should expose the value input buffer");
    ++inputCapacityPlan.buffers[inputCapacityIndex].frames;
    requireRejected(std::move(forgedInputCapacity),
        "input-buffer capacity mutation");

    auto forgedInputType = compiled;
    auto& inputTypePlan = mutablePlanForTest(forgedInputType);
    const auto inputTypeIndex =
        findArcTan(forgedInputType).inputs.front().bufferIndex;
    require(inputTypeIndex < inputTypePlan.buffers.size(),
        "C120 authority fixture should expose a typed value input buffer");
    inputTypePlan.buffers[inputTypeIndex].type = talas::core::PortType::Audio;
    requireRejected(std::move(forgedInputType),
        "input-buffer type mutation");

    auto forgedOutput = compiled;
    auto& outputPlan = mutablePlanForTest(forgedOutput);
    const auto output = std::ranges::find_if(
        outputPlan.buffers,
        [](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == "math"
                && buffer.portId == "value";
        });
    require(output != outputPlan.buffers.end(),
        "C120 authority fixture should expose the value output buffer");
    ++output->frames;
    requireRejected(std::move(forgedOutput),
        "output-buffer mutation");

    auto forgedOutputIdentity = compiled;
    auto& outputIdentityPlan = mutablePlanForTest(forgedOutputIdentity);
    const auto outputIdentity = std::ranges::find_if(
        outputIdentityPlan.buffers,
        [](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == "math"
                && buffer.portId == "value";
        });
    require(outputIdentity != outputIdentityPlan.buffers.end(),
        "C120 authority fixture should expose output identity");
    outputIdentity->nodeId += "Forged";
    requireRejected(std::move(forgedOutputIdentity),
        "output-buffer identity mutation");

    auto forgedDuplicateOutput = compiled;
    auto& duplicateOutputPlan = mutablePlanForTest(forgedDuplicateOutput);
    const auto duplicateOutput = std::ranges::find_if(
        duplicateOutputPlan.buffers,
        [](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == "math"
                && buffer.portId == "value";
        });
    require(duplicateOutput != duplicateOutputPlan.buffers.end(),
        "C120 authority fixture should expose a duplicable output shape");
    duplicateOutputPlan.buffers.push_back(*duplicateOutput);
    requireRejected(std::move(forgedDuplicateOutput),
        "duplicate output-buffer shape mutation");

    auto forgedResource = compiled;
    mutableSettingsForTest(forgedResource).tableResources.push_back(
        {"Tables/C120Unrelated", {9.0}});
    requireRejected(std::move(forgedResource),
        "unrelated-resource mutation");

    auto coherentlyForged = compiled;
    auto& coherentSettings = mutableSettingsForTest(coherentlyForged);
    auto& coherentPlan = mutablePlanForTest(coherentlyForged);
    ++coherentSettings.maxBlockFrames;
    for (auto& buffer : coherentPlan.buffers)
        ++buffer.frames;
    requireRejected(std::move(coherentlyForged),
        "coherent plan/settings buffer-capacity mutation");

}

void testArcTanLifecycleCopiesAndPartitionsMatchExactly()
{
    const auto graph = compile(
        makeUnaryControlMathVcaDocument(
            "talas.arcTan", "-0.75"),
        talas::runtime::RenderSettings{8.0, 5});
    const auto copiedGraph = graph;
    talas::runtime::OfflineRenderSession offline(graph);
    talas::runtime::OfflineRenderSession copiedOffline(copiedGraph);
    talas::runtime::RealtimeRenderSession realtime(graph);
    talas::runtime::RealtimeRenderSession copiedRealtime(copiedGraph);
    require(realtime.ready() && copiedRealtime.ready(),
        "C120 original and copied prepared lifecycle fixtures should prepare: "
            + std::string{realtime.ready()
                ? copiedRealtime.error()
                : realtime.error()});

    for (const auto frames : std::array<std::size_t, 6>{
             1, 5, 2, 4, 3, 5})
    {
        const auto expected = offline.render(frames);
        const auto copied = copiedOffline.render(frames);
        std::vector<double> actual(frames);
        std::vector<double> copiedActual(frames);
        std::size_t allocations = 0;
        require(expected.ok() && copied.ok()
                && copied.mono == expected.mono
                && renderAndCount(realtime, actual, allocations)
                && renderAndCount(
                    copiedRealtime, copiedActual, allocations)
                && allocations == 0
                && actual == expected.mono
                && copiedActual == expected.mono,
            "C120 ArcTan offline/prepared copies should match exactly across irregular partitions");
    }

    std::size_t allocations = 0;
    require(renderEmptyMonoAndCount(realtime, allocations)
            && renderEmptyMonoAndCount(copiedRealtime, allocations)
            && allocations == 0,
        "C120 zero-frame callback should preserve original and copied prepared ArcTan execution");

    offline.reset();
    copiedOffline.reset();
    realtime.resetTransport();
    copiedRealtime.resetTransport();
    const auto expected = offline.render(5);
    const auto copied = copiedOffline.render(5);
    talas::runtime::RealtimeRenderSession replacement(graph);
    std::array<double, 5> actual{};
    std::array<double, 5> copiedActual{};
    std::array<double, 5> replaced{};
    require(replacement.ready()
            && expected.ok() && copied.ok()
            && copied.mono == expected.mono
            && renderAndCount(realtime, actual, allocations)
            && renderAndCount(
                copiedRealtime, copiedActual, allocations)
            && renderAndCount(replacement, replaced, allocations)
            && allocations == 0
            && std::ranges::equal(actual, expected.mono)
            && std::ranges::equal(copiedActual, expected.mono)
            && std::ranges::equal(replaced, expected.mono),
        "C120 reset, prepared copies, replacement, and copied offline graph should reproduce a fresh exact stream");
}

