void testRealtimeSessionRendersProductControlWithoutAllocations()
{
    auto graph = compile(
        makeProductVcaDocument("2", "0.25"),
        talas::runtime::RenderSettings{4.0, 4});
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 4> output{};
    std::size_t allocations = 0;
    require(renderAndCount(session, output, allocations),
        "C123 finite Product block should render");
    require(allocations == 0,
        "C123 finite Product block should not allocate");
    const auto expected = talas::runtime::renderOffline(graph, output.size());
    require(expected.ok()
            && std::ranges::equal(output, expected.mono),
        "C123 prepared Product should match offline exactly");
}

