void testRealtimeAddRejectsLateOverflowAndRepairsExactRetry()
{
    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.eventValues = {{
        "C128Left", -std::numeric_limits<double>::max(),
        talas::expr::ValueDomain::Scalar}};
    const auto graph = compile(
        makeAddVcaDocument(
            "!C128Left", "1.7976931348623157e308"),
        settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession pristine(graph);
    require(candidate.ready() && pristine.ready(),
        "C128 late-overflow Add fixtures should prepare");
    require(candidate.scheduleEventValue(
                "C128Left", std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar, 2),
        "C128 Add should admit the finite value whose late sum overflows");

    std::array<double, 4> actual;
    actual.fill(128.0);
    std::size_t allocations = 0;
    require(!renderAndCount(candidate, actual, allocations)
            && allocations == 0
            && actual == std::array<double, 4>{},
        "C128 late Add overflow should publish no callback prefix");
    actual.fill(128.0);
    require(!renderAndCount(candidate, actual, allocations)
            && allocations == 0
            && actual == std::array<double, 4>{},
        "C128 repeated Add overflow should restore the same scheduled failure");

    constexpr auto repaired = -8.0e307;
    require(candidate.updateEventValue(
                "C128Left", repaired,
                talas::expr::ValueDomain::Scalar)
            && pristine.updateEventValue(
                "C128Left", repaired,
                talas::expr::ValueDomain::Scalar),
        "C128 repaired Add fixtures should admit a finite current value");
    std::array<double, 4> expected{};
    require(renderAndCount(candidate, actual, allocations)
            && renderAndCount(pristine, expected, allocations)
            && allocations == 0 && actual == expected,
        "C128 repaired Add retry should restore scheduler, producers, frame, and output exactly");
}

void testRealtimeAddRequiresExactCompilerOwnedAuthority()
{
    const auto document = makeAddVcaDocument("0.25", "0.5");
    const auto compiled = compile(
        document, talas::runtime::RenderSettings{4.0, 4});
    talas::runtime::RealtimeRenderSession publiclyConstructed(
        talas::runtime::PreparedRuntimeGraph{
            compiled.plan(), compiled.renderSettings()});
    require(!publiclyConstructed.ready()
            && publiclyConstructed.error()
                == "Realtime renderer requires compiler-owned Add execution authority",
        "C128 Add should require privately compiler-sealed execution authority");

    const auto requireCustomRegistryRejected = [&] (
        talas::core::NodeRegistry registry,
        std::string_view mutation) {
        const auto forged = talas::runtime::compileProject(
            document,
            registry,
            talas::runtime::RenderSettings{4.0, 4});
        require(forged.ok(),
            "C128 custom-registry fixture should compile "
                + std::string{mutation});
        talas::runtime::RealtimeRenderSession session(*forged.graph);
        require(!session.ready(),
            "C128 Add should reject compiler-sealed custom registry "
                + std::string{mutation});
    };
    {
        auto registry = talas::core::makeBuiltinNodeRegistry();
        registry.setNodeTypePreparedRealtimeSupport(
            "talas.add",
            talas::core::ExecutionSupport::Subset,
            talas::core::ExecutionBinding::LegacyAdapter);
        requireCustomRegistryRejected(
            std::move(registry), "prepared-support divergence");
    }
    {
        auto registry = talas::core::makeBuiltinNodeRegistry();
        registry.setNodeTypeProcessingContract(
            "talas.add",
            talas::core::NodeStateModel::SessionStateful,
            false,
            {talas::core::LatencyKind::None, 0});
        requireCustomRegistryRejected(
            std::move(registry), "state-model divergence");
    }
    {
        auto registry = talas::core::makeBuiltinNodeRegistry();
        registry.setNodeTypeFanInLatencyPolicy(
            "talas.add", talas::core::FanInLatencyPolicy::Align);
        requireCustomRegistryRejected(
            std::move(registry), "fan-in policy divergence");
    }

    const auto requireRejected = [](auto graph,
                                    std::string_view mutation) {
        talas::runtime::RealtimeRenderSession session(graph);
        require(!session.ready(),
            "C128 Add authority should reject "
                + std::string{mutation});
    };
    const auto findAdd = [](auto& graph) -> auto& {
        auto& plan = mutablePlanForTest(graph);
        const auto step = std::ranges::find(
            plan.steps, std::string_view{"talas.add"},
            &talas::runtime::CompileStep::typeId);
        require(step != plan.steps.end(),
            "C128 authority fixture should expose Add");
        return *step;
    };
    const auto findBinding = [](auto& step,
                                std::string_view port) -> auto& {
        const auto binding = std::ranges::find(
            step.inputs, port,
            &talas::runtime::InputBinding::inputPortId);
        require(binding != step.inputs.end(),
            "C128 authority fixture should expose "
                + std::string{port} + " binding");
        return *binding;
    };

    auto forgedSupport = compiled;
    findAdd(forgedSupport).preparedRealtimeSupport =
        talas::core::ExecutionSupport::Subset;
    requireRejected(std::move(forgedSupport),
        "prepared-support mutation");

    auto forgedParameter = compiled;
    findAdd(forgedParameter).parameters.push_back({});
    requireRejected(std::move(forgedParameter),
        "parameter-shape mutation");

    auto forgedOrder = compiled;
    std::swap(
        findAdd(forgedOrder).inputs[0],
        findAdd(forgedOrder).inputs[1]);
    requireRejected(std::move(forgedOrder),
        "ordered-input mutation");

    auto forgedProducer = compiled;
    findBinding(findAdd(forgedProducer), "right").sourceNodeId
        += "Forged";
    requireRejected(std::move(forgedProducer),
        "producer-identity mutation");

    auto forgedBindingScope = compiled;
    ++findBinding(findAdd(forgedBindingScope), "left")
        .sourceScopeId;
    requireRejected(std::move(forgedBindingScope),
        "producer-scope mutation");

    auto forgedInputPort = compiled;
    findBinding(findAdd(forgedInputPort), "right")
        .inputPortId = "left";
    requireRejected(std::move(forgedInputPort),
        "duplicate named-input mutation");

    auto forgedScope = compiled;
    ++findAdd(forgedScope).scopeId;
    requireRejected(std::move(forgedScope),
        "execution-scope mutation");

    auto forgedEventValueScope = compiled;
    ++findAdd(forgedEventValueScope).eventValueScopeId;
    requireRejected(std::move(forgedEventValueScope),
        "Event Value scope mutation");

    auto forgedAncestry = compiled;
    findAdd(forgedAncestry).structuralSourcePath += "/forged";
    requireRejected(std::move(forgedAncestry),
        "structural-ancestry mutation");

    auto forgedLatency = compiled;
    findAdd(forgedLatency).cumulativeOutputLatencyFrames = 1;
    requireRejected(std::move(forgedLatency),
        "latency mutation");

    auto forgedInputCapacity = compiled;
    auto& inputCapacityPlan = mutablePlanForTest(
        forgedInputCapacity);
    const auto leftIndex = findBinding(
        findAdd(forgedInputCapacity), "left").bufferIndex;
    ++inputCapacityPlan.buffers[leftIndex].frames;
    requireRejected(std::move(forgedInputCapacity),
        "input-capacity mutation");

    auto forgedInputType = compiled;
    auto& inputTypePlan = mutablePlanForTest(forgedInputType);
    const auto rightIndex = findBinding(
        findAdd(forgedInputType), "right").bufferIndex;
    require(rightIndex < inputTypePlan.buffers.size(),
        "C128 authority fixture should expose the right input buffer");
    inputTypePlan.buffers[rightIndex].type = talas::core::PortType::Audio;
    requireRejected(std::move(forgedInputType),
        "input-buffer type mutation");

    auto forgedOutput = compiled;
    auto& outputPlan = mutablePlanForTest(forgedOutput);
    const auto output = std::ranges::find_if(
        outputPlan.buffers,
        [](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == "add"
                && buffer.portId == "value";
        });
    require(output != outputPlan.buffers.end(),
        "C128 authority fixture should expose the output buffer");
    ++output->frames;
    requireRejected(std::move(forgedOutput),
        "output-buffer mutation");

    auto forgedOutputAlias = compiled;
    auto& aliasStep = findAdd(forgedOutputAlias);
    const auto aliasIndex =
        findBinding(aliasStep, "left").bufferIndex;
    auto& aliasPlan = mutablePlanForTest(forgedOutputAlias);
    const auto addOutput = std::ranges::find_if(
        aliasPlan.buffers,
        [&](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == aliasStep.nodeId
                && buffer.scopeId == aliasStep.scopeId
                && buffer.portId == "value";
        });
    require(addOutput != aliasPlan.buffers.end(),
        "C128 authority fixture should expose output alias shape");
    *addOutput = aliasPlan.buffers[aliasIndex];
    requireRejected(std::move(forgedOutputAlias),
        "output-input alias mutation");

    auto forgedResource = compiled;
    mutableSettingsForTest(forgedResource).tableResources.push_back(
        {"Tables/C128Unrelated", {9.0}});
    requireRejected(std::move(forgedResource),
        "unrelated-resource mutation");

    auto coherent = compiled;
    auto& coherentPlan = mutablePlanForTest(coherent);
    auto& coherentSettings = mutableSettingsForTest(coherent);
    ++coherentSettings.maxBlockFrames;
    for (auto& buffer : coherentPlan.buffers)
        ++buffer.frames;
    requireRejected(std::move(coherent),
        "coherent settings/buffer mutation");

    const auto sameProducer = compile(
        makeSameProducerAddVcaDocument(),
        talas::runtime::RenderSettings{4.0, 4});
    talas::runtime::RealtimeRenderSession sameProducerSession(sameProducer);
    std::array<double, 4> sameProducerOutput{};
    std::size_t allocations = 0;
    require(sameProducerSession.ready()
            && renderAndCount(
                sameProducerSession,
                sameProducerOutput,
                allocations)
            && allocations == 0
            && sameProducerOutput[1] != 0.0,
        "C128 Add should admit one legitimate producer bound to both named inputs");
}

void testAddLifecycleCopiesPartitionsResetAndReplacementMatchExactly()
{
    auto settings = talas::runtime::RenderSettings{8.0, 5};
    settings.eventValues = {
        {"C128Left", -0.75, talas::expr::ValueDomain::Scalar},
        {"C128Right", 0.5, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(
        makeAddVcaDocument("!C128Left", "!C128Right"), settings);
    const auto copiedGraph = graph;
    talas::runtime::OfflineRenderSession offline(graph);
    talas::runtime::OfflineRenderSession copiedOffline(copiedGraph);
    talas::runtime::RealtimeRenderSession realtime(graph);
    talas::runtime::RealtimeRenderSession copiedRealtime(copiedGraph);
    require(realtime.ready() && copiedRealtime.ready(),
        "C128 original and copied Add fixtures should prepare");

    for (const auto frames :
         std::array<std::size_t, 6>{1, 5, 2, 4, 3, 5})
    {
        const auto expected = offline.render(frames);
        const auto copied = copiedOffline.render(frames);
        std::vector<double> actual(frames);
        std::vector<double> copiedActual(frames);
        std::size_t allocations = 0;
        require(expected.ok() && copied.ok()
                && copied.mono == expected.mono
                && renderAndCount(realtime, actual, allocations)
                && renderAndCount(
                    copiedRealtime, copiedActual, allocations)
                && allocations == 0
                && actual == expected.mono
                && copiedActual == expected.mono,
            "C128 Add copies should match offline across irregular partitions");
    }

    std::size_t allocations = 0;
    require(renderEmptyMonoAndCount(realtime, allocations)
            && allocations == 0,
        "C128 zero-frame callback should preserve Add execution");
    offline.reset();
    realtime.resetTransport();
    const auto expected = offline.render(5);
    talas::runtime::RealtimeRenderSession replacement(graph);
    std::array<double, 5> actual{};
    std::array<double, 5> replaced{};
    require(replacement.ready() && expected.ok()
            && renderAndCount(realtime, actual, allocations)
            && renderAndCount(replacement, replaced, allocations)
            && allocations == 0
            && std::ranges::equal(actual, expected.mono)
            && std::ranges::equal(replaced, expected.mono),
        "C128 Add reset and replacement should match a fresh exact stream");
}

void testAddDownstreamFailureRestoresNeighborStateForRetry()
{
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.eventValues = {
        {"C128Left", 1.0, talas::expr::ValueDomain::Scalar},
        {"C128Right", 1.0, talas::expr::ValueDomain::Scalar},
        {"C128FailureScale", 0.25, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(
        makeDownstreamFailureAddDocument(), settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession pristine(graph);
    require(candidate.ready() && pristine.ready(),
        "C128 Add downstream-failure fixtures should prepare");

    std::array<double, 4> actual{};
    std::array<double, 4> expected{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, actual, allocations)
            && renderAndCount(pristine, expected, allocations)
            && allocations == 0 && actual == expected,
        "C128 downstream fixtures should establish identical state");
    require(candidate.updateEventValue(
                "C128FailureScale",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C128 downstream fixture should admit its finite failure scale");
    actual.fill(128.0);
    require(!renderAndCount(candidate, actual, allocations)
            && allocations == 0
            && actual == std::array<double, 4>{},
        "C128 downstream overflow should publish no output prefix");
    require(candidate.updateEventValue(
                "C128FailureScale", 0.25,
                talas::expr::ValueDomain::Scalar),
        "C128 downstream fixture should admit its repaired scale");
    require(renderAndCount(candidate, actual, allocations)
            && renderAndCount(pristine, expected, allocations)
            && allocations == 0 && actual == expected,
        "C128 repaired downstream retry should restore neighboring state exactly");
}

void testRealtimeDifferenceRejectsLateNonFiniteOperandsAndResultAndRepairsRetry()
{
    for (const auto rejectedBoundary :
         std::array<std::string_view, 3>{"left", "right", "value"})
    {
        auto settings = talas::runtime::RenderSettings{4.0, 4};
        settings.eventValues = {{
            "C124Input", -0.75, talas::expr::ValueDomain::Scalar}};
        const auto graph = compile(
            makeLateInvalidDifferenceVcaDocument(rejectedBoundary),
            settings);
        talas::runtime::RealtimeRenderSession candidate(graph);
        talas::runtime::RealtimeRenderSession pristine(graph);
        require(candidate.ready() && pristine.ready(),
            "C124 late-invalid Difference fixtures should prepare");
        require(candidate.scheduleEventValue(
                    "C124Input", std::numeric_limits<double>::max(),
                    talas::expr::ValueDomain::Scalar, 2),
            "C124 Difference should admit a late finite control for "
                + std::string{rejectedBoundary} + " rejection");

        std::array<double, 4> actual;
        actual.fill(124.0);
        std::size_t allocations = 0;
        require(!renderAndCount(candidate, actual, allocations)
                && allocations == 0
                && actual == std::array<double, 4>{},
            "C124 Difference should reject a late "
                + std::string{rejectedBoundary}
                + " failure without publishing a callback prefix");
        actual.fill(124.0);
        require(!renderAndCount(candidate, actual, allocations)
                && allocations == 0
                && actual == std::array<double, 4>{},
            "C124 repeated Difference retry should encounter the restored late failure without publication");

        require(candidate.updateEventValue(
                    "C124Input", -0.5,
                    talas::expr::ValueDomain::Scalar)
                && pristine.updateEventValue(
                    "C124Input", -0.5,
                    talas::expr::ValueDomain::Scalar),
            "C124 repaired Difference fixtures should admit a finite value");
        std::array<double, 4> expected{};
        require(renderAndCount(candidate, actual, allocations)
                && renderAndCount(pristine, expected, allocations)
                && allocations == 0 && actual == expected,
            "C124 repaired Difference retry should restore Event Value, producers, frame, and output state");
    }
}

