void testRealtimeProductRequiresExactCompilerOwnedAuthority()
{
    const auto compiled = compile(
        makeProductVcaDocument("0.5", "0.25"),
        talas::runtime::RenderSettings{4.0, 4});
    talas::runtime::RealtimeRenderSession publiclyConstructed(
        talas::runtime::PreparedRuntimeGraph{
            compiled.plan(), compiled.renderSettings()});
    require(!publiclyConstructed.ready()
            && publiclyConstructed.error()
                == "Realtime renderer requires compiler-owned Product execution authority",
        "C123 Product should require privately compiler-sealed execution authority");

    const auto requireRejected = [](auto forged,
                                    std::string_view context) {
        talas::runtime::RealtimeRenderSession rejected(forged);
        require(!rejected.ready(),
            "C123 Product authority should reject "
                + std::string{context});
    };
    const auto findProduct = [](auto& graph) -> auto& {
        auto& plan = mutablePlanForTest(graph);
        const auto step = std::ranges::find(
            plan.steps, std::string_view{"talas.product"},
            &talas::runtime::CompileStep::typeId);
        require(step != plan.steps.end(),
            "C123 authority fixture should expose Product");
        return *step;
    };
    const auto findBinding = [](auto& step,
                                std::string_view port) -> auto& {
        const auto binding = std::ranges::find(
            step.inputs, port,
            &talas::runtime::InputBinding::inputPortId);
        require(binding != step.inputs.end(),
            "C123 authority fixture should expose "
                + std::string{port} + " binding");
        return *binding;
    };

    auto forgedSupport = compiled;
    findProduct(forgedSupport).preparedRealtimeSupport =
        talas::core::ExecutionSupport::Subset;
    requireRejected(std::move(forgedSupport),
        "prepared-support mutation");

    auto forgedParameter = compiled;
    findProduct(forgedParameter).parameters.push_back({});
    requireRejected(std::move(forgedParameter),
        "parameter-shape mutation");

    auto forgedScope = compiled;
    ++findProduct(forgedScope).scopeId;
    requireRejected(std::move(forgedScope),
        "execution-scope mutation");

    auto forgedAncestry = compiled;
    findProduct(forgedAncestry).structuralSourcePath += "/forged";
    requireRejected(std::move(forgedAncestry),
        "structural-ancestry mutation");

    auto forgedLatency = compiled;
    findProduct(forgedLatency).cumulativeOutputLatencyFrames = 1;
    requireRejected(std::move(forgedLatency),
        "latency mutation");

    auto forgedLeftBinding = compiled;
    ++findBinding(findProduct(forgedLeftBinding), "left")
        .sourceScopeId;
    requireRejected(std::move(forgedLeftBinding),
        "left-binding mutation");

    auto forgedRightProducer = compiled;
    findBinding(findProduct(forgedRightProducer), "right")
        .sourceNodeId += "Forged";
    requireRejected(std::move(forgedRightProducer),
        "right-producer identity mutation");

    auto forgedInputPort = compiled;
    findBinding(findProduct(forgedInputPort), "right")
        .inputPortId = "left";
    requireRejected(std::move(forgedInputPort),
        "duplicate named-input mutation");

    auto forgedInputCapacity = compiled;
    auto& inputCapacityPlan = mutablePlanForTest(forgedInputCapacity);
    const auto leftIndex = findBinding(
        findProduct(forgedInputCapacity), "left").bufferIndex;
    require(leftIndex < inputCapacityPlan.buffers.size(),
        "C123 authority fixture should expose the left input buffer");
    ++inputCapacityPlan.buffers[leftIndex].frames;
    requireRejected(std::move(forgedInputCapacity),
        "input-buffer capacity mutation");

    auto forgedInputType = compiled;
    auto& inputTypePlan = mutablePlanForTest(forgedInputType);
    const auto rightIndex = findBinding(
        findProduct(forgedInputType), "right").bufferIndex;
    require(rightIndex < inputTypePlan.buffers.size(),
        "C123 authority fixture should expose the right input buffer");
    inputTypePlan.buffers[rightIndex].type = talas::core::PortType::Audio;
    requireRejected(std::move(forgedInputType),
        "input-buffer type mutation");

    auto forgedOutput = compiled;
    auto& outputPlan = mutablePlanForTest(forgedOutput);
    const auto output = std::ranges::find_if(
        outputPlan.buffers,
        [](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == "product"
                && buffer.portId == "value";
        });
    require(output != outputPlan.buffers.end(),
        "C123 authority fixture should expose the output buffer");
    ++output->frames;
    requireRejected(std::move(forgedOutput),
        "output-buffer mutation");

    auto forgedOutputAlias = compiled;
    auto& aliasStep = findProduct(forgedOutputAlias);
    const auto aliasIndex = findBinding(aliasStep, "left").bufferIndex;
    auto& aliasPlan = mutablePlanForTest(forgedOutputAlias);
    const auto productOutput = std::ranges::find_if(
        aliasPlan.buffers,
        [&](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == aliasStep.nodeId
                && buffer.scopeId == aliasStep.scopeId
                && buffer.portId == "value";
        });
    require(productOutput != aliasPlan.buffers.end(),
        "C123 authority fixture should expose output alias shape");
    *productOutput = aliasPlan.buffers[aliasIndex];
    requireRejected(std::move(forgedOutputAlias),
        "output-input alias mutation");

    auto forgedResource = compiled;
    mutableSettingsForTest(forgedResource).tableResources.push_back(
        {"Tables/C123Unrelated", {9.0}});
    requireRejected(std::move(forgedResource),
        "unrelated-resource mutation");

    auto coherentlyForged = compiled;
    auto& coherentSettings = mutableSettingsForTest(coherentlyForged);
    auto& coherentPlan = mutablePlanForTest(coherentlyForged);
    ++coherentSettings.maxBlockFrames;
    for (auto& buffer : coherentPlan.buffers)
        ++buffer.frames;
    requireRejected(std::move(coherentlyForged),
        "coherent plan/settings buffer-capacity mutation");

    const auto sameProducer = compile(
        makeSameProducerProductVcaDocument(),
        talas::runtime::RenderSettings{4.0, 4});
    talas::runtime::RealtimeRenderSession sameProducerSession(sameProducer);
    std::array<double, 4> sameProducerOutput{};
    std::size_t allocations = 0;
    require(sameProducerSession.ready()
            && renderAndCount(
                sameProducerSession, sameProducerOutput, allocations)
            && allocations == 0
            && sameProducerOutput[1] != 0.0,
        "C123 Product should admit one legitimate producer bound to both named inputs");
}

void testProductLifecycleCopiesPartitionsResetAndReplacementMatchExactly()
{
    auto settings = talas::runtime::RenderSettings{8.0, 5};
    settings.eventValues = {
        {"C123Left", -0.75, talas::expr::ValueDomain::Scalar},
        {"C123Right", 0.5, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(
        makeProductVcaDocument("!C123Left", "!C123Right"), settings);
    const auto copiedGraph = graph;
    talas::runtime::OfflineRenderSession offline(graph);
    talas::runtime::OfflineRenderSession copiedOffline(copiedGraph);
    talas::runtime::RealtimeRenderSession realtime(graph);
    talas::runtime::RealtimeRenderSession copiedRealtime(copiedGraph);
    require(realtime.ready() && copiedRealtime.ready(),
        "C123 original and copied Product lifecycle fixtures should prepare");

    for (const auto frames :
         std::array<std::size_t, 6>{1, 5, 2, 4, 3, 5})
    {
        const auto expected = offline.render(frames);
        const auto copied = copiedOffline.render(frames);
        std::vector<double> actual(frames);
        std::vector<double> copiedActual(frames);
        std::size_t allocations = 0;
        require(expected.ok() && copied.ok()
                && copied.mono == expected.mono
                && renderAndCount(realtime, actual, allocations)
                && renderAndCount(
                    copiedRealtime, copiedActual, allocations)
                && allocations == 0
                && actual == expected.mono
                && copiedActual == expected.mono,
            "C123 Product offline/prepared copies should match exactly across irregular partitions");
    }

    std::size_t allocations = 0;
    require(renderEmptyMonoAndCount(realtime, allocations)
            && renderEmptyMonoAndCount(copiedRealtime, allocations)
            && allocations == 0,
        "C123 zero-frame callback should preserve copied Product execution");

    offline.reset();
    copiedOffline.reset();
    realtime.resetTransport();
    copiedRealtime.resetTransport();
    const auto expected = offline.render(5);
    const auto copied = copiedOffline.render(5);
    talas::runtime::RealtimeRenderSession replacement(graph);
    std::array<double, 5> actual{};
    std::array<double, 5> copiedActual{};
    std::array<double, 5> replaced{};
    require(replacement.ready() && expected.ok() && copied.ok()
            && copied.mono == expected.mono
            && renderAndCount(realtime, actual, allocations)
            && renderAndCount(
                copiedRealtime, copiedActual, allocations)
            && renderAndCount(replacement, replaced, allocations)
            && allocations == 0
            && std::ranges::equal(actual, expected.mono)
            && std::ranges::equal(copiedActual, expected.mono)
            && std::ranges::equal(replaced, expected.mono),
        "C123 reset, copies, replacement, and offline Product should reproduce a fresh exact stream");
}

