void testFrequencyTrackerMatchesOfflineForIdenticalCallbackWindowsAndReset()
{
    auto document = makeFrequencyTrackerVcaDocument();
    for (auto& graphNode : document.graph.nodes)
    {
        if (graphNode.instanceId == "source")
        {
            for (auto& parameter : graphNode.parameters)
                if (parameter.parameterId == "frequency")
                    parameter.expression = "3.75 hz";
        }
        if (graphNode.instanceId == "tracker")
        {
            for (auto& parameter : graphNode.parameters)
                if (parameter.parameterId == "emphasis")
                    parameter.expression = "0.25";
        }
    }

    auto settings = talas::runtime::RenderSettings{64.0, 64};
    settings.maxRealtimeHistoryFrames = 128;
    const auto graph = compile(document, settings);
    talas::runtime::OfflineRenderSession offline(graph);
    talas::runtime::RealtimeRenderSession realtime(graph);
    require(
        realtime.ready(),
        "C90 same-window realtime session should prepare");

    std::array<double, 64> actual{};
    std::size_t allocations = 0;
    for (std::size_t block = 0; block < 3; ++block)
    {
        const auto expected = offline.render(actual.size());
        require(
            expected.ok()
                && renderAndCount(realtime, actual, allocations)
                && allocations == 0
                && std::ranges::equal(expected.mono, actual),
            "C90 offline and prepared Frequency Tracker should match for identical callback window "
                + std::to_string(block));
    }

    offline.reset();
    realtime.resetTransport();
    const auto resetExpected = offline.render(actual.size());
    require(
        resetExpected.ok()
            && renderAndCount(realtime, actual, allocations)
            && allocations == 0
            && std::ranges::equal(resetExpected.mono, actual)
            && actual == std::array<double, 64>{},
        "C90 offline and prepared reset should restore the same empty callback-window tracker state");
}

