void testFrequencyTrackerRetainsPreparedCapacityAcrossConnectedRangeChanges()
{
    auto settings = talas::runtime::RenderSettings{64.0, 16};
    settings.maxRealtimeHistoryFrames = 128;
    auto minimumSequence = std::vector<double>(128, 9.0);
    minimumSequence.resize(144, 1.0);
    settings.tableResources.push_back({
        "Tables/C90TrackerMinimum", std::move(minimumSequence)});
    auto document = makeFrequencyTrackerVcaDocument();
    const auto tracker = std::ranges::find(
        document.graph.nodes,
        std::string_view{"tracker"},
        &talas::project::ProjectNode::instanceId);
    require(
        tracker != document.graph.nodes.end(),
        "C90 connected-range history-retention fixture should expose Frequency Tracker");
    tracker->parameters = {
        {"minFrequency", "9 hz"},
        {"maxFrequency", "16 hz"},
        {"confidence", "0"},
        {"scale", "1"},
        {"detectors", "10"},
        {"emphasis", "0"},
    };
    document.graph.nodes.push_back(node(
        "minimumSequence", "talas.triggeredTableRead", {
            {"trigger", "1"},
            resourceParameter(
                "wavetable", "Tables/C90TrackerMinimum"),
            {"gate", "1"},
            booleanParameter("ignoreLoops", true),
            booleanParameter("fromMemoryWriter", false),
        }));
    document.graph.connections.push_back(connection(
        "minimumSequence", "value", "tracker", "minFrequency"));
    const auto graph = compile(document, settings);
    talas::runtime::OfflineRenderSession offline(graph);
    talas::runtime::RealtimeRenderSession realtime(graph);
    std::array<double, 16> actual{};
    std::size_t allocations = 0;

    require(
        realtime.ready(),
        "C90 connected-range history-retention fixture should prepare");
    for (std::size_t block = 0; block < 9; ++block)
    {
        const auto expected = offline.render(actual.size());
        require(
            expected.ok(),
            "C90 offline connected-range history-retention block should render "
                + std::to_string(block));
        require(
            renderAndCount(realtime, actual, allocations),
            "C90 prepared connected-range history-retention block should render "
                + std::to_string(block));
        require(
            allocations == 0,
            "C90 prepared connected-range history-retention block should not allocate "
                + std::to_string(block));
        require(
            std::ranges::equal(expected.mono, actual),
            "C90 offline/prepared history retention should match after connected minimum-frequency transition in block "
                + std::to_string(block));
    }
    require(
        std::ranges::any_of(actual, [](double sample) {
            return sample != 0.0;
        }),
        "C90 widened connected range should reuse the full admitted prepared history capacity");
}

void testRealtimeFrequencyTrackerOwnOverflowPreservesHistoryAndCallbackPosition()
{
    auto document = makeConnectedFrequencyTrackerVcaDocument();
    const auto source = std::ranges::find(
        document.graph.nodes,
        std::string_view{"source"},
        &talas::project::ProjectNode::instanceId);
    require(
        source != document.graph.nodes.end(),
        "C90 overflow fixture should expose its tracked source");
    for (auto& parameter : source->parameters)
        if (parameter.parameterId == "frequency")
            parameter.expression = "3.75 hz";

    auto settings = talas::runtime::RenderSettings{64.0, 64};
    settings.maxRealtimeHistoryFrames = 128;
    settings.eventValues = {
        {"TrackerMin", 1.0, talas::expr::ValueDomain::Scalar},
        {"TrackerMax", 8.0, talas::expr::ValueDomain::Scalar},
        {"TrackerConfidence", 0.5, talas::expr::ValueDomain::Scalar},
        {"TrackerScale", 0.25, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    std::array<double, 64> seed{};
    std::array<double, 64> rejected{};
    std::array<double, 32> candidateRetry{};
    std::array<double, 32> referenceRetry{};
    std::size_t allocations = 0;
    require(
        candidate.ready() && reference.ready()
            && renderAndCount(candidate, seed, allocations)
            && allocations == 0
            && renderAndCount(candidate, seed, allocations)
            && allocations == 0
            && renderAndCount(reference, seed, allocations)
            && allocations == 0
            && renderAndCount(reference, seed, allocations)
            && allocations == 0
            && candidate.updateEventValue(
                "TrackerScale", std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C90 overflow fixture should establish two blocks of tracker history");
    rejected.fill(1.0);
    require(
        !renderAndCount(candidate, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 64>{},
        "C90 scaled-frequency overflow should fail closed without allocation or output prefix");
    require(
        candidate.updateEventValue(
            "TrackerScale", 0.25, talas::expr::ValueDomain::Scalar)
            && renderAndCount(candidate, candidateRetry, allocations)
            && allocations == 0
            && renderAndCount(reference, referenceRetry, allocations)
            && allocations == 0
            && candidateRetry == referenceRetry,
        "C90 rejected callback should preserve tracker history and callback position exactly");
}

