void testRealtimeSetRangeRejectsLateFiniteIntermediateOverflowAndRepairsRetry()
{
    const auto maximumFinite = std::numeric_limits<double>::max();
    const auto requireRejectedLane = [&](std::string_view eventName) {
        auto value = 0.25;
        auto oldMin = 0.0;
        auto oldMax = 1.0;
        auto newMin = 0.0;
        auto newMax = 1.0;
        auto invalid = maximumFinite;
        if (eventName == "RangeValue")
        {
            value = -0.5;
            oldMin = -maximumFinite;
            oldMax = 0.0;
        }
        else if (eventName == "RangeOldMin")
        {
            oldMax = maximumFinite;
            invalid = -maximumFinite;
        }
        else if (eventName == "RangeOldMax")
        {
            oldMin = -maximumFinite;
        }
        else if (eventName == "RangeNewMin")
        {
            newMax = maximumFinite;
            invalid = -maximumFinite;
        }
        else
        {
            newMin = -maximumFinite;
        }

        auto settings = talas::runtime::RenderSettings{4.0, 4};
        settings.eventValues = {
            {"RangeValue", value, talas::expr::ValueDomain::Scalar},
            {"RangeOldMin", oldMin, talas::expr::ValueDomain::Scalar},
            {"RangeOldMax", oldMax, talas::expr::ValueDomain::Scalar},
            {"RangeNewMin", newMin, talas::expr::ValueDomain::Scalar},
            {"RangeNewMax", newMax, talas::expr::ValueDomain::Scalar},
        };
        const auto graph = compile(
            makeConnectedSetRangeVcaDocument(), settings);
        talas::runtime::RealtimeRenderSession candidate(graph);
        talas::runtime::RealtimeRenderSession pristine(graph);
        require(candidate.ready() && pristine.ready(),
            "C122 late-overflow Set Range fixtures should prepare");
        require(candidate.scheduleEventValue(
                    eventName,
                    invalid,
                    talas::expr::ValueDomain::Scalar,
                    2),
            "C122 Set Range should admit a late finite overflow-producing "
                + std::string{eventName} + " value");

        std::array<double, 4> actual;
        actual.fill(122.0);
        std::size_t allocations = 0;
        require(!renderAndCount(candidate, actual, allocations)
                && allocations == 0
                && actual == std::array<double, 4>{},
            "C122 Set Range should reject a late finite "
                + std::string{eventName}
                + " intermediate overflow without publishing a callback prefix");
        actual.fill(122.0);
        require(!renderAndCount(candidate, actual, allocations)
                && allocations == 0
                && actual == std::array<double, 4>{},
            "C122 repeated retry should restore the rejected scheduled Set Range control");

        const auto repaired = eventName == "RangeValue" ? value
            : eventName == "RangeOldMin" ? oldMin
            : eventName == "RangeOldMax" ? oldMax
            : eventName == "RangeNewMin" ? newMin
            : newMax;
        require(candidate.updateEventValue(
                    eventName,
                    repaired,
                    talas::expr::ValueDomain::Scalar)
                && pristine.updateEventValue(
                    eventName,
                    repaired,
                    talas::expr::ValueDomain::Scalar),
            "C122 repaired-retry fixtures should admit the finite Set Range recovery value");
        std::array<double, 4> expected{};
        require(renderAndCount(candidate, actual, allocations)
                && renderAndCount(pristine, expected, allocations)
                && allocations == 0
                && actual == expected,
            "C122 repaired Set Range retry should restore all Event Values, producers, frame, and output state");
    };

    for (const auto eventName : {
             std::string_view{"RangeValue"},
             std::string_view{"RangeOldMin"},
             std::string_view{"RangeOldMax"},
             std::string_view{"RangeNewMin"},
             std::string_view{"RangeNewMax"},
         })
    {
        requireRejectedLane(eventName);
    }
}

void testSetRangeLifecycleCopiesPartitionsResetAndReplacementMatchExactly()
{
    auto settings = talas::runtime::RenderSettings{8.0, 5};
    settings.eventValues = {
        {"RangeValue", 0.25, talas::expr::ValueDomain::Scalar},
        {"RangeOldMin", -1.0, talas::expr::ValueDomain::Scalar},
        {"RangeOldMax", 1.0, talas::expr::ValueDomain::Scalar},
        {"RangeNewMin", -0.5, talas::expr::ValueDomain::Scalar},
        {"RangeNewMax", 0.75, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(
        makeConnectedSetRangeVcaDocument(), settings);
    const auto copiedGraph = graph;
    talas::runtime::OfflineRenderSession offline(graph);
    talas::runtime::OfflineRenderSession copiedOffline(copiedGraph);
    talas::runtime::RealtimeRenderSession realtime(graph);
    talas::runtime::RealtimeRenderSession copiedRealtime(copiedGraph);
    require(realtime.ready() && copiedRealtime.ready(),
        "C122 original and copied prepared Set Range lifecycle fixtures should prepare");

    for (const auto frames : std::array<std::size_t, 6>{
             1, 5, 2, 4, 3, 5})
    {
        const auto expected = offline.render(frames);
        const auto copied = copiedOffline.render(frames);
        std::vector<double> actual(frames);
        std::vector<double> copiedActual(frames);
        std::size_t allocations = 0;
        require(expected.ok() && copied.ok()
                && copied.mono == expected.mono
                && renderAndCount(realtime, actual, allocations)
                && renderAndCount(
                    copiedRealtime, copiedActual, allocations)
                && allocations == 0
                && actual == expected.mono
                && copiedActual == expected.mono,
            "C122 Set Range offline/prepared copies should match exactly across irregular partitions");
    }

    std::size_t allocations = 0;
    require(renderEmptyMonoAndCount(realtime, allocations)
            && renderEmptyMonoAndCount(copiedRealtime, allocations)
            && allocations == 0,
        "C122 zero-frame callback should preserve original and copied prepared Set Range execution");

    offline.reset();
    copiedOffline.reset();
    realtime.resetTransport();
    copiedRealtime.resetTransport();
    const auto expected = offline.render(5);
    const auto copied = copiedOffline.render(5);
    talas::runtime::RealtimeRenderSession replacement(graph);
    std::array<double, 5> actual{};
    std::array<double, 5> copiedActual{};
    std::array<double, 5> replaced{};
    require(replacement.ready()
            && expected.ok() && copied.ok()
            && copied.mono == expected.mono
            && renderAndCount(realtime, actual, allocations)
            && renderAndCount(
                copiedRealtime, copiedActual, allocations)
            && renderAndCount(replacement, replaced, allocations)
            && allocations == 0
            && std::ranges::equal(actual, expected.mono)
            && std::ranges::equal(copiedActual, expected.mono)
            && std::ranges::equal(replaced, expected.mono),
        "C122 reset, prepared copies, replacement, and copied offline graph should reproduce a fresh exact Set Range stream");
}

void testRealtimeSetRangeRequiresCompilerOwnedExecutionAuthority()
{
    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.eventValues = {
        {"RangeValue", 0.25, talas::expr::ValueDomain::Scalar},
        {"RangeOldMin", 0.0, talas::expr::ValueDomain::Scalar},
        {"RangeOldMax", 1.0, talas::expr::ValueDomain::Scalar},
        {"RangeNewMin", -1.0, talas::expr::ValueDomain::Scalar},
        {"RangeNewMax", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = compile(
        makeConnectedSetRangeVcaDocument(), settings);
    talas::runtime::RealtimeRenderSession publiclyConstructed(
        talas::runtime::PreparedRuntimeGraph{
            compiled.plan(), compiled.renderSettings()});
    require(!publiclyConstructed.ready()
            && publiclyConstructed.error()
                == "Realtime renderer requires compiler-owned Set Range execution authority",
        "C122 Set Range should require privately compiler-sealed execution authority");

    const auto requireRejected = [](auto forged,
                                    std::string_view context) {
        talas::runtime::RealtimeRenderSession rejected(forged);
        require(!rejected.ready(),
            "C122 Set Range authority should reject "
                + std::string{context});
    };
    const auto findSetRange = [](auto& graph) -> auto& {
        auto& plan = mutablePlanForTest(graph);
        const auto step = std::ranges::find(
            plan.steps, std::string_view{"talas.setRange"},
            &talas::runtime::CompileStep::typeId);
        require(step != plan.steps.end(),
            "C122 authority fixture should expose Set Range");
        return *step;
    };
    const auto findBinding = [](auto& step,
                                std::string_view port) -> auto& {
        const auto binding = std::ranges::find(
            step.inputs, port,
            &talas::runtime::InputBinding::inputPortId);
        require(binding != step.inputs.end(),
            "C122 authority fixture should expose "
                + std::string{port} + " binding");
        return *binding;
    };
    const auto findParameter = [](auto& step,
                                  std::string_view parameterId) -> auto& {
        const auto parameter = std::ranges::find(
            step.parameters, parameterId,
            &talas::runtime::ParameterValue::id);
        require(parameter != step.parameters.end(),
            "C122 authority fixture should expose "
                + std::string{parameterId} + " fallback");
        return *parameter;
    };

    auto forgedSupport = compiled;
    findSetRange(forgedSupport).preparedRealtimeSupport =
        talas::core::ExecutionSupport::Subset;
    requireRejected(std::move(forgedSupport),
        "prepared-support mutation");

    auto forgedParameterOrder = compiled;
    auto& reordered = findSetRange(forgedParameterOrder).parameters;
    std::swap(reordered[0], reordered[1]);
    requireRejected(std::move(forgedParameterOrder),
        "parameter-order mutation");

    auto forgedParameterIdentity = compiled;
    findParameter(findSetRange(forgedParameterIdentity), "newMin").id =
        "oldMin";
    requireRejected(std::move(forgedParameterIdentity),
        "parameter-identity mutation");

    auto forgedParameterValue = compiled;
    auto& forgedNewMax = findParameter(
        findSetRange(forgedParameterValue), "newMax");
    forgedNewMax.value = std::nextafter(
        forgedNewMax.value, std::numeric_limits<double>::infinity());
    requireRejected(std::move(forgedParameterValue),
        "parameter-value mutation");

    auto forgedScope = compiled;
    ++findSetRange(forgedScope).scopeId;
    requireRejected(std::move(forgedScope),
        "execution-scope mutation");

    auto forgedAncestry = compiled;
    findSetRange(forgedAncestry).structuralSourcePath += "/forged";
    requireRejected(std::move(forgedAncestry),
        "structural-ancestry mutation");

    auto forgedLatency = compiled;
    findSetRange(forgedLatency).cumulativeOutputLatencyFrames = 1;
    requireRejected(std::move(forgedLatency),
        "latency mutation");

    auto forgedOptionalPresence = compiled;
    auto& missingOptional = findSetRange(forgedOptionalPresence).inputs;
    const auto oldMinBinding = std::ranges::find(
        missingOptional, std::string_view{"oldMin"},
        &talas::runtime::InputBinding::inputPortId);
    require(oldMinBinding != missingOptional.end(),
        "C122 authority fixture should expose optional-binding presence");
    missingOptional.erase(oldMinBinding);
    requireRejected(std::move(forgedOptionalPresence),
        "optional-binding presence mutation");

    auto forgedProducer = compiled;
    findBinding(findSetRange(forgedProducer), "oldMax")
        .sourceNodeId += "Forged";
    requireRejected(std::move(forgedProducer),
        "producer-identity mutation");

    auto forgedInputPort = compiled;
    findBinding(findSetRange(forgedInputPort), "newMax")
        .inputPortId = "newMin";
    requireRejected(std::move(forgedInputPort),
        "duplicate named-input mutation");

    auto forgedInputCapacity = compiled;
    auto& inputCapacityPlan = mutablePlanForTest(forgedInputCapacity);
    const auto valueIndex = findBinding(
        findSetRange(forgedInputCapacity), "value").bufferIndex;
    require(valueIndex < inputCapacityPlan.buffers.size(),
        "C122 authority fixture should expose the value input buffer");
    ++inputCapacityPlan.buffers[valueIndex].frames;
    requireRejected(std::move(forgedInputCapacity),
        "input-buffer capacity mutation");

    auto forgedInputType = compiled;
    auto& inputTypePlan = mutablePlanForTest(forgedInputType);
    const auto newMinIndex = findBinding(
        findSetRange(forgedInputType), "newMin").bufferIndex;
    require(newMinIndex < inputTypePlan.buffers.size(),
        "C122 authority fixture should expose the newMin input buffer");
    inputTypePlan.buffers[newMinIndex].type =
        talas::core::PortType::Audio;
    requireRejected(std::move(forgedInputType),
        "input-buffer type mutation");

    auto forgedOutput = compiled;
    auto& outputPlan = mutablePlanForTest(forgedOutput);
    const auto output = std::ranges::find_if(
        outputPlan.buffers,
        [](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == "range"
                && buffer.portId == "value";
        });
    require(output != outputPlan.buffers.end(),
        "C122 authority fixture should expose the output buffer");
    ++output->frames;
    requireRejected(std::move(forgedOutput),
        "output-buffer mutation");

    auto forgedOutputAlias = compiled;
    auto& aliasStep = findSetRange(forgedOutputAlias);
    const auto aliasIndex = findBinding(aliasStep, "value").bufferIndex;
    auto& aliasPlan = mutablePlanForTest(forgedOutputAlias);
    const auto rangeOutput = std::ranges::find_if(
        aliasPlan.buffers,
        [&](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == aliasStep.nodeId
                && buffer.scopeId == aliasStep.scopeId
                && buffer.portId == "value";
        });
    require(rangeOutput != aliasPlan.buffers.end()
            && aliasIndex < aliasPlan.buffers.size(),
        "C122 authority fixture should expose output alias shape");
    *rangeOutput = aliasPlan.buffers[aliasIndex];
    requireRejected(std::move(forgedOutputAlias),
        "output-input alias mutation");

    auto forgedDuplicateOutput = compiled;
    auto& duplicateOutputPlan = mutablePlanForTest(forgedDuplicateOutput);
    const auto originalOutput = std::ranges::find_if(
        duplicateOutputPlan.buffers,
        [](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == "range"
                && buffer.portId == "value";
        });
    require(originalOutput != duplicateOutputPlan.buffers.end(),
        "C122 authority fixture should expose duplicate-output shape");
    duplicateOutputPlan.buffers.push_back(*originalOutput);
    requireRejected(std::move(forgedDuplicateOutput),
        "duplicate output mutation");

    auto forgedResource = compiled;
    mutableSettingsForTest(forgedResource).tableResources.push_back(
        {"Tables/C122Unrelated", {9.0}});
    requireRejected(std::move(forgedResource),
        "unrelated-resource mutation");

    auto coherentlyForged = compiled;
    auto& coherentSettings = mutableSettingsForTest(coherentlyForged);
    auto& coherentPlan = mutablePlanForTest(coherentlyForged);
    ++coherentSettings.maxBlockFrames;
    for (auto& buffer : coherentPlan.buffers)
        ++buffer.frames;
    requireRejected(std::move(coherentlyForged),
        "coherent plan/settings buffer-capacity mutation");

    const auto sameProducer = compile(
        makeSharedProducerSetRangeVcaDocument(), settings);
    talas::runtime::RealtimeRenderSession sameProducerSession(sameProducer);
    std::array<double, 4> sameProducerOutput{};
    std::size_t allocations = 0;
    require(sameProducerSession.ready()
            && renderAndCount(
                sameProducerSession, sameProducerOutput, allocations)
            && allocations == 0
            && sameProducerOutput[1] != 0.0,
        "C122 Set Range should admit one legitimate producer bound to multiple named inputs");
}

