void testRealtimeVcaNormalizationDoesNotWeakenConnectedNoiseAuthority()
{
    auto document = makeDirectEventValueNoiseDocument(true);
    const auto terminal = std::ranges::find_if(
        document.graph.connections,
        [](const auto& edge) {
            return edge.fromNode == "noise"
                && edge.fromPort == "audioOut"
                && edge.toNode == "out"
                && edge.toPort == "audioIn";
        });
    require(terminal != document.graph.connections.end(),
        "C126 normalization fixture should expose Noise output");
    terminal->toNode = "vca";
    terminal->toPort = "audioIn";
    document.graph.nodes.push_back(node("vca", "talas.vca"));
    document.graph.nodes.push_back(node(
        "vcaGain", "talas.constant", {{"value", "1"}}));
    document.graph.connections.push_back(connection(
        "vcaGain", "value", "vca", "gain"));
    document.graph.connections.push_back(connection(
        "vca", "audioOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.eventValues = {
        {"NoiseFrequency", 1.0, talas::expr::ValueDomain::Scalar},
        {"NoiseCenter", 0.0, talas::expr::ValueDomain::Scalar},
        {"NoiseScale", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto forgedGraph = compile(document, std::move(settings));
    auto& plan = mutablePlanForTest(forgedGraph);
    const auto noise = std::ranges::find(
        plan.steps, std::string_view{"talas.noise"},
        &talas::runtime::CompileStep::typeId);
    require(noise != plan.steps.end(),
        "C126 normalization fixture should expose connected Noise");
    const auto frequency = std::ranges::find(
        noise->parameters, std::string_view{"frequency"},
        &talas::runtime::ParameterValue::id);
    require(frequency != noise->parameters.end(),
        "C126 normalization fixture should expose Noise frequency fallback");
    frequency->value = std::numeric_limits<double>::infinity();

    talas::runtime::RealtimeRenderSession session(forgedGraph);
    require(!session.ready(),
        "C126 VCA normalization must not weaken exact connected Noise fallback authority");
}

void testRealtimeVcaRejectsLateInputAndProductWithoutPublication()
{
    for (const auto rejectsProduct : {false, true})
    {
        const auto graph = compile(
            makeAudioInputVcaDocument(
                rejectsProduct
                    ? std::to_string(
                        std::numeric_limits<double>::max())
                    : "0.5"),
            talas::runtime::RenderSettings{8.0, 4});
        talas::runtime::RealtimeRenderSession candidate(graph);
        talas::runtime::RealtimeRenderSession pristine(graph);
        require(candidate.ready() && pristine.ready(),
            "C126 late-invalid VCA fixtures should prepare");

        std::array<float, 4> input{
            0.5F, 0.5F, rejectsProduct ? 2.0F : 0.5F, 0.5F};
        if (!rejectsProduct)
            input[2] = std::numeric_limits<float>::infinity();
        const std::array<const float*, 1> channels{input.data()};
        const talas::runtime::RealtimeAudioInputBlock inputBlock{
            channels.data(), channels.size()};
        std::array<double, 4> actualLeft;
        std::array<double, 4> actualRight;
        actualLeft.fill(126.0);
        actualRight.fill(126.0);
        std::size_t allocations = 0;
        require(!renderStereoInputAndCount(
                    candidate,
                    inputBlock,
                    actualLeft,
                    actualRight,
                    allocations)
                && allocations == 0
                && actualLeft == std::array<double, 4>{}
                && actualRight == std::array<double, 4>{},
            "C126 VCA should reject a late invalid "
                + std::string{rejectsProduct ? "product" : "input"}
                + " without publishing a callback prefix");

        actualLeft.fill(126.0);
        actualRight.fill(126.0);
        require(!renderStereoInputAndCount(
                    candidate,
                    inputBlock,
                    actualLeft,
                    actualRight,
                    allocations)
                && allocations == 0
                && actualLeft == std::array<double, 4>{}
                && actualRight == std::array<double, 4>{},
            "C126 rejected VCA callback should remain exactly retryable");

        input.fill(0.5F);
        std::array<double, 4> expectedLeft{};
        std::array<double, 4> expectedRight{};
        require(renderStereoInputAndCount(
                    candidate,
                    inputBlock,
                    actualLeft,
                    actualRight,
                    allocations)
                && renderStereoInputAndCount(
                    pristine,
                    inputBlock,
                    expectedLeft,
                    expectedRight,
                    allocations)
                && allocations == 0
                && actualLeft == expectedLeft
                && actualRight == expectedRight,
            "C126 repaired VCA retry should restore input cursors, frame position, and output state");
    }
}

void testRealtimeVcaRejectsLateConnectedGainAndRepairsRetry()
{
    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.eventValues = {{
        "C126Gain", 0.5, talas::expr::ValueDomain::Scalar}};
    auto document = makeOscillatorVcaDocument("!C126Gain");
    const auto connectedGain = std::ranges::find_if(
        document.graph.connections,
        [](const auto& edge) {
            return edge.fromNode == "gain"
                && edge.fromPort == "value"
                && edge.toNode == "vca"
                && edge.toPort == "gain";
        });
    require(connectedGain != document.graph.connections.end(),
        "C126 late connected-gain fixture should expose the direct gain edge");
    document.graph.connections.erase(connectedGain);
    document.graph.nodes.push_back(node("gainOverflow", "talas.add"));
    document.graph.connections.push_back(connection(
        "gain", "value", "gainOverflow", "left"));
    document.graph.connections.push_back(connection(
        "gain", "value", "gainOverflow", "right"));
    document.graph.connections.push_back(connection(
        "gainOverflow", "value", "vca", "gain"));
    const auto graph = compile(
        document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession pristine(graph);
    require(candidate.ready() && pristine.ready(),
        "C126 late connected-gain fixtures should prepare");
    require(candidate.scheduleEventValue(
                "C126Gain", std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar, 2),
        "C126 VCA should admit a late finite Event Value whose connected gain producer overflows");

    std::array<double, 4> actual;
    actual.fill(126.0);
    std::size_t allocations = 0;
    require(!renderAndCount(candidate, actual, allocations)
            && allocations == 0
            && actual == std::array<double, 4>{},
        "C126 VCA should reject a late non-finite connected gain without publishing its valid callback prefix");
    actual.fill(126.0);
    require(!renderAndCount(candidate, actual, allocations)
            && allocations == 0
            && actual == std::array<double, 4>{},
        "C126 repeated retry should restore the late connected-gain Event Value and publish nothing");

    require(candidate.updateEventValue(
                "C126Gain", 0.25,
                talas::expr::ValueDomain::Scalar)
            && pristine.updateEventValue(
                "C126Gain", 0.25,
                talas::expr::ValueDomain::Scalar),
        "C126 connected-gain repaired-retry fixtures should admit the finite recovery value");
    std::array<double, 4> expected{};
    require(renderAndCount(candidate, actual, allocations)
            && renderAndCount(pristine, expected, allocations)
            && allocations == 0
            && actual == expected,
        "C126 repaired connected-gain retry should restore scheduler cursors, frame position, producer state, and exact output");
}

void testVcaLifecycleCopiesPartitionsResetAndReplacementMatchExactly()
{
    auto staticDocument = makeOscillatorVcaDocument("0.5");
    const auto staticVca = std::ranges::find(
        staticDocument.graph.nodes,
        std::string_view{"vca"},
        &talas::project::ProjectNode::instanceId);
    require(staticVca != staticDocument.graph.nodes.end(),
        "C126 static lifecycle fixture should expose VCA");
    staticVca->parameters = {{"gain", "0.5"}};
    std::erase_if(
        staticDocument.graph.nodes,
        [](const talas::project::ProjectNode& node) {
            return node.instanceId == "gain";
        });
    std::erase_if(
        staticDocument.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.toNode == "vca" && edge.toPort == "gain";
        });

    for (const auto& document : {
             staticDocument,
             makeOscillatorVcaDocument("0.5")})
    {
        const auto graph = compile(
            document, talas::runtime::RenderSettings{8.0, 5});
        const auto copiedGraph = graph;
        talas::runtime::OfflineRenderSession offline(graph);
        talas::runtime::OfflineRenderSession copiedOffline(copiedGraph);
        talas::runtime::RealtimeRenderSession realtime(graph);
        talas::runtime::RealtimeRenderSession copiedRealtime(copiedGraph);
        require(realtime.ready() && copiedRealtime.ready(),
            "C126 original and copied VCA lifecycle fixtures should prepare");

        for (const auto frames :
             std::array<std::size_t, 6>{1, 5, 2, 4, 3, 5})
        {
            const auto expected = offline.render(frames);
            const auto copied = copiedOffline.render(frames);
            std::vector<double> actual(frames);
            std::vector<double> copiedActual(frames);
            std::size_t allocations = 0;
            require(expected.ok() && copied.ok()
                    && copied.mono == expected.mono
                    && renderAndCount(realtime, actual, allocations)
                    && renderAndCount(
                        copiedRealtime, copiedActual, allocations)
                    && allocations == 0
                    && actual == expected.mono
                    && copiedActual == expected.mono,
                "C126 static/connected VCA copies should match offline exactly across irregular partitions");
        }

        std::size_t allocations = 0;
        require(renderEmptyMonoAndCount(realtime, allocations)
                && renderEmptyMonoAndCount(copiedRealtime, allocations)
                && allocations == 0,
            "C126 zero-frame callback should preserve copied VCA execution");

        offline.reset();
        copiedOffline.reset();
        realtime.resetTransport();
        copiedRealtime.resetTransport();
        const auto expected = offline.render(5);
        const auto copied = copiedOffline.render(5);
        talas::runtime::RealtimeRenderSession replacement(graph);
        std::array<double, 5> actual{};
        std::array<double, 5> copiedActual{};
        std::array<double, 5> replaced{};
        require(replacement.ready() && expected.ok() && copied.ok()
                && copied.mono == expected.mono
                && renderAndCount(realtime, actual, allocations)
                && renderAndCount(
                    copiedRealtime, copiedActual, allocations)
                && renderAndCount(replacement, replaced, allocations)
                && allocations == 0
                && std::ranges::equal(actual, expected.mono)
                && std::ranges::equal(copiedActual, expected.mono)
                && std::ranges::equal(replaced, expected.mono),
            "C126 reset, copies, replacement, static/connected gain, and offline VCA should reproduce a fresh exact stream");
    }
}

void testVcaDownstreamFailureRestoresNeighborStateForRetry()
{
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.eventValues = {{
        "C126FailureScale", 0.25,
        talas::expr::ValueDomain::Scalar}};
    const auto graph = compile(
        makeDownstreamFailureVcaDocument(), settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession pristine(graph);
    require(candidate.ready() && pristine.ready(),
        "C126 VCA downstream-failure fixtures should prepare");

    std::array<double, 4> actual{};
    std::array<double, 4> expected{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, actual, allocations)
            && renderAndCount(pristine, expected, allocations)
            && allocations == 0 && actual == expected,
        "C126 downstream fixtures should establish identical accepted oscillator and VCA state");

    require(candidate.updateEventValue(
                "C126FailureScale",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C126 downstream fixture should admit its finite overflow-producing gain");
    actual.fill(126.0);
    require(!renderAndCount(candidate, actual, allocations)
            && allocations == 0
            && actual == std::array<double, 4>{},
        "C126 downstream Mixer overflow should publish no output prefix");

    require(candidate.updateEventValue(
                "C126FailureScale", 0.25,
                talas::expr::ValueDomain::Scalar),
        "C126 downstream fixture should admit its repaired gain");
    require(renderAndCount(candidate, actual, allocations)
            && renderAndCount(pristine, expected, allocations)
            && allocations == 0 && actual == expected,
        "C126 repaired downstream retry should restore oscillator, VCA, Event Value, frame, and output state");
}

void testRealtimeSqrtMagnitudeRejectsLateNonFiniteInputAndRepairsRetry()
{
    const auto graph = compile(
        makeAudioInputSqrtMagnitudeDocument(),
        talas::runtime::RenderSettings{8.0, 4});
    for (const auto rejectedChannel : {0U, 1U})
    {
        talas::runtime::RealtimeRenderSession candidate(graph);
        talas::runtime::RealtimeRenderSession pristine(graph);
        require(candidate.ready() && pristine.ready(),
            "C125 late-invalid Sqrt Magnitude fixtures should prepare");

        std::array<float, 4> left{0.3F, 0.3F, 0.3F, 0.3F};
        std::array<float, 4> right{0.4F, 0.4F, 0.4F, 0.4F};
        (rejectedChannel == 0 ? left : right)[2] =
            std::numeric_limits<float>::infinity();
        const std::array<const float*, 2> invalidChannels{
            left.data(), right.data()};
        std::array<double, 4> actualLeft;
        std::array<double, 4> actualRight;
        actualLeft.fill(125.0);
        actualRight.fill(125.0);
        std::size_t allocations = 0;
        require(
            !renderStereoInputAndCount(
                candidate,
                {invalidChannels.data(), invalidChannels.size()},
                actualLeft,
                actualRight,
                allocations)
                && allocations == 0
                && actualLeft == std::array<double, 4>{}
                && actualRight == std::array<double, 4>{},
            "C125 Sqrt Magnitude should reject a late non-finite "
                + std::string{rejectedChannel == 0 ? "left" : "right"}
                + " input without publishing a callback prefix");

        actualLeft.fill(125.0);
        actualRight.fill(125.0);
        require(
            !renderStereoInputAndCount(
                candidate,
                {invalidChannels.data(), invalidChannels.size()},
                actualLeft,
                actualRight,
                allocations)
                && allocations == 0
                && actualLeft == std::array<double, 4>{}
                && actualRight == std::array<double, 4>{},
            "C125 repeated Sqrt Magnitude retry should encounter the restored late input failure");

        left.fill(0.3F);
        right.fill(0.4F);
        const std::array<const float*, 2> repairedChannels{
            left.data(), right.data()};
        std::array<double, 4> expectedLeft{};
        std::array<double, 4> expectedRight{};
        require(
            renderStereoInputAndCount(
                candidate,
                {repairedChannels.data(), repairedChannels.size()},
                actualLeft,
                actualRight,
                allocations)
                && renderStereoInputAndCount(
                    pristine,
                    {repairedChannels.data(), repairedChannels.size()},
                    expectedLeft,
                    expectedRight,
                    allocations)
                && allocations == 0
                && actualLeft == expectedLeft
                && actualRight == expectedRight,
            "C125 repaired Sqrt Magnitude retry should restore input cursors, frame position, and output state");
    }
}

void testSqrtMagnitudeLifecycleCopiesPartitionsResetAndReplacementMatchExactly()
{
    auto settings = talas::runtime::RenderSettings{8.0, 5};
    settings.eventValues = {
        {"C125Left", 0.3, talas::expr::ValueDomain::Scalar},
        {"C125Right", 0.4, talas::expr::ValueDomain::Scalar},
    };
    for (const auto& document : {
             makeStereoSqrtMagnitudeDocument(
                 "!C125Left", "!C125Right"),
             makeMonoSqrtMagnitudeDocument()})
    {
        const auto graph = compile(document, settings);
        const auto copiedGraph = graph;
        talas::runtime::OfflineRenderSession offline(graph);
        talas::runtime::OfflineRenderSession copiedOffline(copiedGraph);
        talas::runtime::RealtimeRenderSession realtime(graph);
        talas::runtime::RealtimeRenderSession copiedRealtime(copiedGraph);
        require(realtime.ready() && copiedRealtime.ready(),
            "C125 original and copied Sqrt Magnitude lifecycle fixtures should prepare");

        for (const auto frames :
             std::array<std::size_t, 6>{1, 5, 2, 4, 3, 5})
        {
            const auto expected = offline.render(frames);
            const auto copied = copiedOffline.render(frames);
            std::vector<double> actual(frames);
            std::vector<double> copiedActual(frames);
            std::size_t allocations = 0;
            require(expected.ok() && copied.ok()
                    && copied.mono == expected.mono
                    && renderAndCount(realtime, actual, allocations)
                    && renderAndCount(
                        copiedRealtime, copiedActual, allocations)
                    && allocations == 0
                    && actual == expected.mono
                    && copiedActual == expected.mono,
                "C125 Sqrt Magnitude offline/prepared copies should match exactly across irregular partitions");
        }

        std::size_t allocations = 0;
        require(renderEmptyMonoAndCount(realtime, allocations)
                && renderEmptyMonoAndCount(copiedRealtime, allocations)
                && allocations == 0,
            "C125 zero-frame callback should preserve copied Sqrt Magnitude execution");

        offline.reset();
        copiedOffline.reset();
        realtime.resetTransport();
        copiedRealtime.resetTransport();
        const auto expected = offline.render(5);
        const auto copied = copiedOffline.render(5);
        talas::runtime::RealtimeRenderSession replacement(graph);
        std::array<double, 5> actual{};
        std::array<double, 5> copiedActual{};
        std::array<double, 5> replaced{};
        require(replacement.ready() && expected.ok() && copied.ok()
                && copied.mono == expected.mono
                && renderAndCount(realtime, actual, allocations)
                && renderAndCount(
                    copiedRealtime, copiedActual, allocations)
                && renderAndCount(replacement, replaced, allocations)
                && allocations == 0
                && std::ranges::equal(actual, expected.mono)
                && std::ranges::equal(copiedActual, expected.mono)
                && std::ranges::equal(replaced, expected.mono),
            "C125 reset, copies, replacement, mono/dual fallback, and offline Sqrt Magnitude should reproduce a fresh exact stream");
    }
}

void testSqrtMagnitudeDownstreamFailureRestoresNeighborStateForRetry()
{
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.eventValues = {{
        "C125FailureScale", 0.25,
        talas::expr::ValueDomain::Scalar}};
    const auto graph = compile(
        makeDownstreamFailureSqrtMagnitudeDocument(), settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession pristine(graph);
    require(candidate.ready() && pristine.ready(),
        "C125 Sqrt Magnitude downstream-failure fixtures should prepare");

    std::array<double, 4> actual{};
    std::array<double, 4> expected{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, actual, allocations)
            && renderAndCount(pristine, expected, allocations)
            && allocations == 0 && actual == expected,
        "C125 downstream fixtures should establish identical accepted oscillator and magnitude state");

    require(candidate.updateEventValue(
                "C125FailureScale",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C125 downstream fixture should admit its finite overflow-producing gain");
    actual.fill(125.0);
    require(!renderAndCount(candidate, actual, allocations)
            && allocations == 0
            && actual == std::array<double, 4>{},
        "C125 downstream Mixer overflow should publish no output prefix");

    require(candidate.updateEventValue(
                "C125FailureScale", 0.25,
                talas::expr::ValueDomain::Scalar),
        "C125 downstream fixture should admit its repaired gain");
    require(renderAndCount(candidate, actual, allocations)
            && renderAndCount(pristine, expected, allocations)
            && allocations == 0 && actual == expected,
        "C125 repaired downstream retry should restore both oscillator producers, Event Value, frame, and output state");
}

void testRealtimeSessionRendersPhaseShiftBy90AcrossBlocksWithoutAllocations()
{
    auto graph = compile(makePhaseShiftBy90Document());
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 2> first{};
    std::array<double, 2> second{};
    std::size_t allocations = 0;
    require(renderAndCount(session, first, allocations), "first Phase Shift By 90 block should render");
    require(allocations == 0, "first Phase Shift By 90 block should not allocate");
    require(renderAndCount(session, second, allocations), "second Phase Shift By 90 block should render");
    require(allocations == 0, "second Phase Shift By 90 block should not allocate");
    const auto rootTwo = std::sqrt(2.0);
    const auto r = rootTwo - 1.0;
    requireNear(first[0], 0.0, 1.0e-12, "Phase Shift By 90 first frame");
    requireNear(first[1], r, 1.0e-12, "Phase Shift By 90 left branch should match its first target-frequency impulse sample");
    requireNear(second[0], -2.0 * r, 1.0e-12, "Phase Shift By 90 left branch should retain its allpass history across blocks");
    requireNear(second[1], -(5.0 - 3.0 * rootTwo), 1.0e-12, "Phase Shift By 90 left branch should continue the target-frequency impulse response");
}

void testRealtimePhaseShiftBy90ConnectedFallbackResetAndFreshReplayAreExact()
{
    auto document = makePhaseShiftBy90Document();
    const auto phase = std::ranges::find(
        document.graph.nodes,
        std::string_view{"phase"},
        &talas::project::ProjectNode::instanceId);
    require(phase != document.graph.nodes.end(),
        "C100 connected fallback fixture should expose its phase node");
    phase->parameters[0].expression = "1e200 * 1e200";
    document.graph.nodes.push_back(node(
        "frequency", "talas.constant", {{"value", "1"}}));
    document.graph.connections.push_back(connection(
        "frequency", "value", "phase", "frequency"));

    const auto graph = compile(document, {4.0, 2});
    const auto offline = talas::runtime::renderOffline(graph, 4);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession fresh(graph);
    require(offline.ok() && candidate.ready() && fresh.ready(),
        "C100 connected frequency should hide its invalid fallback in offline and prepared execution: "
            + std::string{candidate.error()});

    std::array<double, 2> warm{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, warm, allocations)
            && allocations == 0
            && renderAndCount(candidate, warm, allocations)
            && allocations == 0,
        "C100 connected allpass should establish state without allocation");
    std::size_t resetAllocations = 0;
    {
        AllocationCounter counter;
        candidate.resetTransport();
        resetAllocations = counter.count();
    }
    std::array<double, 2> reset{};
    std::array<double, 2> expected{};
    require(resetAllocations == 0
            && renderAndCount(candidate, reset, allocations)
            && allocations == 0
            && renderAndCount(fresh, expected, allocations)
            && allocations == 0
            && reset == expected,
        "C100 transport reset should restore the exact fresh allpass and connected-authority state without allocation");
}

