void testPhaseShiftBy90DirectScheduleMatchesOfflinePreparedAndLifecycle()
{
    const auto document = makePhaseShiftBy90Document({
        {"frequency", "!C165Frequency"},
    });
    auto preparedSettings = talas::runtime::RenderSettings{8.0, 8};
    preparedSettings.maxRealtimeEventTransactions = 4;
    preparedSettings.eventValues = {
        {"C165Frequency", 0.5, talas::expr::ValueDomain::Hertz},
    };
    auto offlineSettings = preparedSettings;
    offlineSettings.eventValueChanges = {
        {2, "C165Frequency", 1.0, talas::expr::ValueDomain::Hertz},
        {5, "C165Frequency", 1.5, talas::expr::ValueDomain::Hertz},
    };
    const auto offlineGraph = compile(document, offlineSettings);
    const auto preparedGraph = compile(document, preparedSettings);
    const auto offline = talas::runtime::renderOffline(offlineGraph, 8);
    talas::runtime::RealtimeRenderSession prepared{preparedGraph};
    require(offline.ok() && prepared.ready(),
        "C165 direct frequency schedule should render offline and prepare realtime: "
            + std::string{prepared.error()});
    require(prepared.scheduleEventValue(
                "C165Frequency", 1.0,
                talas::expr::ValueDomain::Hertz, 2)
            && prepared.scheduleEventValue(
                "C165Frequency", 1.5,
                talas::expr::ValueDomain::Hertz, 5),
        "C165 prepared frequency schedule should stage exact absolute-frame updates");

    std::array<double, 8> actual{};
    std::size_t allocations = 0;
    require(renderEmptyMonoAndCount(prepared, allocations)
            && allocations == 0,
        "C165 zero-frame callback should be an allocation-free no-op");
    std::size_t offset = 0;
    for (const auto frames : std::array<std::size_t, 3>{1, 2, 5})
    {
        require(renderAndCount(
                    prepared,
                    std::span<double>{actual}.subspan(offset, frames),
                    allocations)
                && allocations == 0,
            "C165 irregular prepared partition should render without allocation");
        offset += frames;
    }
    require(std::ranges::equal(actual, offline.mono),
        "C165 direct frequency schedule should be bit-identical offline and prepared across partitions");

    prepared.resetTransport();
    talas::runtime::RealtimeRenderSession fresh{preparedGraph};
    std::array<double, 8> reset{};
    std::array<double, 8> expected{};
    require(fresh.ready()
            && renderEmptyMonoAndCount(prepared, allocations)
            && allocations == 0
            && renderAndCount(prepared, reset, allocations)
            && allocations == 0
            && renderAndCount(fresh, expected, allocations)
            && allocations == 0
            && reset == expected,
        "C165 transport reset should reproduce fresh allpass state and initial frequency exactly");

    talas::runtime::RealtimeRenderSession failing{preparedGraph};
    require(failing.ready(),
        "C165 late Nyquist fixture should prepare");
    // A frequency at Nyquist saturates below it (owner, 2026-10-12).
    require(!failing.scheduleEventValue(
                "C165Frequency", std::numeric_limits<double>::quiet_NaN(),
                talas::expr::ValueDomain::Hertz, 2),
        "C165 direct scheduler should reject a frequency that is not a number before mutating callback state");
    std::array<double, 4> repaired{};
    std::array<double, 4> pristine{};
    talas::runtime::RealtimeRenderSession replacement{preparedGraph};
    require(replacement.ready()
            && renderAndCount(failing, repaired, allocations)
            && allocations == 0
            && renderAndCount(replacement, pristine, allocations)
            && allocations == 0
            && repaired == pristine,
        "C165 rejected direct update should leave the exact fresh callback state intact");
}

void testSingleSideBandRmDirectSchedulesMatchOfflinePreparedAndLifecycle()
{
    const auto document = makeSingleSideBandRmDocument(
        "!C166Frequency", "!C166FreqScale");
    auto preparedSettings = talas::runtime::RenderSettings{8.0, 8};
    preparedSettings.maxRealtimeEventTransactions = 8;
    preparedSettings.eventValues = {
        {"C166Frequency", 0.5, talas::expr::ValueDomain::Hertz},
        {"C166FreqScale", 0.5, talas::expr::ValueDomain::Scalar},
    };
    auto offlineSettings = preparedSettings;
    offlineSettings.eventValueChanges = {
        {2, "C166Frequency", 1.0, talas::expr::ValueDomain::Hertz},
        {2, "C166FreqScale", 1.0, talas::expr::ValueDomain::Scalar},
        {5, "C166Frequency", 1.5, talas::expr::ValueDomain::Hertz},
        {5, "C166FreqScale", 2.0, talas::expr::ValueDomain::Scalar},
    };
    const auto offlineGraph = compile(document, offlineSettings);
    const auto preparedGraph = compile(document, preparedSettings);
    const auto offline = talas::runtime::renderOffline(offlineGraph, 8);
    talas::runtime::RealtimeRenderSession prepared{preparedGraph};
    require(offline.ok() && prepared.ready(),
        "C166 direct dual schedules should render offline and prepare realtime: "
            + std::string{prepared.error()});
    const std::array<talas::runtime::RealtimeEventValueUpdate, 2>
        frame2{{
            {"C166Frequency", 1.0,
                talas::expr::ValueDomain::Hertz},
            {"C166FreqScale", 1.0,
                talas::expr::ValueDomain::Scalar},
        }};
    const std::array<talas::runtime::RealtimeEventValueUpdate, 2>
        frame5{{
            {"C166Frequency", 1.5,
                talas::expr::ValueDomain::Hertz},
            {"C166FreqScale", 2.0,
                talas::expr::ValueDomain::Scalar},
        }};
    require(prepared.scheduleEventValues(frame2, 2)
            && prepared.scheduleEventValues(frame5, 5),
        "C166 prepared shifter should stage both exact absolute-frame schedules");

    std::array<double, 8> actual{};
    std::size_t allocations = 0;
    const auto renderedEmpty = renderEmptyMonoAndCount(
        prepared, allocations);
    require(renderedEmpty,
        "C166 zero-frame callback should succeed as a no-op");
    require(allocations == 0,
        "C166 zero-frame callback should allocate nothing");
    std::size_t offset = 0;
    for (const auto frames : std::array<std::size_t, 3>{1, 2, 5})
    {
        require(renderAndCount(
                    prepared,
                    std::span<double>{actual}.subspan(offset, frames),
                    allocations)
                && allocations == 0,
            "C166 irregular prepared partition should render without allocation");
        offset += frames;
    }
    require(std::ranges::equal(actual, offline.mono),
        "C166 direct dual schedules should be bit-identical offline and prepared across partitions");

    prepared.resetTransport();
    talas::runtime::RealtimeRenderSession fresh{preparedGraph};
    std::array<double, 8> reset{};
    std::array<double, 8> expected{};
    require(fresh.ready()
            && renderEmptyMonoAndCount(prepared, allocations)
            && allocations == 0
            && renderAndCount(prepared, reset, allocations)
            && allocations == 0
            && renderAndCount(fresh, expected, allocations)
            && allocations == 0
            && reset == expected,
        "C166 transport reset should reproduce fresh allpass, phase, and initial dual controls exactly");

    talas::runtime::RealtimeRenderSession invalidFrequency{preparedGraph};
    talas::runtime::RealtimeRenderSession invalidScale{preparedGraph};
    require(invalidFrequency.ready() && invalidScale.ready(),
        "C166 invalid direct-update fixtures should prepare");
    // A frequency at Nyquist and a zero scale saturate (owner, 2026-10-12).
    require(!invalidFrequency.scheduleEventValue(
                "C166Frequency", std::numeric_limits<double>::quiet_NaN(),
                talas::expr::ValueDomain::Hertz, 2)
            && !invalidScale.scheduleEventValue(
                "C166FreqScale", std::numeric_limits<double>::quiet_NaN(),
                talas::expr::ValueDomain::Scalar, 2),
        "C166 direct scheduler should reject a frequency and scale that are not numbers before state mutation");
    std::array<double, 4> repairedFrequency{};
    std::array<double, 4> repairedScale{};
    std::array<double, 4> pristine{};
    talas::runtime::RealtimeRenderSession replacement{preparedGraph};
    require(replacement.ready()
            && renderAndCount(
                invalidFrequency, repairedFrequency, allocations)
            && allocations == 0
            && renderAndCount(invalidScale, repairedScale, allocations)
            && allocations == 0
            && renderAndCount(replacement, pristine, allocations)
            && allocations == 0
            && repairedFrequency == pristine
            && repairedScale == pristine,
        "C166 rejected direct updates should leave the exact fresh callback state intact");
}

void testRealtimePhaseShiftBy90OwnsDownstreamFailureRollback()
{
    auto document = makePhaseShiftBy90Document({
        {"frequency", "!C165Frequency"},
    });
    const auto source = std::ranges::find(
        document.graph.nodes,
        std::string_view{"source"},
        &talas::project::ProjectNode::instanceId);
    require(source != document.graph.nodes.end(),
        "C100 rollback fixture should expose its source");
    source->typeId = "talas.audioInput";
    source->parameters = {
        choiceParameter("routing", "monoSum"),
        booleanParameter("channel1", true),
        booleanParameter("channel2", false),
    };
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C100Downstream"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    std::erase_if(document.graph.connections, [](const auto& edge) {
        return edge.fromNode == "phase" && edge.toNode == "out";
    });
    document.graph.connections.push_back(connection(
        "phase", "audioOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.eventValues = {
        {"C165Frequency", 1.0, talas::expr::ValueDomain::Hertz},
        {"C100Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(candidate.ready() && reference.ready(),
        "C165 module-owned direct-schedule rollback fixtures should prepare: "
            + std::string{candidate.error()});
    require(candidate.updateEventValue(
                "C100Downstream",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C165 rollback fixture should arm its late downstream failure");
    require(candidate.scheduleEventValue(
                "C165Frequency", 1.5,
                talas::expr::ValueDomain::Hertz, 2)
            && reference.scheduleEventValue(
                "C165Frequency", 1.5,
                talas::expr::ValueDomain::Hertz, 2),
        "C165 rollback fixtures should accept the same direct frequency update");
    std::array<float, 4> inputChannel{0.0F, 0.0F, 2.0F, 2.0F};
    std::array<const float*, 1> inputChannels{inputChannel.data()};
    const talas::runtime::RealtimeAudioInputBlock inputBlock{
        inputChannels.data(), inputChannels.size()};
    std::array<double, 4> rejectedLeft;
    std::array<double, 4> rejectedRight;
    rejectedLeft.fill(100.0);
    rejectedRight.fill(100.0);
    std::size_t allocations = 0;
    require(!renderStereoInputAndCount(
                candidate,
                inputBlock,
                rejectedLeft,
                rejectedRight,
                allocations)
            && allocations == 0
            && rejectedLeft == std::array<double, 4>{}
            && rejectedRight == std::array<double, 4>{},
        "C165 late downstream failure should publish no callback audio");
    require(candidate.updateEventValue(
                "C100Downstream", 1.0,
                talas::expr::ValueDomain::Scalar),
        "C165 rollback fixture should repair its downstream control");
    std::array<double, 4> retryLeft{};
    std::array<double, 4> retryRight{};
    std::array<double, 4> expectedLeft{};
    std::array<double, 4> expectedRight{};
    require(renderStereoInputAndCount(
                candidate,
                inputBlock,
                retryLeft,
                retryRight,
                allocations)
            && allocations == 0
            && renderStereoInputAndCount(
                reference,
                inputBlock,
                expectedLeft,
                expectedRight,
                allocations)
            && allocations == 0
            && retryLeft == expectedLeft
            && retryRight == expectedRight,
        "C165 should restore its accepted direct schedule, live frequency, and allpass state before retry after a later failure");
}

void testRealtimePhaseShiftBy90RejectsForgedPreparedAuthority()
{
    auto document = makePhaseShiftBy90Document();
    document.graph.nodes.push_back(node(
        "frequency", "talas.constant", {{"value", "1"}}));
    document.graph.connections.push_back(connection(
        "frequency", "value", "phase", "frequency"));
    const auto graph = compile(document, {4.0, 2});
    const auto requireRejected = [&](auto mutate,
                                     std::string_view context) {
        auto plan = graph.plan();
        const auto step = std::ranges::find(
            plan.steps,
            std::string_view{"talas.phaseShiftBy90"},
            &talas::runtime::CompileStep::typeId);
        require(step != plan.steps.end(),
            "C100 forged-authority fixture should expose Phase Shift By 90");
        mutate(*step);
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), graph.renderSettings()});
        require(!session.ready(), std::string{context}
                + " should reject forged C100 Phase Shift By 90 authority");
    };
    requireRejected(
        [](auto& step) { step.supportsReset = false; },
        "forged reset capability");
    requireRejected(
        [](auto& step) { step.resolvedLatencyFrames = 1; },
        "forged intrinsic latency");
    requireRejected(
        [](auto& step) {
            step.offlineSupport =
                talas::core::ExecutionSupport::Supported;
        },
        "forged offline support");
    requireRejected(
        [](auto& step) { step.parameters[0].id = "wrong"; },
        "forged parameter identity");
    requireRejected(
        [](auto& step) { step.inputs[0].inputPortId = "frequency"; },
        "forged input order");
    requireRejected(
        [](auto& step) {
            step.preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
            step.kernelKind = talas::runtime::KernelKind::Gate;
        },
        "forged prepared binding");
}

