void testRealtimeLfoRollsBackPhaseOnLaterFailureWithoutOscillatorOwner()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("input", "talas.audioInput"),
        node("lfoVca", "talas.vca"),
        node("lfo", "talas.lfo", {
            {"frequency", "1 hz"}, {"minimum", "2"},
            {"maximum", "3"},
        }),
        node("failureGain", "talas.constant", {
            {"value", "!C96Downstream"},
        }),
        node("failureProduct", "talas.product"),
        node("failureVca", "talas.vca"),
    };
    document.graph.connections = {
        connection("input", "audioOut", "lfoVca", "audioIn"),
        connection("lfo", "value", "lfoVca", "gain"),
        connection("lfoVca", "audioOut", "failureVca", "audioIn"),
        connection("lfo", "value", "failureProduct", "left"),
        connection("failureGain", "value", "failureProduct", "right"),
        connection("failureProduct", "value", "failureVca", "gain"),
        connection("failureVca", "audioOut", "out", "audioIn"),
    };
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.eventValues = {
        {"C96Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(candidate.ready() && reference.ready(),
        "C96 LFO-owned rollback fixtures should prepare without an Oscillator owner: "
            + std::string{candidate.error()});

    std::array<float, 4> inputSamples{1.0F, 1.0F, 1.0F, 1.0F};
    std::array<const float*, 1> inputChannels{inputSamples.data()};
    const talas::runtime::RealtimeAudioInputBlock input{
        inputChannels.data(), inputChannels.size()};
    std::array<double, 4> candidateWarm{};
    std::array<double, 4> referenceWarm{};
    std::array<double, 4> right{};
    std::size_t allocations = 0;
    require(
        renderStereoInputAndCount(
            candidate, input, candidateWarm, right, allocations)
            && allocations == 0
            && renderStereoInputAndCount(
                reference, input, referenceWarm, right, allocations)
            && allocations == 0
            && candidateWarm == referenceWarm,
        "C96 LFO-owned rollback fixtures should establish matching phase");
    require(candidate.updateEventValue(
                "C96Downstream", std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C96 rollback fixture should arm a later finite-input overflow");
    std::array<double, 4> rejected;
    rejected.fill(96.0);
    require(
        !renderStereoInputAndCount(
            candidate, input, rejected, right, allocations)
            && allocations == 0
            && rejected == std::array<double, 4>{},
        "C96 later failure should publish no callback prefix");
    require(candidate.updateEventValue(
                "C96Downstream", 1.0,
                talas::expr::ValueDomain::Scalar),
        "C96 rollback fixture should repair its downstream control");
    std::array<double, 4> retry{};
    std::array<double, 4> expected{};
    require(
        renderStereoInputAndCount(
            candidate, input, retry, right, allocations)
            && allocations == 0
            && renderStereoInputAndCount(
                reference, input, expected, right, allocations)
            && allocations == 0
            && retry == expected,
        "C96 later failure should restore exact LFO phase before retry");
}

void testRealtimeLfoAppliesScheduledDirectControlsSampleAccurately()
{
    auto document = makeLfoVcaDocument();
    const auto lfo = std::ranges::find(
        document.graph.nodes, std::string_view{"lfo"},
        &talas::project::ProjectNode::instanceId);
    require(lfo != document.graph.nodes.end(),
        "C96 scheduled-control fixture should expose LFO");
    for (auto& parameter : lfo->parameters)
    {
        if (parameter.parameterId == "frequency")
            parameter.expression = "!C96LfoFrequency * 1 hz";
        else if (parameter.parameterId == "minimum")
            parameter.expression = "!C96LfoMinimum";
        else if (parameter.parameterId == "maximum")
            parameter.expression = "!C96LfoMaximum";
    }
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.eventValues = {
        {"C96LfoFrequency", 0.0, talas::expr::ValueDomain::Scalar},
        {"C96LfoMinimum", 0.0, talas::expr::ValueDomain::Scalar},
        {"C96LfoMaximum", 2.0, talas::expr::ValueDomain::Scalar},
    };
    talas::runtime::RealtimeRenderSession session(
        compile(document, settings));
    require(session.ready(),
        "C96 scheduled direct-control fixture should prepare: "
            + std::string{session.error()});
    require(
        session.scheduleEventValue(
            "C96LfoMinimum", 2.0,
            talas::expr::ValueDomain::Scalar, 2)
            && session.scheduleEventValue(
                "C96LfoMaximum", 4.0,
                talas::expr::ValueDomain::Scalar, 2),
        "C96 LFO should accept same-frame scheduled endpoint updates");

    std::array<double, 4> output{};
    std::size_t allocations = 0;
    require(renderAndCount(session, output, allocations)
            && allocations == 0,
        "C96 scheduled direct-control callback should render without allocation");
    const auto rootHalf = std::sqrt(0.5);
    requireNear(output[0], 0.0, 1.0e-12,
        "C96 scheduled LFO frame zero");
    requireNear(output[1], rootHalf, 1.0e-12,
        "C96 scheduled LFO should retain the initial range before the event");
    requireNear(output[2], 3.0, 1.0e-12,
        "C96 scheduled LFO should apply both endpoint updates at the target frame");
    requireNear(output[3], 3.0 * rootHalf, 1.0e-12,
        "C96 scheduled LFO should retain the updated range after the event");
}

void testRealtimeLfoRejectsForgedPreparedAuthority()
{
    const auto graph = compile(
        makeLfoVcaDocument(), {4.0, 4});
    const auto requireRejected = [&](auto mutate,
                                     std::string_view context) {
        auto plan = graph.plan();
        const auto lfo = std::ranges::find(
            plan.steps, std::string_view{"talas.lfo"},
            &talas::runtime::CompileStep::typeId);
        require(lfo != plan.steps.end(),
            "C96 forged-authority fixture should expose LFO");
        mutate(*lfo);
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), graph.renderSettings()});
        require(!session.ready(),
            std::string{context}
                + " should reject forged C96 LFO authority");
    };
    requireRejected(
        [](auto& lfo) { lfo.supportsReset = false; },
        "forged reset capability");
    requireRejected(
        [](auto& lfo) {
            lfo.preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
            lfo.kernelKind = talas::runtime::KernelKind::Gate;
        },
        "forged kernel binding");
    requireRejected(
        [](auto& lfo) { lfo.resolvedLatencyFrames = 1; },
        "forged intrinsic latency");
    requireRejected(
        [](auto& lfo) { lfo.preparedIsolatedComponent = true; },
        "forged isolation authority");
}

void testRealtimeLfoAdmitsNestedParentScopeOverrideAuthority()
{
    talas::project::ProjectSoundDefinition definition;
    definition.definitionId = "c96LfoCell";
    definition.displayName = "C96 LFO Cell";
    definition.graph.nodes = {
        node("lfo", "talas.lfo", {
            {"frequency", "1 hz"}, {"minimum", "0"},
            {"maximum", "1"},
        }),
    };
    definition.outputs = {{
        "value", talas::core::PortType::Control, "lfo", "value",
    }};
    talas::project::ProjectSoundExposedParameter frequency;
    frequency.parameterId = "frequency";
    frequency.displayName = "Frequency";
    frequency.domain = talas::expr::ValueDomain::Hertz;
    frequency.defaultValue = {"frequency", "1 hz"};
    frequency.bindings.push_back({
        talas::project::ProjectSoundParameterTarget::NodeParameter,
        "lfo",
        "frequency",
        {},
        talas::expr::ValueDomain::Hertz,
    });
    definition.exposedParameters.push_back(std::move(frequency));

    talas::project::ProjectNode instance;
    instance.instanceId = "lfoCell";
    instance.soundDefinitionId = definition.definitionId;
    instance.parameters = {{"frequency", "0.5 hz"}};

    talas::project::ProjectDocument document;
    document.soundDefinitions.push_back(std::move(definition));
    document.graph.nodes = {
        std::move(instance),
        node("carrier", "talas.oscillator", {
            {"frequency", "1 hz"}, {"amplitude", "1"},
        }),
        node("vca", "talas.vca"),
        node("out", "talas.audioOutput"),
    };
    document.graph.connections = {
        connection("carrier", "audioOut", "vca", "audioIn"),
        connection("lfoCell", "value", "vca", "gain"),
        connection("vca", "audioOut", "out", "audioIn"),
    };

    const auto graph = compile(document, {4.0, 4});
    const auto lfo = std::ranges::find(
        graph.plan().steps, std::string_view{"talas.lfo"},
        &talas::runtime::CompileStep::typeId);
    require(lfo != graph.plan().steps.end()
            && lfo->scopeId != talas::runtime::globalRuntimeScope
            && lfo->parameters.front().variableScopeId
                == talas::runtime::globalRuntimeScope,
        "C96 nested LFO should retain caller-owned parent parameter scope");
    talas::runtime::RealtimeRenderSession session(graph);
    std::array<double, 4> output{};
    std::size_t allocations = 0;
    require(session.ready()
            && renderAndCount(session, output, allocations)
            && allocations == 0,
        "C96 legitimate nested parent-scope LFO override should prepare and render without allocation: "
            + std::string{session.error()});
}

