void requireTalasRampRealtimeMatchesOffline(
    const talas::project::ProjectDocument& document,
    std::size_t frameCount,
    const std::string& context,
    std::size_t blockFrames = 2)
{
    require(frameCount % blockFrames == 0, context + " frame count should contain whole blocks");
    talas::runtime::RenderSettings settings{4.0, blockFrames};
    auto graph = compile(document, std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, frameCount);
    require(expected.ok(), context + " offline reference should render");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), context + ": " + std::string(session.error()));

    std::vector<double> actual(frameCount, 0.0);
    std::size_t allocations = 0;
    for (std::size_t frame = 0; frame < frameCount; frame += blockFrames)
    {
        require(renderAndCount(session, std::span<double>{actual}.subspan(frame, blockFrames), allocations), context + " realtime block should render");
        require(allocations == 0, context + " realtime block should not allocate");
    }
    for (std::size_t frame = 0; frame < frameCount; ++frame)
        requireNear(actual[frame], expected.mono[frame], 1.0e-12, context + " offline/realtime frame");
}

