void testRealtimeSessionDirectTalasRampMatchesConnectedLifecycleAndCapturesDuration()
{
    talas::runtime::RenderSettings settings{4.0, 2};
    settings.eventValues = {
        {"RampTrigger", 0.0, talas::expr::ValueDomain::Scalar},
        {"RampDuration", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto directGraph = compile(makeDirectEventValueTalasRampVcaDocument(), settings);
    auto connectedGraph = compile(makeDirectEventValueTalasRampVcaDocument(true), std::move(settings));
    talas::runtime::RealtimeRenderSession direct(directGraph);
    talas::runtime::RealtimeRenderSession connected(connectedGraph);
    require(direct.ready(), std::string(direct.error()));
    require(connected.ready(), std::string(connected.error()));

    std::array<double, 2> directBlock{};
    std::array<double, 2> connectedBlock{};
    std::size_t allocations = 0;
    const auto renderMatchingBlock = [&](const std::string& context) {
        require(renderAndCount(direct, directBlock, allocations), context + " direct block should render");
        require(allocations == 0, context + " direct block should not allocate");
        require(renderAndCount(connected, connectedBlock, allocations), context + " connected block should render");
        require(allocations == 0, context + " connected block should not allocate");
        for (std::size_t frame = 0; frame < directBlock.size(); ++frame)
            requireNear(directBlock[frame], connectedBlock[frame], 1.0e-12, context + " direct/connected frame");
    };

    renderMatchingBlock("resting");
    for (auto* session : {&direct, &connected})
        require(session->updateEventValue("RampTrigger", 1.0, talas::expr::ValueDomain::Scalar), "Ramp trigger should rise");
    renderMatchingBlock("triggered");
    for (auto* session : {&direct, &connected})
        require(session->updateEventValue("RampDuration", 0.5, talas::expr::ValueDomain::Scalar), "Ramp duration should update while active");
    renderMatchingBlock("captured-duration");
    requireNear(directBlock[1], 0.75, 1.0e-12, "active Ramp should retain its captured one-second duration");
    for (auto* session : {&direct, &connected})
        require(session->updateEventValue("RampTrigger", 0.0, talas::expr::ValueDomain::Scalar), "Ramp trigger should close");
    renderMatchingBlock("released");
    for (auto* session : {&direct, &connected})
        require(session->updateEventValue("RampTrigger", 1.0, talas::expr::ValueDomain::Scalar), "Ramp trigger should retrigger");
    renderMatchingBlock("retriggered");
    requireNear(directBlock[1], 0.5, 1.0e-12, "retriggered Ramp should capture the updated half-second duration");
}

void testRealtimeSessionRejectsInvalidDirectTalasRampTransaction()
{
    talas::runtime::RenderSettings settings{4.0, 2};
    settings.eventValues = {
        {"RampTrigger", 0.0, talas::expr::ValueDomain::Scalar},
        {"RampDuration", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto candidateGraph = compile(makeDirectEventValueTalasRampVcaDocument(), settings);
    auto referenceGraph = compile(makeDirectEventValueTalasRampVcaDocument(), std::move(settings));
    talas::runtime::RealtimeRenderSession candidate(candidateGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(candidate.ready(), std::string(candidate.error()));
    require(reference.ready(), std::string(reference.error()));

    // A zero duration saturates at one sample (owner, 2026-10-12).
    require(!candidate.updateEventValue("RampDuration", std::numeric_limits<double>::quiet_NaN(), talas::expr::ValueDomain::Scalar), "a direct Ramp duration that is not a number should reject the transaction");
    require(
        !candidate.updateEventValue("RampDuration", 2305843009213693952.0, talas::expr::ValueDomain::Scalar),
        "direct Ramp duration reaching 2^63 frames should reject the transaction");
    for (auto* session : {&candidate, &reference})
        require(session->updateEventValue("RampTrigger", 1.0, talas::expr::ValueDomain::Scalar), "Ramp trigger should update after rejected transaction");
    std::array<double, 2> candidateBlock{};
    std::array<double, 2> referenceBlock{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, candidateBlock, allocations), "Ramp rollback candidate should render");
    require(allocations == 0, "Ramp rollback candidate should not allocate");
    require(renderAndCount(reference, referenceBlock, allocations), "Ramp rollback reference should render");
    require(allocations == 0, "Ramp rollback reference should not allocate");
    for (std::size_t frame = 0; frame < candidateBlock.size(); ++frame)
        requireNear(candidateBlock[frame], referenceBlock[frame], 1.0e-12, "rejected Ramp transaction should preserve prior values");
}

