void testRealtimeRampTransportResetMatchesFreshEdgeState()
{
    auto document = makeTalasRampVcaDocument("ramp");
    const auto carrier = std::ranges::find(
        document.graph.nodes, std::string_view{"carrier"},
        &talas::project::ProjectNode::instanceId);
    require(carrier != document.graph.nodes.end(),
        "C97 Ramp reset fixture should expose its carrier");
    carrier->typeId = "talas.oscillator";
    carrier->parameters = {
        {"frequency", "1 hz"}, {"amplitude", "1"},
    };

    const auto graph = compile(document, {8.0, 4});
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession fresh(graph);
    require(candidate.ready() && fresh.ready(),
        "C97 Ramp reset fixtures should prepare");
    std::array<double, 4> warm{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, warm, allocations)
            && allocations == 0,
        "C97 Ramp reset fixture should advance without allocation");
    candidate.resetTransport();
    std::array<double, 4> reset{};
    std::array<double, 4> expected{};
    require(renderAndCount(candidate, reset, allocations)
            && allocations == 0
            && renderAndCount(fresh, expected, allocations)
            && allocations == 0
            && reset == expected,
        "C97 Ramp transport reset should restore exact fresh edge and duration state");
}

void testRealtimeRampRestoresLateInvalidScheduleCursorWithoutPublication()
{
    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.eventValues = {
        {"RampTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        {"RampDuration", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto document =
        makeDirectEventValueTalasRampVcaDocument(true);
    talas::runtime::RealtimeRenderSession candidate(
        compile(document, settings));
    require(candidate.ready(),
        "C97 late connected Ramp failure fixture should prepare");
    require(candidate.scheduleEventValue(
                "RampDuration", 0.0,
                talas::expr::ValueDomain::Scalar, 2),
        "C97 connected Ramp duration should accept a scheduled value for callback validation");

    std::array<double, 4> rejected;
    rejected.fill(97.0);
    std::size_t allocations = 0;
    require(!renderAndCount(candidate, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 4>{},
        "C97 late invalid connected Ramp duration should publish no callback prefix");
    rejected.fill(97.0);
    require(!renderAndCount(candidate, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 4>{},
        "C97 repeated callback should encounter the restored invalid scheduled event again without publication");
}

void testRealtimeRampRejectsForgedPreparedAuthority()
{
    const auto graph = compile(
        makeTalasRampVcaDocument("ramp"), {4.0, 4});
    const auto requireRejected = [&](auto mutate,
                                     std::string_view context) {
        auto plan = graph.plan();
        const auto ramp = std::ranges::find(
            plan.steps, std::string_view{"talas.ramp"},
            &talas::runtime::CompileStep::typeId);
        require(ramp != plan.steps.end(),
            "C97 forged-authority fixture should expose Ramp");
        mutate(*ramp);
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), graph.renderSettings()});
        require(!session.ready(),
            std::string{context}
                + " should reject forged C97 Ramp authority");
    };
    requireRejected(
        [](auto& ramp) { ramp.supportsReset = false; },
        "forged reset capability");
    requireRejected(
        [](auto& ramp) {
            ramp.preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
            ramp.kernelKind = talas::runtime::KernelKind::Gate;
        },
        "forged kernel binding");
    requireRejected(
        [](auto& ramp) { ramp.resolvedLatencyFrames = 1; },
        "forged intrinsic latency");
    requireRejected(
        [](auto& ramp) {
            std::swap(ramp.parameters[0], ramp.parameters[1]);
        },
        "forged parameter order");
}

