void testRealtimeSampleAndHoldRejectsForgedPreparedAuthority()
{
    const auto graph = compile(
        makeConnectedSampleAndHoldVcaDocument(),
        talas::runtime::RenderSettings{
            .sampleRate = 4.0,
            .maxBlockFrames = 4,
            .eventValues = {{
                "HoldTime", 0.5,
                talas::expr::ValueDomain::Scalar}},
        });
    const auto requireRejected = [&](auto mutate,
                                     std::string_view context) {
        auto plan = graph.plan();
        const auto hold = std::ranges::find(
            plan.steps, std::string_view{"talas.sampleAndHold"},
            &talas::runtime::CompileStep::typeId);
        require(hold != plan.steps.end(),
            "C98 forged-authority fixture should expose Sample And Hold");
        mutate(*hold);
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), graph.renderSettings()});
        require(!session.ready(), std::string{context}
                + " should reject forged C98 Sample And Hold authority");
    };
    requireRejected(
        [](auto& hold) { hold.supportsReset = false; },
        "forged reset capability");
    requireRejected(
        [](auto& hold) {
            hold.preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
            hold.kernelKind = talas::runtime::KernelKind::Gate;
        },
        "forged kernel binding");
    requireRejected(
        [](auto& hold) { hold.resolvedLatencyFrames = 1; },
        "forged intrinsic latency");
    requireRejected(
        [](auto& hold) {
            std::swap(hold.parameters[0], hold.parameters[1]);
        },
        "forged parameter order");
    requireRejected(
        [](auto& hold) {
            std::swap(hold.inputs[0], hold.inputs[1]);
        },
        "forged input order");
}

void testRealtimeSampleAndHoldOwnsNoiseSiblingRollbackBoundary()
{
    const auto makeDocument = [] {
        auto document = makeSampleAndHoldVcaDocument();
        const auto carrier = std::ranges::find(
            document.graph.nodes, std::string_view{"carrier"},
            &talas::project::ProjectNode::instanceId);
        require(carrier != document.graph.nodes.end(),
            "C98 Noise rollback fixture should expose its carrier");
        carrier->typeId = "talas.noise";
        carrier->parameters = {
            {"initialState", "0.25"},
            {"frequency", "1 hz"},
            {"centerValue", "0"},
            {"scale", "1"},
            choiceParameter("type", "hotPink"),
        };
        document.graph.nodes.push_back(node(
            "z_failure", "talas.level", {
                {"left", "!C98NoiseDownstream"}, {"right", "0"},
                booleanParameter("noGain", false),
            }));
        std::erase_if(document.graph.connections, [](const auto& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });
        document.graph.connections.push_back(connection(
            "vca", "audioOut", "z_failure", "audioIn"));
        document.graph.connections.push_back(connection(
            "z_failure", "leftOut", "out", "audioIn"));
        return document;
    };

    auto settings = talas::runtime::RenderSettings{4.0, 3};
    settings.eventValues = {{
        "C98NoiseDownstream", 1.0,
        talas::expr::ValueDomain::Scalar}};
    talas::runtime::RealtimeRenderSession candidate(
        compile(makeDocument(), settings));
    talas::runtime::RealtimeRenderSession reference(
        compile(makeDocument(), settings));
    require(candidate.ready() && reference.ready(),
        "C98 Sample And Hold-owned Noise rollback fixtures should prepare: "
            + std::string{candidate.error()});

    std::array<double, 3> warmCandidate{};
    std::array<double, 3> warmReference{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, warmCandidate, allocations)
            && renderAndCount(reference, warmReference, allocations)
            && allocations == 0 && warmCandidate == warmReference,
        "C98 Sample And Hold/Noise fixtures should establish identical state");
    require(candidate.updateEventValue(
                "C98NoiseDownstream",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C98 Sample And Hold/Noise fixture should arm its downstream failure");
    std::array<double, 3> rejected;
    rejected.fill(98.0);
    require(!renderAndCount(candidate, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 3>{},
        "C98 downstream failure should publish no Sample And Hold/Noise prefix");
    require(candidate.updateEventValue(
                "C98NoiseDownstream", 1.0,
                talas::expr::ValueDomain::Scalar),
        "C98 Sample And Hold/Noise fixture should repair its downstream value");
    std::array<double, 3> retry{};
    std::array<double, 3> expected{};
    require(renderAndCount(candidate, retry, allocations)
            && renderAndCount(reference, expected, allocations)
            && allocations == 0 && retry == expected,
        "C98 Sample And Hold-owned transaction should restore clock, latch, and Noise state before retry");
}

