void testRealtimeTriggeredSampleAndHoldDirectScheduleMatchesOfflinePartitions()
{
    const auto document = makeDirectEventValueTriggeredSampleAndHoldVcaDocument();
    auto preparedSettings = talas::runtime::RenderSettings{8.0, 6};
    preparedSettings.eventValues = {{
        "SampleTrigger", 0.0, talas::expr::ValueDomain::Scalar}};
    auto offlineSettings = preparedSettings;
    offlineSettings.eventValueChanges = {
        {1, "SampleTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        {3, "SampleTrigger", -0.0, talas::expr::ValueDomain::Scalar},
        {4, "SampleTrigger", 1.0, talas::expr::ValueDomain::Scalar},
    };

    const auto offlineGraph = compile(document, offlineSettings);
    const auto preparedGraph = compile(document, preparedSettings);
    const auto offline = talas::runtime::renderOffline(offlineGraph, 6);
    talas::runtime::RealtimeRenderSession prepared{preparedGraph};
    require(offline.ok(),
        "C153 direct scheduled Triggered Sample And Hold should render offline");
    require(prepared.ready(),
        "C153 direct scheduled Triggered Sample And Hold should prepare realtime: "
            + std::string{prepared.error()});
    require(
        prepared.scheduleEventValue(
            "SampleTrigger", 1.0,
            talas::expr::ValueDomain::Scalar, 1)
            && prepared.scheduleEventValue(
                "SampleTrigger", -0.0,
                talas::expr::ValueDomain::Scalar, 3)
            && prepared.scheduleEventValue(
                "SampleTrigger", 1.0,
                talas::expr::ValueDomain::Scalar, 4),
        "C153 prepared Triggered Sample And Hold should accept exact-edge direct schedules");

    std::array<double, 6> actual{};
    std::size_t allocations = 0;
    require(
        renderAndCount(
            prepared, std::span<double>{actual}.subspan(0, 1),
            allocations)
            && allocations == 0
            && renderAndCount(
                prepared, std::span<double>{actual}.subspan(1, 2),
                allocations)
            && allocations == 0
            && renderAndCount(
                prepared, std::span<double>{actual}.subspan(3, 3),
                allocations)
            && allocations == 0,
        "C153 prepared scheduled edges should render irregular callbacks without allocation");
    require(
        std::ranges::equal(actual, offline.mono),
        "C153 direct scheduled edges should be bit-identical offline and prepared at exact frames");
}

void testRealtimeTriggeredSampleAndHoldRequiresExactCompilerOwnedAuthority()
{
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.eventValues = {{
        "SampleTrigger", 1.0, talas::expr::ValueDomain::Scalar}};
    const auto document = makeDirectEventValueTriggeredSampleAndHoldVcaDocument();
    const auto exact = compile(document, settings);
    talas::runtime::RealtimeRenderSession exactSession{exact};
    const auto exactOffline = talas::runtime::renderOffline(exact, 4);
    require(exactSession.ready() && exactOffline.ok(),
        "C153 exact built-in Triggered Sample And Hold authority should prepare");

    talas::project::ProjectDocument standaloneDocument;
    standaloneDocument.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("carrier", "talas.oscillator", {
            {"frequency", "440 hz"}, {"amplitude", "0.25"}}),
        node("source", "talas.linearRamp", {
            {"duration", "1 s"}, {"start", "220"}, {"end", "440"}}),
        node("hold", "talas.triggeredSampleAndHold", {
            {"trigger", "!C153Trigger"}}),
    };
    standaloneDocument.graph.connections = {
        connection("source", "value", "hold", "value"),
        connection("hold", "value", "carrier", "frequency"),
        connection("carrier", "audioOut", "out", "audioIn"),
    };
    auto standaloneSettings = talas::runtime::RenderSettings{8.0, 4};
    standaloneSettings.eventValues = {{
        "C153Trigger", 1.0, talas::expr::ValueDomain::Scalar}};
    const auto standalone = compile(standaloneDocument, standaloneSettings);
    const auto standaloneOffline = talas::runtime::renderOffline(standalone, 4);
    talas::runtime::RealtimeRenderSession standaloneSession{standalone};
    require(standaloneOffline.ok() && standaloneSession.ready(),
        "C153 Triggered Sample And Hold should seal a complete standalone sampling plan: "
            + std::string{standaloneSession.error()}
            + (standaloneOffline.diagnostics.empty()
                    ? std::string{}
                    : " / " + standaloneOffline.diagnostics.front().message));

    auto subsetRegistry = talas::core::makeBuiltinNodeRegistry();
    subsetRegistry.setNodeTypeOfflineSupport(
        "talas.triggeredSampleAndHold",
        talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    subsetRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.triggeredSampleAndHold",
        talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto subset = talas::runtime::compileProject(
        document, subsetRegistry, settings);
    require(subset.ok(),
        "C153 explicit custom Subset Triggered Sample And Hold should compile");
    talas::runtime::RealtimeRenderSession subsetSession{*subset.graph};
    const auto subsetOffline = talas::runtime::renderOffline(*subset.graph, 4);
    require(subsetSession.ready() && subsetOffline.ok(),
        "C153 explicit custom Subset should retain C70 compatibility");

    auto statefulDocument = document;
    auto statefulHold = std::ranges::find(
        statefulDocument.graph.nodes,
        std::string_view{"hold"},
        &talas::project::ProjectNode::instanceId);
    require(statefulHold != statefulDocument.graph.nodes.end(),
        "C153 stateful direct fixture should expose Triggered Sample And Hold");
    statefulHold->parameters = {{"trigger", "previous(0, 0)"}};
    const auto stateful = talas::runtime::compileProject(
        statefulDocument, talas::core::makeBuiltinNodeRegistry(), settings);
    require(stateful.ok(),
        "C153 stateful direct Triggered Sample And Hold fixture should compile before runtime rejection");
    talas::runtime::RealtimeRenderSession statefulSession{*stateful.graph};
    const auto statefulOffline = talas::runtime::renderOffline(*stateful.graph, 4);
    require(!statefulSession.ready() && !statefulOffline.ok()
            && statefulOffline.mono.empty(),
        "C153 promoted Triggered Sample And Hold should reject stateful direct scalar authority offline and prepared");

    auto connectedStatefulDocument = statefulDocument;
    connectedStatefulDocument.graph.nodes.push_back(node(
        "trigger", "talas.constant", {{"value", "1"}}));
    connectedStatefulDocument.graph.connections.push_back(connection(
        "trigger", "value", "hold", "trigger"));
    const auto connectedStateful = talas::runtime::compileProject(
        connectedStatefulDocument,
        talas::core::makeBuiltinNodeRegistry(), settings);
    require(connectedStateful.ok(),
        "C153 connected stateful fallback fixture should compile before promoted-authority rejection");
    talas::runtime::RealtimeRenderSession connectedStatefulSession{
        *connectedStateful.graph};
    const auto connectedStatefulOffline = talas::runtime::renderOffline(
        *connectedStateful.graph, 4);
    require(!connectedStatefulSession.ready()
            && !connectedStatefulOffline.ok()
            && connectedStatefulOffline.mono.empty(),
        "C153 connected trigger precedence should not mint unrestricted stateful fallback authority offline or prepared");

    auto divergentRegistry = talas::core::makeBuiltinNodeRegistry();
    divergentRegistry.setNodeTypeFanInLatencyPolicy(
        "talas.triggeredSampleAndHold",
        talas::core::FanInLatencyPolicy::PreserveRelative);
    const auto divergent = talas::runtime::compileProject(
        document, divergentRegistry, settings);
    require(divergent.ok(),
        "C153 coherent divergent Triggered Sample And Hold fixture should compile");
    talas::runtime::RealtimeRenderSession divergentSession{*divergent.graph};
    const auto divergentOffline = talas::runtime::renderOffline(*divergent.graph, 4);
    require(!divergentSession.ready() && !divergentOffline.ok()
            && divergentOffline.mono.empty(),
        "C153 coherent divergent Supported descriptor should not mint built-in Triggered Sample And Hold authority");

    auto forgedPlan = exact;
    auto forgedHold = std::ranges::find(
        mutablePlanForTest(forgedPlan).steps,
        std::string_view{"talas.triggeredSampleAndHold"},
        &talas::runtime::CompileStep::typeId);
    require(forgedHold != mutablePlanForTest(forgedPlan).steps.end(),
        "C153 forged plan fixture should expose Triggered Sample And Hold");
    forgedHold->supportsReset = false;
    talas::runtime::RealtimeRenderSession forgedPlanSession{forgedPlan};
    const auto forgedPlanOffline = talas::runtime::renderOffline(forgedPlan, 4);
    require(!forgedPlanSession.ready() && !forgedPlanOffline.ok()
            && forgedPlanOffline.mono.empty(),
        "C153 compiler-owned Triggered Sample And Hold should reject sealed plan mutation offline and prepared");

    auto forgedSettings = exact;
    ++mutableSettingsForTest(forgedSettings).maxBlockFrames;
    talas::runtime::RealtimeRenderSession forgedSettingsSession{forgedSettings};
    const auto forgedSettingsOffline = talas::runtime::renderOffline(
        forgedSettings, 4);
    require(!forgedSettingsSession.ready()
            && !forgedSettingsOffline.ok()
            && forgedSettingsOffline.mono.empty(),
        "C153 compiler-owned Triggered Sample And Hold should reject sealed settings mutation offline and prepared");
}

