    require(allocations == 0, "first edge-triggered Sample And Hold block should not allocate");
    require(renderAndCount(session, second, allocations), "second edge-triggered Sample And Hold block should render");
    require(allocations == 0, "second edge-triggered Sample And Hold block should not allocate");
    require(renderAndCount(session, third, allocations), "third edge-triggered Sample And Hold block should render");
    require(allocations == 0, "third edge-triggered Sample And Hold block should not allocate");
    requireNear(first[0], 0.0, 1.0e-12, "edge-triggered Sample And Hold before first edge");
