void testRealtimePromotedTriggeredSampleAndHoldConnectedTriggerHidesInvalidFallback()
{
    for (const auto& invalidFallback : {
            std::string{"440 hz"},
            std::string{"!C153MissingTrigger"}})
    {
        auto invalidDocument = makeTriggeredSampleAndHoldVcaDocument(
            invalidFallback);
        invalidDocument.graph.nodes.push_back(node(
            "trigger", "talas.constant", {{"value", "1"}}));
        invalidDocument.graph.connections.push_back(connection(
            "trigger", "value", "hold", "trigger"));
        const auto invalid = talas::runtime::compileProject(
            invalidDocument,
            talas::core::makeBuiltinNodeRegistry(),
            talas::runtime::RenderSettings{4.0, 2});
        require(!invalid.ok(),
            "C153 connected trigger precedence should not hide wrong-domain or unresolved fallback authority");
    }

    auto document = makeTriggeredSampleAndHoldVcaDocument(
        "1e200 * 1e200");
    document.graph.nodes.push_back(node(
        "trigger", "talas.constant", {{"value", "1"}}));
    document.graph.connections.push_back(connection(
        "trigger", "value", "hold", "trigger"));
    const auto graph = compile(
        document, talas::runtime::RenderSettings{4.0, 2});
    const auto offline = talas::runtime::renderOffline(graph, 2);
    talas::runtime::RealtimeRenderSession prepared{graph};
    require(offline.ok(),
        "C153 connected Triggered Sample And Hold should hide its invalid direct fallback offline");
    require(prepared.ready(),
        "C153 connected Triggered Sample And Hold should hide its invalid direct fallback during prepared admission: "
            + std::string{prepared.error()});
    std::array<double, 2> actual{};
    std::size_t allocations = 0;
    require(renderAndCount(prepared, actual, allocations)
            && allocations == 0
            && std::ranges::equal(actual, offline.mono),
        "C153 connected trigger precedence should remain bit-identical offline and prepared without allocation");
}

void testRealtimeSessionRejectsNonFiniteDirectTriggeredSampleAndHoldWithoutChangingState()
{
    talas::runtime::RenderSettings settings{4.0, 2};
    settings.eventValues.push_back({"SampleTrigger", 1.0, talas::expr::ValueDomain::Scalar});
    auto candidateGraph = compile(makeDirectEventValueTriggeredSampleAndHoldVcaDocument(), settings);
    auto referenceGraph = compile(makeDirectEventValueTriggeredSampleAndHoldVcaDocument(), std::move(settings));
    talas::runtime::RealtimeRenderSession candidate(candidateGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(candidate.ready(), std::string(candidate.error()));
    require(reference.ready(), std::string(reference.error()));

    std::array<double, 2> ignored{};
    std::array<double, 2> candidateAfter{};
    std::array<double, 2> referenceAfter{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, ignored, allocations), "direct trigger rejection candidate setup should render");
    require(renderAndCount(reference, ignored, allocations), "direct trigger rejection reference setup should render");
    require(!candidate.updateEventValue("SampleTrigger", std::numeric_limits<double>::infinity(), talas::expr::ValueDomain::Scalar),
            "non-finite direct Triggered Sample And Hold trigger should reject");
    require(renderAndCount(candidate, candidateAfter, allocations), "rejected direct trigger candidate should render");
    require(allocations == 0, "rejected direct trigger candidate should not allocate");
    require(renderAndCount(reference, referenceAfter, allocations), "unchanged direct trigger reference should render");
    for (std::size_t frame = 0; frame < candidateAfter.size(); ++frame)
        requireNear(candidateAfter[frame], referenceAfter[frame], 1.0e-12,
                    "rejected direct trigger should preserve held value and edge state");
}

