void testRealtimeSessionUpdatesDirectArParametersBeforeRenderingWithoutAllocations()
{
    talas::runtime::RenderSettings settings{4.0, 2};
    settings.eventValues = {
        {"Attack", 0.5, talas::expr::ValueDomain::Seconds},
        {"Release", 0.5, talas::expr::ValueDomain::Seconds},
        {"Scale", 1.0, talas::expr::ValueDomain::Scalar},
        {"KeyDown", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto directGraph = compile(makeDirectEventValueArVcaDocument(), std::move(settings));
    auto staticGraph = compile(makeArVcaDocument({
        {"attackTime", "1 s"},
        {"releaseTime", "1 s"},
        choiceParameter("type", "linear"),
        {"scale", "0.5"},
        {"gate", "1"},
    }), talas::runtime::RenderSettings{4.0, 2});
    talas::runtime::RealtimeRenderSession direct(directGraph);
    talas::runtime::RealtimeRenderSession reference(staticGraph);
    require(direct.ready(), std::string(direct.error()));
    require(reference.ready(), std::string(reference.error()));
    require(direct.updateEventValue("Attack", 1.0, talas::expr::ValueDomain::Seconds), "direct AR attack should update");
    require(direct.updateEventValue("Release", 1.0, talas::expr::ValueDomain::Seconds), "direct AR release should update");
    require(direct.updateEventValue("Scale", 0.5, talas::expr::ValueDomain::Scalar), "direct AR scale should update");

    std::array<double, 2> actual{};
    std::array<double, 2> expected{};
    std::size_t allocations = 0;
    require(renderAndCount(direct, actual, allocations), "updated direct AR should render");
    require(allocations == 0, "updated direct AR should not allocate");
    require(renderAndCount(reference, expected, allocations), "static AR reference should render");
    require(allocations == 0, "static AR reference should not allocate");
    for (std::size_t frame = 0; frame < actual.size(); ++frame)
        requireNear(actual[frame], expected[frame], 1.0e-12, "direct AR parameters should match static updated values");
}

void testRealtimeSessionDirectArGateReleasesAndRetriggersWithoutAllocations()
{
    talas::runtime::RenderSettings settings{4.0, 2};
    settings.eventValues = {
        {"Attack", 0.5, talas::expr::ValueDomain::Seconds},
        {"Release", 1.0, talas::expr::ValueDomain::Seconds},
        {"Scale", 1.0, talas::expr::ValueDomain::Scalar},
        {"KeyDown", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto graph = compile(makeDirectEventValueArVcaDocument(), std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 2> attack{};
    std::array<double, 2> release{};
    std::array<double, 2> retrigger{};
    std::size_t allocations = 0;
    require(renderAndCount(session, attack, allocations), "direct AR attack should render");
    require(allocations == 0, "direct AR attack should not allocate");
    require(session.updateEventValue("KeyDown", 0.0, talas::expr::ValueDomain::Scalar), "direct AR gate should close");
    require(renderAndCount(session, release, allocations), "direct AR release should render");
    require(allocations == 0, "direct AR release should not allocate");
    require(session.updateEventValue("KeyDown", 1.0, talas::expr::ValueDomain::Scalar), "direct AR gate should reopen");
    require(renderAndCount(session, retrigger, allocations), "direct AR retrigger should render");
    require(allocations == 0, "direct AR retrigger should not allocate");
    requireNear(attack[1], 0.5, 1.0e-12, "direct AR should attack before gate close");
    requireNear(release[1], -0.375, 1.0e-12, "direct AR falling gate should release instead of resetting");
    requireNear(retrigger[1], 0.875, 1.0e-12, "direct AR rising gate should retrigger from the release value");
}

void testRealtimeSessionUpdatesDirectArTimingWhileActiveWithoutAllocations()
{
    talas::runtime::RenderSettings settings{4.0, 2};
    settings.eventValues = {
        {"Attack", 1.0, talas::expr::ValueDomain::Seconds},
        {"Release", 1.0, talas::expr::ValueDomain::Seconds},
        {"Scale", 1.0, talas::expr::ValueDomain::Scalar},
        {"KeyDown", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto graph = compile(makeDirectEventValueArVcaDocument(), std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 2> firstAttack{};
    std::array<double, 2> updatedAttack{};
    std::array<double, 2> release{};
    std::array<double, 2> shortenedRelease{};
    std::size_t allocations = 0;
    require(renderAndCount(session, firstAttack, allocations), "initial direct AR attack should render");
    require(allocations == 0, "initial direct AR attack should not allocate");
    require(session.updateEventValue("Attack", 0.5, talas::expr::ValueDomain::Seconds), "active AR attack time should update");
    require(session.updateEventValue("Scale", 0.5, talas::expr::ValueDomain::Scalar), "active AR scale should update");
    require(renderAndCount(session, updatedAttack, allocations), "updated active AR attack should render");
    require(allocations == 0, "updated active AR attack should not allocate");
    requireNear(firstAttack[1], 0.25, 1.0e-12, "initial AR attack should use the initial time and scale");
    requireNear(updatedAttack[1], -0.5, 1.0e-12, "active AR attack should use the new time and scale at the next block");

    require(session.updateEventValue("KeyDown", 0.0, talas::expr::ValueDomain::Scalar), "active AR gate should close");
    require(renderAndCount(session, release, allocations), "active AR release should render");
    require(allocations == 0, "active AR release should not allocate");
    requireNear(release[1], 0.375, 1.0e-12, "AR should begin release with the original release time");
    require(session.updateEventValue("Release", 0.5, talas::expr::ValueDomain::Seconds), "active AR release time should update");
    require(renderAndCount(session, shortenedRelease, allocations), "shortened active AR release should render");
    require(allocations == 0, "shortened active AR release should not allocate");
    requireNear(shortenedRelease[1], 0.0, 1.0e-12, "active AR release should use the new time at the next block");
}

