void testRealtimeOscillatorAuthorityRejectsInvalidConnectedArFallback()
{
    auto candidateGraph = compile(makeConnectedGateArVcaDocument());
    auto referenceGraph = compile(makeConnectedGateArVcaDocument());
    auto& plan = const_cast<talas::runtime::RuntimePlan&>(candidateGraph.plan());
    const auto ar = std::ranges::find(
        plan.steps, std::string_view{"talas.ar"},
        &talas::runtime::CompileStep::typeId);
    require(ar != plan.steps.end(), "C91 fixture should expose AR");
    const auto gate = std::ranges::find(
        ar->parameters, std::string_view{"gate"},
        &talas::runtime::ParameterValue::id);
    require(gate != ar->parameters.end(),
        "C91 fixture should expose inert gate");
    gate->value = std::numeric_limits<double>::infinity();
    talas::runtime::RealtimeRenderSession candidate(candidateGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(!candidate.ready() && reference.ready(),
        "C160 Oscillator authority should reject an invalid connected AR "
        "fallback without rejecting its compiler-owned reference: "
            + std::string{candidate.error()}
            + " / " + std::string{reference.error()});
}

void testArRequiresExactCompilerOwnedAuthority()
{
    const auto makeAuthorityDocument = [](bool connectedGate = false) {
        talas::project::ProjectDocument document;
        document.graph.nodes = {
            node("out", "talas.audioOutput"),
            node("carrier", "talas.oscillator", {
                {"frequency", "0.25 hz"}, {"amplitude", "0.25"}}),
            node("env", "talas.ar", {
                {"attackTime", "1 s"},
                {"releaseTime", "1 s"},
                choiceParameter("type", "linear"),
                {"scale", "1"},
                {"gate", "1"},
            }),
        };
        document.graph.connections = {
            connection("env", "value", "carrier", "frequency"),
            connection("carrier", "audioOut", "out", "audioIn"),
        };
        if (connectedGate)
        {
            document.graph.nodes.push_back(
                node("gate", "talas.constant", {{"value", "1"}}));
            document.graph.connections.push_back(
                connection("gate", "value", "env", "gate"));
        }
        return document;
    };
    const auto settings = talas::runtime::RenderSettings{4.0, 4};
    const auto compiled = compile(makeAuthorityDocument(), settings);
    const auto findAr = [](auto& graph) {
        auto& plan = mutablePlanForTest(graph);
        return std::ranges::find(
            plan.steps, std::string_view{"talas.ar"},
            &talas::runtime::CompileStep::typeId);
    };
    const auto ar = std::ranges::find(
        compiled.plan().steps, std::string_view{"talas.ar"},
        &talas::runtime::CompileStep::typeId);
    require(ar != compiled.plan().steps.end()
            && ar->offlineSupport
                == talas::core::ExecutionSupport::Supported
            && ar->offlineBinding
                == talas::core::ExecutionBinding::LegacyAdapter
            && ar->preparedRealtimeSupport
                == talas::core::ExecutionSupport::Supported
            && ar->preparedRealtimeBinding
                == talas::core::ExecutionBinding::LegacyAdapter
            && !ar->kernelKind.has_value()
            && ar->supportsReset
            && !ar->preparedIsolatedComponent
            && ar->eventValueScopeId == ar->scopeId
            && ar->resolvedLatencyFrames == 0
            && ar->cumulativeOutputLatencyFrames == 0
            && ar->parameters.size() == 6
            && ar->inputs.empty(),
        "C163 exact fixture should expose promoted resettable AR authority");
    talas::runtime::RealtimeRenderSession exact{compiled};
    const auto exactOffline = talas::runtime::renderOffline(compiled, 4);
    require(exact.ready() && exactOffline.ok(),
        "C163 exact built-in AR should render in both engines: "
            + std::string{exact.error()});

    const auto publicGraph =
        makePublicCompatibilityGraphWithSubsetOscillators(compiled);
    talas::runtime::RealtimeRenderSession publicRealtime{publicGraph};
    const auto publicOffline = talas::runtime::renderOffline(publicGraph, 4);
    require(!publicRealtime.ready()
            && std::string{publicRealtime.error()}.find("AR")
                != std::string::npos
            && !publicOffline.ok()
            && std::ranges::any_of(
                publicOffline.diagnostics,
                [](const auto& diagnostic) {
                    return diagnostic.message.find("AR")
                        != std::string::npos;
                }),
        "C163 Supported AR should require private compiler authority in both engines");

    const auto requireRejected = [](auto forged,
                                    std::string_view context) {
        talas::runtime::RealtimeRenderSession realtime{forged};
        const auto offline = talas::runtime::renderOffline(forged, 4);
        require(!realtime.ready() && !offline.ok(),
            "C163 AR authority should reject "
                + std::string{context});
    };
    auto forgedParameter = compiled;
    auto parameterStep = findAr(forgedParameter);
    parameterStep->parameters[0].value = std::nextafter(
        parameterStep->parameters[0].value,
        std::numeric_limits<double>::infinity());
    requireRejected(std::move(forgedParameter),
        "attack-time bit mutation");

    auto forgedScope = compiled;
    ++findAr(forgedScope)->scopeId;
    requireRejected(std::move(forgedScope), "scope mutation");

    auto forgedOutput = compiled;
    auto& outputPlan = mutablePlanForTest(forgedOutput);
    const auto output = std::ranges::find_if(
        outputPlan.buffers,
        [](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == "env"
                && buffer.portId == "value";
        });
    require(output != outputPlan.buffers.end(),
        "C163 fixture should expose the AR output buffer");
    ++output->frames;
    requireRejected(std::move(forgedOutput),
        "output-buffer mutation");

    const auto connected = compile(
        makeAuthorityDocument(true), settings);
    auto forgedInput = connected;
    auto inputStep = findAr(forgedInput);
    require(inputStep != mutablePlanForTest(forgedInput).steps.end()
            && inputStep->inputs.size() == 1,
        "C163 fixture should expose one optional gate binding");
    ++inputStep->inputs.front().sourceScopeId;
    requireRejected(std::move(forgedInput),
        "gate-binding mutation");

    auto forgedSettings = compiled;
    mutableSettingsForTest(forgedSettings).tempoBpm =
        std::nextafter(
            forgedSettings.renderSettings().tempoBpm,
            std::numeric_limits<double>::infinity());
    requireRejected(std::move(forgedSettings),
        "settings-bit mutation");

    auto downgraded = compiled;
    findAr(downgraded)->preparedRealtimeSupport =
        talas::core::ExecutionSupport::Subset;
    requireRejected(std::move(downgraded),
        "sealed support downgrade");

    auto subsetRegistry = talas::core::makeBuiltinNodeRegistry();
    subsetRegistry.setNodeTypeOfflineSupport(
        "talas.ar", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    subsetRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.ar", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto subset = talas::runtime::compileProject(
        makeAuthorityDocument(), subsetRegistry, settings);
    require(subset.ok(),
        "C163 explicit custom both-Subset AR should compile");
    talas::runtime::RealtimeRenderSession subsetRealtime{*subset.graph};
    const auto subsetOffline = talas::runtime::renderOffline(
        *subset.graph, 4);
    const auto publicSubset =
        makePublicCompatibilityGraphWithSubsetOscillators(*subset.graph);
    talas::runtime::RealtimeRenderSession publicSubsetRealtime{
        publicSubset};
    const auto publicSubsetOffline = talas::runtime::renderOffline(
        publicSubset, 4);
    require(subsetRealtime.ready() && subsetOffline.ok()
            && publicSubsetRealtime.ready()
            && publicSubsetOffline.ok(),
        "C163 compiler-produced and public both-Subset AR should retain bounded compatibility: "
            + std::string{subsetRealtime.error()}
            + " / " + std::string{publicSubsetRealtime.error()});

    auto mixedRegistry = talas::core::makeBuiltinNodeRegistry();
    mixedRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.ar", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto mixed = talas::runtime::compileProject(
        makeAuthorityDocument(), mixedRegistry, settings);
    require(mixed.ok(),
        "C163 mixed AR fixture should compile before admission rejection");
    requireRejected(*mixed.graph, "mixed renderer support");

    auto divergentRegistry = talas::core::makeBuiltinNodeRegistry();
    divergentRegistry.setNodeTypeFanInLatencyPolicy(
        "talas.ar", talas::core::FanInLatencyPolicy::PreserveRelative);
    const auto divergent = talas::runtime::compileProject(
        makeAuthorityDocument(), divergentRegistry, settings);
    require(divergent.ok(),
        "C163 divergent AR descriptor should compile before admission rejection");
    requireRejected(*divergent.graph,
        "coherent divergent Supported descriptor");
}

void testArConnectedFallbacksHideOnlyExactNonFinite()
{
    const auto makeConnected = [](std::string gateExpression) {
        auto document = makeArVcaDocument({
            {"attackTime", "1 s"},
            {"releaseTime", "1 s"},
            choiceParameter("type", "linear"),
            {"scale", "1"},
            {"gate", std::move(gateExpression)},
        });
        document.graph.nodes.push_back(
            node("gate", "talas.constant", {{"value", "1"}}));
        document.graph.connections.push_back(
            connection("gate", "value", "env", "gate"));
        return document;
    };
    const auto accepted = talas::runtime::compileProject(
        makeConnected("1e200 * 1e200"),
        talas::core::makeBuiltinNodeRegistry(),
        talas::runtime::RenderSettings{4.0, 4});
    require(accepted.ok(),
        "C163 connected precedence should hide one exact non-finite AR gate fallback");
    talas::runtime::RealtimeRenderSession acceptedRealtime{
        *accepted.graph};
    const auto acceptedOffline = talas::runtime::renderOffline(
        *accepted.graph, 4);
    require(acceptedRealtime.ready() && acceptedOffline.ok(),
        "C163 exact connected non-finite AR fallback should render in both engines: "
            + std::string{acceptedRealtime.error()});

    const auto rejected = talas::runtime::compileProject(
        makeConnected("!C163MissingGate"),
        talas::core::makeBuiltinNodeRegistry(),
        talas::runtime::RenderSettings{4.0, 4});
    require(!rejected.ok(),
        "C163 connected precedence must not hide unresolved AR fallback authority");
}

void testArScheduledControlsMatchOfflineAcrossPartitions()
{
    auto document = makeDirectEventValueArVcaDocument();
    auto carrier = std::ranges::find(
        document.graph.nodes,
        std::string_view{"carrier"},
        &talas::project::ProjectNode::instanceId);
    require(carrier != document.graph.nodes.end(),
        "C163 schedule fixture should expose its carrier");
    carrier->parameters[1].expression = "0.5";

    auto settings = talas::runtime::RenderSettings{8.0, 8};
    settings.eventValues = {
        {"Attack", 0.5, talas::expr::ValueDomain::Seconds},
        {"Release", 0.5, talas::expr::ValueDomain::Seconds},
        {"Scale", 1.0, talas::expr::ValueDomain::Scalar},
        {"KeyDown", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "Attack", 0.25, talas::expr::ValueDomain::Seconds},
        {2, "Scale", -0.5, talas::expr::ValueDomain::Scalar},
        {3, "KeyDown", 0.0, talas::expr::ValueDomain::Scalar},
        {4, "Release", 0.25, talas::expr::ValueDomain::Seconds},
        {5, "Attack", 0.5, talas::expr::ValueDomain::Seconds},
        {5, "Scale", 0.75, talas::expr::ValueDomain::Scalar},
        {5, "KeyDown", 1.0, talas::expr::ValueDomain::Scalar},
        {7, "Release", 0.25, talas::expr::ValueDomain::Seconds},
        {7, "KeyDown", 0.0, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(document, settings);
    const auto offline = talas::runtime::renderOffline(graph, 8);
    require(offline.ok() && offline.mono.size() == 8,
        "C163 scheduled AR fixture should render offline");

    const auto renderPartitions = [&](std::span<const std::size_t> partitions) {
        talas::runtime::RealtimeRenderSession session{graph};
        require(session.ready(),
            "C163 scheduled AR should prepare: "
                + std::string{session.error()});
        std::array<double, 8> output{};
        std::size_t renderedFrames = 0;
        std::size_t allocations = 0;
        require(renderAndCount(
                    session,
                    std::span<double>{output}.first(0),
                    allocations)
                && allocations == 0,
            "C163 zero-frame AR callback should be an allocation-free no-op");
        for (const auto partition : partitions)
        {
            require(renderedFrames + partition <= output.size()
                    && renderAndCount(
                        session,
                        std::span<double>{output}.subspan(
                            renderedFrames, partition),
                        allocations)
                    && allocations == 0,
                "C163 scheduled AR partition should render without allocation");
            renderedFrames += partition;
        }
        require(renderedFrames == output.size(),
            "C163 scheduled AR partitions should cover all frames");
        session.resetTransport();
        std::array<double, 8> reset{};
        require(renderAndCount(session, reset, allocations)
                && allocations == 0
                && reset == output,
            "C163 transport reset should replay scheduled AR exactly");
        return output;
    };
    constexpr std::array<std::size_t, 3> irregular{3, 2, 3};
    constexpr std::array<std::size_t, 8> singleFrames{
        1, 1, 1, 1, 1, 1, 1, 1};
    const auto irregularOutput = renderPartitions(irregular);
    const auto singleFrameOutput = renderPartitions(singleFrames);
    require(irregularOutput == singleFrameOutput
            && std::ranges::equal(
                irregularOutput, offline.mono),
        "C163 four scheduled AR controls should be bit-identical offline and across prepared partitions");
}

void testRealtimeSessionRejectsInvalidDirectArTimeTransaction()
{
    talas::runtime::RenderSettings settings{4.0, 2};
    settings.eventValues = {
        {"Attack", 0.5, talas::expr::ValueDomain::Seconds},
        {"Release", 1.0, talas::expr::ValueDomain::Seconds},
        {"Scale", 1.0, talas::expr::ValueDomain::Scalar},
        {"KeyDown", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto candidateGraph = compile(makeDirectEventValueArVcaDocument(), settings);
    auto referenceGraph = compile(makeDirectEventValueArVcaDocument(), std::move(settings));
    talas::runtime::RealtimeRenderSession candidate(candidateGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(candidate.ready(), std::string(candidate.error()));
    require(reference.ready(), std::string(reference.error()));

    std::array<double, 2> candidateFirst{};
    std::array<double, 2> referenceFirst{};
    std::array<double, 2> candidateSecond{};
    std::array<double, 2> referenceSecond{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, candidateFirst, allocations), "AR rejection candidate first block should render");
    require(renderAndCount(reference, referenceFirst, allocations), "AR rejection reference first block should render");
    require(!candidate.updateEventValue("Attack", std::numeric_limits<double>::quiet_NaN(), talas::expr::ValueDomain::Seconds), "non-numeric direct AR attack should reject");
    require(!candidate.updateEventValue("Attack", std::numeric_limits<double>::quiet_NaN(), talas::expr::ValueDomain::Seconds), "non-numeric direct AR attack should reject");
    require(!candidate.updateEventValue("Release", std::numeric_limits<double>::quiet_NaN(), talas::expr::ValueDomain::Seconds), "non-numeric direct AR release should reject");
    require(!candidate.updateEventValue("Release", std::numeric_limits<double>::quiet_NaN(), talas::expr::ValueDomain::Seconds), "non-numeric direct AR release should reject");
    require(renderAndCount(candidate, candidateSecond, allocations), "AR rejection candidate should remain renderable");
    require(allocations == 0, "AR rejection candidate should not allocate");
    require(renderAndCount(reference, referenceSecond, allocations), "AR rejection reference should render");
    require(allocations == 0, "AR rejection reference should not allocate");
    for (std::size_t frame = 0; frame < candidateSecond.size(); ++frame)
        requireNear(candidateSecond[frame], referenceSecond[frame], 1.0e-12, "rejected AR update should preserve prior state and generation");
}

void testRealtimeArTransportResetReplaysInitialStateWithoutAllocations()
{
    auto graph = compile(makeArVcaDocument());
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    std::array<double, 2> initial{};
    std::array<double, 2> advanced{};
    std::array<double, 2> reset{};
    std::size_t allocations = 0;
    require(renderAndCount(session, initial, allocations),
        "C91 initial AR block should render");
    require(renderAndCount(session, advanced, allocations),
        "C91 advanced AR block should render");
    std::size_t resetAllocations = 0;
    {
        AllocationCounter counter;
        session.resetTransport();
        resetAllocations = counter.count();
    }
    require(resetAllocations == 0, "C91 AR reset should not allocate");
    require(renderAndCount(session, reset, allocations) && allocations == 0,
        "C91 reset AR block should render without allocation");
    require(initial == reset,
        "C91 AR reset should replay exact positive-zero attack state");
}

void testRealtimeArLaterFailureRollsBackStateAndOutputBeforeRetry()
{
    const auto makeDocument = [] {
        auto document = makeArVcaDocument({
            {"attackTime", "0.5 s"}, {"releaseTime", "1 s"},
            choiceParameter("type", "linear"), {"scale", "2"},
            {"gate", "1"},
        });
        document.graph.nodes.push_back(node(
            "multiplier", "talas.constant", {{"value", "!C91Multiplier"}}));
        document.graph.nodes.push_back(node("downstream", "talas.product"));
        std::erase_if(document.graph.connections, [](const auto& edge) {
            return edge.fromNode == "env" && edge.toNode == "vca";
        });
        document.graph.connections.push_back(connection(
            "env", "value", "downstream", "left"));
        document.graph.connections.push_back(connection(
            "multiplier", "value", "downstream", "right"));
        document.graph.connections.push_back(connection(
            "downstream", "value", "vca", "gain"));
        return document;
    };
    auto candidateSettings = talas::runtime::RenderSettings{4.0, 3};
    candidateSettings.eventValues = {
        {"C91Multiplier", 1.0e308, talas::expr::ValueDomain::Scalar},
    };
    auto referenceSettings = candidateSettings;
    referenceSettings.eventValues.front().value = 1.0;
    auto candidateGraph = compile(makeDocument(), candidateSettings);
    auto referenceGraph = compile(makeDocument(), referenceSettings);
    talas::runtime::RealtimeRenderSession candidate(candidateGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    std::array<double, 3> rejected;
    rejected.fill(73.0);
    std::array<double, 3> retry{};
    std::array<double, 3> expected{};
    std::size_t allocations = 0;
    require(!renderAndCount(candidate, rejected, allocations)
            && allocations == 0 && rejected == std::array<double, 3>{},
        "C91 later failure should reject without output publication");
    require(candidate.updateEventValue(
                "C91Multiplier", 1.0, talas::expr::ValueDomain::Scalar)
            && renderAndCount(candidate, retry, allocations)
            && renderAndCount(reference, expected, allocations)
            && allocations == 0 && retry == expected,
        "C91 later failure should restore AR before exact retry");
}

