void testRealtimePulseTrainRejectsForgedPreparedAuthority()
{
    const auto compiled = compile(
        makePulseTrainVcaDocument(),
        talas::runtime::RenderSettings{4.0, 4});
    const auto requireRejected = [&](auto mutate, std::string_view context) {
        auto plan = compiled.plan();
        const auto pulse = std::ranges::find(
            plan.steps, std::string_view{"talas.pulseTrain"},
            &talas::runtime::CompileStep::typeId);
        require(pulse != plan.steps.end(),
            "C93 forged-authority fixture should expose Pulse Train");
        mutate(*pulse);
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), compiled.renderSettings()});
        require(!session.ready(),
            std::string{context}
                + " should reject forged C93 Pulse Train authority");
    };
    requireRejected(
        [](auto& pulse) { pulse.supportsReset = false; },
        "forged reset capability");
    requireRejected(
        [](auto& pulse) {
            pulse.preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
            pulse.kernelKind = talas::runtime::KernelKind::Gate;
        },
        "forged kernel binding");
    requireRejected(
        [](auto& pulse) { pulse.resolvedLatencyFrames = 1; },
        "forged intrinsic latency");
}

void testRealtimePulseTrainTransportResetReplaysInitialPhaseWithoutAllocations()
{
    auto graph = compile(
        makePulseTrainVcaDocument(), talas::runtime::RenderSettings{4.0, 2});
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 2> initial{};
    std::array<double, 1> advanced{};
    std::array<double, 2> reset{};
    std::size_t allocations = 0;
    require(renderAndCount(session, initial, allocations)
            && renderAndCount(session, advanced, allocations)
            && allocations == 0,
        "C93 Pulse Train setup should advance without allocation");
    std::size_t resetAllocations = 0;
    {
        AllocationCounter counter;
        session.resetTransport();
        resetAllocations = counter.count();
    }
    require(resetAllocations == 0,
        "C93 Pulse Train transport reset should not allocate");
    require(renderAndCount(session, reset, allocations) && allocations == 0,
        "C93 reset Pulse Train should render without allocation");
    require(initial == reset,
        "C93 Pulse Train transport reset should replay its exact initial phase");
}

void testRealtimePulseTrainLaterFailureRollsBackPhaseBeforeRetry()
{
    const auto makeDocument = [] {
        auto document = makePulseTrainVcaDocument();
        document.graph.nodes.push_back(node(
            "z_failureLeft", "talas.constant", {
                {"value", "!C93RealtimeDownstream"},
            }));
        document.graph.nodes.push_back(node(
            "z_failureRight", "talas.constant", {
                {"value", "!C93RealtimeDownstream"},
            }));
        document.graph.nodes.push_back(node("z_failureProduct", "talas.product"));
        document.graph.nodes.push_back(node(
            "z_failureCheck", "talas.scaleAndOffset",
            {{"scale", "1"}, {"offset", "0"}}));
        document.graph.nodes.push_back(node(
            "z_failureCarrier", "talas.oscillator",
            {{"frequency", "0.25 hz"}, {"amplitude", "1"}}));
        document.graph.nodes.push_back(node("z_failure", "talas.vca"));
        document.graph.nodes.push_back(node(
            "zz_mix", "talas.mixer", {{"gain1", "1"}, {"gain2", "1"}}));
        std::erase_if(document.graph.connections, [](const auto& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });
        document.graph.connections.push_back(connection(
            "z_failureLeft", "value", "z_failureProduct", "left"));
        document.graph.connections.push_back(connection(
            "z_failureRight", "value", "z_failureProduct", "right"));
        document.graph.connections.push_back(connection(
            "z_failureProduct", "value", "z_failureCheck", "value"));
        document.graph.connections.push_back(connection(
            "z_failureCarrier", "audioOut", "z_failure", "audioIn"));
        document.graph.connections.push_back(connection(
            "z_failureCheck", "value", "z_failure", "gain"));
        document.graph.connections.push_back(connection(
            "vca", "audioOut", "zz_mix", "in1"));
        document.graph.connections.push_back(connection(
            "z_failure", "audioOut", "zz_mix", "in2"));
        document.graph.connections.push_back(connection(
            "zz_mix", "audioOut", "out", "audioIn"));
        return document;
    };

    auto candidateSettings = talas::runtime::RenderSettings{4.0, 3};
    candidateSettings.eventValues = {
        {"C93RealtimeDownstream", 1.0,
            talas::expr::ValueDomain::Scalar},
    };
    auto referenceSettings = candidateSettings;
    talas::runtime::RealtimeRenderSession candidate(
        compile(makeDocument(), candidateSettings));
    talas::runtime::RealtimeRenderSession reference(
        compile(makeDocument(), referenceSettings));
    require(candidate.ready() && reference.ready(),
        "C93 Pulse Train downstream rollback fixtures should prepare");
    std::array<double, 2> candidateEstablished{};
    std::array<double, 2> referenceEstablished{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, candidateEstablished, allocations)
            && renderAndCount(reference, referenceEstablished, allocations)
            && allocations == 0
            && candidateEstablished == referenceEstablished,
        "C93 rollback fixture should establish non-zero retained phase");
    require(candidate.updateEventValue(
                "C93RealtimeDownstream",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C93 rollback fixture should arm its downstream failure");
    std::array<double, 3> rejected;
    rejected.fill(93.0);
    std::array<double, 3> retry{};
    std::array<double, 3> expected{};
    require(!renderAndCount(candidate, rejected, allocations)
            && allocations == 0 && rejected == std::array<double, 3>{},
        "C93 later failure should publish no callback output");
    require(candidate.updateEventValue(
                "C93RealtimeDownstream", 1.0,
                talas::expr::ValueDomain::Scalar),
        "C93 rollback fixture should accept its corrected downstream value");
    require(renderAndCount(candidate, retry, allocations)
            && renderAndCount(reference, expected, allocations)
            && allocations == 0,
        "C93 corrected retry and reference should render without allocation");
    for (std::size_t frame = 0; frame < retry.size(); ++frame)
    {
        require(retry[frame] == expected[frame],
            "C93 later failure should restore Pulse Train before exact retry frame "
                + std::to_string(frame) + ": actual="
                + std::to_string(retry[frame]) + ", expected="
                + std::to_string(expected[frame]));
    }
}

void testRealtimeRampOwnsExactRampNoiseRollbackBoundary()
{
    const auto makeDocument = [](bool includePulseTrain) {
        auto document = makePulseTriggeredTalasRampVcaDocument("ramp");
        for (auto& graphNode : document.graph.nodes)
        {
            if (graphNode.instanceId == "carrier")
            {
                for (auto& parameter : graphNode.parameters)
                {
                    if (parameter.parameterId == "frequency")
                        parameter.expression = "1 hz";
                    else if (parameter.parameterId == "centerValue")
                        parameter.expression = "10";
                }
            }
            else if (graphNode.instanceId == "ramp")
            {
                for (auto& parameter : graphNode.parameters)
                    if (parameter.parameterId == "duration")
                        parameter.expression = "4 s";
            }
            else if (graphNode.instanceId == "trigger")
            {
                if (includePulseTrain)
                {
                    graphNode.parameters = {
                        {"period", "8 s"},
                        booleanParameter("variableDutyCycle", true),
                        {"dutyCycle", "1"},
                        {"gate", "1"},
                    };
                }
                else
                {
                    graphNode.typeId = "talas.adsr";
                    graphNode.parameters = {
                        {"attackTime", "0.25 s"},
                        {"decayTime", "0.25 s"},
                        {"sustainLevel", "0.5"},
                        {"releaseTime", "0.25 s"},
                        choiceParameter("type", "linear"),
                        {"scale", "1"},
                        {"gate", "1"},
                        {"legato", "0"},
                    };
                }
            }
        }

        document.graph.nodes.push_back(node(
            "z_failure", "talas.level", {
                {"left", "!C93RampNoiseDownstream"},
                {"right", "0"},
                booleanParameter("noGain", false),
            }));
        std::erase_if(document.graph.connections, [](const auto& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });
        document.graph.connections.push_back(connection(
            "vca", "audioOut", "z_failure", "audioIn"));
        document.graph.connections.push_back(connection(
            "z_failure", "leftOut", "out", "audioIn"));
        return document;
    };

    auto withoutPulseSettings = talas::runtime::RenderSettings{4.0, 3};
    withoutPulseSettings.eventValues.push_back({
        "C93RampNoiseDownstream", 1.0,
        talas::expr::ValueDomain::Scalar});
    talas::runtime::RealtimeRenderSession withoutPulse(
        compile(makeDocument(false), std::move(withoutPulseSettings)));
    require(withoutPulse.ready(),
        "C97 Ramp should own its same-scope Noise checkpoint without Pulse Train: "
            + std::string{withoutPulse.error()});

    auto candidateSettings = talas::runtime::RenderSettings{4.0, 3};
    candidateSettings.eventValues.push_back({
        "C93RampNoiseDownstream", 1.0,
        talas::expr::ValueDomain::Scalar});
    auto referenceSettings = candidateSettings;
    talas::runtime::RealtimeRenderSession candidate(
        compile(makeDocument(false), candidateSettings));
    talas::runtime::RealtimeRenderSession reference(
        compile(makeDocument(false), referenceSettings));
    require(candidate.ready() && reference.ready(),
        "C97 Ramp-owned Ramp/Noise rollback fixtures should prepare");

    std::array<double, 3> candidateWarm{};
    std::array<double, 3> referenceWarm{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, candidateWarm, allocations)
            && renderAndCount(reference, referenceWarm, allocations)
            && allocations == 0 && candidateWarm == referenceWarm,
        "C93 Ramp/Noise rollback fixture should establish matching retained state");
    require(candidate.updateEventValue(
                "C93RampNoiseDownstream",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C93 Ramp/Noise rollback fixture should arm its downstream failure");
    std::array<double, 3> rejected;
    rejected.fill(93.0);
    require(!renderAndCount(candidate, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 3>{},
        "C93 Ramp/Noise downstream failure should publish no callback output");
    require(candidate.updateEventValue(
                "C93RampNoiseDownstream", 1.0,
                talas::expr::ValueDomain::Scalar),
        "C93 Ramp/Noise rollback fixture should repair its downstream value");
    std::array<double, 3> retry{};
    std::array<double, 3> expected{};
    require(renderAndCount(candidate, retry, allocations)
            && renderAndCount(reference, expected, allocations)
            && allocations == 0 && retry == expected,
        "C97 Ramp-owned transaction should restore Ramp and Noise state exactly before retry");
}

