    std::array<double, 2> first{};
    std::array<double, 2> updated{};
    std::size_t allocations = 0;
    require(renderAndCount(session, first, allocations), "initial Multislope control block should render");
    require(allocations == 0, "initial Multislope control block should not allocate");
    require(session.updateEventValue("MultiLevel", 0.25, talas::expr::ValueDomain::Scalar),
            "Multislope level Event Value should update");
    require(session.updateEventValue("MultiRate", 0.5, talas::expr::ValueDomain::Scalar),
            "Multislope rate Event Value should update");
    require(renderAndCount(session, updated, allocations), "updated Multislope control block should render");
