void testRealtimeMultislopeRequiresExactCompilerOwnedAuthority()
{
    const auto makeAuthorityDocument = [] {
        talas::project::ProjectDocument document;
        document.graph.nodes = {
            node("out", "talas.audioOutput"),
            node("carrier", "talas.oscillator", {
                {"frequency", "0.25 hz"}, {"amplitude", "0.25"}}),
            node("multi", "talas.multislopeFunctionGenerator", {
                textParameter("timePoints", "{0 s} {1 s} {2 s}"),
                textParameter("slopes", "{-1} {1}"),
                {"level", "1"}, {"gate", "1"}, {"rate", "1"},
            }),
        };
        document.graph.connections = {
            connection("multi", "value", "carrier", "frequency"),
            connection("carrier", "audioOut", "out", "audioIn"),
        };
        return document;
    };
    const auto compiled = compile(
        makeAuthorityDocument(),
        talas::runtime::RenderSettings{4.0, 4});
    talas::runtime::RealtimeRenderSession exact{compiled};
    const auto exactOffline = talas::runtime::renderOffline(compiled, 4);
    require(exact.ready() && exactOffline.ok(),
        "C156 exact built-in Multislope authority should render offline and prepare realtime");
    talas::runtime::RealtimeRenderSession publiclyConstructed(
        talas::runtime::PreparedRuntimeGraph{
            compiled.plan(), compiled.renderSettings()});
    require(!publiclyConstructed.ready()
            && publiclyConstructed.error()
                == "Realtime Multislope Function Generator requires exact compiler-owned descriptor, plan, settings, and resource-free authority",
        "C156 Multislope should require privately compiler-sealed exact execution authority: "
            + std::string{publiclyConstructed.error()});

    const auto requireRejected = [](auto forged,
                                    std::string_view context) {
        talas::runtime::RealtimeRenderSession rejected(forged);
        require(!rejected.ready(),
            "C156 Multislope authority should reject "
                + std::string{context});
    };

    auto forgedText = compiled;
    auto& textPlan = mutablePlanForTest(forgedText);
    const auto textStep = std::ranges::find(
        textPlan.steps,
        std::string_view{"talas.multislopeFunctionGenerator"},
        &talas::runtime::CompileStep::typeId);
    require(textStep != textPlan.steps.end(),
        "C156 authority fixture should expose Multislope");
    const auto timePoints = std::ranges::find(
        textStep->parameters,
        std::string_view{"timePoints"},
        &talas::runtime::ParameterValue::id);
    require(timePoints != textStep->parameters.end()
            && timePoints->text.has_value(),
        "C156 authority fixture should expose timePoints text");
    *timePoints->text += " ";
    requireRejected(std::move(forgedText), "static-envelope text mutation");

    auto forgedBinding = compiled;
    auto& bindingPlan = mutablePlanForTest(forgedBinding);
    const auto carrier = std::ranges::find(
        bindingPlan.steps,
        std::string_view{"talas.oscillator"},
        &talas::runtime::CompileStep::typeId);
    require(carrier != bindingPlan.steps.end()
            && !carrier->inputs.empty(),
        "C156 authority fixture should expose downstream binding");
    ++carrier->inputs.front().sourceScopeId;
    requireRejected(std::move(forgedBinding), "binding mutation");

    auto forgedSettings = compiled;
    mutableSettingsForTest(forgedSettings).tempoBpm =
        std::nextafter(
            forgedSettings.renderSettings().tempoBpm,
            std::numeric_limits<double>::infinity());
    requireRejected(std::move(forgedSettings), "settings-bit mutation");

    auto downgraded = compiled;
    const auto downgradedStep = std::ranges::find(
        mutablePlanForTest(downgraded).steps,
        std::string_view{"talas.multislopeFunctionGenerator"},
        &talas::runtime::CompileStep::typeId);
    require(downgradedStep != mutablePlanForTest(downgraded).steps.end(),
        "C156 downgrade fixture should expose Multislope");
    downgradedStep->offlineSupport =
        talas::core::ExecutionSupport::Subset;
    talas::runtime::RealtimeRenderSession downgradedRealtime{downgraded};
    const auto downgradedOffline = talas::runtime::renderOffline(
        downgraded, 4);
    require(!downgradedRealtime.ready() && !downgradedOffline.ok(),
        "C156 sealed Multislope should reject a support downgrade");

    auto subsetRegistry = talas::core::makeBuiltinNodeRegistry();
    subsetRegistry.setNodeTypeOfflineSupport(
        "talas.multislopeFunctionGenerator",
        talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    subsetRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.multislopeFunctionGenerator",
        talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto subset = talas::runtime::compileProject(
        makeAuthorityDocument(), subsetRegistry,
        talas::runtime::RenderSettings{4.0, 4});
    require(subset.ok(),
        "C156 explicit custom Subset Multislope should compile");
    const auto unsealed =
        makePublicCompatibilityGraphWithSubsetOscillators(
            *subset.graph);
    talas::runtime::RealtimeRenderSession subsetRealtime{unsealed};
    const auto subsetOffline = talas::runtime::renderOffline(unsealed, 4);
    require(subsetRealtime.ready() && subsetOffline.ok(),
        "C156 genuine unsealed both-Subset Multislope should retain C116 compatibility: "
            + std::string{subsetRealtime.error()});

    auto mixedRegistry = talas::core::makeBuiltinNodeRegistry();
    mixedRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.multislopeFunctionGenerator",
        talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto mixed = talas::runtime::compileProject(
        makeAuthorityDocument(), mixedRegistry,
        talas::runtime::RenderSettings{4.0, 4});
    require(mixed.ok(),
        "C156 mixed-support fixture should compile before admission rejection");
    talas::runtime::RealtimeRenderSession mixedRealtime{*mixed.graph};
    const auto mixedOffline = talas::runtime::renderOffline(*mixed.graph, 4);
    require(!mixedRealtime.ready() && !mixedOffline.ok(),
        "C156 mixed Multislope support should not mint promoted authority");

    auto divergentRegistry = talas::core::makeBuiltinNodeRegistry();
    divergentRegistry.setNodeTypeFanInLatencyPolicy(
        "talas.multislopeFunctionGenerator",
        talas::core::FanInLatencyPolicy::PreserveRelative);
    const auto divergent = talas::runtime::compileProject(
        makeAuthorityDocument(), divergentRegistry,
        talas::runtime::RenderSettings{4.0, 4});
    require(divergent.ok(),
        "C156 coherent divergent descriptor should compile before admission rejection");
    talas::runtime::RealtimeRenderSession divergentRealtime{
        *divergent.graph};
    const auto divergentOffline = talas::runtime::renderOffline(
        *divergent.graph, 4);
    require(!divergentRealtime.ready() && !divergentOffline.ok(),
        "C156 coherent divergent Supported descriptor should not mint built-in authority");
}

void testRealtimeMultislopeDownstreamFailureRetryRestoresState()
{
    const auto makeRetryGraph = [] {
        auto document = makeMultislopeVcaDocument();
        document.graph.nodes.push_back(node(
            "z_failureLeft", "talas.constant",
            {{"value", "!C116RetryGain"}}));
        document.graph.nodes.push_back(node(
            "z_failureRight", "talas.constant", {{"value", "1e200"}}));
        document.graph.nodes.push_back(node(
            "z_failureProduct", "talas.product"));
        document.graph.nodes.push_back(node(
            "z_failureOsc", "talas.oscillator",
            {{"frequency", "0.5 hz"}, {"amplitude", "0.25"}}));
        document.graph.nodes.push_back(node("z_failureVca", "talas.vca"));
        document.graph.nodes.push_back(node(
            "zz_mix", "talas.mixer", {{"gain1", "1"}, {"gain2", "1"}}));
        std::erase_if(document.graph.connections, [](const auto& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });
        document.graph.connections.push_back(connection(
            "z_failureLeft", "value", "z_failureProduct", "left"));
        document.graph.connections.push_back(connection(
            "z_failureRight", "value", "z_failureProduct", "right"));
        document.graph.connections.push_back(connection(
            "z_failureOsc", "audioOut", "z_failureVca", "audioIn"));
        document.graph.connections.push_back(connection(
            "z_failureProduct", "value", "z_failureVca", "gain"));
        document.graph.connections.push_back(connection(
            "vca", "audioOut", "zz_mix", "in1"));
        document.graph.connections.push_back(connection(
            "z_failureVca", "audioOut", "zz_mix", "in2"));
        document.graph.connections.push_back(connection(
            "zz_mix", "audioOut", "out", "audioIn"));
        auto settings = talas::runtime::RenderSettings{4.0, 2};
        settings.eventValues = {
            {"C116RetryGain", 1.0,
                talas::expr::ValueDomain::Scalar},
        };
        return compile(document, std::move(settings));
    };

    talas::runtime::RealtimeRenderSession candidate(makeRetryGraph());
    talas::runtime::RealtimeRenderSession pristine(makeRetryGraph());
    require(candidate.ready() && pristine.ready(),
        "C116 downstream retry fixtures should prepare: "
            + std::string{candidate.error()});
    std::array<double, 2> candidateOutput{};
    std::array<double, 2> pristineOutput{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, candidateOutput, allocations)
            && allocations == 0
            && renderAndCount(pristine, pristineOutput, allocations)
            && allocations == 0
            && candidateOutput == pristineOutput,
        "C116 retry fixtures should establish identical accepted Multislope state");
    const auto beforeFailure =
        talas::runtime::RealtimeRenderSessionTestAccess::
            multislopeElapsedTime(candidate);

    require(candidate.updateEventValue(
            "C116RetryGain",
            std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar),
        "C116 candidate should accept a downstream-failure Event Value");
    candidateOutput.fill(17.0);
    require(!renderAndCount(candidate, candidateOutput, allocations)
            && allocations == 0
            && candidateOutput == std::array<double, 2>{}
            && talas::runtime::RealtimeRenderSessionTestAccess::
                    multislopeElapsedTime(candidate)
                == beforeFailure,
        "C116 downstream failure should publish no output or Multislope state");

    require(candidate.updateEventValue(
            "C116RetryGain", 1.0,
            talas::expr::ValueDomain::Scalar),
        "C116 candidate should accept the repaired Event Value");
    require(renderAndCount(candidate, candidateOutput, allocations)
            && allocations == 0
            && renderAndCount(pristine, pristineOutput, allocations)
            && allocations == 0
            && candidateOutput == pristineOutput
            && talas::runtime::RealtimeRenderSessionTestAccess::
                    multislopeElapsedTime(candidate)
                == talas::runtime::RealtimeRenderSessionTestAccess::
                    multislopeElapsedTime(pristine),
        "C116 repaired retry should restore exact Multislope state and output");
}

