    require(renderAndCount(reference, ignored, allocations), "connected Graphical Envelope reference first block should render");
    require(direct.updateEventValue("GraphLevel", 0.5, talas::expr::ValueDomain::Scalar), "direct Graphical Envelope level should update");
    require(direct.updateEventValue("GraphRate", 2.0, talas::expr::ValueDomain::Scalar), "direct Graphical Envelope rate should update");
    require(reference.updateEventValue("GraphLevel", 0.5, talas::expr::ValueDomain::Scalar), "connected Graphical Envelope level should update");
