void testRealtimeSessionDirectGraphicalEnvelopeGateMatchesConnectedLifecycle()
{
    auto settings = makeGraphicalEnvelopeEventValueSettings();
    auto directGraph = compile(makeDirectEventValueGraphicalEnvelopeVcaDocument(), settings);
    auto referenceGraph = compile(makeConnectedGraphicalEnvelopeVcaDocument(), std::move(settings));
    talas::runtime::RealtimeRenderSession direct(directGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(direct.ready(), std::string(direct.error()));
    require(reference.ready(), std::string(reference.error()));

    std::array<double, 2> ignored{};
    std::array<double, 2> directContinuing{};
    std::array<double, 2> referenceContinuing{};
    std::array<double, 2> directRetriggered{};
    std::array<double, 2> referenceRetriggered{};
    std::size_t allocations = 0;
    require(renderAndCount(direct, ignored, allocations), "direct Graphical Envelope trigger should render");
    require(renderAndCount(reference, ignored, allocations), "connected Graphical Envelope trigger should render");
    require(direct.updateEventValue("GraphGate", 0.0, talas::expr::ValueDomain::Scalar), "direct Graphical Envelope gate should close");
    require(reference.updateEventValue("GraphGate", 0.0, talas::expr::ValueDomain::Scalar), "connected Graphical Envelope gate should close");
    require(renderAndCount(direct, directContinuing, allocations), "closed direct Graphical Envelope should continue");
    require(renderAndCount(reference, referenceContinuing, allocations), "closed connected Graphical Envelope should continue");
    require(direct.updateEventValue("GraphGate", 1.0, talas::expr::ValueDomain::Scalar), "direct Graphical Envelope gate should reopen");
    require(reference.updateEventValue("GraphGate", 1.0, talas::expr::ValueDomain::Scalar), "connected Graphical Envelope gate should reopen");
    require(renderAndCount(direct, directRetriggered, allocations), "direct Graphical Envelope should retrigger");
    require(allocations == 0, "direct Graphical Envelope retrigger should not allocate");
    require(renderAndCount(reference, referenceRetriggered, allocations), "connected Graphical Envelope should retrigger");
    require(allocations == 0, "connected Graphical Envelope retrigger should not allocate");
    for (std::size_t frame = 0; frame < directContinuing.size(); ++frame)
    {
        requireNear(directContinuing[frame], referenceContinuing[frame], 1.0e-12, "direct Graphical Envelope falling gate should continue and rearm");
        requireNear(directRetriggered[frame], referenceRetriggered[frame], 1.0e-12, "direct Graphical Envelope rising gate should retrigger");
    }
}

void testRealtimeGraphicalEnvelopePairedSchedulesMatchOfflinePartitions()
{
    auto document = makeDirectEventValueGraphicalEnvelopeVcaDocument();
    const auto graphical = std::ranges::find(
        document.graph.nodes, std::string_view{"graphical"},
        &talas::project::ProjectNode::instanceId);
    require(graphical != document.graph.nodes.end(),
        "C158 paired schedule fixture should expose Graphical Envelope");
    graphical->parameters[0] = textParameter(
        "envelope", "{0 s} {0} {0.5 s} {1} {0.75 s} {0.5}");

    auto preparedSettings = talas::runtime::RenderSettings{8.0, 8};
    preparedSettings.eventValues = {
        {"GraphLevel", 0.5, talas::expr::ValueDomain::Scalar},
        {"GraphGate", 0.0, talas::expr::ValueDomain::Scalar},
        {"GraphRate", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto offlineSettings = preparedSettings;
    offlineSettings.eventValueChanges = {
        {1, "GraphGate", 1.0, talas::expr::ValueDomain::Scalar},
        {2, "GraphRate", 4.0, talas::expr::ValueDomain::Scalar},
        {3, "GraphLevel", 0.25, talas::expr::ValueDomain::Scalar},
        {4, "GraphGate", 0.0, talas::expr::ValueDomain::Scalar},
        {5, "GraphLevel", 0.75, talas::expr::ValueDomain::Scalar},
        {5, "GraphGate", 1.0, talas::expr::ValueDomain::Scalar},
        {5, "GraphRate", 0.5, talas::expr::ValueDomain::Scalar},
        {6, "GraphGate", 0.0, talas::expr::ValueDomain::Scalar},
        {7, "GraphLevel", 1.0, talas::expr::ValueDomain::Scalar},
        {7, "GraphRate", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto offline = talas::runtime::renderOffline(
        compile(document, offlineSettings), 8);
    const auto prepared = compile(document, preparedSettings);
    require(offline.ok() && offline.mono.size() == 8,
        "C158 paired Graphical Envelope schedules should render offline");
    requireNear(offline.mono[0], 0.0, 1.0e-12,
        "C158 closed initial gate should remain at rest");
    requireNear(offline.mono[1], 0.0, 1.0e-12,
        "C158 rising gate should render elapsed time zero");
    requireNear(offline.mono[2], 0.04783542904563622, 1.0e-12,
        "C158 rate change should apply only to the post-output advance");
    require(offline.mono[4] > 0.0,
        "C158 falling gate should continue through the held endpoint");
    requireNear(offline.mono[5], 0.0, 1.0e-12,
        "C158 simultaneous controls should retrigger before output");

    const auto renderPrepared = [&](bool singleFrame) {
        talas::runtime::RealtimeRenderSession session{prepared};
        require(session.ready(),
            "C158 paired Graphical Envelope schedules should prepare: "
                + std::string{session.error()});
        require(
            session.scheduleEventValue(
                "GraphGate", 1.0,
                talas::expr::ValueDomain::Scalar, 1)
                && session.scheduleEventValue(
                    "GraphRate", 4.0,
                    talas::expr::ValueDomain::Scalar, 2)
                && session.scheduleEventValue(
                    "GraphLevel", 0.25,
                    talas::expr::ValueDomain::Scalar, 3)
                && session.scheduleEventValue(
                    "GraphGate", 0.0,
                    talas::expr::ValueDomain::Scalar, 4)
                && session.scheduleEventValue(
                    "GraphLevel", 0.75,
                    talas::expr::ValueDomain::Scalar, 5)
                && session.scheduleEventValue(
                    "GraphGate", 1.0,
                    talas::expr::ValueDomain::Scalar, 5)
                && session.scheduleEventValue(
                    "GraphRate", 0.5,
                    talas::expr::ValueDomain::Scalar, 5)
                && session.scheduleEventValue(
                    "GraphGate", 0.0,
                    talas::expr::ValueDomain::Scalar, 6)
                && session.scheduleEventValue(
                    "GraphLevel", 1.0,
                    talas::expr::ValueDomain::Scalar, 7)
                && session.scheduleEventValue(
                    "GraphRate", 1.0,
                    talas::expr::ValueDomain::Scalar, 7),
            "C158 prepared Graphical Envelope should accept paired direct schedules");
        std::array<double, 8> actual{};
        std::size_t allocations = 0;
        if (singleFrame)
        {
            for (std::size_t frame = 0; frame < actual.size(); ++frame)
            {
                require(
                    renderAndCount(
                        session,
                        std::span<double>{actual}.subspan(frame, 1),
                        allocations)
                        && allocations == 0,
                    "C158 single-frame Graphical Envelope callback should render without allocation");
            }
        }
        else
        {
            require(
                renderAndCount(
                    session, std::span<double>{actual}.first(1),
                    allocations)
                    && allocations == 0
                    && renderAndCount(
                        session,
                        std::span<double>{actual}.subspan(1, 2),
                        allocations)
                    && allocations == 0
                    && renderAndCount(
                        session,
                        std::span<double>{actual}.subspan(3, 2),
                        allocations)
                    && allocations == 0
                    && renderAndCount(
                        session,
                        std::span<double>{actual}.subspan(5, 3),
                        allocations)
                    && allocations == 0,
                "C158 irregular Graphical Envelope callbacks should render without allocation");
        }
        require(std::ranges::equal(actual, offline.mono),
            "C158 Graphical Envelope schedules should be bit-identical across offline and prepared partitions");
    };
    renderPrepared(false);
    renderPrepared(true);
}

void testRealtimeGraphicalEnvelopeRequiresExactCompilerOwnedAuthority()
{
    const auto makeAuthorityDocument = [] {
        talas::project::ProjectDocument document;
        document.graph.nodes = {
            node("out", "talas.audioOutput"),
            node("carrier", "talas.oscillator", {
                {"frequency", "0.25 hz"}, {"amplitude", "0.25"}}),
            node("graphical", "talas.graphicalEnvelope", {
                textParameter(
                    "envelope", "{0 s} {0} {1 s} {1} {2 s} {0.5}"),
                {"level", "1"}, {"gate", "1"}, {"rate", "1"},
            }),
        };
        document.graph.connections = {
            connection("graphical", "value", "carrier", "frequency"),
            connection("carrier", "audioOut", "out", "audioIn"),
        };
        return document;
    };
    const auto compiled = compile(
        makeAuthorityDocument(),
        talas::runtime::RenderSettings{4.0, 4});
    talas::runtime::RealtimeRenderSession exact{compiled};
    const auto exactOffline = talas::runtime::renderOffline(compiled, 4);
    require(exact.ready() && exactOffline.ok(),
        "C158 exact built-in Graphical Envelope authority should render offline and prepare realtime");

    const auto publiclyConstructedGraph =
        talas::runtime::PreparedRuntimeGraph{
            compiled.plan(), compiled.renderSettings()};
    talas::runtime::RealtimeRenderSession publiclyConstructed{
        publiclyConstructedGraph};
    const auto publicOffline = talas::runtime::renderOffline(
        publiclyConstructedGraph, 4);
    require(!publiclyConstructed.ready() && !publicOffline.ok(),
        "C158 Graphical Envelope should require privately compiler-sealed exact execution authority");

    const auto requireRejected = [](auto forged,
                                    std::string_view context) {
        talas::runtime::RealtimeRenderSession rejected{forged};
        const auto offline = talas::runtime::renderOffline(forged, 4);
        require(!rejected.ready() && !offline.ok(),
            "C158 Graphical Envelope authority should reject "
                + std::string{context});
    };

    auto forgedText = compiled;
    auto& textPlan = mutablePlanForTest(forgedText);
    const auto textStep = std::ranges::find(
        textPlan.steps,
        std::string_view{"talas.graphicalEnvelope"},
        &talas::runtime::CompileStep::typeId);
    require(textStep != textPlan.steps.end()
            && textStep->parameters[0].text.has_value(),
        "C158 authority fixture should expose Graphical Envelope text");
    *textStep->parameters[0].text += " ";
    requireRejected(std::move(forgedText),
        "static envelope text mutation");

    auto forgedControl = compiled;
    const auto controlStep = std::ranges::find(
        mutablePlanForTest(forgedControl).steps,
        std::string_view{"talas.graphicalEnvelope"},
        &talas::runtime::CompileStep::typeId);
    controlStep->parameters[1].value = std::nextafter(
        controlStep->parameters[1].value,
        std::numeric_limits<double>::infinity());
    requireRejected(std::move(forgedControl),
        "level control-bit mutation");

    auto forgedScope = compiled;
    const auto scopeStep = std::ranges::find(
        mutablePlanForTest(forgedScope).steps,
        std::string_view{"talas.graphicalEnvelope"},
        &talas::runtime::CompileStep::typeId);
    ++scopeStep->scopeId;
    requireRejected(std::move(forgedScope),
        "execution-scope mutation");

    auto forgedAncestry = compiled;
    const auto ancestryStep = std::ranges::find(
        mutablePlanForTest(forgedAncestry).steps,
        std::string_view{"talas.graphicalEnvelope"},
        &talas::runtime::CompileStep::typeId);
    ancestryStep->structuralSourcePath += "/forged";
    requireRejected(std::move(forgedAncestry),
        "structural-ancestry mutation");

    auto forgedLatency = compiled;
    const auto latencyStep = std::ranges::find(
        mutablePlanForTest(forgedLatency).steps,
        std::string_view{"talas.graphicalEnvelope"},
        &talas::runtime::CompileStep::typeId);
    latencyStep->cumulativeOutputLatencyFrames = 1;
    requireRejected(std::move(forgedLatency),
        "latency mutation");

    auto forgedOutput = compiled;
    auto& outputPlan = mutablePlanForTest(forgedOutput);
    const auto output = std::ranges::find_if(
        outputPlan.buffers,
        [](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == "graphical"
                && buffer.portId == "value";
        });
    require(output != outputPlan.buffers.end(),
        "C158 authority fixture should expose Graphical Envelope output buffer");
    ++output->frames;
    requireRejected(std::move(forgedOutput),
        "output-buffer mutation");

    const auto connectedCompiled = compile(
        makeDirectEventValueGraphicalEnvelopeVcaDocument(true),
        makeGraphicalEnvelopeEventValueSettings());
    talas::runtime::RealtimeRenderSession connectedExact{connectedCompiled};
    const auto connectedOffline = talas::runtime::renderOffline(
        connectedCompiled, 4);
    require(connectedExact.ready() && connectedOffline.ok(),
        "C158 exact optional connected level/gate/rate bindings should render in both engines");

    const auto requireSingleOptionalInputAccepted = [](
        std::string_view inputPortId,
        double value) {
        auto document =
            makeDirectEventValueGraphicalEnvelopeVcaDocument();
        const auto producerId = std::string{inputPortId} + "Only";
        document.graph.nodes.push_back(node(
            producerId, "talas.constant",
            {{"value", std::to_string(value)}}));
        document.graph.connections.push_back(connection(
            producerId, "value", "graphical", std::string{inputPortId}));

        const auto graph = compile(
            std::move(document),
            makeGraphicalEnvelopeEventValueSettings());
        const auto graphical = std::ranges::find(
            graph.plan().steps,
            std::string_view{"talas.graphicalEnvelope"},
            &talas::runtime::CompileStep::typeId);
        require(graphical != graph.plan().steps.end()
                && graphical->inputs.size() == 1
                && graphical->inputs.front().inputPortId == inputPortId
                && graphical->inputs.front().sourceNodeId == producerId,
            "C158 single optional-input fixture should seal only the selected "
                + std::string{inputPortId} + " binding");

        talas::runtime::RealtimeRenderSession realtime{graph};
        const auto offline = talas::runtime::renderOffline(graph, 4);
        require(realtime.ready() && offline.ok(),
            "C158 " + std::string{inputPortId}
                + "-only optional binding should admit and render in both engines");
    };
    requireSingleOptionalInputAccepted("level", 0.5);
    requireSingleOptionalInputAccepted("gate", 1.0);
    requireSingleOptionalInputAccepted("rate", 0.5);

    auto forgedInput = connectedCompiled;
    const auto inputStep = std::ranges::find(
        mutablePlanForTest(forgedInput).steps,
        std::string_view{"talas.graphicalEnvelope"},
        &talas::runtime::CompileStep::typeId);
    require(inputStep != mutablePlanForTest(forgedInput).steps.end()
            && inputStep->inputs.size() == 3,
        "C158 authority fixture should expose connected level/gate/rate bindings");
    ++inputStep->inputs.front().sourceScopeId;
    requireRejected(std::move(forgedInput),
        "input-binding mutation");

    auto forgedProducer = connectedCompiled;
    const auto producerStep = std::ranges::find(
        mutablePlanForTest(forgedProducer).steps,
        std::string_view{"talas.graphicalEnvelope"},
        &talas::runtime::CompileStep::typeId);
    producerStep->inputs.front().sourceNodeId += "Forged";
    requireRejected(std::move(forgedProducer),
        "input-producer mutation");

    auto forgedSettings = compiled;
    mutableSettingsForTest(forgedSettings).tempoBpm = std::nextafter(
        forgedSettings.renderSettings().tempoBpm,
        std::numeric_limits<double>::infinity());
    requireRejected(std::move(forgedSettings),
        "settings-bit mutation");

    auto forgedResource = compiled;
    mutableSettingsForTest(forgedResource).tableResources.push_back(
        {"Tables/C158Unrelated", {9.0}});
    requireRejected(std::move(forgedResource),
        "unrelated-resource mutation");

    auto coherentlyForged = compiled;
    ++mutableSettingsForTest(coherentlyForged).maxBlockFrames;
    for (auto& buffer : mutablePlanForTest(coherentlyForged).buffers)
        ++buffer.frames;
    requireRejected(std::move(coherentlyForged),
        "coherent plan/settings buffer-capacity mutation");

    auto downgraded = compiled;
    const auto downgradedStep = std::ranges::find(
        mutablePlanForTest(downgraded).steps,
        std::string_view{"talas.graphicalEnvelope"},
        &talas::runtime::CompileStep::typeId);
    downgradedStep->offlineSupport =
        talas::core::ExecutionSupport::Subset;
    requireRejected(std::move(downgraded),
        "sealed support downgrade");

    auto statefulDocument = makeAuthorityDocument();
    const auto statefulNode = std::ranges::find(
        statefulDocument.graph.nodes,
        std::string_view{"graphical"},
        &talas::project::ProjectNode::instanceId);
    statefulNode->parameters[1].expression = "previous(0, 0)";
    const auto stateful = talas::runtime::compileProject(
        statefulDocument, talas::core::makeBuiltinNodeRegistry(),
        talas::runtime::RenderSettings{4.0, 4});
    require(stateful.ok(),
        "C158 stateful control fixture should compile before promoted admission rejection");
    requireRejected(*stateful.graph,
        "stateful direct control authority");

    auto subsetRegistry = talas::core::makeBuiltinNodeRegistry();
    subsetRegistry.setNodeTypeOfflineSupport(
        "talas.graphicalEnvelope",
        talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    subsetRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.graphicalEnvelope",
        talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto subset = talas::runtime::compileProject(
        makeAuthorityDocument(), subsetRegistry,
        talas::runtime::RenderSettings{4.0, 4});
    require(subset.ok(),
        "C158 explicit custom Subset Graphical Envelope should compile");
    const auto unsealed =
        makePublicCompatibilityGraphWithSubsetOscillators(
            *subset.graph);
    talas::runtime::RealtimeRenderSession subsetRealtime{unsealed};
    const auto subsetOffline = talas::runtime::renderOffline(unsealed, 4);
    require(subsetRealtime.ready() && subsetOffline.ok(),
        "C158 genuine unsealed both-Subset Graphical Envelope should retain legacy compatibility: "
            + std::string{subsetRealtime.error()});

    auto mixedRegistry = talas::core::makeBuiltinNodeRegistry();
    mixedRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.graphicalEnvelope",
        talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto mixed = talas::runtime::compileProject(
        makeAuthorityDocument(), mixedRegistry,
        talas::runtime::RenderSettings{4.0, 4});
    require(mixed.ok(),
        "C158 mixed-support fixture should compile before admission rejection");
    requireRejected(*mixed.graph,
        "mixed renderer support");

    auto divergentRegistry = talas::core::makeBuiltinNodeRegistry();
    divergentRegistry.setNodeTypeFanInLatencyPolicy(
        "talas.graphicalEnvelope",
        talas::core::FanInLatencyPolicy::PreserveRelative);
    const auto divergent = talas::runtime::compileProject(
        makeAuthorityDocument(), divergentRegistry,
        talas::runtime::RenderSettings{4.0, 4});
    require(divergent.ok(),
        "C158 divergent descriptor should compile before admission rejection");
    requireRejected(*divergent.graph,
        "coherent divergent Supported descriptor");
}

void testRealtimeGraphicalEnvelopeConnectedFallbacksHideOnlyExactNonFinite()
{
    const auto setParameter = [](
        talas::project::ProjectDocument& document,
        std::string_view parameterId,
        std::string expression) {
        const auto graphical = std::ranges::find(
            document.graph.nodes, std::string_view{"graphical"},
            &talas::project::ProjectNode::instanceId);
        require(graphical != document.graph.nodes.end(),
            "C158 fallback fixture should expose Graphical Envelope");
        const auto parameter = std::ranges::find(
            graphical->parameters, parameterId,
            &talas::project::ProjectParameterExpression::parameterId);
        require(parameter != graphical->parameters.end(),
            "C158 fallback fixture should expose selected control");
        parameter->expression = std::move(expression);
    };

    auto nonFinite = makeDirectEventValueGraphicalEnvelopeVcaDocument(true);
    setParameter(nonFinite, "level", "1e200 * 1e200");
    const auto accepted = talas::runtime::compileProject(
        nonFinite, talas::core::makeBuiltinNodeRegistry(),
        makeGraphicalEnvelopeEventValueSettings());
    require(accepted.ok(),
        "C158 connected precedence should hide one exact non-finite promoted Graphical Envelope fallback");
    talas::runtime::RealtimeRenderSession acceptedRealtime{*accepted.graph};
    const auto acceptedOffline = talas::runtime::renderOffline(
        *accepted.graph, 2);
    require(acceptedRealtime.ready() && acceptedOffline.ok(),
        "C158 exact non-finite connected fallback should render in both engines");

    auto unresolved = makeDirectEventValueGraphicalEnvelopeVcaDocument(true);
    setParameter(unresolved, "gate", "!C158MissingGate");
    const auto rejected = talas::runtime::compileProject(
        unresolved, talas::core::makeBuiltinNodeRegistry(),
        makeGraphicalEnvelopeEventValueSettings());
    require(!rejected.ok(),
        "C158 connected precedence must not hide unresolved Graphical Envelope fallback authority");
}

void testRealtimeGraphicalEnvelopeDownstreamFailureRetryRestoresStateWithoutOscillator()
{
    const auto makeRetryGraph = [] {
        auto document = makeGraphicalEnvelopeVcaDocument();
        auto source = std::ranges::find(
            document.graph.nodes,
            "carrier",
            &talas::project::ProjectNode::instanceId);
        require(source != document.graph.nodes.end(),
            "C158 prepared rollback fixture should expose its source");
        source->typeId = "talas.audioInput";
        source->parameters = {
            booleanParameter("channel1", true),
            booleanParameter("channel2", false),
        };
        document.graph.nodes.push_back(node(
            "z_failureLeft", "talas.constant",
            {{"value", "!C158RetryGain"}}));
        document.graph.nodes.push_back(node(
            "z_failureRight", "talas.constant", {{"value", "1e200"}}));
        document.graph.nodes.push_back(node(
            "z_failureProduct", "talas.product"));
        document.graph.nodes.push_back(node(
            "z_failureVca", "talas.vca"));
        document.graph.nodes.push_back(node(
            "zz_mix", "talas.mixer", {{"gain1", "1"}, {"gain2", "1"}}));
        std::erase_if(document.graph.connections, [](const auto& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });
        document.graph.connections.push_back(connection(
            "z_failureLeft", "value", "z_failureProduct", "left"));
        document.graph.connections.push_back(connection(
            "z_failureRight", "value", "z_failureProduct", "right"));
        document.graph.connections.push_back(connection(
            "carrier", "audioOut", "z_failureVca", "audioIn"));
        document.graph.connections.push_back(connection(
            "z_failureProduct", "value", "z_failureVca", "gain"));
        document.graph.connections.push_back(connection(
            "vca", "audioOut", "zz_mix", "in1"));
        document.graph.connections.push_back(connection(
            "z_failureVca", "audioOut", "zz_mix", "in2"));
        document.graph.connections.push_back(connection(
            "zz_mix", "audioOut", "out", "audioIn"));
        auto settings = talas::runtime::RenderSettings{4.0, 2};
        settings.eventValues = {
            {"C158RetryGain", 1.0,
                talas::expr::ValueDomain::Scalar},
        };
        return compile(document, std::move(settings));
    };

    talas::runtime::RealtimeRenderSession candidate(makeRetryGraph());
    talas::runtime::RealtimeRenderSession pristine(makeRetryGraph());
    require(candidate.ready() && pristine.ready(),
        "C158 non-oscillator downstream retry fixtures should prepare: "
            + std::string{candidate.error()});
    std::array<float, 2> inputSamples{1.0F, 1.0F};
    std::array<const float*, 1> inputChannels{inputSamples.data()};
    const talas::runtime::RealtimeAudioInputBlock input{
        inputChannels.data(), inputChannels.size()};
    std::array<double, 2> candidateOutput{};
    std::array<double, 2> pristineOutput{};
    std::size_t allocations = 0;
    require(renderMonoInputAndCount(
                candidate, input, candidateOutput, allocations)
            && allocations == 0
            && renderMonoInputAndCount(
                pristine, input, pristineOutput, allocations)
            && allocations == 0
            && candidateOutput == pristineOutput,
        "C158 retry fixtures should establish identical accepted Graphical Envelope state");
    const auto beforeFailure =
        talas::runtime::RealtimeRenderSessionTestAccess::
            graphicalEnvelopeElapsedTime(candidate);

    require(candidate.updateEventValue(
            "C158RetryGain",
            std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar),
        "C158 candidate should accept a downstream-failure Event Value");
    candidateOutput.fill(17.0);
    require(!renderMonoInputAndCount(
                candidate, input, candidateOutput, allocations)
            && allocations == 0
            && candidateOutput == std::array<double, 2>{}
            && talas::runtime::RealtimeRenderSessionTestAccess::
                    graphicalEnvelopeElapsedTime(candidate)
                == beforeFailure,
        "C158 downstream failure should publish no output or Graphical Envelope state without oscillator ancestry");

    require(candidate.updateEventValue(
            "C158RetryGain", 1.0,
            talas::expr::ValueDomain::Scalar),
        "C158 candidate should accept the repaired Event Value");
    require(renderMonoInputAndCount(
                candidate, input, candidateOutput, allocations)
            && allocations == 0
            && renderMonoInputAndCount(
                pristine, input, pristineOutput, allocations)
            && allocations == 0
            && candidateOutput == pristineOutput
            && talas::runtime::RealtimeRenderSessionTestAccess::
                    graphicalEnvelopeElapsedTime(candidate)
                == talas::runtime::RealtimeRenderSessionTestAccess::
                    graphicalEnvelopeElapsedTime(pristine),
        "C158 repaired retry should restore exact Graphical Envelope state and output without oscillator ancestry");
}

void testRealtimeSessionConnectedGraphicalEnvelopeControlsOverrideDirectFallbacks()
{
    auto settings = makeGraphicalEnvelopeEventValueSettings();
    auto candidateGraph = compile(makeDirectEventValueGraphicalEnvelopeVcaDocument(true), settings);
    auto referenceGraph = compile(makeDirectEventValueGraphicalEnvelopeVcaDocument(true), std::move(settings));
    talas::runtime::RealtimeRenderSession candidate(candidateGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(candidate.ready(), std::string(candidate.error()));
    require(reference.ready(), std::string(reference.error()));
    require(candidate.updateEventValue("GraphLevel", 0.25, talas::expr::ValueDomain::Scalar), "overridden Graphical Envelope level should update");
    require(candidate.updateEventValue("GraphGate", 0.0, talas::expr::ValueDomain::Scalar), "overridden Graphical Envelope gate should update");
    require(candidate.updateEventValue("GraphRate", 2.0, talas::expr::ValueDomain::Scalar), "overridden Graphical Envelope rate should update");
    std::array<double, 2> candidateOutput{};
    std::array<double, 2> referenceOutput{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, candidateOutput, allocations), "connected-precedence Graphical Envelope candidate should render");
    require(allocations == 0, "connected-precedence Graphical Envelope candidate should not allocate");
    require(renderAndCount(reference, referenceOutput, allocations), "connected-precedence Graphical Envelope reference should render");
    require(allocations == 0, "connected-precedence Graphical Envelope reference should not allocate");
    for (std::size_t frame = 0; frame < candidateOutput.size(); ++frame)
        requireNear(candidateOutput[frame], referenceOutput[frame], 1.0e-12, "connected Graphical Envelope controls should override direct fallbacks");
}

