    requireNear(second[0], 0.17677669529663687, 1.0e-12, "looping Triggered Table Read should wrap at the table boundary");
    requireNear(second[1], 0.46193976625564337, 1.0e-12, "looping Triggered Table Read should continue after wrapping");
    requireNear(third[0], 0.25, 1.0e-12, "looping Triggered Table Read should wrap repeatedly");
