void testCheckedTriggeredTableReadTransitionOwnsCursorGateAndFailureSemantics()
{
    using namespace talas::runtime::checked_triggered_table_read;

    const std::array samples{1.0, 2.0};
    State state;
    State candidate{99, 99.0, false};
    auto output = 77.0;
    require(
        advance(
            state, Controls{1.0, 1.0, samples, true},
            candidate, output) == Error::None
            && candidate.readIndex == 1
            && candidate.heldValue == 1.0
            && candidate.gateWasPositive
            && output == 1.0,
        "C154 checked Triggered Table Read should reset before a same-frame positive-trigger read");

    state = candidate;
    require(
        advance(
            state, Controls{-0.0, 1.0, samples, true},
            candidate, output) == Error::None
            && candidate.readIndex == 1
            && candidate.heldValue == 1.0
            && candidate.gateWasPositive
            && output == 1.0,
        "C154 signed-zero trigger should hold cursor and sample");

    state = candidate;
    require(
        advance(
            state, Controls{1.0, -0.0, samples, true},
            candidate, output) == Error::None
            && candidate.readIndex == 2
            && candidate.heldValue == 2.0
            && !candidate.gateWasPositive
            && output == 2.0,
        "C154 inactive signed-zero gate should preserve cursor before reading");

    state = candidate;
    require(
        advance(
            state, Controls{1.0, 0.0, samples, true},
            candidate, output) == Error::None
            && candidate.readIndex == 2
            && candidate.heldValue == 2.0
            && output == 2.0,
        "C154 ignoreLoops should hold the final sample at exhaustion");
    require(
        advance(
            state, Controls{1.0, 0.0, samples, false},
            candidate, output) == Error::None
            && candidate.readIndex == 2
            && candidate.heldValue == 2.0
            && output == 2.0,
        "a table without a header loop should play once and hold its final sample");
    require(
        advance(
            state, Controls{1.0, 0.0, samples, false, 0, 2},
            candidate, output) == Error::None
            && candidate.readIndex == 1
            && candidate.heldValue == 1.0
            && output == 1.0,
        "a header loop should send an exhausted cursor back to its start before reading");
    require(
        advance(
            state, Controls{1.0, 0.0, samples, false, 0, 0, true},
            candidate, output) == Error::None
            && candidate.readIndex == 1
            && candidate.heldValue == 1.0
            && output == 1.0,
        "C154 legacy looping should wrap before reading an exhausted cursor");
    require(
        advance(
            state, Controls{1.0, 1.0, samples, true},
            candidate, output) == Error::None
            && candidate.readIndex == 1
            && candidate.heldValue == 1.0
            && candidate.gateWasPositive
            && output == 1.0,
        "C154 gate edge should reset an exhausted cursor before the same-frame read");

    const auto sentinel = State{9, 8.0, true};
    candidate = sentinel;
    output = 7.0;
    const std::array invalidSamples{1.0,
        std::numeric_limits<double>::infinity()};
    require(
        advance(
            State{1, 1.0, false},
            Controls{1.0, 0.0, invalidSamples, false},
            candidate, output) == Error::SampleNonFinite
            && candidate.readIndex == sentinel.readIndex
            && candidate.heldValue == sentinel.heldValue
            && candidate.gateWasPositive
                == sentinel.gateWasPositive
            && output == 7.0,
        "C154 checked transition failure should publish neither candidate state nor output");

    const std::array oneSample{3.0};
    require(
        advance(
            State{}, Controls{1.0, 0.0, oneSample, false},
            candidate, output) == Error::None
            && candidate.readIndex == 1
            && candidate.heldValue == 3.0
            && output == 3.0,
        "C154 one-sample tables should use the same checked cursor transition");
}

void testRealtimeTriggeredTableReadPairedSchedulesMatchOfflinePartitions()
{
    for (const auto ignoreLoops : {false, true})
    {
        const auto document = makeTriggeredTableReadVcaDocument({
            {"trigger", "!TableTrigger"},
            resourceParameter("wavetable", "Tables/Steps"),
            {"gate", "!TableGate"},
            booleanParameter("ignoreLoops", ignoreLoops),
            booleanParameter("fromMemoryWriter", false),
        });
        auto preparedSettings = talas::runtime::RenderSettings{8.0, 8};
        preparedSettings.eventValues = {
            {"TableTrigger", 0.0, talas::expr::ValueDomain::Scalar},
            {"TableGate", 0.0, talas::expr::ValueDomain::Scalar},
        };
        preparedSettings.tableResources.push_back(
            {"Tables/Steps", {2.0, 3.0}});
        auto offlineSettings = preparedSettings;
        offlineSettings.eventValueChanges = {
            {1, "TableTrigger", 1.0, talas::expr::ValueDomain::Scalar},
            {2, "TableTrigger", -0.0, talas::expr::ValueDomain::Scalar},
            {3, "TableGate", 1.0, talas::expr::ValueDomain::Scalar},
            {3, "TableTrigger", 1.0, talas::expr::ValueDomain::Scalar},
            {4, "TableGate", 0.0, talas::expr::ValueDomain::Scalar},
            {6, "TableTrigger", 0.0, talas::expr::ValueDomain::Scalar},
            {7, "TableTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        };

        const auto offlineGraph = compile(document, offlineSettings);
        const auto preparedGraph = compile(document, preparedSettings);
        const auto offline = talas::runtime::renderOffline(offlineGraph, 8);
        require(offline.ok() && offline.mono.size() == 8,
            "C154 paired Triggered Table Read schedules should render offline");

        const auto renderPrepared = [&](bool singleFrame) {
            talas::runtime::RealtimeRenderSession session{preparedGraph};
            require(session.ready(),
                "C154 paired schedules should prepare: "
                    + std::string{session.error()});
            require(
                session.scheduleEventValue(
                    "TableTrigger", 1.0,
                    talas::expr::ValueDomain::Scalar, 1)
                    && session.scheduleEventValue(
                        "TableTrigger", -0.0,
                        talas::expr::ValueDomain::Scalar, 2)
                    && session.scheduleEventValue(
                        "TableGate", 1.0,
                        talas::expr::ValueDomain::Scalar, 3)
                    && session.scheduleEventValue(
                        "TableTrigger", 1.0,
                        talas::expr::ValueDomain::Scalar, 3)
                    && session.scheduleEventValue(
                        "TableGate", 0.0,
                        talas::expr::ValueDomain::Scalar, 4)
                    && session.scheduleEventValue(
                        "TableTrigger", 0.0,
                        talas::expr::ValueDomain::Scalar, 6)
                    && session.scheduleEventValue(
                        "TableTrigger", 1.0,
                        talas::expr::ValueDomain::Scalar, 7),
                "C154 prepared Triggered Table Read should accept independent and joint schedules");
            std::array<double, 8> actual{};
            std::size_t allocations = 0;
            if (singleFrame)
            {
                for (std::size_t frame = 0; frame < actual.size(); ++frame)
                {
                    require(
                        renderAndCount(
                            session,
                            std::span<double>{actual}.subspan(frame, 1),
                            allocations)
                            && allocations == 0,
                        "C154 single-frame paired schedule callback should render without allocation");
                }
            }
            else
            {
                require(
                    renderAndCount(
                        session, std::span<double>{actual}.subspan(0, 1),
                        allocations)
                        && allocations == 0
                        && renderAndCount(
                            session, std::span<double>{actual}.subspan(1, 2),
                            allocations)
                        && allocations == 0
                        && renderAndCount(
                            session, std::span<double>{actual}.subspan(3, 1),
                            allocations)
                        && allocations == 0
                        && renderAndCount(
                            session, std::span<double>{actual}.subspan(4, 4),
                            allocations)
                        && allocations == 0,
                    "C154 irregular paired schedule callbacks should render without allocation");
            }
            require(std::ranges::equal(actual, offline.mono),
                "C154 paired schedules should be bit-identical across offline and prepared partitions");
        };
        renderPrepared(false);
        renderPrepared(true);
    }
}

void testRealtimeTriggeredTableReadRequiresExactCompilerOwnedAuthority()
{
    auto settings = talas::runtime::RenderSettings{8.0, 4};
    settings.eventValues = {
        {"TableTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        {"TableGate", 0.0, talas::expr::ValueDomain::Scalar},
    };
    settings.tableResources.push_back(
        {"Tables/Steps", {1.0, 2.0, 3.0}});
    const auto document = makeTriggeredTableReadVcaDocument({
        {"trigger", "!TableTrigger"},
        resourceParameter("wavetable", "Tables/Steps"),
        {"gate", "!TableGate"},
        booleanParameter("ignoreLoops", false),
        booleanParameter("fromMemoryWriter", false),
    });
    const auto exact = compile(document, settings);
    talas::runtime::RealtimeRenderSession exactSession{exact};
    const auto exactOffline = talas::runtime::renderOffline(exact, 4);
    require(exactSession.ready() && exactOffline.ok(),
        "C154 exact built-in Triggered Table Read authority should prepare offline and realtime");

    auto downgradedOfflineSupport = exact;
    auto& downgradedOfflinePlan =
        mutablePlanForTest(downgradedOfflineSupport);
    const auto downgradedTable = std::ranges::find(
        downgradedOfflinePlan.steps,
        std::string_view{"talas.triggeredTableRead"},
        &talas::runtime::CompileStep::typeId);
    require(downgradedTable != downgradedOfflinePlan.steps.end(),
        "C154 forged-support fixture should expose Triggered Table Read");
    downgradedTable->offlineSupport =
        talas::core::ExecutionSupport::Subset;
    talas::runtime::RealtimeRenderSession downgradedOfflineSession{
        downgradedOfflineSupport};
    const auto downgradedOffline = talas::runtime::renderOffline(
        downgradedOfflineSupport, 4);
    require(!downgradedOfflineSession.ready()
            && !downgradedOffline.ok()
            && downgradedOffline.mono.empty(),
        "C154 sealed built-in authority should reject an executable step downgraded from offline Supported to Subset");

    const auto expectMalformedSnapshotRejectedBeforeSeal =
        [&](auto mutate, std::string_view contract) {
            auto malformedSnapshot =
                std::make_shared<talas::core::ResourceSnapshot>();
            malformedSnapshot->id = "Tables/Steps";
            malformedSnapshot->kind =
                talas::core::ResourceSnapshotKind::Table;
            malformedSnapshot->generation = 1;
            malformedSnapshot->contentHash = std::string(64, 'a');
            malformedSnapshot->tableSamples = {1.0, 2.0, 3.0};
            mutate(*malformedSnapshot);
            auto malformedSettings =
                talas::runtime::RenderSettings{8.0, 4};
            malformedSettings.eventValues = settings.eventValues;
            malformedSettings.resourceSnapshots.push_back(
                std::move(malformedSnapshot));
            const auto malformed = talas::runtime::compileProject(
                document,
                talas::core::makeBuiltinNodeRegistry(),
                std::move(malformedSettings));
            require(!malformed.ok(),
                "C154 compiler should reject Table snapshot "
                    + std::string{contract}
                    + " before sealing authority");
        };
    expectMalformedSnapshotRejectedBeforeSeal(
        [](auto& snapshot) { snapshot.channelCount = 2; },
        "multichannel metadata");
    expectMalformedSnapshotRejectedBeforeSeal(
        [](auto& snapshot) { snapshot.sampleRate = 48'000.0; },
        "sample-rate metadata");
    expectMalformedSnapshotRejectedBeforeSeal(
        [](auto& snapshot) { snapshot.sampleRate = -0.0; },
        "negative-zero sample-rate metadata");
    expectMalformedSnapshotRejectedBeforeSeal(
        [](auto& snapshot) { snapshot.frameCount = 3; },
        "frame-count metadata");
    expectMalformedSnapshotRejectedBeforeSeal(
        [](auto& snapshot) { snapshot.encoding = "pcm16-wav"; },
        "encoding metadata");

    auto subsetRegistry = talas::core::makeBuiltinNodeRegistry();
    subsetRegistry.setNodeTypeOfflineSupport(
        "talas.triggeredTableRead",
        talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    subsetRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.triggeredTableRead",
        talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto subset = talas::runtime::compileProject(
        document, subsetRegistry, settings);
    require(subset.ok(),
        "C154 explicit custom Subset Triggered Table Read should compile");
    talas::runtime::RealtimeRenderSession subsetSession{*subset.graph};
    const auto subsetOffline = talas::runtime::renderOffline(
        *subset.graph, 4);
    require(subsetSession.ready() && subsetOffline.ok(),
        "C154 explicit custom Subset should retain C71 compatibility");

    talas::project::ProjectDocument subsetStandaloneDocument;
    subsetStandaloneDocument.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("carrier", "talas.oscillator", {
            {"frequency", "440 hz"}, {"amplitude", "0.25"}}),
        node("table", "talas.triggeredTableRead", {
            {"trigger", "1"},
            resourceParameter("wavetable", "Tables/Steps"),
            {"gate", "1"},
            booleanParameter("ignoreLoops", false),
            booleanParameter("fromMemoryWriter", false),
        }),
    };
    subsetStandaloneDocument.graph.connections = {
        connection("table", "value", "carrier", "frequency"),
        connection("carrier", "audioOut", "out", "audioIn"),
    };
    const auto subsetStandalone = talas::runtime::compileProject(
        subsetStandaloneDocument, subsetRegistry, settings);
    require(subsetStandalone.ok(),
        "C154 unsealed custom Subset metadata fixture should compile");
    const auto publicSubsetStandalone =
        makePublicCompatibilityGraphWithSubsetOscillators(
            *subsetStandalone.graph);
    talas::runtime::RealtimeRenderSession unsealedSubsetBaseline{
        publicSubsetStandalone};
    require(unsealedSubsetBaseline.ready(),
        "C154 unsealed custom Subset baseline should reach per-node admission without compiler seals: "
            + std::string{unsealedSubsetBaseline.error()});

    const auto expectMalformedSubsetSnapshotRejected =
        [&](auto mutate, std::string_view contract) {
            auto malformedSubsetSettings =
                subsetStandalone.graph->renderSettings();
            auto malformedSubsetSnapshot =
                std::make_shared<talas::core::ResourceSnapshot>(
                    *malformedSubsetSettings.resourceSnapshots.front());
            mutate(*malformedSubsetSnapshot);
            malformedSubsetSettings.resourceSnapshots.front() =
                std::move(malformedSubsetSnapshot);
            talas::runtime::RealtimeRenderSession malformedSubsetSession{
                talas::runtime::PreparedRuntimeGraph{
                    publicSubsetStandalone.plan(),
                    std::move(malformedSubsetSettings)}};
            require(!malformedSubsetSession.ready(),
                "C154 prepared Subset compatibility should reject Table snapshot "
                    + std::string{contract}
                    + " without relying on a compiler seal");
        };
    expectMalformedSubsetSnapshotRejected(
        [](auto& snapshot) { snapshot.channelCount = 2; },
        "multichannel metadata");
    expectMalformedSubsetSnapshotRejected(
        [](auto& snapshot) { snapshot.sampleRate = 48'000.0; },
        "sample-rate metadata");
    expectMalformedSubsetSnapshotRejected(
        [](auto& snapshot) { snapshot.sampleRate = -0.0; },
        "negative-zero sample-rate metadata");
    expectMalformedSubsetSnapshotRejected(
        [](auto& snapshot) { snapshot.frameCount = 3; },
        "frame-count metadata");
    expectMalformedSubsetSnapshotRejected(
        [](auto& snapshot) { snapshot.encoding = "pcm16-wav"; },
        "encoding metadata");

    auto mixedSupportRegistry = talas::core::makeBuiltinNodeRegistry();
    mixedSupportRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.triggeredTableRead",
        talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto mixedSupport = talas::runtime::compileProject(
        document, mixedSupportRegistry, settings);
    require(mixedSupport.ok(),
        "C154 mixed-support Triggered Table Read fixture should compile before admission rejection");
    talas::runtime::RealtimeRenderSession mixedSupportSession{
        *mixedSupport.graph};
    const auto mixedSupportOffline = talas::runtime::renderOffline(
        *mixedSupport.graph, 4);
    require(!mixedSupportSession.ready()
            && !mixedSupportOffline.ok()
            && mixedSupportOffline.mono.empty(),
        "C154 offline Supported authority should reject a mixed-support descriptor that did not mint the exact built-in seal");

    auto divergentRegistry = talas::core::makeBuiltinNodeRegistry();
    divergentRegistry.setNodeTypeFanInLatencyPolicy(
        "talas.triggeredTableRead",
        talas::core::FanInLatencyPolicy::PreserveRelative);
    const auto divergent = talas::runtime::compileProject(
        document, divergentRegistry, settings);
    require(divergent.ok(),
        "C154 coherent divergent Triggered Table Read fixture should compile");
    talas::runtime::RealtimeRenderSession divergentSession{
        *divergent.graph};
    const auto divergentOffline = talas::runtime::renderOffline(
        *divergent.graph, 4);
    require(!divergentSession.ready() && !divergentOffline.ok()
            && divergentOffline.mono.empty(),
        "C154 coherent divergent Supported descriptor should not mint built-in authority");

    auto statefulDocument = document;
    const auto statefulTable = std::ranges::find(
        statefulDocument.graph.nodes,
        std::string_view{"table"},
        &talas::project::ProjectNode::instanceId);
    require(statefulTable != statefulDocument.graph.nodes.end(),
        "C154 stateful fixture should expose Triggered Table Read");
    statefulTable->parameters[0].expression = "previous(0, 0)";
    const auto stateful = talas::runtime::compileProject(
        statefulDocument,
        talas::core::makeBuiltinNodeRegistry(), settings);
    require(stateful.ok(),
        "C154 stateful direct fixture should compile before promoted admission rejection");
    talas::runtime::RealtimeRenderSession statefulSession{*stateful.graph};
    const auto statefulOffline = talas::runtime::renderOffline(
        *stateful.graph, 4);
    require(!statefulSession.ready() && !statefulOffline.ok()
            && statefulOffline.mono.empty(),
        "C154 promoted Triggered Table Read should reject stateful direct control authority");

    for (const auto port : {std::string_view{"trigger"},
             std::string_view{"gate"}})
    {
        for (const auto& invalidFallback : {
                 std::string{"440 hz"},
                 std::string{"!C154MissingControl"}})
        {
            auto invalidDocument = document;
            const auto table = std::ranges::find(
                invalidDocument.graph.nodes,
                std::string_view{"table"},
                &talas::project::ProjectNode::instanceId);
            require(table != invalidDocument.graph.nodes.end(),
                "C154 connected-invalid fixture should expose Triggered Table Read");
            const auto parameter = std::ranges::find(
                table->parameters, port,
                &talas::project::ProjectParameterExpression::parameterId);
            require(parameter != table->parameters.end(),
                "C154 connected-invalid fixture should expose selected fallback");
            parameter->expression = invalidFallback;
            const auto sourceId = std::string{"connected"}
                + std::string{port};
            invalidDocument.graph.nodes.push_back(node(
                sourceId, "talas.constant", {{"value", "1"}}));
            invalidDocument.graph.connections.push_back(connection(
                sourceId, "value", "table", std::string{port}));
            const auto invalid = talas::runtime::compileProject(
                invalidDocument,
                talas::core::makeBuiltinNodeRegistry(), settings);
            require(!invalid.ok(),
                "C154 connected precedence should not hide wrong-domain or unresolved fallback authority");
        }

        auto hiddenDocument = document;
        const auto table = std::ranges::find(
            hiddenDocument.graph.nodes,
            std::string_view{"table"},
            &talas::project::ProjectNode::instanceId);
        const auto parameter = std::ranges::find(
            table->parameters, port,
            &talas::project::ProjectParameterExpression::parameterId);
        parameter->expression = "1e200 * 1e200";
        const auto sourceId = std::string{"connected"}
            + std::string{port};
        hiddenDocument.graph.nodes.push_back(node(
            sourceId, "talas.constant", {{"value", "1"}}));
        hiddenDocument.graph.connections.push_back(connection(
            sourceId, "value", "table", std::string{port}));
        const auto hidden = talas::runtime::compileProject(
            hiddenDocument,
            talas::core::makeBuiltinNodeRegistry(), settings);
        require(hidden.ok(),
            "C154 connected precedence should hide exactly one bounded non-finite fallback result");
        talas::runtime::RealtimeRenderSession hiddenSession{*hidden.graph};
        const auto hiddenOffline = talas::runtime::renderOffline(
            *hidden.graph, 4);
        std::array<double, 4> hiddenPrepared{};
        std::size_t allocations = 0;
        require(hiddenSession.ready()
                && hiddenOffline.ok()
                && renderAndCount(
                    hiddenSession, hiddenPrepared, allocations)
                && allocations == 0
                && std::ranges::equal(
                    hiddenPrepared, hiddenOffline.mono),
            "C154 independently connected controls should override their own hidden non-finite fallback offline and prepared");
    }

    auto forgedPlan = exact;
    const auto forgedTable = std::ranges::find(
        mutablePlanForTest(forgedPlan).steps,
        std::string_view{"talas.triggeredTableRead"},
        &talas::runtime::CompileStep::typeId);
    require(forgedTable != mutablePlanForTest(forgedPlan).steps.end(),
        "C154 sealed-plan fixture should expose Triggered Table Read");
    forgedTable->supportsReset = false;
    talas::runtime::RealtimeRenderSession forgedPlanSession{forgedPlan};
    const auto forgedPlanOffline = talas::runtime::renderOffline(
        forgedPlan, 4);
    require(!forgedPlanSession.ready() && !forgedPlanOffline.ok()
            && forgedPlanOffline.mono.empty(),
        "C154 sealed plan mutation should reject offline and prepared");

    auto forgedSettings = exact;
    ++mutableSettingsForTest(forgedSettings).maxBlockFrames;
    talas::runtime::RealtimeRenderSession forgedSettingsSession{
        forgedSettings};
    const auto forgedSettingsOffline = talas::runtime::renderOffline(
        forgedSettings, 4);
    require(!forgedSettingsSession.ready()
            && !forgedSettingsOffline.ok()
            && forgedSettingsOffline.mono.empty(),
        "C154 sealed settings mutation should reject offline and prepared");

    auto forgedResources = exact;
    mutableSettingsForTest(forgedResources)
        .tableResources.front().samples.front() = 99.0;
    talas::runtime::RealtimeRenderSession forgedResourceSession{
        forgedResources};
    const auto forgedResourceOffline = talas::runtime::renderOffline(
        forgedResources, 4);
    require(!forgedResourceSession.ready()
            && !forgedResourceOffline.ok()
            && forgedResourceOffline.mono.empty(),
        "C154 sealed immutable-resource mutation should reject offline and prepared");
}

void testRealtimeTriggeredTableReadDirectControlsResetRollbackAndAuthority()
{
    auto document = makeTriggeredTableReadVcaDocument({
        {"trigger", "!TableTrigger"},
        resourceParameter("wavetable", "Tables/Steps"),
        {"gate", "!TableGate"},
        booleanParameter("ignoreLoops", true),
        booleanParameter("fromMemoryWriter", false),
    });
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C71Downstream"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    std::erase_if(
        document.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });
    document.graph.connections.push_back(connection(
        "vca", "audioOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.eventValues = {
        {"TableTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        {"TableGate", 0.0, talas::expr::ValueDomain::Scalar},
        {"C71Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.tableResources.push_back(
        {"Tables/Steps", {2.0, 3.0, 4.0, 5.0}});
    const auto graph = compile(document, settings);

    talas::runtime::RealtimeRenderSession resetCandidate(graph);
    talas::runtime::RealtimeRenderSession pristine(graph);
    require(
        resetCandidate.ready() && pristine.ready(),
        "C71 prepared runtime should accept direct Event Value trigger and gate controls");
    std::array<double, 2> ignored{};
    std::size_t allocations = 0;
    require(
        renderAndCount(resetCandidate, ignored, allocations)
            && allocations == 0,
        "C71 reset fixture should advance the table without allocation");
    resetCandidate.resetTransport();
    std::array<double, 2> resetOutput{};
    std::array<double, 2> pristineOutput{};
    require(
        renderAndCount(resetCandidate, resetOutput, allocations)
            && allocations == 0
            && renderAndCount(pristine, pristineOutput, allocations)
            && allocations == 0
            && resetOutput == pristineOutput,
        "C71 transport reset should clear cursor, held sample, and gate polarity");

    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(
        candidate.ready() && reference.ready()
            && candidate.scheduleEventValue(
                "TableGate", 1.0,
                talas::expr::ValueDomain::Scalar, 3)
            && candidate.scheduleEventValue(
                "C71Downstream", std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar, 3),
        "C71 rollback fixture should schedule a late gate reset and downstream failure");
    std::array<double, 4> rejected{1.0, 1.0, 1.0, 1.0};
    require(
        !renderAndCount(candidate, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 4>{},
        "C71 downstream failure should reject the whole callback without allocation");
    require(
        candidate.updateEventValue(
            "TableTrigger", 0.0,
            talas::expr::ValueDomain::Scalar)
            && candidate.updateEventValue(
                "TableGate", 1.0,
                talas::expr::ValueDomain::Scalar)
            && candidate.updateEventValue(
                "C71Downstream", 1.0,
                talas::expr::ValueDomain::Scalar)
            && reference.updateEventValue(
                "TableTrigger", 0.0,
                talas::expr::ValueDomain::Scalar)
            && reference.updateEventValue(
                "TableGate", 1.0,
                talas::expr::ValueDomain::Scalar),
        "C71 failed callback should permit a matching valid control retry");
    std::array<double, 4> retry{};
    std::array<double, 4> expected{};
    require(
        renderAndCount(candidate, retry, allocations)
            && allocations == 0
            && renderAndCount(reference, expected, allocations)
            && allocations == 0
            && retry == expected,
        "C71 failed callback should restore cursor, held sample, gate polarity, scheduler, and predecessors");

    const auto verifySeededRollback =
        [&](double retryTrigger,
            double retryGate,
            bool changeGateDuringFailure,
            std::string_view contract) {
            talas::runtime::RealtimeRenderSession seededCandidate(graph);
            talas::runtime::RealtimeRenderSession seededReference(graph);
            std::array<double, 1> candidateSeed{};
            std::array<double, 1> referenceSeed{};
            require(
                seededCandidate.ready() && seededReference.ready()
                    && renderAndCount(
                        seededCandidate, candidateSeed, allocations)
                    && allocations == 0
                    && renderAndCount(
                        seededReference, referenceSeed, allocations)
                    && allocations == 0
                    && candidateSeed == referenceSeed,
                "C71 seeded rollback fixtures should establish index one, held first sample, and non-positive Gate polarity");
            require(
                (!changeGateDuringFailure
                    || seededCandidate.scheduleEventValue(
                        "TableGate", 1.0,
                        talas::expr::ValueDomain::Scalar, 3))
                    && seededCandidate.scheduleEventValue(
                        "C71Downstream",
                        std::numeric_limits<double>::max(),
                        talas::expr::ValueDomain::Scalar, 3),
                "C71 seeded rollback fixture should schedule a late downstream rejection");
            std::array<double, 4> seededRejected{
                1.0, 1.0, 1.0, 1.0};
            require(
                !renderAndCount(
                    seededCandidate, seededRejected, allocations)
                    && allocations == 0
                    && seededRejected == std::array<double, 4>{},
                "C71 seeded late failure should publish no callback audio");
            require(
                seededCandidate.updateEventValue(
                    "TableTrigger", retryTrigger,
                    talas::expr::ValueDomain::Scalar)
                    && seededCandidate.updateEventValue(
                        "TableGate", retryGate,
                        talas::expr::ValueDomain::Scalar)
                    && seededCandidate.updateEventValue(
                        "C71Downstream", 1.0,
                        talas::expr::ValueDomain::Scalar)
                    && seededReference.updateEventValue(
                        "TableTrigger", retryTrigger,
                        talas::expr::ValueDomain::Scalar)
                    && seededReference.updateEventValue(
                        "TableGate", retryGate,
                        talas::expr::ValueDomain::Scalar),
                "C71 seeded rollback should accept matching retry controls");
            std::array<double, 4> seededRetry{};
            std::array<double, 4> seededExpected{};
            require(
                renderAndCount(
                    seededCandidate, seededRetry, allocations)
                    && allocations == 0
                    && renderAndCount(
                        seededReference, seededExpected, allocations)
                    && allocations == 0
                    && seededRetry == seededExpected,
                "C71 seeded failure should independently restore "
                    + std::string{contract});
        };
    verifySeededRollback(
        1.0, 0.0, false,
        "the table cursor before the next read");
    verifySeededRollback(
        0.0, 0.0, false,
        "the held sample while Trigger remains closed");
    verifySeededRollback(
        0.0, 1.0, true,
        "the prior-Gate polarity before a retry reset edge");

    const auto expectForgedRejected =
        [&](auto mutate, std::string_view contract) {
            auto forgedGraph = graph;
            auto& forgedPlan = mutablePlanForTest(forgedGraph);
            const auto table = std::ranges::find(
                forgedPlan.steps,
                std::string_view{"talas.triggeredTableRead"},
                &talas::runtime::CompileStep::typeId);
            require(table != forgedPlan.steps.end(),
                "C71 forged-authority fixture should expose Triggered Table Read");
            mutate(*table);
            talas::runtime::RealtimeRenderSession forged{forgedGraph};
            require(!forged.ready(),
                "C71 prepared Triggered Table Read should reject forged "
                    + std::string{contract});
        };
    expectForgedRejected(
        [](auto& step) { step.supportsReset = false; },
        "reset authority");
    expectForgedRejected(
        [](auto& step) {
            const auto wavetable = std::ranges::find(
                step.parameters, std::string_view{"wavetable"},
                &talas::runtime::ParameterValue::id);
            require(wavetable != step.parameters.end(),
                "C71 forged resource fixture should expose wavetable authority");
            wavetable->id = "forgedWavetable";
        },
        "resource authority");
    expectForgedRejected(
        [](auto& step) {
            step.parameters.front().expression.reset();
        },
        "parameter expression authority");
    expectForgedRejected(
        [](auto& step) {
            step.parameters.push_back(step.parameters.front());
        },
        "duplicate parameter authority");
    expectForgedRejected(
        [](auto& step) {
            step.offlineSupport =
                talas::core::ExecutionSupport::Subset;
        },
        "offline support authority");
    expectForgedRejected(
        [](auto& step) {
            step.preparedRealtimeBinding =
                talas::core::ExecutionBinding::None;
        },
        "prepared binding authority");
    expectForgedRejected(
        [](auto& step) { ++step.eventValueScopeId; },
        "Event Value scope authority");
    expectForgedRejected(
        [](auto& step) {
            step.kernelKind = talas::runtime::KernelKind::Clock;
        },
        "kernel authority");
    expectForgedRejected(
        [](auto& step) {
            step.parameters.front().domain =
                talas::expr::ValueDomain::Hertz;
        },
        "parameter domain authority");
    expectForgedRejected(
        [](auto& step) {
            std::swap(step.parameters[0], step.parameters[1]);
        },
        "parameter order authority");
    expectForgedRejected(
        [](auto& step) {
            step.parameters[1].resource.reset();
        },
        "wavetable parameter kind authority");
    expectForgedRejected(
        [](auto& step) {
            step.parameters[3].boolean.reset();
        },
        "Boolean parameter kind authority");
    expectForgedRejected(
        [](auto& step) {
            step.resolvedLatencyFrames.reset();
        },
        "resolved latency authority");
    expectForgedRejected(
        [](auto& step) {
            step.cumulativeInputLatencyFrames = 1;
        },
        "cumulative input latency authority");
    expectForgedRejected(
        [](auto& step) {
            step.cumulativeOutputLatencyFrames = 1;
        },
        "cumulative output latency authority");
    expectForgedRejected(
        [](auto& step) {
            step.preparedSpectralFrameSize = 64;
        },
        "spectral authority");
    expectForgedRejected(
        [](auto& step) {
            step.soundVariableCellIndex = 0;
        },
        "Sound Variable authority");

    auto connectedAuthorityDocument =
        makeTriggeredTableReadVcaDocument({
            {"trigger", "!TableTrigger"},
            resourceParameter("wavetable", "Tables/Steps"),
            {"gate", "!TableGate"},
            booleanParameter("ignoreLoops", true),
            booleanParameter("fromMemoryWriter", false),
        });
    connectedAuthorityDocument.graph.nodes.push_back(node(
        "connectedTrigger", "talas.constant", {{"value", "1"}}));
    connectedAuthorityDocument.graph.nodes.push_back(node(
        "connectedGate", "talas.constant", {{"value", "0"}}));
    connectedAuthorityDocument.graph.connections.push_back(connection(
        "connectedTrigger", "value", "table", "trigger"));
    connectedAuthorityDocument.graph.connections.push_back(connection(
        "connectedGate", "value", "table", "gate"));
    auto connectedAuthoritySettings =
        talas::runtime::RenderSettings{4.0, 4};
    connectedAuthoritySettings.eventValues = {
        {"TableTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        {"TableGate", 0.0, talas::expr::ValueDomain::Scalar},
    };
    connectedAuthoritySettings.tableResources.push_back(
        {"Tables/Steps", {1.0, 2.0, 3.0, 4.0}});
    const auto connectedAuthorityGraph = compile(
        connectedAuthorityDocument, connectedAuthoritySettings);
    const auto expectConnectedPlanRejected =
        [&](auto mutate, std::string_view contract) {
            auto forgedGraph = connectedAuthorityGraph;
            auto& forgedPlan = mutablePlanForTest(forgedGraph);
            const auto table = std::ranges::find(
                forgedPlan.steps,
                std::string_view{"talas.triggeredTableRead"},
                &talas::runtime::CompileStep::typeId);
            require(table != forgedPlan.steps.end(),
                "C71 connected forged fixture should expose Triggered Table Read");
            mutate(*table, forgedPlan);
            talas::runtime::RealtimeRenderSession forged{forgedGraph};
            require(!forged.ready(),
                "C71 prepared Triggered Table Read should reject forged "
                    + std::string{contract});
        };
    expectConnectedPlanRejected(
        [](auto& step, auto&) {
            step.inputs.push_back(step.inputs.front());
            step.inputLatencyFrames.push_back(
                step.inputLatencyFrames.front());
        },
        "duplicate input authority");
    expectConnectedPlanRejected(
        [](auto& step, auto&) {
            require(step.inputs.size() == 2
                    && step.inputLatencyFrames.size() == 2,
                "C71 reordered fixture should expose Trigger and Gate inputs");
            std::swap(step.inputs[0], step.inputs[1]);
            std::swap(
                step.inputLatencyFrames[0],
                step.inputLatencyFrames[1]);
        },
        "input order authority");
    expectConnectedPlanRejected(
        [](auto& step, auto&) {
            step.inputs.front().inputPortId = "unknown";
        },
        "unknown input authority");
    expectConnectedPlanRejected(
        [](auto& step, auto&) {
            step.inputLatencyFrames.front() = 0;
        },
        "input latency authority");
    expectConnectedPlanRejected(
        [](auto& step, auto& plan) {
            const auto trigger = std::ranges::find(
                step.inputs, std::string_view{"trigger"},
                &talas::runtime::InputBinding::inputPortId);
            require(trigger != step.inputs.end()
                    && trigger->bufferIndex < plan.buffers.size(),
                "C71 unproduced fixture should expose Trigger buffer");
            auto unproduced = plan.buffers[trigger->bufferIndex];
            unproduced.nodeId += "Unproduced";
            trigger->sourceNodeId = unproduced.nodeId;
            trigger->bufferIndex = plan.buffers.size();
            plan.buffers.push_back(std::move(unproduced));
        },
        "self-consistent unproduced input buffer");
    expectConnectedPlanRejected(
        [](auto& step, auto& plan) {
            const auto trigger = std::ranges::find(
                step.inputs, std::string_view{"trigger"},
                &talas::runtime::InputBinding::inputPortId);
            require(trigger != step.inputs.end(),
                "C71 duplicate-producer fixture should expose Trigger input");
            const auto source = std::ranges::find(
                plan.steps, trigger->sourceNodeId,
                &talas::runtime::CompileStep::nodeId);
            require(source != plan.steps.end(),
                "C71 duplicate-producer fixture should expose source step");
            plan.steps.push_back(*source);
        },
        "multiply defined input producer identity");
    expectConnectedPlanRejected(
        [](auto& step, auto& plan) {
            const auto trigger = std::ranges::find(
                step.inputs, std::string_view{"trigger"},
                &talas::runtime::InputBinding::inputPortId);
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const auto& buffer) {
                    return buffer.nodeId == step.nodeId
                        && buffer.scopeId == step.scopeId
                        && buffer.portId == "value"
                        && buffer.type == talas::core::PortType::Control;
                });
            require(trigger != step.inputs.end()
                    && output != plan.buffers.end(),
                "C71 alias fixture should expose Trigger input and output");
            trigger->sourceNodeId = output->nodeId;
            trigger->sourcePortId = output->portId;
            trigger->sourceScopeId = output->scopeId;
            trigger->bufferIndex = static_cast<std::size_t>(
                std::distance(plan.buffers.begin(), output));
        },
        "aliased input and output buffer");
    expectConnectedPlanRejected(
        [](auto& step, auto& plan) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const auto& buffer) {
                    return buffer.nodeId == step.nodeId
                        && buffer.scopeId == step.scopeId
                        && buffer.portId == "value"
                        && buffer.type == talas::core::PortType::Control;
                });
            require(output != plan.buffers.end(),
                "C71 duplicate-output fixture should expose output buffer");
            plan.buffers.push_back(*output);
        },
        "duplicate output buffer");
    expectConnectedPlanRejected(
        [](auto& step, auto& plan) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const auto& buffer) {
                    return buffer.nodeId == step.nodeId
                        && buffer.scopeId == step.scopeId
                        && buffer.portId == "value"
                        && buffer.type == talas::core::PortType::Control;
                });
            require(output != plan.buffers.end(),
                "C71 output-capacity fixture should expose output buffer");
            ++output->frames;
        },
        "output frame authority");

    auto duplicateResourceGraph = connectedAuthorityGraph;
    auto& duplicateResourceSettings =
        mutableSettingsForTest(duplicateResourceGraph);
    duplicateResourceSettings.tableResources.push_back(
        duplicateResourceSettings.tableResources.front());
    talas::runtime::RealtimeRenderSession duplicateResource{
        duplicateResourceGraph};
    require(!duplicateResource.ready(),
        "C71 prepared Triggered Table Read should reject duplicate immutable resource identity");

    const auto expectForgedResourceSettingsRejected =
        [&](auto mutate, std::string_view contract) {
            auto forgedGraph = graph;
            auto& forgedSettings = mutableSettingsForTest(forgedGraph);
            require(
                forgedSettings.tableResources.size() == 1
                    && forgedSettings.resourceSnapshots.size() == 1
                    && forgedSettings.resourceSnapshots.front() != nullptr,
                "C71 immutable-resource fixture should expose one compatibility table and one snapshot");
            mutate(forgedSettings);
            talas::runtime::RealtimeRenderSession forged{forgedGraph};
            require(!forged.ready(),
                "C71 prepared Triggered Table Read should reject forged "
                    + std::string{contract});
        };
    expectForgedResourceSettingsRejected(
        [](auto& forgedSettings) {
            forgedSettings.tableResources.front().samples.front() = 99.0;
        },
        "compatibility table payload that differs from its immutable snapshot");
    expectForgedResourceSettingsRejected(
        [](auto& forgedSettings) {
            auto forgedSnapshot = std::make_shared<talas::core::ResourceSnapshot>(
                *forgedSettings.resourceSnapshots.front());
            forgedSnapshot->kind = talas::core::ResourceSnapshotKind::Binary;
            forgedSnapshot->binaryBytes = {1};
            forgedSnapshot->tableSamples.clear();
            forgedSettings.resourceSnapshots.front() =
                std::move(forgedSnapshot);
        },
        "non-table snapshot kind");
    expectForgedResourceSettingsRejected(
        [](auto& forgedSettings) {
            auto forgedSnapshot = std::make_shared<talas::core::ResourceSnapshot>(
                *forgedSettings.resourceSnapshots.front());
            forgedSnapshot->generation = 1;
            forgedSnapshot->contentHash = "not-a-canonical-sha256";
            forgedSettings.resourceSnapshots.front() =
                std::move(forgedSnapshot);
        },
        "snapshot generation/hash shape");
    expectForgedResourceSettingsRejected(
        [](auto& forgedSettings) {
            forgedSettings.resourceSnapshots.front().reset();
        },
        "null snapshot authority");
    expectForgedResourceSettingsRejected(
        [](auto& forgedSettings) {
            forgedSettings.resourceSnapshots.push_back(
                forgedSettings.resourceSnapshots.front());
        },
        "duplicate snapshot identity");
}

void testRealtimeSessionRendersFunctionGeneratorAcrossBlocksWithoutAllocations()
{
    talas::runtime::RenderSettings settings{4.0, 2};
    settings.tableResources.push_back({"Tables/Envelope", {0.0, 1.0, 0.0}});
    auto graph = compile(makeFunctionGeneratorVcaDocument(), std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 2> first{};
    std::array<double, 2> second{};
    std::array<double, 2> third{};
    std::size_t allocations = 0;
    require(renderAndCount(session, first, allocations), "first Function Generator block should render");
    require(allocations == 0, "first Function Generator block should not allocate");
    require(renderAndCount(session, second, allocations), "second Function Generator block should render");
    require(allocations == 0, "second Function Generator block should not allocate");
    require(renderAndCount(session, third, allocations), "third Function Generator block should render");
    require(allocations == 0, "third Function Generator block should not allocate");

    requireNear(first[0], 0.0, 1.0e-12, "Function Generator table start");
    requireNear(first[1], 0.1913417161825449, 1.0e-12, "Function Generator linear table interpolation");
    requireNear(second[0], 0.7071067811865475, 1.0e-12, "Function Generator table peak across blocks");
    requireNear(second[1], 0.46193976625564337, 1.0e-12, "Function Generator table descent across blocks");
    requireNear(third[0], 0.0, 1.0e-12, "Function Generator should become silent at onDuration");
    requireNear(third[1], 0.0, 1.0e-12, "Function Generator should stay silent after onDuration");
}

void testFunctionGeneratorLevelSoundFollowsEachSample()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("input", "talas.audioInput"),
        node("carrier", "talas.oscillator", {
            {"frequency", "0.25 hz"}, {"amplitude", "1"}}),
        node("function", "talas.functionGenerator", {
            {"trigger", "1"},
            {"onDuration", "1 s"},
            {"level", "0.125"},
            resourceParameter("wavetable", "Tables/Envelope"),
            booleanParameter("fromMemoryWriter", false),
        }),
        node("vca", "talas.vca"),
    };
    document.graph.connections = {
        connection("input", "audioOut", "function", "level"),
        connection("carrier", "audioOut", "vca", "audioIn"),
        connection("function", "value", "vca", "gain"),
        connection("vca", "audioOut", "out", "audioIn"),
    };
    const auto saved = talas::project::serializeProjectDocument(
        document, talas::core::makeBuiltinNodeRegistry());
    const auto reopened = talas::project::parseProjectDocument(saved);
    require(reopened.ok()
            && talas::project::serializeProjectDocument(
                   reopened.document,
                   talas::core::makeBuiltinNodeRegistry()) == saved,
        "FunctionGenerator Level Sound should save and reopen byte-stably");

    constexpr std::array<float, 6> levels{2.0F, -1.0F, 0.5F, 1.0F, -2.0F, 3.0F};
    talas::runtime::RenderSettings settings{4.0, levels.size()};
    settings.tableResources.push_back({"Tables/Envelope", {0.0, 1.0, 0.0}});
    settings.audioInputChannels = {{1, std::vector<double>(
        levels.begin(), levels.end())}};
    const auto graph = compile(reopened.document, settings);
    const auto offline = talas::runtime::renderOffline(graph, levels.size());
    require(offline.ok() && offline.mono.size() == levels.size(),
        "FunctionGenerator connected Level Sound should render offline");
    const std::array<double, 6> tableValues{0.0, 0.5, 1.0, 0.5, 0.0, 0.0};
    for (std::size_t frame = 0; frame < levels.size(); ++frame)
    {
        const auto expected = std::sin(std::numbers::pi * frame / 8.0)
            * tableValues[frame] * levels[frame];
        requireNear(offline.mono[frame], expected, 1.0e-12,
            "FunctionGenerator connected Level should multiply each sample and override scalar fallback");
    }

    talas::runtime::OfflineRenderSession partitioned(graph);
    const auto first = partitioned.render(1);
    const auto middle = partitioned.render(3);
    const auto last = partitioned.render(2);
    require(first.ok() && middle.ok() && last.ok(),
        "FunctionGenerator Level Sound should render across unequal offline partitions");
    for (std::size_t frame = 0; frame < levels.size(); ++frame)
    {
        const auto actual = frame == 0 ? first.mono[0]
            : frame < 4 ? middle.mono[frame - 1]
            : last.mono[frame - 4];
        requireNear(actual, offline.mono[frame], 1.0e-12,
            "FunctionGenerator Level Sound should preserve offline partition continuity");
    }

    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(),
        "FunctionGenerator Level Sound should prepare realtime: "
            + std::string{session.error()});
    std::array<double, levels.size()> prepared{};
    std::size_t offset = 0;
    for (const auto partition : {std::size_t{3}, std::size_t{1}, std::size_t{2}})
    {
        std::array<const float*, 1> channels{levels.data() + offset};
        std::size_t allocations = 0;
        require(renderMonoInputAndCount(
                    session,
                    {channels.data(), channels.size()},
                    std::span<double>(prepared).subspan(offset, partition),
                    allocations)
                && allocations == 0,
            "FunctionGenerator Level Sound prepared callback should render without allocation");
        offset += partition;
    }
    for (std::size_t frame = 0; frame < levels.size(); ++frame)
        requireNear(prepared[frame], offline.mono[frame], 1.0e-12,
            "FunctionGenerator Level Sound prepared output should match offline");
}

void testFunctionGeneratorAcceptsHistoricOnDurationUnits()
{
    const auto makeGraph = [](std::string_view duration) {
        const auto document = makeFunctionGeneratorVcaDocument({
            {"trigger", "1"},
            {"onDuration", std::string{duration}},
            resourceParameter("wavetable", "Tables/Envelope"),
            booleanParameter("fromMemoryWriter", false),
        });
        const auto saved = talas::project::serializeProjectDocument(
            document, talas::core::makeBuiltinNodeRegistry());
        const auto reopened = talas::project::parseProjectDocument(saved);
        require(reopened.ok(),
            "FunctionGenerator historic duration should save and reopen");
        talas::runtime::RenderSettings settings{4.0, 2};
        settings.tableResources.push_back(
            {"Tables/Envelope", {0.0, 1.0, 0.0}});
        return compile(reopened.document, settings);
    };
    const auto reference = talas::runtime::renderOffline(
        makeGraph("500 ms"), 4);
    require(reference.ok() && reference.mono.size() == 4
            && reference.mono[1] > 0.0
            && reference.mono[2] == 0.0,
        "FunctionGenerator half-second reference should render one event");

    for (const auto duration : {std::string_view{"2 samp"},
             std::string_view{"1 / 2 hz"},
             std::string_view{"500000 usec"}})
    {
        const auto graph = makeGraph(duration);
        const auto offline = talas::runtime::renderOffline(graph, 4);
        require(offline.ok() && offline.mono.size() == 4,
            "FunctionGenerator should accept a documented OnDuration unit form offline");
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(),
            "FunctionGenerator should prepare a documented OnDuration unit form: "
                + std::string{session.error()});
        std::array<double, 4> prepared{};
        std::size_t allocations = 0;
        require(renderAndCount(session,
                    std::span<double>{prepared}.first(2), allocations)
                && allocations == 0
                && renderAndCount(session,
                    std::span<double>{prepared}.last(2), allocations)
                && allocations == 0,
            "FunctionGenerator historic units should render without prepared callback allocations");
        for (std::size_t frame = 0; frame < prepared.size(); ++frame)
        {
            requireNear(offline.mono[frame], reference.mono[frame], 1.0e-12,
                "FunctionGenerator historic duration should match millisecond reference offline");
            requireNear(prepared[frame], reference.mono[frame], 1.0e-12,
                "FunctionGenerator historic duration should match reference prepared");
        }
    }
}

void testRealtimeFunctionGeneratorPairedSchedulesMatchOfflinePartitions()
{
    const auto document = makeFunctionGeneratorVcaDocument({
        {"trigger", "!FunctionTrigger"},
        {"onDuration", "!FunctionDuration"},
        resourceParameter("wavetable", "Tables/Envelope"),
        booleanParameter("fromMemoryWriter", false),
    });
    auto preparedSettings = talas::runtime::RenderSettings{4.0, 8};
    preparedSettings.eventValues = {
        {"FunctionTrigger", 0.0, talas::expr::ValueDomain::Scalar},
        {"FunctionDuration", 1.0, talas::expr::ValueDomain::Seconds},
    };
    preparedSettings.tableResources.push_back(
        {"Tables/Envelope", {0.0, 1.0, 0.0}});
    auto offlineSettings = preparedSettings;
    offlineSettings.eventValueChanges = {
        {1, "FunctionTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        {2, "FunctionTrigger", -0.0, talas::expr::ValueDomain::Scalar},
        {3, "FunctionDuration", 0.5, talas::expr::ValueDomain::Seconds},
        {4, "FunctionDuration", 1.0, talas::expr::ValueDomain::Seconds},
        {5, "FunctionDuration", 0.5, talas::expr::ValueDomain::Seconds},
        {5, "FunctionTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        {6, "FunctionTrigger", 0.0, talas::expr::ValueDomain::Scalar},
        {7, "FunctionDuration", 0.25, talas::expr::ValueDomain::Seconds},
    };

    const auto offlineGraph = compile(document, offlineSettings);
    const auto preparedGraph = compile(document, preparedSettings);
    const auto offline = talas::runtime::renderOffline(offlineGraph, 8);
    require(offline.ok() && offline.mono.size() == 8
            && offline.mono[2] != 0.0
            && offline.mono[4] != 0.0
            && offline.mono[6] != 0.0,
        "C155 paired Function Generator schedules should render offline");

    const auto renderPrepared = [&](bool singleFrame) {
        talas::runtime::RealtimeRenderSession session{preparedGraph};
        require(session.ready(),
            "C155 paired Function Generator schedules should prepare: "
                + std::string{session.error()});
        require(
            session.scheduleEventValue(
                "FunctionTrigger", 1.0,
                talas::expr::ValueDomain::Scalar, 1)
                && session.scheduleEventValue(
                    "FunctionTrigger", -0.0,
                    talas::expr::ValueDomain::Scalar, 2)
                && session.scheduleEventValue(
                    "FunctionDuration", 0.5,
                    talas::expr::ValueDomain::Seconds, 3)
                && session.scheduleEventValue(
                    "FunctionDuration", 1.0,
                    talas::expr::ValueDomain::Seconds, 4)
                && session.scheduleEventValue(
                    "FunctionDuration", 0.5,
                    talas::expr::ValueDomain::Seconds, 5)
                && session.scheduleEventValue(
                    "FunctionTrigger", 1.0,
                    talas::expr::ValueDomain::Scalar, 5)
                && session.scheduleEventValue(
                    "FunctionTrigger", 0.0,
                    talas::expr::ValueDomain::Scalar, 6)
                && session.scheduleEventValue(
                    "FunctionDuration", 0.25,
                    talas::expr::ValueDomain::Seconds, 7),
            "C155 prepared Function Generator should accept paired direct schedules");
        std::array<double, 8> actual{};
        std::size_t allocations = 0;
        if (singleFrame)
        {
            for (std::size_t frame = 0; frame < actual.size(); ++frame)
            {
                require(
                    renderAndCount(
                        session,
                        std::span<double>{actual}.subspan(frame, 1),
                        allocations)
                        && allocations == 0,
                    "C155 single-frame paired schedule callback should render without allocation");
            }
        }
        else
        {
            require(
                renderAndCount(
                    session, std::span<double>{actual}.first(1),
                    allocations)
                    && allocations == 0
                    && renderAndCount(
                        session,
                        std::span<double>{actual}.subspan(1, 2),
                        allocations)
                    && allocations == 0
                    && renderAndCount(
                        session,
                        std::span<double>{actual}.subspan(3, 2),
                        allocations)
                    && allocations == 0
                    && renderAndCount(
                        session,
                        std::span<double>{actual}.subspan(5, 3),
                        allocations)
                    && allocations == 0,
                "C155 irregular paired schedule callbacks should render without allocation");
        }
        require(std::ranges::equal(actual, offline.mono),
            "C155 Function Generator schedules should be bit-identical across offline and prepared partitions");
    };
    renderPrepared(false);
    renderPrepared(true);
}

void testCheckedFunctionGeneratorFrameTransitionIsFailureAtomic()
{
    using namespace talas::runtime::checked_function_generator;

    const std::array envelope{0.0, 1.0, 0.0};
    auto next = State{99.0, false, false};
    auto output = 77.0;
    require(advanceFrame(
                envelope,
                State{},
                Controls{1.0, 1.0, false},
                Config{4.0},
                next,
                output)
                == Error::None
            && next == State{0.25, true, true}
            && output == 0.0,
        "C115 checked Function Generator should start a positive static one-shot at the table origin");

    next = State{99.0, false, false};
    output = 77.0;
    require(advanceFrame(
                envelope,
                State{0.25, true, true},
                Controls{1.0, 1.0, false},
                Config{4.0},
                next,
                output)
                == Error::None
            && next == State{0.5, true, true}
            && output == 0.5,
        "C115 checked Function Generator should preserve locked interpolation and elapsed stepping");

    next = State{99.0, true, true};
    output = 77.0;
    require(advanceFrame(
                envelope,
                State{0.5, true, true},
                Controls{0.0, 1.0, false},
                Config{4.0},
                next,
                output)
                == Error::None
            && next == State{}
            && output == 0.0
            && !std::signbit(output),
        "C115 checked Function Generator should reset on a closed static trigger");

    next = State{99.0, true, true};
    output = 77.0;
    require(advanceFrame(
                envelope,
                State{0.5, true, true},
                Controls{0.0, 1.0, false},
                Config{std::numeric_limits<double>::denorm_min()},
                next,
                output)
                == Error::None
            && next == State{}
            && output == 0.0
            && !std::signbit(output),
        "C115 inactive Function Generator frame should not evaluate an unused sample-rate reciprocal");

    next = State{99.0, true, true};
    output = 77.0;
    require(advanceFrame(
                envelope,
                State{0.25, true, true},
                Controls{0.0, 1.0, true},
                Config{4.0},
                next,
                output)
                == Error::None
            && next == State{0.5, true, false}
            && output == 0.5,
        "C115 connected falling edge should not stop an active one-shot");

    next = State{99.0, false, false};
    output = 77.0;
    require(advanceFrame(
                envelope,
                State{0.75, true, false},
                Controls{1.0, 1.0, true},
                Config{4.0},
                next,
                output)
                == Error::None
            && next == State{0.25, true, true}
            && output == 0.0,
        "C115 connected rising edge should retrigger before table sampling");

    next = State{99.0, false, false};
    output = 77.0;
    require(advanceFrame(
                envelope,
                State{0.75, true, false},
                Controls{0.0, 0.5, true},
                Config{4.0},
                next,
                output)
                == Error::None
            && next == State{0.75, true, false}
            && output == 0.0,
        "C115 duration shrink should silence without rescaling retained elapsed state");

    next = State{99.0, false, false};
    output = 77.0;
    require(advanceFrame(
                envelope,
                State{0.75, true, false},
                Controls{0.0, 1.25, true},
                Config{4.0},
                next,
                output)
                == Error::None
            && next == State{1.0, true, false}
            && output == 0.8,
        "C115 duration growth should resume the retained one-shot position");

    next = State{99.0, false, false};
    output = 77.0;
    require(advanceFrame(
                std::array{-0.0},
                State{},
                Controls{1.0, 1.0, false},
                Config{4.0},
                next,
                output)
                == Error::None
            && next == State{0.25, true, true}
            && output == 0.0
            && std::signbit(output),
        "C115 checked Function Generator should preserve table signed zero");

    const auto requireAtomicFailure = [&] (
        std::span<const double> table,
        State state,
        Controls controls,
        Config config,
        Error expected,
        std::string_view message) {
        auto rejectedNext = State{13.0, true, false};
        auto rejectedOutput = -17.0;
        require(advanceFrame(
                    table,
                    state,
                    controls,
                    config,
                    rejectedNext,
                    rejectedOutput)
                    == expected
                && rejectedNext == State{13.0, true, false}
                && rejectedOutput == -17.0,
            std::string{message});
    };

    requireAtomicFailure(
        {}, State{}, Controls{1.0, 1.0, false}, Config{4.0},
        Error::TableInvalid,
        "C115 checked Function Generator should reject an empty table without publication");
    requireAtomicFailure(
        envelope,
        State{std::numeric_limits<double>::quiet_NaN(), false, false},
        Controls{1.0, 1.0, false},
        Config{4.0},
        Error::StateInvalid,
        "C115 checked Function Generator should reject invalid state without publication");
    requireAtomicFailure(
        envelope, State{},
        Controls{std::numeric_limits<double>::infinity(), 1.0, false},
        Config{4.0}, Error::ControlsInvalid,
        "C115 checked Function Generator should reject a non-finite trigger without publication");
    requireAtomicFailure(
        envelope, State{}, Controls{1.0, 0.0, false}, Config{4.0},
        Error::ControlsInvalid,
        "C115 checked Function Generator should reject invalid duration without publication");
    requireAtomicFailure(
        envelope, State{}, Controls{1.0, 1.0, false}, Config{0.0},
        Error::ConfigInvalid,
        "C115 checked Function Generator should reject invalid sample rate without publication");
    requireAtomicFailure(
        envelope, State{}, Controls{1.0, 1.0, false},
        Config{std::numeric_limits<double>::denorm_min()},
        Error::SampleDurationNonFinite,
        "C115 checked Function Generator should reject reciprocal overflow without publication");
    requireAtomicFailure(
        std::array{std::numeric_limits<double>::max(),
            -std::numeric_limits<double>::max()},
        State{0.5, true, true}, Controls{1.0, 1.0, false}, Config{4.0},
        Error::InterpolationNonFinite,
        "C115 checked Function Generator should reject interpolation overflow without publication");
    requireAtomicFailure(
        std::array{std::numeric_limits<double>::max(),
            -std::numeric_limits<double>::max()},
        State{0.5, true, true}, Controls{1.0, 1.0, false},
        Config{std::numeric_limits<double>::denorm_min()},
        Error::InterpolationNonFinite,
        "C115 checked Function Generator should preserve interpolation-before-reciprocal failure ordering");
    requireAtomicFailure(
        std::array{1.0},
        State{1.0e308, true, true},
        Controls{1.0, 1.5e308, false},
        Config{1.0e-308},
        Error::StateStepNonFinite,
        "C115 checked Function Generator should reject elapsed addition overflow without publication");
}

void testRealtimeSessionRetriggersConnectedFunctionGeneratorWithoutAllocations()
{
    talas::runtime::RenderSettings settings{4.0, 2};
    settings.eventValues.push_back({"FunctionTrigger", 0.0, talas::expr::ValueDomain::Scalar});
    settings.tableResources.push_back({"Tables/Envelope", {0.0, 1.0, 0.0}});
    auto graph = compile(makeConnectedTriggerFunctionGeneratorVcaDocument(), std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 2> initial{};
    std::array<double, 2> triggered{};
    std::array<double, 2> continued{};
    std::array<double, 2> retriggered{};
    std::size_t allocations = 0;
    require(renderAndCount(session, initial, allocations), "closed Function Generator block should render");
    require(allocations == 0, "closed Function Generator block should not allocate");
    require(session.updateEventValue("FunctionTrigger", 1.0, talas::expr::ValueDomain::Scalar),
            "Function Generator trigger should accept the control-thread update");
    require(renderAndCount(session, triggered, allocations), "triggered Function Generator block should render");
    require(allocations == 0, "triggered Function Generator block should not allocate");
    require(session.updateEventValue("FunctionTrigger", 0.0, talas::expr::ValueDomain::Scalar),
            "Function Generator trigger should accept the falling-edge update");
    require(renderAndCount(session, continued, allocations), "released Function Generator block should render");
    require(allocations == 0, "released Function Generator block should not allocate");
    require(session.updateEventValue("FunctionTrigger", 1.0, talas::expr::ValueDomain::Scalar),
            "Function Generator trigger should accept a second rising-edge update");
    require(renderAndCount(session, retriggered, allocations), "retriggered Function Generator block should render");
    require(allocations == 0, "retriggered Function Generator block should not allocate");

    requireNear(initial[0], 0.0, 1.0e-12, "closed Function Generator should be silent");
    requireNear(initial[1], 0.0, 1.0e-12, "closed Function Generator should remain silent");
    requireNear(triggered[0], 0.0, 1.0e-12, "Function Generator trigger edge should restart at table start");
    requireNear(triggered[1], 0.46193976625564337, 1.0e-12, "Function Generator should advance after trigger edge");
    requireNear(continued[0], 1.0, 1.0e-12, "closed Function Generator trigger should not stop an active event");
    requireNear(continued[1], 0.46193976625564337, 1.0e-12, "Function Generator should continue through its table");
    requireNear(retriggered[0], 0.0, 1.0e-12, "a later Function Generator trigger edge should restart the table");
    requireNear(retriggered[1], 0.1913417161825449, 1.0e-12, "retriggered Function Generator should advance from its reset position");
}

