void testConnectedFunctionGeneratorControlsOwnInvalidFallbacksOfflineAndRealtime()
{
    talas::runtime::RenderSettings settings{4.0, 4};
    settings.tableResources.push_back(
        {"Tables/Envelope", {0.0, 1.0, 0.0}});
    const auto graph = compile(
        makeConnectedControlsFunctionGeneratorVcaDocument(),
        std::move(settings));

    const auto offline = talas::runtime::renderOffline(graph, 4);
    require(offline.ok() && offline.mono.size() == 4,
        "C115 connected Function Generator controls should own invalid inert fallbacks offline");

    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(),
        "C115 connected Function Generator controls should own invalid inert fallbacks during prepared construction: "
            + std::string{session.error()});
    std::array<double, 4> prepared{};
    std::size_t allocations = 0;
    require(renderAndCount(session, prepared, allocations)
            && allocations == 0
            && std::ranges::equal(offline.mono, prepared),
        "C115 connected Function Generator controls should own invalid inert fallbacks identically offline and prepared realtime");

    for (const auto port : {
             std::string_view{"trigger"},
             std::string_view{"onDuration"}})
    {
        for (const auto& invalidFallback : {
                 std::string{"440 hz"},
                 std::string{"!C155MissingControl"}})
        {
            auto invalidDocument =
                makeConnectedControlsFunctionGeneratorVcaDocument();
            const auto function = std::ranges::find(
                invalidDocument.graph.nodes,
                std::string_view{"function"},
                &talas::project::ProjectNode::instanceId);
            require(function != invalidDocument.graph.nodes.end(),
                "C155 invalid-fallback fixture should expose Function Generator");
            const auto parameter = std::ranges::find(
                function->parameters, port,
                &talas::project::ProjectParameterExpression::parameterId);
            require(parameter != function->parameters.end(),
                "C155 invalid-fallback fixture should expose selected control");
            parameter->expression = invalidFallback;
            talas::runtime::RenderSettings invalidSettings{4.0, 4};
            invalidSettings.tableResources.push_back(
                {"Tables/Envelope", {0.0, 1.0, 0.0}});
            const auto invalid = talas::runtime::compileProject(
                invalidDocument,
                talas::core::makeBuiltinNodeRegistry(),
                std::move(invalidSettings));
            require(!invalid.ok(),
                "C155 connected precedence must not hide wrong-domain or unresolved promoted Function Generator fallback authority");
        }
    }
}

