void testRealtimeFunctionGeneratorRequiresExactCompilerOwnedSamplingAuthority()
{
    talas::runtime::RenderSettings settings{4.0, 2};
    settings.tableResources.push_back(
        {"Tables/Envelope", {0.0, 1.0, 0.0}});
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("carrier", "talas.oscillator", {
            {"frequency", "440 hz"}, {"amplitude", "0.25"}}),
        node("function", "talas.functionGenerator", {
            {"trigger", "1"},
            {"onDuration", "1 s"},
            resourceParameter("wavetable", "Tables/Envelope"),
            booleanParameter("fromMemoryWriter", false),
        }),
    };
    document.graph.connections = {
        connection("function", "value", "carrier", "frequency"),
        connection("carrier", "audioOut", "out", "audioIn"),
    };
    const auto compiled = compile(document, settings);
    talas::runtime::RealtimeRenderSession exactSession{compiled};
    const auto exactOffline = talas::runtime::renderOffline(compiled, 2);
    require(exactSession.ready() && exactOffline.ok(),
        "C155 exact built-in Function Generator authority should render offline and prepare realtime");

    talas::runtime::RealtimeRenderSession publiclyConstructed(
        talas::runtime::PreparedRuntimeGraph{
            compiled.plan(), compiled.renderSettings()});
    require(!publiclyConstructed.ready()
            && publiclyConstructed.error()
                == "Realtime Function Generator requires exact compiler-owned descriptor, plan, settings, and immutable-resource authority",
        "C155 Function Generator should require privately compiler-sealed exact authority: "
            + std::string{publiclyConstructed.error()});

    auto forgedSettingsGraph = compiled;
    auto& forgedSettings = mutableSettingsForTest(forgedSettingsGraph);
    require(!forgedSettings.tableResources.empty(),
        "C115 Function Generator authority fixture should expose its table DTO");
    forgedSettings.tableResources.front().samples[1] = std::nextafter(
        forgedSettings.tableResources.front().samples[1],
        std::numeric_limits<double>::infinity());
    talas::runtime::RealtimeRenderSession rejectedSettings(
        forgedSettingsGraph);
    const auto rejectedSettingsOffline = talas::runtime::renderOffline(
        forgedSettingsGraph, 2);
    require(!rejectedSettings.ready()
            && !rejectedSettingsOffline.ok()
            && rejectedSettingsOffline.mono.empty(),
        "C155 Function Generator should reject table-sample mutation after compilation offline and prepared");

    auto forgedPlanGraph = compiled;
    auto& plan = mutablePlanForTest(forgedPlanGraph);
    const auto step = std::ranges::find(
        plan.steps,
        std::string_view{"talas.functionGenerator"},
        &talas::runtime::CompileStep::typeId);
    require(step != plan.steps.end() && !step->parameters.empty(),
        "C115 Function Generator authority fixture should expose its compile step");
    step->parameters.front().value = std::nextafter(
        step->parameters.front().value,
        std::numeric_limits<double>::infinity());
    talas::runtime::RealtimeRenderSession rejectedPlan(forgedPlanGraph);
    const auto rejectedPlanOffline = talas::runtime::renderOffline(
        forgedPlanGraph, 2);
    require(!rejectedPlan.ready() && !rejectedPlanOffline.ok()
            && rejectedPlanOffline.mono.empty(),
        "C155 Function Generator should reject plan mutation after compilation offline and prepared");

    auto downgraded = compiled;
    const auto downgradedStep = std::ranges::find(
        mutablePlanForTest(downgraded).steps,
        std::string_view{"talas.functionGenerator"},
        &talas::runtime::CompileStep::typeId);
    require(downgradedStep != mutablePlanForTest(downgraded).steps.end(),
        "C155 downgraded fixture should expose Function Generator");
    downgradedStep->offlineSupport =
        talas::core::ExecutionSupport::Subset;
    talas::runtime::RealtimeRenderSession downgradedSession{downgraded};
    const auto downgradedOffline = talas::runtime::renderOffline(
        downgraded, 2);
    require(!downgradedSession.ready() && !downgradedOffline.ok(),
        "C155 sealed Function Generator should reject a support downgrade");

    auto subsetRegistry = talas::core::makeBuiltinNodeRegistry();
    subsetRegistry.setNodeTypeOfflineSupport(
        "talas.functionGenerator", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    subsetRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.functionGenerator", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto subset = talas::runtime::compileProject(
        document, subsetRegistry, settings);
    require(subset.ok(),
        "C155 explicit custom Subset Function Generator should compile");
    talas::runtime::RealtimeRenderSession subsetSession{*subset.graph};
    const auto subsetOffline = talas::runtime::renderOffline(
        *subset.graph, 2);
    const auto unsealedSubsetGraph =
        makePublicCompatibilityGraphWithSubsetOscillators(
            *subset.graph);
    talas::runtime::RealtimeRenderSession unsealedSubsetSession{
        unsealedSubsetGraph};
    const auto unsealedSubsetOffline = talas::runtime::renderOffline(
        unsealedSubsetGraph, 2);
    require(subsetSession.ready() && subsetOffline.ok(),
        "C155 exact custom Subset should retain sealed C115 compatibility: "
            + std::string{subsetSession.error()});
    require(unsealedSubsetSession.ready()
            && unsealedSubsetOffline.ok(),
        "C155 exact custom Subset should retain genuinely unsealed C115 compatibility: "
            + std::string{unsealedSubsetSession.error()});

    auto mixedRegistry = talas::core::makeBuiltinNodeRegistry();
    mixedRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.functionGenerator", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto mixed = talas::runtime::compileProject(
        document, mixedRegistry, settings);
    require(mixed.ok(),
        "C155 mixed-support fixture should compile before admission rejection");
    talas::runtime::RealtimeRenderSession mixedSession{*mixed.graph};
    const auto mixedOffline = talas::runtime::renderOffline(
        *mixed.graph, 2);
    require(!mixedSession.ready() && !mixedOffline.ok(),
        "C155 mixed Function Generator support should not mint promoted authority");

    auto divergentRegistry = talas::core::makeBuiltinNodeRegistry();
    divergentRegistry.setNodeTypeFanInLatencyPolicy(
        "talas.functionGenerator",
        talas::core::FanInLatencyPolicy::PreserveRelative);
    const auto divergent = talas::runtime::compileProject(
        document, divergentRegistry, settings);
    require(divergent.ok(),
        "C155 coherent divergent descriptor should compile before admission rejection");
    talas::runtime::RealtimeRenderSession divergentSession{
        *divergent.graph};
    const auto divergentOffline = talas::runtime::renderOffline(
        *divergent.graph, 2);
    require(!divergentSession.ready() && !divergentOffline.ok(),
        "C155 coherent divergent Supported descriptor should not mint built-in authority");
}

void testRealtimeFunctionGeneratorTransportResetIsFreshEquivalent()
{
    talas::runtime::RenderSettings settings{4.0, 4};
    settings.tableResources.push_back(
        {"Tables/Envelope", {0.0, 1.0, 0.0}});
    const auto graph = compile(
        makeFunctionGeneratorVcaDocument(), std::move(settings));
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession fresh(graph);
    require(candidate.ready() && fresh.ready(),
        "C115 Function Generator reset fixtures should prepare");

    std::array<double, 3> warm{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, warm, allocations)
            && allocations == 0,
        "C115 Function Generator should advance before transport reset");
    candidate.resetTransport();

    std::array<double, 4> reset{};
    std::array<double, 4> expected{};
    require(renderAndCount(candidate, reset, allocations)
            && renderAndCount(fresh, expected, allocations)
            && allocations == 0
            && reset == expected,
        "C115 Function Generator transport reset should reproduce a fresh session exactly");
}

