    std::size_t allocations = 0;
    require(renderAndCount(session, first, allocations), "first Samples From Disk Single Step block should render");
    require(allocations == 0, "first Samples From Disk Single Step block should not allocate");
    require(renderAndCount(session, second, allocations), "second Samples From Disk Single Step block should render");
    require(allocations == 0, "second Samples From Disk Single Step block should not allocate");
    require(renderAndCount(session, third, allocations), "completed Samples From Disk Single Step block should render");
