void testSamplesFromDiskSingleStepConnectedControlsHideInvalidFallbacksAcrossReset()
{
    auto document = makeSamplesFromDiskSingleStepDocument({
        resourceParameter("fileName", "Samples/DiskStep"),
        {"filePosition", "9"},
        {"trigger", "1e200 * 1e200"},
        {"gate", "1e200 * 1e200"},
    });
    document.graph.nodes.push_back(node(
        "position", "talas.constant", {{"value", "1"}}));
    document.graph.nodes.push_back(node(
        "trigger", "talas.constant", {{"value", "1"}}));
    document.graph.nodes.push_back(node(
        "gate", "talas.constant", {{"value", "1"}}));
    document.graph.connections.push_back(connection(
        "position", "value", "disk", "filePosition"));
    document.graph.connections.push_back(connection(
        "trigger", "value", "disk", "trigger"));
    document.graph.connections.push_back(connection(
        "gate", "value", "disk", "gate"));

    auto settings = talas::runtime::RenderSettings{4.0, 2};
    settings.tableResources.push_back(
        {"Samples/DiskStep", {10.0, 20.0, 30.0}});
    const auto graph = compile(document, settings);
    const auto offline = talas::runtime::renderOffline(graph, 2);
    talas::runtime::RealtimeRenderSession session(graph);
    talas::runtime::RealtimeRenderSession fresh(graph);
    require(offline.ok()
            && offline.mono == std::vector<double>({20.0, 30.0}),
        "C99 connected controls should hide every invalid direct fallback offline");
    require(session.ready() && fresh.ready(),
        "C99 connected controls should hide every invalid direct fallback during prepared admission: "
            + std::string{session.error()});
    std::array<double, 2> output{};
    std::size_t allocations = 0;
    require(renderAndCount(session, output, allocations)
            && allocations == 0
            && output == std::array<double, 2>{20.0, 30.0},
        "C99 connected invalid fallback fixture should render the selected controls without allocation");

    std::size_t resetAllocations = 0;
    {
        AllocationCounter counter;
        session.resetTransport();
        resetAllocations = counter.count();
    }
    std::array<double, 2> reset{};
    std::array<double, 2> expected{};
    require(resetAllocations == 0
            && renderAndCount(session, reset, allocations)
            && allocations == 0
            && renderAndCount(fresh, expected, allocations)
            && allocations == 0
            && reset == expected
            && reset == std::array<double, 2>{20.0, 30.0},
        "C99 connected authority should survive transport reset without consulting its hidden fallback");
}

void testSamplesFromDiskSingleStepDirectScheduledControlsMatchOfflinePartitions()
{
    auto settings = talas::runtime::RenderSettings{4.0, 3};
    settings.eventValues = {
        {"C99DirectPosition", 1.0,
            talas::expr::ValueDomain::Scalar},
        {"C99DirectTrigger", 1.0,
            talas::expr::ValueDomain::Scalar},
        {"C99DirectGate", 1.0,
            talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "C99DirectTrigger", 0.0,
            talas::expr::ValueDomain::Scalar},
        {3, "C99DirectPosition", 0.0,
            talas::expr::ValueDomain::Scalar},
        {3, "C99DirectGate", 0.0,
            talas::expr::ValueDomain::Scalar},
        {4, "C99DirectTrigger", 1.0,
            talas::expr::ValueDomain::Scalar},
        {4, "C99DirectGate", 1.0,
            talas::expr::ValueDomain::Scalar},
    };
    settings.tableResources.push_back(
        {"Samples/DiskStep", {10.0, 20.0, 30.0, 40.0}});
    const auto graph = compile(
        makeSamplesFromDiskSingleStepDocument({
            resourceParameter("fileName", "Samples/DiskStep"),
            {"filePosition", "!C99DirectPosition"},
            {"trigger", "!C99DirectTrigger"},
            {"gate", "!C99DirectGate"},
        }),
        settings);
    const auto offline = talas::runtime::renderOffline(graph, 6);
    talas::runtime::RealtimeRenderSession prepared(graph);
    require(offline.ok() && prepared.ready(),
        "C99 direct scheduled controls should prepare offline and realtime");
    const std::array expected{20.0, 30.0, 30.0, 30.0, 10.0, 20.0};
    require(std::ranges::equal(offline.mono, expected),
        "C99 offline direct controls should preserve advance, hold, re-arm, and restart semantics");
    std::array<double, 6> actual{};
    std::size_t allocations = 0;
    std::size_t offset = 0;
    for (const auto frames : std::array<std::size_t, 3>{2, 1, 3})
    {
        require(renderAndCount(
                    prepared,
                    std::span<double>{actual}.subspan(offset, frames),
                    allocations)
                && allocations == 0,
            "C99 direct scheduled prepared partition should render without allocation");
        offset += frames;
    }
    require(actual == expected,
        "C99 direct scheduled prepared controls should be bit-identical to offline across irregular partitions");
}

