void testRealtimeSamplesFromDiskSingleStepRejectsForgedPreparedAuthority()
{
    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.eventValues = {
        {"StepPosition", 1.0, talas::expr::ValueDomain::Scalar},
        {"StepGate", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.tableResources.push_back(
        {"Samples/DiskStep", {10.0, 20.0, 30.0, 40.0, 50.0}});
    const auto graph = compile(
        makeConnectedSamplesFromDiskSingleStepDocument(), settings);
    const auto requireRejected = [&](auto mutate,
                                     std::string_view context) {
        auto plan = graph.plan();
        const auto step = std::ranges::find(
            plan.steps,
            std::string_view{"talas.samplesFromDiskSingleStep"},
            &talas::runtime::CompileStep::typeId);
        require(step != plan.steps.end(),
            "C99 forged-authority fixture should expose Samples From Disk Single Step");
        mutate(*step);
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), graph.renderSettings()});
        require(!session.ready(), std::string{context}
                + " should reject forged C99 Samples From Disk Single Step authority");
    };
    requireRejected(
        [](auto& step) { step.supportsReset = false; },
        "forged reset capability");
    requireRejected(
        [](auto& step) { step.resolvedLatencyFrames = 1; },
        "forged intrinsic latency");
    requireRejected(
        [](auto& step) {
            std::swap(step.parameters[0], step.parameters[1]);
        },
        "forged parameter order");
    requireRejected(
        [](auto& step) {
            std::swap(step.inputs[0], step.inputs[1]);
        },
        "forged input order");
    requireRejected(
        [](auto& step) {
            step.preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
            step.kernelKind = talas::runtime::KernelKind::Gate;
        },
        "forged prepared binding");
}

