void testCheckedChopperFrameTransitionIsFailureAtomic()
{
    using namespace talas::runtime::checked_chopper;

    const std::array envelope{0.0, 1.0, 0.0};
    auto next = State{99.0};
    auto output = 77.0;
    require(advanceFrame(
                envelope,
                State{0.25},
                Controls{2.0, 1.0, 0.5},
                Config{4.0},
                next,
                output)
                == Error::None
            && next == State{0.5}
            && output == 1.0,
        "C114 checked Chopper should preserve the locked active-grain interpolation and elapsed step");

    next = State{99.0};
    output = 77.0;
    require(advanceFrame(
                envelope,
                State{1.0},
                Controls{2.0, 1.0, 0.5},
                Config{4.0},
                next,
                output)
                == Error::None
            && next == State{1.25}
            && output == 0.0,
        "C114 checked Chopper should keep the grain interval half-open");

    next = State{99.0};
    output = 77.0;
    require(advanceFrame(
                envelope,
                State{1.0},
                Controls{-2.0, 1.0, 0.5},
                Config{4.0},
                next,
                output)
                == Error::None
            && next == State{1.25}
            && output == 0.0
            && std::signbit(output),
        "C114 checked Chopper should preserve negative signed zero from delay-interval multiplication");

    next = State{99.0};
    output = 77.0;
    require(advanceFrame(
                envelope,
                State{1.5},
                Controls{2.0, 1.0, 0.5},
                Config{4.0},
                next,
                output)
                == Error::None
            && next == State{0.25}
            && output == 0.0,
        "C114 checked Chopper should wrap a live-cycle boundary before sampling");

    const auto requireAtomicFailure = [&] (
        std::span<const double> table,
        State state,
        Controls controls,
        Config config,
        Error expected,
        std::string_view message) {
        auto rejectedNext = State{13.0};
        auto rejectedOutput = -17.0;
        require(advanceFrame(
                    table,
                    state,
                    controls,
                    config,
                    rejectedNext,
                    rejectedOutput)
                    == expected
                && rejectedNext == State{13.0}
                && rejectedOutput == -17.0,
            std::string{message});
    };

    requireAtomicFailure(
        {},
        State{0.0},
        Controls{1.0, 1.0, 0.5},
        Config{4.0},
        Error::TableInvalid,
        "C114 checked Chopper should reject an empty envelope without publication");
    requireAtomicFailure(
        envelope,
        State{0.0},
        Controls{
            std::numeric_limits<double>::infinity(), 1.0, 0.5},
        Config{4.0},
        Error::ControlsInvalid,
        "C114 checked Chopper should reject non-finite input without publication");
    requireAtomicFailure(
        envelope,
        State{std::numeric_limits<double>::quiet_NaN()},
        Controls{1.0, 1.0, 0.5},
        Config{4.0},
        Error::StateInvalid,
        "C114 checked Chopper should reject invalid elapsed state without publication");
    requireAtomicFailure(
        envelope,
        State{0.0},
        Controls{1.0, 1.0, 0.5},
        Config{0.0},
        Error::ConfigInvalid,
        "C114 checked Chopper should reject an invalid sample rate without publication");
    requireAtomicFailure(
        envelope,
        State{0.0},
        Controls{1.0, 1.0, 0.5},
        Config{std::numeric_limits<double>::denorm_min()},
        Error::SampleDurationNonFinite,
        "C114 checked Chopper should reject reciprocal sample-duration overflow without publication");
    requireAtomicFailure(
        envelope,
        State{0.0},
        Controls{1.0,
            std::numeric_limits<double>::max(),
            std::numeric_limits<double>::max()},
        Config{4.0},
        Error::CycleDurationNonFinite,
        "C114 checked Chopper should reject cycle addition overflow without publication");
    requireAtomicFailure(
        envelope,
        State{0.0},
        Controls{
            std::numeric_limits<double>::infinity(),
            std::numeric_limits<double>::max(),
            std::numeric_limits<double>::max()},
        Config{4.0},
        Error::CycleDurationNonFinite,
        "C114 checked Chopper should preserve cycle-before-input failure ordering for simultaneous hazards");
    requireAtomicFailure(
        std::array{std::numeric_limits<double>::max(),
            -std::numeric_limits<double>::max()},
        State{0.5},
        Controls{1.0, 1.0, 0.5},
        Config{4.0},
        Error::InterpolationNonFinite,
        "C114 checked Chopper should reject interpolation overflow without publication");
    requireAtomicFailure(
        std::array{2.0},
        State{0.0},
        Controls{std::numeric_limits<double>::max(), 1.0, 0.5},
        Config{4.0},
        Error::OutputNonFinite,
        "C114 checked Chopper should reject output multiplication overflow without publication");
    requireAtomicFailure(
        std::array{1.0},
        State{1.0e308},
        Controls{1.0, 1.5e308, 1.0e307},
        Config{1.0e-308},
        Error::StateStepNonFinite,
        "C114 checked Chopper should reject elapsed-state addition overflow without publication");
}

void testRealtimeChopperTransportResetIsFreshEquivalent()
{
    talas::runtime::RenderSettings settings{4.0, 4};
    settings.tableResources.push_back(
        {"Tables/Grain", {0.0, 1.0, 0.0}});
    const auto graph = compile(
        makeChopperDocument(), std::move(settings));
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession fresh(graph);
    require(candidate.ready() && fresh.ready(),
        "C114 reset-equivalence Chopper fixtures should prepare: "
            + std::string{candidate.error()});

    std::array<double, 3> warm{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, warm, allocations)
            && allocations == 0,
        "C114 Chopper fixture should advance without allocation");
    candidate.resetTransport();

    std::array<double, 4> reset{};
    std::array<double, 4> expected{};
    require(renderAndCount(candidate, reset, allocations)
            && renderAndCount(fresh, expected, allocations)
            && allocations == 0
            && reset == expected,
        "C114 Chopper transport reset should reproduce a fresh prepared session exactly");
}

