void testRealtimeChopperRequiresExactCompilerOwnedSamplingAuthority()
{
    talas::runtime::RenderSettings settings{4.0, 4};
    settings.tableResources.push_back(
        {"Tables/Grain", {0.0, 1.0, 0.0}});
    const auto compiled = compile(
        makeChopperDocument(), std::move(settings));
    talas::runtime::RealtimeRenderSession exactSession{compiled};
    const auto exactOffline = talas::runtime::renderOffline(compiled, 4);
    require(exactSession.ready() && exactOffline.ok(),
        "C161 exact built-in Chopper authority should render offline and prepare realtime");

    talas::runtime::RealtimeRenderSession publiclyConstructed(
        makePublicCompatibilityGraphWithSubsetOscillators(
            compiled));
    require(!publiclyConstructed.ready()
            && publiclyConstructed.error()
                == "Realtime Chopper requires exact compiler-owned descriptor, plan, settings, and immutable-resource authority",
        "C161 Chopper should require privately compiler-sealed exact authority: "
            + std::string{publiclyConstructed.error()});

    auto forged = compiled;
    auto& forgedSettings = mutableSettingsForTest(forged);
    require(!forgedSettings.tableResources.empty(),
        "C114 Chopper authority fixture should expose its wavetable DTO");
    forgedSettings.tableResources.front().samples.front() =
        std::nextafter(
            forgedSettings.tableResources.front().samples.front(),
            std::numeric_limits<double>::infinity());
    talas::runtime::RealtimeRenderSession rejected(forged);
    require(!rejected.ready(),
        "C114 Chopper should reject a table-sample bit mutation after compilation");

    const auto requirePlanMutationRejected = [&] (
        auto mutate, std::string_view context) {
        auto mutated = compiled;
        auto& plan = mutablePlanForTest(mutated);
        const auto step = std::ranges::find(
            plan.steps,
            std::string_view{"talas.chopper"},
            &talas::runtime::CompileStep::typeId);
        require(step != plan.steps.end(),
            "C114 authority fixture should expose the Chopper step");
        mutate(plan, *step);
        talas::runtime::RealtimeRenderSession candidate(mutated);
        require(!candidate.ready(),
            "C114 Chopper should reject compiler-authority "
                + std::string{context});
    };
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.parameters.front().value = std::nextafter(
            step.parameters.front().value,
            std::numeric_limits<double>::infinity());
    }, "parameter mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.inputs.front().sourcePortId += "Forged";
    }, "input-binding mutation");
    requirePlanMutationRejected([] (auto& plan, auto& step) {
        const auto output = std::ranges::find_if(
            plan.buffers,
            [&] (const auto& buffer) {
                return buffer.nodeId == step.nodeId
                    && buffer.scopeId == step.scopeId
                    && buffer.portId == "audioOut";
            });
        require(output != plan.buffers.end(),
            "C114 authority fixture should expose the Chopper output buffer");
        ++output->frames;
    }, "output-buffer mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.resolvedLatencyFrames = 1;
    }, "latency mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.preparedRealtimeSupport =
            talas::core::ExecutionSupport::Unsupported;
    }, "support mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        step.supportsReset = false;
    }, "reset-capability mutation");
    requirePlanMutationRejected([] (auto&, auto& step) {
        ++step.scopeId;
    }, "scope mutation");

    auto compatibilitySettings = talas::runtime::RenderSettings{4.0, 4};
    compatibilitySettings.tableResources.push_back(
        {"Tables/Grain", {0.0, 1.0, 0.0}});
    auto subsetRegistry = talas::core::makeBuiltinNodeRegistry();
    subsetRegistry.setNodeTypeOfflineSupport(
        "talas.chopper", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    subsetRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.chopper", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto subset = talas::runtime::compileProject(
        makeChopperDocument(), subsetRegistry,
        compatibilitySettings);
    require(subset.ok(),
        "C161 explicit custom Subset Chopper should compile");
    talas::runtime::RealtimeRenderSession subsetSession{*subset.graph};
    const auto subsetOffline = talas::runtime::renderOffline(
        *subset.graph, 4);
    const auto unsealedSubsetGraph =
        makePublicCompatibilityGraphWithSubsetOscillators(
            *subset.graph);
    talas::runtime::RealtimeRenderSession unsealedSubsetSession{
        unsealedSubsetGraph};
    const auto unsealedSubsetOffline = talas::runtime::renderOffline(
        unsealedSubsetGraph, 4);
    require(subsetSession.ready() && subsetOffline.ok(),
        "C161 coherent custom Subset Chopper should retain bounded compatibility: "
            + std::string{subsetSession.error()});
    require(unsealedSubsetSession.ready()
            && unsealedSubsetOffline.ok(),
        "C161 unsealed custom Subset Chopper should retain bounded compatibility: "
            + std::string{unsealedSubsetSession.error()});

    auto mixedRegistry = talas::core::makeBuiltinNodeRegistry();
    mixedRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.chopper", talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto mixed = talas::runtime::compileProject(
        makeChopperDocument(), mixedRegistry,
        compatibilitySettings);
    require(mixed.ok(),
        "C161 mixed-support Chopper fixture should compile before admission rejection");
    talas::runtime::RealtimeRenderSession mixedSession{*mixed.graph};
    const auto mixedOffline = talas::runtime::renderOffline(
        *mixed.graph, 4);
    require(!mixedSession.ready() && !mixedOffline.ok(),
        "C161 mixed Chopper support should not mint promoted authority");

    auto divergentRegistry = talas::core::makeBuiltinNodeRegistry();
    divergentRegistry.setNodeTypeFanInLatencyPolicy(
        "talas.chopper",
        talas::core::FanInLatencyPolicy::PreserveRelative);
    const auto divergent = talas::runtime::compileProject(
        makeChopperDocument(), divergentRegistry,
        compatibilitySettings);
    require(divergent.ok(),
        "C161 divergent Chopper descriptor should compile before admission rejection");
    talas::runtime::RealtimeRenderSession divergentSession{
        *divergent.graph};
    const auto divergentOffline = talas::runtime::renderOffline(
        *divergent.graph, 4);
    require(!divergentSession.ready() && !divergentOffline.ok(),
        "C161 divergent Supported Chopper descriptor should not mint built-in authority");
}

