void testRealtimeSessionUpdatesConnectedChopperDurationsWithoutAllocations()
{
    talas::runtime::RenderSettings settings{4.0, 4};
    settings.tableResources.push_back({"Tables/Grain", {0.0, 1.0, 0.0}});
    settings.tableResources.push_back({"Tables/GrainDuration", {1.0, 1.0, 1.0, 0.5, 0.5, 0.5, 0.5, 0.5}});
    auto graph = compile(makeConnectedChopperDocument(), std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 8);
    require(expected.ok(), "offline connected Chopper reference should render");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 4> first{};
    std::array<double, 4> second{};
    std::size_t allocations = 0;
    require(renderAndCount(session, first, allocations), "first connected Chopper block should render");
    require(allocations == 0, "first connected Chopper block should not allocate");
    require(renderAndCount(session, second, allocations), "second connected Chopper block should render");
    require(allocations == 0, "second connected Chopper block should not allocate");

    require(expected.mono.size() == first.size() + second.size(), "offline connected Chopper reference should provide two blocks");
    for (std::size_t frame = 0; frame < first.size(); ++frame)
        requireNear(first[frame], expected.mono[frame], 1.0e-12, "first connected Chopper block should match offline");
    for (std::size_t frame = 0; frame < second.size(); ++frame)
        requireNear(second[frame], expected.mono[first.size() + frame], 1.0e-12,
                "second connected Chopper block should match offline after duration changes");
}

void testChopperScheduledDurationsMatchOfflinePreparedAndPartitions()
{
    const auto initialSettings = [] {
        auto settings = talas::runtime::RenderSettings{8.0, 8};
        settings.maxRealtimeEventTransactions = 8;
        settings.tableResources = {
            {"Tables/Grain", {0.0, 1.0, 0.0}},
        };
        settings.eventValues = {
            {"C161GrainDuration", 0.5,
                talas::expr::ValueDomain::Scalar},
            {"C161InterGrainDelay", 0.25,
                talas::expr::ValueDomain::Scalar},
        };
        return settings;
    };
    auto offlineSettings = initialSettings();
    offlineSettings.eventValueChanges = {
        {2, "C161GrainDuration", 0.25,
            talas::expr::ValueDomain::Scalar},
        {2, "C161InterGrainDelay", 0.125,
            talas::expr::ValueDomain::Scalar},
        {4, "C161GrainDuration", 0.75,
            talas::expr::ValueDomain::Scalar},
        {5, "C161InterGrainDelay", 0.375,
            talas::expr::ValueDomain::Scalar},
    };
    const auto offlineGraph = compile(
        makeC161ScheduledChopperDocument(), offlineSettings);
    const auto offline = talas::runtime::renderOffline(offlineGraph, 8);
    require(offline.ok() && offline.mono.size() == 8,
        "C161 paired Chopper offline schedule should render");

    talas::runtime::OfflineRenderSession partitionedOffline{offlineGraph};
    std::vector<double> partitioned;
    for (const auto frames : {std::size_t{1}, std::size_t{3},
             std::size_t{1}, std::size_t{3}})
    {
        const auto block = partitionedOffline.render(frames);
        require(block.ok(),
            "C161 irregular offline Chopper partition should render");
        partitioned.insert(
            partitioned.end(), block.mono.begin(), block.mono.end());
    }
    require(partitioned == offline.mono,
        "C161 offline Chopper schedule should be partition invariant");

    const auto schedule = [] (talas::runtime::RealtimeRenderSession& session) {
        const std::array shrink{
            talas::runtime::RealtimeEventValueUpdate{
                "C161GrainDuration", 0.25,
                talas::expr::ValueDomain::Scalar},
            talas::runtime::RealtimeEventValueUpdate{
                "C161InterGrainDelay", 0.125,
                talas::expr::ValueDomain::Scalar},
        };
        require(session.scheduleEventValues(shrink, 2),
            "C161 same-frame Chopper shrink batch should stage");
        require(session.scheduleEventValue(
                    "C161GrainDuration", 0.75,
                    talas::expr::ValueDomain::Scalar, 4),
            "C161 Chopper grain grow should stage");
        require(session.scheduleEventValue(
                    "C161InterGrainDelay", 0.375,
                    talas::expr::ValueDomain::Scalar, 5),
            "C161 Chopper delay grow should stage");
    };
    const auto preparedGraph = compile(
        makeC161ScheduledChopperDocument(), initialSettings());
    talas::runtime::RealtimeRenderSession prepared{preparedGraph};
    require(prepared.ready(),
        "C161 paired Chopper prepared graph should prepare: "
            + std::string{prepared.error()});
    require(!prepared.scheduleEventValue(
                "C161GrainDuration", std::numeric_limits<double>::quiet_NaN(),
                talas::expr::ValueDomain::Scalar, 0)
            && !prepared.scheduleEventValue(
                "C161InterGrainDelay",
                std::numeric_limits<double>::infinity(),
                talas::expr::ValueDomain::Scalar, 0),
        "C161 prepared Chopper should reject invalid duration schedules transactionally");
    schedule(prepared);
    std::array<double, 8> preparedOutput{};
    std::size_t allocations = 0;
    require(renderAndCount(prepared, preparedOutput, allocations)
            && allocations == 0,
        "C161 paired Chopper schedule should render allocation free");
    require(std::ranges::equal(preparedOutput, offline.mono),
        "C161 same-frame duration schedule should match offline exactly");

    talas::runtime::RealtimeRenderSession singleFrame{preparedGraph};
    require(singleFrame.ready(),
        "C161 single-frame Chopper graph should prepare: "
            + std::string{singleFrame.error()});
    schedule(singleFrame);
    std::array<double, 8> singleFrameOutput{};
    for (auto& sample : singleFrameOutput)
    {
        std::span<double, 1> frame{&sample, 1};
        require(renderAndCount(singleFrame, frame, allocations)
                && allocations == 0,
            "C161 single-frame Chopper partition should render allocation free");
    }
    require(singleFrameOutput == preparedOutput,
        "C161 prepared Chopper schedule should retain offsets across single-frame callbacks");
}

void testChopperDownstreamFailureRestoresScheduledDurationCursor()
{
    auto document = makeC161ScheduledChopperDocument();
    const auto carrier = std::ranges::find(
        document.graph.nodes,
        std::string_view{"osc"},
        &talas::project::ProjectNode::instanceId);
    require(carrier != document.graph.nodes.end(),
        "C161 rollback fixture should expose its carrier");
    const auto amplitude = std::ranges::find(
        carrier->parameters,
        std::string_view{"amplitude"},
        &talas::project::ProjectParameterExpression::parameterId);
    require(amplitude != carrier->parameters.end(),
        "C161 rollback fixture should expose carrier amplitude");
    amplitude->expression = "4";
    std::erase_if(document.graph.connections,
        [] (const auto& candidate) {
            return candidate.fromNode == "chop"
                && candidate.toNode == "out";
        });
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C161Downstream"},
            {"right", "0"},
            booleanParameter("noGain", false),
        }));
    document.graph.connections.push_back(connection(
        "chop", "audioOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 2};
    settings.maxRealtimeEventTransactions = 4;
    settings.tableResources = {
        {"Tables/Grain", {0.0, 1.0, 0.0}},
    };
    settings.eventValues = {
        {"C161GrainDuration", 0.5,
            talas::expr::ValueDomain::Scalar},
        {"C161InterGrainDelay", 0.25,
            talas::expr::ValueDomain::Scalar},
        {"C161Downstream", 1.0,
            talas::expr::ValueDomain::Scalar},
    };
    talas::runtime::RealtimeRenderSession session{
        compile(document, settings)};
    require(session.ready(),
        "C161 scheduled rollback fixture should prepare: "
            + std::string{session.error()});
    require(session.scheduleEventValue(
                "C161GrainDuration", 0.75,
                talas::expr::ValueDomain::Scalar, 1)
            && session.scheduleEventValue(
                "C161Downstream",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar, 1),
        "C161 rollback fixture should stage duration and downstream failure at the same frame");
    const auto before =
        talas::runtime::RealtimeRenderSessionTestAccess::
            chopperElapsedTime(session);
    std::array<double, 2> rejected;
    std::size_t allocations = 0;
    for (auto attempt = 0; attempt < 2; ++attempt)
    {
        rejected.fill(100.0);
        require(!renderAndCount(session, rejected, allocations)
                && allocations == 0
                && rejected == std::array<double, 2>{}
                && talas::runtime::RealtimeRenderSessionTestAccess::
                        chopperElapsedTime(session)
                    == before,
            "C161 downstream rejection should restore duration schedule, callback position, and Chopper elapsed state");
    }
}

