void testPromotedChopperConnectedFallbackDiagnosticsRemainExact()
{
    const auto settings = [] {
        auto result = talas::runtime::RenderSettings{4.0, 2};
        result.tableResources = {
            {"Tables/Grain", {0.0, 1.0, 0.0}},
            {"Tables/GrainDuration", {1.0, 1.0}},
        };
        return result;
    };
    for (const auto port : {
             std::string_view{"grainDuration"},
             std::string_view{"interGrainDelay"}})
    {
        for (const auto& invalidFallback : {
                 std::string{"440 hz"},
                 std::string{"!C161MissingDuration"}})
        {
            auto document = makeConnectedChopperDocument();
            const auto chopper = std::ranges::find(
                document.graph.nodes,
                std::string_view{"chop"},
                &talas::project::ProjectNode::instanceId);
            require(chopper != document.graph.nodes.end(),
                "C161 invalid-fallback fixture should expose Chopper");
            const auto parameter = std::ranges::find(
                chopper->parameters, port,
                &talas::project::ProjectParameterExpression::parameterId);
            require(parameter != chopper->parameters.end(),
                "C161 invalid-fallback fixture should expose selected duration");
            parameter->expression = invalidFallback;
            const auto invalid = talas::runtime::compileProject(
                document,
                talas::core::makeBuiltinNodeRegistry(),
                settings());
            require(!invalid.ok(),
                "C161 connected precedence must not hide wrong-domain or unresolved promoted Chopper fallback authority");
        }
    }

    auto inertDocument = makeConnectedChopperDocument();
    const auto chopper = std::ranges::find(
        inertDocument.graph.nodes,
        std::string_view{"chop"},
        &talas::project::ProjectNode::instanceId);
    require(chopper != inertDocument.graph.nodes.end(),
        "C161 inert-fallback fixture should expose Chopper");
    for (auto& parameter : chopper->parameters)
    {
        if (parameter.parameterId == "grainDuration"
            || parameter.parameterId == "interGrainDelay")
        {
            parameter.expression = "1e308 * 1e308 s";
        }
    }
    const auto inert = talas::runtime::compileProject(
        inertDocument,
        talas::core::makeBuiltinNodeRegistry(),
        settings());
    require(inert.ok(),
        "C161 connected Chopper should suppress only exact inert non-finite numeric fallbacks");
    talas::runtime::RealtimeRenderSession session{*inert.graph};
    std::array<double, 2> output{};
    std::size_t allocations = 0;
    require(session.ready()
            && renderAndCount(session, output, allocations)
            && allocations == 0,
        "C161 connected inputs should own frames after inert fallback suppression: "
            + std::string{session.error()});
}

