void testRealtimeSessionMultiplyingWaveshaperPreservesExtremeFiniteTableEndpointsAndMidpoint()
{
    const auto maximum = std::numeric_limits<double>::max();
    const auto parameters = std::vector<talas::project::ProjectParameterExpression>{
        {"scale", "1"},
        resourceParameter("wavetable", "Tables/Dynamics"),
    };

    talas::runtime::RenderSettings leftSettings{4.0, 2};
    leftSettings.tableResources.push_back(
        {"Tables/Dynamics", {-maximum, maximum}});
    auto leftGraph = compile(makeMultiplyingWaveshaperDocument(
        parameters,
        {{"frequency", "0 hz"}, {"amplitude", "1"}},
        {{"frequency", "1 hz"}, {"amplitude", "1"}}),
        std::move(leftSettings));
    talas::runtime::RealtimeRenderSession leftSession(leftGraph);

    talas::runtime::RenderSettings rightSettings{4.0, 2};
    rightSettings.tableResources.push_back(
        {"Tables/Dynamics", {-maximum, maximum}});
    auto rightGraph = compile(makeMultiplyingWaveshaperDocument(
        parameters,
        {{"frequency", "1 hz"}, {"amplitude", "1"}},
        {{"frequency", "1 hz"}, {"amplitude", "1"}}),
        std::move(rightSettings));
    talas::runtime::RealtimeRenderSession rightSession(rightGraph);

    talas::runtime::RenderSettings midpointSettings{4.0, 2};
    midpointSettings.tableResources.push_back(
        {"Tables/Dynamics", {-maximum, maximum}});
    auto midpointGraph = compile(makeMultiplyingWaveshaperDocument(
        parameters,
        {{"frequency", "1 hz"}, {"amplitude", "0.5"}},
        {{"frequency", "1 hz"}, {"amplitude", "1"}}),
        std::move(midpointSettings));
    talas::runtime::RealtimeRenderSession midpointSession(midpointGraph);
    require(
        leftSession.ready() && rightSession.ready() && midpointSession.ready(),
        "extreme finite prepared MultiplyingWaveshaper fixtures should prepare");

    std::array<double, 2> left{};
    std::array<double, 2> right{};
    std::array<double, 2> midpoint{};
    std::size_t allocations = 0;
    require(
        renderAndCount(leftSession, left, allocations) && allocations == 0
            && renderAndCount(rightSession, right, allocations) && allocations == 0
            && renderAndCount(midpointSession, midpoint, allocations)
            && allocations == 0,
        "extreme finite prepared MultiplyingWaveshaper lookups should render without allocations");
    require(
        std::ranges::all_of(left, [](double sample) {
            return std::isfinite(sample);
        })
            && std::ranges::all_of(right, [](double sample) {
                return std::isfinite(sample);
            })
            && std::ranges::all_of(midpoint, [](double sample) {
                return std::isfinite(sample);
            }),
        "extreme finite prepared MultiplyingWaveshaper lookups should remain finite");
    require(left[1] == -maximum,
        "prepared MultiplyingWaveshaper should preserve the exact left endpoint");
    require(right[1] == maximum,
        "prepared MultiplyingWaveshaper should preserve the exact right endpoint");
    require(midpoint[1] == 0.0,
        "prepared MultiplyingWaveshaper should preserve the exact extreme midpoint");
}

