void testRealtimeSessionMultiplyingWaveshaperConnectedScaleResetAndReplacementExactly()
{
    talas::runtime::RenderSettings settings{8.0, 3};
    settings.tableResources = {
        {"Tables/Dynamics", {-1.0, -0.25, 0.5, 1.0}},
        {"Tables/Scale", {1.0, 0.25, 2.0, 0.5, 1.5, 0.75, 1.0}},
    };
    const auto graph = compile(
        makeConnectedScaleMultiplyingWaveshaperDocument(),
        std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 7);
    require(expected.ok(),
        "connected-scale MultiplyingWaveshaper offline reference should render");
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession replacement(graph);
    require(candidate.ready() && replacement.ready(),
        "connected-scale MultiplyingWaveshaper lifecycle fixtures should prepare");

    std::array<double, 7> partitioned{};
    std::size_t allocations = 0;
    require(
        renderAndCount(
            candidate, std::span<double>{partitioned}.subspan(0, 2), allocations)
            && allocations == 0
            && renderAndCount(
                candidate, std::span<double>{partitioned}.subspan(2, 1), allocations)
            && allocations == 0
            && renderAndCount(
                candidate, std::span<double>{partitioned}.subspan(3, 3), allocations)
            && allocations == 0
            && renderAndCount(
                candidate, std::span<double>{partitioned}.subspan(6, 1), allocations)
            && allocations == 0,
        "connected-scale MultiplyingWaveshaper irregular callbacks should render without allocations");
    require(std::ranges::equal(partitioned, expected.mono),
        "connected-scale MultiplyingWaveshaper partitions should be bit-exact offline");

    candidate.resetTransport();
    std::array<double, 3> reset{};
    std::array<double, 3> replaced{};
    require(
        renderAndCount(candidate, reset, allocations) && allocations == 0
            && renderAndCount(replacement, replaced, allocations) && allocations == 0
            && reset == replaced
            && std::ranges::equal(
                reset, std::span<const double>{expected.mono}.first(3)),
        "connected-scale MultiplyingWaveshaper reset and replacement should be exact");
}

