void testRealtimeSessionMultiplyingWaveshaperPreservesEnclosingFailureIsolation()
{
    auto document = makeMultiplyingWaveshaperDocument({
        {"scale", "0.5"},
        resourceParameter("wavetable", "Tables/Dynamics"),
    });
    const auto terminal = std::ranges::find_if(
        document.graph.connections,
        [](const auto& edge) {
            return edge.fromNode == "shape"
                && edge.fromPort == "audioOut"
                && edge.toNode == "out";
        });
    require(terminal != document.graph.connections.end(),
        "C81 failure fixture should expose its terminal edge");
    terminal->toNode = "c81Level";
    terminal->toPort = "audioIn";
    document.graph.nodes.push_back(node(
        "c81Gain", "talas.constant", {{"value", "!C81Gain"}}));
    document.graph.nodes.push_back(node(
        "c81Level", "talas.level", {
            {"left", "1"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    document.graph.connections.push_back(connection(
        "c81Gain", "value", "c81Level", "left"));
    document.graph.connections.push_back(connection(
        "c81Level", "leftOut", "out", "audioIn"));

    auto candidateSettings = talas::runtime::RenderSettings{4.0, 4};
    candidateSettings.tableResources.push_back(
        {"Tables/Dynamics", {-2.0, 0.0, 2.0}});
    candidateSettings.eventValues.push_back({
        "C81Gain", std::numeric_limits<double>::max(),
        talas::expr::ValueDomain::Scalar});
    auto referenceSettings = talas::runtime::RenderSettings{4.0, 4};
    referenceSettings.tableResources.push_back(
        {"Tables/Dynamics", {-2.0, 0.0, 2.0}});
    referenceSettings.eventValues.push_back({
        "C81Gain", 1.0, talas::expr::ValueDomain::Scalar});
    const auto candidateGraph = compile(document, candidateSettings);
    const auto referenceGraph = compile(document, referenceSettings);
    talas::runtime::RealtimeRenderSession candidate(candidateGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(candidate.ready() && reference.ready(),
        "C81 downstream failure fixtures should prepare");

    std::array<double, 4> rejected{1.0, 1.0, 1.0, 1.0};
    std::size_t allocations = 0;
    require(
        !renderAndCount(candidate, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 4>{},
        "C81 downstream overflow should publish no callback prefix");
    require(
        candidate.updateEventValue(
            "C81Gain", 1.0, talas::expr::ValueDomain::Scalar),
        "C81 downstream gain should recover after rejection");
    std::array<double, 4> recovered{};
    std::array<double, 4> pristine{};
    require(
        renderAndCount(candidate, recovered, allocations) && allocations == 0
            && renderAndCount(reference, pristine, allocations) && allocations == 0
            && recovered == pristine,
        "C81 stateless MultiplyingWaveshaper should preserve enclosing predecessor rollback and retry identity");
}

