void testRealtimeSessionRendersIteratedWaveshaperAcrossBlocksWithoutAllocations()
{
    talas::runtime::RenderSettings settings{4.0, 3};
    settings.tableResources.push_back({"Tables/Dynamics", {-1.0, 0.0, 1.0}});
    auto graph = compile(makeIteratedWaveshaperDocument(), std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 6);
    require(expected.ok(), "offline Iterated Waveshaper reference should render");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 3> first{};
    std::array<double, 3> second{};
    std::size_t allocations = 0;
    require(renderAndCount(session, first, allocations), "first Iterated Waveshaper block should render");
    require(allocations == 0, "first Iterated Waveshaper block should not allocate");
    require(renderAndCount(session, second, allocations), "second Iterated Waveshaper block should render");
    require(allocations == 0, "second Iterated Waveshaper block should not allocate");

    require(expected.mono.size() == first.size() + second.size(), "offline Iterated Waveshaper reference should provide two blocks");
    for (std::size_t frame = 0; frame < first.size(); ++frame)
        requireNear(first[frame], expected.mono[frame], 1.0e-12, "first Iterated Waveshaper block should match offline");
    for (std::size_t frame = 0; frame < second.size(); ++frame)
        requireNear(second[frame], expected.mono[first.size() + frame], 1.0e-12,
                "second Iterated Waveshaper block should match offline");
}

