void testStereoWaveshaperProjectWavRendersIndependentCurves()
{
    const auto directory = std::filesystem::temp_directory_path()
        / ("talas-stereo-waveshaper-"
           + std::to_string(std::chrono::steady_clock::now()
                                .time_since_epoch().count()));
    std::filesystem::create_directories(directory);
    struct RemoveDirectory
    {
        std::filesystem::path path;
        ~RemoveDirectory()
        {
            std::error_code error;
            std::filesystem::remove_all(path, error);
        }
    } cleanup{directory};

    std::string error;
    const std::vector<std::vector<double>> curves{
        {-1.0, 0.0, 1.0}, {1.0, 0.0, -1.0}};
    require(talas::audio::writePcm16Wav(
                directory / "shape.wav", 4.0, curves, error),
        "stereo Waveshaper fixture should write a two-curve WAV: " + error);

    auto document = makeWaveshaperDocument({
        choiceParameter("interpolation", "linear"),
        choiceParameter("shapeFrom", "wavetable"),
        resourceParameter("shapingFunction", "Tables/StereoShape"),
        textParameter("coefficients", "0"),
        booleanParameter("fromMemoryWriter", false),
    });
    document.graph.connections.push_back(connection(
        "shape", "rightOut", "out", "rightIn"));
    document.assets.push_back({
        "Tables/StereoShape", talas::project::ProjectAssetKind::Table,
        "shape.wav"});
    const auto saved = talas::project::serializeProjectDocument(
        document, talas::core::makeBuiltinNodeRegistry());
    const auto reopened = talas::project::parseProjectDocument(saved);
    require(reopened.ok()
                && talas::project::serializeProjectDocument(
                       reopened.document,
                       talas::core::makeBuiltinNodeRegistry()) == saved,
        "stereo Waveshaper Sound should save and reopen byte-stably");
    const auto loaded = talas::audio::loadReferencedProjectResourceSnapshots(
        reopened.document,
        talas::core::makeBuiltinNodeRegistry(),
        directory / "sound.talas.json");
    require(loaded.ok() && loaded.snapshots.size() == 1
                && loaded.snapshots.front()->tableRightSamples.size() == 3,
        "stereo Waveshaper project should retain both immutable curves");

    talas::runtime::RenderSettings settings{4.0, 8};
    settings.resourceSnapshots = loaded.snapshots;
    const auto graph = compile(reopened.document, std::move(settings));
    const auto offline = talas::runtime::renderOffline(graph, 8);
    require(offline.ok() && offline.mono.size() == 8
                && offline.right.size() == 8,
        "stereo Waveshaper should render both offline output channels");
    require(std::abs(offline.mono[1]) > 0.9
                && std::abs(offline.right[1]) > 0.9
                && offline.mono[1] == -offline.right[1],
        "one input should select visibly distinct left and right shaping curves");

    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string{session.error()});
    std::array<double, 3> firstLeft{}, firstRight{};
    std::array<double, 5> secondLeft{}, secondRight{};
    std::size_t allocations = 0;
    require(renderStereoAndCount(
                session, firstLeft, firstRight, allocations)
                && allocations == 0
                && renderStereoAndCount(
                    session, secondLeft, secondRight, allocations)
                && allocations == 0,
        "prepared stereo Waveshaper should render unequal blocks without allocations");
    for (std::size_t frame = 0; frame < offline.mono.size(); ++frame)
    {
        const auto left = frame < firstLeft.size()
            ? firstLeft[frame] : secondLeft[frame - firstLeft.size()];
        const auto right = frame < firstRight.size()
            ? firstRight[frame] : secondRight[frame - firstRight.size()];
        require(left == offline.mono[frame]
                    && right == offline.right[frame],
            "prepared stereo Waveshaper channels should exactly match offline samples");
    }

    auto separatelyDriven = reopened.document;
    separatelyDriven.graph.nodes.push_back(node(
        "rightOsc", "talas.oscillator",
        {{"frequency", "1 hz"}, {"amplitude", "0.25"}}));
    separatelyDriven.graph.connections.push_back(connection(
        "rightOsc", "audioOut", "shape", "rightIn"));
    talas::runtime::RenderSettings rightInputSettings{4.0, 8};
    rightInputSettings.resourceSnapshots = loaded.snapshots;
    const auto rightInputGraph = compile(
        separatelyDriven, std::move(rightInputSettings));
    const auto rightInputOffline = talas::runtime::renderOffline(
        rightInputGraph, 8);
    require(rightInputOffline.ok()
                && rightInputOffline.right.size() == 8
                && rightInputOffline.right[1] < -0.24
                && rightInputOffline.right[1] > -0.26
                && rightInputOffline.mono[1] == offline.mono[1],
        "optional right input should index the right curve independently");
    talas::runtime::RealtimeRenderSession rightInputSession(rightInputGraph);
    require(rightInputSession.ready(), std::string{rightInputSession.error()});
    std::array<double, 8> independentLeft{}, independentRight{};
    require(renderStereoAndCount(
                rightInputSession,
                independentLeft, independentRight, allocations)
                && allocations == 0
                && std::ranges::equal(
                    independentLeft, rightInputOffline.mono)
                && std::ranges::equal(
                    independentRight, rightInputOffline.right),
        "independent right input should match offline output without allocations");
}

