void testRealtimeSessionInputOutputCharacteristicPreservesEndpointFmaRounding()
{
    constexpr auto firstInput = -0.000000007450580596923828125;
    constexpr auto firstOutput = -1.0;
    constexpr auto startSlope = -1.000000007450580596923828125;
    const auto expected = std::fma(
        startSlope, -1.0 - firstInput, firstOutput);
    require(std::bit_cast<std::uint64_t>(expected)
            == std::uint64_t{0xbc90000000000000},
        "C82 endpoint FMA rounding oracle should retain negative 2^-54");

    auto document = makeInputOutputCharacteristicDocument({
        textParameter("inValues", "-0.000000007450580596923828125"),
        textParameter("outValues", "-1"),
        {"smoothing", "0.5"},
        {"startSlope", "-1.000000007450580596923828125"},
        {"endSlope", "0"},
    });
    const auto source = std::ranges::find(
        document.graph.nodes, std::string_view{"osc"},
        &talas::project::ProjectNode::instanceId);
    require(source != document.graph.nodes.end(),
        "C82 endpoint rounding fixture should expose its source");
    source->typeId = "talas.noise";
    source->parameters = {
        {"initialState", "-1"},
        {"frequency", "0 hz"},
        {"centerValue", "0"},
        {"scale", "1"},
    };

    talas::runtime::RenderSettings settings{8.0, 1};
    const auto graph = compile(document, std::move(settings));
    const auto offline = talas::runtime::renderOffline(graph, 1);
    talas::runtime::RealtimeRenderSession session(graph);
    require(offline.ok() && offline.mono.size() == 1 && session.ready(),
        "C82 endpoint rounding fixtures should prepare");
    std::array<double, 1> realtime{};
    std::size_t allocations = 0;
    require(renderAndCount(session, realtime, allocations) && allocations == 0,
        "C82 endpoint rounding fixture should render without allocations");
    require(std::bit_cast<std::uint64_t>(offline.mono[0])
                == std::bit_cast<std::uint64_t>(expected)
            && std::bit_cast<std::uint64_t>(realtime[0])
                == std::bit_cast<std::uint64_t>(expected),
        "C82 endpoint synthesis should preserve the frozen FMA bit pattern");
}

void testRealtimeSessionInputOutputCharacteristicPartitionsResetAndReplacementExactly()
{
    talas::runtime::RenderSettings settings{12.0, 4};
    const auto graph = compile(makeInputOutputCharacteristicDocument({
        textParameter("inValues", "-1 -0.25 0.5 1"),
        textParameter("outValues", "-0.75 0.5 -0.25 1"),
        {"smoothing", "0.8"},
        {"startSlope", "0.25"},
        {"endSlope", "-0.5"},
    }), std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 9);
    require(expected.ok(),
        "Input Output Characteristic lifecycle reference should render");
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession replacement(graph);
    talas::runtime::RealtimeRenderSession restaged(graph);
    require(candidate.ready() && replacement.ready() && restaged.ready(),
        "Input Output Characteristic lifecycle fixtures should prepare");

    std::array<double, 9> partitioned{};
    std::size_t allocations = 0;
    require(
        renderAndCount(candidate, std::span<double>{partitioned}.subspan(0, 2), allocations)
            && allocations == 0
            && renderAndCount(candidate, std::span<double>{partitioned}.subspan(2, 1), allocations)
            && allocations == 0
            && renderAndCount(candidate, std::span<double>{partitioned}.subspan(3, 4), allocations)
            && allocations == 0
            && renderAndCount(candidate, std::span<double>{partitioned}.subspan(7, 2), allocations)
            && allocations == 0,
        "Input Output Characteristic irregular callbacks should render without allocations");
    require(std::ranges::equal(partitioned, expected.mono),
        "Input Output Characteristic partitions should be bit-exact offline");

    candidate.resetTransport();
    std::array<double, 4> reset{};
    std::array<double, 4> replaced{};
    std::array<double, 4> restagedOutput{};
    require(
        renderAndCount(candidate, reset, allocations) && allocations == 0
            && renderAndCount(replacement, replaced, allocations) && allocations == 0
            && renderAndCount(restaged, restagedOutput, allocations)
            && allocations == 0
            && reset == replaced
            && replaced == restagedOutput
            && std::ranges::equal(
                reset, std::span<const double>{expected.mono}.first(4)),
        "stateless Input Output Characteristic reset/replacement/restage should be exact");
}

void testRealtimeSessionOwnsInputOutputCharacteristicBreakpointSnapshot()
{
    talas::runtime::RenderSettings settings{8.0, 5};
    auto graph = compile(makeInputOutputCharacteristicDocument({
        textParameter("inValues", "-1 -0.25 0.5 1"),
        textParameter("outValues", "-0.75 0.5 -0.25 1"),
        {"smoothing", "0.8"},
        {"startSlope", "0.25"},
        {"endSlope", "-0.5"},
    }), std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 5);
    require(expected.ok(),
        "Input Output Characteristic ownership reference should render");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    auto& plan = const_cast<talas::runtime::RuntimePlan&>(graph.plan());
    const auto mapper = std::ranges::find(
        plan.steps, std::string_view{"talas.inputOutputCharacteristic"},
        &talas::runtime::CompileStep::typeId);
    require(mapper != plan.steps.end(),
        "ownership fixture should expose Input Output Characteristic");
    const auto inValues = std::ranges::find(
        mapper->parameters, std::string_view{"inValues"},
        &talas::runtime::ParameterValue::id);
    const auto outValues = std::ranges::find(
        mapper->parameters, std::string_view{"outValues"},
        &talas::runtime::ParameterValue::id);
    const auto smoothing = std::ranges::find(
        mapper->parameters, std::string_view{"smoothing"},
        &talas::runtime::ParameterValue::id);
    const auto startSlope = std::ranges::find(
        mapper->parameters, std::string_view{"startSlope"},
        &talas::runtime::ParameterValue::id);
    const auto endSlope = std::ranges::find(
        mapper->parameters, std::string_view{"endSlope"},
        &talas::runtime::ParameterValue::id);
    require(
        inValues != mapper->parameters.end() && inValues->text.has_value()
            && outValues != mapper->parameters.end() && outValues->text.has_value()
            && smoothing != mapper->parameters.end()
            && startSlope != mapper->parameters.end()
            && endSlope != mapper->parameters.end(),
        "ownership fixture should expose curve settings");
    inValues->text = "-1 1";
    outValues->text = "1 -1";
    smoothing->value = 0.0;
    startSlope->value = std::numeric_limits<double>::max();
    endSlope->value = -std::numeric_limits<double>::max();

    std::array<double, 5> output{};
    std::size_t allocations = 0;
    require(
        renderAndCount(session, output, allocations) && allocations == 0,
        "prepared Input Output Characteristic should render from its owned curve snapshot");
    require(std::ranges::equal(output, expected.mono),
        "caller plan mutation should not alter prepared Input Output Characteristic output");
}

void testRealtimeSessionInputOutputCharacteristicPreservesEnclosingFailureIsolation()
{
    auto document = makeInputOutputCharacteristicDocument({
        textParameter("inValues", "-1 0 1"),
        textParameter("outValues", "-1 0 1"),
        {"smoothing", "0.5"},
        {"startSlope", "0"},
        {"endSlope", "0"},
    });
    const auto terminal = std::ranges::find_if(
        document.graph.connections,
        [](const auto& edge) {
            return edge.fromNode == "mapper"
                && edge.fromPort == "audioOut"
                && edge.toNode == "out";
        });
    require(terminal != document.graph.connections.end(),
        "C82 failure fixture should expose its terminal edge");
    terminal->toNode = "firstLevel";
    terminal->toPort = "audioIn";
    document.graph.nodes.push_back(node("gain", "talas.constant", {
        {"value", "!C82Gain"},
    }));
    document.graph.nodes.push_back(node(
        "gainHold", "talas.triggeredSampleAndHold", {{"trigger", "1"}}));
    document.graph.nodes.push_back(node("firstLevel", "talas.level", {
        {"left", "1"}, {"right", "0"},
        booleanParameter("noGain", false),
    }));
    document.graph.nodes.push_back(node("secondLevel", "talas.level", {
        {"left", "2"}, {"right", "0"},
        booleanParameter("noGain", false),
    }));
    document.graph.connections.push_back(connection(
        "gain", "value", "gainHold", "value"));
    document.graph.connections.push_back(connection(
        "gainHold", "value", "firstLevel", "left"));
    document.graph.connections.push_back(connection(
        "firstLevel", "leftOut", "secondLevel", "audioIn"));
    document.graph.connections.push_back(connection(
        "secondLevel", "leftOut", "out", "audioIn"));

    auto candidateSettings = talas::runtime::RenderSettings{4.0, 2};
    candidateSettings.eventValues.push_back({
        "C82Gain", std::numeric_limits<double>::max(),
        talas::expr::ValueDomain::Scalar});
    auto referenceSettings = talas::runtime::RenderSettings{4.0, 2};
    referenceSettings.eventValues.push_back({
        "C82Gain", 1.0, talas::expr::ValueDomain::Scalar});
    const auto candidateGraph = compile(document, candidateSettings);
    const auto referenceGraph = compile(document, referenceSettings);
    talas::runtime::RealtimeRenderSession candidate(candidateGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(candidate.ready() && reference.ready(),
        "C82 downstream failure fixtures should prepare");

    std::array<double, 2> rejected{1.0, 1.0};
    std::size_t allocations = 0;
    require(
        !renderAndCount(candidate, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 2>{},
        "C82 downstream overflow should publish no callback prefix");
    require(candidate.updateEventValue(
        "C82Gain", 1.0, talas::expr::ValueDomain::Scalar),
        "C82 downstream gain should recover after rejection");
    std::array<double, 2> recovered{};
    std::array<double, 2> pristine{};
    require(
        renderAndCount(candidate, recovered, allocations) && allocations == 0
            && renderAndCount(reference, pristine, allocations) && allocations == 0
            && recovered == pristine,
        "C82 stateless curve should preserve enclosing predecessor rollback and retry identity: recovered="
            + std::to_string(recovered[0]) + "," + std::to_string(recovered[1])
            + " pristine=" + std::to_string(pristine[0]) + "," + std::to_string(pristine[1]));
}

