void testRealtimeSessionRendersLinearPulseGeneratorAcrossBlocksWithoutAllocations()
{
    talas::runtime::RenderSettings settings{8.0, 4};
    auto graph = compile(makePulseGeneratorDocument({
        {"frequency", "1 hz"},
        textParameter("modulation", ""),
        {"maxMI", "0"},
        choiceParameter("interpolation", "linear"),
        {"envelope", "1"},
        {"dutyCycle", "0.25"},
        {"reset", "0"},
    }), std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 8);
    require(expected.ok(), "offline linear PulseGenerator reference should render");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 4> first{};
    std::array<double, 4> second{};
    std::size_t allocations = 0;
    require(renderAndCount(session, first, allocations), "first linear PulseGenerator block should render");
    require(allocations == 0, "first linear PulseGenerator block should not allocate");
    require(renderAndCount(session, second, allocations), "second linear PulseGenerator block should render");
    require(allocations == 0, "second linear PulseGenerator block should not allocate");

    for (std::size_t frame = 0; frame < first.size(); ++frame)
        requireNear(first[frame], expected.mono[frame], 1.0e-12, "first linear PulseGenerator block should match offline");
    for (std::size_t frame = 0; frame < second.size(); ++frame)
        requireNear(second[frame], expected.mono[first.size() + frame], 1.0e-12,
                "second linear PulseGenerator block should preserve offline-equivalent phase");
}

