void testCheckedGrainCloudArithmeticAndHighFrameRejectionAreAtomic()
{
    double exactFrame = 0.0;
    constexpr auto twoTo53 = std::uint64_t{1} << 53U;
    require(talas::runtime::checked_grain_cloud::exactAbsoluteFrameAsDouble(
                twoTo53, exactFrame)
            && exactFrame == 0x1p53,
        "C113 checked GrainCloud should accept exact 2^53 frame identity");
    require(!talas::runtime::checked_grain_cloud::exactAbsoluteFrameAsDouble(
                twoTo53 + 1, exactFrame),
        "C113 checked GrainCloud should reject inexact 2^53 + 1 frame identity");
    require(talas::runtime::checked_grain_cloud::exactAbsoluteFrameAsDouble(
                twoTo53 + 2, exactFrame)
            && exactFrame == 0x1.0000000000001p53,
        "C113 checked GrainCloud should accept exact 2^53 + 2 frame identity");

    const std::array waveform{
        std::numeric_limits<double>::max()};
    const std::array envelope{2.0};
    auto candidate = talas::runtime::checked_grain_cloud::StereoFrame{
        0.25, -0.25};
    const auto before = candidate;
    require(talas::runtime::checked_grain_cloud::mixGrain(
                waveform,
                envelope,
                {0, 0.0},
                {1.0, 0.5, 1.0, 1.0, 1.0, 1, 0.0, 0.0, 0.0},
                {4.0, 1.0, 0.0, 0.0},
                candidate)
                == talas::runtime::checked_grain_cloud::Error::OutputNonFinite
            && candidate == before,
        "C113 checked GrainCloud output overflow should preserve candidate publication state");

    auto cycleBoundary = talas::runtime::checked_grain_cloud::StereoFrame{};
    require(talas::runtime::checked_grain_cloud::mixGrain(
                std::array{1.0},
                std::array{1.0},
                {0, 0.0},
                {1.0, 0.5, 5.570776895428878, 0.0,
                    1.0, 1, 0.0, 0.0, 0.0},
                {96000.0, 0.4113090274458322, 0.0, 7088.0},
                cycleBoundary)
                == talas::runtime::checked_grain_cloud::Error::None
            && cycleBoundary.left != 0.0
            && cycleBoundary.right != 0.0,
        "C113 cycle-derived duration should preserve the prepared multiply-before-divide half-open boundary");

    auto graph = compile(
        makeGrainCloudRealtimeDocument(),
        grainCloudRealtimeSettings(1));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(),
        "C113 high-frame GrainCloud fixture should prepare: "
            + std::string{session.error()});
    require(talas::runtime::RealtimeRenderSessionTestAccess::
                setGrainCloudRenderedFrames(session, twoTo53 + 1),
        "C113 high-frame fixture should set the GrainCloud cursor");
    const auto beforeCursor =
        talas::runtime::RealtimeRenderSessionTestAccess::
            grainCloudRenderedFrames(session);
    std::array<double, 1> left{1.0};
    std::array<double, 1> right{1.0};
    std::size_t allocations = 0;
    require(!renderStereoAndCount(session, left, right, allocations)
            && allocations == 0
            && left == std::array<double, 1>{}
            && right == std::array<double, 1>{}
            && talas::runtime::RealtimeRenderSessionTestAccess::
                    grainCloudRenderedFrames(session)
                == beforeCursor,
        "C113 prepared GrainCloud should reject an inexact cursor without output, allocation, or state publication");
}

void testRealtimeGrainCloudRetainsCurrentEligibleCrossingParityPastCapacity()
{
    auto document = makeGrainCloudRealtimeDocument(
        grainCloudRealtimeParameters({
            {"amplitude", "1"}, {"density", "1"},
            {"grainDur", "4 s"}, {"cyclesPerGrain", "0"},
            {"frequency", "1 hz"}, {"maxGrains", "1"},
            {"panJitter", "0.5"}, {"seed", "0.25"},
        }));
    document.graph.nodes.push_back(node(
        "densityControl", "talas.triggeredTableRead", {
            {"trigger", "1"},
            resourceParameter("wavetable", "Tables/C113CapacityDensity"),
            {"gate", "1"},
            booleanParameter("ignoreLoops", true),
            booleanParameter("fromMemoryWriter", false),
        }));
    document.graph.nodes.push_back(node(
        "maxGrainsControl", "talas.constant", {{"value", "1"}}));
    document.graph.connections.push_back(connection(
        "densityControl", "value", "cloud", "density"));
    document.graph.connections.push_back(connection(
        "maxGrainsControl", "value", "cloud", "maxGrains"));

    auto settings = grainCloudRealtimeSettings(2);
    settings.sampleRate = 1.0;
    settings.tableResources[0].samples = {1.0};
    settings.tableResources[1].samples = {1.0};
    settings.tableResources.push_back({
        "Tables/C113CapacityDensity",
        {std::nextafter(1.0, 0.0), 65.0},
    });
    const auto graph = compile(document, std::move(settings));
    talas::runtime::OfflineRenderSession offline(graph);
    talas::runtime::RealtimeRenderSession realtime(graph);
    require(realtime.ready(),
        "C113 capacity-crossing GrainCloud fixture should prepare: "
            + std::string{realtime.error()});

    const auto expected = offline.render(2);
    std::array<double, 2> left{};
    std::array<double, 2> right{};
    std::size_t allocations = 0;
    require(expected.ok()
            && renderStereoAndCount(realtime, left, right, allocations)
            && allocations == 0
            && std::ranges::equal(left, expected.mono)
            && std::ranges::equal(right, expected.right),
        "C113 offline and prepared GrainCloud should choose the same eligible current crossing beyond retained capacity");
}

