void testRealtimeGrainCloudAllDynamicControlsArePartitionInvariant()
{
    auto document = makeGrainCloudRealtimeDocument(
        grainCloudRealtimeParameters({
            {"amplitude", "0.25"},
            {"density", "4"},
            {"grainDur", "4 s"},
            {"cyclesPerGrain", "0"},
            {"frequency", "1 hz"},
            {"maxGrains", "1"},
            {"pan", "0.5"},
            {"seed", "0.25"},
        }));
    const std::array controls = {
        std::pair{std::string_view{"amplitude"},
            std::string_view{"Tables/C113Amplitude"}},
        std::pair{std::string_view{"pan"},
            std::string_view{"Tables/C113Pan"}},
        std::pair{std::string_view{"frequency"},
            std::string_view{"Tables/C113Frequency"}},
        std::pair{std::string_view{"grainDur"},
            std::string_view{"Tables/C113Duration"}},
        std::pair{std::string_view{"density"},
            std::string_view{"Tables/C113Density"}},
        std::pair{std::string_view{"maxGrains"},
            std::string_view{"Tables/C113MaxGrains"}},
        std::pair{std::string_view{"panJitter"},
            std::string_view{"Tables/C113PanJitter"}},
        std::pair{std::string_view{"grainDurJitter"},
            std::string_view{"Tables/C113DurationJitter"}},
        std::pair{std::string_view{"freqJitter"},
            std::string_view{"Tables/C113FrequencyJitter"}},
    };
    for (const auto& [port, resource] : controls)
    {
        const auto source = "dynamic_" + std::string{port};
        document.graph.nodes.push_back(node(
            source,
            "talas.triggeredTableRead",
            {
                {"trigger", "1"},
                resourceParameter("wavetable", std::string{resource}),
                {"gate", "1"},
                booleanParameter("ignoreLoops", true),
                booleanParameter("fromMemoryWriter", false),
            }));
        document.graph.connections.push_back(connection(
            source, "value", "cloud", std::string{port}));
    }

    auto settings = grainCloudRealtimeSettings(12);
    settings.tableResources[0].samples = {1.0};
    settings.tableResources[1].samples = {1.0};
    settings.tableResources.push_back({"Tables/C113Amplitude",
        {0.25, 0.5, 0.75, 1.0, 0.5, 0.25, 1.0, 0.75, 0.5, 1.0, 0.25, 0.75}});
    settings.tableResources.push_back({"Tables/C113Pan",
        {0.0, 0.25, 0.5, 0.75, 1.0, 0.75, 0.5, 0.25, 0.0, 0.5, 1.0, 0.5}});
    settings.tableResources.push_back({"Tables/C113Frequency",
        {1.0, 2.0, 1.0, 0.5, 2.0, 1.0, 0.5, 1.0, 2.0, 1.0, 0.5, 1.0}});
    settings.tableResources.push_back({"Tables/C113Duration",
        {4.0, 3.0, 4.0, 2.0, 3.0, 4.0, 2.0, 3.0, 4.0, 2.0, 3.0, 4.0}});
    settings.tableResources.push_back({"Tables/C113Density",
        {4.0, 8.0, 4.0, 8.0, 2.0, 4.0, 8.0, 4.0, 2.0, 8.0, 4.0, 8.0}});
    settings.tableResources.push_back({"Tables/C113MaxGrains",
        {1.0, 1.0, 1.0, 1.0, 4.0, 4.0, 8.0, 8.0, 2.0, 2.0, 8.0, 8.0}});
    settings.tableResources.push_back({"Tables/C113PanJitter",
        {0.0, 0.1, 0.2, 0.1, 0.0, 0.2, 0.1, 0.0, 0.2, 0.1, 0.0, 0.2}});
    settings.tableResources.push_back({"Tables/C113DurationJitter",
        {0.0, 0.2, 0.1, 0.0, 0.1, 0.2, 0.0, 0.2, 0.1, 0.0, 0.1, 0.2}});
    settings.tableResources.push_back({"Tables/C113FrequencyJitter",
        {0.0, 0.1, 0.0, 0.2, 0.1, 0.0, 0.2, 0.1, 0.0, 0.2, 0.1, 0.0}});

    const auto graph = compile(document, std::move(settings));
    talas::runtime::OfflineRenderSession offlineOneShot(graph);
    talas::runtime::OfflineRenderSession offlinePartitioned(graph);
    talas::runtime::RealtimeRenderSession realtimeOneShot(graph);
    talas::runtime::RealtimeRenderSession realtimePartitioned(graph);
    require(realtimeOneShot.ready() && realtimePartitioned.ready(),
        "C113 all-control GrainCloud fixtures should prepare: "
            + std::string{realtimeOneShot.error()});

    const auto expected = offlineOneShot.render(12);
    std::array<double, 12> expectedLeft{};
    std::array<double, 12> expectedRight{};
    std::size_t allocations = 0;
    require(expected.ok(),
        "C113 one-shot offline dynamic GrainCloud should render");
    require(renderStereoAndCount(
                realtimeOneShot,
                expectedLeft,
                expectedRight,
                allocations)
            && allocations == 0,
        "C113 one-shot prepared dynamic GrainCloud should render without allocation");
    for (std::size_t frame = 0; frame < expectedLeft.size(); ++frame)
    {
        requireNear(expectedLeft[frame], expected.mono[frame], 1.0e-12,
            "C113 one-shot dynamic GrainCloud left should match offline at frame "
                + std::to_string(frame));
        requireNear(expectedRight[frame], expected.right[frame], 1.0e-12,
            "C113 one-shot dynamic GrainCloud right should match offline at frame "
                + std::to_string(frame));
    }

    std::array<double, 12> offlineLeft{};
    std::array<double, 12> offlineRight{};
    std::array<double, 12> realtimeLeft{};
    std::array<double, 12> realtimeRight{};
    std::size_t offset = 0;
    for (const auto frames : {
             std::size_t{3}, std::size_t{1}, std::size_t{4},
             std::size_t{2}, std::size_t{2}})
    {
        const auto offlineBlock = offlinePartitioned.render(frames);
        std::span<double> left{realtimeLeft};
        std::span<double> right{realtimeRight};
        allocations = 0;
        require(offlineBlock.ok()
                && renderStereoAndCount(
                    realtimePartitioned,
                    left.subspan(offset, frames),
                    right.subspan(offset, frames),
                    allocations)
                && allocations == 0,
            "C113 irregular dynamic GrainCloud partition should render without allocation");
        std::ranges::copy(
            offlineBlock.mono,
            offlineLeft.begin() + static_cast<std::ptrdiff_t>(offset));
        std::ranges::copy(
            offlineBlock.right,
            offlineRight.begin() + static_cast<std::ptrdiff_t>(offset));
        offset += frames;
    }
    for (std::size_t frame = 0; frame < expectedLeft.size(); ++frame)
    {
        requireNear(offlineLeft[frame], expectedLeft[frame], 1.0e-12,
            "C113 partitioned offline GrainCloud left should match one-shot at frame "
                + std::to_string(frame));
        requireNear(offlineRight[frame], expectedRight[frame], 1.0e-12,
            "C113 partitioned offline GrainCloud right should match one-shot at frame "
                + std::to_string(frame));
        requireNear(realtimeLeft[frame], expectedLeft[frame], 1.0e-12,
            "C113 partitioned prepared GrainCloud left should match one-shot at frame "
                + std::to_string(frame));
        requireNear(realtimeRight[frame], expectedRight[frame], 1.0e-12,
            "C113 partitioned prepared GrainCloud right should match one-shot at frame "
                + std::to_string(frame));
    }
}

void testRealtimeGrainCloudRejectsEveryInvalidConnectedControlAtomically()
{
    struct InvalidControl
    {
        std::string_view port;
        double validValue;
        double invalidValue;
        bool requiresOverflowProducer = false;
        std::string_view contract;
    };
    const std::array controls = {
        InvalidControl{"amplitude", -1.0e308, 1.0e308, true,
            "finite amplitude"},
        InvalidControl{"pan", 0.5, -0.125, false,
            "pan in [0,1]"},
        InvalidControl{"frequency", 1.0, -1.0, false,
            "non-negative frequency"},
        InvalidControl{"grainDur", 1.0, -1.0, false,
            "non-negative duration"},
        InvalidControl{"density", 1.0, -1.0, false,
            "non-negative density"},
        InvalidControl{"maxGrains", 4.0, 1.5, false,
            "integer maximum grains"},
        InvalidControl{"maxGrains", 4.0, 65.0, false,
            "bounded maximum grains"},
        InvalidControl{"panJitter", 0.0, -1.0, false,
            "non-negative pan jitter"},
        InvalidControl{"grainDurJitter", 0.0, -1.0, false,
            "non-negative duration jitter"},
        InvalidControl{"freqJitter", 0.0, -1.0, false,
            "non-negative frequency jitter"},
    };
    const std::array<std::size_t, 3> invalidFrames{0, 2, 3};

    for (const auto& control : controls)
    {
        for (const auto invalidFrame : invalidFrames)
        {
            auto document = makeGrainCloudRealtimeDocument(
                grainCloudRealtimeParameters({
                    {"amplitude", "0.25"},
                    {"cyclesPerGrain", "0"},
                    {"density", "2"},
                    {"frequency", "1 hz"},
                    {"grainDur", "1 s"},
                    {"maxGrains", "4"},
                }));
            document.graph.nodes.push_back(node(
                "invalidControl", "talas.triggeredTableRead", {
                    {"trigger", "1"},
                    resourceParameter(
                        "wavetable", "Tables/C113InvalidControl"),
                    {"gate", "1"},
                    booleanParameter("ignoreLoops", true),
                    booleanParameter("fromMemoryWriter", false),
                }));
            auto sourceNode = std::string{"invalidControl"};
            if (control.requiresOverflowProducer)
            {
                document.graph.nodes.push_back(node(
                    "overflowFactor", "talas.constant", {{"value", "1e308"}}));
                document.graph.nodes.push_back(node(
                    "invalidProduct", "talas.add"));
                document.graph.connections.push_back(connection(
                    "invalidControl", "value", "invalidProduct", "left"));
                document.graph.connections.push_back(connection(
                    "overflowFactor", "value", "invalidProduct", "right"));
                sourceNode = "invalidProduct";
            }
            document.graph.connections.push_back(connection(
                sourceNode, "value", "cloud", std::string{control.port}));

            auto settings = grainCloudRealtimeSettings(4);
            std::vector<double> values(4, control.validValue);
            values[invalidFrame] = control.invalidValue;
            settings.tableResources.push_back(
                {"Tables/C113InvalidControl", std::move(values)});
            talas::runtime::RealtimeRenderSession session(
                compile(document, std::move(settings)));
            require(session.ready(),
                "C113 invalid connected control fixture should prepare: "
                    + std::string{control.port} + ": "
                    + std::string{session.error()});

            std::array<double, 4> left{1.0, 1.0, 1.0, 1.0};
            std::array<double, 4> right{1.0, 1.0, 1.0, 1.0};
            std::size_t allocations = 0;
            require(!renderStereoAndCount(
                        session, left, right, allocations)
                    && allocations == 0
                    && left == std::array<double, 4>{}
                    && right == std::array<double, 4>{},
                "C113 connected " + std::string{control.contract}
                    + " should reject atomically at frame "
                    + std::to_string(invalidFrame));
        }
    }
}

void testRealtimeGrainCloudDownstreamRetryRestoresExactSchedulerState()
{
    const auto makeRetryGraph = [] {
        auto settings = grainCloudRealtimeSettings(2);
        settings.tableResources[0].samples = {1.0};
        settings.tableResources[1].samples = {1.0};
        settings.eventValues = {
            {"C113RetryGain", 1.0, talas::expr::ValueDomain::Scalar},
        };
        auto document = makeGrainCloudRealtimeDocument(
            grainCloudRealtimeParameters({
                {"amplitude", "1"},
                {"cyclesPerGrain", "0"},
                {"density", "2"},
                {"frequency", "1 hz"},
                {"grainDur", "10 s"},
                {"maxGrains", "4"},
                {"pan", "0"},
            }));
        document.graph.nodes.push_back(node(
            "level", "talas.level", {
                {"left", "!C113RetryGain"},
                {"right", "1"},
                booleanParameter("noGain", false),
            }));
        document.graph.connections.clear();
        document.graph.connections.push_back(connection(
            "cloud", "leftOut", "level", "audioIn"));
        document.graph.connections.push_back(connection(
            "level", "leftOut", "out", "audioIn"));
        document.graph.connections.push_back(connection(
            "level", "rightOut", "out", "rightIn"));
        return compile(document, std::move(settings));
    };

    talas::runtime::RealtimeRenderSession candidate(makeRetryGraph());
    talas::runtime::RealtimeRenderSession pristine(makeRetryGraph());
    require(candidate.ready() && pristine.ready(),
        "C113 downstream-retry GrainCloud fixtures should prepare: "
            + std::string{candidate.error()});

    std::array<double, 2> candidateLeft{};
    std::array<double, 2> candidateRight{};
    std::array<double, 2> pristineLeft{};
    std::array<double, 2> pristineRight{};
    std::size_t candidateAllocations = 0;
    std::size_t pristineAllocations = 0;
    require(renderStereoAndCount(
                candidate, candidateLeft, candidateRight,
                candidateAllocations)
            && renderStereoAndCount(
                pristine, pristineLeft, pristineRight,
                pristineAllocations)
            && candidateAllocations == 0
            && pristineAllocations == 0
            && candidateLeft == pristineLeft
            && candidateRight == pristineRight,
        "C113 downstream-retry fixtures should establish identical GrainCloud state");

    require(candidate.updateEventValue(
                "C113RetryGain",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C113 candidate should accept the downstream-failure Event Value");
    candidateLeft.fill(1.0);
    candidateRight.fill(1.0);
    require(!renderStereoAndCount(
                candidate, candidateLeft, candidateRight,
                candidateAllocations)
            && candidateAllocations == 0
            && candidateLeft == std::array<double, 2>{}
            && candidateRight == std::array<double, 2>{},
        "C113 downstream failure should publish no GrainCloud output");
    require(candidate.updateEventValue(
                "C113RetryGain", 1.0,
                talas::expr::ValueDomain::Scalar),
        "C113 candidate should accept the repaired downstream Event Value");
    require(renderStereoAndCount(
                candidate, candidateLeft, candidateRight,
                candidateAllocations)
            && renderStereoAndCount(
                pristine, pristineLeft, pristineRight,
                pristineAllocations)
            && candidateAllocations == 0
            && pristineAllocations == 0
            && candidateLeft == pristineLeft
            && candidateRight == pristineRight,
        "C113 repaired downstream retry should restore exact GrainCloud scheduler, retention, and cursor state");
}

