void testRealtimeGrainCloudResetAndDiscontinuityAreFreshEquivalent()
{
    auto document = makeGrainCloudRealtimeDocument(
        grainCloudRealtimeParameters({
            {"amplitude", "1"},
            {"cyclesPerGrain", "0"},
            {"density", "4"},
            {"frequency", "1 hz"},
            {"grainDur", "10 s"},
            {"maxGrains", "1"},
        }));
    document.graph.nodes.push_back(node(
        "maxGrainsControl", "talas.triggeredTableRead", {
            {"trigger", "1"},
            resourceParameter("wavetable", "Tables/C113LifecycleMax"),
            {"gate", "1"},
            booleanParameter("ignoreLoops", true),
            booleanParameter("fromMemoryWriter", false),
        }));
    document.graph.connections.push_back(connection(
        "maxGrainsControl", "value", "cloud", "maxGrains"));
    auto settings = grainCloudRealtimeSettings(2);
    settings.tableResources[0].samples = {1.0};
    settings.tableResources[1].samples = {1.0};
    settings.tableResources.push_back(
        {"Tables/C113LifecycleMax", {1.0, 1.0, 4.0, 4.0}});
    const auto graph = compile(document, settings);

    talas::runtime::RealtimeRenderSession resetCandidate(graph);
    talas::runtime::RealtimeRenderSession fresh(graph);
    std::array<double, 2> prefixLeft{};
    std::array<double, 2> prefixRight{};
    std::size_t allocations = 0;
    require(resetCandidate.ready() && fresh.ready()
            && renderStereoAndCount(
                resetCandidate, prefixLeft, prefixRight, allocations)
            && allocations == 0,
        "C113 lifecycle fixture should establish progressed GrainCloud state");
    resetCandidate.resetTransport();
    std::array<double, 2> actualLeft{};
    std::array<double, 2> actualRight{};
    std::array<double, 2> expectedLeft{};
    std::array<double, 2> expectedRight{};
    require(renderStereoAndCount(
                resetCandidate, actualLeft, actualRight, allocations)
            && renderStereoAndCount(
                fresh, expectedLeft, expectedRight, allocations)
            && allocations == 0
            && actualLeft == expectedLeft
            && actualRight == expectedRight,
        "C113 reset should restore complete dynamic GrainCloud state to fresh identity");

    talas::runtime::RealtimeRenderSession discontinuous(graph);
    talas::runtime::RealtimeRenderSession discontinuityFresh(graph);
    require(discontinuous.ready() && discontinuityFresh.ready()
            && renderStereoAndCount(
                discontinuous, prefixLeft, prefixRight, allocations),
        "C113 discontinuity fixture should progress before replacement");
    const talas::runtime::RealtimeTransportSnapshot discontinuity{
        .epoch = 1,
        .absoluteFrame = 2,
        .playheadFrame = 2,
        .sampleRate = 4.0,
        .loopStartFrame = 0,
        .loopEndFrame = 0,
        .discontinuitySequence = 1,
        .playing = true,
        .loopEnabled = false,
    };
    discontinuous.setTransportSnapshotBeforeRender(discontinuity);
    discontinuityFresh.setTransportSnapshotBeforeRender(discontinuity);
    require(renderStereoAndCount(
                discontinuous, actualLeft, actualRight, allocations)
            && renderStereoAndCount(
                discontinuityFresh, expectedLeft, expectedRight, allocations)
            && allocations == 0
            && actualLeft == expectedLeft
            && actualRight == expectedRight,
        "C113 discontinuity should reset complete GrainCloud state identically to fresh replacement");
}

void testRealtimeGrainCloudRejectsProfilesOutsideStaticBound()
{
    {
        auto graph = compile(
            makeGrainCloudRealtimeDocument(
                grainCloudRealtimeParameters({
                    {"maxGrains", "64"}, {"density", "256"}})),
            grainCloudRealtimeSettings());
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(), std::string(session.error()));
        std::array<double, 1> left{};
        std::array<double, 1> right{};
        std::size_t allocations = 0;
        require(renderStereoAndCount(session, left, right, allocations)
                && allocations == 0,
            "maximum GrainCloud scheduler saturation should remain allocation-free");
    }
    {
        auto graph = compile(
            makeGrainCloudRealtimeDocument(
                grainCloudRealtimeParameters({{"maxGrains", "65"}})),
            grainCloudRealtimeSettings());
        talas::runtime::RealtimeRenderSession session(graph);
        require(!session.ready(),
            "prepared realtime GrainCloud should reject more than 64 grains");
    }
    {
        auto settings = grainCloudRealtimeSettings();
        settings.tableResources.pop_back();
        auto graph = compile(makeGrainCloudRealtimeDocument(), settings);
        talas::runtime::RealtimeRenderSession session(graph);
        require(!session.ready(),
            "prepared realtime GrainCloud should reject a missing envelope table");
    }
}

void testRealtimeNamedMemoryWriterSampleCloudMatchesOffline()
{
    for (const auto futureRead : {false, true})
    {
        auto document = makeNamedMemoryWriterSampleDocument();
        const auto reader = std::ranges::find(
            document.graph.nodes, std::string_view{"reader"},
            &talas::project::ProjectNode::instanceId);
        require(reader != document.graph.nodes.end(),
            "named SampleCloud fixture should retain its reader");
        reader->typeId = "talas.sampleCloud";
        reader->parameters = sampleCloudRealtimeParameters({
            resourceParameter("sample", "Memory/Capture"),
            resourceParameter("grainEnv", "Envelopes/Flat"),
            {"maxGrains", "1"},
            {"amplitude", futureRead ? "1" : "0"},
            {"density", "1"},
            {"grainDur", "1 s"},
            {"timeIndex", futureRead ? "1" : "-1"},
            booleanParameter("fromMemoryWriter", true),
        });
        const auto playbackControl = std::ranges::find_if(
            document.graph.connections, [](const auto& connection) {
                return connection.toNode == "reader"
                    && connection.toPort == "gate";
            });
        require(playbackControl != document.graph.connections.end(),
            "named SampleCloud fixture should retain playback control");
        if (futureRead)
            document.graph.connections.erase(playbackControl);
        else
            playbackControl->toPort = "amplitude";

        talas::runtime::RenderSettings settings{4.0, 8};
        settings.tableResources = {
            {"Tables/PlaybackGate", {0, 0, 0, 0, 1, 1, 1, 1}},
            {"Envelopes/Flat", {1}},
            {"Memory/Capture", {99, 99, 99, 99}},
        };
        const auto graph = compile(document, settings);
        const auto offline = talas::runtime::renderOffline(graph, 8);
        require(offline.ok() && offline.mono.size() == 8,
            "named SampleCloud offline reference should render");
        if (futureRead)
            requireNear(offline.mono.front(), 0.0, 1e-12,
                "future SampleCloud read should not see an unwritten slot");
        else
        {
            requireNear(offline.mono[5], 1.0, 1e-12,
                "named SampleCloud should play the captured positive pulse");
            requireNear(offline.mono[7], -1.0, 1e-12,
                "named SampleCloud should play the captured negative pulse");
        }
        for (const auto block : std::array<std::size_t, 4>{1, 2, 4, 8})
        {
            talas::runtime::RealtimeRenderSession session(graph);
            require(session.ready(),
                "named SampleCloud should prepare: "
                    + std::string{session.error()});
            std::array<double, 8> left{};
            std::array<double, 8> right{};
            std::size_t allocations = 0;
            for (std::size_t offset = 0; offset < left.size(); offset += block)
            {
                require(renderStereoAndCount(
                            session,
                            std::span<double>{left}.subspan(offset, block),
                            std::span<double>{right}.subspan(offset, block),
                            allocations)
                        && allocations == 0,
                    "named SampleCloud should render without callback allocation");
            }
            for (std::size_t frame = 0; frame < left.size(); ++frame)
            {
                requireNear(left[frame], offline.mono[frame], 1e-12,
                    "named SampleCloud left partition parity");
                requireNear(right[frame], offline.mono[frame], 1e-12,
                    "named SampleCloud right partition parity");
            }
        }
        if (!futureRead)
        {
            auto mismatched = document;
            const auto mismatchedReader = std::ranges::find(
                mismatched.graph.nodes, std::string_view{"reader"},
                &talas::project::ProjectNode::instanceId);
            require(mismatchedReader != mismatched.graph.nodes.end(),
                "mismatched SampleCloud fixture should retain its reader");
            mismatchedReader->parameters = sampleCloudRealtimeParameters({
                resourceParameter("sample", "Memory/Other"),
                resourceParameter("grainEnv", "Envelopes/Flat"),
                {"maxGrains", "1"},
                {"amplitude", "0"},
                {"density", "1"},
                {"grainDur", "1 s"},
                booleanParameter("fromMemoryWriter", true),
            });
            settings.tableResources.push_back(
                {"Memory/Other", {77, 77, 77, 77}});
            talas::runtime::RealtimeRenderSession rejected(
                compile(mismatched, settings));
            require(!rejected.ready(),
                "named SampleCloud must not use an immutable same-name fallback");
        }
    }
}

void testRealtimeSampleCloudMatchesOfflineWithoutAllocations()
{
    const std::array profiles = {
        sampleCloudRealtimeParameters({
            {"density", "2.0"},
            {"grainDur", "1 s"},
            {"pan", "0.25"},
            {"timeIndex", "-1.0"},
        }),
        sampleCloudRealtimeParameters({
            {"density", "3.0"},
            {"grainDur", "0.75 s"},
            {"grainDurJitter", "0.25"},
            {"pan", "0.5"},
            {"panJitter", "0.4"},
            {"timeIndex", "-0.5"},
            {"timeIndexJitter", "0.35"},
            {"seed", "0.25"},
        }),
    };
    const std::array<std::size_t, 5> partitions{3, 1, 7, 2, 5};
    for (const auto& parameters : profiles)
    {
        auto graph = compile(
            makeSampleCloudRealtimeDocument(parameters),
            sampleCloudRealtimeSettings(8));
        talas::runtime::OfflineRenderSession offline(graph);
        talas::runtime::RealtimeRenderSession realtime(graph);
        require(realtime.ready(), std::string(realtime.error()));

        for (const auto frames : partitions)
        {
            const auto expected = offline.render(frames);
            require(expected.ok()
                    && expected.mono.size() == frames
                    && expected.right.size() == frames,
                "offline SampleCloud parity reference should render stereo");
            std::vector<double> left(frames);
            std::vector<double> right(frames);
            std::size_t allocations = 0;
            require(renderStereoAndCount(
                    realtime, left, right, allocations),
                "prepared realtime SampleCloud should render");
            require(allocations == 0,
                "prepared realtime SampleCloud callback should not allocate");
            for (std::size_t frame = 0; frame < frames; ++frame)
            {
                requireNear(left[frame], expected.mono[frame], 1.0e-12,
                    "prepared realtime SampleCloud left should match offline");
                requireNear(right[frame], expected.right[frame], 1.0e-12,
                    "prepared realtime SampleCloud right should match offline");
            }
        }

        offline.reset();
        realtime.resetTransport();
        const auto expected = offline.render(8);
        std::array<double, 8> left{};
        std::array<double, 8> right{};
        std::size_t allocations = 0;
        require(expected.ok()
                && renderStereoAndCount(realtime, left, right, allocations)
                && allocations == 0,
            "reset SampleCloud fixtures should render without allocation");
        for (std::size_t frame = 0; frame < left.size(); ++frame)
        {
            requireNear(left[frame], expected.mono[frame], 1.0e-12,
                "reset SampleCloud left should restart exactly");
            requireNear(right[frame], expected.right[frame], 1.0e-12,
                "reset SampleCloud right should restart exactly");
        }
    }
}

void testRealtimeSampleCloudRejectsInexactAbsoluteFrameAtomically()
{
    auto graph = compile(
        makeSampleCloudRealtimeDocument(),
        sampleCloudRealtimeSettings(1));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(),
        "C110 realtime inexact absolute-frame fixture should prepare: "
            + std::string{session.error()});

    constexpr auto inexactFrame = (std::uint64_t{1} << 53) + 1;
    require(
        talas::runtime::RealtimeRenderSessionTestAccess::
            setSampleCloudRenderedFrames(session, inexactFrame),
        "C110 fixture should set the prepared SampleCloud cursor");
    const auto before =
        talas::runtime::RealtimeRenderSessionTestAccess::
            sampleCloudRenderedFrames(session);
    std::array<double, 1> left{1.0};
    std::array<double, 1> right{1.0};
    std::size_t allocations = 0;
    require(
        !renderStereoAndCount(session, left, right, allocations)
            && allocations == 0
            && left == std::array<double, 1>{}
            && right == std::array<double, 1>{},
        "C110 prepared SampleCloud should reject an inexact absolute frame without allocation or output publication");
    require(
        talas::runtime::RealtimeRenderSessionTestAccess::
                sampleCloudRenderedFrames(session)
            == before,
        "C110 prepared inexact absolute-frame rejection should restore the exact cursor");
}

