void testRealtimeSampleCloudMixesCurrentFrameCrossingsLikeOffline()
{
    auto document = makeSampleCloudRealtimeDocument(
        sampleCloudRealtimeParameters({
            {"amplitude", "1"},
            {"density", "0"},
            {"grainDur", "10 s"},
            {"maxGrains", "1"},
            {"pan", "0"},
            {"timeIndex", "-1"},
        }));
    document.graph.nodes.push_back(node(
        "densityControl",
        "talas.triggeredTableRead",
        {
            {"trigger", "1"},
            resourceParameter("wavetable", "Tables/C110PhaseEdge"),
            {"gate", "1"},
            booleanParameter("ignoreLoops", true),
            booleanParameter("fromMemoryWriter", false),
        }));
    document.graph.connections.push_back(connection(
        "densityControl", "value", "cloud", "density"));

    auto settings = sampleCloudRealtimeSettings(2);
    settings.sampleRate = 1.0;
    settings.tableResources[1].samples = {1.0};
    settings.tableResources.push_back({
        "Tables/C110PhaseEdge",
        {std::nextafter(1.0, 0.0), 0.001},
    });
    auto graph = compile(document, std::move(settings));
    talas::runtime::OfflineRenderSession offline(graph);
    talas::runtime::RealtimeRenderSession realtime(graph);
    require(realtime.ready(),
        "C110 current-frame crossing fixture should prepare: "
            + std::string{realtime.error()});

    const auto expected = offline.render(2);
    std::array<double, 2> left{};
    std::array<double, 2> right{};
    std::size_t allocations = 0;
    require(expected.ok()
            && expected.mono == std::vector<double>({1.0, 0.0})
            && expected.right == std::vector<double>({0.0, 0.0}),
        "C110 offline phase-edge oracle should let the newest current-frame crossing consume the sole grain slot");
    require(renderStereoAndCount(
                realtime, left, right, allocations)
            && allocations == 0
            && std::ranges::equal(left, expected.mono)
            && std::ranges::equal(right, expected.right),
        "C110 prepared SampleCloud should mix the post-schedule current-frame grain order exactly like offline");
}

