void testRealtimeCloudBankResetDiscontinuityAndReplacementAreFreshEquivalent()
{
    const auto graph = compile(
        makeCloudBankRealtimeDocument(), cloudBankRealtimeSettings(2));
    talas::runtime::RealtimeRenderSession resetCandidate(graph);
    talas::runtime::RealtimeRenderSession fresh(graph);
    std::array<double, 2> prefixLeft{};
    std::array<double, 2> prefixRight{};
    std::size_t allocations = 0;
    require(resetCandidate.ready() && fresh.ready()
            && renderStereoAndCount(
                resetCandidate, prefixLeft, prefixRight, allocations)
            && allocations == 0,
        "C111 lifecycle fixture should establish progressed CloudBank state");
    resetCandidate.resetTransport();
    std::array<double, 2> resetLeft{};
    std::array<double, 2> resetRight{};
    std::array<double, 2> freshLeft{};
    std::array<double, 2> freshRight{};
    require(renderStereoAndCount(
                resetCandidate, resetLeft, resetRight, allocations)
            && renderStereoAndCount(
                fresh, freshLeft, freshRight, allocations)
            && allocations == 0
            && resetLeft == freshLeft
            && resetRight == freshRight,
        "C111 reset should restore CloudBank cursor and analytical grain state to fresh");

    talas::runtime::RealtimeRenderSession discontinuous(graph);
    talas::runtime::RealtimeRenderSession discontinuityFresh(graph);
    talas::runtime::RealtimeRenderSession replacement(graph);
    require(discontinuous.ready() && discontinuityFresh.ready()
            && replacement.ready()
            && renderStereoAndCount(
                discontinuous, prefixLeft, prefixRight, allocations),
        "C111 discontinuity fixture should progress before reset");
    const talas::runtime::RealtimeTransportSnapshot discontinuity{
        .epoch = 1,
        .absoluteFrame = 2,
        .playheadFrame = 2,
        .sampleRate = 4.0,
        .loopStartFrame = 0,
        .loopEndFrame = 0,
        .discontinuitySequence = 1,
        .playing = true,
        .loopEnabled = false,
    };
    discontinuous.setTransportSnapshotBeforeRender(discontinuity);
    discontinuityFresh.setTransportSnapshotBeforeRender(discontinuity);
    replacement.setTransportSnapshotBeforeRender(discontinuity);
    std::array<double, 2> actualLeft{};
    std::array<double, 2> actualRight{};
    std::array<double, 2> expectedLeft{};
    std::array<double, 2> expectedRight{};
    std::array<double, 2> replacementLeft{};
    std::array<double, 2> replacementRight{};
    require(renderStereoAndCount(
                discontinuous, actualLeft, actualRight, allocations)
            && renderStereoAndCount(
                discontinuityFresh, expectedLeft, expectedRight, allocations)
            && renderStereoAndCount(
                replacement,
                replacementLeft,
                replacementRight,
                allocations)
            && allocations == 0
            && actualLeft == expectedLeft
            && actualRight == expectedRight
            && replacementLeft == expectedLeft
            && replacementRight == expectedRight,
        "C111 discontinuity and replacement should reset complete CloudBank state identically");
}

void testRealtimeCloudBankElementMatchesOfflineWithoutAllocations()
{
    struct Profile
    {
        std::vector<talas::project::ProjectParameterExpression> parameters;
        double pan;
        double frequencyMod;
        double durationMod;
    };
    const std::array profiles = {
        Profile{cloudBankElementRealtimeParameters({
            {"grainDur", "1 s"},
            {"cyclesPerGrain", "0"},
            choiceParameter("interpolation", "linear"),
        }), 0.25, 0.0, 0.0},
        Profile{cloudBankElementRealtimeParameters({
            {"first", "2"},
            {"count", "1"},
            {"grainDur", "0 s"},
            {"cyclesPerGrain", "1"},
            {"initialDelay", "0.5 s"},
            choiceParameter("interpolation", "none"),
        }), 0.75, 0.5, 0.25},
    };
    const std::array<std::size_t, 5> partitions{3, 1, 7, 2, 5};
    for (const auto& profile : profiles)
    {
        auto graph = compile(
            makeCloudBankElementRealtimeDocument(
                profile.parameters,
                1.0,
                profile.pan,
                profile.frequencyMod,
                profile.durationMod),
            cloudBankRealtimeSettings(8));
        talas::runtime::OfflineRenderSession offline(graph);
        talas::runtime::RealtimeRenderSession realtime(graph);
        require(realtime.ready(), std::string(realtime.error()));
        for (const auto frames : partitions)
        {
            const auto expected = offline.render(frames);
            require(expected.ok()
                    && expected.mono.size() == frames
                    && expected.right.size() == frames,
                "offline CloudBankElement parity reference should render stereo");
            std::vector<double> left(frames);
            std::vector<double> right(frames);
            std::size_t allocations = 0;
            require(renderStereoAndCount(
                    realtime, left, right, allocations),
                "prepared realtime CloudBankElement should render");
            require(allocations == 0,
                "prepared realtime CloudBankElement callback should not allocate");
            for (std::size_t frame = 0; frame < frames; ++frame)
            {
                requireNear(left[frame], expected.mono[frame], 1.0e-12,
                    "prepared realtime CloudBankElement left should match offline");
                requireNear(right[frame], expected.right[frame], 1.0e-12,
                    "prepared realtime CloudBankElement right should match offline");
            }
        }

        offline.reset();
        realtime.resetTransport();
        const auto expected = offline.render(8);
        std::array<double, 8> left{};
        std::array<double, 8> right{};
        std::size_t allocations = 0;
        require(expected.ok()
                && renderStereoAndCount(realtime, left, right, allocations)
                && allocations == 0,
            "reset CloudBankElement fixtures should render without allocation");
        for (std::size_t frame = 0; frame < left.size(); ++frame)
        {
            requireNear(left[frame], expected.mono[frame], 1.0e-12,
                "reset CloudBankElement left should restart exactly");
            requireNear(right[frame], expected.right[frame], 1.0e-12,
                "reset CloudBankElement right should restart exactly");
        }
    }
}

