void testRealtimeMonotonizerOwnsLateDownstreamRollback()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("input", "talas.audioInput", {
            choiceParameter("routing", "monoSum"),
            booleanParameter("channel1", true),
            booleanParameter("channel2", false),
        }),
        node("mono", "talas.monotonizer", {
            {"frequency", "150 hz"},
            {"minInputPitch", "100 hz"},
            {"maxInputPitch", "100 hz"},
        }),
        node("downstream", "talas.level", {
            {"left", "!C105Downstream"}, {"right", "0"},
            booleanParameter("noGain", false),
        }),
    };
    document.graph.connections = {
        connection("input", "audioOut", "mono", "audioIn"),
        connection("mono", "audioOut", "downstream", "audioIn"),
        connection("downstream", "leftOut", "out", "audioIn"),
    };
    auto settings = talas::runtime::RenderSettings{48000.0, 256};
    settings.eventValues = {
        {"C105Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession reference(graph);
    require(candidate.ready() && reference.ready(),
        "C105 Monotonizer rollback fixtures should prepare: "
            + std::string{candidate.error()});
    std::array<float, 256> inputChannel{};
    for (std::size_t frame = 0; frame < inputChannel.size(); ++frame)
    {
        inputChannel[frame] = static_cast<float>(
            1.0e20 * std::sin(
                2.0 * std::numbers::pi * 100.0
                * static_cast<double>(frame) / 48000.0));
    }
    std::array<const float*, 1> inputChannels{inputChannel.data()};
    const talas::runtime::RealtimeAudioInputBlock inputBlock{
        inputChannels.data(), inputChannels.size()};
    std::array<double, 256> warmupCandidate{};
    std::array<double, 256> warmupReference{};
    std::size_t allocations = 0;
    for (int block = 0; block < 5; ++block)
    {
        require(renderStereoInputAndCount(
                    candidate,
                    inputBlock,
                    warmupCandidate,
                    {},
                    allocations)
                && allocations == 0
                && renderStereoInputAndCount(
                    reference,
                    inputBlock,
                    warmupReference,
                    {},
                    allocations)
                && allocations == 0
                && warmupCandidate == warmupReference,
            "C105 Monotonizer rollback fixtures should share identical active history");
    }
    require(candidate.updateEventValue(
                "C105Downstream",
                std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C105 Monotonizer rollback fixture should arm its downstream overflow");

    std::array<double, 256> rejected;
    rejected.fill(100.0);
    require(!renderStereoInputAndCount(
                candidate, inputBlock, rejected, {}, allocations)
            && allocations == 0
            && rejected == std::array<double, 256>{},
        "C105 downstream failure should publish no Monotonizer callback prefix");
    require(candidate.updateEventValue(
                "C105Downstream", 1.0,
                talas::expr::ValueDomain::Scalar),
        "C105 Monotonizer rollback fixture should repair only the downstream control");

    std::array<double, 256> retry{};
    std::array<double, 256> expected{};
    require(renderStereoInputAndCount(
                candidate, inputBlock, retry, {}, allocations)
            && allocations == 0
            && renderStereoInputAndCount(
                reference, inputBlock, expected, {}, allocations)
            && allocations == 0
            && retry == expected,
        "C105 downstream failure should restore complete Monotonizer phase-vocoder state before exact retry");
}

void testRealtimeMonotonizerRejectsForgedPreparedAuthority()
{
    const auto graph = compile(makeMonotonizerDocument({
        {"frequency", "150 hz"},
        {"minInputPitch", "100 hz"},
        {"maxInputPitch", "100 hz"},
    }), talas::runtime::RenderSettings{48000.0, 256});
    const auto requireRejected = [&](auto mutate,
                                     std::string_view context) {
        auto plan = graph.plan();
        const auto monotonizer = std::ranges::find(
            plan.steps,
            std::string_view{"mono"},
            &talas::runtime::CompileStep::nodeId);
        require(monotonizer != plan.steps.end(),
            "C105 forged-authority fixture should expose Monotonizer");
        mutate(plan, *monotonizer);
        talas::runtime::RealtimeRenderSession session(
            talas::runtime::PreparedRuntimeGraph{
                std::move(plan), graph.renderSettings()});
        require(!session.ready(), std::string{context}
                + " should reject forged C105 Monotonizer authority");
    };
    requireRejected(
        [](auto&, auto& monotonizer) {
            monotonizer.offlineSupport =
                talas::core::ExecutionSupport::Supported;
        },
        "forged offline support");
    requireRejected(
        [](auto&, auto& monotonizer) {
            monotonizer.preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
            monotonizer.kernelKind = talas::runtime::KernelKind::Gate;
        },
        "forged prepared binding");
    requireRejected(
        [](auto&, auto& monotonizer) {
            std::swap(monotonizer.parameters[0], monotonizer.parameters[1]);
        },
        "forged parameter order");
    requireRejected(
        [](auto&, auto& monotonizer) {
            monotonizer.structuralScopeId += 1;
        },
        "forged structural scope");
    requireRejected(
        [](auto& plan, auto& monotonizer) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == monotonizer.nodeId
                        && buffer.scopeId == monotonizer.scopeId
                        && buffer.portId == "audioOut";
                });
            require(output != plan.buffers.end(),
                "C105 forged-authority fixture should expose mono output");
            output->frames -= 1;
        },
        "forged output capacity");
    requireRejected(
        [](auto&, auto& monotonizer) {
            monotonizer.cumulativeInputLatencyFrames = 1;
        },
        "forged cumulative latency ancestry");

    auto missingAuthoritySettings = graph.renderSettings();
    missingAuthoritySettings.preparedMonotonizerAuthorityPlan.reset();
    talas::runtime::RealtimeRenderSession missingAuthority(
        talas::runtime::PreparedRuntimeGraph{
            graph.plan(), std::move(missingAuthoritySettings)});
    require(!missingAuthority.ready(),
        "C105 prepared admission should require compiler-owned Monotonizer authority");
}

