void testRealtimeSessionRendersNonNeutralSimplePitchShifterWithOfflineParity()
{
    constexpr std::size_t totalFrames = 4096;
    talas::runtime::RenderSettings settings{48000.0, 257};
    auto graph = compile(makeSimplePitchShifterDocument({
        {"interval", "12"},
        {"minInputPitch", "20 hz"},
        {"maxInputPitch", "2000 hz"},
    }), settings);
    const auto expected = talas::runtime::renderOffline(graph, totalFrames);
    require(expected.ok(),
            "offline non-neutral Simple Pitch Shifter reference should render");
    require(expected.mono.size() == totalFrames,
            "offline pitch-shift reference should preserve duration");

    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    std::vector<double> actual(totalFrames, 0.0);
    std::size_t offset = 0;
    while (offset < actual.size())
    {
        const auto count = std::min<std::size_t>(
            settings.maxBlockFrames,
            actual.size() - offset);
        std::size_t allocations = 0;
        require(renderAndCount(
                    session,
                    std::span<double>{actual}.subspan(offset, count),
                    allocations),
                "non-neutral realtime Simple Pitch Shifter block should render");
        require(allocations == 0,
                "non-neutral realtime Simple Pitch Shifter callback should not allocate");
        offset += count;
    }
    for (std::size_t frame = 0; frame < actual.size(); ++frame)
    {
        requireNear(actual[frame], expected.mono[frame], 1.0e-9,
                    "non-neutral Simple Pitch Shifter realtime/offline parity frame "
                        + std::to_string(frame));
    }
    for (std::size_t frame = 0;
         frame < talas::dsp::phaseVocoderPitchLatencyFrames;
         ++frame)
    {
        require(actual[frame] == 0.0,
                "non-neutral Simple Pitch Shifter should expose exact startup latency");
    }

    auto tamperedPlan = graph.plan();
    auto pitch = std::ranges::find_if(
        tamperedPlan.steps,
        [](const talas::runtime::CompileStep& step) {
            return step.nodeId == "pitch";
        });
    require(pitch != tamperedPlan.steps.end(),
            "pitch latency tamper fixture should retain the target step");
    pitch->resolvedLatencyFrames = 0;
    talas::runtime::PreparedRuntimeGraph tampered{
        std::move(tamperedPlan), settings};
    talas::runtime::RealtimeRenderSession rejected(tampered);
    require(!rejected.ready(),
            "tampered non-neutral Simple Pitch Shifter latency should fail before callback admission");
}

