void testRealtimeSessionDynamicSimplePitchShifterMatchesOfflineAcrossTransitions()
{
    constexpr std::size_t blockFrames = 256;
    constexpr std::size_t sectionFrames = 4096;
    constexpr std::array<double, 4> intervals{0.0, 7.0, -7.0, 0.0};
    talas::runtime::RenderSettings settings{48000.0, blockFrames};
    std::vector<double> intervalTable;
    intervalTable.reserve(sectionFrames * intervals.size());
    for (const auto interval : intervals)
        intervalTable.insert(intervalTable.end(), sectionFrames, interval);
    settings.tableResources.push_back(
        {"Tables/DynamicInterval", intervalTable});

    auto document = makeSimplePitchShifterDocument({
        {"interval", "0"},
        {"minInputPitch", "20 hz"},
        {"maxInputPitch", "2000 hz"},
    });
    document.graph.nodes.push_back(node(
        "interval",
        "talas.triggeredTableRead",
        {
            {"trigger", "1"},
            resourceParameter("wavetable", "Tables/DynamicInterval"),
            {"gate", "1"},
            booleanParameter("ignoreLoops", true),
            booleanParameter("fromMemoryWriter", false),
        }));
    document.graph.connections.push_back(
        connection("interval", "value", "pitch", "interval"));
    auto graph = compile(document, settings);
    talas::runtime::OfflineRenderSession offline(graph);
    talas::runtime::RealtimeRenderSession realtime(graph);
    require(realtime.ready(), std::string(realtime.error()));

    std::array<double, blockFrames> actual{};
    for (std::size_t block = 0;
         block < intervalTable.size() / blockFrames;
         ++block)
    {
        const auto expected = offline.render(blockFrames);
        require(expected.ok(),
                "offline dynamic Simple Pitch Shifter block should render");
        std::size_t allocations = 0;
        require(renderAndCount(realtime, actual, allocations),
                "realtime dynamic Simple Pitch Shifter block should render");
        require(allocations == 0,
                "dynamic Simple Pitch Shifter callback should not allocate");
        for (std::size_t frame = 0; frame < blockFrames; ++frame)
        {
            requireNear(
                actual[frame],
                expected.mono[frame],
                1.0e-9,
                "dynamic Simple Pitch Shifter realtime/offline parity");
        }
    }

    auto tamperedPlan = graph.plan();
    auto pitch = std::ranges::find_if(
        tamperedPlan.steps,
        [](const talas::runtime::CompileStep& step) {
            return step.nodeId == "pitch";
        });
    require(pitch != tamperedPlan.steps.end(),
            "dynamic pitch tamper fixture should retain its operation");
    pitch->resolvedLatencyFrames = 0;
    talas::runtime::PreparedRuntimeGraph tampered{
        std::move(tamperedPlan), settings};
    talas::runtime::RealtimeRenderSession rejected(tampered);
    require(!rejected.ready(),
            "connected pitch graph with zero claimed latency should fail preparation");
}

