// Delay is read once, at the start, so a
// Delay that changes keeps its starting value in both renderers. Projects
// before format 85 follow it offline, and realtime, whose delay line is
// sized when the Sound is prepared, refuses it rather than keep its first
// value.
void testRealtimeSessionRefusesAChangingFrequencyScaleDelay()
{
    talas::runtime::RenderSettings settings{4.0, 3};
    settings.eventValues = {{"Lag", 0.25, talas::expr::ValueDomain::Scalar}};
    settings.eventValueChanges = {{3, "Lag", 0.5, talas::expr::ValueDomain::Scalar}};
    auto atStart = compile(makeFrequencyScaleDocument({
        {"frequencyScale", "1"}, {"maxScale", "1"}, resourceParameter("window", "Private"), {"delay", "!Lag"},
    }), settings);
    const auto expected = talas::runtime::renderOffline(atStart, 6);
    require(expected.ok(), "offline should keep a FrequencyScale Delay's starting value");
    talas::runtime::RealtimeRenderSession reading(atStart);
    require(reading.ready(), "realtime should read a FrequencyScale Delay at the start: " + std::string{reading.error()});
    std::array<double, 3> first{};
    std::array<double, 3> second{};
    std::size_t allocations = 0;
    require(renderAndCount(reading, first, allocations) && renderAndCount(reading, second, allocations),
        "realtime should play a FrequencyScale Delay read at the start");
    for (std::size_t frame = 0; frame < first.size(); ++frame)
    {
        requireNear(first[frame], expected.mono[frame], 1.0e-12, "a Delay read at the start should match offline");
        requireNear(second[frame], expected.mono[first.size() + frame], 1.0e-12,
            "a Delay read at the start should match offline");
    }

    auto graph = compile(makeFrequencyScaleDocument({
        {"frequencyScale", "1"}, {"maxScale", "1"}, resourceParameter("window", "Private"), {"delay", "!Lag"},
        choiceParameter("delayRead", "legacyFollows"),
    }), std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(!session.ready()
            && std::string{session.error()}.find("cannot follow a Delay that changes") != std::string::npos,
        "realtime should refuse a FrequencyScale Delay that changes: " + std::string{session.error()});
}

