void testRealtimeSessionDynamicFrequencyScaleMatchesOfflineAcrossTransitions()
{
    constexpr std::size_t blockFrames = 256;
    constexpr std::size_t sectionFrames = 4096;
    constexpr std::array<double, 4> ratios{1.0, 1.5, 0.75, 1.0};
    talas::runtime::RenderSettings settings{48000.0, blockFrames};
    std::vector<double> ratioTable;
    ratioTable.reserve(sectionFrames * ratios.size());
    for (const auto ratio : ratios)
        ratioTable.insert(ratioTable.end(), sectionFrames, ratio);
    settings.tableResources.push_back(
        {"Tables/FrequencyScaleDynamic", ratioTable});

    auto document = makeFrequencyScaleDocument({
        {"frequencyScale", "1"},
        {"maxScale", "2"},
        resourceParameter("window", "Private"),
        {"delay", "0.001"},
    });
    document.graph.nodes.push_back(node(
        "frequencyScale",
        "talas.triggeredTableRead",
        {
            {"trigger", "1"},
            resourceParameter(
                "wavetable", "Tables/FrequencyScaleDynamic"),
            {"gate", "1"},
            booleanParameter("ignoreLoops", true),
            booleanParameter("fromMemoryWriter", false),
        }));
    document.graph.connections.push_back(connection(
        "frequencyScale", "value", "scale", "frequencyScale"));
    auto graph = compile(document, settings);
    const auto scaleStep = std::ranges::find_if(
        graph.plan().steps,
        [](const talas::runtime::CompileStep& step) {
            return step.nodeId == "scale";
        });
    require(scaleStep != graph.plan().steps.end()
            && scaleStep->resolvedLatencyFrames
                == talas::dsp::phaseVocoderPitchLatencyFrames + 48,
            "dynamic FrequencyScale should bind exact pre-delay plus pitch latency");

    talas::runtime::OfflineRenderSession offline(graph);
    talas::runtime::RealtimeRenderSession realtime(graph);
    require(realtime.ready(), std::string(realtime.error()));
    std::array<double, blockFrames> actual{};
    for (std::size_t block = 0;
         block < ratioTable.size() / blockFrames;
         ++block)
    {
        const auto expected = offline.render(blockFrames);
        require(expected.ok(),
                "offline dynamic FrequencyScale block should render");
        std::size_t allocations = 0;
        require(renderAndCount(realtime, actual, allocations),
                "realtime dynamic FrequencyScale block should render");
        require(allocations == 0,
                "dynamic FrequencyScale callback should not allocate");
        for (std::size_t frame = 0; frame < blockFrames; ++frame)
        {
            requireNear(
                actual[frame],
                expected.mono[frame],
                1.0e-9,
                "dynamic FrequencyScale realtime/offline parity");
        }
    }

    constexpr std::size_t partitionFrames = 128;
    talas::runtime::OfflineRenderSession partitionReference(graph);
    talas::runtime::RealtimeRenderSession partitioned(graph);
    require(partitioned.ready(), std::string(partitioned.error()));
    std::array<double, partitionFrames> partitionOutput{};
    for (std::size_t block = 0;
         block < ratioTable.size() / partitionFrames;
         ++block)
    {
        const auto expected = partitionReference.render(partitionFrames);
        require(expected.ok(),
                "partition reference TimeFrequencyScale should render");
        std::size_t allocations = 0;
        require(renderAndCount(partitioned, partitionOutput, allocations),
                "partitioned TimeFrequencyScale should render");
        require(allocations == 0,
                "partitioned TimeFrequencyScale callback should not allocate");
        for (std::size_t frame = 0; frame < partitionFrames; ++frame)
        {
            requireNear(
                partitionOutput[frame], expected.mono[frame], 1.0e-9,
                "TimeFrequencyScale should remain invariant across admitted partitions");
        }
    }

    realtime.resetTransport();
    talas::runtime::RealtimeRenderSession fresh(graph);
    require(fresh.ready(), std::string(fresh.error()));
    std::array<double, blockFrames> resetOutput{};
    std::array<double, blockFrames> freshOutput{};
    std::size_t resetAllocations = 0;
    std::size_t freshAllocations = 0;
    require(renderAndCount(realtime, resetOutput, resetAllocations),
            "reset dynamic FrequencyScale callback should render");
    require(renderAndCount(fresh, freshOutput, freshAllocations),
            "fresh dynamic FrequencyScale callback should render");
    require(resetAllocations == 0 && freshAllocations == 0,
            "reset and fresh FrequencyScale callbacks should not allocate");
    for (std::size_t frame = 0; frame < blockFrames; ++frame)
    {
        requireNear(
            resetOutput[frame],
            freshOutput[frame],
            1.0e-12,
            "FrequencyScale transport reset should restore fresh prepared state");
    }

    auto tamperedPlan = graph.plan();
    auto tamperedScale = std::ranges::find_if(
        tamperedPlan.steps,
        [](const talas::runtime::CompileStep& step) {
            return step.nodeId == "scale";
        });
    require(tamperedScale != tamperedPlan.steps.end(),
            "FrequencyScale tamper fixture should retain its operation");
    tamperedScale->resolvedLatencyFrames =
        talas::dsp::phaseVocoderPitchLatencyFrames;
    talas::runtime::PreparedRuntimeGraph tampered{
        std::move(tamperedPlan), settings};
    talas::runtime::RealtimeRenderSession rejected(tampered);
    require(!rejected.ready(),
            "active FrequencyScale with omitted pre-delay latency should fail preparation");
}

void testRealtimeSessionRejectsFrequencyScaleTrackerNyquistMismatch()
{
    talas::runtime::RenderSettings settings{48000.0, 256};
    auto document = makeFrequencyScaleDocument({
        {"frequencyScale", "2"},
        {"maxScale", "2"},
        resourceParameter("window", "Private"),
        {"delay", "0"},
    });
    auto tracker = std::ranges::find_if(
        document.graph.nodes,
        [](const auto& candidate) {
            return candidate.instanceId == "tracker";
        });
    require(tracker != document.graph.nodes.end(),
            "FrequencyScale Nyquist fixture should retain its tracker");
    tracker->parameters.front().expression = "12000";
    auto graph = compile(document, settings);
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    std::array<double, 256> output{};
    output.fill(42.0);
    std::size_t allocations = 0;
    require(!renderAndCount(session, output, allocations),
            "FrequencyScale tracker product at Nyquist should fail closed");
    require(allocations == 0,
            "rejected FrequencyScale tracker evidence should not allocate");
    require(std::ranges::all_of(output, [](double sample) {
                return sample == 0.0;
            }),
            "rejected FrequencyScale tracker evidence should publish no partial audio");
}

