void testRealtimePackedFftPreservesLoopPauseAndResetsOnDiscontinuity()
{
    constexpr std::size_t frameCount = 96;
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 17;
    settings.transportLoop = talas::runtime::TransportLoopRegion{0, 32};
    auto graph = compile(makePackedFftAudioInputDocument(1), settings);
    talas::runtime::RealtimeRenderSession reference(graph);
    talas::runtime::RealtimeRenderSession transported(graph);
    require(reference.ready(), std::string(reference.error()));
    require(transported.ready(), std::string(transported.error()));

    std::vector<float> input(frameCount, 0.0F);
    input[0] = 1.0F;
    input[37] = -0.5F;
    const std::array<std::size_t, 6> partitions{17, 17, 17, 17, 17, 11};
    std::vector<double> expected(frameCount, 0.0);
    std::vector<double> actual(frameCount, 0.0);
    const auto snapshot = [](std::uint64_t absoluteFrame, bool playing) {
        return talas::runtime::RealtimeTransportSnapshot{
            .epoch = 1,
            .absoluteFrame = absoluteFrame,
            .playheadFrame = absoluteFrame % 32,
            .sampleRate = 64.0,
            .loopStartFrame = 0,
            .loopEndFrame = 32,
            .discontinuitySequence = 0,
            .playing = playing,
            .loopEnabled = true,
        };
    };

    std::size_t offset = 0;
    for (std::size_t index = 0; index < partitions.size(); ++index)
    {
        const auto count = partitions[index];
        const std::array<const float*, 1> channels{input.data() + offset};
        std::size_t allocations = 0;
        require(renderStereoInputAndCount(
                    reference,
                    {channels.data(), channels.size()},
                    std::span<double>{expected}.subspan(offset, count),
                    {},
                    allocations),
                "packed FFT reference callback should render");
        require(allocations == 0,
                "packed FFT reference callback should not allocate");
        if (index == 2)
        {
            transported.setTransportSnapshotBeforeRender(
                snapshot(offset, false));
        }
        transported.setTransportSnapshotBeforeRender(
            snapshot(offset, true));
        require(renderStereoInputAndCount(
                    transported,
                    {channels.data(), channels.size()},
                    std::span<double>{actual}.subspan(offset, count),
                    {},
                    allocations),
                "loop/pause packed FFT callback should render");
        require(allocations == 0,
                "loop/pause packed FFT callback should not allocate");
        offset += count;
    }
    for (std::size_t frame = 0; frame < frameCount; ++frame)
    {
        requireNear(actual[frame], expected[frame], 1.0e-9,
                    "ordinary loop wrap and pause must preserve packed FFT state");
    }
    requireNear(actual[2 * (16 - 1)], 1.0, 1.0e-9,
                "packed FFT history should survive the first loop wrap");

    auto discontinuity = snapshot(200, true);
    discontinuity.epoch = 2;
    discontinuity.discontinuitySequence = 1;
    transported.setTransportSnapshotBeforeRender(discontinuity);
    talas::runtime::RealtimeRenderSession fresh(graph);
    require(fresh.ready(), std::string(fresh.error()));
    fresh.setTransportSnapshotBeforeRender(discontinuity);
    std::array<float, 17> zeroInput{};
    const std::array<const float*, 1> zeroChannels{zeroInput.data()};
    std::array<double, 17> resetOutput{};
    std::array<double, 17> freshOutput{};
    std::size_t allocations = 0;
    require(renderStereoInputAndCount(
                transported,
                {zeroChannels.data(), zeroChannels.size()},
                resetOutput,
                {},
                allocations),
            "discontinuous packed FFT callback should render");
    require(allocations == 0,
            "discontinuous packed FFT callback should not allocate");
    require(renderStereoInputAndCount(
                fresh,
                {zeroChannels.data(), zeroChannels.size()},
                freshOutput,
                {},
                allocations),
            "fresh packed FFT discontinuity reference should render");
    require(allocations == 0,
            "fresh packed FFT discontinuity reference should not allocate");
    for (std::size_t frame = 0; frame < resetOutput.size(); ++frame)
    {
        requireNear(resetOutput[frame], freshOutput[frame], 1.0e-9,
                    "true discontinuity should restore fresh packed FFT state");
    }
}

void testRealtimePackedFftGraphGenerationsOwnIndependentPreparedState()
{
    constexpr std::size_t size = 16;
    constexpr std::size_t frameCount = 3 * size - 2;
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 17;
    auto oldGraph = compile(makePackedFftAudioInputDocument(1), settings);
    auto replacementGraph = compile(
        makePackedFftAudioInputDocument(1), settings);
    talas::runtime::RealtimeRenderSession oldSession(oldGraph);
    talas::runtime::RealtimeRenderSession replacementSession(replacementGraph);
    require(oldSession.ready(), std::string(oldSession.error()));
    require(replacementSession.ready(),
            std::string(replacementSession.error()));

    std::vector<float> oldInput(frameCount, 0.0F);
    oldInput.front() = 1.0F;
    std::vector<float> replacementInput(frameCount, 0.0F);
    std::vector<double> oldOutput(frameCount, 0.0);
    std::vector<double> replacementOutput(frameCount, 0.0);
    const std::array<std::size_t, 4> partitions{9, 17, 17, 3};
    std::size_t offset = 0;
    for (const auto count : partitions)
    {
        const std::array<const float*, 1> oldChannels{
            oldInput.data() + offset};
        const std::array<const float*, 1> replacementChannels{
            replacementInput.data() + offset};
        std::size_t allocations = 0;
        require(renderStereoInputAndCount(
                    oldSession,
                    {oldChannels.data(), oldChannels.size()},
                    std::span<double>{oldOutput}.subspan(offset, count),
                    {},
                    allocations),
                "retained packed FFT graph generation should render");
        require(allocations == 0,
                "retained packed FFT graph generation should not allocate");
        require(renderStereoInputAndCount(
                    replacementSession,
                    {replacementChannels.data(), replacementChannels.size()},
                    std::span<double>{replacementOutput}.subspan(offset, count),
                    {},
                    allocations),
                "replacement packed FFT graph generation should render");
        require(allocations == 0,
                "replacement packed FFT graph generation should not allocate");
        offset += count;
    }
    for (std::size_t frame = 0; frame < frameCount; ++frame)
    {
        requireNear(
            oldOutput[frame],
            frame == 2 * size - 2 ? 1.0 : 0.0,
            1.0e-9,
            "retained packed FFT generation should preserve its partial frame");
        requireNear(replacementOutput[frame], 0.0, 1.0e-12,
                    "replacement packed FFT generation must start with fresh state");
    }
}

void testRealtimeSessionRendersNativeComplexStftAcrossPartitionsAndResetWithoutAllocations()
{
    constexpr std::size_t frameSize = 64;
    constexpr std::size_t latency = frameSize - 1;
    constexpr std::size_t frameCount = 321;
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 17;

    for (const auto& [window, hop] :
         std::vector<std::pair<std::string, std::string>>{
             {"rectangular", "64"},
             {"hann", "32"},
             {"hann", "16"},
         })
    {
        auto graph = compile(
            makeNativeStftDocument("64", hop, window),
            settings);
        const auto expected = talas::runtime::renderOffline(
            graph,
            frameCount);
        require(expected.ok(),
                "offline native STFT realtime reference should render");

        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(), std::string(session.error()));
        std::vector<double> actual;
        actual.reserve(frameCount);
        const std::array<std::size_t, 6> partitions{1, 17, 3, 11, 5, 13};
        std::size_t partitionIndex = 0;
        while (actual.size() != frameCount)
        {
            const auto count = std::min(
                frameCount - actual.size(),
                partitions[partitionIndex % partitions.size()]);
            std::vector<double> block(count, 0.0);
            std::size_t allocations = 0;
            require(renderAndCount(session, block, allocations),
                    "prepared native STFT callback should render");
            require(allocations == 0,
                    "prepared native STFT callback should not allocate");
            actual.insert(actual.end(), block.begin(), block.end());
            ++partitionIndex;
        }
        for (std::size_t frame = 0; frame < frameCount; ++frame)
        {
            requireNear(
                actual[frame],
                expected.mono[frame],
                1.0e-9,
                "prepared native STFT should match offline across callback partitions");
            if (frame < latency)
            {
                requireNear(
                    actual[frame],
                    0.0,
                    1.0e-12,
                    "prepared native STFT should preserve exact N-1 startup latency");
            }
        }

        session.resetTransport();
        std::array<double, 17> resetBlock{};
        std::size_t allocations = 0;
        require(renderAndCount(session, resetBlock, allocations),
                "reset native STFT callback should render");
        require(allocations == 0,
                "reset native STFT callback should not allocate");
        for (std::size_t frame = 0; frame < resetBlock.size(); ++frame)
        {
            requireNear(
                resetBlock[frame],
                expected.mono[frame],
                1.0e-9,
                "transport reset should restore fresh native STFT state");
        }
    }
}

void testRealtimeLiveSpectralAnalysisMatchesOfflineAcrossPartitionsWithoutAllocations()
{
    constexpr std::size_t frameCount = 64;
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = frameCount;
    std::vector<double> offlineInput(frameCount);
    std::array<float, frameCount> realtimeInput{};
    for (std::size_t frame = 0; frame < frameCount; ++frame)
    {
        const auto sample = 0.75 * std::sin(
            2.0 * std::acos(-1.0) * 8.0
            * static_cast<double>(frame) / 64.0);
        offlineInput[frame] = sample;
        realtimeInput[frame] = static_cast<float>(sample);
    }
    settings.audioInputChannels = {{1, offlineInput}};
    auto graph = compile(
        makeLiveSpectralAnalysisAudioInputDocument(), settings);

    talas::runtime::OfflineRenderSession offline{graph};
    const auto expected = offline.inspectPartialSpectrum(
        "spectrum", "spectrumOut", frameCount);
    require(expected.ok() && expected.frames.size() == 1,
            "offline live spectral realtime oracle should publish one frame");

    talas::runtime::RealtimeRenderSession contiguous(graph);
    require(contiguous.ready(), std::string(contiguous.error()));
    const std::array<const float*, 1> channels{realtimeInput.data()};
    std::array<double, frameCount> left{};
    std::array<double, frameCount> right{};
    std::size_t allocations = 0;
    require(renderStereoInputAndCount(
                contiguous,
                {channels.data(), channels.size()},
                left,
                right,
                allocations),
            "contiguous realtime live spectral callback should render");
    require(allocations == 0,
            "first realtime live spectral callback should not allocate");
    const auto actual = contiguous.inspectPartialSpectrum(
        "spectrum", "spectrumOut");
    require(actual.size() == 1 && actual.front().partials.size() == 1,
            "realtime partial inspection should expose the rendered interval");
    require(actual.front().sourceTimestamp
                == expected.frames.front().sourceTimestamp
                && actual.front().sourceSequence
                    == expected.frames.front().sourceSequence,
            "realtime live spectral frame should match offline source metadata");
    requireNear(actual.front().partials.front().amplitude,
                expected.frames.front().partials.front().amplitude,
                1.0e-5,
                "realtime live spectral amplitude should match offline");
    requireNear(actual.front().partials.front().frequencyHz,
                expected.frames.front().partials.front().frequencyHz,
                1.0e-5,
                "realtime live spectral frequency should match offline");
    // ADR-0016: the Hold presents the frame from frame 63, the sample that
    // completes it.
    for (std::size_t frame = 0; frame < frameCount; ++frame)
    {
        requireNear(left[frame], frame < 63 ? 0.0 : 0.75, 1.0e-5,
                    "realtime legacy hold amplitude");
        requireNear(right[frame], frame < 63 ? 0.0 : 8.0, 1.0e-5,
                    "realtime legacy hold frequency");
    }

    talas::runtime::RealtimeRenderSession partitioned(graph);
    require(partitioned.ready(), std::string(partitioned.error()));
    std::array<double, 63> firstLeft{};
    std::array<double, 63> firstRight{};
    const std::array<const float*, 1> firstChannels{
        realtimeInput.data()};
    require(renderStereoInputAndCount(
                partitioned,
                {firstChannels.data(), firstChannels.size()},
                firstLeft,
                firstRight,
                allocations),
            "pre-frame realtime live spectral partition should render");
    require(allocations == 0,
            "pre-frame realtime live spectral partition should not allocate");
    require(partitioned.inspectPartialSpectrum(
                "spectrum", "spectrumOut").empty(),
            "pre-frame realtime interval should expose no partial frame");
    require(std::ranges::all_of(firstLeft, [](double value) {
                return value == 0.0;
            })
                && std::ranges::all_of(firstRight, [](double value) {
                    return value == 0.0;
                }),
            "empty reset hold should produce deterministic zero legacy output");

    std::array<double, 1> lastLeft{};
    std::array<double, 1> lastRight{};
    const std::array<const float*, 1> lastChannels{
        realtimeInput.data() + 63};
    require(renderStereoInputAndCount(
                partitioned,
                {lastChannels.data(), lastChannels.size()},
                lastLeft,
                lastRight,
                allocations),
            "right-edge realtime live spectral partition should render");
    require(allocations == 0,
            "right-edge realtime live spectral partition should not allocate");
    const auto partitionedFrame = partitioned.inspectPartialSpectrum(
        "spectrum", "spectrumOut");
    require(partitionedFrame.size() == 1
                && partitionedFrame.front().sourceTimestamp
                    == actual.front().sourceTimestamp
                && partitionedFrame.front().sourceSequence
                    == actual.front().sourceSequence,
            "callback partitioning should preserve realtime partial metadata");
    requireNear(partitionedFrame.front().partials.front().amplitude,
                actual.front().partials.front().amplitude,
                1.0e-9,
                "callback partitioning should preserve realtime amplitude");
    requireNear(partitionedFrame.front().partials.front().frequencyHz,
                actual.front().partials.front().frequencyHz,
                1.0e-9,
                "callback partitioning should preserve realtime frequency");

    partitioned.resetTransport();
    require(partitioned.inspectPartialSpectrum(
                "spectrum", "spectrumOut").empty(),
            "transport reset should clear realtime partial inspection");
    std::array<double, frameCount> resetLeft{};
    std::array<double, frameCount> resetRight{};
    require(renderStereoInputAndCount(
                partitioned,
                {channels.data(), channels.size()},
                resetLeft,
                resetRight,
                allocations),
            "reset realtime live spectral callback should render");
    require(allocations == 0,
            "reset realtime live spectral callback should not allocate");
    const auto resetFrame = partitioned.inspectPartialSpectrum(
        "spectrum", "spectrumOut");
    require(resetFrame.size() == 1
                && resetFrame.front().sourceSequence == 0
                && resetFrame.front().sourceTimestamp.absoluteFrame == 0,
            "transport reset should restart realtime partial time and sequence");

    const talas::runtime::RealtimeTransportSnapshot discontinuity{
        .epoch = 2,
        .absoluteFrame = 200,
        .playheadFrame = 200,
        .sampleRate = 64.0,
        .loopStartFrame = 0,
        .loopEndFrame = 0,
        .discontinuitySequence = 1,
        .playing = true,
        .loopEnabled = false,
    };
    partitioned.setTransportSnapshotBeforeRender(discontinuity);
    talas::runtime::RealtimeRenderSession replacement(graph);
    require(replacement.ready(), std::string(replacement.error()));
    replacement.setTransportSnapshotBeforeRender(discontinuity);
    std::array<double, frameCount> discontinuousLeft{};
    std::array<double, frameCount> discontinuousRight{};
    std::array<double, frameCount> replacementLeft{};
    std::array<double, frameCount> replacementRight{};
    require(renderStereoInputAndCount(
                replacement,
                {channels.data(), channels.size()},
                replacementLeft,
                replacementRight,
                allocations),
            "replacement realtime live spectral callback should render");
    require(allocations == 0,
            "replacement realtime live spectral callback should not allocate");
    require(renderStereoInputAndCount(
                partitioned,
                {channels.data(), channels.size()},
                discontinuousLeft,
                discontinuousRight,
                allocations),
            "discontinuous realtime live spectral callback should render");
    require(allocations == 0,
            "discontinuous realtime live spectral callback should not allocate");
    const auto discontinuousFrame = partitioned.inspectPartialSpectrum(
        "spectrum", "spectrumOut");
    const auto replacementFrame = replacement.inspectPartialSpectrum(
        "spectrum", "spectrumOut");
    require(discontinuousFrame.size() == 1
                && replacementFrame.size() == 1
                && discontinuousFrame.front().sourceSequence == 0
                && discontinuousFrame.front()
                       .sourceTimestamp.transportEpoch
                    == 2
                && discontinuousFrame.front().sourceTimestamp.absoluteFrame
                    == 200
                && discontinuousFrame.front()
                       .sourceTimestamp.discontinuitySequence
                    == 1,
            "true discontinuity should restart live spectral source authority");
    require(discontinuousFrame.front().sourceTimestamp
                == replacementFrame.front().sourceTimestamp
                && discontinuousFrame.front().sourceSequence
                    == replacementFrame.front().sourceSequence
                && discontinuousFrame.front().partials.size()
                    == replacementFrame.front().partials.size(),
            "true discontinuity should match fresh graph replacement metadata");
    for (std::size_t partial = 0;
         partial < discontinuousFrame.front().partials.size();
         ++partial)
    {
        requireNear(
            discontinuousFrame.front().partials[partial].amplitude,
            replacementFrame.front().partials[partial].amplitude,
            1.0e-9,
            "true discontinuity should match replacement amplitude");
        requireNear(
            discontinuousFrame.front().partials[partial].frequencyHz,
            replacementFrame.front().partials[partial].frequencyHz,
            1.0e-9,
            "true discontinuity should match replacement frequency");
        requireNear(
            discontinuousFrame.front().partials[partial].bandwidthHz,
            replacementFrame.front().partials[partial].bandwidthHz,
            1.0e-9,
            "true discontinuity should match replacement bandwidth");
    }
}

void testRealtimeLiveSpectralAnalysisRejectsMalformedPreparedShape()
{
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 64;
    const auto base = compile(
        makeLiveSpectralAnalysisAudioInputDocument(), settings);
    const auto requireRejected = [&settings](
        talas::runtime::RuntimePlan plan,
        std::string_view context) {
        talas::runtime::PreparedRuntimeGraph graph{
            std::move(plan), settings};
        talas::runtime::RealtimeRenderSession session{graph};
        require(!session.ready(),
                std::string(context)
                    + " should fail before the first callback");
    };

    {
        auto plan = base.plan();
        const auto output = std::ranges::find_if(
            plan.buffers,
            [](const talas::runtime::BufferSpec& buffer) {
                return buffer.nodeId == "spectrum"
                    && buffer.portId == "spectrumOut";
            });
        require(output != plan.buffers.end(),
                "realtime live spectral fixture should contain its partial buffer");
        output->partialFrameCapacity = 0;
        requireRejected(std::move(plan),
                        "missing realtime PartialSpectrumV1 shape");
    }
    {
        auto plan = base.plan();
        const auto step = std::ranges::find(
            plan.steps,
            std::string_view{"spectrum"},
            &talas::runtime::CompileStep::nodeId);
        require(step != plan.steps.end()
                    && step->preparedSpectralFrameSize.has_value(),
                "realtime live spectral fixture should retain derived frame authority");
        ++*step->preparedSpectralFrameSize;
        requireRejected(std::move(plan),
                        "tampered realtime live spectral frame size");
    }
    {
        auto plan = base.plan();
        const auto bridgeOutput = std::ranges::find_if(
            plan.buffers,
            [](const talas::runtime::BufferSpec& buffer) {
                return buffer.nodeId == "bridge"
                    && buffer.portId == "spectrumOut";
            });
        require(bridgeOutput != plan.buffers.end(),
                "realtime live spectral fixture should contain its legacy bridge buffer");
        bridgeOutput->partialFrameCapacity = 1;
        bridgeOutput->partialMaximumPartialsPerFrame =
            talas::dsp::maximumLiveSpectralPartials;
        requireRejected(std::move(plan),
                        "partial shape on realtime legacy Spectrum buffer");
    }
}

void testRealtimeLiveSpectralAnalysisSamplesDynamicScalesAndFailsClosed()
{
    constexpr std::size_t frameCount = 80;
    auto dynamicDocument = makeLiveSpectralAnalysisAudioInputDocument(
        liveSpectralAnalysisParameters({{"initFreq", "4 hz"}}));
    dynamicDocument.graph.nodes.push_back(node(
        "ampScale",
        "talas.linearRamp",
        {{"duration", "1 s"}, {"start", "0.25"}, {"end", "0.5"}}));
    dynamicDocument.graph.nodes.push_back(node(
        "freqScale", "talas.constant", {{"value", "0.5"}}));
    dynamicDocument.graph.connections.push_back(connection(
        "ampScale", "value", "spectrum", "ampScale"));
    dynamicDocument.graph.connections.push_back(connection(
        "freqScale", "value", "spectrum", "freqScale"));

    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = frameCount;
    auto dynamicGraph = compile(dynamicDocument, settings);
    const auto ampStep = std::ranges::find(
        dynamicGraph.plan().steps,
        std::string_view{"ampScale"},
        &talas::runtime::CompileStep::nodeId);
    const auto spectrumStep = std::ranges::find(
        dynamicGraph.plan().steps,
        std::string_view{"spectrum"},
        &talas::runtime::CompileStep::nodeId);
    require(ampStep != dynamicGraph.plan().steps.end()
                && spectrumStep != dynamicGraph.plan().steps.end()
                && ampStep < spectrumStep,
            "dynamic scale producer should precede live spectral analysis in the prepared plan");
    talas::runtime::RealtimeRenderSession dynamic{dynamicGraph};
    require(dynamic.ready(), std::string(dynamic.error()));
    std::array<float, frameCount> input{};
    for (std::size_t frame = 0; frame < frameCount; ++frame)
    {
        input[frame] = static_cast<float>(std::sin(
            2.0 * std::acos(-1.0) * 8.0
            * static_cast<double>(frame) / 64.0));
    }
    // ADR-0016: the session splits its callbacks at each frame a Hold
    // reads, so inspection, which shows the last process interval, sees
    // one frame per callback that completes one.
    std::size_t allocations = 0;
    struct Inspected
    {
        std::uint64_t absoluteFrame = 0;
        double frequencyHz = 0.0;
        double amplitude = 0.0;
    };
    std::vector<Inspected> frames;
    for (const auto& [offset, count] :
         std::array{std::pair<std::size_t, std::size_t>{0, 64}, std::pair<std::size_t, std::size_t>{64, 16}})
    {
        const std::array<const float*, 1> channels{input.data() + offset};
        std::array<double, frameCount> left{};
        std::array<double, frameCount> right{};
        bool rendered = false;
        {
            AllocationCounter counter;
            rendered = dynamic.render({channels.data(), channels.size()},
                std::span{left}.first(count), std::span{right}.first(count));
            allocations = counter.count();
        }
        require(rendered, "dynamic-scale realtime live spectral callback should render");
        require(allocations == 0,
            "dynamic-scale realtime live spectral callback should not allocate");
        for (const auto& frame : dynamic.inspectPartialSpectrum("spectrum", "spectrumOut"))
        {
            require(!frame.partials.empty(), "each inspected frame should hold the tone");
            frames.push_back({frame.sourceTimestamp.absoluteFrame, frame.partials.front().frequencyHz,
                frame.partials.front().amplitude});
        }
    }
    require(frames.size() == 2
                && frames[0].absoluteFrame == 0
                && frames[1].absoluteFrame == 16,
            "dynamic realtime scales should preserve exact frame-start cadence");
    requireNear(frames[0].frequencyHz,
                4.0, 1.0e-5,
                "first realtime frame-start frequency scale");
    requireNear(frames[1].frequencyHz,
                4.0, 1.0e-5,
                "second realtime frame-start frequency scale");
    requireNear(frames[0].amplitude,
                0.25, 1.0e-5,
                "first realtime frame-start amplitude scale");
    requireNear(frames[1].amplitude,
                0.3125, 1.0e-5,
                "second realtime frame-start amplitude scale");

    auto invalidDocument = makeLiveSpectralAnalysisAudioInputDocument();
    invalidDocument.graph.nodes.push_back(node(
        "freqScale", "talas.constant", {{"value", "0"}}));
    invalidDocument.graph.connections.push_back(connection(
        "freqScale", "value", "spectrum", "freqScale"));
    settings.maxBlockFrames = 64;
    auto invalidGraph = compile(invalidDocument, settings);
    talas::runtime::RealtimeRenderSession invalid{invalidGraph};
    require(invalid.ready(), std::string(invalid.error()));
    std::array<float, 64> invalidInput{};
    for (std::size_t frame = 0; frame < invalidInput.size(); ++frame)
    {
        invalidInput[frame] = static_cast<float>(std::sin(
            2.0 * std::acos(-1.0) * 8.0
            * static_cast<double>(frame) / 64.0));
    }
    const std::array<const float*, 1> invalidChannels{
        invalidInput.data()};
    std::array<double, 64> guardedLeft{};
    std::array<double, 64> guardedRight{};
    guardedLeft.fill(7.0);
    guardedRight.fill(7.0);
    require(!renderStereoInputAndCount(
                invalid,
                {invalidChannels.data(), invalidChannels.size()},
                guardedLeft,
                guardedRight,
                allocations),
            "invalid realtime freqScale should fail the owning callback");
    require(allocations == 0,
            "invalid realtime freqScale failure should not allocate");
    require(std::ranges::all_of(guardedLeft, [](double value) {
                return value == 0.0;
            })
                && std::ranges::all_of(guardedRight, [](double value) {
                    return value == 0.0;
                })
                && invalid.inspectPartialSpectrum(
                    "spectrum", "spectrumOut").empty(),
            "invalid realtime scale should publish neither output samples nor partial frames");
}

void testRealtimeSessionPreparesNativeStftEdgesAndRejectsTamperedPlans()
{
    struct Configuration
    {
        std::string frameSize;
        std::string hopSize;
        std::string window;
    };
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 48000.0;
    settings.maxBlockFrames = 17;
    for (const auto& configuration : std::vector<Configuration>{
             {"16", "16", "rectangular"},
             {"16", "8", "hann"},
             {"16", "4", "hann"},
             {"4096", "4096", "rectangular"},
             {"4096", "2048", "hann"},
             {"4096", "1024", "hann"},
         })
    {
        auto graph = compile(
            makeNativeStftDocument(
                configuration.frameSize,
                configuration.hopSize,
                configuration.window),
            settings);
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(),
                "every advertised native STFT size/window/hop edge should prepare");
        std::array<double, 17> first{};
        std::array<double, 17> repeated{};
        std::size_t allocations = 0;
        require(renderAndCount(session, first, allocations),
                "first native STFT edge callback should render");
        require(allocations == 0,
                "first native STFT edge callback should not allocate");
        require(renderAndCount(session, repeated, allocations),
                "repeated native STFT edge callback should render");
        require(allocations == 0,
                "repeated native STFT edge callback should not allocate");
    }

    const auto base = compile(
        makeNativeStftDocument("64", "32", "hann"),
        settings);
    const auto requireRejected = [&](
        talas::runtime::RuntimePlan plan,
        std::string_view context) {
        talas::runtime::PreparedRuntimeGraph tampered{
            std::move(plan), settings};
        talas::runtime::RealtimeRenderSession session(tampered);
        require(!session.ready(),
                std::string(context)
                    + " should fail before the first callback");
    };

    {
        auto plan = base.plan();
        auto spectrum = std::ranges::find_if(
            plan.buffers,
            [](const talas::runtime::BufferSpec& buffer) {
                return buffer.nodeId == "forward"
                    && buffer.portId == "spectrumOut";
            });
        require(spectrum != plan.buffers.end(),
                "tampered native STFT fixture should contain its complex buffer");
        spectrum->complexFrameCapacity = 0;
        requireRejected(std::move(plan),
                        "missing ComplexSpectrum shape");
    }
    {
        auto plan = base.plan();
        auto spectrum = std::ranges::find_if(
            plan.buffers,
            [](const talas::runtime::BufferSpec& buffer) {
                return buffer.nodeId == "forward"
                    && buffer.portId == "spectrumOut";
            });
        spectrum->complexMaximumBinsPerFrame = 34;
        requireRejected(std::move(plan),
                        "mismatched ComplexSpectrum bin capacity");
    }
    {
        auto plan = base.plan();
        auto spectrum = std::ranges::find_if(
            plan.buffers,
            [](const talas::runtime::BufferSpec& buffer) {
                return buffer.nodeId == "forward"
                    && buffer.portId == "spectrumOut";
            });
        spectrum->complexFrameCapacity =
            std::numeric_limits<std::size_t>::max();
        spectrum->complexMaximumBinsPerFrame =
            std::numeric_limits<std::size_t>::max();
        requireRejected(std::move(plan),
                        "overflowed ComplexSpectrum storage shape");
    }
    {
        auto plan = base.plan();
        auto audio = std::ranges::find_if(
            plan.buffers,
            [](const talas::runtime::BufferSpec& buffer) {
                return buffer.type == talas::core::PortType::Audio;
            });
        require(audio != plan.buffers.end(),
                "tampered native STFT fixture should contain an audio buffer");
        audio->complexChannelCount = 1;
        requireRejected(std::move(plan),
                        "complex metadata on a scalar buffer");
    }
    {
        auto plan = base.plan();
        auto inverse = std::ranges::find(
            plan.steps,
            std::string_view{"inverse"},
            &talas::runtime::CompileStep::nodeId);
        require(inverse != plan.steps.end(),
                "tampered native STFT fixture should contain its inverse step");
        auto hop = std::ranges::find(
            inverse->parameters,
            std::string_view{"hopSize"},
            &talas::runtime::ParameterValue::id);
        auto window = std::ranges::find(
            inverse->parameters,
            std::string_view{"window"},
            &talas::runtime::ParameterValue::id);
        require(hop != inverse->parameters.end()
                    && window != inverse->parameters.end(),
                "tampered native STFT fixture should retain inverse parameters");
        hop->value = 64.0;
        window->choice = "rectangular";
        requireRejected(std::move(plan),
                        "inverse/producer configuration mismatch");
    }
    {
        auto plan = base.plan();
        auto inverse = std::ranges::find(
            plan.steps,
            std::string_view{"inverse"},
            &talas::runtime::CompileStep::nodeId);
        require(inverse != plan.steps.end()
                    && !inverse->inputLatencyFrames.empty(),
                "tampered native STFT fixture should retain inverse latency");
        inverse->inputLatencyFrames.front() = std::nullopt;
        requireRejected(std::move(plan),
                        "unknown inverse input latency");
    }
    {
        auto plan = base.plan();
        auto inverse = std::ranges::find(
            plan.steps,
            std::string_view{"inverse"},
            &talas::runtime::CompileStep::nodeId);
        require(inverse != plan.steps.end()
                    && !inverse->inputLatencyFrames.empty()
                    && inverse->inputLatencyFrames.front().has_value()
                    && *inverse->inputLatencyFrames.front() > 0,
                "tampered native STFT fixture should retain exact inverse input latency");
        --*inverse->inputLatencyFrames.front();
        requireRejected(std::move(plan),
                        "mismatched inverse input latency");
    }
    {
        auto plan = base.plan();
        auto forward = std::ranges::find(
            plan.steps,
            std::string_view{"forward"},
            &talas::runtime::CompileStep::nodeId);
        auto inverse = std::ranges::find(
            plan.steps,
            std::string_view{"inverse"},
            &talas::runtime::CompileStep::nodeId);
        require(forward != plan.steps.end()
                    && inverse != plan.steps.end()
                    && !inverse->inputLatencyFrames.empty(),
                "realtime phase-tamper fixture should retain both native steps");
        constexpr std::size_t falseInputLatency = 5;
        constexpr std::size_t falseOutputLatency =
            falseInputLatency + 64 - 1;
        forward->cumulativeInputLatencyFrames = falseInputLatency;
        forward->cumulativeOutputLatencyFrames = falseOutputLatency;
        inverse->inputLatencyFrames.front() = falseOutputLatency;
        inverse->cumulativeInputLatencyFrames = falseOutputLatency;
        inverse->cumulativeOutputLatencyFrames = falseOutputLatency;
        requireRejected(std::move(plan),
                        "forward cumulative phase detached from its realtime audio source");
    }
}

void testRealtimeNativeStftPreservesSegmentationLoopAndPauseAndResetsOnDiscontinuity()
{
    {
        auto document = makeNativeStftDocument(
            "64", "16", "hann");
        document.graph.nodes.push_back(node(
            "segment",
            "talas.constant",
            {{"value", "!Segment"}}));
        talas::runtime::RenderSettings settings;
        settings.sampleRate = 64.0;
        settings.maxBlockFrames = 17;
        settings.eventValues.push_back({
            "Segment", 0.0, talas::expr::ValueDomain::Scalar});
        auto graph = compile(document, settings);
        const auto offline = talas::runtime::renderOffline(graph, 68);
        require(offline.ok(),
                "segmented native STFT offline reference should render");

        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(), std::string(session.error()));
        std::vector<double> actual;
        actual.reserve(68);
        for (std::size_t callback = 0; callback < 4; ++callback)
        {
            if (callback == 3)
            {
                require(session.scheduleEventValue(
                            "Segment",
                            1.0,
                            talas::expr::ValueDomain::Scalar,
                            5),
                        "unused Event Value should schedule an internal callback segment");
            }
            std::array<double, 17> block{};
            std::size_t allocations = 0;
            require(renderAndCount(session, block, allocations),
                    "segmented native STFT callback should render");
            require(allocations == 0,
                    "segmented native STFT callback should not allocate");
            actual.insert(actual.end(), block.begin(), block.end());
        }
        for (std::size_t frame = 0; frame < actual.size(); ++frame)
        {
            requireNear(
                actual[frame],
                offline.mono[frame],
                1.0e-9,
                "Event Value callback segmentation must not change native STFT output");
        }
    }

    {
        talas::runtime::RenderSettings settings;
        settings.sampleRate = 64.0;
        settings.maxBlockFrames = 17;
        settings.transportLoop = talas::runtime::TransportLoopRegion{0, 32};
        auto graph = compile(
            makeNativeStftDocument("64", "64", "rectangular"),
            settings);
        const auto offline = talas::runtime::renderOffline(graph, 96);
        require(offline.ok(),
                "loop/pause native STFT offline reference should render");
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(), std::string(session.error()));

        const auto snapshot = [](std::uint64_t absoluteFrame, bool playing) {
            return talas::runtime::RealtimeTransportSnapshot{
                .epoch = 1,
                .absoluteFrame = absoluteFrame,
                .playheadFrame = absoluteFrame % 32,
                .sampleRate = 64.0,
                .loopStartFrame = 0,
                .loopEndFrame = 32,
                .discontinuitySequence = 0,
                .playing = playing,
                .loopEnabled = true,
            };
        };
        const std::array<std::size_t, 6> partitions{17, 17, 17, 17, 17, 11};
        std::vector<double> actual;
        actual.reserve(96);
        std::uint64_t absoluteFrame = 0;
        for (std::size_t index = 0; index < partitions.size(); ++index)
        {
            if (index == 2)
            {
                session.setTransportSnapshotBeforeRender(
                    snapshot(absoluteFrame, false));
            }
            session.setTransportSnapshotBeforeRender(
                snapshot(absoluteFrame, true));
            std::vector<double> block(partitions[index], 0.0);
            std::size_t allocations = 0;
            require(renderAndCount(session, block, allocations),
                    "loop/pause native STFT callback should render");
            require(allocations == 0,
                    "loop/pause native STFT callback should not allocate");
            actual.insert(actual.end(), block.begin(), block.end());
            absoluteFrame += partitions[index];
        }
        for (std::size_t frame = 0; frame < actual.size(); ++frame)
        {
            requireNear(
                actual[frame],
                offline.mono[frame],
                1.0e-9,
                "ordinary loop wrap and pause must preserve native STFT history");
        }
        require(std::abs(actual[64]) > 1.0e-6,
                "native STFT history should survive the loop wrap through first reconstruction");

        auto discontinuity = snapshot(200, true);
        discontinuity.epoch = 2;
        discontinuity.discontinuitySequence = 1;
        session.setTransportSnapshotBeforeRender(discontinuity);
        talas::runtime::RealtimeRenderSession fresh(graph);
        require(fresh.ready(), std::string(fresh.error()));
        fresh.setTransportSnapshotBeforeRender(discontinuity);
        std::array<double, 17> resetOutput{};
        std::array<double, 17> freshOutput{};
        std::size_t allocations = 0;
        require(renderAndCount(session, resetOutput, allocations),
                "discontinuous native STFT callback should render");
        require(allocations == 0,
                "discontinuous native STFT callback should not allocate");
        require(renderAndCount(fresh, freshOutput, allocations),
                "fresh discontinuity reference should render");
        require(allocations == 0,
                "fresh discontinuity reference should not allocate");
        for (std::size_t frame = 0; frame < resetOutput.size(); ++frame)
        {
            requireNear(
                resetOutput[frame],
                freshOutput[frame],
                1.0e-9,
                "epoch/discontinuity change should restore fresh native STFT state");
        }
    }
}

void testRealtimeNativeStftGraphGenerationsOwnIndependentPreparedState()
{
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 17;
    auto oldGraph = compile(
        makeNativeStftDocument("64", "64", "rectangular"),
        settings);
    const auto oldExpected = talas::runtime::renderOffline(oldGraph, 68);
    require(oldExpected.ok(),
            "old native STFT graph-generation reference should render");
    talas::runtime::RealtimeRenderSession oldSession(oldGraph);
    require(oldSession.ready(), std::string(oldSession.error()));

    const auto renderExpectedBlock = [](
        talas::runtime::RealtimeRenderSession& session,
        const std::vector<double>& expected,
        std::size_t offset,
        std::string_view context) {
        std::array<double, 17> block{};
        std::size_t allocations = 0;
        require(renderAndCount(session, block, allocations),
                std::string(context) + " should render");
        require(allocations == 0,
                std::string(context) + " should not allocate");
        for (std::size_t frame = 0; frame < block.size(); ++frame)
        {
            requireNear(
                block[frame],
                expected[offset + frame],
                1.0e-9,
                std::string(context)
                    + " should retain its own prepared state");
        }
    };

    renderExpectedBlock(
        oldSession, oldExpected.mono, 0, "old native STFT first callback");
    renderExpectedBlock(
        oldSession, oldExpected.mono, 17, "old native STFT second callback");

    auto replacementGraph = compile(
        makeNativeStftDocument("64", "16", "hann"),
        settings);
    const auto replacementExpected = talas::runtime::renderOffline(
        replacementGraph,
        34);
    require(replacementExpected.ok(),
            "replacement native STFT graph-generation reference should render");
    talas::runtime::RealtimeRenderSession replacementSession(
        replacementGraph);
    require(replacementSession.ready(),
            std::string(replacementSession.error()));

    renderExpectedBlock(
        replacementSession,
        replacementExpected.mono,
        0,
        "replacement native STFT first callback");
    renderExpectedBlock(
        oldSession,
        oldExpected.mono,
        34,
        "retained old native STFT callback");
    renderExpectedBlock(
        replacementSession,
        replacementExpected.mono,
        17,
        "replacement native STFT second callback");
    renderExpectedBlock(
        oldSession,
        oldExpected.mono,
        51,
        "retired-later old native STFT callback");
}

void testRealtimeNativeStftFailsClosedAndRecoversWithoutPartialState()
{
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 17;
    auto compiled = talas::runtime::compileProject(
        makeNativeStftAudioInputDocument(),
        talas::core::makeBuiltinNodeRegistry(),
        settings);
    require(compiled.ok(),
            "native STFT fail-closed fixture should compile");
    auto graph = std::move(*compiled.graph);
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<float, 17> input{};
    input[3] = 1.0F;
    input[5] = std::numeric_limits<float>::quiet_NaN();
    std::array<const float*, 1> channels{input.data()};
    std::array<double, 17> rejected{};
    std::ranges::fill(rejected, 42.0);
    std::size_t allocations = 0;
    require(!renderStereoInputAndCount(
                session,
                {channels.data(), channels.size()},
                rejected,
                {},
                allocations),
            "non-finite native STFT input should fail the callback");
    require(allocations == 0,
            "failed native STFT callback should not allocate");
    require(std::ranges::all_of(rejected, [](double value) {
                return value == 0.0;
            }),
            "failed native STFT callback should zero the guarded output");

    input[5] = 0.0F;
    std::array<double, 17> recoveredFirst{};
    require(renderStereoInputAndCount(
                session,
                {channels.data(), channels.size()},
                recoveredFirst,
                {},
                allocations),
            "native STFT should recover at the same timeline position");
    require(allocations == 0,
            "recovered native STFT callback should not allocate");
    input.fill(0.0F);
    std::array<double, 17> recoveredSecond{};
    require(renderStereoInputAndCount(
                session,
                {channels.data(), channels.size()},
                recoveredSecond,
                {},
                allocations),
            "recovered native STFT tail callback should render");
    require(allocations == 0,
            "recovered native STFT tail callback should not allocate");
    requireNear(
        recoveredSecond[1],
        1.0,
        1.0e-9,
        "failed callback should not partially advance native STFT state");
}

void testRealtimeSerialNativeStftRoundTripsHonorKnownUpstreamLatency()
{
    constexpr std::size_t frameCount = 96;
    constexpr std::size_t impulseFrame = 4;
    constexpr std::size_t expectedLatency = 2 * (16 - 1);
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 17;
    auto graph = compile(
        makeSerialNativeStftAudioInputDocument(),
        settings);
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::vector<float> input(frameCount, 0.0F);
    input[impulseFrame] = 1.0F;
    const std::array partitions{7U, 3U, 17U, 5U, 11U};
    const auto renderTrace = [&](std::size_t partitionSeed) {
        std::vector<double> output(frameCount, 0.0);
        std::size_t offset = 0;
        std::size_t partitionIndex = partitionSeed;
        while (offset < frameCount)
        {
            const auto count = std::min<std::size_t>(
                partitions[partitionIndex % partitions.size()],
                frameCount - offset);
            const std::array<const float*, 1> channels{
                input.data() + offset};
            std::size_t allocations = 0;
            require(renderStereoInputAndCount(
                        session,
                        {channels.data(), channels.size()},
                        std::span<double>{output}.subspan(offset, count),
                        {},
                        allocations),
                    "serial realtime native STFT callback should render");
            require(allocations == 0,
                    "serial realtime native STFT callback should not allocate");
            offset += count;
            ++partitionIndex;
        }
        return output;
    };
    const auto output = renderTrace(0);
    const auto requireExpectedTrace = [&](std::span<const double> trace) {
        for (std::size_t frame = 0; frame < frameCount; ++frame)
        {
            requireNear(
                trace[frame],
                frame == impulseFrame + expectedLatency ? 1.0 : 0.0,
                1.0e-6,
                "serial realtime native STFT round trips should retain exact cumulative phase");
        }
    };
    requireExpectedTrace(output);

    session.resetTransport();
    const auto resetOutput = renderTrace(2);
    requireExpectedTrace(resetOutput);
}

void testRealtimeParallelNativeStftPathsOwnNonAliasedComplexBuffers()
{
    constexpr std::size_t frameCount = 160;
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 17;
    auto graph = compile(makeParallelNativeStftDocument(), settings);
    const auto offline = talas::runtime::renderOffline(graph, frameCount);
    require(offline.ok(),
            "parallel native STFT offline reference should render");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    const std::array<std::size_t, 6> pattern{1, 17, 3, 11, 5, 13};
    std::vector<double> actual;
    actual.reserve(frameCount);
    std::size_t partitionIndex = 0;
    while (actual.size() != frameCount)
    {
        const auto count = std::min(
            frameCount - actual.size(),
            pattern[partitionIndex % pattern.size()]);
        std::vector<double> block(count, 0.0);
        std::size_t allocations = 0;
        require(renderAndCount(session, block, allocations),
                "parallel native STFT callback should render");
        require(allocations == 0,
                "parallel native STFT callback should not allocate");
        actual.insert(actual.end(), block.begin(), block.end());
        ++partitionIndex;
    }
    for (std::size_t frame = 0; frame < frameCount; ++frame)
    {
        requireNear(
            actual[frame],
            offline.mono[frame],
            1.0e-9,
            "parallel native STFT paths should retain non-aliased complex sequences");
    }
}

