void testRealtimeSessionPublishesPreparedDisplayAnalysisWithoutAffectingAudio()
{
    for (const auto& typeId : {"talas.oscilloscopeDisplay", "talas.spectrumAnalyzerDisplay"})
    {
        talas::runtime::RenderSettings settings{4.0, 3};
        settings.enableRealtimeAnalysisCapture = true;
        settings.realtimeAnalysisQueueCapacity = 1;
        settings.eventValues = {
            {"UnusedAutomation", 0.0,
             talas::expr::ValueDomain::Scalar},
        };
        settings.eventValueChanges = {
            {0, "UnusedAutomation", 0.0,
             talas::expr::ValueDomain::Scalar,
             talas::core::AutomationInterpolation::
                 Linear},
            {3, "UnusedAutomation", 1.0,
             talas::expr::ValueDomain::Scalar},
        };
        auto graph = compile(makeAudioTransparentDisplayDocument(typeId), std::move(settings));
        const auto capture = graph.analysisCapture();
        require(capture != nullptr && capture->ready(), "display graph should prepare analysis capture");
        const auto probeIndex = capture->preferredProbeIndex("display");
        require(probeIndex.has_value(), "display node should resolve a prepared probe");
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(), std::string(session.error()));
        require(session.bindAnalysisStage(77),
            "prepared display capture should bind exact stage before render");

        std::array<double, 3> first{};
        std::size_t allocations = 0;
        require(renderAndCount(session, first, allocations), "captured display block should render");
        require(allocations == 0, "captured display publication should not allocate");
        std::array<double, 3> captured{};
        const auto capturedRecord = capture->copyLatestRecord(
            *probeIndex, captured);
        require(capturedRecord.has_value()
                && capturedRecord->stageId == 77
                && capturedRecord->bindingGeneration == 1
                && capturedRecord->absoluteSamplePosition == 0
                && capturedRecord->valueCount == 3,
            "display capture should aggregate internally segmented automation "
            "into one exact stage-bound callback record");
        require(
            capture->droppedBlockCount(
                *probeIndex)
                == 0,
            "internally segmented automation should publish only one analysis block");
        for (std::size_t frame = 0; frame < first.size(); ++frame)
            requireNear(captured[frame], first[frame], 1.0e-12,
                        "display capture should match transparent audio output");

        std::array<double, 3> second{};
        std::array<double, 3> third{};
        require(renderAndCount(session, second, allocations), "second captured display block should render");
        require(allocations == 0, "second captured display publication should not allocate");
        require(renderAndCount(session, third, allocations),
                "queue-full capture should not fail transparent audio rendering");
        require(allocations == 0, "queue-full capture path should not allocate");
        require(capture->droppedBlockCount(*probeIndex) == 1,
                "queue-full display capture should account for one dropped block");
    }

    talas::runtime::RenderSettings annotationSettings{4.0, 3};
    annotationSettings.enableRealtimeAnalysisCapture = true;
    const auto annotationGraph = compile(
        makeAudioTransparentDisplayDocument("talas.annotation"),
        std::move(annotationSettings));
    require(annotationGraph.analysisCapture() == nullptr,
            "annotation should not create a realtime analysis capture");
}

void testOscilloscopeDirectSoundTriggerCaptureIsAlignedAndTransparent()
{
    auto document = makeAudioTransparentDisplayDocument("talas.oscilloscopeDisplay");
    document.graph.nodes.push_back(node("pulse", "talas.oscillator", {
        {"frequency", "2 hz"}, {"amplitude", "1"},
    }));
    document.graph.connections.push_back(connection(
        "pulse", "audioOut", "display", "sweepOrTrig"));
    talas::runtime::RenderSettings referenceSettings{8.0, 4};
    const auto referenceGraph = compile(document, referenceSettings);
    const auto reference = talas::runtime::renderOffline(referenceGraph, 84);
    require(reference.ok(), "direct Sound trigger reference should render offline");

    talas::runtime::RenderSettings settings{8.0, 4};
    settings.enableRealtimeAnalysisCapture = true;
    settings.realtimeAnalysisQueueCapacity = 2;
    auto graph = compile(document, std::move(settings));
    const auto capture = graph.analysisCapture();
    require(capture != nullptr && capture->ready()
            && capture->maxPayloadValues()
                >= talas::runtime::realtimeOscilloscopeHistoryFrames,
        "direct Sound trigger graph should prepare capture");
    const auto displayedProbe = capture->preferredProbeIndex("display");
    require(displayedProbe.has_value(),
        "direct Sound trigger graph should retain the displayed probe");
    const auto* displayedSpec = capture->probeSpec(*displayedProbe);
    require(displayedSpec != nullptr,
        "displayed probe should have an exact prepared specification");
    const auto directProbe = capture->probeIndex(
        "display", "sweepOrTrigOut", displayedSpec->scopeId,
        talas::runtime::RealtimeAnalysisPayloadKind::AudioBlock);
    require(directProbe.has_value() && *displayedProbe != *directProbe,
        "displayed audio and direct trigger should use distinct capture probes");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    require(session.bindAnalysisStage(78),
        "direct Sound trigger capture should bind an exact stage");
    for (std::size_t block = 0; block < 2; ++block)
    {
        std::array<double, 4> output{};
        std::size_t allocations = 0;
        require(renderAndCount(session, output, allocations) && allocations == 0,
            "direct Sound trigger callback should render without allocation");
        std::array<double, talas::runtime::realtimeOscilloscopeHistoryFrames>
            displayed{};
        std::array<double, talas::runtime::realtimeOscilloscopeHistoryFrames>
            trigger{};
        const auto displayedRecord = capture->copyLatestRecord(
            *displayedProbe, displayed);
        const auto directRecord = capture->copyLatestRecord(
            *directProbe, trigger);
        require(displayedRecord.has_value() && directRecord.has_value()
                && displayedRecord->absoluteSamplePosition == 0
                && directRecord->absoluteSamplePosition
                    == displayedRecord->absoluteSamplePosition
                && directRecord->stageId == displayedRecord->stageId
                && directRecord->bindingGeneration
                    == displayedRecord->bindingGeneration
                && displayedRecord->valueCount == (block + 1) * 4
                && directRecord->valueCount == (block + 1) * 4,
            "direct trigger and displayed rolling traces should share exact sample history");
        for (std::size_t frame = 0; frame < output.size(); ++frame)
        {
            requireNear(output[frame], reference.mono[block * 4 + frame],
                1.0e-12, "direct trigger must not alter audible output");
            requireNear(displayed[block * 4 + frame], output[frame], 1.0e-12,
                "displayed probe should capture transparent output");
        }
        if (block == 0)
            require(std::abs(trigger[1] - displayed[1]) > 0.1,
                "direct Sound probe should capture its own distinct waveform");
    }

    for (std::size_t block = 2; block < 20; ++block)
    {
        std::array<double, 4> output{};
        std::size_t allocations = 0;
        require(renderAndCount(session, output, allocations) && allocations == 0,
            "skipped UI polls should not allocate or interrupt audio");
        for (std::size_t frame = 0; frame < output.size(); ++frame)
            requireNear(output[frame], reference.mono[block * 4 + frame],
                1.0e-12, "rolling analysis should leave later audio unchanged");
    }
    std::array<double, talas::runtime::realtimeOscilloscopeHistoryFrames>
        displayed{};
    std::array<double, talas::runtime::realtimeOscilloscopeHistoryFrames>
        trigger{};
    const auto staleRecord = capture->copyLatestRecord(
        *displayedProbe, displayed);
    const auto staleTrigger = capture->copyLatestRecord(
        *directProbe, trigger);
    require(staleRecord.has_value() && staleTrigger.has_value()
            && staleRecord->valueCount == 16
            && staleTrigger->valueCount == 16
            && capture->droppedBlockCount(*displayedProbe) > 0,
        "a full UI queue should expose its latest accepted snapshot and count drops");
    std::array<double, 4> freshOutput{};
    std::size_t freshAllocations = 0;
    require(renderAndCount(session, freshOutput, freshAllocations)
            && freshAllocations == 0,
        "fresh callback after a UI drain should publish without allocation");
    for (std::size_t frame = 0; frame < freshOutput.size(); ++frame)
        requireNear(freshOutput[frame], reference.mono[80 + frame],
            1.0e-12, "rolling capture should leave the fresh audio unchanged");
    const auto displayedRecord = capture->copyLatestRecord(
        *displayedProbe, displayed);
    const auto directRecord = capture->copyLatestRecord(
        *directProbe, trigger);
    require(displayedRecord.has_value() && directRecord.has_value()
            && displayedRecord->absoluteSamplePosition == 0
            && directRecord->absoluteSamplePosition == 0
            && displayedRecord->valueCount == 84
            && directRecord->valueCount == 84,
        "fresh rolling snapshot should recover all 84 samples across skipped short callbacks");
    const auto window = talas::audio::selectOscilloscopeWindow(
        std::span<const double>{displayed.data(), 84},
        std::span<const double>{trigger.data(), 84},
        64, talas::audio::OscilloscopeTrigger::Rising, 0.5);
    require(window.triggered,
        "a direct Sound pulse should trigger the actual 64-sample sweep across callbacks");
}

void testOscilloscopeSubAudioSweepSurvivesSkippedPollsAndPreservesRawTrigger()
{
    auto document = makeAudioTransparentDisplayDocument(
        "talas.oscilloscopeDisplay");
    document.graph.nodes[1] = node("display", "talas.oscilloscopeDisplay",
        {{"initialSweepFrequency", "0.25 hz"}});
    const auto referenceGraph = compile(
        document, talas::runtime::RenderSettings{1024.0, 8});
    const auto reference = talas::runtime::renderOffline(referenceGraph, 4104);
    require(reference.ok(), "slow sweep reference should render offline");

    talas::runtime::RenderSettings settings{1024.0, 8};
    settings.enableRealtimeAnalysisCapture = true;
    settings.realtimeAnalysisQueueCapacity = 2;
    auto graph = compile(document, std::move(settings));
    const auto capture = graph.analysisCapture();
    require(capture != nullptr && capture->ready(),
        "slow sweep should prepare bounded realtime capture");
    const auto rawProbe = capture->preferredProbeIndex("display");
    require(rawProbe.has_value(), "slow sweep must retain its raw trigger probe");
    const auto slowProbe = capture->probeIndex(
        "display", "@slow-sweep", capture->probeSpec(*rawProbe)->scopeId,
        talas::runtime::RealtimeAnalysisPayloadKind::AudioBlock);
    require(slowProbe.has_value()
            && capture->probeSpec(*slowProbe)->sampleStrideFrames == 16,
        "0.25 Hz should retain one sample per 16 frames at 1024 Hz");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready() && session.bindAnalysisStage(83),
        "slow sweep session should bind its prepared stage");
    for (std::size_t block = 0; block < 512; ++block)
    {
        std::array<double, 8> output{};
        std::size_t allocations = 0;
        require(renderAndCount(session, output, allocations) && allocations == 0,
            "short slow-sweep callbacks should render without allocation");
        for (std::size_t frame = 0; frame < output.size(); ++frame)
            requireNear(output[frame], reference.mono[block * 8 + frame],
                1.0e-12, "analysis must not alter the audible waveform");
    }
    std::array<double, talas::runtime::realtimeOscilloscopeHistoryFrames>
        rawTrace{};
    std::array<double, talas::runtime::realtimeOscilloscopeHistoryFrames>
        slowTrace{};
    const auto staleRaw = capture->copyLatestRecord(*rawProbe, rawTrace);
    const auto staleSlow = capture->copyLatestRecord(*slowProbe, slowTrace);
    require(staleRaw.has_value() && staleSlow.has_value()
            && capture->droppedBlockCount(*slowProbe) > 0,
        "a skipped UI should leave queued evidence and count dropped slow snapshots");

    std::array<double, 8> finalOutput{};
    std::size_t allocations = 0;
    require(renderAndCount(session, finalOutput, allocations) && allocations == 0,
        "fresh slow-sweep callback should remain allocation free");
    const auto raw = capture->copyLatestRecord(*rawProbe, rawTrace);
    const auto slow = capture->copyLatestRecord(*slowProbe, slowTrace);
    require(raw.has_value() && slow.has_value()
            && raw->valueCount == 512
            && raw->absoluteSamplePosition == 3592
            && slow->valueCount == 257
            && slow->absoluteSamplePosition == 0,
        "fresh records should recover one full slow period and 512 raw trigger samples");
    for (std::size_t point = 0; point < slow->valueCount; ++point)
        requireNear(slowTrace[point], reference.mono[point * 16],
            1.0e-12, "slow trace must sample the original input over four seconds");
    for (std::size_t frame = 0; frame < raw->valueCount; ++frame)
        requireNear(rawTrace[frame], reference.mono[3592 + frame],
            1.0e-12, "trigger trace must preserve full-rate recent audio");
}

