{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "display", "talas.oscilloscopeDisplay"));
    document.graph.nodes.push_back(node("left", "talas.oscillator",
        {{"frequency", "1 hz"}, {"amplitude", "1"}}));
    document.graph.nodes.push_back(node("right", "talas.oscillator",
        {{"frequency", "2 hz"}, {"amplitude", "1"}}));
    document.graph.nodes.push_back(node("level", "talas.constant",
        {{"value", "!ScopeLevel"}}));
    document.graph.connections.push_back(connection(
        "left", "audioOut", "display", "audioIn"));
    document.graph.connections.push_back(connection(
        "right", "audioOut", "display", "rightIn"));
    document.graph.connections.push_back(connection(
        "level", "value", "display", "level"));
    document.graph.connections.push_back(connection(
        "display", "audioOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "display", "rightOut", "out", "rightIn"));

    talas::runtime::RenderSettings settings{8.0, 4};
    settings.eventValues = {{"ScopeLevel", 0.25,
        talas::expr::ValueDomain::Scalar}};
    settings.eventValueChanges = {{4, "ScopeLevel", 0.5,
        talas::expr::ValueDomain::Scalar}};
    settings.enableRealtimeAnalysisCapture = true;
    settings.realtimeAnalysisQueueCapacity = 4;
    auto graph = compile(document, std::move(settings));
    const auto offline = talas::runtime::renderOffline(graph, 8);
    require(offline.ok() && offline.right.size() == 8,
        "connected OscilloscopeDisplay Level should render stereo offline");
    constexpr double rootHalf = 0.7071067811865476;
    constexpr std::array<double, 8> leftRaw{
        0.0, rootHalf, 1.0, rootHalf,
        0.0, -rootHalf, -1.0, -rootHalf};
    constexpr std::array<double, 8> rightRaw{
        0.0, 1.0, 0.0, -1.0,
        0.0, 1.0, 0.0, -1.0};
    for (std::size_t frame = 0; frame < 8; ++frame)
    {
        const auto level = frame < 4 ? 0.25 : 0.5;
        requireNear(offline.mono[frame], leftRaw[frame] * level,
            1.0e-12, "connected Level left offline oracle");
        requireNear(offline.right[frame], rightRaw[frame] * level,
            1.0e-12, "connected Level right offline oracle");
    }

    const auto capture = graph.analysisCapture();
    require(capture != nullptr && capture->ready(),
        "connected Level should prepare display capture");
    const auto leftProbe = capture->preferredProbeIndex("display");
    require(leftProbe.has_value(),
        "connected Level should retain raw left display probe");
    const auto rightProbe = capture->probeIndex(
        "display", "rightOut", capture->probeSpec(*leftProbe)->scopeId,
        talas::runtime::RealtimeAnalysisPayloadKind::AudioBlock);
    require(rightProbe.has_value(),
        "connected Level should retain raw right display probe");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready() && session.bindAnalysisStage(87),
        "connected Level should bind prepared analysis stage");
    for (std::size_t block = 0; block < 2; ++block)
    {
        std::array<double, 4> left{}, right{};
        std::size_t allocations = 0;
        require(renderStereoAndCount(session, left, right, allocations)
                && allocations == 0,
            "connected Level prepared callback should not allocate");
        for (std::size_t frame = 0; frame < 4; ++frame)
        {
            requireNear(left[frame], offline.mono[block * 4 + frame],
                1.0e-12, "connected Level left prepared oracle");
            requireNear(right[frame], offline.right[block * 4 + frame],
                1.0e-12, "connected Level right prepared oracle");
        }
    }
    std::array<double, talas::runtime::realtimeOscilloscopeHistoryFrames>
        leftTrace{}, rightTrace{};
    const auto leftRecord = capture->copyLatestRecord(*leftProbe, leftTrace);
    const auto rightRecord = capture->copyLatestRecord(*rightProbe, rightTrace);
    require(leftRecord && rightRecord
            && leftRecord->valueCount == 8
            && rightRecord->valueCount == 8,
        "connected Level should preserve eight raw display samples");
    for (std::size_t frame = 0; frame < 8; ++frame)
    {
        requireNear(leftTrace[frame], leftRaw[frame],
            1.0e-12, "connected Level must not attenuate displayed left input");
        requireNear(rightTrace[frame], rightRaw[frame],
            1.0e-12, "connected Level must not attenuate displayed right input");
    }

    talas::runtime::RenderSettings invalidSettings{8.0, 4};
    invalidSettings.eventValues = {{"ScopeLevel", 5.0,
        talas::expr::ValueDomain::Scalar}};
    auto invalidGraph = compile(document, std::move(invalidSettings));
    const auto invalidOffline = talas::runtime::renderOffline(invalidGraph, 4);
    require(!invalidOffline.ok(),
        "out-of-range connected Level must reject offline rendering");
    talas::runtime::RealtimeRenderSession invalidSession(invalidGraph);
    require(invalidSession.ready(), std::string(invalidSession.error()));
    std::array<double, 4> invalidLeft{}, invalidRight{};
    invalidLeft.fill(7.0);
    invalidRight.fill(9.0);
    require(!invalidSession.render(invalidLeft, invalidRight),
        "out-of-range connected Level must reject prepared callback");
    require(std::ranges::all_of(invalidLeft,
                [](double value) { return value == 0.0; })
            && std::ranges::all_of(invalidRight,
                [](double value) { return value == 0.0; }),
        "rejected connected Level must silence the complete caller block");
}

void testOscilloscopeTrigSwapUsesDistinctRightLaneWithoutChangingStereoAudio()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("display", "talas.oscilloscopeDisplay",
        {
            {"level", "0.25"},
            {"sweepFreq", "2 hz"},
            {"initialSweepFrequency", "0.25 hz"},
            booleanParameter("trigSwap", true),
            choiceParameter("sweepOrTrig", "trigger"),
            choiceParameter("trigThresh", "falling"),
        }));
    document.graph.nodes.push_back(node("left", "talas.oscillator",
        {{"frequency", "1 hz"}, {"amplitude", "1"}}));
    document.graph.nodes.push_back(node("right", "talas.oscillator",
        {{"frequency", "1.5 hz"}, {"amplitude", "1"}}));
    document.graph.connections.push_back(connection(
        "left", "audioOut", "display", "audioIn"));
    document.graph.connections.push_back(connection(
        "right", "audioOut", "display", "rightIn"));
    document.graph.connections.push_back(connection(
        "display", "audioOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "display", "rightOut", "out", "rightIn"));

    talas::runtime::RenderSettings settings{8.0, 4};
    settings.enableRealtimeAnalysisCapture = true;
    settings.realtimeAnalysisQueueCapacity = 4;
    auto graph = compile(document, std::move(settings));
    const auto reference = talas::runtime::renderOffline(graph, 16);
    require(reference.ok() && reference.right.size() == 16,
        "TrigSwap stereo reference should render offline");
    const auto capture = graph.analysisCapture();
    require(capture != nullptr && capture->ready(),
        "TrigSwap stereo graph should prepare capture");
    const auto leftProbe = capture->preferredProbeIndex("display");
    require(leftProbe.has_value()
            && capture->probeSpec(*leftProbe)->triggerOnRight
            && capture->probeSpec(*leftProbe)->triggerModeEnabled
            && capture->probeSpec(*leftProbe)->triggerOnFallingEdge
            && capture->probeSpec(*leftProbe)->sweepFrequencyHz == 2.0
            && capture->probeSpec(*leftProbe)->initialSweepFrequencyHz
                == 0.25,
        "prepared scope should retain all authored trigger and sweep fields");
    const auto rightProbe = capture->probeIndex(
        "display", "rightOut", capture->probeSpec(*leftProbe)->scopeId,
        talas::runtime::RealtimeAnalysisPayloadKind::AudioBlock);
    require(rightProbe.has_value() && *leftProbe != *rightProbe,
        "right trigger should have its own prepared capture probe");
    require(capture->preferredTriggerProbeIndex(*leftProbe) == rightProbe,
        "Workbench trigger selection should resolve the right channel probe");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready() && session.bindAnalysisStage(80),
        "TrigSwap stereo session should bind its analysis stage");
    for (std::size_t block = 0; block < 4; ++block)
    {
        std::array<double, 4> left{};
        std::array<double, 4> right{};
        std::size_t allocations = 0;
        require(renderStereoAndCount(session, left, right, allocations)
                && allocations == 0,
            "TrigSwap stereo callback should render without allocation");
        for (std::size_t frame = 0; frame < left.size(); ++frame)
        {
            requireNear(left[frame], reference.mono[block * 4 + frame],
                1.0e-12, "prepared left lane should match offline Level output");
            requireNear(right[frame], reference.right[block * 4 + frame],
                1.0e-12, "prepared right lane should match offline Level output");
        }
    }
    std::array<double, talas::runtime::realtimeOscilloscopeHistoryFrames>
        leftTrace{};
    std::array<double, talas::runtime::realtimeOscilloscopeHistoryFrames>
        rightTrace{};
    const auto leftRecord = capture->copyLatestRecord(*leftProbe, leftTrace);
    const auto rightRecord = capture->copyLatestRecord(*rightProbe, rightTrace);
    require(leftRecord.has_value() && rightRecord.has_value()
            && leftRecord->valueCount == 16
            && rightRecord->valueCount == 16
            && leftRecord->stageId == rightRecord->stageId
            && leftRecord->bindingGeneration == rightRecord->bindingGeneration
            && leftRecord->absoluteSamplePosition
                == rightRecord->absoluteSamplePosition,
        "stereo display and trigger should retain aligned raw history");
    for (std::size_t frame = 0; frame < 16; ++frame)
    {
        requireNear(leftTrace[frame], reference.mono[frame] * 4.0,
            1.0e-12, "left display should precede Level");
        requireNear(rightTrace[frame], reference.right[frame] * 4.0,
            1.0e-12, "right trigger should precede Level");
    }
    require(std::abs(leftTrace[2] - rightTrace[2]) > 0.1,
        "TrigSwap should select a genuinely distinct right waveform");
    const auto leftWindow = talas::audio::selectOscilloscopeWindow(
        std::span<const double>{leftTrace.data(), 16},
        8, talas::audio::OscilloscopeTrigger::Rising, 0.5);
    const auto rightWindow = talas::audio::selectOscilloscopeWindow(
        std::span<const double>{leftTrace.data(), 16},
        std::span<const double>{rightTrace.data(), 16},
        8, talas::audio::OscilloscopeTrigger::Rising, 0.5);
    require(leftWindow.triggered && rightWindow.triggered
            && leftWindow.firstFrame != rightWindow.firstFrame,
        "right trigger choice should select a different displayed window");
    const auto fallingWindow = talas::audio::selectOscilloscopeWindow(
        std::span<const double>{leftTrace.data(), 16},
        std::span<const double>{rightTrace.data(), 16},
        8, talas::audio::OscilloscopeTrigger::Falling, 0.5);
    require(fallingWindow.triggered
            && fallingWindow.firstFrame != rightWindow.firstFrame,
        "authored falling edge should choose a different right-channel trigger window");
}

void testRealtimeSessionPublishesSegmentedSpectralAnalysisWithoutAllocations()
{
    const auto segmentedSettings = [](
        talas::runtime::RealtimeAnalysisPayloadKind payloadKind,
        std::string nodeId) {
        talas::runtime::RenderSettings settings{64.0, 17};
        settings.enableRealtimeAnalysisCapture = true;
        settings.realtimeAnalysisQueueCapacity = 1;
        settings.realtimeAnalysisTargets.push_back({
            {},
            {},
            std::move(nodeId),
            "spectrumOut",
            talas::runtime::RealtimeAnalysisKind::Spectrum,
            payloadKind,
            1,
            "trace-spectral",
        });
        settings.eventValues = {
            {"SegmentBoundary", 0.0, talas::expr::ValueDomain::Scalar},
        };
        settings.eventValueChanges = {
            {16, "SegmentBoundary", 1.0, talas::expr::ValueDomain::Scalar},
        };
        return settings;
    };

    {
        auto graph = compile(
            makeLiveSpectralAnalysisAudioInputDocument(
                liveSpectralAnalysisParameters({
                    {"lowestAnalyzedFreq", "4 hz"},
                })),
            segmentedSettings(
                talas::runtime::RealtimeAnalysisPayloadKind::PartialSpectrum,
                "spectrum"));
        const auto capture = graph.analysisCapture();
        require(capture != nullptr && capture->probeCount() == 1,
            "segmented PartialSpectrum fixture should prepare one probe");
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready() && session.bindAnalysisStage(95),
            "segmented PartialSpectrum capture should bind its stage");
        std::array<float, 17> input{};
        for (std::size_t frame = 0; frame < input.size(); ++frame)
        {
            input[frame] = static_cast<float>(std::sin(
                2.0 * std::acos(-1.0) * 8.0
                * static_cast<double>(frame) / 64.0));
        }
        const std::array<const float*, 1> channels{input.data()};
        std::array<double, 17> left{};
        std::array<double, 17> right{};
        std::size_t allocations = 0;
        require(renderStereoInputAndCount(
                    session,
                    {channels.data(), channels.size()},
                    left,
                    right,
                    allocations),
            "segmented PartialSpectrum callback should render");
        require(allocations == 0,
            "segmented PartialSpectrum capture should not allocate");
        std::array<double,
            talas::runtime::maximumRealtimeAnalysisPayloadValues> values{};
        const auto record = capture->copyLatestRecord(0, values);
        require(record.has_value()
                && record->stageId == 95
                && record->payloadKind
                    == talas::runtime::RealtimeAnalysisPayloadKind::PartialSpectrum
                && record->absoluteSamplePosition == 0,
            "frame produced before the final one-frame segment should remain available for callback publication");
        std::array<talas::dsp::PartialSpectrumPoint,
            talas::runtime::maximumRealtimeAnalysisPartialCount> typedPoints{};
        const auto typed = capture->copyLatestPartialSpectrum(
            0, typedPoints);
        require(typed.status
                    == talas::runtime::RealtimeAnalysisCopyStatus::Accepted
                && typed.header.stageId == 95
                && typed.header.absoluteSamplePosition == 0
                && typed.pointCount == record->valueCount / 3,
            "realtime PartialSpectrum publication should retain one typed point record alongside compatibility values");
    }

    {
        auto graph = compile(
            makeNativeStftAudioInputDocument(),
            segmentedSettings(
                talas::runtime::RealtimeAnalysisPayloadKind::ComplexFrame,
                "forward"));
        const auto capture = graph.analysisCapture();
        require(capture != nullptr && capture->probeCount() == 1,
            "segmented ComplexFrame fixture should prepare one probe");
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready() && session.bindAnalysisStage(96),
            "segmented ComplexFrame capture should bind its stage");
        std::array<float, 17> input{};
        for (std::size_t frame = 0; frame < input.size(); ++frame)
        {
            input[frame] = static_cast<float>(std::sin(
                2.0 * std::acos(-1.0) * 4.0
                * static_cast<double>(frame) / 64.0));
        }
        const std::array<const float*, 1> channels{input.data()};
        std::array<double, 17> left{};
        std::array<double, 17> right{};
        std::size_t allocations = 0;
        require(renderStereoInputAndCount(
                    session,
                    {channels.data(), channels.size()},
                    left,
                    right,
                    allocations),
            "segmented ComplexFrame callback should render");
        require(allocations == 0,
            "segmented ComplexFrame capture should not allocate");
        std::array<double,
            talas::runtime::maximumRealtimeAnalysisPayloadValues> values{};
        const auto record = capture->copyLatestRecord(0, values);
        require(record.has_value()
                && record->stageId == 96
                && record->payloadKind
                    == talas::runtime::RealtimeAnalysisPayloadKind::ComplexFrame
                && record->absoluteSamplePosition == 0
                && record->valueCount == 18,
            "ComplexFrame produced before the final one-frame segment should remain available for callback publication");
    }
}

void testRealtimeSessionRendersNamedFeedbackWithoutAllocations()
{
    auto graph = compile(makeRealtimeFeedbackLoopDocument(), {4.0, 4});
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<float, 4> firstInput{1.0F, 0.0F, 0.0F, 0.0F};
    std::array<const float*, 1> firstChannels{firstInput.data()};
    std::array<double, 4> firstOutput{};
    std::size_t allocations = 0;
    bool rendered = false;
    {
        AllocationCounter counter;
        rendered = session.render(
            {firstChannels.data(), firstChannels.size()},
            firstOutput,
            {});
        allocations = counter.count();
    }
    require(rendered, "first prepared feedback callback should render");
    require(allocations == 0, "prepared feedback callback should not allocate");
    const std::array<double, 4> expectedFirst{1.0, 0.5, 0.25, 0.125};
    for (std::size_t frame = 0; frame < expectedFirst.size(); ++frame)
        requireNear(firstOutput[frame], expectedFirst[frame], 1.0e-12, "first prepared feedback frame");

    std::array<float, 4> secondInput{};
    std::array<const float*, 1> secondChannels{secondInput.data()};
    std::array<double, 4> secondOutput{};
    {
        AllocationCounter counter;
        rendered = session.render(
            {secondChannels.data(), secondChannels.size()},
            secondOutput,
            {});
        allocations = counter.count();
    }
    require(rendered, "second prepared feedback callback should render");
    require(allocations == 0, "continued prepared feedback callback should not allocate");
    const std::array<double, 4> expectedSecond{0.0625, 0.03125, 0.015625, 0.0078125};
    for (std::size_t frame = 0; frame < expectedSecond.size(); ++frame)
        requireNear(secondOutput[frame], expectedSecond[frame], 1.0e-12, "continued prepared feedback frame");
}

void testRealtimeFeedbackResetClearsDelayedState()
{
    auto graph = compile(makeRealtimeFeedbackLoopDocument(), {4.0, 4});
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<float, 4> impulse{1.0F, 0.0F, 0.0F, 0.0F};
    std::array<const float*, 1> channels{impulse.data()};
    std::array<double, 4> output{};
    require(session.render({channels.data(), channels.size()}, output, {}), "feedback reset fixture should render its impulse");

    session.resetTransport();
    impulse.fill(0.0F);
    require(session.render({channels.data(), channels.size()}, output, {}), "reset feedback callback should render");
    for (const auto sample : output)
        requireNear(sample, 0.0, 1.0e-12, "transport reset should clear feedback state");
}

void testRealtimeFeedbackFailedFrameDoesNotPublishPartialPairState()
{
    auto graph = compile(
        makeTwoPairFeedbackTransactionDocument(),
        {4.0, 1});
    require(
        graph.plan().feedbackPairs.size() == 2
            && graph.plan().steps[
                    graph.plan().feedbackPairs[0].inputStepIndex]
                    .nodeId
                == "aSink"
            && graph.plan().steps[
                    graph.plan().feedbackPairs[1].inputStepIndex]
                    .nodeId
                == "zSink",
        "transaction fixture should stage the valid feedback input before the failing one");
    require(
        graph.plan().feedbackPairs[0].inputStepIndex
            < static_cast<std::size_t>(
                std::ranges::find_if(
                    graph.plan().steps,
                    [](const talas::runtime::CompileStep& step) {
                        return step.nodeId == "zVca";
                    })
                - graph.plan().steps.begin()),
        "transaction fixture should execute the first commit before the failing VCA");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<float, 1> firstInput{1.0F};
    std::array<float, 1> overflowingInput{
        std::numeric_limits<float>::max()};
    std::array<const float*, 2> invalidChannels{
        firstInput.data(), overflowingInput.data()};
    std::array<double, 1> output{};
    require(
        !session.render(
            {invalidChannels.data(), invalidChannels.size()},
            output,
            {}),
        "overflow in the later VCA should fail the complete feedback frame");

    std::array<float, 1> zeroInput{};
    std::array<const float*, 2> validChannels{
        zeroInput.data(), zeroInput.data()};
    require(
        session.render(
            {validChannels.data(), validChannels.size()},
            output,
            {}),
        "feedback session should recover on the next valid frame");
    requireNear(
        output[0],
        0.0,
        1.0e-12,
        "failed frame must not publish the first pair's staged input");
}

void testRealtimeSessionRejectsUnsupportedNodes()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("feedback", "talas.feedbackLoopOutput", {
        textParameter("connection", ""), {"delay", "0 s"},
    }));
    document.graph.connections.push_back(connection("feedback", "audioOut", "out", "audioIn"));
    auto graph = compile(document);
    talas::runtime::RealtimeRenderSession session(graph);

    require(!session.ready(), "Feedback Loop Output graph should be rejected before realtime rendering");
    require(session.error().find("talas.feedbackLoopOutput") != std::string_view::npos,
            "unsupported node rejection should name the node type");
}

void testRealtimeSessionRejectsMalformedFeedbackPairScope()
{
    auto settings = talas::runtime::RenderSettings{4.0, 1};
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("sink", "talas.feedbackLoopInput", {
            textParameter("connection", "loopA"),
        }),
        node("feedback", "talas.feedbackLoopOutput", {
            textParameter("connection", "loopA"),
            {"delay", "0 s"},
        }),
    };
    document.graph.connections = {
        connection(
            "feedback", "audioOut", "sink", "audioIn"),
        connection(
            "feedback", "audioOut", "out", "audioIn"),
    };
    auto graph = compile(document, settings);
    require(
        graph.plan().feedbackPairs.size() == 1,
        "minimal malformed feedback fixture should compile one pair");
    auto plan = graph.plan();
    plan.feedbackPairs.front().scopeId = 1;
    const talas::runtime::PreparedRuntimeGraph malformed{
        std::move(plan),
        settings};
    const talas::runtime::RealtimeRenderSession session(malformed);
    require(
        !session.ready()
            && session.error().find("feedback pair")
                != std::string_view::npos,
        "realtime preparation should reject a hand-built feedback pair with a mismatched structural scope");
}

void testRealtimeSessionRendersSingleSideBandRmAcrossBlocksWithoutAllocations()
{
    talas::runtime::RenderSettings settings{4.0, 4};
    auto graph = compile(makeSingleSideBandRmDocument(), settings);
    const auto expected = talas::runtime::renderOffline(graph, 8);
    require(expected.ok(), "offline Single Side Band RM reference should render");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 4> first{};
    std::array<double, 4> second{};
    std::size_t allocations = 0;
    require(renderAndCount(session, first, allocations), "first Single Side Band RM block should render");
    require(allocations == 0, "first Single Side Band RM block should not allocate");
    require(renderAndCount(session, second, allocations), "second Single Side Band RM block should render");
    require(allocations == 0, "second Single Side Band RM block should not allocate");
    require(expected.mono.size() == first.size() + second.size(),
            "offline Single Side Band RM reference should provide two blocks");
    for (std::size_t frame = 0; frame < first.size(); ++frame)
        requireNear(first[frame], expected.mono[frame], 1.0e-12, "first Single Side Band RM block should match offline");
    for (std::size_t frame = 0; frame < second.size(); ++frame)
        requireNear(second[frame], expected.mono[first.size() + frame], 1.0e-12,
                "second Single Side Band RM block should retain offline-equivalent state");
}

