void testRealtimeSessionAllowsConnectedSingleSideBandRmControlsWithInvalidFallbacks()
{
    talas::runtime::RenderSettings settings{4.0, 4};
    settings.eventValues.push_back({"SsbFrequency", 1.0, talas::expr::ValueDomain::Scalar});
    settings.eventValues.push_back({"SsbFreqScale", 2.0, talas::expr::ValueDomain::Scalar});
    auto document = makeConnectedSingleSideBandRmDocument();
    for (auto& graphNode : document.graph.nodes)
    {
        if (graphNode.instanceId != "filter")
            continue;
        for (auto& parameter : graphNode.parameters)
        {
            if (parameter.parameterId == "frequency")
                parameter.expression = "1e200 * 1e200";
            else if (parameter.parameterId == "freqScale")
                parameter.expression = "1e200 * 1e200";
        }
    }
    auto graph = compile(document, settings);
    const auto expected = talas::runtime::renderOffline(graph, 4);
    require(expected.ok(), "offline Single Side Band RM should never evaluate connected-control fallback expressions");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 4> output{};
    std::size_t allocations = 0;
    require(renderAndCount(session, output, allocations),
            "connected Single Side Band RM with invalid fallbacks should render");
    require(allocations == 0, "connected Single Side Band RM invalid-fallback render should not allocate");
    require(expected.mono.size() == output.size(), "offline invalid-fallback reference should provide one block");
    for (std::size_t frame = 0; frame < output.size(); ++frame)
        requireNear(output[frame], expected.mono[frame], 1.0e-12,
                "connected Single Side Band RM should ignore invalid fallback values");
}

