    require(renderAndCount(candidate, discarded, allocations)
            && allocations == 0
            && renderAndCount(candidate, discarded, allocations)
            && allocations == 0,
        "C104 reset fixture should first retain non-zero delay history");

    std::size_t resetAllocations = 0;
    {
        AllocationCounter counter;
        candidate.resetTransport();
        resetAllocations = counter.count();
    }
