void testRealtimeReverbSectionRejectsForgedPreparedAuthority()
{
    const auto graph = compile(makeReverbSectionCombDocument());
    talas::runtime::RealtimeRenderSession exactSession(graph);
    require(exactSession.ready(),
        "C141 compiler-sealed Reverb Section authority should prepare");

    auto subsetRegistry = talas::core::makeBuiltinNodeRegistry();
    subsetRegistry.setNodeTypeOfflineSupport(
        "talas.reverbSection",
        talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    subsetRegistry.setNodeTypePreparedRealtimeSupport(
        "talas.reverbSection",
        talas::core::ExecutionSupport::Subset,
        talas::core::ExecutionBinding::LegacyAdapter);
    const auto subsetCompiled = talas::runtime::compileProject(
        makeReverbSectionCombDocument(), subsetRegistry,
        talas::runtime::RenderSettings{4.0, 2});
    require(subsetCompiled.ok(),
        "C141 public-subset compatibility fixture should compile");
    talas::runtime::RealtimeRenderSession subsetSession(
        *subsetCompiled.graph);
    const auto subsetOffline = talas::runtime::renderOffline(
        *subsetCompiled.graph, 2);
    require(subsetSession.ready() && subsetOffline.ok(),
        "C141 explicit public subset authority should retain structural compatibility");

    auto divergentRegistry = talas::core::makeBuiltinNodeRegistry();
    divergentRegistry.setNodeTypeFanInLatencyPolicy(
        "talas.reverbSection",
        talas::core::FanInLatencyPolicy::PreserveRelative);
    const auto divergentCompiled = talas::runtime::compileProject(
        makeReverbSectionCombDocument(), divergentRegistry,
        talas::runtime::RenderSettings{4.0, 2});
    require(divergentCompiled.ok(),
        "C141 divergent-descriptor fixture should compile");
    talas::runtime::RealtimeRenderSession divergentSession(
        *divergentCompiled.graph);
    const auto divergentOffline = talas::runtime::renderOffline(
        *divergentCompiled.graph, 2);
    require(!divergentSession.ready() && !divergentOffline.ok()
            && divergentOffline.mono.empty(),
        "C141 coherent supported descriptor divergence should not mint built-in authority");

    const auto requireRejected = [&](auto mutate,
                                     std::string_view context) {
        auto forged = graph;
        auto& plan = mutablePlanForTest(forged);
        const auto reverb = std::ranges::find(
            plan.steps,
            std::string_view{"reverb"},
            &talas::runtime::CompileStep::nodeId);
        require(reverb != plan.steps.end(),
            "C141 forged-authority fixture should expose Reverb Section");
        mutate(plan, *reverb);
        talas::runtime::RealtimeRenderSession session(forged);
        const auto offline = talas::runtime::renderOffline(forged, 2);
        require(!session.ready() && !offline.ok()
                && offline.mono.empty(),
            std::string{context}
                + " should reject forged C141 Reverb Section authority");
    };
    requireRejected(
        [](auto&, auto& reverb) { reverb.supportsReset = false; },
        "forged reset capability");
    requireRejected(
        [](auto&, auto& reverb) {
            reverb.offlineSupport =
                talas::core::ExecutionSupport::Subset;
        },
        "forged offline support");
    requireRejected(
        [](auto&, auto& reverb) {
            reverb.preparedRealtimeBinding =
                talas::core::ExecutionBinding::Kernel;
            reverb.kernelKind = talas::runtime::KernelKind::Gate;
        },
        "forged prepared binding");
    requireRejected(
        [](auto&, auto& reverb) {
            reverb.resolvedLatencyFrames = 1;
        },
        "forged intrinsic latency");
    requireRejected(
        [](auto&, auto& reverb) {
            reverb.inputLatencyFrames[0] = 1;
        },
        "forged producer input latency");
    requireRejected(
        [](auto&, auto& reverb) {
            reverb.cumulativeInputLatencyFrames = 1;
        },
        "forged cumulative input latency");
    requireRejected(
        [](auto&, auto& reverb) { reverb.structuralScopeId += 1; },
        "forged structural scope");
    requireRejected(
        [](auto&, auto& reverb) {
            std::swap(reverb.parameters[0], reverb.parameters[1]);
        },
        "forged parameter order");
    requireRejected(
        [](auto&, auto& reverb) {
            const auto wavetable = std::ranges::find(
                reverb.parameters,
                std::string_view{"wavetable"},
                &talas::runtime::ParameterValue::id);
            require(wavetable != reverb.parameters.end(),
                "C104 forged resource fixture should expose wavetable");
            wavetable->resource = "External";
        },
        "forged Private resource sentinel");
    requireRejected(
        [](auto& plan, auto& reverb) {
            const auto output = std::ranges::find_if(
                plan.buffers,
                [&](const talas::runtime::BufferSpec& buffer) {
                    return buffer.nodeId == reverb.nodeId
                        && buffer.scopeId == reverb.scopeId
                        && buffer.portId == "audioOut";
                });
            require(output != plan.buffers.end(),
                "C104 forged-authority fixture should expose mono output");
            output->frames -= 1;
        },
        "forged output capacity");

    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.maxRealtimeHistoryFrames = 4;
    settings.eventValues = {
        {"ReverbScale", 1.0, talas::expr::ValueDomain::Scalar},
        {"ReverbDecay", 0.25, talas::expr::ValueDomain::Scalar},
        {"ReverbDelay", 0.25, talas::expr::ValueDomain::Scalar},
        {"ReverbDelayScale", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto connectedGraph = compile(
        makeTemporalReverbSectionDocument(), settings);
    auto reorderedGraph = connectedGraph;
    auto& reorderedPlan = mutablePlanForTest(reorderedGraph);
    const auto connectedReverb = std::ranges::find(
        reorderedPlan.steps,
        std::string_view{"reverb"},
        &talas::runtime::CompileStep::nodeId);
    require(connectedReverb != reorderedPlan.steps.end()
            && connectedReverb->inputs.size() == 5,
        "C104 connected authority fixture should expose five exact inputs");
    std::swap(
        connectedReverb->inputs[0], connectedReverb->inputs[1]);
    std::swap(
        connectedReverb->inputLatencyFrames[0],
        connectedReverb->inputLatencyFrames[1]);
    talas::runtime::RealtimeRenderSession reordered(reorderedGraph);
    require(!reordered.ready(),
        "C104 prepared admission should reject forged Reverb Section input order");
}

void testReverbSectionRejectsForgedConnectedNonFiniteFallbacks()
{
    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.maxRealtimeHistoryFrames = 4;
    settings.eventValues = {
        {"ReverbScale", 0.5, talas::expr::ValueDomain::Scalar},
        {"ReverbDecay", 0.25, talas::expr::ValueDomain::Scalar},
        {"ReverbDelay", 0.25, talas::expr::ValueDomain::Scalar},
        {"ReverbDelayScale", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto candidateGraph = compile(
        makeTemporalReverbSectionDocument(), settings);
    const auto referenceGraph = compile(
        makeTemporalReverbSectionDocument(), std::move(settings));
    auto& candidatePlan = const_cast<talas::runtime::RuntimePlan&>(
        candidateGraph.plan());
    const auto reverb = std::ranges::find(
        candidatePlan.steps,
        std::string_view{"reverb"},
        &talas::runtime::CompileStep::nodeId);
    require(reverb != candidatePlan.steps.end(),
        "C104 hidden-fallback fixture should expose Reverb Section");
    for (const auto parameterId : {
             std::string_view{"scale"},
             std::string_view{"decayTime"},
             std::string_view{"delay"},
             std::string_view{"delayScale"},
         })
    {
        const auto parameter = std::ranges::find(
            reverb->parameters,
            parameterId,
            &talas::runtime::ParameterValue::id);
        require(parameter != reverb->parameters.end(),
            "C104 hidden-fallback fixture should expose "
                + std::string{parameterId});
        parameter->value = std::numeric_limits<double>::infinity();
    }
    const auto offlineCandidate = talas::runtime::renderOffline(
        candidateGraph, 4);
    const auto offlineReference = talas::runtime::renderOffline(
        referenceGraph, 4);
    require(!offlineCandidate.ok() && offlineCandidate.mono.empty()
            && offlineReference.ok(),
        "C141 compiler-owned authority should reject forged connected fallbacks offline");

    talas::runtime::RealtimeRenderSession candidate(candidateGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(!candidate.ready() && reference.ready(),
        "C141 prepared admission should reject forged connected fallbacks before rendering; candidate="
            + std::string{candidate.error()} + "; reference="
            + std::string{reference.error()});
}

