void testRealtimeSessionRendersDistinctBasicFilterModesWithoutAllocations()
{
    auto lowGraph = compile(makeFilterModeDocument("lowPass"), {4.0, 4});
    auto highGraph = compile(makeFilterModeDocument("highPass"), {4.0, 4});
    auto allGraph = compile(makeFilterModeDocument("allPass"), {4.0, 4});
    talas::runtime::RealtimeRenderSession low(lowGraph);
    talas::runtime::RealtimeRenderSession high(highGraph);
    talas::runtime::RealtimeRenderSession all(allGraph);
    require(low.ready() && high.ready() && all.ready(), "all basic Filter modes should prepare");

    std::array<double, 4> lowOutput{};
    std::array<double, 4> highOutput{};
    std::array<double, 4> allOutput{};
    std::size_t allocations = 0;
    require(renderAndCount(low, lowOutput, allocations), "low-pass Filter should render");
    require(allocations == 0, "low-pass Filter should not allocate");
    require(renderAndCount(high, highOutput, allocations), "high-pass Filter should render");
    require(allocations == 0, "high-pass Filter should not allocate");
    require(renderAndCount(all, allOutput, allocations), "all-pass Filter should render");
    require(allocations == 0, "all-pass Filter should not allocate");
    require(std::abs(lowOutput[2] - highOutput[2]) > 1.0e-6, "low-pass and high-pass Filter modes should differ");
    require(std::abs(allOutput[2] - lowOutput[2]) > 1.0e-6, "all-pass and low-pass Filter modes should differ");
}

void testRealtimeSessionUpdatesDirectFilterEventValueParametersWithoutAllocations()
{
    talas::runtime::RenderSettings settings{8.0, 4};
    settings.eventValues = {
        {"Cutoff", 1.0, talas::expr::ValueDomain::Scalar},
        {"Q", 1.0, talas::expr::ValueDomain::Scalar},
        {"Scale", 1.0, talas::expr::ValueDomain::Scalar},
        {"Feedback", 0.0, talas::expr::ValueDomain::Scalar},
    };
    auto directGraph = compile(makeEventValueFilterDocument(false), settings);
    auto referenceGraph = compile(makeEventValueFilterDocument(true), std::move(settings));
    talas::runtime::RealtimeRenderSession direct(directGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(direct.ready(), std::string(direct.error()));
    require(reference.ready(), std::string(reference.error()));

    std::array<double, 4> directFirst{};
    std::array<double, 4> referenceFirst{};
    std::array<double, 4> directSecond{};
    std::array<double, 4> referenceSecond{};
    std::size_t allocations = 0;
    require(renderAndCount(direct, directFirst, allocations), "initial direct Filter Event Value block should render");
    require(allocations == 0, "initial direct Filter Event Value block should not allocate");
    require(renderAndCount(reference, referenceFirst, allocations), "initial connected-reference Filter block should render");
    require(allocations == 0, "initial connected-reference Filter block should not allocate");
    for (std::size_t frame = 0; frame < directFirst.size(); ++frame)
        requireNear(directFirst[frame], referenceFirst[frame], 1.0e-12, "initial direct Filter parameters should match connected reference");

    for (auto* session : {&direct, &reference})
    {
        require(session->updateEventValue("Cutoff", 2.0, talas::expr::ValueDomain::Scalar), "direct Filter cutoff should update");
        require(session->updateEventValue("Q", 0.5, talas::expr::ValueDomain::Scalar), "direct Filter Q should update");
        require(session->updateEventValue("Scale", 0.5, talas::expr::ValueDomain::Scalar), "direct Filter scale should update");
        require(session->updateEventValue("Feedback", 0.25, talas::expr::ValueDomain::Scalar), "direct Filter feedback should update");
    }
    require(renderAndCount(direct, directSecond, allocations), "updated direct Filter Event Value block should render");
    require(allocations == 0, "updated direct Filter Event Value block should not allocate");
    require(renderAndCount(reference, referenceSecond, allocations), "updated connected-reference Filter block should render");
    require(allocations == 0, "updated connected-reference Filter block should not allocate");
    for (std::size_t frame = 0; frame < directSecond.size(); ++frame)
        requireNear(directSecond[frame], referenceSecond[frame], 1.0e-12, "updated direct Filter parameters should match connected reference");
}

