void testRealtimeSessionScaleAndOffsetPreservesFiniteFmaRounding()
{
    constexpr auto input = -1.000000007450580596923828125;
    constexpr auto scale = -0.999999992549419403076171875;
    constexpr auto offset = -1.0;
    const auto expected = std::fma(input, scale, offset);
    require(
        std::bit_cast<std::uint64_t>(expected)
            == std::uint64_t{0xbc90000000000000},
        "C83 FMA oracle should retain negative 2^-54");

    auto graph = compile(makeScaleAndOffsetFmaRoundingDocument());
    const auto offline = talas::runtime::renderOffline(graph, 2);
    talas::runtime::RealtimeRenderSession session(graph);
    require(offline.ok() && offline.mono.size() == 2 && session.ready(),
        "C83 offline and realtime FMA fixtures should prepare");

    std::array<double, 2> output{};
    std::size_t allocations = 0;
    require(renderAndCount(session, output, allocations),
        "C83 realtime FMA fixture should render");
    require(allocations == 0, "C83 FMA fixture should not allocate");
    require(
        std::bit_cast<std::uint64_t>(offline.mono[1])
                == std::bit_cast<std::uint64_t>(expected)
            && std::bit_cast<std::uint64_t>(output[1])
                == std::bit_cast<std::uint64_t>(expected),
        "offline and realtime ScaleAndOffset should publish the frozen FMA result");
}

