void testRealtimeSessionScaleAndOffsetLifecycleAndStaticSnapshotAreExact()
{
    talas::runtime::RenderSettings settings{12.0, 4};
    auto graph = compile(makeScaleAndOffsetControlledVcaDocument(), std::move(settings));
    const auto offline = talas::runtime::renderOffline(graph, 9);
    require(offline.ok() && offline.mono.size() == 9,
        "C83 lifecycle reference should render");
    talas::runtime::RealtimeRenderSession candidate(graph);
    talas::runtime::RealtimeRenderSession replacement(graph);
    talas::runtime::RealtimeRenderSession restaged(graph);
    require(candidate.ready() && replacement.ready() && restaged.ready(),
        "C83 lifecycle fixtures should prepare");

    auto& plan = const_cast<talas::runtime::RuntimePlan&>(graph.plan());
    const auto operation = std::ranges::find(
        plan.steps, std::string_view{"talas.scaleAndOffset"},
        &talas::runtime::CompileStep::typeId);
    require(operation != plan.steps.end(),
        "C83 snapshot fixture should expose ScaleAndOffset");
    const auto scale = std::ranges::find(
        operation->parameters, std::string_view{"scale"},
        &talas::runtime::ParameterValue::id);
    const auto offset = std::ranges::find(
        operation->parameters, std::string_view{"offset"},
        &talas::runtime::ParameterValue::id);
    require(scale != operation->parameters.end() && offset != operation->parameters.end(),
        "C83 snapshot fixture should expose static affine fallbacks");
    scale->value = -2.0;
    offset->value = 1.0;

    std::array<double, 9> partitioned{};
    std::size_t allocations = 0;
    require(
        renderAndCount(candidate, std::span<double>{partitioned}.subspan(0, 2), allocations)
            && allocations == 0
            && renderAndCount(candidate, std::span<double>{partitioned}.subspan(2, 1), allocations)
            && allocations == 0
            && renderAndCount(candidate, std::span<double>{partitioned}.subspan(3, 4), allocations)
            && allocations == 0
            && renderAndCount(candidate, std::span<double>{partitioned}.subspan(7, 2), allocations)
            && allocations == 0,
        "C83 irregular callbacks should render from the owned snapshot without allocations");
    require(std::ranges::equal(partitioned, offline.mono),
        "C83 owned static snapshot and partitions should remain bit-exact offline");

    candidate.resetTransport();
    std::array<double, 4> reset{};
    std::array<double, 4> replaced{};
    std::array<double, 4> restagedOutput{};
    require(
        renderAndCount(candidate, reset, allocations) && allocations == 0
            && renderAndCount(replacement, replaced, allocations) && allocations == 0
            && renderAndCount(restaged, restagedOutput, allocations) && allocations == 0
            && reset == replaced
            && replaced == restagedOutput
            && std::ranges::equal(
                reset, std::span<const double>{offline.mono}.first(4)),
        "C83 stateless reset/replacement/restage should be exact");
}

void testRealtimeSessionScaleAndOffsetPreservesEnclosingFailureIsolation()
{
    auto document = makeScaleAndOffsetControlledVcaDocument();
    for (auto& graphNode : document.graph.nodes)
    {
        if (graphNode.instanceId == "source")
            graphNode.parameters = {{"value", "1"}};
        else if (graphNode.instanceId == "scale")
            graphNode.parameters = {{"scale", "1"}, {"offset", "0"}};
    }
    const auto terminal = std::ranges::find_if(
        document.graph.connections,
        [](const auto& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });
    require(terminal != document.graph.connections.end(),
        "C83 failure fixture should expose its terminal edge");
    terminal->toNode = "firstLevel";
    terminal->toPort = "audioIn";
    document.graph.nodes.push_back(node("gain", "talas.constant", {
        {"value", "!C83Gain"},
    }));
    document.graph.nodes.push_back(node(
        "gainHold", "talas.triggeredSampleAndHold", {{"trigger", "1"}}));
    document.graph.nodes.push_back(node("firstLevel", "talas.level", {
        {"left", "1"}, {"right", "0"},
        booleanParameter("noGain", false),
    }));
    document.graph.nodes.push_back(node("secondLevel", "talas.level", {
        {"left", "2"}, {"right", "0"},
        booleanParameter("noGain", false),
    }));
    document.graph.connections.push_back(connection(
        "gain", "value", "gainHold", "value"));
    document.graph.connections.push_back(connection(
        "gainHold", "value", "firstLevel", "left"));
    document.graph.connections.push_back(connection(
        "firstLevel", "leftOut", "secondLevel", "audioIn"));
    document.graph.connections.push_back(connection(
        "secondLevel", "leftOut", "out", "audioIn"));

    auto candidateSettings = talas::runtime::RenderSettings{4.0, 2};
    candidateSettings.eventValues.push_back({
        "C83Gain", std::numeric_limits<double>::max(),
        talas::expr::ValueDomain::Scalar});
    auto referenceSettings = talas::runtime::RenderSettings{4.0, 2};
    referenceSettings.eventValues.push_back({
        "C83Gain", 1.0, talas::expr::ValueDomain::Scalar});
    const auto candidateGraph = compile(document, candidateSettings);
    const auto referenceGraph = compile(document, referenceSettings);
    talas::runtime::RealtimeRenderSession candidate(candidateGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(candidate.ready() && reference.ready(),
        "C83 downstream failure fixtures should prepare");

    std::array<double, 2> rejected{1.0, 1.0};
    std::size_t allocations = 0;
    require(
        !renderAndCount(candidate, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 2>{},
        "C83 downstream overflow should publish no callback prefix");
    require(candidate.updateEventValue(
        "C83Gain", 1.0, talas::expr::ValueDomain::Scalar),
        "C83 downstream gain should recover after rejection");
    std::array<double, 2> recovered{};
    std::array<double, 2> pristine{};
    require(
        renderAndCount(candidate, recovered, allocations) && allocations == 0
            && renderAndCount(reference, pristine, allocations) && allocations == 0
            && recovered == pristine,
        "C83 should preserve enclosing predecessor rollback and retry identity");
}

