void testRealtimeMixerRequiresExactCompilerOwnedAuthority()
{
    const auto document = makeConnectedMixerDocument();
    const auto compiled = compile(
        document, talas::runtime::RenderSettings{4.0, 4});
    talas::runtime::RealtimeRenderSession publiclyConstructed(
        talas::runtime::PreparedRuntimeGraph{
            compiled.plan(), compiled.renderSettings()});
    require(
        !publiclyConstructed.ready()
            && publiclyConstructed.error()
                == "Realtime renderer requires compiler-owned Mixer execution authority",
        "C129 Mixer should require privately compiler-sealed execution authority");

    const auto requireCustomRegistryRejected = [&] (
        talas::core::NodeRegistry registry,
        std::string_view mutation) {
        const auto forged = talas::runtime::compileProject(
            document,
            registry,
            talas::runtime::RenderSettings{4.0, 4});
        require(forged.ok(),
            "C129 custom-registry fixture should compile "
                + std::string{mutation});
        talas::runtime::RealtimeRenderSession session(*forged.graph);
        require(!session.ready(),
            "C129 Mixer should reject compiler-sealed custom registry "
                + std::string{mutation});
    };
    {
        auto registry = talas::core::makeBuiltinNodeRegistry();
        registry.setNodeTypePreparedRealtimeSupport(
            "talas.mixer",
            talas::core::ExecutionSupport::Subset,
            talas::core::ExecutionBinding::LegacyAdapter);
        requireCustomRegistryRejected(
            std::move(registry), "prepared-support divergence");
    }
    {
        auto registry = talas::core::makeBuiltinNodeRegistry();
        registry.setNodeTypeFanInLatencyPolicy(
            "talas.mixer",
            talas::core::FanInLatencyPolicy::PreserveRelative);
        requireCustomRegistryRejected(
            std::move(registry), "fan-in policy divergence");
    }

    const auto requireRejected = [](auto graph,
                                    std::string_view mutation) {
        talas::runtime::RealtimeRenderSession session(graph);
        require(!session.ready(),
            "C129 Mixer authority should reject "
                + std::string{mutation});
    };
    const auto findMixer = [](auto& graph) -> auto& {
        auto& plan = mutablePlanForTest(graph);
        const auto step = std::ranges::find(
            plan.steps, std::string_view{"talas.mixer"},
            &talas::runtime::CompileStep::typeId);
        require(step != plan.steps.end(),
            "C129 authority fixture should expose Mixer");
        return *step;
    };
    const auto findBinding = [](auto& step,
                                std::string_view port) -> auto& {
        const auto binding = std::ranges::find(
            step.inputs, port,
            &talas::runtime::InputBinding::inputPortId);
        require(binding != step.inputs.end(),
            "C129 authority fixture should expose "
                + std::string{port} + " binding");
        return *binding;
    };

    auto forgedSupport = compiled;
    findMixer(forgedSupport).preparedRealtimeSupport =
        talas::core::ExecutionSupport::Subset;
    requireRejected(std::move(forgedSupport),
        "prepared-support mutation");

    auto forgedParameter = compiled;
    findMixer(forgedParameter).parameters[1].id = "forgedGain2";
    requireRejected(std::move(forgedParameter),
        "parameter-identity mutation");

    auto forgedParameterOrder = compiled;
    std::swap(
        findMixer(forgedParameterOrder).parameters[0],
        findMixer(forgedParameterOrder).parameters[1]);
    requireRejected(std::move(forgedParameterOrder),
        "parameter-order mutation");

    auto forgedInputOrder = compiled;
    std::swap(
        findMixer(forgedInputOrder).inputs[0],
        findMixer(forgedInputOrder).inputs[1]);
    requireRejected(std::move(forgedInputOrder),
        "ordered-audio-input mutation");

    auto forgedProducer = compiled;
    findBinding(findMixer(forgedProducer), "in2").sourceNodeId
        += "Forged";
    requireRejected(std::move(forgedProducer),
        "producer-identity mutation");

    auto forgedProducerScope = compiled;
    ++findBinding(findMixer(forgedProducerScope), "in2")
          .sourceScopeId;
    requireRejected(std::move(forgedProducerScope),
        "producer-scope mutation");

    auto forgedGainBinding = compiled;
    findBinding(findMixer(forgedGainBinding), "gain1")
        .inputPortId = "gain2";
    requireRejected(std::move(forgedGainBinding),
        "duplicate-gain-binding mutation");

    auto forgedScope = compiled;
    ++findMixer(forgedScope).scopeId;
    requireRejected(std::move(forgedScope),
        "execution-scope mutation");

    auto forgedEventScope = compiled;
    ++findMixer(forgedEventScope).eventValueScopeId;
    requireRejected(std::move(forgedEventScope),
        "Event Value scope mutation");

    auto forgedAncestry = compiled;
    findMixer(forgedAncestry).structuralSourcePath += "/forged";
    requireRejected(std::move(forgedAncestry),
        "structural-ancestry mutation");

    auto forgedLatency = compiled;
    findMixer(forgedLatency).cumulativeOutputLatencyFrames = 1;
    requireRejected(std::move(forgedLatency),
        "aligned-output-latency mutation");

    auto forgedInputLatency = compiled;
    findMixer(forgedInputLatency).inputLatencyFrames[0] = 1;
    requireRejected(std::move(forgedInputLatency),
        "input-latency mutation");

    auto forgedInputCapacity = compiled;
    auto& inputCapacityPlan = mutablePlanForTest(forgedInputCapacity);
    const auto in1Index = findBinding(
        findMixer(forgedInputCapacity), "in1").bufferIndex;
    ++inputCapacityPlan.buffers[in1Index].frames;
    requireRejected(std::move(forgedInputCapacity),
        "input-capacity mutation");

    auto forgedGainBufferType = compiled;
    auto& gainTypePlan = mutablePlanForTest(forgedGainBufferType);
    const auto gain1Index = findBinding(
        findMixer(forgedGainBufferType), "gain1").bufferIndex;
    gainTypePlan.buffers[gain1Index].type = talas::core::PortType::Audio;
    requireRejected(std::move(forgedGainBufferType),
        "gain-buffer-type mutation");

    auto forgedOutput = compiled;
    auto& outputPlan = mutablePlanForTest(forgedOutput);
    const auto output = std::ranges::find_if(
        outputPlan.buffers,
        [](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == "mixer"
                && buffer.portId == "audioOut";
        });
    require(output != outputPlan.buffers.end(),
        "C129 authority fixture should expose the output buffer");
    ++output->frames;
    requireRejected(std::move(forgedOutput),
        "output-buffer mutation");

    auto forgedOutputPort = compiled;
    auto& outputPortPlan = mutablePlanForTest(forgedOutputPort);
    const auto outputPort = std::ranges::find_if(
        outputPortPlan.buffers,
        [](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == "mixer"
                && buffer.portId == "audioOut";
        });
    require(outputPort != outputPortPlan.buffers.end(),
        "C129 output-port fixture should expose Mixer audioOut");
    outputPort->portId = "leftOut";
    requireRejected(std::move(forgedOutputPort),
        "output-port alias mutation");

    auto forgedSampleRate = compiled;
    mutableSettingsForTest(forgedSampleRate).sampleRate = 8.0;
    requireRejected(std::move(forgedSampleRate),
        "sample-rate settings mutation");

    auto forgedMaximumFrames = compiled;
    ++mutableSettingsForTest(forgedMaximumFrames).maxBlockFrames;
    requireRejected(std::move(forgedMaximumFrames),
        "maximum-block settings mutation");

    auto forgedResource = compiled;
    mutableSettingsForTest(forgedResource).tableResources.push_back(
        {"Tables/C129Unrelated", {9.0}});
    requireRejected(std::move(forgedResource),
        "unrelated-resource mutation");

    const auto requireAuthenticGainCombination = [](auto document,
                                                     std::string_view label) {
        talas::runtime::RealtimeRenderSession session(
            compile(document, talas::runtime::RenderSettings{4.0, 4}));
        std::array<double, 4> output{};
        std::size_t allocations = 0;
        require(session.ready()
                && renderAndCount(session, output, allocations)
                && allocations == 0,
            "C129 authentic " + std::string{label}
                + " Mixer gain combination should prepare and render");
    };
    requireAuthenticGainCombination(
        makeMixerDocument(), "static/static");
    {
        auto oneConnected = makeMixerDocument();
        oneConnected.graph.nodes.push_back(
            node("sharedGain", "talas.constant", {{"value", "0.5"}}));
        oneConnected.graph.connections.push_back(connection(
            "sharedGain", "value", "mixer", "gain1"));
        requireAuthenticGainCombination(
            oneConnected, "connected/static");
        oneConnected.graph.connections.back().toPort = "gain2";
        requireAuthenticGainCombination(
            oneConnected, "static/connected");
        oneConnected.graph.connections.push_back(connection(
            "sharedGain", "value", "mixer", "gain1"));
        requireAuthenticGainCombination(
            std::move(oneConnected), "same-producer connected/connected");
    }
}

