void testRealtimeSessionUpdatesDirectMixerEventValueGainsWithoutAllocations()
{
    talas::runtime::RenderSettings settings{4.0, 4};
    settings.eventValues = {
        {"LeftGain", 0.5, talas::expr::ValueDomain::Scalar},
        {"RightGain", 0.25, talas::expr::ValueDomain::Scalar},
    };
    auto directGraph = compile(makeEventValueMixerDocument(false), settings);
    auto referenceGraph = compile(makeEventValueMixerDocument(true), std::move(settings));
    talas::runtime::RealtimeRenderSession direct(directGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(direct.ready(), std::string(direct.error()));
    require(reference.ready(), std::string(reference.error()));

    std::array<double, 4> directFirst{};
    std::array<double, 4> referenceFirst{};
    std::array<double, 4> directSecond{};
    std::array<double, 4> referenceSecond{};
    std::size_t allocations = 0;
    require(renderAndCount(direct, directFirst, allocations), "initial direct Mixer Event Value block should render");
    require(allocations == 0, "initial direct Mixer Event Value block should not allocate");
    require(renderAndCount(reference, referenceFirst, allocations), "initial connected-reference Mixer block should render");
    require(allocations == 0, "initial connected-reference Mixer block should not allocate");
    for (std::size_t frame = 0; frame < directFirst.size(); ++frame)
        requireNear(directFirst[frame], referenceFirst[frame], 1.0e-12, "initial direct Mixer gains should match connected reference");

    for (auto* session : {&direct, &reference})
    {
        require(session->updateEventValue("LeftGain", -0.25, talas::expr::ValueDomain::Scalar),
                "direct Mixer left gain should update");
        require(session->updateEventValue("RightGain", 0.5, talas::expr::ValueDomain::Scalar),
                "direct Mixer right gain should update");
    }
    require(renderAndCount(direct, directSecond, allocations), "updated direct Mixer Event Value block should render");
    require(allocations == 0, "updated direct Mixer Event Value block should not allocate");
    require(renderAndCount(reference, referenceSecond, allocations), "updated connected-reference Mixer block should render");
    require(allocations == 0, "updated connected-reference Mixer block should not allocate");
    for (std::size_t frame = 0; frame < directSecond.size(); ++frame)
        requireNear(directSecond[frame], referenceSecond[frame], 1.0e-12, "updated direct Mixer gains should match connected reference");
}

