    require(renderAndCount(session, heldReset, allocations),
        "held oscillator reset block should render");
    require(allocations == 0, "held oscillator reset should not allocate");
    require(renderAndCount(session, releasedReset, allocations),
        "released oscillator reset block should render");
    require(allocations == 0, "released oscillator reset should not allocate");
    require(renderAndCount(session, retriggeredReset, allocations),
        "retriggered oscillator reset block should render");
    require(allocations == 0, "retriggered oscillator reset should not allocate");
