        std::array<double, 4> rejected;
        rejected.fill(95.0);
        require(!renderAndCount(candidate, rejected, allocations)
                && allocations == 0
                && rejected == std::array<double, 4>{},
            "C95 failed Samples From Disk Single Step start should publish no output");
        require(candidate.updateEventValue(
                    "StepGate", 0.0, talas::expr::ValueDomain::Scalar)
                && candidate.updateEventValue(
                    "C95CheckpointDownstream", 1.0,
                    talas::expr::ValueDomain::Scalar),
            "C95 failed Samples From Disk Single Step start should repair for retry");
        std::array<double, 4> retry{};
        std::array<double, 4> expected{};
        require(renderAndCount(candidate, retry, allocations)
                && renderAndCount(reference, expected, allocations)
                && allocations == 0 && retry == expected,
            "C95 Samples From Disk Single Step should restore its unstarted state before closed retry");
