void testRealtimeOscillatorAcceptsCheckpointedLowPassGateNeighbor()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("osc", "talas.oscillator", {
            {"frequency", "1 hz"}, {"amplitude", "1"},
        }),
        node("lowPassGate", "talas.lowPassGate", lowPassGateParameters()),
    };
    document.graph.connections = {
        connection("osc", "audioOut", "lowPassGate", "audioIn"),
        connection("lowPassGate", "audioOut", "out", "audioIn"),
    };
    talas::runtime::RealtimeRenderSession session(compile(
        document, talas::runtime::RenderSettings{48'000.0, 16}));
    require(session.ready(),
        "C95 should admit its bounded Low-Pass Gate checkpoint neighbor: "
            + std::string{session.error()});
    std::array<double, 16> output{};
    std::size_t allocations = 0;
    require(renderAndCount(session, output, allocations)
            && allocations == 0,
        "C95 Low-Pass Gate coexistence should render without allocation");
}

void testRealtimeSessionRejectsNonFiniteConnectedSourceControlsWithoutAllocations()
{
    auto graph = compile(makeNonFiniteOscillatorFrequencyControlDocument());
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 2> output{};
    std::size_t allocations = 0;
    require(!renderAndCount(session, output, allocations), "non-finite connected source controls should fail the realtime block");
    require(allocations == 0, "non-finite connected source control rejection should not allocate");
}

