void testRealtimeSessionRejectsAllInvalidConnectedSourceControlValuesWithoutAllocations()
{
    // A negative frequency reads the Oscillator's
    // wavetable backwards, so it renders.
    {
        auto graph = compile(makeNegativeOscillatorFrequencyControlDocument());
        talas::runtime::RealtimeRenderSession session(graph);
        std::array<double, 2> output{};
        std::size_t allocations = 0;
        require(session.ready() && renderAndCount(session, output, allocations) && allocations == 0,
            "a negative connected oscillator frequency should render without allocating");
    }
    requireRealtimeBlockRejection(
        makeNonFiniteOscillatorAmplitudeControlDocument(),
        "non-finite connected oscillator amplitude should fail the realtime block");
    requireRealtimeBlockRejection(
        makeNegativeNoiseFrequencyControlDocument(),
        "negative connected Noise frequency should fail the realtime block");
    requireRealtimeBlockRejection(
        makeNonFiniteNoiseCenterControlDocument(),
        "non-finite connected Noise centerValue should fail the realtime block");
    requireRealtimeBlockRejection(
        makeNegativeNoiseScaleControlDocument(),
        "negative connected Noise scale should fail the realtime block");
}

