void testRealtimeOscillatorConnectedControlsIgnoreForgedFallbackValues()
{
    const auto referenceGraph = compile(
        makeC95ConnectedControlOscillatorDocument(), {4.0, 4});
    auto candidateGraph = compile(
        makeC95ConnectedControlOscillatorDocument(), {4.0, 4});
    auto& plan = const_cast<talas::runtime::RuntimePlan&>(candidateGraph.plan());
    const auto oscillator = std::ranges::find(
        plan.steps, std::string_view{"talas.oscillator"},
        &talas::runtime::CompileStep::typeId);
    require(oscillator != plan.steps.end(),
        "C95 hidden-fallback fixture should expose Oscillator");
    for (const auto parameterId : {
             std::string_view{"frequency"},
             std::string_view{"amplitude"},
             std::string_view{"envelope"},
             std::string_view{"pitchBend"},
             std::string_view{"reset"},
         })
    {
        const auto parameter = std::ranges::find(
            oscillator->parameters, parameterId,
            &talas::runtime::ParameterValue::id);
        require(parameter != oscillator->parameters.end(),
            "C95 hidden-fallback fixture should expose "
                + std::string{parameterId});
        parameter->value = std::numeric_limits<double>::infinity();
    }
    talas::runtime::RealtimeRenderSession candidate(candidateGraph);
    talas::runtime::RealtimeRenderSession reference(referenceGraph);
    require(candidate.ready() && reference.ready(),
        "C95 connected controls should own invalid hidden fallbacks");
    std::array<double, 4> actual{};
    std::array<double, 4> expected{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, actual, allocations)
            && renderAndCount(reference, expected, allocations)
            && allocations == 0 && actual == expected,
        "C95 prepared controls should never evaluate connected fallbacks");
}

void testRealtimeOscillatorOwnOutputFailurePreservesPhaseBeforeRetry()
{
    const auto makeDocument = [] {
        return makeC95OscillatorDocument({
            {"frequency", "1 hz"},
            {"amplitude", "!C95Amplitude"},
            {"envelope", "2"},
            textParameter("modulation", ""),
            {"maxMI", "0"},
            {"pitchBend", "0"},
            {"reset", "0"},
            resourceParameter("wavetable", ""),
            choiceParameter("interpolation", "linear"),
        });
    };
    talas::runtime::RenderSettings settings{4.0, 3};
    settings.eventValues = {
        {"C95Amplitude", 0.5, talas::expr::ValueDomain::Scalar},
    };
    talas::runtime::RealtimeRenderSession candidate(
        compile(makeDocument(), settings));
    talas::runtime::RealtimeRenderSession reference(
        compile(makeDocument(), settings));
    require(candidate.ready() && reference.ready(),
        "C95 own-output rollback fixtures should prepare");
    std::array<double, 1> candidateWarm{};
    std::array<double, 1> referenceWarm{};
    std::size_t allocations = 0;
    require(renderAndCount(candidate, candidateWarm, allocations)
            && renderAndCount(reference, referenceWarm, allocations)
            && allocations == 0 && candidateWarm == referenceWarm,
        "C95 own-output rollback fixtures should establish matching phase");
    require(candidate.updateEventValue(
                "C95Amplitude", std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar),
        "C95 own-output rollback fixture should arm finite overflow");
    std::array<double, 3> rejected;
    rejected.fill(95.0);
    require(!renderAndCount(candidate, rejected, allocations)
            && allocations == 0
            && rejected == std::array<double, 3>{},
        "C95 Oscillator output overflow should publish no callback prefix");
    require(candidate.updateEventValue(
                "C95Amplitude", 0.5,
                talas::expr::ValueDomain::Scalar),
        "C95 own-output rollback fixture should repair its amplitude");
    std::array<double, 3> retry{};
    std::array<double, 3> expected{};
    require(renderAndCount(candidate, retry, allocations)
            && renderAndCount(reference, expected, allocations)
            && allocations == 0 && retry == expected,
        "C95 own-output rejection should preserve phase before exact retry");
}

