void testRealtimeSessionRendersBorrowedAudioInputWithoutAllocations()
{
    auto graph = compile(makeRealtimeAudioInputDocument(true, true), {4.0, 4});
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<float, 4> channel1{1.0F, 2.0F, 3.0F, 4.0F};
    std::array<float, 4> channel2{0.5F, 1.0F, 1.5F, 2.0F};
    std::array<const float*, 2> channels{channel1.data(), channel2.data()};
    const talas::runtime::RealtimeAudioInputBlock input{channels.data(), channels.size()};
    std::array<double, 4> left{};
    std::array<double, 4> right{};

    allocationCount.store(0, std::memory_order_relaxed);
    countAllocations.store(true, std::memory_order_relaxed);
    const auto rendered = session.render(input, left, right);
    countAllocations.store(false, std::memory_order_relaxed);
    require(rendered, "borrowed two-channel AudioInput block should render");
    require(allocationCount.load(std::memory_order_relaxed) == 0, "borrowed AudioInput callback should not allocate");
    for (std::size_t frame = 0; frame < left.size(); ++frame)
    {
        const auto expected = static_cast<double>(channel1[frame] + channel2[frame]);
        requireNear(left[frame], expected, 1.0e-12, "selected AudioInput channels should sum without normalization");
        requireNear(right[frame], expected, 1.0e-12, "AudioInput rightOut should duplicate the mono sum");
    }

    std::array<float, 4> replacement{8.0F, 7.0F, 6.0F, 5.0F};
    channels = {replacement.data(), channel2.data()};
    require(session.render({channels.data(), channels.size()}, left, right),
            "a later AudioInput callback should borrow the new block");
    requireNear(left[0], 8.5, 1.0e-12, "live AudioInput should not keep an offline read cursor");
}

void testRealtimeSessionRendersTrueStereoAudioInputWithoutAllocations()
{
    talas::runtime::RenderSettings settings{4.0, 4};
    settings.audioInputChannels = {
        {1, {1.0, 2.0, 3.0, 4.0}},
        {2, {10.0, 20.0, 30.0, 40.0}},
    };
    auto graph = compile(
        makeRealtimeAudioInputDocument(
            true, true, "1", "stereoPair"),
        settings);
    const auto expected = talas::runtime::renderOffline(graph, 4);
    require(expected.ok(), "offline stereoPair AudioInput should render");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<float, 4> channel1{1.0F, 2.0F, 3.0F, 4.0F};
    std::array<float, 4> channel2{10.0F, 20.0F, 30.0F, 40.0F};
    std::array<const float*, 2> channels{channel1.data(), channel2.data()};
    std::array<double, 4> left{};
    std::array<double, 4> right{};
    std::size_t allocations = 0;
    require(
        renderStereoInputAndCount(
            session,
            {channels.data(), channels.size()},
            left,
            right,
            allocations),
        "borrowed stereoPair AudioInput block should render");
    require(allocations == 0, "stereoPair AudioInput callback should not allocate");
    for (std::size_t frame = 0; frame < left.size(); ++frame)
    {
        requireNear(left[frame], channel1[frame], 1.0e-12,
                    "stereoPair should retain the lower selected channel on the left");
        requireNear(right[frame], channel2[frame], 1.0e-12,
                    "stereoPair should retain the higher selected channel on the right");
        requireNear(left[frame], expected.mono[frame], 1.0e-12,
                    "prepared stereoPair left should match offline");
        requireNear(right[frame], expected.right[frame], 1.0e-12,
                    "prepared stereoPair right should match offline");
    }
}

