void testRealtimeSessionSupportsIndependentAudioInputMasks()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("mixer", "talas.mixer", {{"gain1", "1"}, {"gain2", "1"}}),
        node("leftInput", "talas.audioInput", {booleanParameter("channel1", true), booleanParameter("channel2", false)}),
        node("rightInput", "talas.audioInput", {booleanParameter("channel1", false), booleanParameter("channel2", true)}),
    };
    document.graph.connections = {
        connection("leftInput", "audioOut", "mixer", "in1"),
        connection("rightInput", "audioOut", "mixer", "in2"),
        connection("mixer", "audioOut", "out", "audioIn"),
    };
    auto graph = compile(document);
    talas::runtime::RealtimeRenderSession session(graph);

    std::array<float, 2> channel1{1.0F, 2.0F};
    std::array<float, 2> channel2{10.0F, 20.0F};
    std::array<const float*, 2> channels{channel1.data(), channel2.data()};
    std::array<double, 2> output{};
    require(session.render({channels.data(), channels.size()}, output, {}),
            "independently masked AudioInput nodes should render");
    requireNear(output[0], 11.0, 1.0e-12, "independent AudioInput masks frame zero");
    requireNear(output[1], 22.0, 1.0e-12, "independent AudioInput masks frame one");
}

void testRealtimeSessionRejectsInvalidAudioInputBeforeSchedulerStateChanges()
{
    talas::runtime::RenderSettings settings{4.0, 4};
    settings.eventValues.push_back({"Gain", 1.0, talas::expr::ValueDomain::Scalar});
    auto graph = compile(makeRealtimeAudioInputDocument(true, false, "!Gain"), std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.scheduleEventValue("Gain", 0.5, talas::expr::ValueDomain::Scalar, 0),
            "invalid-input fixture should schedule a gain change");

    std::array<double, 4> left{};
    std::array<double, 4> right{};
    require(!session.render({}, left, right), "missing selected AudioInput channel should reject the callback");

    std::array<const float*, 1> nullChannel{nullptr};
    require(!session.render({nullChannel.data(), nullChannel.size()}, left, right),
            "null selected AudioInput channel should reject the callback");

    std::array<float, 4> nonFinite{1.0F, 2.0F, std::numeric_limits<float>::infinity(), 4.0F};
    std::array<const float*, 1> channels{nonFinite.data()};
    require(!session.render({channels.data(), channels.size()}, left, right),
            "non-finite selected AudioInput sample should reject the callback");

    std::array<float, 4> valid{1.0F, 2.0F, 3.0F, 4.0F};
    channels[0] = valid.data();
    require(session.render({channels.data(), channels.size()}, left, right),
            "valid AudioInput should render after rejected callbacks");
    requireNear(left[0], 0.5, 1.0e-12, "invalid input must not consume the scheduled gain change");
}

