void testRealtimeSessionRendersScheduledEventValueChangesAtExactFrames()
{
    talas::runtime::RenderSettings settings{4.0, 4};
    settings.eventValues.push_back({"Gain", 1.0, talas::expr::ValueDomain::Scalar});
    settings.eventValues.push_back({"Bias", 0.0, talas::expr::ValueDomain::Scalar});
    settings.eventValueChanges = {
        {0, "Gain", 0.25, talas::expr::ValueDomain::Scalar},
        {1, "Gain", 0.5, talas::expr::ValueDomain::Scalar},
        {1, "Bias", 0.25, talas::expr::ValueDomain::Scalar},
        {4, "Gain", 0.125, talas::expr::ValueDomain::Scalar},
    };
    auto graph = compile(makeConstantNoiseVcaDocument("!Gain + !Bias"), std::move(settings));
    const auto expected = talas::runtime::renderOffline(graph, 8);
    require(expected.ok(), "scheduled Event Value offline reference should render");
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));

    std::array<double, 4> first{};
    std::array<double, 4> second{};
    std::size_t allocations = 0;
    require(renderAndCount(session, first, allocations), "first scheduled Event Value block should render");
    require(allocations == 0, "first scheduled Event Value block should not allocate");
    require(renderAndCount(session, second, allocations), "second scheduled Event Value block should render");
    require(allocations == 0, "second scheduled Event Value block should not allocate");
    for (std::size_t frame = 0; frame < first.size(); ++frame)
    {
        requireNear(first[frame], expected.mono[frame], 1.0e-12, "first scheduled Event Value frame");
        requireNear(second[frame], expected.mono[frame + first.size()], 1.0e-12, "second scheduled Event Value frame");
    }
    requireNear(first[0], 0.25, 1.0e-12, "frame-zero scheduled Event Value should apply before the first sample");
    requireNear(first[1], 0.75, 1.0e-12, "equal-frame scheduled Event Values should apply in stable order");
    requireNear(first[3], 0.75, 1.0e-12, "scheduled value should remain active through the first block");
    requireNear(second[0], 0.375, 1.0e-12, "block-end Event Value should apply at the next callback start");
}

void testRealtimeSessionRepeatsOnlyLoopTimelineEventsAndReconstructsLateState()
{
    talas::runtime::RenderSettings settings{4.0, 4};
    settings.transportLoop = talas::runtime::TransportLoopRegion{2, 6};
    settings.eventValues.push_back(
        {"Gain", 0.0, talas::expr::ValueDomain::Scalar});
    settings.eventValueChanges = {
        {1, "Gain", 0.1, talas::expr::ValueDomain::Scalar},
        {2, "Gain", 0.2, talas::expr::ValueDomain::Scalar},
        {4, "Gain", 0.4, talas::expr::ValueDomain::Scalar},
        {6, "Gain", 0.6, talas::expr::ValueDomain::Scalar},
        {7, "Gain", 0.7, talas::expr::ValueDomain::Scalar},
    };
    auto graph = compile(
        makeConstantNoiseVcaDocument("!Gain"),
        std::move(settings));
    talas::runtime::RealtimeRenderSession session(graph);
    require(session.ready(), std::string(session.error()));
    require(
        session.scheduleEventValue(
            "Gain",
            0.9,
            talas::expr::ValueDomain::Scalar,
            3),
        "independent live change inside the first loop iteration should schedule");

    std::array<double, 4> first{};
    std::array<double, 4> second{};
    std::array<double, 2> third{};
    std::size_t allocations = 0;
    require(renderAndCount(session, first, allocations),
            "first loop Timeline block should render");
    require(allocations == 0, "first loop Timeline block must not allocate");
    require(renderAndCount(session, second, allocations),
            "wrapping loop Timeline block should render");
    require(allocations == 0, "wrapping loop Timeline block must not allocate");
    require(renderAndCount(session, third, allocations),
            "second loop Timeline iteration should render");
    require(allocations == 0, "second loop Timeline iteration must not allocate");

    const std::array<double, 10> expected{
        0.0, 0.1, 0.2, 0.9, 0.4, 0.4, 0.2, 0.2, 0.4, 0.4,
    };
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
    {
        const auto actual = frame < first.size()
            ? first[frame]
            : frame < first.size() + second.size()
                ? second[frame - first.size()]
                : third[frame - first.size() - second.size()];
        requireNear(
            actual,
            expected[frame],
            1.0e-12,
            "loop Timeline frame " + std::to_string(frame));
    }

    talas::runtime::RealtimeRenderSession replacement(graph);
    replacement.setTransportFrameBeforeFirstRender(9);
    std::array<double, 1> replacementOutput{};
    require(renderAndCount(replacement, replacementOutput, allocations),
            "late replacement should reconstruct loop state directly");
    require(allocations == 0, "late loop reconstruction must not allocate");
    requireNear(
        replacementOutput[0],
        0.4,
        1.0e-12,
        "late replacement should reconstruct the current loop iteration");

    replacement.resetTransport();
    require(renderAndCount(replacement, replacementOutput, allocations),
            "reset replacement should render from frame zero");
    requireNear(
        replacementOutput[0],
        0.0,
        1.0e-12,
        "transport reset should restore the pre-Timeline initial value");
}

