void testRealtimeSessionPreservesStateAcrossScheduledExpressionSegments()
{
    {
        talas::runtime::RenderSettings settings{8.0, 4};
        settings.eventValues.push_back({"Control", 0.25, talas::expr::ValueDomain::Scalar});
        settings.eventValueChanges = {
            {1, "Control", 0.5, talas::expr::ValueDomain::Scalar},
            {3, "Control", 0.125, talas::expr::ValueDomain::Scalar},
        };
        auto graph = compile(makeScheduledConnectedEventValueOscillatorDocument(), std::move(settings));
        const auto expected = talas::runtime::renderOffline(graph, 8);
        require(expected.ok(), "scheduled oscillator offline reference should render");
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(), std::string(session.error()));

        std::array<double, 4> block{};
        std::size_t allocations = 0;
        for (std::size_t blockIndex = 0; blockIndex < 2; ++blockIndex)
        {
            require(renderAndCount(session, block, allocations), "scheduled oscillator realtime block should render");
            require(allocations == 0, "scheduled oscillator realtime block should not allocate");
            for (std::size_t frame = 0; frame < block.size(); ++frame)
            {
                const auto absoluteFrame = blockIndex * block.size() + frame;
                requireNear(block[frame], expected.mono[absoluteFrame], 1.0e-12,
                            "scheduled oscillator phase at frame " + std::to_string(absoluteFrame)
                                + ": actual=" + std::to_string(block[frame])
                                + " expected=" + std::to_string(expected.mono[absoluteFrame]));
            }
        }
    }

    {
        talas::runtime::RenderSettings settings{4.0, 4};
        settings.eventValues = {
            {"RampTrigger", 0.0, talas::expr::ValueDomain::Scalar},
            {"RampDuration", 1.0, talas::expr::ValueDomain::Scalar},
        };
        settings.eventValueChanges = {
            {1, "RampTrigger", 1.0, talas::expr::ValueDomain::Scalar},
            {2, "RampDuration", 0.5, talas::expr::ValueDomain::Scalar},
            {5, "RampTrigger", 0.0, talas::expr::ValueDomain::Scalar},
            {6, "RampTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        };
        auto graph = compile(makeDirectEventValueTalasRampVcaDocument(true), std::move(settings));
        const auto expected = talas::runtime::renderOffline(graph, 8);
        require(expected.ok(), "scheduled Ramp offline reference should render");
        talas::runtime::RealtimeRenderSession session(graph);
        require(session.ready(), std::string(session.error()));

        std::array<double, 4> block{};
        std::size_t allocations = 0;
        for (std::size_t blockIndex = 0; blockIndex < 2; ++blockIndex)
        {
            require(renderAndCount(session, block, allocations), "scheduled Ramp realtime block should render");
            require(allocations == 0, "scheduled Ramp realtime block should not allocate");
            for (std::size_t frame = 0; frame < block.size(); ++frame)
                requireNear(block[frame], expected.mono[blockIndex * block.size() + frame], 1.0e-12,
                            "scheduled Ramp should preserve edges and captured duration");
        }
    }
}

